ad: {\n      milestoneType\n    }\n  };\n}\n\nexport function updateMilestoneTypeItemAction(milestoneType: IMilestoneType): IUpdateMilestoneType {\n  return {\n    type: MILESTONE_TYPE_UDPATE_STATUS,\n    payload: {\n      milestoneType\n    }\n  };\n}\n\n\nexport function deleteMilestoneTypeAction(milestoneType: IMilestoneType): IDeleteMilestoneType {\n  return {\n    type: MILESTONE_TYPE_DELETE_STATUS,\n    payload: {\n      milestoneType\n    }\n  };\n}\n\nexport function changeOrderMilestoneTypeAction(orderBy: string, orderType: string): IChangeOrderMilestoneType {\n  return {\n    type: MILESTONE_TYPE_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getMilestoneTypesThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>, getState: () => { milestoneType: IMilestoneTypeState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingMilestoneTypeAction(!hideLoading));\n    const page = nextPage ? nextPage : state.milestoneType.pagination.page;\n    dispatch(changeOrderMilestoneTypeAction(orderBy, orderType));\n    dispatch(cancelMilestoneTypeAction(api.getSource()));\n    Axios\n      .all([\n        api.getMilestoneTypes({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((milestoneTypes) => {\n        const { data } = milestoneTypes;\n        dispatch(loadMilestoneTypeAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingMilestoneTypeAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingMilestoneTypeAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createMilestoneTypeThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n\nexport function updateMilestoneTypeThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n\nexport function deleteMilestoneTypeItemThunkAction(milestoneType: IMilestoneType) {\n  return (dispatch: Dispatch<MilestoneTypeReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteMilestoneType(milestoneType)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneTypeItemAction(idMilestoneType, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport const MILESTONE_TYPE_CANCEL_STATUS = '/MILESTONE_TYPE/CANCEL_STATUS';\nexport const MILESTONE_TYPE_IS_LOADING = '/MILESTONE_TYPE/IS_LOADING';\nexport const MILESTONE_TYPE_LOAD_STATUS = '/MILESTONE_TYPE/LOAD_STATUS';\nexport const MILESTONE_TYPE_CREATE_STATUS = '/MILESTONE_TYPE/CREATE_STATUS';\nexport const MILESTONE_TYPE_UDPATE_STATUS = '/MILESTONE_TYPE/UDPATE_STATUS';\nexport const MILESTONE_TYPE_DELETE_STATUS = '/MILESTONE_TYPE/DELETE_STATUS';\nexport const MILESTONE_TYPE_CHANGE_ORDER = '/MILESTONE_TYPE/CHANGE_ORDER';\n\nexport interface IMilestoneTypeState {\n  milestoneTypes: IMilestoneType[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelMilestoneType {\n  type: typeof MILESTONE_TYPE_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingMilestoneType {\n  type: typeof MILESTONE_TYPE_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadMilestoneType {\n  type: typeof MILESTONE_TYPE_LOAD_STATUS;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateMilestoneType {\n  type: typeof MILESTONE_TYPE_CREATE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IUpdateMilestoneType {\n  type: typeof MILESTONE_TYPE_UDPATE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IDeleteMilestoneType {\n  type: typeof MILESTONE_TYPE_DELETE_STATUS;\n  payload: {\n    milestoneType: IMilestoneType\n  };\n}\n\nexport interface IChangeOrderMilestoneType {\n  type: typeof MILESTONE_TYPE_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type MilestoneTypeReduxActions =\n  ICancelMilestoneType |\n  IIsLoadingMilestoneType |\n  ICreateMilestoneType |\n  IUpdateMilestoneType |\n  IDeleteMilestoneType |\n  IChangeOrderMilestoneType |\n  ILoadMilestoneType;\n","\nexport interface IModalState {\n  title: string;\n  body: JSX.Element| null;\n  footer: JSX.Element| null;\n}\n\ninterface ILoadData {\n  type: '/MODAL/LOAD_DATA';\n  payload: {\n    title: string;\n    body: JSX.Element | null;\n    footer?: JSX.Element | null;\n  };\n}\n\nexport function loadDataAction(title: string, body: JSX.Element, footer?: JSX.Element): ILoadData {\n  return {\n    type: '/MODAL/LOAD_DATA',\n    payload: {\n      title,\n      body,\n      footer\n    }\n  };\n}\n\ninterface IClear {\n  type: '/MODAL/CLEAR';\n}\n\nexport type ModalReduxAction =\n  ILoadData |\n  IClear;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IOperationType } from '../../../../../src/request/interfaces/operationType.i