ason`}\n                    label='Motivo'\n                    component={BootstrapSelectField}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      labelOff: true,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...reasons.map((reason) => ({\n                          value: reason._id,\n                          text: reason.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.reason`, value)\n                        );\n                      }\n                    }}\n                  >\n                  </Field>\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.origin`}\n                    label='Motivo'\n                    component={BootstrapSelectField}\n                    validate={[inputStringRequired]}\n                    props={{\n                      noneSelectedText: 'Seleccione...',\n                      displayItems: 2,\n                      labelOff: true,\n                      autoClouse: true,\n                      sm: true,\n                      allOption: false,\n                      search: true,\n                      options: [\n                        ...venues.map((venue) => ({\n                          value: venue._id,\n                          text: venue.name\n                        }))\n                      ],\n                      onClick: (value: string) => {\n                        this.props.dispatch(\n                          autofill('requestImportForm', `${item}.origin`, value)\n                 