mponentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestStatus.source) {\n      this.props.requestStatus.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, status, pagination } = this.props.requestStatus;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.3\" cAction=\"Estados\">\n        <section className=\"content\">\n          <div className=\"row\">\n            <div className=\"col-md-3\">\n              <div className=\"list-group\">\n                <Link to=\"/requests/settings/reasons/\" className=\"list-group-item\">\n                  Motivos\n                </Link>\n                <Link to=\"/requests/settings/channels/\" className=\"list-group-item\">\n                  Canales\n                </Link>\n                <Link to=\"/requests/settings/status/\" className=\"list-group-item active\">\n                  Estados\n                </Link>\n                <Link to=\"/requests/settings/operations-type/\" className=\"list-group-item \">\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className=\"col-md-9\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\">\n                  <h3 className=\"box-title\">Estados <small>{pagination.count}</small></h3>\n                  <div className=\"box-tools pull-right\">\n                    {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className=\"btn btn-sm btn-success\"\n                        onClick={this.createRequestStatus}\n                        ><i className=\"fa fa-plus\" />  Crear estado</button>\n                        : null\n                    }\n                  </div>\n                </div>\n                <div className=\"box-body table-responsive no-padding\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '70%' }} className=\"middle\">Nombre</th>\n                        <th style={{ width: '10%' }} className=\"middle\">Peso</th>\n                        <th style={{ width: '18%' }} className=\"middle text-center\">Default</th>\n                        {\n                          canEdit ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                        {\n                          canDelete ?\n                            <th style={{ width: '1%' }} className=\"width-10\" /> : null\n                        }\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        status.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className=\"middle\"><strong className='text-primary'>{item.name}</strong></td>\n                              <td className=\"middle\">{item.weigth}</td>\n                              <td className=\"middle text-center\">\n                                <i\n                                  className={\n                                    item.default ?\n                                      'fa fa-check-circle text-green':\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td>\n                              {\n                                canEdit ?\n                                  <td\n                                    className=\"middle text-blue pointer\"\n                                    onClick={() => this.updateReaon(item)}\n                                  >\n                                    <i className=\"fa fa-pencil\" />\n                                  </td> : null\n                              }\n                              {\n                                !item.default && canDelete ?\n                                  <td\n                                    className={canDelete ? 'middle text-red pointer' : 'middle text-muted not-allowed'}\n                                    // className={'middle text-red pointer'}\n                                    onClick={canDelete ? () => this.deleteRequestStatus(item) : undefined}\n                                  >\n                                    <i className=\"fa fa-minus-circle\"/>\n                                  </td> : canDelete ?\n                                    <td/> : null\n                              }\n                            </tr>\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className=\"box-footer text-right\">\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\" />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRequestStatus(): void {\n    this.props.loadDataAction(\n      'Agregar Estado',\n      <StatusForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateReaon(reason: any): void {\n    this.props.loadDataAction(\n      'Editar Estado',\n      <StatusForm\n        initialValues={{ update: false, ...reason }}\n        onSubmit={this.processUpdateRequestStatus}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={() => this.props.dispatch(submit('statusForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRequestStatus(requestStatus: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateRequestStatusThunkAction(requestStatus);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteRequestStatus(requestStatus: IRequestStatus): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el estado: ${requestStatus.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestStatusThunkAction(requestStatus);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.requestStatus.options;\n    this.props.getRequestStatusThunkAction(page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestStatusThunkAction: (nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestStatusThunkAction(nextPage, orderBy, orderType, hideLoading)),\n    createRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(createRequestStatusThunkAction(requestStatus)),\n    updateRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(updateRequestStatusThunkAction(requestStatus)),\n    deleteRequestStatusThunkAction: (requestStatus: IRequestStatus) => dispatch(deleteRequestStatusItemThunkAction(requestStatus)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestStatusListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IRequestStatusState } from '../../actions/requestStatus.types';\nimport BootstrapSwitchField from '../Utils/forms/BootsrapSwitchField';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed } = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name=\"weigth\"\n              label=\"Peso *\"\n              placeholder=\"Peso\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className=\"col-md-12\">\n            <Field\n              name={`default`}\n              label=\"Por defecto\"\n              type=\"checkbox\"\n              component={BootstrapSwitchField}\n              validate={[]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{ marginTop: '20px' }}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst StatusForm = reduxForm({\n  form: 'statusForm'\n})(Form);\n\nconst mapStateToProps = (state: { requestStatus: IRequestStatusState }) => {\n  return {\n    requestStatus: state.requestStatus\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ requestStatus: IRequestStatusState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(StatusForm);","import { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport AppContainer from '../../container/AppContainer';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as Raven from 'raven-js';\nimport { connect } from 'react-redux';\nimport {\n  changeTempStudioAction,\n  createStudioAction,\n  deleteStudioAction,\n  editStudioAction,\n  getStudiosAction,\n  IStatsDashboardState,\n  ITempStudio,\n  loadStudioUsersAction,\n  StatsDashboardReducerAction\n} from '../../actions/statsDashboard.actions';\nimport { DashboardTypesDictionary, StatsDashboardTypes } from '../../../../../../src/stats/models/studio.types';\nimport { IStudio } from '../../../../../../src/stats/interfaces/studio.interface';\nimport { hasPermission } from '../../utils/common';\nimport * as moment from 'moment';\nimport Paginator from '../Utils/Paginator';\nimport ModalView from '../Modal/ModalView';\nimport { IWindow } from '../../interfaces/window';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport * as swal from 'sweetalert';\nimport StudioFormView from './StudioFormView';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getStudiosAction(type?: StatsDashboardTypes | null): void;\n  loadStudioUsers(): void;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  changeTempStudioAction(studio: ITempStudio): void;\n  deleteStudio(studio: IStudio): void;\n  processCreateStudio(): void;\n  processEditStudio(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: StatsDashboardTypes | null;\n}\n\ndeclare let window: IWindow;\n\nclass DashboardStatsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    type: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Configuración de Studios\";\n\n    this.processEditStudio = this.processEditStudio.bind(this);\n    this.createStudio = this.createStudio.bind(this);\n    this.processCreateStudio = this.processCreateStudio.bind(this);\n    this.deleteStudio = this.deleteStudio.bind(this);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getStudiosAction(this.state.type);\n    this.props.loadStudioUsers();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private showStudioModal(studio?: IStudio): void {\n    this.props.changeTempStudioAction(studio ?? {\n      name: \"\",\n      team: window.user.team._id,\n      _id: '',\n      embedURL: '',\n      type: '',\n      users: []\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        studio ? 'Editar Studio' : 'Agregar Studio',\n        <StudioFormView\n          changeTempStudioAction={this.props.changeTempStudioAction}\n          users={this.props.dashboard.users}\n          types={Object.keys(DashboardTypesDictionary).map(key => {\n            return {id: key, name: DashboardTypesDictionary[key]}\n          })}\n          dashboard={this.props.dashboard}\n        />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={studio ? this.processEditStudio : this.processCreateStudio}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  public createStudio(studio: IStudio){\n\n  }\n\n  private processCreateStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Agregar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Agregar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processCreateStudio();\n    }\n  }\n\n  private processEditStudio(): void {\n    const {tempStudio} = this.props.dashboard;\n    if (!tempStudio.name || !tempStudio.name.trim()) {\n      swal('Editar Studio', 'El nombres es requerido', 'error');\n    } else if (!tempStudio.embedURL || !tempStudio.embedURL.trim()){\n      swal('Editar Studio', 'El URL es requerido', 'error');\n    } else {\n      this.props.processEditStudio();\n    }\n  }\n\n  private deleteStudio(studio: IStudio) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el Dashboard: ${studio.name || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteStudio(studio);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const {studios, loading, pagination} = this.props.dashboard;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.3\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Studios <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                {\n                  hasPermission(window.user, 'addStatsDashboard') ?\n                    <button className=\"btn btn-sm btn-success\" onClick={() => this.showStudioModal()}><i className=\"fa fa-plus\" />  Agregar</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                <tr>\n                  <th style={{width: '30%'}} className=\"middle\">Nombre</th>\n                  <th style={{width: '30%'}} className=\"middle\">Tipo</th>\n                  <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteStatsDashboard') ?\n                      <th style={{width: '1%'}} className=\"width-10\"/> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && !studios.length?\n                    <tr>\n                      <td\n                        colSpan={2 + (hasPermission(window.user, 'deleteStatsDashboard') ? 1 : 0) +( hasPermission(window.user, 'changeStatsDashboard') ? 1 : 0)}\n                      >\n                        No se han creado análisis estadisticos\n                      </td>\n                    </tr>\n                    :null\n                }\n                {\n                  studios.map((studio: IStudio) => {\n                    return (\n                      <tr\n                        key={studio._id}\n                        id={`studio-${studio._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className=\"middle\"><strong className='text-primary'>{studio.name}</strong></td>\n                        <td className=\"middle text-muted\">{DashboardTypesDictionary[studio.type]}</td>\n                        <td className=\"middle text-sm text-muted hidden-xs\">{moment(studio.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeStatsDashboard') ?\n                            <td\n                              className=\"middle text-blue pointer\"\n                              onClick={() => this.showStudioModal(studio)}\n                            >\n                              <i className=\"fa fa-pencil\"/>\n                            </td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'deleteStatsDashboard') ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteStudio(studio)}\n                            ><i className=\"fa fa-minus-circle\"/></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>)\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStudiosAction: (type?: StatsDashboardTypes) => dispatch(getStudiosAction(type)),\n    changeTempStudioAction: (studio: ITempStudio) => dispatch(changeTempStudioAction(studio)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    deleteStudio: (studio: IStudio) => dispatch(deleteStudioAction(studio._id)),\n    loadStudioUsers: () => dispatch(loadStudioUsersAction()),\n    processCreateStudio: () => dispatch(createStudioAction()),\n    processEditStudio: () => dispatch(editStudioAction()),\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsListView);\n\n","import { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport AppContainer from '../../container/AppContainer';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as Raven from 'raven-js';\nimport { connect } from 'react-redux';\nimport { getMyStudiosAction, IStatsDashboardState, StatsDashboardReducerAction } from '../../actions/statsDashboard.actions';\nimport { IStudio } from '../../../../../../src/stats/interfaces/studio.interface';\nimport Row from '../Utils/Row';\nimport { StatsDashboardTypes } from '../../../../../../src/stats/models/studio.types';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<StatsDashboardReducerAction>;\n  dashboard: IStatsDashboardState;\n  getMyStudiosAction(type?: StatsDashboardTypes): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  menu: string;\n  cSubmenu: string;\n  type: StatsDashboardTypes;\n  tab: String;\n}\n\nclass DashboardStatsView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  state = {\n    error: null,\n    menu: \"\",\n    cSubmenu: \"\",\n    tab: \"0\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = \"Dashboard de Estadísticas\";\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    this.props.getMyStudiosAction(this.state.type)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    if (prevProps.dashboard.loading && !this.props.dashboard.loading && this.props.dashboard.studios.length > 0){\n      this.setState({\n        tab: this.props.dashboard.studios[0]._id as String\n      })\n    }\n  }\n\n  private changeTab(name: string): void {\n    this.setState({\n      tab: name\n    });\n  }\n\n\n  render() {\n    const {studios, loading} = this.props.dashboard;\n    const { tab } = this.state;\n    const selectedStudio : IStudio | undefined = studios.find((studio: IStudio) => studio._id === tab);\n    return <AppContainer title=\"\" cMenu={this.state.menu} cSubMenu={this.state.cSubmenu}>\n      <section className=\"content\">\n        <div className=\"box\">\n          <div className=\"box-header with-border\">\n            <h3 className=\"box-title\">Dashboard de Estadísticas</h3>\n          </div>\n          <div className=\"box-body\">\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n            {\n              !loading && studios.length == 0 &&\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <p>No se han encontrado resultados.</p>\n                </div>\n              </div>\n            }\n            {!loading && studios.length > 0 &&\n              <div className=\"col-md-12 col-lg-12\">\n                <div className=\"box box-solid\">\n                  <div className=\"nav-tabs-custom\">\n                    <ul className=\"nav nav-tabs\">\n                      {\n                        studios.map((studio: any) => {\n                          return (\n                            <li className={tab === studio._id ? 'active' : ''} key={studio._id}>\n                              <a\n                                href=\"javascript:void(0);\"\n                                className={tab === studio._id ? 'background-transition' : ''}\n                                style={{borderTop: '0', marginBottom: '0'}}\n                                onClick={() => this.changeTab(studio._id)}\n                              >{studio.name}</a>\n                            </li>\n                          )\n                        })\n                      }\n                    </ul>\n                  </div>\n                </div>\n              </div>\n            }\n            { selectedStudio &&\n              <Row>\n                <div className=\"col-md-12\">\n                  <div className=\"box\">\n                    <div className=\"box-body\">\n                      <iframe src={selectedStudio.embedURL} style={{width: \"100%\", minWidth: \"1000px\" ,minHeight: \"500px\", height: \"100vh\"}} allowFullScreen={true}  frameBorder={0} security={\"\"}/>\n                    </div>\n                  </div>\n                </div>\n              </Row>\n            }\n          </div>\n        </div>\n      </section>\n    </AppContainer>\n  }\n}\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard,\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getMyStudiosAction: (type?: StatsDashboardTypes) => dispatch(getMyStudiosAction(type))\n  };\n};\n\n\nclass InventoryDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"2\",\n    cSubmenu: \"2.5\",\n    type: StatsDashboardTypes.INVENTORY,\n    tab: \"\",\n  };\n}\n\nclass UnitControlDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"1\",\n    cSubmenu: \"1.7\",\n    type: StatsDashboardTypes.UNIT_CONTROL,\n    tab: \"\",\n  };\n}\n\nclass DistributionDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.DISTRIBUTION,\n    tab: \"\",\n  };\n}\n\nclass PlanificationDashboardStatsView extends DashboardStatsView {\n  state = {\n    error: null,\n    loading: true,\n    menu: \"3\",\n    cSubmenu: \"3.5\",\n    type: StatsDashboardTypes.PLANIFICATION,\n    tab: \"\",\n  };\n}\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardStatsView);\nlet VInventoryDashboardStatsView =  connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDashboardStatsView);\nlet VUnitControlDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UnitControlDashboardStatsView);\nlet VDistributionDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DistributionDashboardStatsView);\nlet VPlanificationDashboardStatsView = connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanificationDashboardStatsView);\nexport { VInventoryDashboardStatsView, VUnitControlDashboardStatsView, VDistributionDashboardStatsView, VPlanificationDashboardStatsView };\n","import * as React from \"react\";\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {\n  IStatsDashboardState, ITempStudio,\n} from \"../../actions/statsDashboard.actions\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {IUser} from \"../../../../../../src/app/interfaces/user.interface\";\nimport {IBaseVenue, IVenue} from \"../../../../../../src/app/interfaces/venue.interface\";\nimport {IStudio} from \"../../../../../../src/stats/interfaces/studio.interface\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport {connect} from \"react-redux\";\n\ninterface IPropsType {\n  dashboard: IStatsDashboardState;\n  users: IUser[];\n  types: any[];\n  changeTempStudioAction(studio: ITempStudio): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass StudioFormView extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    selectedUsers: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount() {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n\n    ($('#id-types') as any).chosen(chosenOptions).change((e: React.ChangeEvent<HTMLSelectElement>) => {\n      this.chooseType(e.target.value);\n    });\n\n    ($('#id-users') as any).chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addUser(e.target.value);\n      });\n  }\n\n\n\n  componentDidUpdate() {\n    $('#id-users').trigger('chosen:updated');\n    $('#id-types').trigger('chosen:updated');\n  }\n\n  private chooseType(type: string) {\n    const {changeTempStudioAction} = this.props;\n    const {tempStudio} = this.props.dashboard;\n    changeTempStudioAction({...tempStudio, type});\n  }\n\n  private addUser(id: string) {\n    let user = this.props.users.find((user: IUser) => user._id === id);\n    const {tempStudio} = this.props.dashboard;\n    let {users} = tempStudio;\n    if (user != undefined && !users.find((u: IUser) => u._id === user!!._id)) {\n      users.push(user);\n      this.props.changeTempStudioAction({\n          ...tempStudio,\n          users\n        }\n      )\n    }\n  }\n\n  private deleteUser(user: IUser){\n    const {tempStudio} = this.props.dashboard;\n    this.props.changeTempStudioAction({\n      ...tempStudio,\n      users: tempStudio.users.filter((u: IUser) => u._id !== user._id)\n      }\n    )\n  }\n\n  public render() {\n    const { changeTempStudioAction, users, types } = this.props;\n    const { tempStudio } = this.props.dashboard;\n\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombre</label>\n                  <input\n                    type=\"text\"\n                    name=\"name\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempStudio ? tempStudio.name : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      name: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>URL</label>\n                  <input\n                    type=\"text\"\n                    name=\"embedURL\"\n                    className=\"form-control\"\n                    defaultValue={tempStudio ? tempStudio.embedURL : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      embedURL: e.target.value})}\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-types\">Tipo</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-types\"\n                    name=\"type\"\n                    defaultValue={tempStudio ? tempStudio.type : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => changeTempStudioAction({\n                      ...tempStudio,\n                      type: e.target.value})}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      types.map((type) => (\n                        <option key={type.id} value={type.id}>{type.name}</option>\n                      ))\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-users\">Usuarios</label>\n                  <select\n                    id=\"id-users\"\n                    className=\"chosen-select form-control\"\n                    style={{minWidth: '200px'}}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}\n                  >\n                    <option value=\"\" />\n                    {\n                      users.filter(user => !tempStudio.users.find(u => u._id == user._id)).map((user) => {\n                        return (\n                          <option key={user._id} value={user._id}>{user.firstName} {user.lastName}</option>\n                        );\n                      })\n                    }\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                  <tr>\n                    <th style={{width: '90%'}}>Name</th>\n                    <th style={{width: '10%'}}/>\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    tempStudio.users.length ? tempStudio.users.map((user: IUser) => {\n                        return (\n                          <tr key={user._id}>\n                            <td>{user.firstName} {user.lastName}</td>\n                            <td\n                              className=\"text-center text-red pointer\"\n                              onClick={() => this.deleteUser(user)}\n                            >\n                              <i className=\"fa fa-minus-circle\"/>\n                            </td>\n                          </tr>\n                        );\n                      }) :\n                      <tr>\n                        <td colSpan={2}>Aún no se han seleccionado usuarios.</td>\n                      </tr>\n                  }\n                  </tbody>\n                </table>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n}\n\n\nconst mapStateToProps = (state: { statsDashboard: IStatsDashboardState }) => {\n  return {\n    dashboard: state.statsDashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StudioFormView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\n\ninterface IPropsType {\n  car: any;\n  // increaseWarning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockCarDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {car} = this.props;\n    return (\n      <tr className={car.created ? \"text-green\" : \"\"}>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.vin ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"El vin debe tener al menos 17 dígitos.\"\n              /> : null\n          }{\n            car.created ?\n              <i\n                className=\"fa fa-plus-circle text-green pointer\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"Este vehículo se agregará al stock.\"\n              /> : null\n          } {car.vin}\n        </td>\n        <td style={{fontSize: \"12px\"}}>\n          {\n            car.hasWarnings && car.warning.patent ?\n              <i\n                className=\"fa fa-warning pointer\"\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title=\"La patente debe tener al menos 6 dígitos.\"\n              /> : null\n          } {car.patent}\n        </td>\n        <td style={{fontSize: \"12px\"}}>{car.brand}</td>\n        <td style={{fontSize: \"12px\"}}>{car.denomination}</td>\n        <td style={{fontSize: \"12px\"}}>{car.type}</td>\n      </tr>\n    );\n  }\n}\n\nexport default StockCarDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo, RefObject} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport {AxiosError, AxiosResponse} from \"axios\";\nimport {\n  getStockAction,\n  IStockState,\n  StockReducerAction\n} from \"../../actions/stock.actions\";\nimport ShowIf from \"../Utils/ShowIf\";\nimport StockVenueDetail from \"./StockVenueDetail\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n  getStockAction(): StockReducerAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  loadingSettings: boolean;\n  carsByVenue: any[];\n  totalCars: number;\n  createdCard: number;\n  deletedCard: number;\n  venues: any[];\n  loading: boolean;\n  sending: boolean;\n  file: File | null;\n}\n\nclass StockImportView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    loadingSettings: false,\n    carsByVenue:[],\n    venues: [],\n    totalCars: 0,\n    createdCard: 0,\n    deletedCard: 0,\n    loading: false,\n    sending: false,\n    file: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar Stock';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.getVenues = this.getVenues.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.inputFile = React.createRef();\n  }\n\n  public componentWillMount() {\n    // set the title of the page\n    document.title = 'OSA Andes | Importar Stock';\n    this.getVenues();\n    this.props.getStockAction();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, sending, loading, carsByVenue, totalCars, createdCard, deletedCard\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.4\" cAction=\"Importar\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar stock</h3>\n              <div className=\"pull-right box-tools\">\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  onClick={this.downloadTemplate}\n                >\n                  <i className=\"fa fa-fw fa-download\"/> Descargar Formato\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                carsByVenue.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <div\n                      style={{\n                        backgroundColor: \"#f0f0f0\",\n                        padding: \"10px 10px 2px  10px\",\n                        marginBottom: \"10px\"\n                      }}>\n                        <p className=\"text-green\">\n                          <i className=\"fa fa-fw fa-plus-circle\"/> Se {createdCard > 1 ? \"agregarán\" : \"agregará\"} {createdCard} {createdCard > 1 ? \"unidades\" : \"unidad\"} al stock.\n                        </p>\n                        <p className=\"text-red\">\n                          <i className=\"fa fa-fw fa-minus-circle\" /> Se {deletedCard > 1 ? \"eliminarán\" : \"eliminará\"} {deletedCard} {deletedCard > 1 ? \"unidades\" : \"unidad\"} del stock.\n                        </p>\n                      </div>\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Configuración cargada</label>\n                        <div className=\"box-group\" id=\"accordion\" style={{margin: '2px 0 10px 0'}}>\n                          {\n                            carsByVenue.map((venue: any, index) => {\n                              return (\n                                <StockVenueDetail\n                                  index={index}\n                                  venue={venue}\n                                  key={venue.name}\n                                  deleteVenue={this.deleteVenue}\n                                />\n                              );\n                            })\n                          }\n                        </div>\n                      </div>\n                    </div>\n                    <div className=\"col-md-6\">\n                      <p><strong>Total de sucursales:</strong> {carsByVenue.length}</p>\n                      <p><strong>Total de unidades:</strong> {totalCars}</p>\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      {/*<button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile}>*/}\n                      {/*  <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración*/}\n                      {/*</button>*/}\n                    </div>\n                  </div> :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile}\n                accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <ShowIf condition={carsByVenue.length > 0}>\n              <div className=\"box-footer text-right\">\n                <button\n                  className=\"btn btn-sm btn-default\"\n                  onClick={() => this.props.history.push('/stock/')}\n                >\n                  Cancelar\n                </button>\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  style={{marginLeft: '5px'}}\n                  onClick={this.sendCreate}\n                  disabled={sending}\n                >\n                  {\n                    sending || loading ?\n                      <React.Fragment>\n                        <i className=\"fa fa-fw fa-spin fa-spinner\"/> Creando...\n                      </React.Fragment>\n                      : 'Crear'\n                  }\n                </button>\n              </div>\n            </ShowIf>\n            {\n              sending || loading || loadingSettings ?\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteVenue(venueName: string): void {\n    const {carsByVenue} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal \"${venueName}\"`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.setState({\n          carsByVenue: carsByVenue.filter((venue: any) => venue.name !== venueName)\n        });\n      }\n    });\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private downloadTemplate(): void {\n    /* headers worksheet */\n    const data = [{\n      sucursal: '',\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_stock_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    const {vinInStock} = this.props.stock;\n    const {venues} = this.state;\n    let createdCard = 0;\n    let totalCars = 0;\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook: XLSX.WorkBook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          const carsByVenue: any = {};\n          if (excelData.length >= 1) {\n            excelData.forEach((item: any) => {\n              if (item.hasOwnProperty('vin') && item.vin && item.hasOwnProperty('sucursal') && item.sucursal) {\n                totalCars++;\n                const vinWarning = item.vin.length < 17;\n                const patentWarning = item.patente && item.patente.length < 6;\n                const inStock = vinInStock.hasOwnProperty(item.vin.trim());\n                if(!inStock){\n                  createdCard++;\n                }\n                const car = {\n                  vin: item.vin.trim(),\n                  internalNumber: item.NInterno ? item.NInterno.trim() : '',\n                  color: item.color ? item.color.trim() : '',\n                  denomination: item.denominacion ? item.denominacion.trim() : '',\n                  brand: item.marca ? item.marca.trim() : '',\n                  patent: item.patente ? item.patente.trim() : '',\n                  property: item.propiedad ? item.propiedad.trim().toUpperCase() : '',\n                  type: item.tipo ? item.tipo.trim() : '',\n                  hasWarnings: vinWarning || patentWarning,\n                  created: !inStock,\n                  warning: {\n                    vin: vinWarning,\n                    patent: patentWarning\n                  }\n                };\n                if (!carsByVenue.hasOwnProperty(item.sucursal)) {\n                  carsByVenue[item.sucursal] = {\n                    cars: []\n                  };\n                }\n                carsByVenue[item.sucursal].cars.push(car);\n              } else {\n                /* tslint:disable:no-console */\n                console.log('Error en linea:');\n                console.log(item.__rowNum__);\n              }\n            });\n            const carsByVenueArray: any[] = [];\n            for (const cv in carsByVenue) {\n              if (carsByVenue.hasOwnProperty(cv)) {\n                const existVenue = venues.length ? venues.some((venue: any) => {\n                  return venue.name.trim().toLowerCase() === cv.trim().toLowerCase()\n                }) : false;\n                carsByVenueArray.push({\n                  name: cv.trim(),\n                  warningNoExist: !existVenue,\n                  cars: carsByVenue[cv].cars.sort((x: any, y: any) => {\n                    return (x.hasWarnings === y.hasWarnings) ? 0 : x.hasWarnings ? -1 : 1;\n                  })\n                });\n              }\n            }\n            this.setState({\n              file,\n              createdCard,\n              deletedCard: (Object.keys(vinInStock).length  - (totalCars- createdCard)),\n              totalCars,\n              carsByVenue: carsByVenueArray,\n              loadingSettings: false\n            });\n          } else {\n            swal(\n              'Importador de configuración',\n              `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n              'error'\n            );\n            this.setState({\n              loadingSettings: false\n            });\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    } else {\n      swal('Importador de configuración', 'Este archivo no cumple con los requisitos mínimos o no tiene autos.', 'error');\n      this.setState({\n        loadingSettings: false\n      });\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private getVenues(){\n    this.setState({loading: true});\n    const api: ApiService = new ApiService();\n    api.getVenues({ page: 1, pageSize: 200 })\n      .then((response: AxiosResponse):void =>{\n        this.setState({\n          venues: response.data.results,\n          loading: false\n        });\n      })\n    .catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  }\n\n  private sendCreate(): void {\n    const {carsByVenue, totalCars, file} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    if (!totalCars) {\n      swal('Importación de stock', 'No se ha importado la configuración o no contiene sucursales.', 'error');\n      this.setState({\n        sending: false\n      });\n    } else if (file) {\n      const api = new ApiService();\n      api.getSource();\n      api\n        .loadStock({\n          carsByVenue\n        })\n        .then((response: any) => {\n          const { message } = response.data;\n          setTimeout(() => {\n            swal('Importación de stock', message, 'success');\n          }, 200);\n          history.push('/stock/');\n          this.setState({\n            sending: false\n          });\n        })\n        .catch((e) => {\n          console.log('e', e);\n          swal('Importación de stock', 'Se produjo un error al cargar el stock.', 'error');\n          this.setState({\n            sending: false\n          });\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(StockImportView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment-timezone';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport { changeFilter, changeOrder, changeFilterText, getStockAction, IStockState, StockReducerAction } from '../../actions/stock.actions';\nimport filterFactory from 'react-bootstrap-table2-filter';\nimport paginationFactory from 'react-bootstrap-table2-paginator';\nimport BootstrapTable from 'react-bootstrap-table-next';\nimport * as XLSX from 'xlsx';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport { IFilterStock } from '../../reducers/stock.reducer';\nimport ShowIf from '../Utils/ShowIf';\nimport ImageLazyLoad from '../Utils/ImageLazyLoad';\nimport { IWindow } from '../../interfaces/window';\nimport { parseReplicableURL } from '../../utils/common';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { StatusHistory } from '../../../../../../src/app/models/history.types';\nimport DateRangeInput from '../Utils/DateRangeInput';\nimport CopyText from '../Utils/CopyText';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  dispatch: Dispatch<StockReducerAction>;\n  stock: IStockState;\n\n  getStockAction(): StockReducerAction;\n\n  changeFilter(filter: IFilterStock): StockReducerAction;\n  changeOrder(order: any): StockReducerAction;\n\n  changeFilterText(filter: IFilterStock): StockReducerAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private paginationOption: any = {\n    paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '25', value: 25\n    },{\n      text: '40', value: 40\n    }, {\n      text: '100', value: 100\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      window.scrollTo(0, 0);\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  readonly statusText: any = {\n    available: 'Disponible',\n    inTransit: 'En tránsito',\n    sale: 'Entregado'\n  };\n\n  readonly statusClass: any = {\n    available: 'label-primary',\n    inTransit: 'label-yellow',\n    sale: 'label-green'\n  };\n\n  private socket: Socket;\n\n  readonly columns: any[] = [];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Stock Actual';\n    this.xlsExport = this.xlsExport.bind(this);\n    this.daysInVenue = this.daysInVenue.bind(this);\n    this.daysPermanence = this.daysPermanence.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.movements = this.movements.bind(this);\n    this.repcetionVenue = this.repcetionVenue.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllBrands = this.filterAllBrands.bind(this);\n    this.filterBrands = this.filterBrands.bind(this);\n    this.filterAllDenominations = this.filterAllDenominations.bind(this);\n    this.filterDenominations = this.filterDenominations.bind(this);\n    this.filterAllColors = this.filterAllColors.bind(this);\n    this.filterColors = this.filterColors.bind(this);\n    this.filterStatus = this.filterStatus.bind(this);\n    this.venueFormatter = this.venueFormatter.bind(this);\n    this.filterProperty = this.filterProperty.bind(this);\n    this.handleChangeSearchText = this.handleChangeSearchText.bind(this);\n    this.clearFilter = this.clearFilter.bind(this);\n    this.statusHumanize = this.statusHumanize.bind(this);\n    this.statusFormatter = this.statusFormatter.bind(this);\n    this.vinFormatter = this.vinFormatter.bind(this);\n    this.brandFormatter = this.brandFormatter.bind(this);\n    this.detailFormatter = this.detailFormatter.bind(this);\n\n    this.columns = [{\n      dataField: 'vin',\n      text: 'VIN',\n      headerStyle: {width: '170px'},\n      formatter: this.vinFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle text-primary',\n      headerClasses: 'middle pointer',\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'brand',\n      text: 'Marca',\n      formatter: this.brandFormatter,\n      classes: 'middle',\n      headerStyle:{minWidth: '80px'},\n      headerClasses: 'middle pointer',\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'denomination',\n      text: 'Detalle',\n      classes: 'middle',\n      formatter: this.detailFormatter,\n      headerClasses: 'middle pointer',\n      // headerStyle:{maxWidth: '280px'},\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'status',\n      text: 'Estado',\n      formatter: this.statusFormatter,\n      classes: 'middle',\n      headerStyle:{minWidth: '100px'},\n      headerClasses: 'middle pointer',\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'to',\n      text: 'Sucursal',\n      headerStyle:{minWidth: '100px'},\n      formatter: this.venueFormatter,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'movements',\n      text: 'Movimientos',\n      headerStyle:{width: '120px'},\n      formatter: this.movements,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'daysInVenue',\n      text: 'En Sucursal',\n      // headerFormatter: () => (<span>Días<br />Sucursal</span>),\n      formatter: this.daysInVenue,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      headerStyle:{minWidth: '110px'},\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }, {\n      dataField: 'daysPermanence',\n      text: 'Permanencia',\n      // headerFormatter: () => (<span>Días<br />Permanencia</span>),\n      formatter: this.daysPermanence,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      headerStyle:{minWidth: '125px'},\n      sort: true,\n      onSort: (field: any, order: any) => {\n        this.props.changeOrder({dataField: field, order});\n      }\n    }];\n  }\n\n  public componentWillMount(): void {\n    this.props.getStockAction();\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `stock-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        this.props.getStockAction();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.stock.source) {\n      this.props.stock.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    $('.react-bootstrap-table-pagination')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div')\n      .removeClass('col-xs-6')\n      .addClass('col-xs-12')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div:last-child')\n      .removeClass('text-right')\n      .addClass('text-right');\n    $('#pageDropDown')\n      .removeClass('btn-sm')\n      .addClass('btn-sm');\n    $('.bs-searchbox input')\n      .removeClass('input-sm')\n      .addClass('input-sm');\n    $('.pagination')\n      .removeClass('pagination-sm')\n      .addClass('pagination-sm')\n      .css({ margin: 0 });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, carsTable, dataFilters, filter, searching, message, rangeOptions, defaultSorted } = this.props.stock;\n    return (\n      <AppContainer title={\n        <div\n          style={{ width: '180px' }}\n        >\n          <ShowIf condition={Object.keys(this.props.stock.rangeOptions.ranges!).length > 0}>\n            <DateRangeInput\n              options={rangeOptions}\n              onChange={this.onDateRangeChange}\n              startDate={filter.from}\n              endDate={filter.to}\n            />\n          </ShowIf>\n\n        </div>\n      } cMenu='2' cSubMenu='2.4'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Stock Actual <small>{carsTable.length}</small></h3>\n              <ShowIf condition={!loading && message.length < 1}>\n                <div className='box-tools pull-right'>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs hidden-sm'\n                    onClick={this.xlsExport}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    <i className='fa fa-fw fa-download' /> Exportar Excel\n                  </button>\n                </div>\n              </ShowIf>\n            </div>\n            <div className='box-body no-padding'>\n              <ShowIf condition={message.length > 1}>\n                <p className='text-center text-muted' style={{ paddingBottom: '10px' }}>\n                  <ImageLazyLoad\n                    url='/images/not_found.png'\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '20px',\n                      marginTop: '35x'\n                    }}\n                    replaceLoading={\n                      <i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />\n                    }\n                  /><br />\n                  <strong>{message}</strong>\n                </p>\n              </ShowIf>\n              <ShowIf condition={!loading && message.length < 1}>\n                <React.Fragment>\n                  <div style={{padding: '10px' }}>\n                    <div className='row' style={{ margin: '0' }}>\n                      <div className='col-md-12' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='cars' className='control-label'>Buscador</label>\n                          <input\n                            type='text'\n                            className='form-control input-sm'\n                            id='cars'\n                            defaultValue={filter.text}\n                            placeholder='Busca por VIN, Nº interno, patente, marca o modelo.'\n                            onChange={this.handleChangeSearchText}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='venues' className='control-label'>Sucursales</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todas'\n                            displayItems={2}\n                            sm={true}\n                            search={true}\n                            selectedText='sucursales seleccionadas.'\n                            selected={filter.venues}\n                            allOption={true}\n                            selectAll={this.filterAllVenues}\n                            options={dataFilters.venues.map(venue => ({\n                              value: venue._id,\n                              text: venue.name\n                            }))}\n                            onClick={this.filterVenues}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='types' className='control-label'>Estado</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todos'\n                            displayItems={4}\n                            sm={true}\n                            selectedText='estados seleccionados.'\n                            separator=' - '\n                            options={Object\n                            .keys(this.statusText)\n                            .map((status: any) => ({\n                              value: status,\n                              text: this.statusText[status],\n                              className: `label ${this.statusClass[status]}`\n                            }))}\n                            // allOption={true}\n                            selected={filter.status}\n                            // autoClouse={true}\n                            onClick={this.filterStatus}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='properties' className='control-label'>Propiedad</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todos'\n                            sm={true}\n                            displayItems={4}\n                            selectedText='estados seleccionados.'\n                            separator=' - '\n                            options={dataFilters.properties\n                              .map((property) => ({\n                                value: property,\n                                text: property\n                              }))}\n                            selected={[filter.property]}\n                            autoClouse={true}\n                            onClick={this.filterProperty}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='brands' className='control-label'>Marca</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todas'\n                            sm={true}\n                            displayItems={2}\n                            search={true}\n                            selectedText='marcas seleccionadas.'\n                            selected={filter.brands}\n                            allOption={true}\n                            selectAll={this.filterAllBrands}\n                            options={dataFilters.brands.map(brand => ({\n                              value: brand,\n                              text: brand\n                            }))}\n                            onClick={this.filterBrands}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='denominations' className='control-label'>Modelo</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todas'\n                            displayItems={2}\n                            search={true}\n                            sm={true}\n                            selectedText='modelos seleccionadas.'\n                            selected={filter.denominations}\n                            allOption={true}\n                            selectAll={this.filterAllDenominations}\n                            options={dataFilters.denominations.map(denomination => ({\n                              value: denomination,\n                              text: denomination\n                            }))}\n                            onClick={this.filterDenominations}\n                          />\n                        </div>\n                      </div>\n                      <div className='col-md-4' style={{padding: '0 5px'}}>\n                        <div className='form-group'>\n                          <label htmlFor='denominations' className='control-label'>Color</label>\n                          <BootstrapSelect\n                            noneSelectedText='Todas'\n                            sm={true}\n                            displayItems={2}\n                            search={true}\n                            selectedText='colores seleccionadas.'\n                            selected={filter.colors}\n                            allOption={true}\n                            selectAll={this.filterAllColors}\n                            options={dataFilters.colors.map(color => ({\n                              value: color,\n                              text: color\n                            }))}\n                            onClick={this.filterColors}\n                          />\n                        </div>\n                      </div>\n                    </div>\n                    {/*<Row style={{ margin: '0' }}>\n                      <div\n                        className='col-md-6 col-md-push-6 text-right'\n                        style={{ marginBottom: '10px' }}\n                      >\n                        <button\n                          className='btn btn-default btn-sm'\n                          onClick={this.clearFilter}\n                          disabled={!searching}\n                        >\n                          <i className='fa fa-fw fa-eraser' /> Limpiar Filtros\n                        </button>\n                      </div>\n                    </Row>*/}\n                  </div>\n                </React.Fragment>\n              </ShowIf>\n              <ShowIf condition={carsTable.length > 0 && !loading}>\n                <div className='stock-table'>\n                  <BootstrapTable\n                    keyField='_id'\n                    data={carsTable}\n                    columns={this.columns}\n                    filter={filterFactory()}\n                    pagination={paginationFactory(this.paginationOption)}\n                    defaultSorted={defaultSorted}\n                  />\n                </div>\n              </ShowIf>\n              <ShowIf condition={searching && carsTable.length < 1 && !loading}>\n                <p className='text-center text-muted'>\n                  <ImageLazyLoad\n                    url='/images/not_found.png'\n                    height={'200px'}\n                    style={{\n                      opacity: 0.5,\n                      maxHeight: '200px',\n                      marginBottom: '10px'\n                    }}\n                    replaceLoading={\n                      <i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />\n                    }\n                  /><br />\n                  <strong>No hay información para mostrar</strong>\n                </p>\n              </ShowIf>\n            </div>\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onDateRangeChange(from: Date, to: Date) {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      from,\n      to\n    });\n  }\n\n  private handleChangeSearchText(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    const { filter } = this.props.stock;\n    this.props.changeFilterText({\n      ...filter,\n      text: value ? e.target.value : ''\n    });\n  }\n\n  private filterAllVenues(value: boolean): void {\n    const { filter, dataFilters } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: value ? dataFilters.venues.map((venue: any) => venue._id) : []\n    });\n  }\n\n  private filterVenues(value: any): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      venues: filter.venues.includes(value)\n        ? filter.venues.filter((venue) => venue !== value)\n        : [value, ...filter.venues]\n    });\n  }\n\n  private filterAllBrands(value: boolean): void {\n    const { filter, dataFilters } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: value ? dataFilters.brands.map((brand: any) => brand) : []\n    });\n  }\n\n  private filterBrands(value: any): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      brands: filter.brands.includes(value)\n        ? filter.brands.filter((brand) => brand !== value)\n        : [value, ...filter.brands]\n    });\n  }\n\n  private filterAllDenominations(value: boolean): void {\n    const { filter, dataFilters } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: value ? dataFilters.denominations.map((denomination: any) => denomination) : []\n    });\n  }\n\n  private filterDenominations(value: any): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      denominations: filter.denominations.includes(value)\n        ? filter.denominations.filter((denomination) => denomination !== value)\n        : [value, ...filter.denominations]\n    });\n  }\n\n  private filterAllColors(value: boolean): void {\n    const { filter, dataFilters } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: value ? dataFilters.colors.map((color: any) => color) : []\n    });\n  }\n\n  private filterColors(value: any): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      colors: filter.colors.includes(value)\n        ? filter.colors.filter((color) => color !== value)\n        : [value, ...filter.colors]\n    });\n  }\n\n  private filterStatus(value: string): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      status: filter.status.includes(value)\n        ? filter.status.filter((s) => s !== value)\n        : [value, ...filter.status]\n    });\n  }\n\n  private filterProperty(value: string): void {\n    const { filter } = this.props.stock;\n    this.props.changeFilter({\n      ...filter,\n      property: filter.property !== value ? value : ''\n    });\n  }\n\n  private clearFilter(): void {\n    const { from, to } = this.props.stock.filter;\n    this.props.changeFilter({\n      venues: [],\n      colors: [],\n      brands: [],\n      denominations: [],\n      property: '',\n      status: [],\n      text: '',\n      from,\n      to\n    });\n    $('#cars').val('');\n  }\n\n  private xlsExport(): void {\n    this.trackClick('Exportar');\n    const { cars } = this.props.stock;\n    const data: any = [];\n    // order data\n    if (cars.length) {\n      for (const car of cars) {\n        if (!car.car)\n          continue;\n        let venue = (car as any).to ? (car as any).to : (car as any).from;\n        let daysInVenue = null;\n        let daysPermanence = moment().diff(moment(car.car.createdAt), 'days');\n        const venueFoundID = venue ? venue._id : '-';\n        let receptionVenue = null;\n        if (car.car?.meta?.location?.venue && car.car.meta.location.venue._id === venueFoundID) {\n          receptionVenue = car.car.meta.location.checkedDate;\n          daysInVenue = moment().diff(moment(receptionVenue), 'days');\n        }\n        data.push({\n          VIN: car.car.vin,\n          Patente: car.car?.patent?.length ? car.car.patent : '-',\n          ['Nº interno']: car.car?.internalNumber?.length ? car.car.internalNumber : '-',\n          Marca: car.car?.brand?.length ? car.car.brand : '-',\n          ['Denominación']: car.car?.denomination?.length ? car.car.denomination : '-',\n          Color: car.car.color && car.car.color.length ? car.car.color : '-',\n          Estado: this.statusText[car.status],\n          Tipo: car.car.type && car.car.type ? car.car.type : '-',\n          Propiedad: car.car.property && car.car.property ? car.car.property : '-',\n          Sucursal: venue ? venue.name : '-',\n          // ['Última actualización']: moment(car.createdAt).format('YYYY-MM-DD'),\n          ['En Sucursaln']: daysInVenue,\n          ['Permanencia']: daysPermanence\n        });\n      }\n    }\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Detalle');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, `Stock ${moment().format('YYYYMMDD')}.xlsx`);\n  }\n\n  private statusHumanize(status: StatusHistory) {\n    return this.statusText[status]\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return (\n      <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n        &nbsp;&nbsp;Mostrando del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private daysInVenue(_: string, row: any) {\n    if(row.daysInVenue){\n      return (\n        <>{row.daysInVenue}</>\n      );\n    }\n    return '-';\n  }\n\n  private movements(cell: string, row: any) {\n    return row.movements ?? '-';\n  }\n\n  private daysPermanence(cell: string, row: any) {\n    if(row.daysPermanence){\n      return (\n        <>{row.daysPermanence}</>\n      );\n    }\n    return '-';\n  }\n\n  private repcetionVenue(cell: string, row: any) {\n    return row.receptionVenue ? moment(row.receptionVenue).format('L') : '-';\n  }\n\n  private venueFormatter(cell: string, row: any) {\n    return row.venueFound !== '-' ? row.venueFound : row.venue;\n  }\n\n  private vinFormatter(cell: string, row: any) {\n    return (\n      <CopyText value={row.vin || '-'}>\n        <strong\n          className='text-primary pointer text-underline'\n          onClick={() => this.props.history.push(parseReplicableURL(`/settings/cars/${row.carID}`))}\n        >\n          {row.vin || '-'}\n        </strong>\n      </CopyText>\n    );\n  }\n\n  private brandFormatter(cell: string, row: any) {\n    return (\n      <div>\n        <strong>{row.brand}</strong><br />\n      </div>\n    );\n  }\n\n  private detailFormatter(cell: string, row: any) {\n    return (\n      <div>\n        <strong>{row.denomination}</strong><br />\n        {row.color}\n      </div>\n    );\n  }\n\n  private statusFormatter(cell: string, row: any) {\n    let status: StatusHistory = row.status;\n    return (\n      <span className={`label ${this.statusClass[status]}`}>\n        {this.statusText[status]}\n      </span>\n    )\n  }\n}\n\nconst mapStateToProps = (state: { stock: IStockState }) => {\n  return {\n    stock: state.stock\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getStockAction: () => dispatch(getStockAction()),\n    changeOrder: (order: any) => dispatch(changeOrder(order)),\n    changeFilter: (filter: IFilterStock) => dispatch(changeFilter(filter)),\n    changeFilterText: (filter: IFilterStock) => dispatch(changeFilterText(filter))\n  };\n};\n\nexport default connect<{ stock: IStockState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(StockView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport slugify from 'slugify';\nimport StockCarDetail from './StockCarDetail';\n\ninterface IPropsType {\n  venue: any;\n  index: number;\n\n  deleteVenue(venueName: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass StockVenueDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {venue, index} = this.props;\n    const warnings = venue.cars.filter((car: any) => car.hasWarnings).length;\n    const created = venue.cars.filter((car: any) => car.created).length;\n    return (\n      <div className=\"panel box box-default\" style={{borderTopWidth: '2px'}}>\n        <div className=\"box-header with-border\" style={{padding: '10px 6px'}}>\n          <h4 className=\"box-title\" style={{\n            fontSize: '15px',\n            display: 'block'\n          }}>\n            <a data-toggle=\"collapse\"\n               data-parent=\"#accordion\"\n               href={`#${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n               aria-expanded=\"false\"\n               className=\"collapsed\">\n              {index + 1} {venue.name} ({venue.cars.length} Unidades)\n\n            {/*<i*/}\n            {/*  className=\"fa fa-minus-circle text-red pull-right pointer\"*/}\n            {/*  onClick={() => this.props.deleteVenue(venue.name)}*/}\n            {/*/>*/}\n            {\n              venue.warningNoExist ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> Esta sucursal se creará.\n                </span> : null\n            }\n            {\n              warnings ?\n                <span className=\"text-muted pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-warning\" style={{color: '#f2aa2e'}}/> {warnings} alertas.\n                </span> : null\n            }\n            {\n              created ?\n                <span className=\"text-muted  text-green pull-right\" style={{marginLeft: '5px'}}>\n                  <i className=\"fa fa-plus-circle text-green\"/> {created} {created > 1 ? \"unidades\" : \"unidad\"}.\n                </span> : null\n            }\n            </a>\n          </h4>\n        </div>\n        <div\n          id={`${slugify(venue.name.toLowerCase(), {remove: /[*+~.()'\"!:@]/g})}`}\n          className=\"panel-collapse collapse\"\n          aria-expanded=\"false\"\n        >\n          <div className=\"box-body no-padding\">\n            <table className=\"table table-striped\">\n              <thead>\n              <tr>\n                <th style={{width: '18%'}}>VIN</th>\n                <th style={{width: '10%'}}>PATENTE</th>\n                <th style={{width: '15%'}}>MARCA</th>\n                <th>DENOMINACION</th>\n                <th style={{width: '15%'}}>TIPO</th>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                venue.cars.map((car: any, index: any) => {\n                  return (\n                    <StockCarDetail car={car} key={index}/>\n                  );\n                })\n              }\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default StockVenueDetail;\n","import TrackingBasePage from '../../Utils/TrackingBasePage';\nimport * as React from 'react';\nimport BootstrapTable from 'react-bootstrap-table-next';\nimport filterFactory from 'react-bootstrap-table2-filter';\nimport paginationFactory from 'react-bootstrap-table2-paginator';\nimport JsonFormatter from 'react-json-formatter'\nimport { ChoicesStatusTransmittalItem } from '../../../../../../../src/distribution/models/transmittalItem.types';\nimport * as moment from 'moment-timezone';\n\ninterface IPropsType {\n  data: any[];\n  type: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DashboardStatsView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private paginationOption: any = {\n    paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '20', value: 20\n    }, {\n      text: '50', value: 50\n    }, {\n      text: '100', value: 100\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      window.scrollTo(0, 0);\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  readonly columns: any[] = [];\n\n  readonly defaultSorted = [{\n    dataField: 'dateDiff',\n    order: 'desc'\n  }];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Stock Actual';\n    this.customTotal = this.customTotal.bind(this);\n    this.driverFormatter = this.driverFormatter.bind(this);\n    this.otFormatter = this.otFormatter.bind(this);\n    this.originFormatter = this.originFormatter.bind(this);\n    this.destinationFormatter = this.destinationFormatter.bind(this);\n    this.datesFormatter = this.datesFormatter.bind(this);\n    this.columns = [{\n      dataField: 'number',\n      text: 'OT',\n      formatter: this.otFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'transporter.patent',\n      text: 'Placa',\n      // formatter: this.brandFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'transporter.driver._id',\n      text: 'Chofer',\n      formatter: this.driverFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'origin._id',\n      text: 'Origen',\n      formatter: this.originFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }, {\n      dataField: 'destination._id',\n      text: 'Destino',\n      formatter: this.destinationFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    },{\n      dataField: 'dateDiff',\n      text: 'Fechas',\n      formatter: this.datesFormatter,\n      // filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true\n    }];\n  }\n\n  public datesFormatter(cell: string, row: any) {\n    const dateDiff: any = {\n      [ChoicesStatusTransmittalItem.pending]: moment(row.createdAt).fromNow(),\n      [ChoicesStatusTransmittalItem.shipped]: moment(row.shippingDate).fromNow(),\n      [ChoicesStatusTransmittalItem.loaded]: moment(row.loadingDate).fromNow(),\n      [ChoicesStatusTransmittalItem.documented]: row.checkDate ? moment(row.checkDate).fromNow() : '',\n      [ChoicesStatusTransmittalItem.arrived]: moment(row.evidenceDate).fromNow(),\n      [ChoicesStatusTransmittalItem.received]: moment(row.checkDate).fromNow(),\n      [ChoicesStatusTransmittalItem.damaged]: 'OTS dañadas',\n      [ChoicesStatusTransmittalItem.completed]: 'OTS completadas'\n    };\n    const {type} = this.props;\n    return dateDiff[type]\n    // return <JsonFormatter\n    //   json={JSON.stringify({\n    //     createdAt: row.createdAt,\n    //     arrivalDate: row.arrivalDate,\n    //     evidenceDate: row.evidenceDate,\n    //     shippingDate: row.shippingDate,\n    //     loadingDate: row.loadingDate,\n    //     dateDiff: row.dateDiff,\n    //     type: dateDiff[type]\n    //   })}\n    //   tabWith={4}\n    //   jsonStyle={{\n    //     propertyStyle: { color: 'red' },\n    //     stringStyle: { color: 'green' },\n    //     numberStyle: { color: 'darkorange' }\n    //   }} />;\n  }\n\n  public otFormatter(cell: string, row: any) {\n    return <strong>#{`${row.number}`}</strong>;\n  }\n\n  public driverFormatter(cell: string, row: any) {\n    return `${row.transporter.driver?.firstName} ${row.transporter.driver?.lastName}`;\n  }\n\n  public originFormatter(cell: string, row: any) {\n    return `${row.origin?.name}`;\n  }\n\n  public destinationFormatter(cell: string, row: any) {\n    return `${row.destination?.name}`;\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    $('.react-bootstrap-table-pagination')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div')\n      .removeClass('col-xs-6')\n      .addClass('col-xs-12')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div:last-child')\n      .removeClass('text-right')\n      .addClass('text-right');\n    $('#pageDropDown')\n      .removeClass('btn-sm')\n      .addClass('btn-sm');\n    $('.bs-searchbox input')\n      .removeClass('input-sm')\n      .addClass('input-sm');\n    $('.pagination')\n      .removeClass('pagination-sm')\n      .addClass('pagination-sm')\n      .css({ margin: 0 });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { data } = this.props;\n    return (\n      <BootstrapTable\n        keyField='_id'\n        data={data}\n        columns={this.columns}\n        filter={filterFactory()}\n        pagination={paginationFactory(this.paginationOption)}\n        defaultSorted={this.defaultSorted}\n      />\n    );\n  }\n\n\n  private customTotal(from: any, to: any, size: any) {\n    return (\n      <span className='react-bootstrap-table-pagination-total text-ellipsis' style={{ fontSize: '75%' }}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n}\n\nexport default DashboardStatsView;\n\n\n","import { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport AppContainer from '../../../container/AppContainer';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport DateRangeInput from '../../Utils/DateRangeInput';\nimport { IWindow } from '../../../interfaces/window';\nimport TransmittalLineChartComponent from './TransmittalLineChartComponent';\nimport { sum } from 'lodash';\nimport {\n  ChoicesStatusTransmittal\n} from '../../../../../../../src/distribution/models/transmitall.types';\nimport * as daterangepicker from 'daterangepicker';\nimport { ChoicesStatusTransmittalItem } from '../../../../../../../src/distribution/models/transmittalItem.types';\nimport ModalView from '../../Modal/ModalView';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\n\ndeclare let window: IWindow;\n\ninterface ITransmittalResume {\n  _id: string;\n  status: ChoicesStatusTransmittal;\n  shippingDate: string;\n  checkDate: string | null;\n  loadingDate: string | null;\n  evidenceDate: string | null;\n  cars: number;\n  OT: string;\n  type: string;\n}\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n\n  transmittalActions: TransmittalActions;\n  transmittal: ITransmittalState;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n  from: Date;\n  to: Date;\n}\n\nclass DashboardView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  histogramChartRef: React.RefObject<HTMLDivElement>;\n  histogramChart: echarts.ECharts;\n\n  readonly state: IStateType = {\n    error: null,\n    loading: true,\n    from: moment().startOf('month').subtract(1, 'months').toDate(),\n    to: moment().toDate()\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Transporte análisis';\n    this.histogramChartRef = React.createRef<HTMLDivElement>();\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateDashboardChart = this.updateDashboardChart.bind(this);\n    this.proccessDataForChart = this.proccessDataForChart.bind(this);\n    this.processDataForTimeline = this.processDataForTimeline.bind(this);\n  }\n\n  public componentWillUnmount(): void {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  componentWillMount() {\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n    const { from, to } = this.state;\n    this.props.transmittalActions.loadTransmittalResume(moment(from).unix().toString(), moment(to).unix().toString());\n\n  }\n\n  componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    if (this.histogramChartRef.current)\n      this.histogramChart = echarts.init(this.histogramChartRef.current!!);\n    this.updateDashboardChart();\n  }\n\n  private resizeCharts(): void {\n    if (this.histogramChart) {\n      this.histogramChart.resize();\n      setTimeout(() => {\n        this.histogramChart.resize();\n      }, 400);\n    }\n  }\n\n  getDateRangeOptions(): daterangepicker.Options {\n    return {\n      startDate: this.state.from,\n      endDate: this.state.to,\n      maxDate: moment().toDate(),\n      minYear: 2021,\n      locale: {\n        format: 'DD/MM/YYYY',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      opens: 'left'\n    };\n  }\n\n  onDateRangeChange(from: Date, to: Date) {\n    this.setState({\n      from,\n      to\n    }, () => {\n      this.props.transmittalActions.loadTransmittalResume(moment(from).unix().toString(), moment(to).unix().toString());\n    });\n  }\n\n  private calculateTimeDiff(transmittalResume: any) {\n    let datum = {\n      shipping_pending: 0,\n      pending_loading: -1,\n      loading_evidence: -1,\n      evidence_arrival: -1,\n      arrival_check: -1\n    };\n\n    // console.log('transmittalResume', transmittalResume);\n    if (transmittalResume.pendingDate && !transmittalResume.loadingDate) {\n      datum.pending_loading = moment().diff(moment(transmittalResume.createdAt), 'hours');\n    }\n\n    if (transmittalResume.shippingDate && transmittalResume.pendingDate) {\n      datum.shipping_pending = moment().diff(moment(transmittalResume.shippingDate), 'hours');\n    }\n\n    if (transmittalResume.loadingDate && !transmittalResume.evidenceDate) {\n      datum.loading_evidence = moment().diff(moment(transmittalResume.loadingDate), 'hours');\n    }\n\n    if (transmittalResume.evidenceDate && !transmittalResume.arrivalDate) {\n      datum.evidence_arrival = moment().diff(moment(transmittalResume.checkDate), 'hours');\n    }\n\n    if (transmittalResume.evidenceDate && !transmittalResume.checkDate) {\n      datum.arrival_check = moment().diff(moment(transmittalResume.evidenceDate), 'hours');\n    }\n    console.log('datum.evidence_arrival', datum?.evidence_arrival);\n\n    return datum;\n  }\n\n  private calculateCarOTQuantity(transmittalResumes: ITransmittalResume[]) {\n\n    let shipping = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          transmittalResume.status === 'pending' && moment(transmittalResume.shippingDate).isValid()\n      );\n    let pending = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          transmittalResume.status === 'pending' && !moment(transmittalResume.loadingDate).isValid()\n      );\n    // console.log('pending', pending);\n    let loading = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          (transmittalResume.status === 'pending' && moment(transmittalResume.loadingDate).isValid()) ||\n          (transmittalResume.status === 'inTransit' && !moment(transmittalResume.evidenceDate).isValid())\n      );\n    // console.log('loading', loading);\n    let evidence = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          transmittalResume.status === 'inTransit' && moment(transmittalResume.evidenceDate).isValid()\n      );\n    console.log('evidence', evidence);\n    let arrival = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          transmittalResume.status === 'completed' && !moment(transmittalResume.checkDate).isValid()\n      );\n    let receptions = transmittalResumes\n      .filter(\n        (transmittalResume) =>\n          ['completed', 'completed_by_reception'].includes(transmittalResume.status) &&\n          moment(transmittalResume.checkDate).isValid()\n      );\n\n    return {\n      shipping_car: shipping.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      shipping,\n      pending_car: pending.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      pending_ot: pending.length,\n      pending,\n      loading_car: loading.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      loading_ot: loading.length,\n      loading,\n      evidence_car: evidence.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      evidence_ot: evidence.length,\n      evidence,\n      arrival_car: arrival.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      arrival_ot: arrival.length,\n      arrival,\n      receptions_car: receptions.reduce((a: number, b: ITransmittalResume) => a + b.cars, 0),\n      receptions_ot: receptions.length,\n      receptions\n    };\n  }\n\n  private humanizeHours(hours: number) {\n    if (hours === 0) {\n      return '-';\n    }\n    let days = Math.floor(hours / 24);\n    let left_hours = Math.floor(hours % 24);\n\n    if (days > 0)\n      if (hours > 0) {\n        return `${days}d ${left_hours}h`;\n      } else {\n        return `${days}d`;\n      }\n    else {\n      return `${left_hours}h`;\n    }\n  }\n\n  private processDataForTimeline() {\n    let { resume } = this.props.transmittal;\n\n    if (resume.length === 0) {\n      return { circles: [] };\n    }\n\n    resume = resume.filter(transmittalResume =>\n      transmittalResume.type === 'Internacional'\n    );\n\n    let quanty_datum = this.calculateCarOTQuantity(resume);\n\n    let active_OT = resume.filter(transmittalResume =>\n      !quanty_datum.receptions.find((datum: ITransmittalResume) => datum.OT === transmittalResume.OT)\n    );\n\n    let time_datum_resume = active_OT.map(transmittal =>\n      this.calculateTimeDiff(transmittal)\n    );\n\n    let filtered_shipping = time_datum_resume.filter(datum => datum.shipping_pending !== 0).map(d => d.shipping_pending > 0 ? d.shipping_pending : d.pending_loading + d.shipping_pending);\n    let filtered_pending = time_datum_resume.filter(datum => datum.pending_loading >= 0).map(d => d.pending_loading);\n    let filtered_loaded = time_datum_resume.filter(datum => datum.loading_evidence >= 0).map(d => d.loading_evidence);\n    let filtered_evidence = time_datum_resume.filter(datum => datum.evidence_arrival >= 0).map(d => d.evidence_arrival);\n    let filtered_checked = time_datum_resume.filter(datum => datum.arrival_check >= 0).map(d => d.arrival_check);\n    console.log('filtered_pending', filtered_pending);\n\n\n    let shipping_time_hours = filtered_shipping.length === 0 ? 0 : sum(filtered_shipping) / filtered_shipping.length;\n    let pending_time_hours = filtered_pending.length === 0 ? 0 : sum(filtered_pending) / filtered_pending.length;\n    let loaded_time_hours = filtered_loaded.length === 0 ? 0 : sum(filtered_loaded) / filtered_loaded.length;\n    let evidence_time_hours = filtered_evidence.length === 0 ? 0 : sum(filtered_evidence) / filtered_evidence.length;\n    let checked_time_hours = filtered_checked.length === 0 ? 0 : sum(filtered_checked) / filtered_checked.length;\n    console.log('pending_time_hours', pending_time_hours);\n\n    let shipping_time = this.humanizeHours(shipping_time_hours);\n    let pending_time = this.humanizeHours(pending_time_hours);\n    let loaded_time = this.humanizeHours(loaded_time_hours);\n    let evidence_time = this.humanizeHours(evidence_time_hours);\n    let checked_time = this.humanizeHours(checked_time_hours);\n\n\n    let total_time = shipping_time_hours + pending_time_hours + loaded_time_hours + evidence_time_hours + checked_time_hours;\n    let total_ot = resume.length - quanty_datum.receptions_ot;\n    let total_car = sum(resume.map(d => d.cars)) - quanty_datum.receptions_car;\n\n    return {\n      circles: [{\n        value: quanty_datum.shipping_car,\n        upperValues: [shipping_time],\n        lowerValues: [quanty_datum.shipping_car, '-'],\n        type: ChoicesStatusTransmittalItem.shipped,\n        title: 'Embarque',\n        color: '#808080'\n      }, {\n        value: quanty_datum.pending_car,\n        upperValues: [pending_time],\n        lowerValues: [quanty_datum.pending_car, quanty_datum.pending_ot],\n        type: ChoicesStatusTransmittalItem.pending,\n        title: 'Pendiente',\n        color: '#bc4da0'\n      }, {\n        value: quanty_datum.loading_car,\n        upperValues: [loaded_time],\n        lowerValues: [quanty_datum.loading_car, quanty_datum.loading_ot],\n        type: ChoicesStatusTransmittalItem.loaded,\n        title: 'Cargado',\n        color: '#00c1f7'\n      }, {\n        value: quanty_datum.evidence_car,\n        upperValues: [evidence_time],\n        lowerValues: [quanty_datum.evidence_car, quanty_datum.evidence_ot],\n        type: ChoicesStatusTransmittalItem.documented,\n        title: 'Documentación',\n        color: '#00c1f7'\n      }, {\n        value: quanty_datum.arrival_car,\n        upperValues: [checked_time],\n        lowerValues: [quanty_datum.arrival_car, quanty_datum.arrival_ot],\n        type: ChoicesStatusTransmittalItem.arrived,\n        title: 'Descargado',\n        color: '#00c1f7'\n      }, {\n        value: quanty_datum.arrival_car,\n        type: ChoicesStatusTransmittalItem.received,\n        upperValues: ['-'],\n        lowerValues: ['-', '-'],\n        title: 'Recepción PDI',\n        color: '#f23d8b'\n      }],\n      total_time: this.humanizeHours(total_time),\n      total_ot,\n      total_car\n    };\n\n  }\n\n  render() {\n    const { from, to } = this.state;\n    const { loading, resume } = this.props.transmittal;\n\n    let end_date = moment(to).endOf('week').endOf('d');\n\n    let completedTransmittals = resume.filter(t =>\n      [ChoicesStatusTransmittal.completed, ChoicesStatusTransmittal.completed_by_reception].includes(t.status) &&\n      moment(t.arrivalDate).isSameOrBefore(end_date));\n\n    let international_data: any = this.processDataForTimeline();\n\n    return <AppContainer\n      cMenu='3'\n      cSubMenu='3.6'\n      title={\n        <div\n          style={{ width: '180px' }}\n        >\n          <DateRangeInput\n            options={this.getDateRangeOptions()}\n            onChange={this.onDateRangeChange}\n            startDate={from}\n            endDate={to}\n          />\n        </div>\n      }\n    >\n      <section className='content'>\n        {\n          loading ?\n            <div className='box'>\n              <div className='box-body text-center'>\n                <p>&nbsp;</p>\n              </div>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </div> :\n            <>\n              <div className='box'>\n                <div className='row no-margin'>\n                  <div className='box-header with-border'>\n                    <h3 className='box-title'>\n                      OT totales completadas por semana <small>({completedTransmittals.length})</small>\n                    </h3>\n                  </div>\n                  <div ref={this.histogramChartRef} style={{ height: '40vh', maxWidth: '100%' }}></div>\n                </div>\n              </div>\n              <div className='box'>\n\n                <div className='row no-margin' style={{ maxWidth: '100%', marginBottom: '20px' }}>\n                  <div className='box-header with-border'>\n                    <h3 className='box-title'>Vista actual de la cadena </h3>\n                  </div>\n                  <div className='box-title' style={{ marginTop: '20px', marginBottom: '20px' }}>\n                    <span style={{ fontSize: '16px', marginLeft: '20px', fontWeight: 'bold' }}>Ruta Internacional | <i\n                      className='fa fa-fw fa-car' /> {international_data.total_car} | <i\n                      className='fa fa-fw fa-truck' /> {international_data.total_ot} | <i\n                      className='fa fa-fw fa-clock-o' /> {international_data.total_time}</span>\n                  </div>\n                  <TransmittalLineChartComponent\n                    circleSize={50}\n                    loadDataAction={this.props.loadDataAction}\n                    circles={international_data.circles}\n                    lineColor='#7bd7eb'\n                    from={moment(from).unix().toString()}\n                    to={moment(to).unix().toString()}\n                  />\n                </div>\n\n              </div>\n            </>\n        }\n        <ModalView noPadding={true} modalLarge={true} />\n      </section>\n    </AppContainer>;\n  }\n\n  private proccessDataForChart() {\n    const { resume } = this.props.transmittal;\n    const { from, to } = this.state;\n\n    let startDate = moment(from).startOf('week').startOf('d');\n    let endDate = moment(to).endOf('week').endOf('d');\n\n    let completed = [];\n    let completed_reception = [];\n\n    let completedTransmittals = resume.filter(t =>\n      [ChoicesStatusTransmittal.completed, ChoicesStatusTransmittal.completed_by_reception].includes(t.status) &&\n      moment(t.arrivalDate).isSameOrBefore(endDate)\n    ).map(t => {\n      return { date: moment(t.arrivalDate), status: t.status };\n    });\n\n    while (startDate < endDate) {\n      let endWeek = startDate.clone().endOf('week');\n      completed.push({\n        name: `${startDate.format('MMM DD')} ${endWeek.format('MMM DD')}`.replace('.', '').toUpperCase(),\n        value: completedTransmittals.filter(t => t.date.isSameOrAfter(startDate) && t.date.isBefore(endWeek) && t.status === ChoicesStatusTransmittal.completed).length,\n        label: {\n          fontWeight: 'bold',\n          fontSize: 12,\n          color: startDate.clone().add(1, 'week') > endDate ? '#52c1e9' : '#000'\n        }\n      });\n\n      completed_reception.push({\n        name: `${startDate.format('MMM DD')} ${endWeek.format('MMM DD')}`.replace('.', '').toUpperCase(),\n        value: completedTransmittals.filter(t => t.date.isSameOrAfter(startDate) && t.date.isBefore(endWeek) && t.status === ChoicesStatusTransmittal.completed_by_reception).length,\n        label: {\n          fontWeight: 'bold',\n          fontSize: 12,\n          color: startDate.clone().add(1, 'week') > endDate ? '#52c1e9' : '#000'\n        }\n      });\n      startDate = startDate.add(1, 'week');\n    }\n\n    return { completed, completed_reception };\n\n  }\n\n  private updateDashboardChart() {\n    if (this.histogramChart === undefined) {\n      return;\n    }\n\n    let { completed, completed_reception } = this.proccessDataForChart();\n\n    const option: any = {\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'none'\n        }\n      },\n      legend: {\n        show: true,\n        bottom: 20,\n        selectedMode: false\n      },\n      calculable: true,\n      xAxis: [\n        {\n          type: 'category',\n          axisTick: { show: false },\n          data: completed.map(datum => {\n            return { value: datum.name, textStyle: datum.label };\n          })\n        }\n      ],\n      yAxis: [\n        {\n          show: false,\n          type: 'value'\n        }\n      ],\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        x: 0,\n        // right\n        x2: 10,\n        containLabel: true\n      },\n      series: [\n        {\n          name: 'OT completadas',\n          type: 'bar',\n          cursor: 'default',\n          stack: 'total',\n          color: '#3b8dbc',\n          barMaxWidth: 50,\n          label: {\n            position: 'top',\n            show: false,\n            fontSize: 12,\n            color: '#000'\n          },\n          data: completed.map(datum => {\n            return { name: datum.name, value: datum.value };\n          })\n        }, {\n          name: 'OT cerradas por recepción',\n          type: 'bar',\n          stack: 'total',\n          cursor: 'default',\n          color: '#f39c12',\n          barMaxWidth: 50,\n          label: {\n            position: 'top',\n            show: true,\n            fontSize: 12,\n            color: '#000',\n            formatter: (object: any) => {\n              return completed[object.dataIndex].value + completed_reception[object.dataIndex].value;\n            }\n          },\n          data: completed_reception.map(datum => {\n            return { name: datum.name, value: datum.value };\n          })\n        }\n      ]\n    };\n\n    this.histogramChart.setOption(option);\n\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState, router: any }) => {\n  return {\n    transmittal: state.transmittal,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardView);\n","import * as React from 'react';\nimport * as moment from 'moment-timezone';\nimport { ModalReduxAction } from '../../../actions/modal.actions';\nimport DashboardStatsView from './DashboardStatusView';\nimport { ChoicesStatusTransmittalItem } from '../../../../../../../src/distribution/models/transmittalItem.types';\nimport ApiService from '../../../utils/axios';\n\nexport interface dataPoint {\n  value: number;\n  upperValues: string[];\n  lowerValues: string[];\n  type: string;\n  title: string;\n  color: string;\n}\n\ninterface IPropsType {\n  circles: dataPoint[],\n  from: string\n  to: string\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n\n  circleSize: number;\n  lineColor: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass TransmittalLineChartComponent extends React.Component<IPropsType, IStateType> {\n\n\n  readonly titleByStatus: any = {\n    [ChoicesStatusTransmittalItem.pending]: 'OTS pendientes',\n    [ChoicesStatusTransmittalItem.shipped]: 'OTS embarcadas',\n    [ChoicesStatusTransmittalItem.loaded]: 'OTS cargadas',\n    [ChoicesStatusTransmittalItem.documented]: 'OTS documentadas',\n    [ChoicesStatusTransmittalItem.arrived]: 'OTS descargadas',\n    [ChoicesStatusTransmittalItem.received]: 'OTS recepcionadas',\n    [ChoicesStatusTransmittalItem.damaged]: 'OTS dañadas',\n    [ChoicesStatusTransmittalItem.completed]: 'OTS completadas',\n  };\n  readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.showOtsOnStatus = this.showOtsOnStatus.bind(this);\n    this.api = new ApiService();\n  }\n\n\n\n  render() {\n    let { circles, circleSize, lineColor } = this.props;\n    let circles_n = circles.length;\n    let circle_width = circleSize;\n    let label_length = 50;\n    let line_diff = circles_n * circle_width + label_length;\n    let lines_n = circles_n - 1;\n    return <div className='row' style={{ display: 'flex', alignItems: 'center', marginLeft: '20px', marginRight: '20px', marginBottom: '40px' }}>\n      <div style={{ paddingRight: '10px', width: `${label_length}px` }} key='0'>\n        <div style={{ marginBottom: '14px', color: '#333', marginTop: '20px' }}>\n          <p style={{ fontSize: '14px', color: '#333', marginTop: '45px', marginBottom: '0px' }}>\n            <i className='fa fa-fw fa-clock-o' />\n          </p>\n        </div>\n        <div className='no-margin' style={{ height: `${circle_width}px` }} />\n        <div style={{ marginTop: '5px' }}>\n          <p style={{ fontSize: '14px', color: '#333' }}>\n            <i className='fa fa-fw fa-car' />\n          </p>\n          <p style={{ fontSize: '14px', color: '#333' }}>\n            <i className='fa fa-fw fa-truck' />\n          </p>\n        </div>\n      </div>\n      {\n        circles.map((circle, index) => {\n          if (index === 0) {\n            return <div key={`circle-${index}`} style={{ display: 'inline-block', width: `${circle_width}px` }}>\n              <div style={{ marginTop: '10px' }}>\n                <p\n                  style={{\n                    paddingLeft: '20%',\n                    fontSize: '15px',\n                    fontWeight: 510,\n                    whiteSpace: 'nowrap'\n                  }}\n                >\n                  {circle.title}\n                </p>\n                {\n                  circle.upperValues.map(value =>\n                    <p key={value} style={{\n                      paddingLeft: '20%',\n                      fontSize: '14px',\n                      fontWeight: 510,\n                      whiteSpace: 'nowrap'\n                    }}>\n                      {value}\n                    </p>\n                  )\n                }\n              </div>\n              <div\n                className='no-margin'\n                style={{\n                  height: `${circle_width}px`,\n                  width: `${circle_width}px`,\n                  borderRadius: '50%',\n                  backgroundColor: circle.color\n                }} />\n              <div style={{ marginTop: '10px' }}>\n                {\n                  circle.lowerValues.map(value =>\n                    <p key={value} style={{\n                      paddingLeft: '20%',\n                      fontSize: '14px',\n                      fontWeight: 510,\n                      whiteSpace: 'nowrap'\n                    }}>\n                      {value}\n                    </p>\n                  )\n                }\n              </div>\n            </div>;\n          } else {\n            return <React.Fragment key={index}>\n              <div\n                key={`line-${index}`}\n                style={{\n                  display: 'inline-block',\n                  height: '100%',\n                  width: `calc((95% - ${line_diff}px)/${lines_n})`,\n                  marginTop: '10px'\n                }}\n              >\n                <div style={{ height: '10px', backgroundColor: lineColor }} />\n              </div>\n              <div key={`circle-${index}`} style={{ display: 'inline-block', width: `${circle_width}px` }}>\n                <div style={{ marginTop: '10px' }}>\n                  <p\n                    style={{\n                      paddingLeft: '20%',\n                      fontSize: '15px',\n                      fontWeight: 510,\n                      whiteSpace: 'nowrap'\n                    }}\n                  >\n                    {circle.title}\n                  </p>\n                  {\n                    circle.upperValues.map(value =>\n                      <p key={value} style={{\n                        paddingLeft: '20%',\n                        fontSize: '14px',\n                        fontWeight: 510,\n                        whiteSpace: 'nowrap'\n                      }}>\n                        {value}\n                      </p>\n                    )\n                  }\n                </div>\n                <div\n                  className='no-margin pointer'\n                  onClick={() => {\n                    this.showOtsOnStatus(circle.type);\n                  }}\n                  style={{\n                    height: `${circle_width}px`, width: `${circle_width}px`,\n                    borderRadius: '50%',\n                    backgroundColor: circle.color\n                  }}\n                />\n                <div>\n                  {\n                    circle.lowerValues.map((value, index) =>\n                      <p key={index} style={{\n                        paddingLeft: '20%',\n                        fontSize: '14px',\n                        fontWeight: 510,\n                        whiteSpace: 'nowrap'\n                      }}>\n                        {value}\n                      </p>\n                    )\n                  }\n                </div>\n              </div>\n            </React.Fragment>;\n          }\n        })\n      }\n    </div>;\n  }\n\n  private showOtsOnStatus(type: string) {\n    const {from, to} = this.props;\n    this.api.getOtsOnStatus(type, from, to)\n      .then(response => {\n        this.props.loadDataAction(\n          this.titleByStatus[type],\n          <DashboardStatsView\n            type={type}\n            data={response.data.map((item: any) => {\n            const dateDiff: any = {\n              [ChoicesStatusTransmittalItem.pending]: moment().diff(moment(item.createdAt), 'minutes'),\n              [ChoicesStatusTransmittalItem.shipped]: moment().diff(moment(item.shippingDate), 'minutes'),\n              [ChoicesStatusTransmittalItem.loaded]: moment().diff(moment(item.loadingDate), 'minutes'),\n              [ChoicesStatusTransmittalItem.documented]: item.checkDate ? moment().diff(moment(item.checkDate), 'minutes') : 0,\n              [ChoicesStatusTransmittalItem.arrived]: moment().diff(moment(item.evidenceDate), 'minutes'),\n              [ChoicesStatusTransmittalItem.received]: moment().diff(moment(item.checkDate), 'minutes'),\n              [ChoicesStatusTransmittalItem.damaged]: 'OTS dañadas',\n              [ChoicesStatusTransmittalItem.completed]: 'OTS completadas'\n            };\n            return {\n              ...item,\n              dateDiff: dateDiff[type]\n            };\n          })} />,\n          <React.Fragment>\n            <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cerrar</button>\n          </React.Fragment>\n        );\n      });\n  }\n}\n\nexport default TransmittalLineChartComponent;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { Dispatch, ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport TransmittalActions from '../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../actions/transmittal.types';\nimport TransmittalForm from './TransmittalForms/TransmittalForm';\nimport ShowIf from '../Utils/ShowIf';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport * as swal from 'sweetalert';\nimport { imageStatus } from '../Utils/MultiUploadFiles';\nimport { ITransmittal } from '../../../../../../src/distribution/interfaces/transmittal.interface';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    loading: false\n  };\n\n  private socket: Socket;\n\n  private readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear orden de transporte';\n    this.processForm = this.processForm.bind(this);\n    this.cancel = this.cancel.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `distribution-create-${window.user.team._id}`\n      });\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-create-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions } = this.props;\n    const { loading } = this.props.transmittal;\n\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.4' cAction='Crear Order'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Crear orden de transporte</h3>\n            </div>\n            <div className='box-body'>\n              <TransmittalForm\n                initialValues={{\n                  files: [],\n                  items: []\n                }}\n                onSubmit={this.processForm}\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <button\n                type='button'\n                className='btn btn-sm btn-default'\n                onClick={this.cancel}\n              >\n                Cancelar\n              </button>\n              <button\n                type='button'\n                className='btn btn-sm btn-primary'\n                disabled={this.state.loading}\n                style={{ marginLeft: '5px' }}\n                onClick={() => transmittalActions.submit('transmittalForm')}\n              >\n                <ShowIf condition={this.state.loading}>\n                  <i className='fa fa-spinner fa-spin ' />\n                </ShowIf> Crear\n              </button>\n            </div>\n            <ShowIf condition={loading || this.state.loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private cancel(): void {\n    this.props.history.push('/transmittals/');\n  }\n\n  private processForm(data: ITransmittal) {\n    const { history } = this.props;\n    const isUploadingFiles = data.files?.filter((file: any) => file.status !== imageStatus.complete).length;\n    const hasItemsLoaded = data.items?.length >= 1;\n    if (isUploadingFiles) {\n      swal!('Orden de transporte', 'Aún se estan cargando archivos, espera que terminen para enviar.', 'error');\n    } else if (!hasItemsLoaded) {\n      swal!('Orden de transporte', 'Debes agregar al menos un vehículo para poder crear una order.', 'error');\n    } else {\n      this.setState({ loading: true });\n      this.api.createTransmittals({\n        ...data,\n        items: data.items.map((item) => ({\n          ...item,\n          request: item.request?._id,\n          requestItem: (item as any).type === 'request' ? item?._id : null\n        })),\n        files: data.files.map((file) => file._id)\n      })\n        .then((response: AxiosResponse): void => {\n          swal('Orden de transporte', 'Se ha creado satisfactoriamente.', 'success')\n            .then(() => {\n              this.setState({ loading: false });\n              history.push('/transmittals/');\n            });\n        })\n        .catch((err: AxiosError): void => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalCreateView);\n","import * as React from 'react';\nimport ShowIf from '../../Utils/ShowIf';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport SearchCarInRequests from './SearchCarInRequest';\nimport SearchCarInCars from './SearchCarInCars';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\n\ntype Tabs = 'cars' | 'requests'\n\ninterface IPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClickRequest(item: IRequestItem): void;\n\n  onClickCar(car: ICar): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tab: Tabs;\n}\n\ndeclare let window: IWindow;\n\n\nclass AddItemsToTransmittal extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    tab: 'requests'\n  };\n\n  public render(): React.ReactElement<IPropsType> {\n    const { tab } = this.state;\n    const { fields, onClickRequest, onClickCar, slimView } = this.props;\n    return (\n      <div>\n        <ShowIf condition={hasPermission(window.user, 'addCarOnTransmittal')}>\n          <ul className='nav nav-pills nav-justified' style={{ marginTop: '10px', marginBottom: '10px', border: '1px solid #f4f4f4' }}>\n            <li className={tab === 'requests' ? 'active' : ''}>\n              <a\n                className={tab === 'requests' ? 'background-transition' : ''}\n                href='javascript:void(0);'\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('requests')}\n              >Solicitudes</a>\n            </li>\n            <li className={tab === 'cars' ? 'active' : ''}>\n              <a\n                href='javascript:void(0);'\n                className={tab === 'cars' ? 'background-transition' : ''}\n                style={{ borderTop: '0', marginBottom: '0' }}\n                onClick={() => this.changeTab('cars')}\n              >Unidades</a>\n            </li>\n          </ul>\n        </ShowIf>\n        <ShowIf condition={tab === 'requests'}>\n          <SearchCarInRequests fields={fields!} onClick={onClickRequest} slimView={slimView} />\n        </ShowIf>\n        <ShowIf condition={tab === 'cars'}>\n          <SearchCarInCars fields={fields!} slimView={slimView} onClick={onClickCar} />\n        </ShowIf>\n      </div>\n    );\n  }\n\n  private changeTab(tab: Tabs) {\n    this.setState({\n      tab\n    });\n  }\n}\n\nexport default AddItemsToTransmittal;\n\n\n","import { Dispatch } from 'redux';\nimport * as React from 'react';\nimport { CarReduxAction, getCarsAction, ICarsState } from '../../../actions/cars.actions';\nimport { connect } from 'react-redux';\nimport { debounce } from 'throttle-debounce';\nimport Paginator from '../../Utils/Paginator';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\n\ninterface IExternarlPropsType {\n  slimView?: boolean\n  fields?: FieldArrayFieldsProps<any>;\n  onClick(item: ICar): void;\n}\n\ninterface IPropsType  extends IExternarlPropsType {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n\n  getCarsAction(page: number, search?: string): CarReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n}\n\n\nclass SearchCarInCars extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    searchText: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  public componentWillMount() {\n    const { pagination } = this.props.cars;\n    this.props.getCarsAction(pagination.page);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, cars, pagination } = this.props.cars;\n    const { slimView, onClick, fields } = this.props;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field.car.vin) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-12'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo o material.'\n                    onChange={this.onChangeSearch}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-striped table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                          <th className='middle'> Color</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    cars\n                      .filter(item => !addedItems.includes(item.vin))\n                      .map((car) => {\n                      return (\n                        <tr key={car._id}>\n                          <td className='middle' style={{ width: '120px' }}>{car.vin}</td>\n                          {\n                            slimView ?\n                              <React.Fragment>\n                                <td className='middle'>\n                                  <strong>{car?.brand}</strong> {car?.denomination}\n                                </td>\n                                <td className='middle'>\n                                  {car?.color}\n                                </td>\n                              </React.Fragment>\n                              : <React.Fragment>\n                                <td className='middle'>{car.brand}</td>\n                                <td className='middle'>{car.denomination}</td>\n                                <td className='middle'>{car.color}</td>\n                              </React.Fragment>\n                          }\n                          <td className='middle'>\n                            <a\n                              className='btn btn-success btn-sm'\n                              href={'javascript:void(0);'}\n                              onClick={() => onClick(car)}\n                            >\n                              <i className='fa fa-plus' /> Agregar\n                            </a>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            loading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.setState({\n      searchText: value\n    });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { searchText } = this.state;\n    if (searchText && searchText.length) {\n      this.props.getCarsAction(1, searchText);\n    } else {\n      this.props.getCarsAction(1);\n    }\n  }\n\n  private changePage(page: number): void {\n    const { searchText } = this.state;\n    this.props.getCarsAction(page, searchText);\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState }) => {\n  return {\n    cars: state.cars\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarsAction: (page: number, search?: string) => dispatch(getCarsAction(page, search))\n  };\n};\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInCars);\n\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment-timezone';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { Dispatch } from 'redux';\nimport { FieldArrayFieldsProps } from 'redux-form/lib/FieldArray';\nimport Paginator from '../../Utils/Paginator';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../../src/app/interfaces/user.interface';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { IWindow } from '../../../interfaces/window';\nimport ShowIf from '../../Utils/ShowIf';\n\n\ninterface IExternarlPropsType {\n  fields?: FieldArrayFieldsProps<any>;\n  slimView?: boolean;\n\n  onClick(item: IRequestItem): void;\n}\n\ninterface IPropsType extends RouteComponentProps<{}>, IExternarlPropsType {\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass SearchCarInRequests extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changePage = this.changePage.bind(this);\n    this.getRequestItemDebounced = debounce(800, this.getRequestItemDebounced.bind(this));\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getRequestItemThunkAction(1);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n    this.socket.on('DELETE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { requestItemsPagination } = this.props.transmittal;\n      this.props.transmittalActions.getRequestItemThunkAction(requestItemsPagination.page, true);\n    });\n  }\n\n  public componentWillUnmount(): void {\n    //cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalActions, transmittal, fields, slimView } = this.props;\n    const { requestItems, requestItemsfilters, requestItemsPagination, requestItemsLoading } = transmittal;\n    const addedItems = fields?.getAll() ? fields.getAll().map(field => field._id) : [];\n    return (\n      <div className='row'>\n        <div className='col-md-12'>\n          <div className='table-container-overlay'>\n            <div className='row'>\n              <div className='col-md-8'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Vehículo\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Busca por VIN, marca, modelo, material o nº de solicitud.'\n                    defaultValue={requestItemsfilters.text}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('text', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Nº Solicitudes\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de solicitudes ejemplo: 2, 8, 10'\n                    defaultValue={requestItemsfilters.request}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('request', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-2'>\n                <div className='form-group'>\n                  <label className='control-label'>\n                    Partida\n                  </label>\n                  <input\n                    type='text'\n                    className='form-control input-sm'\n                    placeholder='Nº de partida ejemplo: J-2136'\n                    defaultValue={requestItemsfilters.entry}\n                    onChange={(e) => {\n                      transmittalActions.filterRequestItemAction('entry', e.target.value);\n                      this.getRequestItemDebounced();\n                    }}\n                  />\n                </div>\n              </div>\n              <div className='col-md-12'>\n                <div className='table-responsive'>\n                  <table className='table table-striped table-xs table-hover' style={!slimView ? { minWidth: '1000px' } : {}}>\n                  <thead>\n                  <tr className='bg-primary' style={{ height: '45px' }}>\n                    <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                    <th className='middle' style={{ width: '120px' }}>VIN</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle'> Vehículo</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle'>Marca</th>\n                          <th className='middle'>Modelo</th>\n                          <th className='middle'>Color</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '100px' }}>Partida</th>\n                    <th className='middle' style={{ width: '100px' }}>Factura</th>\n                    {\n                      slimView ?\n                        <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                        </React.Fragment>\n                        : <React.Fragment>\n                          <th className='middle' style={{ width: '150px' }}>Solicitante</th>\n                          <th className='middle' style={{ width: '150px' }}>Origen</th>\n                          <th className='middle' style={{ width: '150px' }}>Destino</th>\n                          <th className='middle' style={{ width: '100px' }}>Fecha</th>\n                        </React.Fragment>\n                    }\n                    <th className='middle' style={{ width: '28px' }} />\n                  </tr>\n                  </thead>\n                  <tbody>\n                  {\n                    requestItems\n                      .filter(item => !addedItems.includes(item._id))\n                      .map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td className={`middle-center`}>\n                              #{item.request?.number}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.vin}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className='middle'>\n                                    <strong>{item.car?.brand}</strong> {item.car?.denomination}< br />\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {item.car?.brand}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.denomination}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.car?.color}\n                                  </td>\n                                </React.Fragment>\n                            }\n\n                            <td className={`middle`}>\n                              {item.car?.entry ?? '-'}\n                            </td>\n                            <td className={`middle`}>\n                              {item.car?.invoice ?? '-'}\n                            </td>\n                            {\n                              slimView ?\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}<br />\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment> :\n                                <React.Fragment>\n                                  <td className={`middle`}>\n                                    {this.createdBy(item.request?.createdBy) ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.origin?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {item.destination?.name ?? '-'}\n                                  </td>\n                                  <td className={`middle`}>\n                                    {moment(item.request?.createdAt).format('DD/MM/YY') ?? '-'}\n                                  </td>\n                                </React.Fragment>\n                            }\n                            <td className={`middle`}>\n                              <ShowIf condition={!!item.car?.vin?.trim()}>\n                                <a\n                                  className='btn btn-success btn-sm'\n                                  href={'javascript:void(0);'}\n                                  onClick={() => this.props.onClick(item)}\n                                >\n                                  <i className='fa fa-plus' /> Agregar\n                                </a>\n                              </ShowIf>\n                            </td>\n                          </tr>\n                        );\n                      })\n                  }\n                  </tbody>\n                </table>\n                </div>\n              </div>\n            </div>\n            {\n              requestItemsPagination.pages > 1 &&\n              <div className='row'>\n                <div className='col-md-6' style={{ padding: '20px 15px' }}>\n              <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                &nbsp;&nbsp;Mostrando registros del {(requestItemsPagination.page - 1) * 20 + 1} al {(requestItemsPagination.page) * 20} de {requestItemsPagination.count} registros.\n              </span>\n                </div>\n                <div className='col-md-6'>\n                  <div className='text-right' style={{ marginRight: '15px' }}>\n                    <Paginator changePage={this.changePage} page={requestItemsPagination.page} pages={requestItemsPagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n          </div>\n          {\n            requestItemsLoading &&\n            <div className='overlay' style={{\n              position: 'absolute',\n              top: 0,\n              left: 0,\n              height: '100%',\n              width: '100%',\n              zIndex: 50,\n              background: 'rgba(255,255,255,0.7)'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' style={{\n                position: 'absolute',\n                top: '50%',\n                left: '50%',\n                marginLeft: '-15px',\n                marginTop: '-15px',\n                color: '#000',\n                fontSize: '30px'\n              }} />\n            </div>\n          }\n        </div>\n      </div>\n    );\n  }\n\n  private createdBy(createdBy: IUser): string | null {\n    return createdBy ? `${createdBy.firstName} ${createdBy.lastName}` : null;\n  }\n\n  private getRequestItemDebounced() {\n    this.props.transmittalActions.getRequestItemThunkAction(1, false);\n  }\n\n  private changePage(page: number): void {\n    // window.scrollTo(0, 0);\n    this.props.transmittalActions.getRequestItemThunkAction(page);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IExternarlPropsType | any>(mapStateToProps, mapDispatchToProps)(SearchCarInRequests);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {Field, FieldArray, formValueSelector, InjectedFormProps, reduxForm} from 'redux-form';\nimport {ITransmittalState} from '../../../actions/transmittal.types';\nimport InputField from '../../Utils/forms/InputField';\nimport {inputStringRequired} from '../../Utils/forms/validations';\nimport MultiUploadFiles, {imageStatus} from \"../../Utils/MultiUploadFiles\";\nimport TransmittalActions from \"../../../actions/transmittal.actions\";\nimport tramittalRenderItem, {IRenderItemProps} from \"./renders/TramittalRenderItem\";\nimport BootstrapSelectField from \"../../Utils/forms/BootstrapSelectField\";\nimport ShowIf from '../../Utils/ShowIf';\nimport TextAreaField from \"../../Utils/forms/TextAreaField\";\n\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n  transmittal: ITransmittalState;\n  formValues: any;\n  transmittalActions: TransmittalActions\n}\n\ninterface IStateType {\n  filesCache: any[];\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    filesCache: [],\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentWillMount(): void {\n    this.props.transmittalActions.getFormBaseData();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {handleSubmit, valid, submitFailed, transmittal, formValues} = this.props;\n    const {filesCache} = this.state;\n    const filesCompleted = filesCache.filter((file: any) => file.status === imageStatus.complete);\n    const isUploadingFiles = filesCache.length > 0 && filesCompleted.length < filesCache.length;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"row\">\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.driver\"\n                  label=\"Chofer *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un chofer\",\n                    displayItems: 2,\n                    sm: true,\n                    selectedText: \"choferes seleccionadas.\",\n                    autoClouse: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.drivers.map((driver) => ({\n                        value: driver._id,\n                        text: `${driver.firstName} ${driver.lastName} - ${driver.company.name}`\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.driver', value)\n                  }}\n                >\n                </Field>\n              </div>\n              <div className=\"col-md-6\">\n                <Field\n                  name=\"transporter.carrier\"\n                  label=\"Transportista *\"\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                  props={{\n                    noneSelectedText: \"Selecciona un transportista\",\n                    displayItems: 2,\n                    selectedText: \"transportistas seleccionadas.\",\n                    autoClouse: true,\n                    sm: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...transmittal.carriers.map((carrier) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))\n                    ],\n                    onClick: (value: string) => this.props.autofill('transporter.carrier', value)\n                  }}\n                >\n                </Field>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-6\">\n            <Field\n              name=\"transporter.patent\"\n              label=\"Patente del camión\"\n              placeholder=\"ABCD12\"\n              type=\"text\"\n              component={InputField}\n              // validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-6'>\n            <Field\n              name='type'\n              label='Tipo de transporte *'\n              component={BootstrapSelectField}\n              validate={[inputStringRequired]}\n              props={{\n                noneSelectedText: 'Selecciona un tipo',\n                displayItems: 2,\n                selectedText: 'tipo seleccionad0.',\n                autoClouse: true,\n                sm: true,\n                allOption: false,\n                search: true,\n                options: [\n                  ...transmittal.milestoneTypes.map((milestoneType) => ({\n                    value: milestoneType._id,\n                    text: milestoneType.name\n                  }))\n                ],\n                onClick: (value: string) => this.props.autofill('type', value)\n              }}\n            >\n            </Field>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label className=\"control-label label-left\">Adjuntar Documentos</label>\n              <div>\n                <MultiUploadFiles\n                  url={'/api/v1/transmittals/upload-file/'}\n                  onChange={(files) => {\n                    this.setState({filesCache: files});\n                    this.props.autofill('files', files)\n                  }}\n                  files={filesCache}\n                />\n                <ShowIf condition={isUploadingFiles}>\n                  <p>\n                    Se están cargando sus archivos, llevamos {filesCompleted.length} de {filesCache.length} <i className=\"fa fa-spinner fa-spin\"/>.\n                  </p>\n                </ShowIf>\n              </div>\n            </div>\n          </div>\n          <div className=\"col-md-12 m-t-10\">\n            <h4>Unidades Cargadas ({formValues.items ? formValues.items.length : ''})</h4>\n          </div>\n          <FieldArray<IRenderItemProps>\n            name=\"items\"\n            component={tramittalRenderItem}\n            props={{\n              transmittal\n            }}\n          />\n          <div className=\"col-md-12 m-t-10\">\n            <Field\n              name={`observation`}\n              label=\"Observación\"\n              component={TextAreaField}\n              type=\"text\"\n              rows={4}\n              props={{\n                resize: 'none'\n              }}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger m-t-20\"\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst TransmittalForm = reduxForm({\n  form: 'transmittalForm'\n})(Form);\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'carrier', 'driver', 'files', 'items'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\nexport default connect<{ transmittal: ITransmittalState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(TransmittalForm);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { ITransmittalState } from '../../../../actions/transmittal.types';\nimport TransmittalActions from '../../../../actions/transmittal.actions';\nimport { connect } from 'react-redux';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport { IRequestItem } from '../../../../../../../../src/request/interfaces/requestItem.interface';\nimport InputField from '../../../Utils/forms/InputField';\nimport BootstrapSwitchField from '../../../Utils/forms/BootsrapSwitchField';\nimport ShowIf from '../../../Utils/ShowIf';\nimport AddItemsToTransmittal from '../AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../../src/app/interfaces/car.interface';\nimport SelectField from '../../../Utils/forms/SelectField';\n\n\nexport interface IRenderItemProps {\n  transmittal: ITransmittalState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  transmittalActions: TransmittalActions;\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  openTabs: string[];\n  oneOrigin: boolean;\n  oneDestination: boolean;\n}\n\nclass TramittalRenderItem extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    exporing: false,\n    openTabs: [],\n    oneOrigin: true,\n    oneDestination: true\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.toogleTab = this.toogleTab.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, transmittal } = this.props;\n    const { openTabs, oneOrigin, oneDestination } = this.state;\n    return (\n      <React.Fragment>\n        {\n          fields.length === 0 ?\n            <div className='col-md-12'>\n              <p\n                className='text-center text-muted'\n                style={{ padding: '20px 0' }}\n              >\n                No se han agregado unidades aún.\n              </p>\n            </div> :\n            <div className='col-md-12'>\n              <div className='table-responsive'>\n                <table className='table table-xs' style={{ minWidth: '1000px' }}>\n                <thead>\n                <tr className='bg-primary' style={{ height: '45px' }}>\n                  <th className='middle-center' style={{ width: '45px' }}>ID Sol.</th>\n                  <th className='middle' style={{ width: '120px' }}>VIN</th>\n                  <th className='middle'>Marca</th>\n                  <th className='middle'>Modelo</th>\n                  <th className='middle'>Color</th>\n                  <th className='middle' style={{ width: '100px' }}>Partida</th>\n                  <th className='middle' style={{ width: '100px' }}>Factura</th>\n                  <th className='middle' style={{ width: '150px' }}>Origen</th>\n                  <th className='middle' style={{ width: '150px' }}>Destino</th>\n                  <th className='middle' style={{ width: '40px' }} />\n                  <th className='middle' style={{ width: '28px' }} />\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  fields.map((item, index) => {\n                    const value: IRequestItem = fields.get(index) as IRequestItem;\n                    const openTab = openTabs.includes(value._id);\n                    return (\n                      <React.Fragment key={value._id}>\n                        <tr>\n                          <td className={`middle-center`}>\n                            <ShowIf condition={!!value?.request?.number}>\n                              #{this.padNumber(value.request?.number)}\n                            </ShowIf>\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.vin}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.brand}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.denomination}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.color}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.entry ?? '-'}\n                          </td>\n                          <td className={`middle`}>\n                            {value.car?.invoice ?? '-'}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.origin`}\n                              label='Origen *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'origenes seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                disabled: oneOrigin,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.origin`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.destination`}\n                              label='Origen *'\n                              component={SelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                labelOff: true,\n                                disabled: true\n                              }}\n                            >\n                              <option value={\"\"} disabled={true} >Seleccione</option>\n                              {\n                                transmittal.venues.map((venue) => (\n                                  <option key={venue._id} value={venue._id}>{venue.name}</option>\n                                ))\n                              }\n                            </Field>\n                            {/*<Field\n                              name={`${item}.destination`}\n                              label='Destino *'\n                              component={BootstrapSelectField}\n                              validate={[inputStringRequired]}\n                              props={{\n                                noneSelectedText: 'Seleccione...',\n                                displayItems: 2,\n                                selectedText: 'destinos seleccionados.',\n                                autoClouse: true,\n                                sm: true,\n                                right: true,\n                                disabled: oneDestination,\n                                labelOff: true,\n                                allOption: false,\n                                search: true,\n                                options: [\n                                  ...transmittal.venues.map((venue) => ({\n                                    value: venue._id,\n                                    text: venue.name\n                                  }))\n                                ],\n                                onClick: (value: string) => this.props.transmittalActions.autofill(`${item}.destination`, value)\n                              }}\n                            >\n                            </Field>*/}\n                          </td>\n                          <td className={`middle-center pointer`} onClick={() => this.toogleTab(value._id)}>\n                            {\n                              openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                            }\n                          </td>\n                          <td className={`middle`}>\n                            <button\n                              type='button'\n                              className='btn btn-sm btn-danger'\n                              onClick={() => fields.remove(index)}\n                            >\n                              <i className='fa fa-trash' />\n                            </button>\n                          </td>\n                        </tr>\n                        {\n                          openTab ?\n                            <tr style={{ borderTop: 'none' }}>\n                              <td colSpan={11} className={'b-t-0'}>\n                                <table className={'table'} style={{ marginBottom: 0 }}>\n                                  <thead>\n                                  <tr style={{ backgroundColor: '#f9f9f9' }}>\n                                    <th className={'middle width-20'}>Cliente</th>\n                                    <th className={'middle width-20'}>BL</th>\n                                    <th className={'middle width-20'}>Tipo</th>\n                                    <th className={'middle width-20'}>Tipo Operación (Motivo)</th>\n                                    <th className={'middle width-20'}>Observación</th>\n                                  </tr>\n                                  </thead>\n                                  <tbody>\n                                  <tr>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.client`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.car.bl`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                    <td className={'middle'}>{value.car?.type ?? '-'}</td>\n                                    <td className={'middle'}>{value.reason?.name ?? '-'}</td>\n                                    <td className={'middle form-group-no-margin'}>\n                                      <Field\n                                        name={`${item}.observation`}\n                                        type='text'\n                                        component={InputField}\n                                        props={{\n                                          labelOff: true\n                                        }}\n                                      />\n                                    </td>\n                                  </tr>\n                                  </tbody>\n                                </table>\n                              </td>\n                            </tr> : null\n                        }\n                      </React.Fragment>\n                    );\n                  })\n                }\n                <tr>\n                  <td colSpan={7} />\n                  <td colSpan={2}>\n                    <div className='flex flex-row'>\n                      <div className='flex-1' style={{ paddingRight: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneOrigin'\n                            label='Un solo origen'\n                            type='checkbox'\n                            checked={oneOrigin}\n                            component={BootstrapSwitchField}\n                            onChange={(e: any) => {\n                              const { checked } = e.target;\n                              if (!checked) {\n                                this.props.transmittalActions.autofill(`all.origin`, null);\n                              }\n                              this.setState({\n                                oneOrigin: checked\n                              });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.origin`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.origin`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                       {/* <Field\n                          name={`all.origin`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            sm: true,\n                            disabled: !oneOrigin,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.origin`, value);\n                                this.props.transmittalActions.autofill(`all.origin`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                      <div className='flex-1' style={{ paddingLeft: '3px' }}>\n                        <ShowIf condition={false}>\n                          <Field\n                            name='oneDestination'\n                            label='Un solo destino'\n                            type='checkbox'\n                            checked={oneDestination}\n                            component={BootstrapSwitchField}\n                            onChange={() => {\n                              // const { checked } = e.target;\n                              // if (!checked) {\n                              //   this.props.transmittalActions.autofill(`all.destination`, null);\n                              // }\n                              // this.setState({\n                              //   oneDestination: checked\n                              // });\n                            }}\n                            validate={[]}\n                          />\n                        </ShowIf>\n                        <Field\n                          name={`all.destination`}\n                          label=''\n                          component={SelectField}\n                          validate={[inputStringRequired]}\n                          props={{\n                            labelOff: true,\n                          }}\n                          input={{\n                            defaultValue:\"\",\n                            onChange: (e:any) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, e.target.value);\n                                this.props.transmittalActions.autofill(`all.destination`, e.target.value);\n                              });\n                            }\n                          }}\n                        >\n                          <option value={\"\"} disabled={true} >Seleccione</option>\n                          {\n                            transmittal.venues.map((venue) => (\n                              <option\n                                key={venue._id}\n                                value={venue._id}\n                              >\n                                {venue.name}\n                              </option>\n                            ))\n                          }\n                        </Field>\n                        {/*<Field\n                          name={`all.destination`}\n                          label=''\n                          component={BootstrapSelectField}\n                          props={{\n                            noneSelectedText: 'Seleccione...',\n                            displayItems: 2,\n                            selectedText: 'destinos seleccionados.',\n                            autoClouse: true,\n                            right: true,\n                            disabled: !oneDestination,\n                            sm: true,\n                            labelOff: true,\n                            allOption: false,\n                            search: true,\n                            options: [\n                              ...transmittal.venues.map((venue) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))\n                            ],\n                            onClick: (value: string) => {\n                              fields.forEach((item) => {\n                                this.props.transmittalActions.autofill(`${item}.destination`, value);\n                                this.props.transmittalActions.autofill(`all.destination`, value);\n                              });\n                            }\n                          }}\n                        >\n                        </Field>*/}\n                      </div>\n                    </div>\n                  </td>\n                </tr>\n\n                </tbody>\n              </table>\n              </div>\n            </div>\n        }\n        <div className='col-md-12' style={{ marginTop: '10px' }}>\n          <h4>Agregar Unidades</h4>\n        </div>\n        <div className='col-md-12'>\n          <AddItemsToTransmittal fields={fields} onClickRequest={this.pushItem} onClickCar={this.pushItemCar} />\n        </div>\n        {submitFailed && error && <span>{error}</span>}\n      </React.Fragment>\n    );\n  }\n\n  private pushItemCar(car: ICar) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: car._id,\n      car: car,\n      type: 'car',\n      request: null,\n      // reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private pushItem(item: IRequestItem) {\n    const { formValues } = this.props;\n    this.props.transmittalActions.pushItem({\n      _id: item._id,\n      type: 'request',\n      car: {\n        ...item.car,\n        bl: item.car.bl ?? '',\n        client: item.car.client ?? ''\n      },\n      request: item.request,\n      reason: item.reason,\n      origin: formValues?.all?.origin,\n      // destination: formValues?.all?.destination ?? item.destination?._id\n      destination: formValues?.all?.destination\n    });\n  }\n\n  private toogleTab(id: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(id)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== id)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, id]\n      });\n    }\n  }\n\n  private padNumber(n: number): string {\n    const s = '000' + n;\n    return s.substr(s.length - 4);\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('transmittalForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRenderItemProps>(mapStateToProps, mapDispatchToProps)(TramittalRenderItem);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalModel } from '../../../../../../../src/distribution/models/transmittal.model';\nimport TransmitalListItem from './TransmittalListItem';\nimport ShowIf from '../../Utils/ShowIf';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\nimport { goToSection, hasPermission } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport UploadTransmittalFile from './UploadTransmittalFile';\nimport AddItemsToTransmittal from '../TransmittalForms/AddItemsToTransmittal';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { debounce } from 'throttle-debounce';\nimport {IMilestone} from \"../../../../../../../src/distribution/interfaces/milestone.interface\";\nimport {ChoicesStatusTransmittal} from \"../../../../../../../src/distribution/models/transmitall.types\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittalModel;\n  evidenceMilestones: IMilestone[];\n  transmittalActions: TransmittalActions;\n  getParticipant(id: string): void;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListDetail extends React.Component<IPropsType, IStateType> {\n\n  private readonly api: ApiService;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.openDialogAddCar = this.openDialogAddCar.bind(this);\n    this.pushItem = this.pushItem.bind(this);\n    this.pushItemCar = this.pushItemCar.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.debouncedUpdateTransmittalThunkAction = debounce(2000, this.debouncedUpdateTransmittalThunkAction.bind(this));\n    this.api = new ApiService();\n  }\n\n  componentDidMount() {\n    const { location: { query } } = this.props.router;\n    if (query?.transmittal?.length) {\n      this.props.transmittalActions.toogleTab(query.transmittal, true);\n      if (query?.item?.length) {\n        const key = `transmittal-item-${query.item}`;\n        setTimeout(() => {\n          const element = document.getElementById(key);\n          if (element) {\n            element.style.backgroundColor = '#efefef';\n            // element?.classList.add('bg-gray-light');\n            element?.classList.add('text-black');\n            goToSection(`#${key}`);\n          } else {\n            console.log(`No se encontro el elemento ${key}`);\n          }\n        }, 100);\n      }\n    }\n  }\n\n  private debouncedUpdateTransmittalThunkAction(transmittal: any){\n    this.props.transmittalActions.updateTransmittalThunkAction(transmittal)\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item: transmittal, transmittalActions, evidenceMilestones } = this.props;\n    const { carriers, drivers, milestoneTypes } = this.props.transmittal;\n    const open = this.props.transmittal.transmittalOpen.includes(transmittal._id);\n    return (\n      <React.Fragment>\n        <div id={`transmittal-${transmittal._id}`} className='row transmittal bg-transmittal-title background-transition pointer'>\n          <div\n            onClick={() => transmittalActions.toogleTab(transmittal._id)}\n            className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center head-sorted'\n          >\n            <strong className='text-underline'>#{this.padNumber(transmittal.number)}</strong>&nbsp;\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <input\n                    className='form-control input-sm'\n                    defaultValue={transmittal.transporter?.patent}\n                    onChange={(e) => {\n                      this.debouncedUpdateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.patent': e.target.value\n                      });\n                    }}\n                  />\n                ) :\n                (\n                  `${transmittal.transporter?.patent}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.driver?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      drivers.map((driver) => (\n                        <option key={driver._id} value={driver._id}>{`${driver.firstName} ${driver.lastName}`}</option>\n                      ))\n                    }\n                  </select>\n                  /*<BootstrapSelect\n                    noneSelectedText='Selecciona un chófer'\n                    displayItems={2}\n                    sm={true}\n                    selectedText='choferes seleccionadas.'\n                    selected={transmittal.transporter.driver ? [transmittal.transporter.driver._id] : []}\n                    autoClouse={true}\n                    allOption={false}\n                    search={true}\n                    options={drivers.map((driver: any) => ({\n                      value: driver._id,\n                      text: `${driver.firstName} ${driver.lastName}`\n                    }))}\n                    onClick={(e: string) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.driver': e\n                      });\n                    }}\n                  />*/\n                ) :\n                (\n                  `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}`\n                )\n            }\n            {/*{transmittal.transporter.driver._id}*/}\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' style={{ position: 'static' }}>\n            {\n              hasPermission(window.user, 'changeTransmittal') ?\n                (\n                  <select\n                    className='form-control select-sm font-12' value={transmittal.transporter.carrier?._id ?? ''}\n                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                      this.props.transmittalActions.updateTransmittalThunkAction({\n                        _id: transmittal._id,\n                        'transporter.carrier': e.target.value\n                      });\n                    }}\n                  >\n                    {/*<option value='' disabled={true}>-</option>*/}\n                    {\n                      carriers.map((carrier) => (\n                        <option key={carrier._id} value={carrier._id}>{`${carrier.name}`}</option>\n                      ))\n                    }\n                  </select>\n                ) :\n                (\n                  `${transmittal.transporter.carrier.name}`\n                )\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 text-sm text-muted'>\n            {transmittal.items.length} unidades.\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            <div className='flex-45 col-sm-8 col-xs-8 col-md-8 col-lg-8' style={{ position: 'static' }}>\n              {\n                hasPermission(window.user, 'changeTransmittal') ?\n                  (\n                    <select\n                      className='form-control select-sm font-12' value={transmittal.type?._id ?? ''}\n                      onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          'type': e.target.value\n                        });\n                      }}\n                    >\n                      <option value='' disabled={true}>-</option>\n                      {\n                        milestoneTypes.map((milestoneType) => (\n                          <option key={milestoneType._id} value={milestoneType._id}>{`${milestoneType.name}`}</option>\n                        ))\n                      }\n                    </select>\n                    /*<BootstrapSelect\n                      noneSelectedText='Selecciona un transportista'\n                      displayItems={2}\n                      sm={true}\n                      selectedText='transportistas seleccionadas.'\n                      selected={transmittal.transporter.carrier ? [transmittal.transporter.carrier._id] : []}\n                      autoClouse={true}\n                      allOption={false}\n                      search={true}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(e: string) => {\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          'transporter.carrier': e\n                        });\n                      }}\n                    />*/\n                  ) :\n                  (\n                    `${transmittal.type?.name}`\n                  )\n              }\n\n            </div>\n            <div className='flex-45 col-sm-4 col-xs-4 col-md-4 col-lg-4'>\n              <UploadTransmittalFile transmittal={transmittal} />\n              <ShowIf condition={transmittal.files.length >= 1}>\n                <button\n                  className='btn btn-xs btn-default'\n                  onClick={() => this.downloadFiles(transmittal)}\n                >\n                  <i\n                    className='fa fa-paperclip'\n                    data-toggle='tooltip'\n                    data-placement='top'\n                    title={`${transmittal.files.length} archivos adjuntos.`}\n                  /> {`(${transmittal.files.length})`}\n                </button>\n              </ShowIf>\n            </div>\n          </div>\n          {\n            evidenceMilestones.map((milestone: IMilestone, index: number) => {\n              let tmp = transmittal.evidenceFullLoad.filter(e => {\n                if (e.milestone != undefined) {\n                  let is_in: Boolean = evidenceMilestones.filter(em => em._id == e.milestone).length > 0;\n                  return is_in ? e.milestone == milestone._id : index == 0;\n                } else\n                  return index == 0;\n              });\n              return (\n                <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 text-center' key={`${transmittal._id}-${milestone._id}`}>\n                  {\n                    tmp.map((image: any, index: number) => (\n                      <div\n                        key={`${transmittal._id}-${index}${image._id}`}\n                        className={'text-center'} style={{ display: index === 0 ? '' : 'none' }}\n                      >\n                        <a href={decodeURI(image.file.url)}\n                           data-toggle='lightbox'\n                           data-gallery={`${transmittal._id}-${milestone._id}`}\n                           data-title={`#${this.padNumber(transmittal.number)}`}\n                           data-footer={`Conductor ${transmittal.transporter.driver ? `${transmittal.transporter.driver.firstName} ${transmittal.transporter.driver.lastName}` : ''} (${transmittal.transporter?.patent})`}\n                        >\n                          <button className='btn btn-xs btn-default'>\n                            <i className='fa fa-fw fa-image' /> {tmp.length}\n                          </button>\n                        </a>\n                      </div>\n                    ))\n                  }\n                </div>\n              );\n            })\n          }\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              transmittal?.passBorder ?\n                <i className='fa fa-flag' style={{paddingLeft: '5px'}}/> :\n                null\n            }\n          </div>\n          <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            {\n              transmittal?.revision || [ChoicesStatusTransmittal.completed_by_reception.toString(), ChoicesStatusTransmittal.completed.toString()].includes(transmittal?.status) ?\n                this.statusIcon(transmittal.revision, transmittal.status) :\n                null\n            }\n          </div>\n          <div\n            className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 chevron pointer'\n            onClick={() => transmittalActions.toogleTab(transmittal._id)}\n          >\n            {\n              open ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n            }\n          </div>\n        </div>\n        <ShowIf condition={open}>\n          <div className='table-transmittal'>\n            <table className='table table-striped table-hover m-0 table-xs'>\n              <thead>\n              <tr style={{ backgroundColor: '#f9f9f9' }}>\n                <th className='middle' style={{ width: '80px' }}>SOL</th>\n                <th className='middle' style={{ width: '145px' }}>VIN</th>\n                <th className='middle' style={{ minWidth: '100px' }}>Descripción</th>\n                <th className='middle' style={{ width: '80px' }}>Factura</th>\n                <th className='middle' style={{ width: '80px' }}>Partida</th>\n                <th className='middle' style={{ width: '80px' }}>BL</th>\n                <th className='middle' style={{ width: '100px' }}>Origen</th>\n                <th className='middle' style={{ width: '100px' }}>Destino</th>\n                <th className='middle' style={{ width: '105px' }}>Fecha emisión</th>\n                <th className='middle' style={{ width: '105px' }}>Fecha arribo</th>\n                <th className='middle' style={{ width: '20px' }}></th>\n                <th className='middle-center' style={{ width: '40px' }}>Cargado</th>\n                <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n                  <th className='middle' style={{ width: '30px' }} />\n                </ShowIf>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                transmittal.items.map((transmittalItem, index) => (\n                  <TransmitalListItem\n                    history={this.props.history}\n                    item={transmittal}\n                    transmittalItem={transmittalItem}\n                    key={`${index}${transmittalItem._id}`}\n                  />\n                ))\n              }\n              <ShowIf condition={false && transmittal.items.length > 1}>\n                <tr className='no-striped'>\n                  <td colSpan={8} className='middle text-right'>\n                    {/*Masivo*/}\n                  </td>\n                  <td className='middle'>\n                    <DateRangePicker\n                      className={'input-sm'}\n                      value={''}\n                      format={'DD-MM-YY'}\n                      onChange={(e) => {\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          allLoadingDate: e?.toDate() ?? ''\n                        });\n                      }}\n                    />\n                  </td>\n                  <td className='middle'>\n                    <DateRangePicker\n                      className={'input-sm'}\n                      value={''}\n                      format={'DD-MM-YY'}\n                      onChange={(e) => {\n                        // allArrivalDate\n                        this.props.transmittalActions.updateTransmittalThunkAction({\n                          _id: transmittal._id,\n                          allArrivalDate: e?.toDate() ?? ''\n                        });\n                      }}\n                    />\n                  </td>\n                </tr>\n              </ShowIf>\n              </tbody>\n            </table>\n            <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n              <div className='row'>\n                <div className='col-md-12 text-right m-b-10 m-t-10'>\n                  <button className='btn btn-sm btn-success' onClick={this.openDialogAddCar}>\n                    <i className='fa fa-fw fa-plus-square' /> Cargar vehículo\n                  </button>\n                </div>\n              </div>\n            </ShowIf>\n          </div>\n        </ShowIf>\n      </React.Fragment>\n    );\n  }\n\n  private statusIcon(revision: IParticipant, status: string) {\n    if (revision && revision.hasDamages) {\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-warning text-red' />\n        </button>\n      );\n    } else {\n      if (status === ChoicesStatusTransmittal.completed_by_reception)\n        return (\n\n            <i className='fa fa-ban text-warning' style={{paddingLeft: '5px'}}/>\n\n        );\n      return (\n        <button\n          className='btn btn-xs btn-default'\n          data-toggle='tooltip'\n          data-placement='top'\n          title={`Ver detalle`}\n          onClick={() => this.props.getParticipant(revision._id)}\n        >\n          <i className='fa fa-check-circle text-primary' />\n        </button>\n      );\n    }\n  }\n\n  private openDialogAddCar() {\n    const { item: transmittal } = this.props;\n    this.props.loadDataAction(\n      `Agregar vehículo a orden #${this.padNumber(transmittal.number)}`,\n      <AddItemsToTransmittal onClickRequest={this.pushItem} onClickCar={this.pushItemCar} slimView={true} />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cerrar</button>\n      </React.Fragment>\n    );\n  }\n\n  private downloadFiles(transmittal: ITransmittalModel) {\n    window.open(`/transmittals/${transmittal._id}/download-files/`, '_blank');\n  }\n\n  private pushItemCar(car: ICar) {\n    const { item: transmittal } = this.props;\n    this.api.addTransmittalItem({\n      requestItem: null,\n      car: car._id,\n      request: null,\n      // origin: requestItem.origin?._id,\n      // destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private pushItem(requestItem: IRequestItem) {\n    const { item: transmittal } = this.props;\n    this.props.transmittalActions.loadingRequestItemAction(true);\n    this.api.addTransmittalItem({\n      requestItem: requestItem._id,\n      car: requestItem.car._id,\n      request: requestItem.request._id,\n      origin: requestItem.origin?._id,\n      destination: requestItem.destination?._id,\n      transmittal: transmittal._id\n    })\n      .then((): void => {})\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private padNumber(n: number): string {\n    const s = '' + n;\n    return s.substr(0, 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  return {\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListDetail);\n","import * as React from 'react';\nimport { Dispatch } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport * as moment from 'moment-timezone';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport { ITransmittalItem } from '../../../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport ShowIf from '../../Utils/ShowIf';\nimport * as swal from 'sweetalert';\nimport ApiService from '../../../utils/axios';\nimport CopyText from '../../Utils/CopyText';\nimport { ITransmittal } from '../../../../../../../src/distribution/interfaces/transmittal.interface';\nimport { IParticipant } from '../../../../../../../src/form/interfaces/participant.interface';\nimport { getParticipant } from '../../../actions/dashboard.actions';\nimport { debounce } from 'throttle-debounce';\nimport { goToSection, hasPermission, parseReplicableURL } from '../../../utils/common';\nimport { IWindow } from '../../../interfaces/window';\nimport TransmittalStatusDislay from '../../Request/StatusComponents/TransmittalStatusDislay';\nimport RequestStatusDislay from '../../Request/StatusComponents/RequestStatusDislay';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  item: ITransmittal;\n  transmittalItem: ITransmittalItem;\n  transmittalActions: TransmittalActions;\n\n  getParticipant(id: string): void;\n}\n\ntype RecursivePartial<T> = {\n  [P in keyof T]?: RecursivePartial<T[P]>;\n};\n\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass TransmitalListItem extends React.Component<IPropsType, IStateType> {\n  private api: ApiService;\n  title: string;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.delete = this.delete.bind(this);\n    this.statusIcon = this.statusIcon.bind(this);\n    this.debounceUpdateTransmittalItem = debounce(300, this.debounceUpdateTransmittalItem);\n    this.api = new ApiService();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { transmittalItem, transmittal: { venues } } = this.props;\n    return (\n      <tr id={`transmittal-item-${transmittalItem._id}`} className='background-transition'>\n        <td\n          className={'middle pointer'}\n          onClick={transmittalItem.request?._id ? () => {\n            this.props.history.push(parseReplicableURL(`/requests/vehicles/${transmittalItem.request?._id}?item=${transmittalItem.requestItem._id}`, ['item']));\n          } : undefined}\n        >\n          <RequestStatusDislay requestItem={transmittalItem.requestItem} showNumber={true} />\n          {/*<TransmittalStatusDislay transmittal={transmittalItem.transmittal} showNumber={false} />*/}\n          {/*<strong className=\"text-underline\">*/}\n          {/*  <ShowIf condition={!!transmittalItem?.request?.number}>*/}\n          {/*    #{transmittalItem.request?.number}*/}\n          {/*  </ShowIf>*/}\n          {/*</strong>*/}\n        </td>\n        <td\n          className={'middle text-primary'}\n        >\n          <CopyText value={transmittalItem.car.vin}>\n            <strong\n              className={'text-underline pointer'}\n              onClick={()=>{this.props.history.push(`/settings/cars/${transmittalItem.car._id}/`)}}\n            >\n              {transmittalItem.car.vin}\n            </strong>\n          </CopyText>\n        </td>\n        <td className={'middle'}>\n          <strong className={\"text-muted\"}>{transmittalItem.car.brand}</strong><br />\n          <span className={\"text-muted\"}>{transmittalItem.car.denomination}</span><br />\n          <span className={\"text-info\"}>{transmittalItem.car.color}</span>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.invoice}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.invoice}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    invoice: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.entry}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.entry}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    entry: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle-center'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.car.bl}>\n            <input\n              type='text'\n              className='form-control input-sm'\n              defaultValue={transmittalItem.car.bl}\n              onChange={(e) => {\n                this.debounceUpdateTransmittalItem({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  car: {\n                    _id: transmittalItem.car._id,\n                    bl: e.target.value\n                  }\n                });\n              }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.origin?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.origin?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  origin: e.target.value\n                });\n              }}\n            >\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf condition={hasPermission(window.user, 'changeTransmittal')} alternative={transmittalItem.destination?.name}>\n            <select\n              className='form-control select-sm font-12' value={transmittalItem.destination?._id ?? ''}\n              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                this.props.transmittalActions.updateTransmittalItemThunkAction({\n                  _id: transmittalItem._id,\n                  transmittal: transmittalItem.transmittal,\n                  destination: e.target.value\n                });\n              }}\n            >\n              {\n                venues.map((venue) => (\n                  <option key={venue._id} value={venue._id}>{`${venue.name}`}</option>\n                ))\n              }\n            </select>\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.loadingDate ? moment(transmittalItem.loadingDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.loadingDate}\n              format={'DD-MM-YY'}\n              disabled={true}\n              // onChange={(e) => {\n              //   this.props.transmittalActions.updateTransmittalItemThunkAction({\n              //     _id: transmittalItem._id,\n              //     transmittal: transmittalItem.transmittal,\n              //     loadingDate: e?.toDate() ?? ''\n              //   });\n              // }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          <ShowIf\n            condition={hasPermission(window.user, 'changeTransmittal')}\n            alternative={transmittalItem.arrivalDate ? moment(transmittalItem.arrivalDate).format('DD-MM-YYYY') : '-'}\n          >\n            <DateRangePicker\n              className={'input-sm'}\n              value={transmittalItem.arrivalDate}\n              format={'DD-MM-YY'}\n              disabled={true}\n              // onChange={(e) => {\n              //   this.props.transmittalActions.updateTransmittalItemThunkAction({\n              //     _id: transmittalItem._id,\n              //     transmittal: transmittalItem.transmittal,\n              //     arrivalDate: e?.toDate() ?? ''\n              //   });\n              // }}\n            />\n          </ShowIf>\n        </td>\n        <td className={'middle'}>\n          {/*<ShowIf*/}\n          {/*  condition={hasPermission(window.user, 'changeTransmittal')}*/}\n          {/*  alternative={transmittalItem.observation ?? '-'}*/}\n          {/*>*/}\n          {/*  <input*/}\n          {/*    className='form-control input-sm'*/}\n          {/*    defaultValue={transmittalItem.observation}*/}\n          {/*    onChange={(e) => {*/}\n          {/*      this.debounceUpdateTransmittalItem({*/}\n          {/*        _id: transmittalItem._id,*/}\n          {/*        transmittal: transmittalItem.transmittal,*/}\n          {/*        observation: e.target.value*/}\n          {/*      });*/}\n          {/*    }}*/}\n          {/*  />*/}\n          {/*</ShowIf>*/}\n        </td>\n        {\n          transmittalItem.revisions.length ?\n            this.statusIcon(transmittalItem.revisions[0]) :\n            <td className={'middle'} />\n        }\n        <ShowIf condition={hasPermission(window.user, 'changeTransmittal')}>\n          <td className='middle-center text-red pointer' onClick={this.delete}>\n            <i className='fa fa-minus-circle' />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  private debounceUpdateTransmittalItem(transmittalItem: any) {\n    this.props.transmittalActions.updateTransmittalItemThunkAction(transmittalItem);\n  }\n\n  private statusIcon(revision: IParticipant) {\n    if (revision.hasDamages) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-warning text-red' />\n        </td>\n      );\n    } else if (revision.receptionConfirmation) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-check-circle text-primary' />\n        </td>\n      );\n    } else if (!revision.receptionConfirmation) {\n      return (\n        <td className={'middle-center pointer'} onClick={() => this.props.getParticipant(revision._id)}>\n          <i className='fa fa-close text-danger' />\n        </td>\n      );\n    }\n    return <td className={'middle'} />;\n  }\n\n  private delete() {\n    const { transmittalItem } = this.props;\n    const { item: transmittal } = this.props;\n    swal!({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar ${transmittalItem.car.brand} ${transmittalItem.car.denomination}, de la orden ${this.padNumber(transmittal.number)}.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        const { transmittalItem } = this.props;\n        this.api.deleteTransmittalItem(transmittalItem);\n      }\n    });\n  }\n\n  private padNumber(n: number): string {\n    const s = '0000' + n;\n    return s.substr(s.length - 5);\n  }\n\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState, router: any }) => {\n  return {\n    transmittal: state.transmittal,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions,\n    getParticipant: (id: string) => dispatch(getParticipant(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(TransmitalListItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as moment from 'moment-timezone';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport TransmittalActions from '../../../actions/transmittal.actions';\nimport { ITransmittalActionTypes, ITransmittalState } from '../../../actions/transmittal.types';\nimport TransmitalListDetail from './TransmitalListDetail';\nimport { Dispatch } from 'redux';\nimport ModalView from '../../Modal/ModalView';\nimport { debounce } from 'throttle-debounce';\nimport {IMilestone} from '../../../../../../../src/distribution/interfaces/milestone.interface';\nimport {IMilestoneType} from '../../../../../../../src/distribution/interfaces/milestoneType.interface';\nimport DateRangeInput from \"../../Utils/DateRangeInput\";\nimport {IUser} from \"../../../../../../../src/app/interfaces/user.interface\";\nimport BootstrapSelect from \"../../Utils/BootstrapSelect\";\nimport {IForm} from \"../../../../../../../src/form/interfaces/form.interface\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<ITransmittalActionTypes>;\n  transmittal: ITransmittalState;\n  transmittalActions: TransmittalActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  number: string | undefined;\n  drivers: string[] | undefined;\n  driverText: string | undefined;\n  types: string[] | undefined;\n  from: Date;\n  to: Date;\n}\n\ndeclare let window: IWindow;\n\nclass TransmittalListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state : IStateType = {\n    error: null,\n    exporing: false,\n    number: \"\",\n    drivers: [],\n    types: [],\n    driverText: '',\n    from: moment().startOf('month').toDate(),\n    to: moment().endOf('month').toDate(),\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Transporte';\n    this.create = this.create.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeNumber = this.changeNumber.bind(this);\n    this.changeDriver = this.changeDriver.bind(this);\n    this.changePeriod = this.changePeriod.bind(this);\n    this.changeTypes = this.changeTypes.bind(this);\n    this.callChangeFilterData = debounce(1000, this.callChangeFilterData.bind(this));\n  }\n\n  getDateRangeOptions(): daterangepicker.Options {\n    return {\n      // startDate: moment().subtract(11, 'months').startOf('month').toDate(),\n      // endDate: moment().toDate(),\n      maxDate: moment().toDate(),\n      locale: {\n        format: 'DD/MM/YYYY',\n        customRangeLabel: 'Período personalizado',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      ranges: {\n        \"Este mes\": [moment().startOf('month').toDate(), moment().endOf('month').toDate()],\n        \"Últimos 3 meses\": [moment().startOf('month').subtract(3, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n      },\n      opens: 'left'\n    };\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, data, options: { orderBy, orderType }, milestones, milestoneTypes\n    } = this.props.transmittal;\n\n    let longestMilestones: IMilestone[] = [];\n\n    for (let mType of milestoneTypes) {\n      let tmp = milestones\n        .filter(m => m.type === mType._id && m.step === 'loadEvidence');\n      if (tmp.length > longestMilestones.length)\n        longestMilestones = tmp.sort((a, b) => a.order - b.order);\n    }\n\n    const { exporing, number, driverText, from, to, types } = this.state;\n\n    return (\n      <AppContainer title={''\n        /*<div\n          className='input-group input-group-sm'\n          style={{ width: '80%' }}\n        >\n          <input\n            type='text'\n            className='form-control pull-right'\n            onChange={(e) => {\n              this.changeNumber(e.target.value);\n            }}\n            value={number}\n            placeholder='Buscar OT por número ej: 1686' />\n          <div className='input-group-btn'>\n            <button\n              className={`btn ${!!this.state.number?.length ? 'btn-primary' : 'btn-default'}`}\n              onClick={!!this.state.number?.length ? () => {\n                this.props.history.replace(`/transmittals/`);\n                this.changeNumber('');\n              }: undefined}\n            >\n              <ShowIf condition={!!this.state.number?.length} alternative={<i className='fa fa-search' />}>\n                <i className='fa fa-close' />\n              </ShowIf>\n            </button>\n          </div>\n        </div>*/\n      } cMenu='3' cSubMenu='3.4'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Transportes <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                {\n                  hasPermission(window.user, 'addTransmittal') ?\n                    <button className='btn btn-sm btn-success' onClick={this.create}>\n                      <i className='fa fa-fw fa-plus' /> Crear orden de transporte\n                    </button>\n                    : null\n                }\n                <ShowIf condition={data.length > 0}>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs'\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                    style={{ marginLeft: '5px' }}\n                  >\n                    {\n                      exporing ? <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment>\n                        : <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className={`box-body transmittal-list no-padding`}>\n              <div style={{padding: '10px'}}>\n                <div className='row'>\n                  <div className='col-md-3'>\n                    <div\n                      className='input-group input-group-sm'\n                      style={{padding: '10px'}}\n                    >\n                      <input\n                        type='text'\n                        className='form-control pull-right'\n                        onChange={(e) => {\n                          this.changeNumber(e.target.value);\n                        }}\n                        value={number}\n                        placeholder='Buscar OT por número ej: 1686' />\n                      <div className='input-group-btn'>\n                        <button\n                          className={`btn ${!!this.state.number?.length ? 'btn-primary' : 'btn-default'}`}\n                          onClick={!!this.state.number?.length ? () => {\n                            this.props.history.replace(`/transmittals/`);\n                            this.changeNumber('');\n                          } : undefined}\n                        >\n                          <ShowIf condition={!!this.state.number?.length} alternative={<i className='fa fa-search' />}>\n                            <i className='fa fa-close' />\n                          </ShowIf>\n                        </button>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-3'>\n                    <div\n                      className='input-group input-group-sm'\n                      style={{padding: '10px'}}\n                    >\n                      <input\n                        type='text'\n                        className='form-control pull-right'\n                        onChange={(e) => {\n                          this.changeDriver(e.target.value);\n                        }}\n                        value={driverText}\n                        placeholder='Chofer o Placa' />\n                      <div className='input-group-btn'>\n                        <button\n                          className={`btn ${!!this.state.driverText?.length ? 'btn-primary' : 'btn-default'}`}\n                          onClick={!!this.state.driverText?.length ? () => {\n                            this.props.history.replace(`/transmittals/`);\n                            this.changeDriver('');\n                          } : undefined}\n                        >\n                          <ShowIf condition={!!this.state.driverText?.length} alternative={<i className='fa fa-search' />}>\n                            <i className='fa fa-close' />\n                          </ShowIf>\n                        </button>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-3 no-padding'>\n                    <div style={{ padding: '10px' }}>\n                      <BootstrapSelect\n                        noneSelectedText='Todos los tipos de ruta'\n                        displayItems={4}\n                        sm={true}\n                        autoClouse={true}\n                        selectedText='Tipos de ruta seleccionadas.'\n                        selected={types ?? []}\n                        separator=\" - \"\n                        options={this.props.transmittal.milestoneTypes.map((type: IMilestoneType) => ({\n                          value: type._id,\n                          text: type.name\n                        }))}\n                        onClick={this.changeTypes}\n                        notHideOnClickOutside={false}\n                      />\n                    </div>\n                  </div>\n                  <div className='col-md-3 no-padding'>\n                    <div style={{padding: '10px'}}>\n                      <DateRangeInput\n                        options={this.getDateRangeOptions()}\n                        onChange={this.changePeriod}\n                        startDate={from}\n                        endDate={to}\n                      />\n                    </div>\n                  </div>\n              </div>\n              </div>\n              <div className='table-responsive'>\n                <ShowIf condition={data.length > 0}>\n                  <>\n                    <div className='row transmittal bg-primary'>\n                      <div\n                        className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 center pointer head-sorted'\n                        onClick={() => this.changeOrder('_id')}\n                      >\n                        <strong>OT Nº</strong> <i\n                        className={`fa ${orderBy === '_id' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Placa</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Chofer</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Transportista</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <strong>Carga</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                        <div className='flex-45 col-sm-8 col-xs-8 col-md-8 col-lg-8'>\n                          <strong>Tipo</strong>\n                        </div>\n                        <div className='flex-45 col-sm-4 col-xs-4 col-md-4 col-lg-4'>\n                          <strong>Docs</strong>\n                        </div>\n                      </div>\n                      {\n                        longestMilestones.map((milestone: IMilestone, index) => {\n                          return (\n                              <div\n                                className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 text-center no-padding'\n                                key={`${index}${milestone._id}`}>\n                              <strong>{milestone.name.replace('Evidencia', '').toUpperCase()}</strong>\n                            </div>\n                          )\n                        })\n                      }\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 no-padding'>\n                        <strong>FRONTERA</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1 no-padding'>\n                        <strong>DESCARGA</strong>\n                      </div>\n                      <div className='flex-45 col-sm-1 col-xs-1 col-md-1 col-lg-1' />\n                    </div>\n                    {\n                      data.map((item: any, index) => (\n                        <TransmitalListDetail\n                          router={this.props.router}\n                          history={this.props.history}\n                          item={item}\n                          evidenceMilestones={longestMilestones}\n                          key={`${index}${item._id}`}\n                        />\n                      ))\n                    }\n                  </>\n                </ShowIf>\n                <ShowIf condition={!loading && data.length === 0}>\n                  <div className='row'>\n                    <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                      <ImageLazyLoad\n                        url='/images/not_found.png'\n                        height={'200px'}\n                        style={{\n                          opacity: 0.5,\n                          maxHeight: '200px',\n                          marginBottom: '10px'\n                        }}\n                        replaceLoading={<i\n                          className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                          style={{ padding: '30px' }}\n                        />}\n                      /><br />\n                      <strong>No hay información para mostrar</strong>\n                    </div>\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                    <span className='react-bootstrap-table-pagination-total text-muted text-ellipsis'>\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              data.length === 0 && loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView modalLarge={true} />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.transmittal.options;\n    const { page } = this.props.transmittal.pagination;\n    const { location: { query } } = this.props.router;\n    const { transmittalActions } = this.props;\n    const state : IStateType = this.state;\n    window.scrollTo(0, 0);\n    const { number } = query;\n    this.setState({ number });\n    transmittalActions.getTransmittalsThunkAction({\n      nextPage: number ? 1 : page,\n      orderBy,\n      orderType,\n      number,\n      plate: state.driverText,\n      drivers: state.drivers,\n      types: state.types,\n      from: moment(state.from).unix(),\n      to: moment(state.to).unix(),\n    });\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {\n        room: `transmittal-list-${window.user.team._id}`\n      });\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.createTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 300);\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL_ITEM', (data: any): void => {\n      transmittalActions.updateTransmittalItemAction(data.transmittalItem);\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('UPDATE_TRANSMITTAL', (data: any): void => {\n      transmittalActions.updateTransmittalAction(data.transmittal);\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL_ITEM', (data: any): void => {\n      const $item = $(`#transmittal-item-${data.transmittalItem._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalItemAction(data.transmittalItem);\n      }, 300);\n    });\n\n    this.socket.on('DELETE_TRANSMITTAL', (data: any): void => {\n      const $item = $(`#transmittal-${data.transmittal._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        transmittalActions.deleteTransmittalAction(data.transmittal);\n        const { orderBy, orderType } = this.props.transmittal.options;\n        const { page } = this.props.transmittal.pagination;\n        const {from, to } = this.state;\n        transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true, from: moment(from).unix(), to: moment(to).unix() });\n      }, 300);\n    });\n\n    this.socket.on('CREATE_TRANSMITTAL', (): void => {\n      const { page } = this.props.transmittal.pagination;\n      const { orderBy, orderType } = this.props.transmittal.options;\n      const {from, to } = this.state;\n      transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, hideLoading: true, from: moment(from).unix(), to: moment(to).unix() });\n    });\n\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    // window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.transmittal.source) {\n      this.props.transmittal.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `distribution-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private changeNumber(number: string) {\n    if (!number.trim())\n      return\n\n    this.setState({ number }, () => {\n      this.callChangeFilterData();\n    });\n  }\n\n  private changeTypes(value: any) {\n    let { types } = this.state;\n    let sTypes = types || [];\n\n    types = sTypes.includes(value)\n      ? sTypes.filter((type) => type !== value)\n      : [value, ...sTypes];\n\n    this.setState({\n      types: types\n    }, () => {\n      this.callChangeFilterData();\n    });\n  }\n\n  private changeDriver(driver: string) {\n    let drivers = []\n    if (driver.trim()) {\n      let driverNames = driver.split(\",\").map(n => n.toLowerCase().replace(/\\s\\s+/g, ' ').trim())\n      drivers = this.props.transmittal.drivers.filter((user: IUser) => {\n        let fullName = `${user.firstName} ${user.lastName}`.toLowerCase()\n        return fullName === driver || driverNames.filter((name: string) => fullName.includes(name)).length > 0\n      }).map((user: IUser) => user._id);\n    } else {\n      return\n    }\n\n    this.setState({ driverText: driver, drivers }, () => {\n      this.callChangeFilterData();\n    });\n  }\n\n  private changePeriod(from: Date, to: Date) {\n    this.setState({ from, to }, () => {\n      this.callChangeFilterData();\n    });\n  }\n\n  private callChangeFilterData() {\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    let {drivers, driverText, from, to, number, types} = this.state;\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: 1, orderBy, orderType, number,\n      plate: driverText, drivers, types, from: moment(from).unix(), to: moment(to).unix() });\n  }\n\n  private changeOrder(key: string) {\n    const {\n      options: { orderBy, orderType },\n      pagination: { page }\n    } = this.props.transmittal;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    let {driverText, drivers, from, to, number, types} = this.state;\n    this.props.transmittalActions.getTransmittalsThunkAction({\n      nextPage: page,\n      orderBy: newOrderBy,\n      orderType: newOrderType,\n      number,\n      plate: driverText,\n      drivers: drivers,\n      types,\n      from: moment(from).unix(),\n      to: moment(to).unix() });\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/transmittals/create/'));\n  }\n\n  private changePage(page: number): void {\n    const { options: { orderBy, orderType } } = this.props.transmittal;\n    let {drivers, driverText, from, to, number, types} = this.state;\n    this.props.transmittalActions.getTransmittalsThunkAction({ nextPage: page, orderBy, orderType, number,\n      plate: driverText, drivers: drivers, types, from: moment(from).unix(), to: moment(to).unix() });\n  }\n\n  public exportExcel(): void {\n    this.trackClick('Exportar');\n    let {from, to, number, driverText, drivers, types} = this.state;\n\n    let url = `/transmittals/export-xls?${from && to ? `&from=${moment(from).unix()}&to=${moment(to).unix()}` : ''}`;\n    if(number?.trim()){\n      url = `${url}&number=${number}`;\n    }\n    if(driverText && driverText.trim()){\n      url = `${url}&plate=${driverText}`;\n    }\n\n    if(drivers){\n      url = `${url}&drivers=${drivers}`;\n    }\n\n    if (types){\n      url = `${url}&types=${types}`;\n    }\n\n\n    window.open(url, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/transmittals/export-xls/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-distribución.xlsx`;\n    //     // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //     //   // IE workaround for \"HTML7007: One or more blob URLs were\n    //     //   // revoked by closing the blob for which they were created.\n    //     //   // These URLs will no longer resolve as the data backing\n    //     //   // the URL has been freed.\"\n    //     //   window.navigator.msSaveBlob(blob, fileName);\n    //     // } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     // }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal!('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState, router: any }) => {\n  return {\n    transmittal: state.transmittal,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(TransmittalListView);\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport { ITransmittal } from '../../../../../../../src/distribution/interfaces/transmittal.interface';\nimport ApiService from '../../../utils/axios';\nimport { AxiosError } from 'axios';\n\ninterface IPropsType {\n  transmittal: ITransmittal;\n}\n\ninterface IStateType {\n  loading: boolean;\n  error: Error | null;\n}\n\nclass UploadTransmittalFile extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  private readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    loading: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.api = new ApiService();\n    this.inputFile = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading } = this.state;\n    return (\n      <button\n        className='btn btn-xs btn-default'\n        disabled={loading}\n        style={{ marginRight: '5px' }}\n        onClick={this.clickUploadFile}\n      >\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={this.handleChangeInputFile}\n        />\n        {\n          loading\n            ? (\n              <i className='fa fa-spinner fa-spin text-purple' />\n            )\n            : (\n              <i\n                className='fa fa-fw fa-cloud-upload'\n                data-toggle='tooltip'\n                data-placement='top'\n                title={`Cargar archivo`}\n              />\n            )\n        }\n      </button>\n    );\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    const { transmittal } = this.props;\n    if (files && files.length) {\n      const data = new FormData();\n      data.append('file', files[0]);\n      data.append('transmittal', transmittal._id);\n      this.setState({ loading: true });\n      this.api.uploadTransmittalFile(data)\n        .then((response) => {\n          this.setState({ loading: false });\n        })\n        .catch((err: AxiosError) => {\n          this.setState({ loading: false });\n          this.api.errorHandler(err);\n        });\n    }\n    this.inputFile.current!.value = '';\n  }\n}\n\nexport default UploadTransmittalFile;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\nimport {IUsersState} from '../../actions/users.actions';\n\ninterface IPropsType {\n  users: IUsersState;\n  user?: IUser;\n  changeTempUser(user: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  type: string;\n}\n\nclass UserFormChangePasswordView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    type: 'password'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeType = this.changeType.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {changeTempUser} = this.props;\n    const {tempUser} = this.props.users;\n\n    return (\n      <div className=\"row\">\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Nueva Contraseña</label>\n            <div className=\"input-group\">\n              <input\n                type={this.state.type}\n                className=\"form-control\"\n                name={\"change-user\"}\n                defaultValue={tempUser ? tempUser.password : undefined}\n                onChange={(e: React.ChangeEvent<HTMLInputElement>) => changeTempUser({password: e.target.value})}\n              />\n              <span className=\"input-group-addon pointer\" onClick={this.changeType}>\n                <i className={`fa ${this.state.type === 'text' ? 'fa-eye-slash' : 'fa-eye'}`} />\n              </span>\n            </div>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private changeType() {\n    this.setState({\n      type: this.state.type === 'text' ? 'password' : 'text'\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(UserFormChangePasswordView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { ICompany } from '../../../../../../src/app/interfaces/company.interface';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { IPermission } from '../../../../../../src/billing/interfaces/permission.interface';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport { IVenue } from '../../../../../../src/app/interfaces/venue.interface';\nimport { IUsersState } from '../../actions/users.actions';\nimport { IWindow } from '../../interfaces/window';\nimport Checkbox from '../Utils/CheckBox';\nimport { hasPermission } from '../../utils/common';\nimport ShowIf from '../Utils/ShowIf';\n\ninterface IPropsType {\n  users: IUsersState;\n  venues: IVenue[];\n  forms: IForm[];\n  permissions: IPermission[];\n  companies: ICompany[];\n  user?: IUser;\n  create: boolean;\n  changeTempUser(user: any): void;\n}\ndeclare let window: IWindow;\n\ninterface IStateType {\n  error: Error | null;\n  companiesOpen: string[];\n}\n\nclass UserFormView extends React.Component<IPropsType, IStateType> {\n  readonly state: IStateType = {\n    error: null,\n    companiesOpen: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.addPermission = this.addPermission.bind(this);\n    this.deletePermission = this.deletePermission.bind(this);\n    this.addCompanyAccess = this.addCompanyAccess.bind(this);\n    this.deleteCompanyAccess = this.deleteCompanyAccess.bind(this);\n    this.addVenueAccess = this.addVenueAccess.bind(this);\n    this.deleteVenueAccess = this.deleteVenueAccess.bind(this);\n    this.changeIsAdmin = this.changeIsAdmin.bind(this);\n    this.changeIsDriver = this.changeIsDriver.bind(this);\n    this.addForm = this.addForm.bind(this);\n    this.deleteForm = this.deleteForm.bind(this);\n    this.toogleCompanies = this.toogleCompanies.bind(this);\n  }\n\n  public componentDidMount() {\n    const { changeTempUser, companies } = this.props;\n    const { tempUser } = this.props.users;\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    ($('#id-forms') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addForm(e.target.value);\n      });\n    ($('#id-form-default') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({ preferred: e.target.value });\n      });\n    ($('#id-venue') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({ venue: e.target.value });\n      });\n    ($('#id-company') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          company: companies.find((company) => company._id === e.target.value)\n        });\n      });\n    ($('#id-channel') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        changeTempUser({\n          settings: {\n            ...tempUser.settings,\n            defaultChannel: e.target.value\n          }\n        });\n      });\n    ($('#id-permissions') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addPermission(e.target.value);\n      });\n    ($('#id-venues-access') as any)\n      .chosen(chosenOptions)\n      .change((e: React.ChangeEvent<HTMLSelectElement>) => {\n        this.addVenueAccess(e.target.value);\n      });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    $('#id-forms').trigger('chosen:updated');\n    $('#id-form-default').trigger('chosen:updated');\n    $('#id-venue').trigger('chosen:updated');\n    $('#id-permissions').trigger('chosen:updated');\n    $('#id-company').trigger('chosen:updated');\n    $('#id-channel').trigger('chosen:updated');\n    $('#id-venues-access').trigger('chosen:updated');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { changeTempUser, venues, permissions, forms, create, companies } =\n      this.props;\n    const { tempUser, channels } = this.props.users;\n    const userPermissions: IPermission[] = [];\n    const selectPermissions: IPermission[] = [];\n    const userForms: IForm[] = [];\n    const selectForms: IForm[] = [];\n    const idsUserPermissions =\n      tempUser?.userPermissions?.map((userPermission) => userPermission._id) ??\n      [];\n    const idsUserVenueAccess =\n      tempUser?.venuesAccess?.map((venue) => venue._id) ?? [];\n    const idsUserForms =\n      tempUser?.userForms?.map((userForm) => userForm._id) ?? [];\n\n    permissions.forEach((permission) => {\n      if (idsUserPermissions.includes(permission._id)) {\n        userPermissions.push(permission);\n      } else {\n        selectPermissions.push(permission);\n      }\n    });\n    forms.forEach((form) => {\n      if (idsUserForms.includes(form._id)) {\n        userForms.push(form);\n      } else {\n        selectForms.push(form);\n      }\n    });\n\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{ marginBottom: '15px' }}>\n          <li className=\"active\">\n            <a data-toggle=\"tab\" href=\"#general\">\n              General\n            </a>\n          </li>\n          {window.user.isAdmin ||\n          (hasPermission(window.user, 'changeTeamPermissions') &&\n            !this.props.user?.isAdmin) ? (\n            <li>\n              <a data-toggle=\"tab\" href=\"#permissions\">\n                Permisos\n              </a>\n            </li>\n          ) : null}\n          <li>\n            <a data-toggle=\"tab\" href=\"#access\">\n              Accesos\n            </a>\n          </li>\n          <li>\n            <a data-toggle=\"tab\" href=\"#request\">\n              Solicitudes\n            </a>\n          </li>\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Nombres</label>\n                  <input\n                    type=\"text\"\n                    name=\"firstName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.firstName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) =>\n                      changeTempUser({ firstName: e.target.value })\n                    }\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Apellidos</label>\n                  <input\n                    type=\"text\"\n                    name=\"lastName\"\n                    className=\"form-control\"\n                    maxLength={50}\n                    defaultValue={tempUser ? tempUser.lastName : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) =>\n                      changeTempUser({ lastName: e.target.value })\n                    }\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Email</label>\n                  <input\n                    type=\"email\"\n                    name=\"email\"\n                    disabled={!create}\n                    className=\"form-control\"\n                    maxLength={80}\n                    defaultValue={tempUser ? tempUser.email : undefined}\n                    onChange={(e: React.ChangeEvent<HTMLInputElement>) =>\n                      changeTempUser({ email: e.target.value })\n                    }\n                  />\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-company\">Empresa</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-company\"\n                    name=\"venue\"\n                    defaultValue={\n                      tempUser && tempUser.company\n                        ? tempUser.company._id\n                        : undefined\n                    }\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {companies.map((company) => (\n                      <option key={company._id} value={company._id}>\n                        {company.name}\n                      </option>\n                    ))}\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-venue\">Sucursal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-venue\"\n                    name=\"venue\"\n                    defaultValue={\n                      tempUser && tempUser.venue ? tempUser.venue : undefined\n                    }\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {venues\n                      .filter(\n                        (venue) =>\n                          venue.company &&\n                          tempUser.company &&\n                          tempUser.company._id === venue.company._id\n                      )\n                      .map((venue) => (\n                        <option key={venue._id} value={venue._id}>\n                          {venue.name}\n                        </option>\n                      ))}\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formularios</label>\n                  <select\n                    id=\"id-forms\"\n                    className=\"chosen-select form-control\"\n                    style={{ minWidth: '200px' }}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {selectForms.map((form) => {\n                      return (\n                        <option key={form._id} value={form._id}>\n                          {form.name}\n                        </option>\n                      );\n                    })}\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                    <tr>\n                      <th style={{ width: '90%' }}>Name</th>\n                      <th style={{ width: '10%' }} />\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {userForms.length ? (\n                      userForms.map((form: any) => {\n                        return (\n                          <tr key={form._id}>\n                            <td>{form.name}</td>\n                            <td\n                              className=\"text-center text-red pointer\"\n                              onClick={() => this.deleteForm(form._id)}>\n                              <i className=\"fa fa-minus-circle\" />\n                            </td>\n                          </tr>\n                        );\n                      })\n                    ) : (\n                      <tr>\n                        <td colSpan={2}>\n                          Aún no se han seleccionado permisos.\n                        </td>\n                      </tr>\n                    )}\n                  </tbody>\n                </table>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Formulario por defecto</label>\n                  <select\n                    id=\"id-form-default\"\n                    className=\"chosen-select form-control\"\n                    style={{ minWidth: '200px' }}\n                    defaultValue={\n                      tempUser && tempUser.preferred\n                        ? tempUser.preferred\n                        : undefined\n                    }\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {userForms.map((form) => {\n                      return (\n                        <option key={form._id} value={form._id}>\n                          {form.name}\n                        </option>\n                      );\n                    })}\n                  </select>\n                </div>\n              </div>\n              <div className=\"col-md-12\">\n                <div className=\"checkbox\">\n                  <Checkbox\n                    active={tempUser && tempUser.isDriver}\n                    action={this.changeIsDriver}\n                    classes=\"icheck-in-checkbox\"\n                    style={{ marginTop: '-4px', marginRight: '5px' }}\n                  />\n                  Es Conductor\n                </div>\n              </div>\n              {window.user.isAdmin ? (\n                <div className=\"col-md-12\">\n                  <div className=\"checkbox\">\n                    <Checkbox\n                      active={tempUser && tempUser.isAdmin}\n                      action={this.changeIsAdmin}\n                      classes=\"icheck-in-checkbox\"\n                      style={{ marginTop: '-4px', marginRight: '5px' }}\n                    />\n                    Es ADMIN\n                  </div>\n                </div>\n              ) : null}\n            </div>\n          </div>\n          {window.user.isAdmin ||\n          (hasPermission(window.user, 'changeTeamPermissions') &&\n            !this.props.user?.isAdmin) ? (\n            <div id=\"permissions\" className=\"tab-pane fade\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Permisos</label>\n                    <select\n                      id=\"id-permissions\"\n                      className=\"chosen-select form-control\"\n                      style={{ minWidth: '200px' }}\n                      data-placeholder={'Seleccione...'}>\n                      <option value=\"\" />\n                      {selectPermissions.map((permission) => {\n                        return (\n                          <option key={permission._id} value={permission._id}>\n                            {permission.name}\n                          </option>\n                        );\n                      })}\n                    </select>\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <table className=\"table table-striped\">\n                    <thead>\n                      <tr>\n                        <th style={{ width: '20%' }}>Code</th>\n                        <th style={{ width: '70%' }}>Name</th>\n                        <th style={{ width: '10%' }} />\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {userPermissions.length ? (\n                        userPermissions.map((permission: any) => {\n                          return (\n                            <tr key={permission._id}>\n                              <td>{permission.codeName}</td>\n                              <td>{permission.name}</td>\n                              <td\n                                className=\"text-center text-red pointer\"\n                                onClick={() =>\n                                  this.deletePermission(permission._id)\n                                }>\n                                <i className=\"fa fa-minus-circle\" />\n                              </td>\n                            </tr>\n                          );\n                        })\n                      ) : (\n                        <tr>\n                          <td colSpan={3}>\n                            Aún no se han seleccionado permisos.\n                          </td>\n                        </tr>\n                      )}\n                    </tbody>\n                  </table>\n                </div>\n              </div>\n            </div>\n          ) : null}\n          <div id=\"access\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              {/* <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label>Sucursales adicionales</label>\n                   <select\n                    id=\"id-venues-access\"\n                    className=\"chosen-select form-control\"\n                    style={{ minWidth: '200px' }}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {venues\n                      .filter(\n                        (venue) =>\n                          !idsUserVenueAccess.includes(venue._id) &&\n                          venue._id !== tempUser.venue\n                      )\n                      .map((venue) => {\n                        return (\n                          <option key={venue._id} value={venue._id}>\n                            {venue.name}\n                            {venue.company ? ` - ${venue.company.name}` : ''}\n                          </option>\n                        );\n                      })}\n                  </select>\n                </div>\n              </div> */}\n              <div className=\"col-md-12\">\n                {companies.map((company: any) => {\n                  const hasCompany = tempUser.companiesAccess.some(\n                    (c) => c._id === company._id\n                  );\n                  const venuesSelected = company.venues.filter((venue: any) =>\n                    idsUserVenueAccess.includes(venue._id)\n                  );\n                  return (\n                    <div key={company._id}>\n                      <div\n                        className=\"company\"\n                        style={{\n                          padding: '10px',\n                          borderBottom: '1px solid #f4f4f4'\n                        }}>\n                        <Checkbox\n                          active={hasCompany}\n                          action={() => {\n                            hasCompany\n                              ? this.deleteCompanyAccess(company._id)\n                              : this.addCompanyAccess(company._id);\n                          }}\n                          classes=\"icheck-in-checkbox\"\n                          style={{ marginTop: '-4px', marginRight: '5px' }}\n                        />\n                        <strong className=\"text-primary\">{company.name}</strong>{' '}\n                        ({venuesSelected.length} de {company.venues.length}{' '}\n                        sucursales)\n                        <div\n                          className=\"pointer\"\n                          style={{ float: 'right' }}\n                          onClick={() => this.toogleCompanies(company._id)}>\n                          {this.state.companiesOpen.includes(company._id) ? (\n                            <i className=\"fa fa-chevron-up\" />\n                          ) : (\n                            <i className=\"fa fa-chevron-down\" />\n                          )}\n                        </div>\n                      </div>\n                      <ShowIf\n                        condition={this.state.companiesOpen.includes(\n                          company._id\n                        )}>\n                        {company.venues.map((venue: any) => {\n                          return (\n                            <div\n                              key={venue._id}\n                              // className=\"text-muted\"\n                              style={{\n                                marginLeft: '25px',\n                                padding: '10px',\n                                borderBottom: '1px solid #f8f8f8'\n                              }}>\n                              <Checkbox\n                                active={idsUserVenueAccess.includes(venue._id)}\n                                action={() => {\n                                  idsUserVenueAccess.includes(venue._id)\n                                    ? this.deleteVenueAccess(venue._id)\n                                    : this.addVenueAccess(venue._id);\n                                }}\n                                classes=\"icheck-in-checkbox\"\n                                style={{\n                                  marginTop: '-4px',\n                                  marginRight: '5px'\n                                }}\n                              />\n                              {venue.name}\n                            </div>\n                          );\n                        })}\n                      </ShowIf>\n                    </div>\n                  );\n                })}\n              </div>\n              {/* <div className=\"col-md-12\">\n                <table className=\"table table-striped\">\n                  <thead>\n                    <tr>\n                      <th style={{ width: '90%' }}>Sucursal</th>\n                      <th style={{ width: '10%' }} />\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {tempUser.venue\n                      ? venues\n                          .filter((venue: any) => venue._id === tempUser.venue)\n                          .map((venue: any) => (\n                            <tr key={venue._id} className=\"bg-aqua-active\">\n                              <td colSpan={2}>\n                                {venue.name}\n                                {venue.company\n                                  ? ` - ${venue.company.name}`\n                                  : ''}\n                              </td>\n                            </tr>\n                          ))\n                      : null}\n                    {tempUser.venuesAccess.length ? (\n                      tempUser.venuesAccess\n                        .filter((venue: any) => venue._id !== tempUser.venue)\n                        .map((venue: any) => {\n                          return (\n                            <tr key={venue._id}>\n                              <td>\n                                {venue.name}\n                                {venue.company\n                                  ? ` - ${venue.company.name}`\n                                  : ''}\n                              </td>\n                              <td\n                                className=\"text-center text-red pointer\"\n                                onClick={() =>\n                                  this.deleteVenueAccess(venue._id)\n                                }>\n                                <i className=\"fa fa-minus-circle\" />\n                              </td>\n                            </tr>\n                          );\n                        })\n                    ) : (\n                      <tr>\n                        <td colSpan={2}>\n                          Aún no se han seleccionado sucursales adicionales.\n                        </td>\n                      </tr>\n                    )}\n                  </tbody>\n                </table>\n              </div> */}\n            </div>\n          </div>\n          <div id=\"request\" className=\"tab-pane fade\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <div className=\"form-group\">\n                  <label htmlFor=\"id-channel\">Canal</label>\n                  <select\n                    className=\"chosen-select form-control\"\n                    id=\"id-channel\"\n                    name=\"channel\"\n                    defaultValue={tempUser?.settings?.defaultChannel}\n                    onChange={undefined}\n                    data-placeholder={'Seleccione...'}>\n                    <option value=\"\" />\n                    {channels.map((channel) => (\n                      <option key={channel._id} value={channel._id}>\n                        {channel.name}\n                      </option>\n                    ))}\n                  </select>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n  private toogleCompanies(companyId: string) {\n    this.setState({\n      companiesOpen: this.state.companiesOpen.includes(companyId)\n        ? this.state.companiesOpen.filter((id) => id !== companyId)\n        : [...this.state.companiesOpen, companyId]\n    });\n  }\n\n  private changeIsAdmin() {\n    const { isAdmin } = this.props.users.tempUser;\n    this.props.changeTempUser({ isAdmin: !isAdmin });\n  }\n\n  private changeIsDriver() {\n    const { isDriver } = this.props.users.tempUser;\n    this.props.changeTempUser({ isDriver: !isDriver });\n  }\n\n  private addCompanyAccess(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser, companies, venues } = this.props.users;\n    const findVenues = venues.filter((venue) => venue.company._id === id);\n    const company = companies.find((company) => company._id === id);\n    const venuesAccess = [\n      ...findVenues,\n      ...tempUser.venuesAccess.filter((venue) => venue.company._id !== company?._id)\n    ];\n    const companiesAccess = [company, ...tempUser.companiesAccess];\n    // console.log('addCompanyAccess', {\n    //   venuesAccess,\n    //   companiesAccess\n    // });\n    if (company && findVenues) {\n      changeTempUser({\n        venuesAccess,\n        companiesAccess\n      });\n    }\n  }\n\n  private deleteCompanyAccess(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser } = this.props.users;\n    const venuesAccess = tempUser.venuesAccess.filter(\n      (venue) => venue.company._id !== id\n    );\n    const companiesAccess = tempUser.companiesAccess.filter(\n      (company) => company._id !== id\n    );\n    // console.log('deleteCompanyAccess', {\n    //   venuesAccess,\n    //   companiesAccess\n    // });\n    changeTempUser({\n      venuesAccess,\n      companiesAccess\n    });\n  }\n\n  private addVenueAccess(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser, venues, companies } = this.props.users;\n    const findVenue = venues.find((venue) => venue._id === id);\n    const company = companies.find((company) =>\n      company.venues.some((venue) => venue._id === id)\n    );\n    const venuesAccess = [...tempUser.venuesAccess, findVenue];\n    const companiesAccess = [...tempUser.companiesAccess, company];\n    // console.log('addVenueAccess', {\n    //   venuesAccess,\n    //   companiesAccess\n    // });\n    if (company?.venues?.length === venuesAccess.filter((venue)=>venue?.company?._id === company?._id).length) {\n      changeTempUser({\n        venuesAccess,\n        companiesAccess\n      });\n    } else {\n      changeTempUser({\n        venuesAccess\n      });\n    }\n  }\n\n  private deleteVenueAccess(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser, venues } = this.props.users;\n    const findVenue = venues.find((venue) => venue._id === id);\n    const venuesAccess = tempUser?.venuesAccess?.filter((venue) => venue._id !== id) ?? [];\n    const companiesAccess = tempUser.companiesAccess.filter(\n      (company) => company._id !== findVenue?.company?._id\n    );\n    // console.log('deleteVenueAccess', {\n    //   venuesAccess,\n    //   companiesAccess\n    // });\n    changeTempUser({\n      venuesAccess,\n      companiesAccess: tempUser.companiesAccess.filter(\n        (company) => company._id !== findVenue?.company?._id\n      )\n    });\n  }\n\n  private addPermission(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser } = this.props.users;\n    const { permissions } = this.props;\n    const findPermision = permissions.find(\n      (permission) => permission._id === id\n    );\n    if (findPermision) {\n      changeTempUser({\n        userPermissions: [findPermision, ...tempUser.userPermissions]\n      });\n    }\n  }\n\n  private deletePermission(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser } = this.props.users;\n    changeTempUser({\n      userPermissions: tempUser\n        ? tempUser.userPermissions.filter((permission) => permission._id !== id)\n        : []\n    });\n  }\n\n  private addForm(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser } = this.props.users;\n    const { forms } = this.props;\n    const findForm = forms.find((form) => form._id === id);\n    if (findForm) {\n      changeTempUser({\n        userForms: [findForm, ...tempUser.userForms]\n      });\n    }\n  }\n\n  private deleteForm(id: string) {\n    const { changeTempUser } = this.props;\n    const { tempUser } = this.props.users;\n    changeTempUser({\n      userForms: tempUser\n        ? tempUser.userForms.filter((form) => form._id !== id)\n        : []\n    });\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(\n  mapStateToProps,\n  mapDispatchToProps\n)(UserFormView);\n","import { AxiosError, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  changeSearchUserAction,\n  changeStatusUserAction,\n  changeTempUserAction,\n  createUserAction,\n  deleteUserAction,\n  filterVenuesAction,\n  getUsersAction,\n  ITempUser,\n  IUsersState,\n  updateUserAction,\n  UserReduxAction\n} from '../../actions/users.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport {\n  hasPermission,\n  showModal,\n  statusFooterButttonsModal\n} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport UserFormChangePasswordView from './UserFormChangePasswordView';\nimport UserFormView from './UserFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { UserTypes } from '../../../../../../src/app/models/user.model.types';\nimport ShowIf from '../Utils/ShowIf';\nimport CopyText from '../Utils/CopyText';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<UserReduxAction>;\n  users: IUsersState;\n\n  getUsersAction(\n    page: number,\n    type: UserTypes,\n    search?: string\n  ): UserReduxAction;\n\n  createUserAction(): UserReduxAction;\n\n  updateUserAction(): UserReduxAction;\n\n  deleteUserAction(id?: string): UserReduxAction;\n\n  changeStatusUserAction(user: IUser): UserReduxAction;\n\n  filterVenuesAction(venues: string[]): UserReduxAction;\n\n  changeTempUserAction(user: ITempUser): UserReduxAction;\n\n  loadDataAction(\n    title: string,\n    body: JSX.Element,\n    footer: JSX.Element\n  ): ModalReduxAction;\n\n  changeSearchUserAction(searchText: string): UserReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass UserListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    searchText: '',\n    exporing: false\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de usuarios';\n    this.createUser = this.createUser.bind(this);\n    this.processCreateUser = this.processCreateUser.bind(this);\n    this.updateUser = this.updateUser.bind(this);\n    this.processUpdateUser = this.processUpdateUser.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.changeTempUser = this.changeTempUser.bind(this);\n    this.changePassword = this.changePassword.bind(this);\n    this.processChangePassword = this.processChangePassword.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.cloneUser = this.cloneUser.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.users;\n    this.props.getUsersAction(pagination.page, UserTypes.common);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `user-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const { pagination } = this.props.users;\n        this.props.getUsersAction(pagination.page, UserTypes.common);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(\n    prevProps: Readonly<IPropsType>,\n    prevState: Readonly<IStateType>,\n    snapshot?: any\n  ): void {\n    if (this.props.users.pagination.page !== prevProps.users.pagination.page) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.users.source) {\n      this.props.users.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public exportExcel() {\n    this.trackClick('Exportar');\n    this.setState({\n      exporing: true\n    });\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/users/export/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-usuarios.xlsx`;\n        // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n        //   // IE workaround for \"HTML7007: One or more blob URLs were\n        //   // revoked by closing the blob for which they were created.\n        //   // These URLs will no longer resolve as the data backing\n        //   // the URL has been freed.\"\n        //   window.navigator.msSaveBlob(blob, fileName);\n        // } else {\n        const blobURL = URL.createObjectURL(blob);\n        const tempLink = document.createElement('a');\n        tempLink.style.display = 'none';\n        tempLink.href = blobURL;\n        tempLink.setAttribute('download', fileName);\n        // Safari thinks _blank anchor are pop ups. We only want to set _blank\n        // target if the browser does not support the HTML5 download attribute.\n        // This allows you to download files in desktop safari if pop up blocking\n        // is enabled.\n        if (typeof tempLink.download === 'undefined') {\n          tempLink.setAttribute('target', '_blank');\n        }\n        this.setState({\n          exporing: false\n        });\n        document.body.appendChild(tempLink);\n        tempLink.click();\n        document.body.removeChild(tempLink);\n        URL.revokeObjectURL(blobURL);\n        // }\n      })\n      .catch((err) => {\n        this.setState({\n          exporing: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal!(\n            'Exportar usuarios',\n            'Ha ocurrido un error al general el excel.',\n            'error'\n          );\n        }\n      });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { exporing } = this.state;\n    const { loading, users, pagination, searchText, filters, venues } =\n      this.props.users;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.5\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">\n                Usuarios <small>{pagination.count}</small>\n              </h3>\n              <div className=\"box-tools pull-right\">\n                {hasPermission(window.user, 'addUser') ? (\n                  <button\n                    className=\"btn btn-sm btn-success\"\n                    onClick={this.createUser}>\n                    <i className=\"fa fa-plus\" /> Crear usuario\n                  </button>\n                ) : null}\n                <button\n                  className=\"btn btn-sm btn-primary hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporing}\n                  style={{ marginLeft: '5px' }}>\n                  {exporing ? (\n                    <React.Fragment>\n                      <i className=\"fa fa-spin fa-spinner\" /> Exportando\n                    </React.Fragment>\n                  ) : (\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-download\" /> Exportar\n                    </React.Fragment>\n                  )}\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"row\">\n                <div className=\"col-md-8\">\n                  <div\n                    className=\"input-group input-group-sm\"\n                    style={{ padding: '10px' }}>\n                    <input\n                      type=\"text\"\n                      value={searchText}\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      autoComplete=\"off\"\n                      // name={'search-user'}\n                      placeholder=\"Buscar\"\n                    />\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\">\n                        <i className=\"fa fa-search\" />\n                      </button>\n                    </div>\n                  </div>\n                </div>\n                <div className=\"col-md-4\">\n                  <div style={{ padding: '10px' }}>\n                    <BootstrapSelect\n                      sm={true}\n                      noneSelectedText=\"Todas las sucursales\"\n                      displayItems={2}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={filters.venues}\n                      autoClouse={false}\n                      search={true}\n                      allOption={false}\n                      selectAll={this.filterAllVenues}\n                      options={venues.map((venue: any) => ({\n                        value: venue._id,\n                        rend: (\n                          <>\n                            <strong>{venue.company.name.toUpperCase()}</strong>{' '}\n                            {venue.name.toUpperCase()}\n                          </>\n                        ),\n                        text: `${venue.company.name.toUpperCase()} ${venue.name.toUpperCase()}`\n                      }))}\n                      // onClick={() => {\n                      //   console.log('click');\n                      // }}\n                      onClick={this.filterVenues}\n                    />\n                  </div>\n                </div>\n              </div>\n              <table className=\"table table-andes table-hover table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{ width: '26%' }}>Usuario</th>\n                    <th style={{ width: '30%' }} className=\"hidden-xs\">\n                      Sucursal\n                    </th>\n                    <th style={{ width: '20%' }} className=\"hidden-xs\">\n                      Formularios\n                    </th>\n                    <th style={{ width: '20%' }} className=\"hidden-xs\">\n                      Último login\n                    </th>\n                    {window.user.isAdmin ||\n                    hasPermission(window.user, 'changeUser') ? (\n                      <th style={{ width: '1%' }} className=\"width-10\" />\n                    ) : null}\n                    {hasPermission(window.user, 'changeUser') ? (\n                      <th style={{ width: '1%' }} className=\"width-10\" />\n                    ) : null}\n                    {hasPermission(window.user, 'addUser') ? (\n                      <th style={{ width: '1%' }} className=\"width-10\" />\n                    ) : null}\n                    {window.user.isAdmin ||\n                    hasPermission(window.user, 'changeUser') ? (\n                      <th style={{ width: '1%' }} className=\"width-10\" />\n                    ) : null}\n                  </tr>\n                </thead>\n                <tbody>\n                  {!loading && users.length === 0 && users ? (\n                    <tr>\n                      <td colSpan={6}>No se han encontrado resultados.</td>\n                    </tr>\n                  ) : null}\n                  {users.map((user: IUser) => {\n                    const forms = user.userForms;\n                    return (\n                      <tr\n                        key={user._id}\n                        id={`user-${user._id}`}\n                        className={'background-transition'}>\n                        <td\n                          className={`middle ${\n                            user.active ? '' : 'line-through'\n                          }`}>\n                          <strong\n                            className={`middle ${\n                              user.active\n                                ? 'text-primary'\n                                : 'text-muted line-through'\n                            }`}>\n                            <CopyText\n                              value={`${user.firstName?.toUpperCase()} ${user.lastName?.toUpperCase()}`}>\n                              {user.firstName?.toUpperCase()}{' '}\n                              {user.lastName?.toUpperCase()}\n                            </CopyText>\n                          </strong>\n                          <br />\n                          <span className=\"text-muted text-sm\">\n                            <CopyText value={user?.email}>\n                              <i className=\"fa fa-email\"></i>\n                              {user.email}\n                            </CopyText>\n                          </span>\n                          <div className=\"hidden-lg hidden-md hidden-sm text-sm\">\n                            <span className=\"text-sm text-muted\">\n                              {user.venue ? user.venue.name : ''} -{' '}\n                              {user.company?.name?.length\n                                ? user.company.name?.toUpperCase()\n                                : ''}\n                            </span>\n                          </div>\n                        </td>\n\n                        <td\n                          className={`middle hidden-xs text-muted ${\n                            user.active ? '' : 'line-through'\n                          }`}>\n                          <strong>\n                            {user.venue.name?.length\n                              ? user.venue.name.toUpperCase()\n                              : ''}\n                          </strong>\n                          <br />\n                          <span className=\"text-sm text-muted\">\n                            {user.company?.name?.length\n                              ? user.company.name?.toUpperCase()\n                              : ''}\n                          </span>\n                        </td>\n                        <td\n                          className={`middle hidden-xs text-muted text-sm ${\n                            user.active ? '' : 'line-through'\n                          }`}>\n                          <ul style={{ marginBottom: 0, paddingLeft: 0 }}>\n                            <ShowIf condition={!!forms.length}>\n                              {forms.map((form, index) => {\n                                return (\n                                  <React.Fragment key={`${form._id}-${index}`}>\n                                    {/*{index > 0 ?*/}\n                                    {/*  <br /> : null}*/}\n                                    <li>{form.name?.toUpperCase()}</li>\n                                  </React.Fragment>\n                                );\n                              })}\n                            </ShowIf>\n                          </ul>\n                        </td>\n                        <td\n                          className={`middle hidden-xs text-muted text-sm ${\n                            user.active ? '' : 'line-through'\n                          }`}>\n                          {user.lastLogin\n                            ? moment(user.lastLogin).format('LLL')\n                            : '-'}\n                        </td>\n                        {window.user.isAdmin ||\n                        hasPermission(window.user, 'changeUser') ? (\n                          <td\n                            className=\"middle-center\"\n                            style={{ paddingTop: '15px' }}>\n                            <BootstrapSwitch\n                              checked={user.active}\n                              onChange={() => {\n                                swal({\n                                  title: '¿Estás seguro?',\n                                  text: `Vas a ${\n                                    user.active ? 'DESACTIVAR' : 'ACTIVAR'\n                                  } a ${user.firstName} ${user.lastName} `,\n                                  icon: 'warning',\n                                  dangerMode: true,\n                                  buttons: {\n                                    cancel: 'Cancelar' as any,\n                                    confirm: {\n                                      text: 'Sí'\n                                    }\n                                  }\n                                }).then((willDelete: any) => {\n                                  if (willDelete) {\n                                    this.props.changeStatusUserAction(user);\n                                  }\n                                });\n                              }}\n                            />\n                          </td>\n                        ) : null}\n                        {hasPermission(window.user, 'changeUser') ? (\n                          <td\n                            className=\"middle-center text-yellow pointer\"\n                            onClick={() => this.changePassword(user)}>\n                            <i className=\"fa fa-lock\" />\n                          </td>\n                        ) : null}\n                        {hasPermission(window.user, 'addUser') ? (\n                          <td\n                            className=\"middle-center text-blue pointer\"\n                            onClick={() => this.cloneUser(user)}>\n                            <i className=\"fa fa-clone\" />\n                          </td>\n                        ) : null}\n                        {window.user.isAdmin ||\n                        (hasPermission(window.user, 'changeUser') &&\n                          !user.isAdmin) ? (\n                          <td\n                            className=\"middle-center text-blue pointer\"\n                            onClick={() => this.updateUser(user)}>\n                            <i className=\"fa fa-pencil\" />\n                          </td>\n                        ) : (\n                          <td></td>\n                        )}\n                      </tr>\n                    );\n                  })}\n                </tbody>\n              </table>\n            </div>\n            {pagination.pages > 1 && (\n              <div className=\"box-footer text-right\">\n                <Paginator\n                  changePage={this.changePage}\n                  page={pagination.page}\n                  pages={pagination.pages}\n                />\n              </div>\n            )}\n            {users.length === 0 && loading && (\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\" />\n              </div>\n            )}\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterAllVenues(selected: boolean): void {\n    this.props.filterVenuesAction(\n      selected ? this.props.users.venues.map((v) => v._id) : []\n    );\n  }\n\n  private filterVenues(venue: string) {\n    const { filters } = this.props.users;\n    if (filters.venues.includes(venue)) {\n      this.props.filterVenuesAction([]);\n    } else {\n      this.props.filterVenuesAction([venue]);\n    }\n    this.debounceOnChangeSearch();\n  }\n\n  private cloneUser(user: IUser): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    const tmpUser = {\n      ...user,\n      _id: '',\n      firstName: '',\n      lastName: '',\n      email: ''\n    };\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    this.props.changeTempUserAction(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Clonando usuario`,\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={tmpUser}\n        />,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\">\n            Cancelar\n          </button>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-primary\"\n            onClick={this.processCreateUser}>\n            Crear\n          </button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value;\n    this.props.changeSearchUserAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getUsersAction(1, UserTypes.common);\n  }\n\n  private createUser(): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    this.props.changeTempUserAction({\n      _id: '',\n      firstName: '',\n      lastName: '',\n      company: null,\n      email: '',\n      isAdmin: false,\n      isDriver: false,\n      venue: '',\n      userPermissions: [],\n      companiesAccess: [],\n      venuesAccess: [],\n      userForms: [],\n      settings: {}\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Usuario',\n        <UserFormView\n          create={true}\n          changeTempUser={changeTempUser}\n          venues={venues}\n          companies={companies}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n        />,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\">\n            Cancelar\n          </button>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-primary\"\n            onClick={this.processCreateUser}>\n            Crear\n          </button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processCreateUser(): void {\n    const { firstName, lastName, email, venue } = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.createUserAction();\n    }\n  }\n\n  private changePassword(user: IUser): void {\n    const { changeTempUser } = this;\n    const tmpUser = {\n      ...user,\n      password: ''\n    };\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Cambiando contraseña a ${user.firstName} ${user.lastName}`,\n        <UserFormChangePasswordView\n          changeTempUser={changeTempUser}\n          users={this.props.users}\n          user={user}\n        />,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\">\n            Cancelar\n          </button>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-primary\"\n            onClick={this.processChangePassword}>\n            Cambiar\n          </button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processChangePassword() {\n    const { password, _id } = this.props.users.tempUser;\n    statusFooterButttonsModal(true);\n    if (password && password.trim().length >= 6 && _id) {\n      const api: ApiService = new ApiService();\n      api\n        .changePasswordUser(_id, password)\n        .then((response) => {\n          statusFooterButttonsModal(false);\n          showModal(false);\n          swal!(response.data.message, {\n            icon: 'success'\n          });\n        })\n        .catch((err: AxiosError) => {\n          statusFooterButttonsModal(false);\n          api.errorHandler(err);\n        });\n    } else {\n      swal!(\n        'Cambiar contraseña',\n        'La contraseña debe tener al menos 6 caracteres.',\n        'error'\n      );\n      statusFooterButttonsModal(false);\n    }\n  }\n\n  private updateUser(user: IUser): void {\n    const { changeTempUser } = this;\n    const { venues, permissions, forms, companies } = this.props.users;\n    const tmpUser = { ...user };\n    tmpUser.venue = tmpUser.venue ? tmpUser.venue._id : '';\n    changeTempUser(tmpUser);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Editando a ${user.firstName} ${user.lastName}`,\n        <UserFormView\n          create={false}\n          changeTempUser={changeTempUser}\n          companies={companies}\n          venues={venues}\n          users={this.props.users}\n          forms={forms}\n          permissions={permissions}\n          user={user}\n        />,\n        <React.Fragment>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-default\"\n            data-dismiss=\"modal\">\n            Cancelar\n          </button>\n          <button\n            type=\"button\"\n            className=\"btn btn-sm btn-primary\"\n            onClick={this.processUpdateUser}>\n            Editar\n          </button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processUpdateUser() {\n    const { firstName, lastName, email, venue } = this.props.users.tempUser;\n    if (!firstName || !firstName.trim().length) {\n      swal!('Agregar usuario', 'El nombres es requerido', 'error');\n    } else if (!lastName || !lastName.trim().length) {\n      swal!('Agregar usuario', 'El apellidos es requerido', 'error');\n    } else if (!email || !email.trim().length) {\n      swal!('Agregar usuario', 'El email es requerido', 'error');\n    } else if (!venue || !venue.trim().length) {\n      swal!('Agregar usuario', 'El sucursal es requerido', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.updateUserAction();\n    }\n  }\n\n  private changeTempUser({\n    _id,\n    firstName,\n    lastName,\n    email,\n    venue,\n    userPermissions,\n    preferred,\n    userForms,\n    company,\n    venuesAccess,\n    companiesAccess,\n    password,\n    isAdmin,\n    isDriver,\n    settings\n  }: ITempUser) {\n    const tempUser: ITempUser = {\n      _id: _id ? _id : this.props.users.tempUser._id,\n      firstName: firstName ? firstName : this.props.users.tempUser.firstName,\n      lastName: lastName ? lastName : this.props.users.tempUser.lastName,\n      isAdmin:\n        typeof isAdmin === 'boolean'\n          ? isAdmin\n          : this.props.users.tempUser.isAdmin,\n      isDriver:\n        typeof isDriver === 'boolean'\n          ? isDriver\n          : this.props.users.tempUser.isDriver,\n      password: password ? password : '',\n      settings: settings ?? this.props.users.tempUser.settings,\n      email: email ? email : this.props.users.tempUser.email,\n      userPermissions: userPermissions\n        ? userPermissions\n        : this.props.users.tempUser.userPermissions,\n      userForms: userForms ? userForms : this.props.users.tempUser.userForms,\n      preferred: preferred\n        ? preferred\n        : preferred === undefined\n        ? this.props.users.tempUser.preferred\n        : null,\n      venue: venue\n        ? venue\n        : venue === undefined\n        ? this.props.users.tempUser.venue\n        : null,\n      venuesAccess: venuesAccess\n        ? venuesAccess\n        : venuesAccess === undefined\n        ? this.props.users.tempUser.venuesAccess\n        : [],\n      companiesAccess: companiesAccess\n        ? companiesAccess\n        : companiesAccess === undefined\n        ? this.props.users.tempUser.companiesAccess\n        : [],\n      company: company\n        ? company\n        : company === undefined\n        ? this.props.users.tempUser.company\n        : null\n    };\n    this.props.changeTempUserAction(tempUser);\n  }\n\n  private deleteUser(user: IUser) {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el usuario ${user.firstName || ''} ${\n        user.lastName || ''\n      }`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteUserAction(user._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getUsersAction(page, UserTypes.common);\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\n// const mapDispatchToProps = (dispatch: Dispatch<UserReduxAction> ) => {\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getUsersAction: (nextPage: number, type: UserTypes, search?: string) =>\n      dispatch(getUsersAction(nextPage, type, search)),\n    deleteUserAction: (id: string) => dispatch(deleteUserAction(id)),\n    filterVenuesAction: (venues: string[]) =>\n      dispatch(filterVenuesAction(venues)),\n    changeTempUserAction: (user: ITempUser) =>\n      dispatch(changeTempUserAction(user)),\n    createUserAction: () => dispatch(createUserAction()),\n    updateUserAction: () => dispatch(updateUserAction()),\n    changeStatusUserAction: (user: IUser) =>\n      dispatch(changeStatusUserAction(user)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) =>\n      dispatch(loadDataAction(title, body, footer)),\n    changeSearchUserAction: (searchText: string) =>\n      dispatch(changeSearchUserAction(searchText))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(\n  mapStateToProps,\n  mapDispatchToProps\n)(UserListView);\n","import * as React from 'react';\nimport {RefObject} from 'react';\n\ninterface IPropsType {\n  value: string;\n\n  items: any[];\n  inputClass?: string;\n\n  renderItem(item: any, index: any): React.ReactElement<any>;\n  onChange(e: React.ChangeEvent<HTMLInputElement>): void;\n  onSelect(item: any): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n}\n\nclass AutoCompleteInput extends React.Component<IPropsType, IStateType>{\n\n  readonly state = {\n    error: null,\n    open: false\n  };\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.items = React.createRef();\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { onChange, value, items, inputClass } = this.props;\n    return (\n      <div className=\"autocomplete\" ref={this.autocompleteElement} >\n        <input\n          type=\"text\"\n          className={`form-control ${inputClass ? inputClass : ''}`}\n          onChange={(e) => {\n            if (this.items.current) {\n              this.items.current.scrollTop = 0;\n            }\n            this.setState({\n              open: true\n            });\n            onChange(e);\n          }}\n          value={value}\n          onClick={this.changeOpen}\n          autoComplete={'off'}\n        />\n        {\n          this.state.open ?\n            <div className=\"items\" ref={this.items}>\n              {\n                items.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.props.onSelect(item);\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    // if ((e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) && (e.target.nodeName === 'BODY')) {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private outsideClick(e: any): void{\n    if(!this.autocompleteElement.current!.contains(e.target)){\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const {open} = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteInput;\n","import * as React from 'react';\nimport { RefObject } from 'react';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport { IRequestItem } from '../../../../../../src/request/interfaces/requestItem.interface';\nimport ApiService from '../../utils/axios';\nimport { AxiosError, AxiosResponse } from 'axios';\nimport { hasPermission, parseReplicableURL } from '../../utils/common';\nimport ShowIf from './ShowIf';\nimport { Subject } from 'rxjs/internal/Subject';\nimport { IWindow } from '../../interfaces/window';\n\ninterface IPropsType {\n  defaultValue: string;\n  inputClass?: string;\n  item: IRequestItem;\n  history: any;\n  renderItem(item: any, index: any): React.ReactElement<any>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  open: boolean;\n  canEdit: boolean;\n  value: string;\n  VINRecommends: any[];\n}\n\ndeclare let window: IWindow;\n\nclass AutoCompleteVinInput extends React.Component<IPropsType, IStateType> {\n  readonly $subjectVINRecommends = new Subject<any>();\n  readonly api: ApiService;\n  readonly autocompleteElement: RefObject<HTMLInputElement>;\n  readonly items: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeOpen = this.changeOpen.bind(this);\n    this.close = this.close.bind(this);\n    this.outsideClick = this.outsideClick.bind(this);\n    this.renderItem = this.renderItem.bind(this);\n    this.searchVin = this.searchVin.bind(this);\n    this.updateVin = this.updateVin.bind(this);\n    this.openVehicle = this.openVehicle.bind(this);\n    this.autocompleteElement = React.createRef();\n    this.api = new ApiService();\n    this.items = React.createRef();\n    this.state = {\n      error: null,\n      open: false,\n      value: this.props.defaultValue,\n      canEdit: false,\n      VINRecommends: []\n    };\n    this.$subjectVINRecommends.pipe(\n      debounceTime(300),\n      switchMap(({ vin, material }: { vin: string, material: string }) => {\n        return ajax({\n          url: `/api/v1/requests/search-vin/?vin=${vin}&material=${material}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        VINRecommends: response.response.data\n      });\n    });\n  }\n\n  public componentWillReceiveProps(nextProps: Readonly<IPropsType>, nextContext: any) {\n    if (nextProps.defaultValue !== this.props.defaultValue) {\n      this.setState({\n        value: nextProps.defaultValue\n      });\n    }\n  }\n\n  public componentDidMount(): void {\n    document.addEventListener('keydown', this.close, true);\n    document.addEventListener('click', this.outsideClick, true);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { defaultValue, inputClass, item } = this.props;\n    const { VINRecommends, canEdit, value } = this.state;\n    return (\n      <div className='autocomplete' ref={this.autocompleteElement}>\n        <div\n          className='input-group input-group-sm'\n        >\n          <div className='input-group-btn'>\n            {\n              !canEdit ?\n                <ShowIf condition={hasPermission(window.user, 'viewCar') && item.car?.vin?.length > 0}>\n                <button\n                  // className='btn btn-sm pointer btn-success'\n                  className='btn btn-sm pointer btn-default'\n                  style={{ padding: '5px 10px' }}\n                  onClick={this.openVehicle}\n                >\n                  <i className='fa fa-external-link-square' />\n                </button>\n                </ShowIf>\n                : <button\n                  className='btn btn-sm pointer btn-primary'\n                  style={{ padding: '5px 10px' }}\n                  onClick={() => {\n                    this.setState({\n                      value: defaultValue || '',\n                      canEdit: false\n                    });\n                  }}\n                >\n                  <i className='fa fa-stop-circle' />\n                </button>\n            }\n          </div>\n          <input\n            type='text'\n            className={`form-control ${inputClass ? inputClass : ''}`}\n            onChange={(e) => {\n              const { value } = e.target;\n              if (this.items.current) {\n                this.items.current.scrollTop = 0;\n              }\n              this.setState({\n                open: true,\n                value\n              });\n              this.searchVin(value, item.car.material);\n            }}\n            style={{ padding: '5px' }}\n            disabled={!canEdit}\n            value={value}\n            onClick={this.changeOpen}\n            autoComplete={'off'}\n          />\n          <div\n            className={`input-group-btn`}\n          >\n            <button\n              className={`${canEdit || item.car?.vin?.length === 0 ? 'btn btn-sm btn-success' : 'btn btn-sm btn-primary'}`}\n              style={{ padding: '5px 10px' }}\n              onClick={() => {\n                if (canEdit) {\n                  this.updateVin(value);\n                } else {\n                  this.setState({\n                    canEdit: true\n                  });\n                }\n              }}\n            >\n              <i className={`fa ${canEdit ? 'fa-check' : 'fa-pencil-square-o'}`} />\n            </button>\n          </div>\n        </div>\n        {\n          this.state.open ?\n            <div className='items' ref={this.items}>\n              {\n                VINRecommends.map((item, index) => (\n                  this.renderItem(item, index)\n                ))\n              }\n            </div>\n            : null\n        }\n      </div>\n    );\n  }\n\n  private renderItem(item: any, index: any) {\n    const element = this.props.renderItem(item, index);\n    return React.cloneElement(element, {\n      onClick: () => {\n        this.setState({\n          value: item.vin\n        });\n        this.changeOpen();\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    document.removeEventListener('keydown', this.close, true);\n    document.removeEventListener('click', this.outsideClick, true);\n  }\n\n  private close(e: any): void {\n    if (e.key === 'Escape' || e.key === 'Esc' || e.keyCode === 27) {\n      e.preventDefault();\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private updateVin(vin: string) {\n    const { item } = this.props;\n    this.api.uppdateRequestItemVin(item, vin)\n      .then(() => {\n        this.setState({\n          canEdit: false\n        });\n        // transmittalActions.updateTransmittalAction(response.data.data);\n      })\n      .catch((err: AxiosError) => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  openVehicle() {\n    const { item } = this.props;\n    this.props.history.push(parseReplicableURL(`/settings/cars/${item.car._id}`));\n    // window.open(parseReplicableURL(`/settings/cars/${item.car._id}/`), '_blank');\n  }\n\n\n  private searchVin(vin: string, material: string): void {\n    this.$subjectVINRecommends.next({ vin, material });\n  }\n\n  private outsideClick(e: any): void {\n    if (!this.autocompleteElement.current!.contains(e.target)) {\n      this.setState({\n        open: false\n      });\n    }\n  }\n\n  private changeOpen(): void {\n    const { open } = this.state;\n    this.setState({\n      open: !open\n    });\n  }\n}\n\nexport default AutoCompleteVinInput;\n","import * as React from 'react';\nimport * as unorm from 'unorm';\nimport {RefObject} from 'react';\n\ninterface IOption {\n  value: string;\n  text: any;\n  rend?: any;\n  className?: string;\n}\n\ninterface IPropsType {\n  options: IOption[];\n  selected: string[];\n  className?: string;\n  displayItems?: number;\n  onClick: any;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  displayHandler?: (value: boolean) => void;\n  notHideOnClickOutside?: boolean\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelect extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly dropdown: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n    this.dropdown = React.createRef();\n  }\n\n  componentDidMount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').on('click', (event) => {\n        $('.osa-dropdown').toggleClass('open');\n      });\n    }\n  }\n\n  componentWillUnmount() {\n    const {notHideOnClickOutside, autoClouse} = this.props;\n    if (notHideOnClickOutside && !autoClouse) {\n      $('.osa-dropwdown-button').remove('click')\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm, options, selected, onClick, displayItems, noneSelectedText, selectedText, separator, allOption, search, autoClouse, selectAll, notHideOnClickOutside\n    } = this.props;\n    const  {searchText} = this.state;\n    const selectedItems = options.filter((option) => (selected.includes(option.value)));\n\n    return (\n      <div\n        ref={this.dropdown}\n        className={`osa-dropdown dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm?'bootstrap-select-sm':''}`}>\n        <button\n          type=\"button\"\n          className={`osa-dropwdown-button btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n          data-toggle={notHideOnClickOutside && !autoClouse ? '' : \"dropdown\"}\n          style={{borderRadius: '0px'}}\n          onClick={this.handlerOpen}\n        >\n          <div className=\"filter-option\">\n            <div className=\"filter-option-inner\">\n              <div className=\"filter-option-inner-inner\">\n                {\n                  selectedItems.length ?\n                    displayItems && selectedItems.length > displayItems ?\n                      <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                      selectedItems\n                        .map((option, index) => (\n                          <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                          </React.Fragment>\n                        ))\n                    : noneSelectedText ? <span style={{color: '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                }\n              </div>\n            </div>\n          </div>\n          <span className=\"bs-caret\">\n            <span className=\"caret\" />\n          </span>\n        </button>\n        <div className=\"dropdown-menu\" style={{borderRadius: '0px'}}>\n          {\n            search ?\n              <div className=\"bs-searchbox\">\n                <input\n                  ref={this.input}\n                  type=\"text\"\n                  className=\"form-control input-sm\"\n                  autoComplete=\"off\"\n                  value={this.state.searchText}\n                  onChange={\n                    (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                  }\n                />\n              </div> : null\n          }\n          {\n            allOption ?\n              <div className=\"bs-actionsbox\">\n                <div className=\"btn-group btn-group-sm btn-block\">\n                  <button\n                    onClick={() => selectAll(true)}\n                    type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                  </button>\n                  <button\n                    onClick={() => selectAll(false)}\n                    type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                  </button>\n                </div>\n              </div> : null\n          }\n          <div\n            className=\"inner open\"\n            aria-expanded=\"false\"\n            tabIndex={-1}\n          >\n            <ul className=\"dropdown-menu inner\" style={{maxHeight: '30vh', overflowY: 'auto'}}>\n              {\n                options.filter((option) => {\n                  if (!searchText || !searchText.length) {\n                    return true;\n                  }\n                  return unorm.nfd(option.text)\n                    .replace(/[\\u0300-\\u036f]/g, '')\n                    .toLowerCase()\n                    .includes(searchText.toLowerCase());\n                }).map((option) => {\n                  const isSelected = selected.includes(option.value);\n                  return (\n                    <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                      <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                        <span className=\"glyphicon glyphicon-ok check-mark\" />\n                        <span className={option.className ? option.className : ''}>{option.rend?option.rend:option.text}</span>\n                      </a>\n                    </li>\n                  );\n                })\n              }\n            </ul>\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // https://codepen.io/qpqinc/pen/yLyPVMJ\n    if (this.props.displayHandler != null){\n      this.props.displayHandler(!this.state.open);\n    }\n    if(this.input.current){\n      this.input.current.focus()\n    }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelect;\n","import * as React from 'react';\n\ninterface IPropsType {\n  checked: boolean;\n  onChange: any;\n  color?: string;\n}\n\nclass BootstrapSwitch extends React.Component<IPropsType, {}> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {checked, onChange, color} = this.props;\n    return (\n      <label className={`switch ${color ? `switch-${color}` : ''}`}>\n        <input type=\"checkbox\" className=\"switch\" checked={checked} onChange={onChange}/>\n        <span className=\"slider round\"/>\n      </label>\n    );\n  }\n}\n\nexport default BootstrapSwitch;\n","import * as React from 'react';\n// import {CSSProperties} from 'react';\n\ninterface IPropsType {\n  color?: string;\n  active?: boolean;\n  action: any;\n  classes?: string;\n  style?: React.CSSProperties;\n}\n\ninterface IStateType {\n  hover: boolean;\n}\n\nclass Checkbox extends React.Component<IPropsType, IStateType> {\n\n  state = {\n    hover: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.mouseOver = this.mouseOver.bind(this);\n    this.mouseOut = this.mouseOut.bind(this);\n  }\n\n  private mouseOver(): void {\n    this.setState({\n      hover: true\n    });\n  }\n\n  private mouseOut(): void {\n    this.setState({\n      hover: false\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {hover} = this.state;\n    const {color, active, action, classes, style} = this.props;\n    const classIcheck: string[] = [];\n\n    // set color\n    if (color) {\n      classIcheck.push(`icheckbox_square-${color}`);\n    } else {\n      classIcheck.push('icheckbox_square-blue');\n    }\n\n    // if mouse hover\n    if (hover) {\n      classIcheck.push('hover');\n    }\n\n    if (classes) {\n      classIcheck.push(classes);\n    }\n\n    // if checked\n    if (active) {\n      classIcheck.push('checked');\n    }\n\n    return (\n      <div\n        className={classIcheck.join(' ')}\n        onMouseOver={this.mouseOver}\n        onMouseOut={this.mouseOut}\n        onClick={action}\n        style={style ? style : {\n          background: '#CCC'\n        }}\n      >\n      </div>\n    );\n  }\n}\n\nexport default Checkbox;\n","import * as React from 'react';\n\ninterface IPropsType {\n  value: string;\n  className?: string;\n}\n\nclass CopyText extends React.Component<IPropsType, {}> {\n\n  private element: React.RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.copyToClipboard = this.copyToClipboard.bind(this);\n  }\n\n  showNotification(value: string) {\n    if ($('#center-message').length) {\n      $('#center-message').remove();\n    }\n    const div = document.createElement('div');\n    div.id = 'center-message';\n    div.textContent = `${value} copiado al portapapeles.`;\n    document.body.appendChild(div);\n    $('#center-message').fadeIn();\n    setTimeout(() => {\n      const $centerMessage = $('#center-message');\n      $centerMessage.fadeOut('slow', () => {\n        if ($centerMessage.length) {\n          $centerMessage.remove();\n        }\n      });\n    }, 1500);\n  }\n\n  copyToClipboard() {\n    const {value} = this.props;\n    if (value && value.length && this.element.current) {\n      const element = document.createElement('input');\n      element.value = value;\n      // element.type = 'hidden';\n      this.element.current.appendChild(element);\n      element.select();\n      document.execCommand('copy');\n      this.element.current.removeChild(element);\n      this.showNotification(value);\n    }\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const {className} = this.props;\n    return (\n      <span className={className ? className : ''} ref={this.element}>\n        {this.props.children}{' '}\n        <i\n          // className=\"fa text-black fa-copy pointer hidden-xs hidden-sm\"\n          className=\"fa text-black fa-copy pointer\"\n          onClick={this.copyToClipboard}\n          data-toggle=\"tooltip\"\n          data-placement=\"top\"\n          title=\"Copiar al portapapeles\"\n          style={{\n            fontSize: '80%'\n          }}\n        />\n      </span>\n    );\n  }\n}\n\nexport default CopyText;\n","import * as React from 'react';\nimport { createRef, RefObject } from 'react';\nimport * as daterangepicker from 'daterangepicker';\n\ninterface IPropsType {\n  options: daterangepicker.Options,\n  startDate: Date,\n  endDate: Date,\n  onChange: (from: Date, to: Date) => void,\n}\n\ninterface IStateType {\n  from: Date,\n  to: Date\n}\n\nclass DateRangeInput extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    from: this.props.startDate,\n    to: this.props.startDate\n  };\n  pickerRef: RefObject<HTMLInputElement> = createRef();\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChange = this.onChange.bind(this);\n  }\n\n  componentDidMount(): void {\n    const { options, startDate, endDate } = this.props;\n    $(this.pickerRef.current!).daterangepicker({ ...options, startDate, endDate }, (from: any, to: any) => {\n      this.onChange(from, to);\n    });\n  }\n\n  onChange = (from: Date, to: Date) => {\n    this.setState({\n      from,\n      to\n    }, () => {\n      this.props.onChange(from, to);\n    });\n  };\n\n  public componentWillUnmount() {\n    $('.daterangepicker').remove();\n  }\n\n  render() {\n    return <div className='input-group input-group-sm'>\n      <input type='text' className='form-control input-sm' ref={this.pickerRef} />\n      <div className='input-group-btn'>\n        <button className='btn btn-default' onClick={() => {\n          ($(this.pickerRef.current!) as any).click();\n        }}>\n          <i className='fa fa-calendar' /></button>\n      </div>\n    </div>;\n  }\n\n}\n\nexport default DateRangeInput;\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  disabled?: any;\n  input?: any;\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePicker extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { format, value, disabled, input } = this.props;\n    let clenedValue = input ? input.value ?? value : value\n    return (\n      <div className='input-group'>\n        <input\n          ref={this.input}\n          type=\"text\"\n          disabled={disabled}\n          value={clenedValue?.toString().length ? moment(clenedValue).format(format ?? 'DD-MM-YY') : ''}\n          className={`form-control ${this.props.className ?? ''}`}\n          onChange={() => {\n          }}\n          style={{ ...this.props.style }}\n        />\n        <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n      </div>\n    );\n  }\n}\n\nexport default DateRangePicker;\n","import * as React from 'react';\nimport {\n  CSSProperties,\n  RefObject\n} from 'react';\n\ninterface IPropsType {\n  url: string;\n  height: string;\n  small?: boolean;\n  style?: React.CSSProperties;\n  replaceLoading?: any;\n}\n\ninterface IStateType {\n  loading: boolean;\n  inViewPort: boolean;\n  error: boolean;\n  eventRuning: boolean;\n  bounding: any;\n  height: any;\n}\n\nclass ImageLazyLoad extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    loading: true,\n    eventRuning: false,\n    inViewPort: false,\n    error: false,\n    bounding: null,\n    height: null\n  };\n\n  private element: RefObject<HTMLDivElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.element = React.createRef();\n    this.handleImageLoaded = this.handleImageLoaded.bind(this);\n    this.isInViewport = this.isInViewport.bind(this);\n    this.addEventListener = this.addEventListener.bind(this);\n    this.removeEventListener = this.removeEventListener.bind(this);\n    this.error = this.error.bind(this);\n  }\n\n  public componentDidMount() {\n    this.addEventListener();\n  }\n\n  public componentWillUnmount() {\n    this.removeEventListener();\n  }\n\n  public render() {\n    const { loading, inViewPort } = this.state;\n    const { url, height, small, style, replaceLoading } = this.props;\n\n    let imageStyle: CSSProperties = {};\n    if (loading) {\n      imageStyle.display = 'none';\n    } else if (style) {\n      imageStyle = style;\n    }\n\n    return (\n      <React.Fragment>\n        {\n          inViewPort ?\n            <img\n              src={url}\n              onLoad={this.handleImageLoaded}\n              onError={this.error}\n              style={imageStyle}\n            /> : null\n        }\n        {\n          loading ?\n            replaceLoading ?\n              <span ref={this.element}>{replaceLoading}</span> :\n              <div\n                style={{\n                  height,\n                  display: 'table-cell',\n                  verticalAlign: 'middle'\n                }}\n                className={'text-center'}\n                ref={this.element}\n              >\n                {\n                  small\n                    ? (\n                      <i className={'fa fa-circle-o-notch fa-spin'} />\n                    )\n                    : (\n                      <i className={'fa fa-circle-o-notch fa-spin fa-2x'} />\n                    )\n                }\n              </div> : null\n        }\n\n      </React.Fragment>\n    );\n  }\n\n  private error() {\n    this.setState({\n      error: true\n    });\n  }\n\n  private handleImageLoaded() {\n    const { url } = this.props;\n    sessionStorage.setItem(url, 'true');\n    this.setState({\n      loading: false\n    });\n  }\n\n  private isInViewport() {\n    if (!this.state.inViewPort && this.element.current) {\n      const bounding = this.element.current.getBoundingClientRect();\n      // start load distance\n      const distance = 300;\n      const clientHeight: number = document && document.documentElement ? document.documentElement.clientHeight : 0;\n      const height = window.innerHeight || clientHeight;\n      const isInViewPort = (\n        bounding.top >= 0 &&\n        bounding.left >= 0 &&\n        (bounding.bottom - distance) <= height\n      );\n\n      if (isInViewPort) {\n        this.removeEventListener();\n        this.setState({\n          inViewPort: true\n        });\n      }\n    }\n  }\n\n  private addEventListener() {\n    this.setState({\n      eventRuning: true\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.addEventListener('scroll', this.isInViewport, false);\n      modal.addEventListener('rezise', this.isInViewport, false);\n      setTimeout(() => {\n        this.isInViewport();\n      }, 1000);\n    } else {\n      window.addEventListener('scroll', this.isInViewport, false);\n      window.addEventListener('rezise', this.isInViewport, false);\n      this.isInViewport();\n    }\n  }\n\n  private removeEventListener() {\n    this.setState({\n      eventRuning: false\n    });\n    // const modal = document.getElementById('andesModal');\n    let modal = ($('#andesModal').data('bs.modal') || {}).isShown;\n    if (modal) {\n      modal = document.getElementById('andesModal');\n      modal.removeEventListener('scroll', this.isInViewport, false);\n      modal.removeEventListener('rezise', this.isInViewport, false);\n    } else {\n      window.removeEventListener('scroll', this.isInViewport, false);\n      window.removeEventListener('rezise', this.isInViewport, false);\n    }\n  }\n}\n\nexport default ImageLazyLoad;\n","import * as Mixpanel from 'mixpanel-browser';\nimport {IUser} from \"../../../../../../src/app/interfaces/user.interface\";\nimport {IWindow} from \"../../interfaces/window\";\n\ndeclare let window: IWindow;\n\nclass MixpanelTracker {\n  private static instance : MixpanelTracker;\n\n  static getInstance() : MixpanelTracker {\n    if (!this.instance)\n      this.instance = new MixpanelTracker();\n    return this.instance;\n  }\n\n  private constructor() {\n    Mixpanel.init(window.MIXPANEL);\n  }\n\n  public trackAction(title: string, properties: any = {}) : void {\n    Mixpanel.track(title, properties);\n  }\n\n  public identifyUser(user : IUser) : void {\n    Mixpanel.register({\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n    Mixpanel.identify(user._id);\n    Mixpanel.people.set( user._id, {\n      '$first_name': user.firstName,\n      '$last_name': user.lastName,\n      '$email': user.email,\n      'team': user.team.name,\n      'team_id': user.team._id,\n      'company': user.company.name,\n      'company_id': user.company._id,\n      'venue': user.venue.name,\n      'venue_id': user.venue._id,\n    });\n  }\n\n}\n\nexport default MixpanelTracker;\n","import axios from 'axios';\nimport * as React from 'react';\nimport { ChangeEvent, DragEvent, ErrorInfo, RefObject } from 'react';\nimport * as uuid from 'uuid';\nimport { getExtension, getIconFromExtension } from '../../utils/common';\nimport Raven = require('raven-js');\nimport ShowIf from './ShowIf';\nimport ApiService from '../../utils/axios';\nimport * as swal from 'sweetalert';\n\n\ninterface IPropsType {\n  onChange: (e: any) => void;\n  deleteCalback?: (e: any) => void;\n  className?: string;\n  body?: any;\n  files: any[];\n  url: string;\n  listMode?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n}\n\nexport enum imageStatus {\n  pending = 'pending',\n  inProgress = 'inProgress',\n  complete = 'complete'\n}\n\nclass MultiUploadFiles extends React.Component<IPropsType, IStateType> {\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly api: ApiService;\n  readonly state = {\n    error: null,\n    canDrop: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.processFile = this.processFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.uploadImages = this.uploadImages.bind(this);\n    this.deleteFile = this.deleteFile.bind(this);\n    this.getSizeText = this.getSizeText.bind(this);\n    this.downloadFile = this.downloadFile.bind(this);\n    this.inputFile = React.createRef();\n    this.api = new ApiService();\n  }\n\n  public downloadFile(file: any) {\n    window.open(file.url, \"_blank\")\n    // this.api.getInstance()({\n    //   url: file.url,\n    //   method: 'GET',\n    //   responseType: 'blob'\n    // })\n    //   .then((response) => {\n    //     const url = window.URL\n    //       .createObjectURL(new Blob([response.data]));\n    //     const link = document.createElement('a');\n    //     link.href = url;\n    //     link.setAttribute('download', file.name);\n    //     document.body.appendChild(link);\n    //     link.click();\n    //     document.body.removeChild(link);\n    //   });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public render() {\n    const { files, listMode, className } = this.props;\n    return (\n      <div className={`multi-upload ${listMode ? 'list-mode' : ''} ${className}`}>\n        <ShowIf condition={!listMode}>\n          {\n            files.map((file) => (\n              <div className='item-container multi-upload-item' key={file?._id ||file.tmpID}>\n                <div\n                  className='delete-button pointer'\n                  onClick={() => this.deleteFile(file?._id ||file.tmpID)}\n                >\n                  <i className='fa fa-minus-circle' />\n                </div>\n                {\n                  file.isImage ?\n                    <img\n                      src={file.url}\n                      className='image-item'\n                      style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                    /> :\n                    <div className='item'>\n                      <div\n                        className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                        style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                      />\n                      <p\n                        className='text-description'\n                        data-toggle='tooltip'\n                        data-placement='top'\n                        title={file.name}\n                        style={{\n                          paddingBottom: 0\n                        }}\n                      >\n                        {file.name}\n                      </p>\n                      <p\n                        className='text-description'\n                        style={{\n                          color: '#9e9e9e',\n                          paddingTop: 0\n                        }}\n                      >{this.getSizeText(file.size)}</p>\n                    </div>\n                }\n                {\n                  file.status === imageStatus.inProgress ?\n                    <div className='multi-upload-progress-bar'>\n                      <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                    </div> : null\n                }\n              </div>\n            ))\n          }\n        </ShowIf>\n        <ShowIf condition={!!listMode}>\n          <div className='border-bottom'>\n            {\n              files.map((file) => (\n                <React.Fragment key={file._id || file?._id ||file.tmpID}>\n                  <div className='row border' style={{margin: 0}}>\n                    {/*<div*/}\n                    {/*  className='delete-button pointer'*/}\n                    {/*  onClick={() => this.deleteFile(file.tmpID)}*/}\n                    {/*>*/}\n                    {/*  <i className='fa fa-minus-circle' />*/}\n                    {/*</div>*/}\n                    {\n                      file.isImage ?\n                        <div className='col-md-2'>\n                          <img\n                            src={file.url}\n                            className='image-item'\n                            style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                          />\n                        </div> :\n                        <div className='col-md-2'>\n                          <div className='item'>\n                            <div\n                              className={`icon-file ${getIconFromExtension(getExtension(file.name))}`}\n                              style={file.status !== imageStatus.complete ? { opacity: 0.5, filter: 'grayscale(100%)' } : undefined}\n                            />\n                          </div>\n                        </div>\n                    }\n                    <div className='col-md-8' style={{ paddingTop: '20px' }}>\n                      {file.name} <br />\n                      <span className={'text-muted text-sm'}>{this.getSizeText(file.size)}</span>\n                    </div>\n                    <div\n                      className='col-md-1 text-right pointer'\n                      onClick={()=> this.downloadFile(file)}\n                      style={{paddingTop: \"25px\"}}>\n                      <i className='fa fa-download text-primary pointer' />\n                    </div>\n                    <div className='col-md-1 text-right pointer' style={{paddingTop: \"25px\"}}  onClick={() => this.deleteFile(file?._id ||file.tmpID)}>\n                      <i className='fa fa-minus-circle text-red' />\n                    </div>\n                    <div className='row'>\n                      <div className='col-md-12'>\n                        {\n                          file.status === imageStatus.inProgress ?\n                            <div className='multi-upload-progress-bar'>\n                              <div className='multi-progress' style={{ width: `${file.progress}%` }} />\n                            </div> : null\n                        }\n                      </div>\n                    </div>\n                  </div>\n                </React.Fragment>\n              ))\n            }\n          </div>\n        </ShowIf>\n        <div\n          className='add-item pointer multi-upload-item'\n          onClick={this.clickUploadFile}\n          onDrop={this.handleDrop}\n          onDragOver={this.dragOverHandler}\n          onDragEnd={this.dragEndHandler}\n          onDragLeave={this.dragLeaveHandler}\n        >\n          <i className='fa fa-2x fa-cloud-upload' /><br />\n          AÑADIR ARCHIVOS\n        </div>\n        <input\n          type='file'\n          ref={this.inputFile}\n          style={{ display: 'none' }}\n          onChange={(e) => this.handleChangeInputFile(e)}\n          accept='.jpeg, .jpg, .png, .doc, .docx, .xls, .xlsx, .pdf'\n          multiple={true}\n        />\n      </div>\n    );\n  }\n\n  private processFile(file: File | any): Promise<any> {\n    const { onChange, files } = this.props;\n    return new Promise((resolve) => {\n      file.tmpID = uuid.v4();\n      file.progress = 0;\n      file.isImage = this.isImage(file.type);\n      file.status = imageStatus.pending;\n      onChange([...files, file]);\n      this.uploadImages();\n      resolve({});\n    });\n  }\n\n  private getSizeText(bytes: number): string {\n    let text = '';\n    if (bytes < 1000000) {\n      text = Math.floor(bytes / 1000) + 'KB';\n    } else {\n      text = Math.floor(bytes / 1000000) + 'MB';\n    }\n    return text;\n  }\n\n  private deleteFile(id: string) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el archivo adjunto.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        const { onChange, files, deleteCalback } = this.props;\n        onChange([...files].filter(file => file.tmpID !== id && file._id !== id));\n        if (deleteCalback) {\n          deleteCalback(id);\n        }\n      }\n    });\n  }\n\n  private uploadImages() {\n    const { onChange, files, url, body} = this.props;\n    const pendingImages: any[] = [];\n    const inProcessImages: any[] = [];\n    if (files.length) {\n      files.forEach((file) => {\n        if (file.status === imageStatus.pending) {\n          pendingImages.push(file);\n        } else if (file.status === imageStatus.inProgress) {\n          inProcessImages.push(file);\n        }\n      });\n    }\n    if (!inProcessImages.length && pendingImages.length) {\n      const imageToUpload = pendingImages[0];\n      let lastPercentage = 0;\n      onChange([...this.props.files].map((file) => {\n        if (file.tmpID === imageToUpload.tmpID) {\n          file.status = imageStatus.inProgress;\n        }\n        return file;\n      }));\n      const instance = axios.create({\n        timeout: 360000,\n        headers: {\n          'Content-Type': 'multipart/form-data'\n        },\n        onUploadProgress: (progressEvent) => {\n          const percentage = (100 / progressEvent.total) * progressEvent.loaded;\n          if (lastPercentage < percentage) {\n            lastPercentage = percentage + 5;\n            // TODO Fix this\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.inProgress;\n                file.progress = percentage;\n              }\n              return file;\n            }));\n          }\n        }\n      });\n      let attempt = 1;\n      const timeout = 1000;\n      const data = new FormData();\n      data.append('file', imageToUpload);\n      if (body) {\n        Object.keys(body).forEach(key => {\n          data.append(key, body[key]);\n        });\n      }\n      instance\n        .post(url, data)\n        .then(response => {\n          onChange([...this.props.files].map((file) => {\n            if (file.tmpID === imageToUpload.tmpID) {\n              file._id = response.data.data._id;\n              file.progress = 100;\n              file.url = decodeURIComponent(response.data.data.file.url);\n              file.status = imageStatus.complete;\n            }\n            return file;\n          }));\n          // dispatch(updateImage(imageToUpload.tempID, 100, statusImages.completed, response.data.id, 1));\n          // dispatch(uploadImages());\n          this.uploadImages();\n        })\n        .catch(err => {\n          Raven.captureMessage(JSON.stringify(err.response), {\n            level: 'info'\n          });\n          if (!axios.isCancel(err)) {\n            Raven.captureException(JSON.stringify(err.response));\n            const waitTime = Math.pow(2, attempt) * timeout;\n            if (waitTime < 16000) attempt = attempt + 1;\n            else attempt = 1;\n            // dispatch(updateImage(imageToUpload.tempID, 0, statusImages.pending, null, attempt));\n            onChange([...this.props.files].map((file) => {\n              if (file.tmpID === imageToUpload.tmpID) {\n                file.status = imageStatus.pending;\n              }\n              return file;\n            }));\n            setTimeout(() => {\n              this.uploadImages();\n            }, waitTime);\n          }\n        });\n    }\n  }\n\n  private isImage(type: string): boolean {\n    const accepted = ['image/jpg', 'image/jpeg', 'image/png'];\n    return accepted.includes(type);\n  }\n\n  private async handleChangeInputFile(e: ChangeEvent<HTMLInputElement>) {\n    const { files } = e.target;\n    if (files && files.length) {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < files.length; i++) {\n        // const file: File | null = dt.items[i].getAsFile();\n        const file: any = files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private handleDrop(e: DragEvent<HTMLDivElement>) {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        // Use  interface to access the file(s)\n        // tslint:disable-next-line: prefer-for-of\n        for (let i = 0; i < dt.items.length; i++) {\n          // const file: File | null = dt.items[i].getAsFile();\n          const file: any = dt.items[i].getAsFile();\n          if (file) {\n            const reader = new FileReader();\n            reader.onload = async (e) => {\n              file.url = e.target!.result;\n              await this.processFile(file);\n            };\n            reader.readAsDataURL(file);\n          }\n        }\n      }\n    } else {\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.files.length; i++) {\n        const file: any = dt.files[i];\n        if (file) {\n          const reader = new FileReader();\n          reader.onload = async (e) => {\n            file.url = e.target!.result;\n            await this.processFile(file);\n          };\n          reader.readAsDataURL(file);\n        }\n      }\n    }\n    // clear input file\n    this.inputFile.current!.value = '';\n  }\n\n  private dragOverHandler(e: DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      // tslint:disable-next-line: prefer-for-of\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n}\n\nexport default MultiUploadFiles;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\n\ninterface IPropsType {\n  page: number;\n  pages: number;\n  changePage: (page: number) => void;\n}\n\nconst Paginator: React.FunctionComponent<IPropsType> = (props) => {\n  const {page, pages, changePage} = props;\n  return (\n    <ul className=\"pagination pagination-sm\">\n      {\n        new Array(pages).fill(1).map((item, index) => {\n          const key = index + 1;\n          const onClick = key !== page ? () => changePage(key) : undefined;\n          if ((key > page - 3 && key < page + 3) || (key === 1 || key === pages)) {\n            return (\n              <li className={`page-item ${key === page ? 'active' : ''}`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\" onClick={onClick}>{key}</a>\n              </li>\n            );\n          }\n          if (key >= page + 3 && key === pages - 1) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else if (key <= page - 3 && key === 2) {\n            return (\n              <li className={`page-item disabled`} key={key}>\n                <a className=\"page-link\" href=\"javascript:void(0)\">...</a>\n              </li>\n            );\n          } else {\n            return null;\n          }\n        })\n      }\n    </ul>\n  );\n};\n\nPaginator.propTypes = {\n  page: PropTypes.number.isRequired,\n  pages: PropTypes.number.isRequired,\n  changePage: PropTypes.func.isRequired\n};\n\nexport default Paginator;\n","import * as React from 'react';\n\ninterface IPropsType {\n  className?: string;\n  children?: React.ReactNode;\n  style?: React.CSSProperties;\n}\n\nconst Row: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  return (\n    <div\n      className={`row${props.className && props.className.length ? ` ${props.className}` : ''}`}\n      style={props.style ? props.style : {}}\n    >\n      {props.children}\n    </div>\n  );\n};\n\nexport default Row;\n","import * as React from 'react';\n\ninterface IPropsType {\n  condition: boolean;\n  children?: React.ReactNode;\n  alternative?: React.ReactNode;\n}\n\nconst ShowIf: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  if (props.condition) {\n    return (\n      <>{props.children}</>\n    );\n  }\n  if (props.alternative) {\n    return (\n      <>{props.alternative}</>\n    );\n  }\n  return null;\n};\n\nexport default ShowIf;\n","import TrackingBasePage from \"./TrackingBasePage\";\nimport * as React from \"react\";\n\nexport enum Actions {\n  edit = 'edit',\n  delete = 'delete',\n}\n\nexport interface IHeaderAccessor {\n  name: string,\n  accessor:(datum: any) => string,\n}\n\nexport interface IPropsType {\n  headers: IHeaderAccessor[];\n  actions: Actions[];\n  data: {name: string}[];\n  name: string;\n  editElement? : (value: any) => void;\n  deleteElement? : (value: any) => void;\n}\n\nexport default class TableListView extends TrackingBasePage<IPropsType, any> {\n  title: string\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = `${props.name.toUpperCase()}`\n  }\n\n\n  public render() : React.ReactElement<IPropsType> {\n    const {headers, actions, data, name, editElement, deleteElement} = this.props;\n    let columnWidth = 95/headers.length;\n\n    let editElementWrapper = editElement ?? (value => {return;});\n    let deleteElementWrapper = deleteElement ?? (value => {return;});\n\n    return <div className='box-body no-padding'>\n      <table className='table table-andes table-striped'>\n        <thead>\n        <tr>\n          {headers.map(h =>\n            <th key={h.name} style={{ width: `${columnWidth}%` }} className='middle'>{h.name}</th>\n          )}\n          {\n            actions.includes(Actions.edit) ?\n              <th style={{ width: '1%' }} className='width-10' /> : null\n          }\n          {\n            actions.includes(Actions.delete) ?\n              <th style={{ width: '1%' }} className='width-10' /> : null\n          }\n        </tr>\n        </thead>\n        <tbody>\n        {\n          data.map((value: any) => {\n            let cols = headers.map(h =>\n              <td\n                id={`${name}-${h.name}-`}\n                key={`${name}-${h.name}`}\n                className='middle'>\n                  <strong className='text-primary'>\n                    {h.accessor(value)?.toUpperCase()}\n                  </strong>\n              </td>\n            );\n            return <tr\n              key={value._id}\n              id={`${name}-${value._id}`}\n              className={'background-transition'}\n            >{cols}{\n                actions.includes(Actions.edit) ?\n                  <td\n                    className='middle text-blue pointer'\n                    onClick={() => editElementWrapper(value)}>\n                    <i className='fa fa-pencil' />\n                  </td> : null\n              }{\n                actions.includes(Actions.delete) ?\n                  <td\n                    className='middle text-red pointer'\n                    onClick={() => deleteElementWrapper(value)}\n                  >\n                    <i className='fa fa-minus-circle' />\n                  </td> : null\n              }</tr>;\n          })\n        }\n        </tbody>\n      </table>\n    </div>;\n  }\n}\n","import * as React from 'react';\nimport { IWindow } from '../../interfaces/window';\nimport MixpanelTracker from './MixpanelTracker';\nimport * as ReactGA from 'react-ga';\n\ndeclare let window: IWindow;\n\nabstract class TrackingBasePage<PropsType, StateType> extends React.Component<PropsType, StateType> {\n  abstract title: string;\n\n  protected constructor(props: PropsType) {\n    super(props);\n    this.trackPage = this.trackPage.bind(this);\n    this.registerUser = this.registerUser.bind(this);\n    this.shouldTrack = this.shouldTrack.bind(this);\n    this.componentDidMount = this.componentDidMount.bind(this);\n    this.trackClick = this.trackClick.bind(this);\n  }\n\n  public componentDidMount(): void {\n    // set the title of the page\n    document.title = `OSA Andes | ${this.title}`;\n    if (process.env.NODE_ENV === 'production') {\n      this.registerUser();\n      this.trackPage();\n    }\n  }\n\n  trackPage(): void {\n    // console.log('trackPage');\n    // if (this.shouldTrack()){\n\n\n    ReactGA.pageview(`${window.location.pathname}${window.location.search ?? ''}`, ['tracker'], this.title);\n    // ReactGA.event({\n    //   category: 'Navegation',\n    //   action: this.title\n    // }, ['tracker']);\n    MixpanelTracker.getInstance().trackAction(this.title);\n    // }\n  }\n\n  trackClick(title: string, properties: any = {}): void {\n    if (this.shouldTrack())\n      MixpanelTracker.getInstance().trackAction(`${this.title} - ${title}`, properties);\n  }\n\n  public shouldTrack(): boolean {\n    return true\n    // return !window.user.email.includes('@osacontrol.com');\n  }\n\n  private registerUser(): void {\n    if (this.shouldTrack() && !window.isTracked) {\n      MixpanelTracker.getInstance().identifyUser(window.user);\n      window.isTracked = true;\n    }\n  }\n}\n\nexport default TrackingBasePage;\n","import * as React from \"react\";\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst BootstrapSwitchField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group-switch\">\n    <label className={`switch switch-blue`}>\n      <input type='checkbox' className='switch' {...input} checked={checked} />\n      <span className=\"slider round\" />\n    </label>\n    <label className=\"switch-label\">{label}</label>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default BootstrapSwitchField;\n\n\n\n","import * as React from 'react';\nimport {RefObject} from 'react';\nimport * as unorm from 'unorm';\nimport {WrappedFieldProps} from \"redux-form/lib/Field\";\n\ninterface IOption {\n  value: string;\n  text: any;\n  className?: string;\n}\n\ninterface IPropsType extends WrappedFieldProps {\n  options: IOption[];\n  labelOff?:boolean;\n  className?: string;\n  disabled?:boolean;\n  right?:boolean;\n  displayItems?: number;\n  onClick: (value: string) => void;\n  selectAll?: any;\n  noneSelectedText?: string;\n  selectedText?: string;\n  separator?: string;\n  allOption?: boolean;\n  autoClouse?: boolean;\n  search?: boolean;\n  sm?: boolean;\n  label: string;\n}\n\ninterface IStateType {\n  open: boolean;\n  searchText: string;\n}\n\nclass BootstrapSelectField extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    open: false,\n    searchText: ''\n  };\n\n  readonly input: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerOpen = this.handlerOpen.bind(this);\n    this.search = this.search.bind(this);\n    this.input = React.createRef();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      sm,\n      options,\n      onClick,\n      displayItems,\n      noneSelectedText,\n      selectedText,\n      separator,\n      allOption,\n      search,\n      autoClouse,\n      selectAll,\n      label,\n      disabled,\n      right,\n      input,\n      labelOff,\n      meta: {touched, error, warning}\n    } = this.props;\n    const {searchText} = this.state;\n    const selectedItems = options.filter((option) => (input.value.includes(option.value)));\n    // console.log('onClick', onClick)\n    return (\n      <div className={`form-group ${touched && error ? \"has-error\" : \"\"} ${touched && warning ? \"has-warning\" : \"\"}`}>\n        {!labelOff?<label className=\"control-label text-ellipsis\">{label}</label>: null}\n        <div\n          className={`dropdown bootstrap-select form-control show-tick ${autoClouse ? '' : 'keep-inside-clicks-open'} ${sm ? 'bootstrap-select-sm' : ''}`} >\n          <button\n            type=\"button\"\n            className={`btn dropdown-toggle bs-placeholder btn-filter btn-default`}\n            data-toggle=\"dropdown\"\n            disabled={disabled}\n            style={{borderRadius: '0px', borderColor: touched && error ? '#dd4b39' : '', padding: '6px 12px 5px 5px'}}\n            onClick={this.handlerOpen}\n          >\n            <div className=\"filter-option\">\n              <div className=\"filter-option-inner\">\n                <div className=\"filter-option-inner-inner text-ellipsis\">\n                  {\n                    selectedItems.length ?\n                      displayItems && selectedItems.length > displayItems ?\n                        <span style={{color: '#555'}}>{`${selectedItems.length} ${selectedText ? selectedText : 'items seleccionados.'}`}</span> :\n                        selectedItems\n                          .map((option, index) => (\n                            <React.Fragment key={index}>\n                            <span\n                              className={option.className ? option.className : ''}\n                              style={{color: '#555'}}\n                            >{option.text}</span> {selectedItems.length > index + 1 ? separator ? `${separator}` : ', ' : null}\n                            </React.Fragment>\n                          ))\n                      : noneSelectedText ?\n                      <span style={{color: touched && error ? \"#dd4b39\" : '#999'}}> {noneSelectedText}</span> : <span style={{color: '#999'}}> Todos </span>\n                  }\n                </div>\n              </div>\n            </div>\n            <span className=\"bs-caret\" style={{color: touched && error ? \"#dd4b39\" : undefined}}>\n            <span className=\"caret\"/>\n          </span>\n          </button>\n          <div className={`dropdown-menu ${right?'dropdown-menu-right':''}`} style={{borderRadius: '0px'}}>\n            {\n              search ?\n                <div className=\"bs-searchbox\">\n                  <input\n                    ref={this.input}\n                    type=\"text\"\n                    className=\"form-control input-sm\"\n                    autoComplete=\"off\"\n                    value={this.state.searchText}\n                    onChange={\n                      (e: React.ChangeEvent<HTMLInputElement>) => this.search(e.target.value)\n                    }\n                  />\n                </div> : null\n            }\n            {\n              allOption ?\n                <div className=\"bs-actionsbox\">\n                  <div className=\"btn-group btn-group-sm btn-block\">\n                    <button\n                      onClick={() => selectAll(true)}\n                      type=\"button\" className=\"actions-btn bs-select-all btn btn-default\">Seleccionar todo\n                    </button>\n                    <button\n                      onClick={() => selectAll(false)}\n                      type=\"button\" className=\"actions-btn bs-deselect-all btn btn-default\">Deseleccionar todo\n                    </button>\n                  </div>\n                </div> : null\n            }\n            <div\n              className=\"inner open\"\n              aria-expanded=\"false\"\n              tabIndex={-1}\n            >\n              <ul className=\"dropdown-menu inner\" style={{maxHeight: '20vh', overflowY: 'auto'}}>\n                {\n                  options.filter((option) => {\n                    if (!searchText || !searchText.length) {\n                      return true;\n                    }\n                    return unorm.nfd(option.text)\n                      .replace(/[\\u0300-\\u036f]/g, '')\n                      .toLowerCase()\n                      .includes(searchText.toLowerCase());\n                  }).map((option) => {\n                    const isSelected = input.value.includes(option.value);\n                    return (\n                      <li key={option.value} className={`${isSelected ? 'selected' : ''}`} onClick={() => onClick(option.value)}>\n                        <a role=\"option\" tabIndex={0} className={`${isSelected ? 'selected' : ''}`} style={{background: '#FFF'}}>\n                          <span className=\"glyphicon glyphicon-ok check-mark\"/>\n                          <span className={option.className ? option.className : ''}>{option.text}</span>\n                        </a>\n                      </li>\n                    );\n                  })\n                }\n              </ul>\n            </div>\n          </div>\n        </div>\n        {\n          touched &&\n          ((error && <span className=\"help-block text-ellipsis\">{error}</span>) ||\n            (warning && <span className=\"help-block text-ellipsis\">{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n        }\n      </div>\n    );\n  }\n\n  private handlerOpen() {\n    // if (this.input.current) {\n    //   this.input.current.focus()\n    // }\n    this.setState({\n        open: !this.state.open\n      }, () => {\n        if (!this.state.open) {\n          this.search('');\n        }\n      }\n    );\n  }\n\n  private search(searchText: string) {\n    this.setState({\n      searchText: unorm.nfd(searchText).replace(/[\\u0300-\\u036f]/g, '')\n    });\n  }\n}\n\nexport default BootstrapSelectField;\n","import * as React from 'react';\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  checked: boolean;\n  label: string;\n  type: string;\n  help: string;\n  style: any;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\nconst CheckBoxField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  checked,\n  style={},\n  type,\n  help,\n  meta: { touched, error, warning }\n}:IPropsType) => (\n  <div className=\"form-group\" style={style}>\n    <div className=\"form-check\">\n      <input type={type} className=\"form-check-input\" checked={checked} {...input}  />\n      <label className=\"form-check-label\" style={{marginLeft: '5px'}}> {label}</label>\n    </div>\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"error invalid-feedback\">{error}</span>) ||\n        (warning && <span className=\"warning warning-feedback\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default CheckBoxField;\n\n\n\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { CSSProperties, InputHTMLAttributes, RefObject } from 'react';\n\ninterface IPropsType {\n  onChange?: (e: moment.Moment | null) => void;\n  input: InputHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n  className?: string;\n  format?: string;\n  style?: CSSProperties;\n  value?: any;\n  startDate?: any\n  todayHighlight?: boolean\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DateRangePickerField extends React.Component<IPropsType, IStateType> {\n\n  readonly input: RefObject<HTMLInputElement>;\n  readonly inputGroup: RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.input = React.createRef();\n    this.inputGroup = React.createRef();\n    this.clickCalendar = this.clickCalendar.bind(this);\n  }\n\n  public componentDidMount() {\n    const { format } = this.props;\n    $(this.input.current!).datepicker({\n      autoclose: true,\n      language: 'es',\n      todayHighlight: !!this.props.todayHighlight,\n      orientation: 'bottom auto',\n      clearBtn: true,\n      startDate: this.props.startDate,\n      format: {\n        toDisplay: (date) => {\n          return moment(date).utc().format(format ?? 'DD-MM-YY');\n        },\n        toValue: (date) => {\n          return moment(date, format ?? 'DD-MM-YY').utc().toDate();\n        }\n      }\n    });\n    $(this.input.current!).on('changeDate', () => {\n      if (typeof (this.props.onChange) === 'function') {\n        const date = moment(this.input.current!.value, format ?? 'DD-MM-YY', true);\n        if (date.isValid()) {\n          this.props.onChange(date);\n        } else {\n          this.props.onChange(null);\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount() {\n    $(this.input.current!).datepicker('destroy');\n  }\n\n  private clickCalendar() {\n    $(this.input.current!).datepicker('show');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      format, input,\n      label,\n      labelOff,\n      placeholder,\n      type,\n      help,\n      meta: { touched, error, warning }\n    } = this.props;\n    return (\n      <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n        {!labelOff ? <label className='control-label  text-ellipsis'>{label}</label> : null}\n        <div className='input-group'>\n          <input\n            ref={this.input}\n            type='text'\n            value={input.value?.toString().length ? moment(input.value as string).format(format ?? 'DD-MM-YY') : ''}\n            className={`form-control ${this.props.className ?? ''}`}\n            onClick={this.clickCalendar}\n            onChange={() => {\n            }}\n            style={{ ...this.props.style }}\n          />\n          <span className='input-group-addon pointer' onClick={this.clickCalendar}>\n          <i className='fa fa-calendar' />\n        </span>\n        </div>\n        {\n          touched &&\n          ((error && <span className='help-block'>{error}</span>) ||\n            (warning && <span className='help-block'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n        }\n      </div>\n    );\n  }\n}\n\nexport default DateRangePickerField;\n","import * as React from 'react';\n\ninterface IPropsType {\n  input: any;\n  label: string;\n  labelOff?: boolean;\n  readOnly?: boolean;\n  onChange?: any;\n  type: string;\n  help: string;\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst InputField: React.FunctionComponent<IPropsType> = ({\n   input,\n   label,\n   labelOff,\n   placeholder,\n   type,\n   onChange,\n   readOnly,\n   help,\n   meta: { touched, error, warning }\n  }: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff ? <label className='control-label text-ellipsis'>{label}</label> : null}\n    <input\n      {...input}\n      readOnly={readOnly}\n      onChange={onChange ? onChange : input.onChange}\n      className={`form-control input-sm`}\n      placeholder={placeholder}\n      type={type}\n    />\n    {\n      help ?\n        <small id='passwordHelpBlock' className='form-text text-muted'>\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className='help-block text-ellipsis'>{error}</span>) ||\n        (warning && <span className='help-block text-ellipsis'>{warning}</span>)) || <span className='help-block'>&nbsp;</span>\n    }\n  </div>\n);\n\nexport default InputField;\n","import * as React from 'react';\nimport { DetailedHTMLFactory, InputHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: DetailedHTMLFactory<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement>;\n  type: string;\n}\n\nconst InputHiddenField: React.FunctionComponent<IPropsType> = ({ input, type }: IPropsType) => (\n    <input\n      {...input}\n      type={type}\n    />\n);\n\nexport default InputHiddenField;\n","import * as React from 'react';\nimport { SelectHTMLAttributes } from 'react';\n\ninterface IPropsType {\n  input: SelectHTMLAttributes<any>;\n  label: string;\n  children: React.ReactNode;\n  disabled?: boolean;\n  labelOff?: boolean;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  };\n}\n\nconst SelectField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  children,\n  disabled,\n  labelOff,\n  meta: { touched, error, warning }\n}: IPropsType) => {\n  return (\n    <div className={`form-group ${touched && error ? 'has-error' : ''} ${touched && warning ? 'has-warning' : ''}`}>\n      {!labelOff ? <label className='control-label text-ellipsis'>{label}</label> : null}\n      <select\n        {...input}\n        className={`form-control input-sm ${touched && error ? 'is-invalid' : warning ? 'is-warning' : ''}`}\n        disabled={disabled}\n        placeholder={label}\n      >\n        {children}\n      </select>\n      {\n        touched &&\n        ((error && <span className='help-block'>{error}</span>) ||\n          (warning && <span className='help-block'>{warning}</span>)) || <span className=\"help-block\">&nbsp;</span>\n      }\n    </div>\n  );\n};\n\nexport default SelectField;\n","import * as React from \"react\";\nimport { TextareaHTMLAttributes} from \"react\";\nimport {Property} from \"csstype\";\ninterface IPropsType {\n  input: TextareaHTMLAttributes<any>\n  label: string;\n  labelOff?:boolean;\n  resize: Property.Resize;\n  type: string\n  help: string\n  placeholder: string;\n  meta: {\n    touched: boolean;\n    error: string;\n    warning: string;\n  }\n}\nconst TextAreaField: React.FunctionComponent<IPropsType> = ({\n  input,\n  label,\n  labelOff,\n  placeholder,\n  help,\n  resize,\n  meta: { touched, error, warning },\n  ...custom\n}: IPropsType) => (\n  <div className={`form-group ${touched && error ? 'has-error' : warning ? 'has-warning' : ''}`}>\n    {!labelOff?<label className=\"control-label\">{label}</label>: null}\n    <textarea\n      {...input}\n      {...custom}\n      style={{\n        resize: resize ? resize : 'inherit'\n      }}\n      className={`form-control`}\n      placeholder={placeholder}\n    />\n    {\n      help ?\n        <small id=\"passwordHelpBlock\" className=\"form-text text-muted\">\n          {help}\n        </small>\n        : null\n    }\n    {\n      touched &&\n      ((error && <span className=\"help-block\">{error}</span>) ||\n        (warning && <span className=\"help-block\">{warning}</span>))\n    }\n  </div>\n);\n\nexport default TextAreaField;\n","const inputStringRequired = (value: string) => (value && value.toString().trim().length ? undefined : 'Este campo es requerido');\nconst validEmailRequired = (value: string) => /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\\.[A-Z]{2,4}$/i.test(value) ? undefined : 'Este email no es valido';\nconst maxNumber = (max: number) => (value: number) => max < value ? `Debe ser menor a ${max}` : undefined;\nexport {\n  inputStringRequired,\n  validEmailRequired,\n  maxNumber\n};\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IBaseVenue, IVenue} from '../../../../../../src/app/interfaces/venue.interface';\nimport {changeTempVenueAction, getVenueUsersAction, IVenuesState, VenueReduxAction} from '../../actions/venues.actions';\nimport {updateTooltip} from '../../utils/common';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Checkbox from '../Utils/CheckBox';\nimport {IVenueDay} from '../../../../../../src/app/interfaces/venueDay.interface';\n\ninterface IPropsType {\n  venues?: IVenuesState;\n  update?: boolean;\n  changeTempVenueAction?: (venue: IBaseVenue, noDelay?: boolean) => VenueReduxAction;\n  getVenueUsersAction? : (page:number, venue: IVenue) => VenueReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass VenueFormView extends React.Component<IPropsType, IStateType> {\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeTypeAction = this.changeTypeAction.bind(this);\n    this.handleSelectVenues = this.handleSelectVenues.bind(this);\n    this.handleSelectResponsible = this.handleSelectResponsible.bind(this);\n  }\n\n  public componentDidMount(): void {\n    const chosenOptions = {\n      no_results_text: 'Sin resultados para:'\n    };\n    updateTooltip();\n  }\n\n  public componentDidUpdate(prevProps:Readonly<IPropsType>, prevState:Readonly<IStateType>, snapshot?:any): void {\n    updateTooltip();\n    if (prevProps.venues?.tempVenue._id != this.props.venues?.tempVenue._id)\n        this.props.getVenueUsersAction?.(1, this.props.venues?.tempVenue as IVenue)\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction, update} = this.props;\n      const {tempVenue, companies, carriers, regions, users} = this.props.venues;\n      let {allVenues} = this.props.venues;\n      if (update) {\n        allVenues = allVenues.filter((venue) => venue._id !== tempVenue._id);\n      }\n      return (\n        <React.Fragment>\n          <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n            <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n            {tempVenue.sendToDays.length > 0 ? <li><a data-toggle=\"tab\" href=\"#diasSucursales\">Tiempos de despacho</a></li> : null}\n          </ul>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          name: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Código</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.code}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          code: e.target.value\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Abreviación</label>\n                    <input\n                      type=\"text\"\n                      name=\"abbreviation\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={10}\n                      value={tempVenue.abbreviation || ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          abbreviation: e.target.value.toUpperCase()\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Latitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lat}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lat: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Longitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempVenue.lng}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempVenueAction({\n                          ...tempVenue,\n                          lng: parseFloat(e.target.value)\n                        }, true)\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Empresa</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      search={true}\n                      options={\n                        companies\n                          .map((company) => ({\n                            value: company._id,\n                            text: company.name\n                          }))\n                      }\n                      selected={tempVenue.company ? [tempVenue.company._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        company: companies.find((company) => (company._id === value))\n                      }, true)}\n                    />\n                  </div>\n                  {\n                    update ?\n                      <div className=\"alert alert-warning alert-dismissible\">\n                        Si se modifica la empresa, los usuarios asignados a esta sucursal también se verán afectados.\n                      </div> : null\n                  }\n                </div>\n                {update? <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Encargados de local\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"Usuarios seleccionados.\"\n                      selected={tempVenue.responsible.map((user) => user._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectResponsible(true, value)}\n                      options={users.map((user: any) => ({\n                        value: user._id,\n                        text: `${user.firstName} ${user.lastName}`\n                      }))}\n                      onClick={(value: string) => this.handleSelectResponsible(false, value)}\n                    />\n                  </div>\n                </div> : null }\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Región</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      options={\n                        regions\n                          .map((region) => ({\n                            value: region._id,\n                            text: region.name\n                          }))\n                      }\n                      selected={tempVenue.region ? [tempVenue.region._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempVenueAction({\n                        ...tempVenue,\n                        region: regions.find((region) => (region._id === value))\n                      }, true)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Envia <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden enviar a estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.sendToDays.map((venueDay) => venueDay.venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenuesSendToDays( true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        rend: <><strong>{venue.company.name.toUpperCase()}</strong> {venue.name.toUpperCase()}</>,\n                        text: `${venue.company.name.toUpperCase()} ${venue.name.toUpperCase()}`\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenuesSendToDays(false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de envio <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal pueden enviar de estos transportista.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"transportistas seleccionadas.\"\n                      selected={tempVenue.shippingCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('shippingCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('shippingCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Recibe <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\"\n                      data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal, pueden recepcionar de estas sucursales.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={tempVenue.receiveFrom.map((venue) => venue._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectVenues('receiveFrom', true, value)}\n                      options={allVenues.map((venue: any) => ({\n                        value: venue._id,\n                        rend: <><strong>{venue.company.name.toUpperCase()}</strong> {venue.name.toUpperCase()}</>,\n                        text: `${venue.company.name.toUpperCase()} ${venue.name.toUpperCase()}`\n                      }))}\n                      onClick={(value: string) => this.handleSelectVenues('receiveFrom', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"venues\" className=\"control-label\">\n                      Transportistas de recepción <i\n                      className=\"fa fa-info-circle text-black\"\n                      data-toggle=\"tooltip\" data-placement=\"top\"\n                      title=\"Usuarios asignados a esta sucursal pueden recepcionar de estos transportistas.\"\n                    />\n                    </label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      displayItems={2}\n                      search={true}\n                      selectedText=\"transportistas seleccionadas.\"\n                      selected={tempVenue.receptionCarriers.map((carrier) => carrier._id)}\n                      allOption={true}\n                      selectAll={(value: boolean) => this.handleSelectCarriers('receptionCarriers', true, value)}\n                      options={carriers.map((carrier: any) => ({\n                        value: carrier._id,\n                        text: carrier.name\n                      }))}\n                      onClick={(value: string) => this.handleSelectCarriers('receptionCarriers', false, value)}\n                    />\n                  </div>\n                </div>\n                <div className=\"col col-md-12\">\n                  <div className=\"checkbox\">\n                    <label style={{paddingLeft: '0'}} onClick={this.changeTypeAction}>\n                      <Checkbox active={tempVenue.type === 'distributor'} action={this.changeTypeAction}\n                                classes=\"icheck-in-checkbox\"/>\n                      <span\n                        style={{\n                          paddingLeft: '5px',\n                          top: '2px',\n                          position: 'relative'\n                        }}\n                      >\n                        Distribuidor <i\n                        className=\"fa fa-info-circle\"\n                        data-toggle=\"tooltip\"\n                        data-placement=\"top\"\n                        title=\"Activa funcionalidades a la sucursal.\"\n                      />\n                </span>\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            { tempVenue.sendToDays.length > 0 ? <div id=\"diasSucursales\" className=\"tab-pane fade\">\n              { tempVenue.sendToDays.map( (venueDay: IVenueDay) => {\n                const venueIndex = tempVenue.sendToDays.findIndex(v => v.venue._id === venueDay.venue._id);\n                  return <div className=\"row\" key={venueDay.venue._id}>\n                    <div className=\"col-md-12\">\n                      <div className=\"form-group\">\n                        <label>{tempVenue.name} - {venueDay.venue.name}</label>\n                        <input\n                          type=\"number\"\n                          name={venueDay.venue._id}\n                          step=\"any\"\n                          className=\"form-control\"\n                          min={1}\n                          value={venueDay.shippingMaxDays || ''}\n                          onChange={\n                            (e: React.ChangeEvent<HTMLInputElement>) => {\n                              tempVenue.sendToDays[venueIndex].shippingMaxDays = parseInt(e.target.value);\n                              changeTempVenueAction(tempVenue, true);\n                            }\n                          }\n                        />\n                      </div>\n                    </div>\n                  </div>;\n                }\n              )}\n            </div> : null}\n          </div>\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private handleSelectVenuesSendToDays(all: boolean, value: string | boolean){\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values : IVenueDay[]= [];\n      if (all) {\n        values = value ? allVenues.map((venue: IVenue) => {\n          return {_id: null, shippingMaxDays : undefined, venue};}) :\n          [];\n      } else {\n        const add = tempVenue.sendToDays.find((venueDay : IVenueDay) => venueDay.venue._id === value) === undefined;\n        const venueDay : IVenueDay = {\n          _id: null,\n          venue:allVenues.find((venue) => venue._id === value)!,\n          shippingMaxDays: undefined\n        };\n        if (add) {\n          values = [...tempVenue.sendToDays, venueDay];\n        } else {\n          values = tempVenue.sendToDays.filter((venueDay) => venueDay.venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        sendToDays: values\n      }, true);\n    }\n\n  }\n  private handleSelectResponsible(all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, users} = this.props.venues;\n      if (all) {\n        this.props.changeTempVenueAction({\n          ...tempVenue,\n          responsible: value ? users : []\n        }, true);\n      } else {\n        let new_user = users.find(u => u._id === value)\n        if (new_user)\n          this.props.changeTempVenueAction({\n            ...tempVenue,\n            responsible: tempVenue.responsible.concat([new_user])\n          }, true);\n      }\n    }\n  }\n\n  private handleSelectVenues(where: 'receiveFrom' | 'sendTo', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, allVenues} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? allVenues : [];\n      } else {\n        const add = tempVenue[where].find((venue) => venue._id === value) === undefined;\n        const venue = allVenues.find((venue) => venue._id === value);\n        if (add) {\n          values = [...tempVenue[where], venue];\n        } else {\n          values = tempVenue[where].filter((venue) => venue._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n  private handleSelectCarriers(where: 'shippingCarriers' | 'receptionCarriers', all: boolean, value: string | boolean) {\n    if (this.props.changeTempVenueAction && this.props.venues) {\n      const {tempVenue, carriers} = this.props.venues;\n      let values = [];\n      if (all) {\n        values = value ? carriers : [];\n      } else {\n        const add = tempVenue[where].find((carrier) => carrier._id === value) === undefined;\n        const carrier = carriers.find((carrier) => carrier._id === value);\n        if (add) {\n          values = [...tempVenue[where], carrier];\n        } else {\n          values = tempVenue[where].filter((carrier) => carrier._id !== value);\n        }\n      }\n      this.props.changeTempVenueAction({\n        ...tempVenue,\n        [where]: values\n      }, true);\n    }\n  }\n\n  private changeTypeAction() {\n    if (this.props.venues && this.props.changeTempVenueAction) {\n      const {changeTempVenueAction} = this.props;\n      const {tempVenue} = this.props.venues;\n      changeTempVenueAction({\n        ...tempVenue,\n        type: tempVenue.type === 'receiver' ? 'distributor' : 'receiver'\n      }, true);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempVenueAction: (venue: IBaseVenue, noDelay?: boolean) => dispatch(changeTempVenueAction(venue, noDelay)),\n    getVenueUsersAction: (page: number, venue: IVenue) => dispatch(getVenueUsersAction(page, venue))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VenueFormView);\n","import { default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as mapboxgl from 'mapbox-gl';\nimport ApiService from '../../utils/axios';\nimport {\n  IBaseVenue,\n  IVenue\n} from '../../../../../../src/app/interfaces/venue.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport {\n  changeFilterAction,\n  changeSearchAction,\n  changeTempVenueAction,\n  createVenueAction,\n  deleteVenueAction,\n  getVenuesAction,\n  IVenuesState,\n  updateVenueAction,\n  VenueReduxAction\n} from '../../actions/venues.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport VenueFormView from './VenueFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { debounce } from 'throttle-debounce';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport CopyText from '../Utils/CopyText';\nimport Row from '../Utils/Row';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<VenueReduxAction>;\n  venues: IVenuesState;\n\n  getVenuesAction(page: number): VenueReduxAction;\n\n  createVenueAction(): VenueReduxAction;\n\n  updateVenueAction(): VenueReduxAction;\n\n  deleteVenueAction(id?: string): VenueReduxAction;\n\n  changeTempVenueAction(venue: IBaseVenue): VenueReduxAction;\n\n  changeFilterAction(filter: string, value: string): VenueReduxAction;\n\n  changeSearchAction(searchText: string): VenueReduxAction;\n\n  loadDataAction(\n    title: string,\n    body: JSX.Element,\n    footer: JSX.Element\n  ): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporting: boolean;\n  tab: string;\n}\n\ndeclare let window: IWindow;\n\nclass VenuesListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  private map: any;\n  readonly state: IStateType = {\n    error: null,\n    exporting: false,\n    tab: 'list'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de sucursales';\n    this.changePage = this.changePage.bind(this);\n    this.createVenue = this.createVenue.bind(this);\n    this.processCreateVenue = this.processCreateVenue.bind(this);\n    this.updateVenue = this.updateVenue.bind(this);\n    this.processUpdateVenue = this.processUpdateVenue.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.onChangeTab = this.onChangeTab.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.changeTab = this.changeTab.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.filterCompany = this.filterCompany.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  private changeTab(name: string): void {\n    // const { id } = this.props.match.params;\n    // if (name === 'detail') {\n    //   this.props.history.replace(`/inventory/${id}/detail/`);\n    // } else {\n    //   this.props.history.replace(`/inventory/${id}/`);\n    // }\n    this.setState(\n      {\n        tab: name\n      },\n      this.onChangeTab\n    );\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.venues;\n    this.props.getVenuesAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `venue-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const { pagination } = this.props.venues;\n        this.props.getVenuesAction(pagination.page);\n      }\n    });\n  }\n\n  public exportExcel() {\n    this.setState({\n      exporting: true\n    });\n    this.trackClick('Exportar');\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/settings/venues/export-access/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format(\n          'YYYYMMDD'\n        )}-acceso-sucursales.xlsx`;\n        // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n        //   // IE workaround for \"HTML7007: One or more blob URLs were\n        //   // revoked by closing the blob for which they were created.\n        //   // These URLs will no longer resolve as the data backing\n        //   // the URL has been freed.\"\n        //   window.navigator.msSaveBlob(blob, fileName);\n        // } else {\n        const blobURL = URL.createObjectURL(blob);\n        const tempLink = document.createElement('a');\n        tempLink.style.display = 'none';\n        tempLink.href = blobURL;\n        tempLink.setAttribute('download', fileName);\n        // Safari thinks _blank anchor are pop ups. We only want to set _blank\n        // target if the browser does not support the HTML5 download attribute.\n        // This allows you to download files in desktop safari if pop up blocking\n        // is enabled.\n        if (typeof tempLink.download === 'undefined') {\n          tempLink.setAttribute('target', '_blank');\n        }\n        this.setState({\n          exporting: false\n        });\n        document.body.appendChild(tempLink);\n        tempLink.click();\n        document.body.removeChild(tempLink);\n        URL.revokeObjectURL(blobURL);\n        // }\n      })\n      .catch((err) => {\n        this.setState({\n          exporting: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal(\n            'Exportar usuarios',\n            'Ha ocurrido un error al general el excel.',\n            'error'\n          );\n        }\n      });\n  }\n\n  private onChangeTab() {\n    const { allVenues: venues } = this.props.venues;\n\n    const geojson = {\n      type: 'FeatureCollection',\n      features: venues\n        .filter((venue) => venue.lng && venue.lat)\n        .map((venue: any) => {\n          return {\n            type: 'Feature',\n            geometry: {\n              type: 'Point',\n              coordinates: [venue.lng, venue.lat]\n            },\n            properties: {\n              title: 'Sucursal',\n              name: venue.name?.toUpperCase(),\n              venue,\n              logo: venue.company.marker?.url?.length\n                ? `url(\"${venue.company.marker.url}\")`\n                : 'url(\"/static/images/files/pin_osa.svg\")'\n            }\n          };\n        })\n    };\n\n    const $map = this.map;\n    // $('#map').css('width', $('#tab_2').width() as any);\n    const bounds = new mapboxgl.LngLatBounds();\n    geojson.features.forEach((marker) => {\n      // create a HTML element for each feature\n      const el: HTMLDivElement = document.createElement('div');\n      // here set class use in the marker\n      // el.className = 'marker';\n      el.style.backgroundImage = marker.properties.logo;\n      el.style.backgroundSize = 'cover';\n      el.style.width = '50px';\n      el.style.height = '50px';\n      el.style.borderRadius = '50p%';\n      el.style.cursor = 'pointer';\n\n      // make a marker for each feature and add to the map\n      if (Math.abs(marker.geometry.coordinates[0]) > 0.1) {\n        new mapboxgl.Marker(el)\n          .setLngLat(marker.geometry.coordinates as [number, number])\n          .setPopup(\n            new mapboxgl.Popup({ offset: 25 }).setHTML(`\n            <strong>${marker.properties.name}</strong><br />\n            ${marker.properties.venue.name}<br />\n<!--            <strong >Editar</strong>-->\n          `)\n          )\n          .addTo($map);\n\n        bounds.extend(marker.geometry.coordinates as [number, number]);\n      }\n    });\n    $map.resize();\n    $map.fitBounds(bounds, { padding: 100 });\n  }\n\n  public componentDidMount() {\n    super.componentDidMount();\n    // mapboxgl.accessToken = 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw';\n    this.map = new mapboxgl.Map({\n      accessToken:\n        'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw',\n      container: 'map',\n      style: 'mapbox://styles/mapbox/streets-v11',\n      center: [-70.593536, -33.509243],\n      zoom: 10,\n      trackResize: true\n    });\n    this.map.addControl(new mapboxgl.NavigationControl(), 'bottom-right');\n\n    $(\"a[href='#tab_2']\").on('shown.bs.tab', () => {\n      this.onChangeTab();\n    });\n  }\n\n  public componentDidUpdate(\n    prevProps: Readonly<IPropsType>,\n    prevState: Readonly<IStateType>,\n    snapshot?: any\n  ): void {\n    if (this.props.venues.pagination !== prevProps.venues.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.venues.source) {\n      this.props.venues.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { exporting, tab } = this.state;\n    const { loading, venues, pagination, searchText, companies, filters } =\n      this.props.venues;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.4\" cAction=\"Listado\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12 col-lg-12\">\n              <div className=\"box box-solid\">\n                <ul className=\"nav nav-pills nav-justified no-padding\">\n                  <li\n                    className={\n                      tab === 'list' ? 'no-margin active' : 'no-margin'\n                    }>\n                    <a\n                      href=\"javascript:void(0);\"\n                      className={tab === 'list' ? 'background-transition' : ''}\n                      style={{ borderTop: '0', marginBottom: '0' }}\n                      onClick={() => this.changeTab('list')}>\n                      Sucursales\n                    </a>\n                  </li>\n                  <li\n                    className={\n                      tab === 'map' ? 'no-margin active' : 'no-margin'\n                    }>\n                    <a\n                      className={tab === 'map' ? 'background-transition' : ''}\n                      href=\"javascript:void(0);\"\n                      style={{ borderTop: '0', marginBottom: '0' }}\n                      onClick={() => this.changeTab('map')}>\n                      Mapa\n                    </a>\n                  </li>\n                </ul>\n              </div>\n            </div>\n          </Row>\n\n          <div className={`box ${tab === 'list' ? '' : 'hidden'}`}>\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">\n                Sucursales <small>{pagination.count}</small>\n              </h3>\n              <div className=\"box-tools pull-right\">\n                {hasPermission(window.user, 'addVenue') ? (\n                  <button\n                    className=\"btn btn-sm btn-success\"\n                    onClick={this.createVenue}>\n                    <i className=\"fa fa-plus\" /> Crear sucursal\n                  </button>\n                ) : null}\n                <button\n                  className=\"btn btn-sm btn-primary  hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporting}\n                  style={{ marginLeft: '5px' }}>\n                  {exporting ? (\n                    <React.Fragment>\n                      <i className=\"fa fa-spin fa-spinner\" /> Exportando\n                    </React.Fragment>\n                  ) : (\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-download\" /> Exportar\n                    </React.Fragment>\n                  )}\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div className=\"row\">\n                <div className=\"col-md-8\">\n                  <div\n                    className=\"input-group input-group-sm\"\n                    style={{ padding: '10px' }}>\n                    <input\n                      type=\"text\"\n                      value={searchText}\n                      className=\"form-control pull-right\"\n                      onChange={this.onChangeSearch}\n                      placeholder=\"Buscar\"\n                    />\n                    <div className=\"input-group-btn\">\n                      <button className=\"btn btn-default\">\n                        <i className=\"fa fa-search\" />\n                      </button>\n                    </div>\n                  </div>\n                </div>\n                <div className=\"col-md-4\">\n                  <div style={{ padding: '10px' }}>\n                    <BootstrapSelect\n                      sm={true}\n                      noneSelectedText=\"Todas las empresas\"\n                      displayItems={2}\n                      selectedText=\"sucursales seleccionadas.\"\n                      selected={filters.company ? [filters.company] : []}\n                      // selected={[]}\n                      autoClouse={true}\n                      allOption={false}\n                      // selectAll={this.filterAllVenues}\n                      options={companies.map((company: any) => ({\n                        value: company._id,\n                        text: company.name.toUpperCase()\n                      }))}\n                      // onClick={() => {\n                      //   console.log('click');\n                      // }}\n                      onClick={this.filterCompany}\n                    />\n                  </div>\n                </div>\n              </div>\n              <div className=\"box-body no-padding\">\n                <table className=\"table table-andes table-striped table-hover\">\n                  <thead>\n                    <tr>\n                      <th style={{ width: '40%' }} className=\"middle\">\n                        Nombre\n                      </th>\n                      <th style={{ width: '10%' }} className=\"middle hidden-xs\">\n                        Código\n                      </th>\n                      <th\n                        style={{ width: '10%' }}\n                        className=\"middle-center hidden-xs\">\n                        Distribuidor\n                      </th>\n                      <th style={{ width: '10%' }} className=\"middle hidden-xs\">\n                        Asignaciones\n                      </th>\n                      <th\n                        style={{ width: '10%' }}\n                        className=\"middle-center hidden-xs\">\n                        Ubicación\n                      </th>\n                      <th style={{ width: '15%' }} className=\"middle hidden-xs\">\n                        Modificado\n                      </th>\n                      {hasPermission(window.user, 'changeVenue') ? (\n                        <th style={{ width: '1%' }} className=\"width-10\" />\n                      ) : null}\n                      {hasPermission(window.user, 'deleteVenue') ? (\n                        <th style={{ width: '1%' }} className=\"width-10\" />\n                      ) : null}\n                    </tr>\n                  </thead>\n                  <tbody>\n                    {venues.map((venue: IVenue) => {\n                      const canDelete =\n                        venue.users &&\n                        venue.users.length === 0 &&\n                        venue.participants &&\n                        venue.participants.length === 0;\n                      return (\n                        <tr\n                          key={venue._id}\n                          id={`venue-${venue._id}`}\n                          className={'background-transition'}>\n                          <td className=\"middle\">\n                            <CopyText value={`${venue.name?.toUpperCase()}`}>\n                              <strong className=\"text-primary\">\n                                {venue.name?.toUpperCase()}\n                              </strong>\n                            </CopyText>\n                            <br />\n                            {venue.company ? (\n                              <span className={'text-sm text-muted'}>\n                                {venue.company.name?.toUpperCase()}\n                              </span>\n                            ) : null}\n                          </td>\n                          <td className=\"middle text-sm text-muted  hidden-xs\">\n                            {venue.code}\n                          </td>\n                          <td className=\"middle-center hidden-xs\">\n                            {venue.type === 'distributor' ? (\n                              <i className=\"fa fa-check-circle text-green\" />\n                            ) : (\n                              <i className=\"fa fa-times-circle text-blue\" />\n                            )}\n                          </td>\n                          <td className=\"middle text-sm text-muted  hidden-xs\">\n                            Usuarios: {venue.users ? venue.users.length : 0}\n                            <br />\n                            Revisiones:{' '}\n                            {venue.participants ? venue.participants.length : 0}\n                            <br />\n                          </td>\n                          <td className=\"middle text-sm text-muted hidden-xs\">\n                            lat: {venue.lat}\n                            <br />\n                            lng: {venue.lng}\n                          </td>\n                          <td className=\"middle hidden-xs text-sm text-muted\">\n                            {moment(venue.updatedAt).format('LLL')}\n                          </td>\n                          {hasPermission(window.user, 'changeVenue') ? (\n                            <td\n                              className=\"middle text-blue pointer\"\n                              onClick={() => this.updateVenue(venue)}>\n                              <i className=\"fa fa-pencil\" />\n                            </td>\n                          ) : null}\n                          {hasPermission(window.user, 'deleteVenue') ? (\n                            <td\n                              className={\n                                canDelete\n                                  ? 'middle text-red pointer'\n                                  : 'middle text-muted not-allowed'\n                              }\n                              onClick={\n                                canDelete\n                                  ? () => this.deleteVenue(venue)\n                                  : undefined\n                              }>\n                              <i className=\"fa fa-minus-circle\" />\n                            </td>\n                          ) : null}\n                        </tr>\n                      );\n                    })}\n                  </tbody>\n                </table>\n              </div>\n            </div>\n            {pagination.pages > 1 && (\n              <div className=\"box-footer text-right\">\n                <Paginator\n                  changePage={this.changePage}\n                  page={pagination.page}\n                  pages={pagination.pages}\n                />\n              </div>\n            )}\n            {loading && (\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\" />\n              </div>\n            )}\n          </div>\n\n          <div className={`box ${tab === 'map' ? '' : 'hidden'}`}>\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">\n                Sucursales <small>{pagination.count}</small>\n              </h3>\n              <div className=\"box-tools pull-right\">\n                <button\n                  className=\"btn btn-sm btn-primary  hidden-xs\"\n                  onClick={this.exportExcel}\n                  disabled={exporting}\n                  style={{ marginLeft: '5px' }}>\n                  {exporting ? (\n                    <React.Fragment>\n                      <i className=\"fa fa-spin fa-spinner\" /> Exportando\n                    </React.Fragment>\n                  ) : (\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-download\" /> Exportar\n                    </React.Fragment>\n                  )}\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <div\n                id=\"map\"\n                style={{\n                  position: 'relative',\n                  width: '100%',\n                  height: '70vh'\n                }}\n              />\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterCompany(company: string): void {\n    const { filters } = this.props.venues;\n    this.props.changeFilterAction('company', filters.company === company? '' : company);\n    this.debounceOnChangeSearch();\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    this.props.getVenuesAction(1);\n  }\n\n  private createVenue(): void {\n    this.props.changeTempVenueAction({\n      _id: '',\n      lat: 0,\n      lng: 0,\n      name: '',\n      code: '',\n      abbreviation: '',\n      type: 'receiver',\n      sendTo: [],\n      sendToDays: [],\n      receiveFrom: [],\n      shippingCarriers: [],\n      responsible: [],\n      shippingMaxDays: 5,\n      receptionCarriers: []\n    });\n    this.props.loadDataAction(\n      'Agregar Sucursal',\n      <VenueFormView />,\n      <React.Fragment>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-default\"\n          data-dismiss=\"modal\">\n          Cancelar\n        </button>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-primary\"\n          onClick={this.processCreateVenue}>\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateVenue(): void {\n    const { tempVenue } = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Agregar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Agregar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.createVenueAction();\n    }\n  }\n\n  private updateVenue(venue: IVenue): void {\n    this.props.changeTempVenueAction({\n      _id: venue._id,\n      name: venue.name,\n      code: venue.code ?? '',\n      abbreviation: venue.abbreviation ?? '',\n      lat: venue.lat,\n      lng: venue.lng,\n      company: venue.company,\n      region: venue.region,\n      type: venue.type ? venue.type : 'receiver',\n      sendTo: venue.sendTo ? venue.sendTo : [],\n      sendToDays: venue.sendToDays ? venue.sendToDays : [],\n      shippingMaxDays: venue.shippingMaxDays,\n      receiveFrom: venue.receiveFrom ? venue.receiveFrom : [],\n      responsible: venue.responsible ? venue.responsible : [],\n      shippingCarriers: venue.shippingCarriers ? venue.shippingCarriers : [],\n      receptionCarriers: venue.receptionCarriers ? venue.receptionCarriers : []\n    });\n    this.props.loadDataAction(\n      'Editar Sucursal',\n      <VenueFormView update={true} />,\n      <React.Fragment>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-default\"\n          data-dismiss=\"modal\">\n          Cancelar\n        </button>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-primary\"\n          onClick={this.processUpdateVenue}>\n          Editar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateVenue(): void {\n    const { tempVenue } = this.props.venues;\n    if (!tempVenue.name || !tempVenue.name.trim()) {\n      swal!('Editar sucursal', 'El nombres es requerido', 'error');\n    } else if (!tempVenue.company || !tempVenue.company._id) {\n      swal!('Editar sucursal', 'La empresa es requerida', 'error');\n    } else {\n      this.props.updateVenueAction();\n    }\n  }\n\n  private deleteVenue(venue: IVenue): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal ${venue.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteVenueAction(venue._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getVenuesAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { venues: IVenuesState }) => {\n  return {\n    venues: state.venues\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getVenuesAction: (page: number) => dispatch(getVenuesAction(page)),\n    changeFilterAction: (filter: string, value: string) => dispatch(changeFilterAction(filter, value)),\n    createVenueAction: () => dispatch(createVenueAction()),\n    updateVenueAction: () => dispatch(updateVenueAction()),\n    deleteVenueAction: (id: string) => dispatch(deleteVenueAction(id)),\n    changeSearchAction: (searchText: string) =>\n      dispatch(changeSearchAction(searchText)),\n    changeTempVenueAction: (venue: IBaseVenue) =>\n      dispatch(changeTempVenueAction(venue)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) =>\n      dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ venues: IVenuesState }, { dispatch: any }, IPropsType>(\n  mapStateToProps,\n  mapDispatchToProps\n)(VenuesListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\n\ninterface IPropsType {\n  changeTempVersion: (tempVersion: ITempVersion) => void;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n  description: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempVersion: ITempVersion;\n  currentUser: string;\n}\n\nclass VersionFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    currentUser: '',\n    tempVersion: {\n      description: '',\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChangeDescription = this.onChangeDescription.bind(this);\n    this.onChangeiOS = this.onChangeiOS.bind(this);\n    this.onChangeAndroid = this.onChangeAndroid.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    this.props.changeTempVersion(this.state.tempVersion);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    return (\n      <div className={'row'}>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Descripción</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeDescription}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>iOS</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeiOS}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Android</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeAndroid}\n            />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeDescription(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        description: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeiOS(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        ios: e.target.value.trim()\n      }\n    });\n  }\n\n  private onChangeAndroid(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempVersion: {\n        ...this.state.tempVersion,\n        android: e.target.value.trim()\n      }\n    });\n  }\n\n}\n\nexport default VersionFormView;\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {createVersionAction, IVersionsState, getVersionsAction} from '../../actions/versions.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {statusFooterButttonsModal} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport VersionFormView from './VersionFormView';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  versions: IVersionsState;\n  dispatch: Dispatch<ModalReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  getVersionsAction(): ModalReduxAction;\n\n  createVersionAction(version: ITempVersion): ModalReduxAction;\n}\n\ninterface ITempVersion {\n  ios: string;\n  android: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  dragging: string;\n  draggingLocation: number;\n  completed: string[];\n  users: string[];\n  tempVersion: ITempVersion;\n}\n\nclass VersionListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   alerts: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    dragging: '',\n    draggingLocation: -1,\n    completed: [],\n    users: ['One', 'Two', 'Three', 'Four', 'Five'],\n    tempVersion: {\n      ios: '',\n      android: ''\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de versiones';\n    this.changeTempVersion = this.changeTempVersion.bind(this);\n    this.onDragStart = this.onDragStart.bind(this);\n    this.onDragEnd = this.onDragEnd.bind(this);\n    this.onDragOver = this.onDragOver.bind(this);\n    this.onDrop = this.onDrop.bind(this);\n    this.onDropChangeIndex = this.onDropChangeIndex.bind(this);\n    this.onDragOverChange = this.onDragOverChange.bind(this);\n    this.onDragEndChange = this.onDragEndChange.bind(this);\n\n    this.addVersion = this.addVersion.bind(this);\n    this.processAddAlert = this.processAddAlert.bind(this);\n\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    this.props.getVersionsAction();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.versions.source) {\n      this.props.versions.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n\n    const {versions, loading} = this.props.versions;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.100\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Versiones <small>{versions.length}</small></h3>\n              <div className=\"pull-right box-tools\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addVersion}><i className='fa fa-plus' /> Crear versión</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Descripción</th>\n                    <th className=\"middle text-center\">iOS</th>\n                    <th className=\"middle text-center\">Android</th>\n                    <th className=\"middle\">Creada</th>\n                    <th className=\"middle\">Creada por</th>\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  versions.length ?\n                    versions.map((version: any) => {\n                      return (\n                        <tr\n                          key={version._id}\n                          id={`alert-${version._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">\n                            <strong className='text-primary'>{version.description}</strong>\n                          </td>\n                          <td className=\"middle text-center text-muted\">{version.ios}</td>\n                          <td className=\"middle text-center text-muted\">{version.android}</td>\n                          <td className=\"middle text-sm text-muted\">{moment(version.createdAt).format('LLL')}</td>\n                          <td className=\"middle text-info\">\n                            {\n                              version.createdBy ? version.createdBy.firstName + ' ' + version.createdBy.lastName : '-'\n                            }\n                          </td>\n                        </tr>\n                      );\n                    }) : <tr>\n                      <td colSpan={5}>Aún no se han ingresado versiones</td>\n                    </tr>\n                }\n                </tbody>\n              </table>\n              <Row>\n                <div className=\"col-md-6\">\n                  <table className=\"table table-andes table-striped\">\n                    <thead>\n                      <tr>\n                        <th className=\"middle\">Nombre</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        this.state.users.map((user, index)=>{\n                          return (\n                            <tr\n                              draggable\n                              key={index}\n                              className={`pointer ${this.state.draggingLocation === index ? 'bg-aqua-active' : ''}`}\n                              style={{\n                                opacity: this.state.dragging === user || this.state.draggingLocation === index ? 0.5 : 1\n                              }}\n                              onDragStart = {(e) => this.onDragStart(e, user, index)}\n                              onDragEnter={this.onDragEnter}\n                              onDragEnd = {this.onDragEndChange}\n                              onDrop={(e) =>this.onDropChangeIndex(e, index)}\n                              onDragOver={(e)=>this.onDragOverChange(e, index)}\n                            >\n                              <td\n                              ><i className=\"fa fa-arrows-v text-muted font-md\" /> {\n                                this.state.draggingLocation === index ? this.state.dragging : user\n                              }</td>\n                            </tr>\n\n                          );\n                        })\n                      }\n                    </tbody>\n                  </table>\n                </div>\n                <div className=\"col-md-6\" style={{height: '150px', overflowY: 'auto'}}>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDrop={(e) =>this.onDrop(e, 'completed')}\n                    onDragEnter={this.onDragEnter}\n                    style={{width: 200, minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    completed\n                    {this.state.completed.map((item, index)=><div key={index}>{item}</div>)}\n                  </div>\n                  <div\n                    onDragOver={this.onDragOver}\n                    onDragEnter={this.onDragEnter}\n                    onDrop={(e) =>this.onDrop(e, 'incompleted')}\n                    style={{width: 200,  minHeight: 100, border: '1px solid #CCC'}}\n                  >\n                    incompleted\n                  </div>\n                </div>\n              </Row>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onDragStart(ev: React.DragEvent<HTMLTableRowElement>, id:string, index: number) {\n    console.log(`onDragStart: ${id}`);\n    ev.dataTransfer.setData('id', id);\n    ev.dataTransfer.setData('type', 'type');\n    ev.dataTransfer.setData('index', index.toString());\n\n    ev.dataTransfer.dropEffect = 'move';\n\n    const dragIcon = document.createElement('img');\n    dragIcon.src = 'https://www.automotrizcumbre.cl/wp-content/uploads/2018/08/chevrolet-sail-sedan-detalles-personaliza-648x240-4-300x180.jpg';\n    dragIcon.width = 100;\n    ev.dataTransfer.setDragImage(dragIcon, -10, -10);\n\n    this.setState({\n      dragging: id\n    });\n  }\n\n  private onDragEnd(ev: React.DragEvent<HTMLTableRowElement>) {\n    console.log(`onDragEnd`);\n    this.setState({\n      dragging: ''\n    });\n  }\n\n  private onDragEnter(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragEnter`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOver(ev: React.DragEvent<HTMLElement>) {\n    console.log(`onDragOver`);\n    ev.preventDefault();\n    ev.stopPropagation();\n  }\n\n  private onDragOverChange(ev: React.DragEvent<HTMLElement>, index: number) {\n    console.log(`onDragOverChange`);\n    ev.dataTransfer.dropEffect = 'move';\n    ev.preventDefault();\n    ev.stopPropagation();\n    this.setState({\n      draggingLocation: index\n    });\n  }\n\n  private onDragEndChange(ev: React.DragEvent<HTMLElement>){\n    console.log(`onDragEndChange`);\n    this.setState({\n      draggingLocation: -1,\n      dragging: ''\n    });\n  }\n\n  private onDrop(ev: React.DragEvent<HTMLElement>, cat: string){\n    const id = ev.dataTransfer.getData('id');\n    const type = ev.dataTransfer.getData('type');\n    console.log(`onDrop: id: ${id} cat: ${cat}`);\n    console.log(id);\n    if (cat === 'completed') {\n      this.setState({\n        completed: [id, ...this.state.completed]\n      });\n    } else {\n      alert(`${id} se a soltado en ${cat}`);\n\n    }\n  }\n\n  private onDropChangeIndex(ev: React.DragEvent<HTMLElement>, newIndex: number) {\n    let {users} = this.state;\n    let index = parseInt(ev.dataTransfer.getData('index'));\n    console.log(`onDropChangeIndex newIndex:${newIndex} index:${index}`);\n    const data = users[index];\n    if (newIndex > index) {\n      for (let i = 0; i < users.length; i++) {\n        if (i >= index && i < newIndex) {\n          users[i] = users[i + 1];\n        }\n      }\n    } else {\n      for (let i = users.length - 1; i >= 0; i--) {\n        if (i > newIndex && i <= index) {\n          console.log(`2 ${users[i]} -> ${users[i - 1]}`);\n          users[i] = users[i - 1];\n        }\n      }\n    }\n    users[newIndex] = data;\n    this.setState({\n      users\n    });\n  }\n\n\n  private addVersion() {\n    this.props.loadDataAction(\n      'Agregar Alerta',\n        <VersionFormView changeTempVersion={this.changeTempVersion} />\n      ,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-primary\" onClick={this.processAddAlert}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private changeTempVersion(tempVersion: ITempVersion) {\n    this.setState({\n      tempVersion\n    });\n  }\n\n  private processAddAlert() {\n\n    const {tempVersion} = this.state;\n\n    if(tempVersion.ios.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else if(tempVersion.android.trim().length === 0)\n    {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    }\n    else\n    {\n      statusFooterButttonsModal(true);\n      this.props.createVersionAction(tempVersion);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { versions: IVersionsState }) => {\n  return {\n    versions: state.versions\n  };\n};\n\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getVersionsAction: () => dispatch(getVersionsAction()),\n    createVersionAction: (version: ITempVersion) => dispatch(createVersionAction(version))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(VersionListView);\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport BreadcrumbApp from './BreadcrumbApp';\nimport FooterApp from './FooterApp';\nimport HeaderApp from './HeadeApp';\nimport MenuApp from './MenuApp';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport moment = require('moment');\nimport ShowIf from '../components/Utils/ShowIf';\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  children: JSX.Element;\n  router: any;\n  title: any;\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass AppContainer extends React.Component<IPropsType, IStateType> {\n\n  static propTypes = {\n    title: PropTypes.any.isRequired,\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired,\n    cAction: PropTypes.string\n  };\n\n  componentDidMount() {\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      const $body = $('body');\n      $body\n        .removeClass('skin-purple')\n        .css({ 'background-color': '#ecf0f5' });\n      $body.append( `<div class=\"text-muted text-center\" style=\"position: absolute; height: 30px; width: 100%;\">Copyright (c) ${moment().format('YYYY')} <a href=\"http://www.osacontrol.com\" target=\"_blank\">OSA SPA</a>. All rights reserved.</div>` );\n\n    }\n  }\n\n  public render() {\n    const { title, cMenu, cSubMenu, cAction } = this.props;\n    const { location: { query } } = this.props.router;\n    if (query?.integration === 'webview') {\n      return (\n        <React.Fragment>\n          {this.props.children}\n        </React.Fragment>\n      );\n    }\n    return (\n      <React.Fragment>\n        <HeaderApp />\n        <MenuApp cMenu={cMenu} cSubMenu={cSubMenu} />\n        <div className='content-wrapper' style={{ minHeight: `${window.innerHeight - 51}px` }}>\n          <section className='content-header'>\n            <ShowIf condition={typeof title === 'string'} alternative={title}>\n              <h1>{title ? title: '\\u00A0'}</h1>\n            </ShowIf>\n            <BreadcrumbApp cMenu={cMenu} cSubMenu={cSubMenu} cAction={cAction} />\n          </section>\n          {this.props.children}\n        </div>\n        <FooterApp />\n      </React.Fragment>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { router: any }) => {\n  return {\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(AppContainer);\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n  cAction?: string;\n}\n\nconst BreadcrumbApp: React.FunctionComponent<IPropsType> = (props) => {\n  const menu = menus.find((menu: any) => menu.id === props.cMenu);\n  if (menu) {\n    const subMenu = menu.items.find((item: any) => item.id === props.cSubMenu);\n    return (\n      <ol className=\"breadcrumb\">\n        <li><Link to={menu.url}><i className={`fa ${menu.icon}`}/>{menu.text}</Link></li>\n        {\n          props.cAction && props.cAction.length ?\n            subMenu ? <li><Link to={subMenu.url}>{subMenu.text}</Link></li> : null :\n            subMenu ? <li className=\"active\">{subMenu.text}</li> : null\n        }\n        {props.cAction && props.cAction.length && <li className=\"active\">{props.cAction}</li>}\n      </ol>\n    );\n  }\n  return null;\n};\n\n// BreadcrumbApp.propTypes = {\n//   cMenu: PropTypes.string.isRequired,\n//   cSubMenu: PropTypes.string.isRequired,\n//   cAction: PropTypes.string\n// };\n\nexport default BreadcrumbApp;\n","import * as React from 'react';\nimport * as moment from 'moment-timezone';\n\nconst FooterApp: React.StatelessComponent<{}> = () => {\n  return (\n    <footer className=\"main-footer\">\n      <div className=\"pull-right hidden-xs\"><b>Version</b> 2.1.3 stable</div>\n      <strong>Copyright (c) {moment().format('YYYY')} <a href=\"https://www.osa-app.cl\" target={'_blank'}>OSA SPA.</a></strong> All rights\n      reserved.\n    </footer>\n  );\n};\n\nFooterApp.propTypes = {\n};\n\nexport default FooterApp;\n","// import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {IWindow} from '../interfaces/window';\n\ndeclare let window: IWindow;\n\nclass HeaderApp extends React.Component<{}, {}> {\n  protected channel: BroadcastChannel;\n  protected existBC: boolean = window.hasOwnProperty('BroadcastChannel');\n\n  constructor(props: {}) {\n    super(props);\n    this.closeSesion = this.closeSesion.bind(this);\n  }\n\n  public componentDidMount() {\n    if (this.existBC) {\n      this.channel = new BroadcastChannel('andes');\n      this.channel.onmessage = (e) => {\n        if (e.data.close) {\n          location.href = '/account/logout/';\n        }\n      };\n    }\n  }\n\n  public componentWillUnmount() {\n    if (this.existBC) {\n      this.channel.close();\n    }\n  }\n\n  public render() {\n    return (\n      <header className=\"main-header\">\n        <a className=\"logo\" href=\"/\" style={{padding: '5px 15px'}}>\n          <span className=\"logo-mini\">&nbsp;</span>\n          <span className=\"logo-lg\"><img src=\"/static/images/OSA_andes_logo_horizontal.svg\" style={{maxHeight: '40px', verticalAlign: 'baseline'}}/></span>\n        </a>\n        <nav className=\"navbar navbar-static-top\">\n          <a className=\"sidebar-toggle hidden-sm hidden-md hidden-lg\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">\n          {/*<a className=\"sidebar-toggle\" href=\"#\" data-toggle=\"push-menu\" role=\"button\">*/}\n            <span className=\"sr-only\">Toggle navigation</span>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n            <span className=\"icon-bar\"/>\n          </a>\n          <div className=\"navbar-custom-menu\">\n            <ul className=\"nav navbar-nav\">\n              {/*<li className=\"dropdown messages-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-envelope-o\" />*/}\n              {/*<span className=\"label label-success\">4</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 4 messages</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\">*/}\n              {/*<div className=\"pull-left\">*/}\n              {/*<img className=\"img-circle\" src=\"/static/theme/dist/img/user2-160x160.jpg\" alt=\"User Image\" />*/}\n              {/*</div>*/}\n              {/*<h4>Support Team*/}\n              {/*<small><i className=\"fa fa-clock-o\" /> 5 mins</small>*/}\n              {/*</h4>*/}\n              {/*<p>Why not buy a new awesome theme?</p></a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">See All Messages</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"dropdown notifications-menu\">*/}\n              {/*<a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">*/}\n              {/*<i className=\"fa fa-bell-o\" />*/}\n              {/*<span className=\"label label-warning\">10</span>*/}\n              {/*</a>*/}\n              {/*<ul className=\"dropdown-menu\">*/}\n              {/*<li className=\"header\">You have 10 notifications</li>*/}\n              {/*<li>*/}\n              {/*<ul className=\"menu\">*/}\n              {/*<li><a href=\"#\"><i className=\"fa fa-users text-aqua\" /> 5 new members joined today</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              {/*<li className=\"footer\"><a href=\"#\">View all</a></li>*/}\n              {/*</ul>*/}\n              {/*</li>*/}\n              <li className=\"dropdown user user-menu\">\n                <a className=\"dropdown-toggle\" href=\"#\" data-toggle=\"dropdown\">\n                  <img className=\"user-image\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                  <span\n                    className=\"hidden-xs\">{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}</span>\n                </a>\n                <ul className=\"dropdown-menu\">\n                  <li className=\"user-header\">\n                    <img className=\"img-circle\" src=\"/static/images/icon_circular.png\" alt=\"User Image\"/>\n                    <p>{`${window.user.firstName || ''} ${window.user.lastName || ''}${!window.user.firstName && !window.user.lastName ? 'Unknown User' : ''}`}\n                      <small>{window.user.email || ''}</small>\n                    </p>\n                  </li>\n                  {/*<li className=\"user-body\">*/}\n                  {/*<div className=\"row\">*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Followers</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Sales</a></div>*/}\n                  {/*<div className=\"col-xs-4 text-center\"><a href=\"#\">Friends</a></div>*/}\n                  {/*</div>*/}\n                  {/*</li>*/}\n                  <li className=\"user-footer\">\n                    {/*<div className=\"pull-left\"><a className=\"btn btn-default btn-flat\" href=\"#\">Profile</a></div>*/}\n                    <div className=\"pull-right\">\n                      <a\n                        className=\"btn btn-sm btn-default btn-flat\"\n                        href=\"/account/logout/\"\n                        onClick={this.closeSesion}\n                      >\n                        Cerrar sesión\n                      </a>\n                    </div>\n                  </li>\n                </ul>\n              </li>\n              {/*<li><a href=\"#\" data-toggle=\"control-sidebar\"><i className=\"fa fa-gears\"></i></a></li>*/}\n            </ul>\n          </div>\n        </nav>\n      </header>\n    );\n  }\n  private closeSesion() {\n    if (this.existBC) {\n      this.channel.postMessage({\n        close: true\n      });\n    }\n  }\n}\n\nexport default HeaderApp;\n","import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {Link} from 'react-router-dom';\nimport menus from '../utils/menus';\n\ninterface IPropsType {\n  cMenu: string;\n  cSubMenu: string;\n}\n\nclass MenuApp extends React.Component<IPropsType, {}> {\n\n  static propTypes = {\n    cMenu: PropTypes.string.isRequired,\n    cSubMenu: PropTypes.string.isRequired\n  };\n\n  public componentDidMount(): void {\n    ($('.sidebar-menu') as any).tree();\n  }\n\n  public render() {\n    const {cMenu, cSubMenu} = this.props;\n\n    return (\n      <aside className=\"main-sidebar\">\n        <section className=\"sidebar\">\n          <ul className=\"sidebar-menu\" data-widget=\"tree\">\n            <li className=\"header\">MENÚ</li>\n            {\n              menus.map((menu: any) => {\n                return (\n                  <li className={`treeview ${menu.id === cMenu ? 'active menu-open' : ''}`} key={menu.id}>\n                    <a href=\"#\">\n                      <i className={`fa ${menu.icon}`}/> <span>{menu.text}</span>\n                      <span className=\"pull-right-container\">\n                      <i className=\"fa fa-angle-left pull-right\"/>\n                    </span>\n                    </a>\n                    <ul className=\"treeview-menu\">\n                      {\n                        menu.items.map((item: any) => {\n                          return (\n                            <li key={item.id} className={item.id === cSubMenu ? 'active' : ''}>\n                              <Link to={item.url}><i className={`fa ${item.icon}`}/> {item.text}</Link>\n                            </li>\n                          );\n                        })\n                      }\n                    </ul>\n                  </li>\n                );\n              })\n            }\n          </ul>\n        </section>\n      </aside>\n    );\n  }\n}\n\nexport default MenuApp;\n","import {AlertReduxAction, IAlertsState} from '../actions/alerts.actions';\n\nconst initialState: IAlertsState = {\n  alerts: [],\n  users: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function alertsReducer(state = initialState, action: AlertReduxAction): IAlertsState {\n  switch (action.type) {\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/ALERTS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/DELETE':\n      return {\n        ...state,\n        alerts: state.alerts.filter((alert) => alert._id !== action.payload.id)\n      };\n    case '/ALERTS/CREATE':\n      return {\n        ...state,\n        alerts: [action.payload.alert, ...state.alerts]\n      };\n    case '/ALERTS/LOAD_DATA':\n      return {\n        ...state,\n        users: action.payload.users,\n        alerts: action.payload.alerts\n      };\n    default:\n      return state;\n  }\n}\n","import {BillingReduxAction, IBillingState} from \"../actions/billing.actions\";\n\nconst initialState: IBillingState = {\n  invoices: [],\n  source: null,\n  loading: true,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function billingReducer(state = initialState, action: BillingReduxAction): any {\n  switch (action.type) {\n    case '/BILLING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/BILLING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/BILLING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/BILLING/LOAD_BILLING':\n      return {\n        ...state,\n        invoices: action.payload.invoices,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  CANCEL_BILLING_SETINGS,\n  IBillingSettingsActionTypes,\n  IBillingSettingsState,\n  LOAD_ALL_COMPANIES_BILLING_SETINGS,\n  LOAD_ALL_MODULES_BILLING_SETINGS,\n  LOAD_BILLING_SETINGS,\n  LOAD_INVOICE,\n  LOADING_BILLING_SETINGS\n} from '../actions/billingSettings.types';\nimport * as moment from 'moment';\n\nconst initialState: IBillingSettingsState = {\n  loading: true,\n  source: null,\n  companies: [],\n  modules: [],\n  billingSettings: null,\n  invoice: null,\n  oldest: null,\n  last: null\n};\n\nexport default function billingSettingsReducer(state = initialState, action: IBillingSettingsActionTypes): IBillingSettingsState {\n  switch (action.type) {\n    case LOADING_BILLING_SETINGS:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case LOAD_ALL_COMPANIES_BILLING_SETINGS:\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case LOAD_ALL_MODULES_BILLING_SETINGS:\n      return {\n        ...state,\n        modules: action.payload.modules\n      };\n    case LOAD_ALL_MODULES_BILLING_SETINGS:\n      return {\n        ...state,\n        modules: action.payload.modules\n      };\n    case LOAD_BILLING_SETINGS:\n      return {\n        ...state,\n        billingSettings: action.payload.billingSettings\n        // pagination: {\n        //   ...state.pagination,\n        //   pages: action.payload.pages,\n        //   page: action.payload.page,\n        //   count: action.payload.count\n        // }\n      };\n    case LOAD_INVOICE:\n      return {\n        ...state,\n        invoice: action.payload.invoice,\n        oldest: moment(action.payload.oldest, 'YYYYMM'),\n        last: moment(action.payload.last, 'YYYYMM')\n      };\n    case CANCEL_BILLING_SETINGS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    default:\n      return state;\n  }\n}\n","import {BorderReduxAction, IBorderState} from \"../actions/borders.actions\";\nimport {IBorder} from \"../../../../../src/app/interfaces/border.interface\";\n\nconst initialState : IBorderState = {\n  searchText: '',\n  loading: true,\n  source: null,\n  borders: [],\n  companies: [],\n  tempBorder: {\n    _id: '',\n    lat: 0,\n    lng: 0,\n    name: ''\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n}\n\nexport function bordersReducer(state: IBorderState = initialState, action: BorderReduxAction) : IBorderState {\n  switch (action.type) {\n    case \"/BORDERS/CANCEL_REQUEST\":\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case \"/BORDERS/IS_LOADING\":\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case \"/BORDERS/CHANGE_PAGE\":\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case \"/BORDERS/CHANGE_SEARCH\":\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case \"/BORDERS/CHANGE_TEMP_BORDER\":\n      return {\n        ...state,\n        tempBorder: action.payload.border\n      };\n    case \"/BORDERS/LOAD_BORDERS\":\n      return {\n        ...state,\n        borders: action.payload.borders,\n        pagination: {\n          ...state.pagination,\n          count: action.payload.count,\n          pages: action.payload.pages\n        }\n      };\n    case \"/BORDERS/LOAD_COMPANIES\":\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case \"/BORDERS/DELETE_BORDER\":\n      return {\n        ...state,\n        borders: state.borders.filter((borders: IBorder) => borders._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n\n    default:\n      return state;\n  }\n\n}\n","import {CarrierReduxAction, ICarriersState} from '../actions/carriers.actions';\n\nconst initialState: ICarriersState = {\n  carriers: [],\n  tempCarrier: {\n    name: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carriersReducer(state = initialState, action: CarrierReduxAction): ICarriersState {\n  switch (action.type) {\n    case '/CARRIERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARRIERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARRIERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/CARRIERS/CHANGE_TEMP_CARRIER':\n      return {\n        ...state,\n        tempCarrier: action.payload.carrier\n      };\n    case '/CARRIERS/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport {CarReduxAction, ICarsState} from '../actions/cars.actions';\n\nconst initialState: ICarsState = {\n  cars: [],\n  car: null,\n  carEvents: {} ,\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function carsReducer(state = initialState, action: CarReduxAction): ICarsState {\n  switch (action.type) {\n    case '/CARS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/CARS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/CARS/LOAD_CARS':\n      return {\n        ...state,\n        cars: action.payload.cars,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/CARS/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n        carEvents: groupCarEvents(action.payload.car)\n      };\n    case '/CARS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n\nfunction groupCarEvents(car: ICar): any[] {\n  const events: any[] = [];\n  events.push({\n    _id: car._id,\n    createdAt: moment(car.createdAt).seconds(0),\n    typeEvent: 'created'\n  });\n  if (car.participants && car.participants.length) {\n    for (const participant of car.participants) {\n      events.push({\n        ...participant,\n        createdAt: moment(participant.createdAt),\n        typeEvent: 'revision'\n      });\n    }\n  }\n  if (car.inventories && car.inventories.length) {\n    for (const inventory of car.inventories) {\n      events.push({\n        ...inventory,\n        createdAt: moment(inventory.createdAt),\n        typeEvent: 'inventory'\n      });\n    }\n  }\n\n  return events\n    .sort((a, b) => {\n      return b.createdAt.unix() - a.createdAt.unix();\n    })\n    .reduce((acc: any, cur: any) => {\n    const key = moment(cur.createdAt).startOf('month').format('YYYY-MM-DD');\n    acc[key] = acc[key] || [];\n    acc[key].push(cur);\n    return acc;\n  }, {});\n}\n","import {\n  IColorState,\n  ColorReduxActions,\n  COLOR_CANCEL,\n  COLOR_CHANGE_ORDER,\n  COLOR_IS_LOADING,\n  COLOR_LOAD,\n  COLOR_UDPATE, COLOR_CREATE, COLOR_DELETE\n} from '../actions/color.types';\n\nconst initialState: IColorState = {\n  colors: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function colorsReducer(state = initialState, action: ColorReduxActions): IColorState {\n  switch (action.type) {\n    case COLOR_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case COLOR_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case COLOR_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case COLOR_CREATE:\n      return {\n        ...state,\n        colors: [...state.colors, action.payload.color]\n      };\n     case COLOR_DELETE:\n       return {\n         ...state,\n         colors: [...state.colors.filter((color) => color._id !== action.payload.color)]\n       };\n     case COLOR_UDPATE:\n      return {\n        ...state,\n        colors: [...state.colors.map((color) => {\n          if (color._id === action.payload.color._id) {\n            return {\n              color,\n              ...action.payload.color\n            };\n          }\n          return color;\n        })]\n      };\n\n    case COLOR_LOAD:\n      return {\n        ...state,\n        colors: action.payload.colors,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {ICompany} from '../../../../../src/app/interfaces/company.interface';\nimport {CompaniesReduxAction, ICompaniesState} from '../actions/companies.actions';\n\nconst initialState: ICompaniesState = {\n  companies: [],\n  tempCompany: {\n    name: '',\n    businessName: '',\n    rut: '',\n    imageURI: null,\n    image: null,\n    markerURI: null,\n    marker: null,\n    billing: {\n      active: false,\n      inventoryPrice: 0.0,\n      checklistPrice: 0.0,\n      requestPrice: 0.0,\n      deliveryPrice: 0.0\n    },\n    notifications:[]\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function companiesReducer(state = initialState, action: CompaniesReduxAction): ICompaniesState {\n  switch (action.type) {\n    case '/COMPANIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/COMPANIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/COMPANIES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/COMPANIES/CHANGE_TEMP_COMPANY':\n      return {\n        ...state,\n        tempCompany: action.payload.company\n      };\n    case '/COMPANIES/CHANGE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.map((company: ICompany) => {\n          if (company._id === action.payload.company._id) {\n            company.name = action.payload.company.name;\n            company.businessName = action.payload.company.businessName;\n            company.rut = action.payload.company.rut;\n            company.billing = action.payload.company.billing;\n            company.notifications = action.payload.company.notifications;\n            company.image = action.payload.company.image;\n            company.marker = action.payload.company.marker;\n          }\n          return company;\n        })\n      };\n    case '/COMPANIES/DELETE_COMPANY':\n      return {\n        ...state,\n        companies: state.companies.filter((company: ICompany) => company._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/COMPANIES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardReduxAction, IDashboardState} from '../actions/dashboard.actions';\nimport * as moment from 'moment-timezone';\n\nconst initialState: IDashboardState = {\n  loading: true,\n  source: null,\n  participants: [],\n  requests: [],\n  companies:[],\n  car: null,\n  carEvents: {} ,\n  forms: [],\n  searchForms: [],\n  participantsReceivedPerDate: [],\n  participantsSentPerDate: [],\n  participantPerRange: [],\n  carsPerDate: [],\n  planningPerDate: [],\n  planningProcessPerDate: [],\n  searchText: '',\n  searchFrom: moment().startOf('month').subtract(6, 'months').startOf('month').toDate(),\n  searchTo: moment().toDate(),\n  carsByVenue: [],\n  totalCars: 0,\n  loadingParticipant: null,\n  revisionStats: null,\n  venueStats: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function dashboardReducer(state = initialState, action: DashboardReduxAction): IDashboardState {\n  switch (action.type) {\n    case '/DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS':\n      return {\n        ...state,\n        participants: action.payload.participants,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/DASHBOARD/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/DASHBOARD/CHANGE_RANGE':\n      return {\n        ...state,\n        searchFrom: action.payload.from,\n        searchTo: action.payload.to,\n      };\n    case '/DASHBOARD/LOADING_PARTICIPANT':\n      return {\n        ...state,\n        loadingParticipant: action.payload.loadingParticipant\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE':\n      return {\n        ...state,\n        companies: action.payload.companies,\n        participantsReceivedPerDate: action.payload.participantsReceivedPerDate,\n        participantsSentPerDate: action.payload.participantsSentPerDate,\n        carsPerDate: action.payload.carsPerDate,\n        planningPerDate: action.payload.planningPerDate,\n        planningProcessPerDate: action.payload.planningProcessPerDate,\n        totalCars: action.payload.totalCars,\n        carsByVenue: action.payload.carsByVenue,\n        participantPerRange: action.payload.participantPerRange\n      };\n    case '/DASHBOARD/LOAD_CAR':\n      return {\n        ...state,\n        car: action.payload.car,\n      };\n    case '/DASHBOARD/LOAD_REQUESTS_IN_CAR':\n      return {\n        ...state,\n        requests: action.payload.requests\n      };\n    case '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR':\n      if (state.car && state.car.participants) {\n        return {\n          ...state,\n          car: {\n            ...state.car,\n            participants: [action.payload.participant, ...state.car.participants]\n          }\n        };\n      } else {\n        return state;\n      }\n    case '/DASHBOARD/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/DASHBOARD/LOAD_VENUES_STATS':\n      return {\n        ...state,\n        venueStats: action.payload.venuesStats\n      };\n    case '/DASHBOARD/LOAD_REVISION_STATS':\n      return {\n        ...state,\n        revisionStats: action.payload.revisionStats\n      };\n    case '/DASHBOARD/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/DASHBOARD/CHANGE_FORM_SEARCH':\n      return {\n        ...state,\n        searchForms: action.payload.searchForms\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDamagesReduxAction, IDashboardDamagesState} from \"../actions/dashboardDamages.actions\";\n\nconst initialState: IDashboardDamagesState = {\n  data: {},\n  venues: [],\n  loading: true\n};\n\nexport function dashboardDamagesReducer(state = initialState, action: DashboardDamagesReduxAction): IDashboardDamagesState {\n  switch (action.type) {\n    case '/DASHBOARD/DAMAGES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/DAMAGES/LOAD_DATA':\n      return {\n        ...state,\n        data: action.payload.data\n      };\n    default:\n      return state;\n  }\n}\n","import {DashboardDercoReduxAction, IDashboardDercoState} from \"../actions/dashboardDerco.actions\";\n\nconst initialState: IDashboardDercoState = {\n  cleaning: {\n    loading: false,\n    days: [],\n    clean: [],\n    notClean: [],\n  }\n};\n\nexport function dashboardDercoReducer(state = initialState, action: DashboardDercoReduxAction): IDashboardDercoState {\n  switch (action.type) {\n    case '/DASHBOARD/CLEANING/IS_LOADING':\n      return {\n        ...state,\n        cleaning: {\n          ...state.cleaning,\n          loading: true\n        },\n      };\n    case '/DASHBOARD/CLEANING/LOAD_DATA_DAILY':\n      return {\n        ...state,\n        cleaning: {\n          ...action.payload.cleaning,\n          loading: false\n        },\n\n      };\n\n    default:\n      return state;\n  }\n}\n","import {DashboardTimingReduxAction, IDashboardTimingState} from '../actions/dashboardTiming.actions';\n\nconst initialState: IDashboardTimingState = {\n  data: {\n    months: [],\n    overdue: [],\n    ontime: []\n  },\n  perVenue: {},\n  venues: [],\n  venuesDict: {},\n  loading: true,\n  loadingPerVenue: false\n};\n\nexport function dashboardTimingReducer(state = initialState, action: DashboardTimingReduxAction): IDashboardTimingState {\n  switch (action.type) {\n    case '/DASHBOARD/TIMING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/DASHBOARD/TIMING/LOAD_DATA':\n      const venuesDict: any = {};\n      action.payload.venues.forEach((v: any) => venuesDict[v._id] = v );\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        venuesDict,\n        data: action.payload.data\n      };\n    case '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE':\n      return {\n        ...state,\n        loadingPerVenue: true\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  CANCEL_DELIVERIES,\n  CHANGE_FILTER_DELIVERIES,\n  IDeliveriesActionTypes,\n  IDeliveriesState,\n  LOAD_DELIVERIES,\n  LOAD_FORMS,\n  LOADING_DELIVERIES\n} from '../actions/deliveries.types';\nimport * as moment from 'moment';\n\nconst initialState: IDeliveriesState = {\n  loading: true,\n  source: null,\n  forms: [],\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  },\n  filters: {\n    forms: [],\n    searchText: '',\n    searchDelivery: '',\n    from: moment().subtract(3, 'months').startOf('month'),\n    to: moment().endOf('day')\n  },\n  participants: []\n};\n\n\nexport default function deliveriesReducer(state = initialState, action: IDeliveriesActionTypes): IDeliveriesState {\n  switch (action.type) {\n    case LOADING_DELIVERIES:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case CHANGE_FILTER_DELIVERIES:\n      return {\n        ...state,\n        filters: {\n          ...state.filters,\n          ...action.payload\n        }\n      };\n    case LOAD_FORMS:\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case LOAD_DELIVERIES:\n      return {\n        ...state,\n        participants: action.payload.participants,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case CANCEL_DELIVERIES:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    default:\n      return state;\n  }\n}\n","import { IFormsState,\n  FormReduxActions,\n  FORM_CANCEL_STATUS,\n  FORM_CHANGE_ORDER,\n  FORM_IS_LOADING,\n  FORM_LOAD_STATUS,\n  FORM_LOAD_REQUEST_STATUS\n} from '../actions/form.types';\nimport { MILESTONE_LOAD_REQUEST_STATUS } from '../actions/milestone.types';\n\nconst initialState: IFormsState = {\n  forms: [],\n  requestStatus: [],\n  milestoneTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function formsReducer(state = initialState, action: FormReduxActions): IFormsState {\n  switch (action.type) {\n    case FORM_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case FORM_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case FORM_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case FORM_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case FORM_LOAD_STATUS:\n      return {\n        ...state,\n        forms: action.payload.forms,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case \"/FORM/LOAD_MILESTONE_TYPES\":\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes\n      }\n    default:\n      return state;\n  }\n}\n","import { connectRouter } from 'connected-react-router';\nimport { combineReducers } from 'redux';\nimport { reducer as formReducer } from 'redux-form';\nimport { alertsReducer } from './alerts.reducer';\nimport { billingReducer } from './billing.reducers';\nimport { carriersReducer } from './carriers.reducer';\nimport { carsReducer } from './cars.reducer';\nimport { companiesReducer } from './companies.reducer';\nimport { dashboardReducer } from './dashboard.reducer';\nimport { dashboardDamagesReducer } from './dashboardDamages.reducer';\nimport { dashboardDercoReducer } from './dashboardDerco.reducer';\nimport { dashboardTimingReducer } from './dashboardTiming.reducer';\nimport { inventoriesReducer } from './inventory.reducer';\nimport { inventoriesDashboardReducer } from './inventoryDashboard.reducer';\nimport { labelsReducer } from './labels.reducer';\nimport { modalReducer } from './modal.reducer';\nimport { planningReducer } from './planning.reducer';\nimport { reasonsReducers } from './reasons.reducer';\nimport { regionsReducer } from './regions.reducer';\nimport { requestItemsReducers } from './requestItems.reducer';\nimport { requestsReducers } from './requests.reducer';\nimport { stockReducer } from './stock.reducer';\nimport { usersReducer } from './users.reducer';\nimport { requestStatusReducer } from './requestStatus.reducer';\nimport { requestChannelReducer } from './requestChannel.reducer';\nimport { paymentMethodReducer } from './paymentMethod.reducer';\nimport { venuesReducer } from './venues.reducer';\nimport { versionsReducer } from './versions.reducer';\nimport transmittalReducer from \"./transmittal.reducer\";\nimport { operationTypeReducer } from './operationType.reducer';\nimport { milestoneReducer } from './milestone.reducer';\nimport { milestoneTypeReducer } from './milestoneType.reducer';\nimport { formsReducer } from './form.reducer';\nimport { colorsReducer } from './color.reducer';\nimport {statsDashboardReducer} from \"./statsDashboard.reducer\";\nimport {bordersReducer} from \"./borders.reducer\";\nimport billingSettingsReducer from './billingSettings.reducer';\nimport deliveriesReducer from './deliveries.reducer';\n\nexport default (history: any) => combineReducers({\n  users: usersReducer,\n  cars: carsReducer,\n  forms: formsReducer,\n  colors: colorsReducer,\n  transmittal: transmittalReducer,\n  modal: modalReducer,\n  carriers: carriersReducer,\n  dashboard: dashboardReducer,\n  dashboardDamages: dashboardDamagesReducer,\n  dashboardTiming: dashboardTimingReducer,\n  billing: billingReducer,\n  dashboardDerco: dashboardDercoReducer,\n  inventories: inventoriesReducer,\n  inventoryDashboard: inventoriesDashboardReducer,\n  alerts: alertsReducer,\n  reasons: reasonsReducers,\n  versions: versionsReducer,\n  requestStatus: requestStatusReducer,\n  paymentMethod: paymentMethodReducer,\n  requestChannel: requestChannelReducer,\n  deliveries: deliveriesReducer,\n  venues: venuesReducer,\n  companies: companiesReducer,\n  labels: labelsReducer,\n  requests: requestsReducers,\n  requestItems: requestItemsReducers,\n  operationType: operationTypeReducer,\n  billingSettings: billingSettingsReducer,\n  milestone: milestoneReducer,\n  milestoneType: milestoneTypeReducer,\n  regions: regionsReducer,\n  stock: stockReducer,\n  statsDashboard: statsDashboardReducer,\n  planning: planningReducer,\n  border: bordersReducer,\n  form: formReducer,\n  router: connectRouter(history)\n});\n","import * as unorm from 'unorm';\nimport {\n  IInventoryCar\n} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventoryState, InventoryReduxAction} from '../actions/inventory.actions';\n\nconst initialState: IInventoryState = {\n  inventories: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  inventoryCar: null,\n  source: null,\n  loadingDetail: true,\n  fetchingDetail: false,\n  summary: {\n    _id: '',\n    name: '',\n    status: '',\n    createdAt: null,\n    finalizedAt: null\n  },\n  detail: {\n    venues: [],\n    cars: []\n  },\n  labels: [],\n  detailByVenue: [],\n  detailByBrand: [],\n  carsTable: [],\n  cardTypes: [],\n  cardProperties: [],\n  selectedItems: {},\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport interface IFilterCar {\n  text: string;\n  type: string;\n  property: string;\n  venues: string[];\n  states: string[];\n}\n\nexport function inventoriesReducer(state = initialState, action: InventoryReduxAction): IInventoryState {\n  switch (action.type) {\n    case '/INVENTORIES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORIES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/INVENTORIES/LOAD_DATA':\n      return {\n        ...state,\n        inventories: action.payload.inventories,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case '/INVENTORIES/UPDATE_INVENTORY_CAR':\n      return {\n        ...state,\n        inventoryCar: action.payload.inventoryCar\n      };\n    case '/INVENTORIES/CHANGE_FILTER':\n      return {\n        ...state,\n        carsTable: processCars(state.detail.cars, state.selectedItems, action.payload.filter),\n        filter: action.payload.filter\n      };\n    case '/INVENTORIES/CHANGE_SELECTED':\n      const newSelected = processSelected(state.selectedItems, action.payload.item);\n      return {\n        ...state,\n        selectedItems: newSelected,\n        carsTable: processCars(state.detail.cars, newSelected, state.filter)\n      };\n    case '/INVENTORIES/LOADING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        loadingDetail: action.payload.loadingDetail\n      };\n    case '/INVENTORIES/FETCHING_INVENTORY_DETAIL':\n      return {\n        ...state,\n        fetchingDetail: action.payload.fetchingDetail\n      };\n    case '/INVENTORIES/LOAD_INVENTORY_DATA':\n      const selectedItems = action.payload.resetFilter ? initialState.selectedItems : state.selectedItems;\n      const filter = action.payload.resetFilter ? initialState.filter : state.filter;\n      return {\n        ...state,\n        ...processPropertyCars(action.payload.detail.cars),\n        carsTable: processCars(action.payload.detail.cars, selectedItems, filter),\n        selectedItems,\n        filter,\n        labels: action.payload.labels,\n        summary: action.payload.summary,\n        inventorySettings: action.payload.inventorySettings,\n        detailByVenue: action.payload.detailByVenue,\n        detail: action.payload.detail,\n        detailByBrand: action.payload.detailByBrand\n      };\n    case '/INVENTORIES/ADD_COMMENT':\n      if (state.inventoryCar) {\n        return {\n          ...state,\n          inventoryCar: {\n            ...state.inventoryCar,\n            comments: [...state.inventoryCar.comments, action.payload.inventoryComment]\n          }\n        };\n      } else {\n        return state;\n      }\n    default:\n      return state;\n  }\n}\n\nfunction processSelected(selectedItems: any, item: string) {\n  let newSelectedItems = {...selectedItems};\n  if (newSelectedItems.hasOwnProperty(item)) {\n    delete (newSelectedItems as any)[item];\n  } else {\n    newSelectedItems = {\n      ...newSelectedItems,\n      [item]: true\n    };\n  }\n  return newSelectedItems;\n}\n\ninterface IPropertyCar {\n  cardProperties: string[];\n  cardTypes: string[];\n}\n\nfunction processPropertyCars(cars: IInventoryCar[]): IPropertyCar {\n  const propertyCars: IPropertyCar = {\n    cardProperties: [],\n    cardTypes: []\n  };\n  for (const car of cars) {\n    if (car.car?.property && !propertyCars.cardProperties.includes(car.car.property)) {\n      propertyCars.cardProperties.push(car.car.property);\n    }\n    if (car.car?.type && !propertyCars.cardTypes.includes(car.car.type)) {\n      propertyCars.cardTypes.push(car.car.type);\n    }\n  }\n  return propertyCars;\n}\n\nfunction processCars(cars: IInventoryCar[], selectedItems: { [key: string]: any }, filter: IFilterCar) {\n  const products: any[] = [];\n  // const missincars = [];\n  for (const car of cars) {\n    let add = true;\n    if (filter && filter.venues && filter.venues.length && car.venue) {\n      add = (filter.venues as any).includes(car.venue._id);\n      if (!add && car.venueFound) {\n        add = (filter.venues as any).includes(car.venueFound._id);\n      }\n    }\n    if (add && filter && filter.states && filter.states.length && car.status) {\n      add = (filter.states as any).includes(car.status);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.type && filter.type.length) {\n      add = car.car.type === filter.type;\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element);\n      /*add = `${car.car.vin}${car.car.brand}${car.car.denomination}${car.car.patent}`.normalize('NFD')\n        .replace(/[\\u0300-\\u036f]/g, '')\n        .toLowerCase()\n        .includes(filter.text.toLowerCase());*/\n    }\n    const patent: string = car.car?.patent ? car.car.patent : '';\n    // if (add && filter && filter && filter.type.length) {\n    //   if (filter.type === 'new') {\n    //     add = patent.length === 0;\n    //   } else if (filter.type === 'used') {\n    //     add = patent.length !== 0;\n    //   }\n    // }\n    if (add && (car as any).car?._id) {\n      products.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        venue: car.venue ? car.venue.name : '-',\n        files: car.files && car.files.length ? car.files : [],\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFound: car.venueFound ? car.venueFound.name : '-',\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        selected: selectedItems.hasOwnProperty((car as any)._id),\n        status: car.status,\n        option: car.status\n      });\n    } else {\n      // if(car.status !==\"pending\"){\n        // console.log('car', car);\n        // missincars.push(car)\n      // }\n    }\n  }\n  // console.log('missincars', missincars);\n  return products;\n}\n","import {\n  IInventoryDashboardState,\n  InventoryDashboardReduxAction\n} from '../actions/inventoryDashboard.actions';\n\nconst initialState: IInventoryDashboardState = {\n  filter: {\n    text: '',\n    property: '',\n    type: '',\n    venues: [],\n    states: []\n  },\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  venues: [],\n  monthlyReport: [],\n  loading: true\n};\n\nexport function inventoriesDashboardReducer(state = initialState, action: InventoryDashboardReduxAction): IInventoryDashboardState {\n  switch (action.type) {\n    case '/INVENTORY_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA':\n      return {\n        ...state,\n        loading: false,\n        venues: action.payload.venues,\n        inventorySettings: action.payload.inventorySettings,\n        monthlyReport: action.payload.monthlyReport\n      };\n    case '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED':\n      return {\n        ...state,\n        inventorySettings: action.payload.inventorySettings,\n        filter: {\n          ...action.payload.filter,\n          venues: action.payload.filter.venues,\n        },\n        monthlyReport: action.payload.monthlyReport\n      };\n    default:\n      return state;\n  }\n}\n","import {ILabelsState, LabelsReduxAction} from '../actions/labels.actions';\n\nconst initialState: ILabelsState = {\n  labels: [],\n  inventorySettings: {\n    report: null,\n    leftoverDifferentVenue: false,\n    pending: \"\",\n    pendingClass: \"aqua\",\n    pendingColor: \"\",\n    found: \"\",\n    foundClass: \"green\",\n    foundColor: \"\",\n    missing: \"\",\n    missingClass: \"red\",\n    missingColor: \"\",\n    leftover: \"\",\n    leftoverClass: \"yellow\",\n    leftoverColor: \"\",\n    reported: \"\",\n    reportedClass: \"gray-dark\",\n    reportedColor: \"\"\n  },\n  loading: true,\n  tempLabel: {\n    _id: '',\n    description: '',\n    name: '',\n    color: '',\n    affected: [],\n    sendTo: '',\n    requireCustomText: false,\n    isExhibition: false,\n    active: true\n  },\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function labelsReducer(state = initialState, action: LabelsReduxAction): ILabelsState {\n  switch (action.type) {\n    case '/LABELS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/LABELS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/LABELS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/LABELS/CHANGE_TEMP_LABEL':\n      return {\n        ...state,\n        tempLabel: action.payload.tempLabel\n      };\n    case '/LABELS/CREATE_LABEL':\n      return {\n        ...state,\n        labels: [action.payload.label, ...state.labels],\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count + 1\n        }\n      };\n    case '/LABELS/CHANGE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.map((label) => {\n          if (label._id === action.payload.label._id) {\n            return action.payload.label;\n          }\n          return label;\n        })\n      };\n    case '/LABELS/DELETE_LABEL':\n      return {\n        ...state,\n        labels: state.labels.filter((label: any) => label._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/LABELS/LOAD_LABELS':\n      return {\n        ...state,\n        labels: action.payload.labels,\n        inventorySettings: action.payload.inventorySettings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IMilestoneState,\n  MilestoneReduxActions,\n  MILESTONE_CANCEL_STATUS,\n  MILESTONE_CHANGE_ORDER,\n  MILESTONE_IS_LOADING,\n  MILESTONE_LOAD_STATUS,\n  MILESTONE_LOAD_FORMS,\n  MILESTONE_LOAD_REQUEST_STATUS,\n  MILESTONE_UDPATE_STATUS,\n  MILESTONE_LOAD_TYPES\n} from '../actions/milestone.types';\n\nconst initialState: IMilestoneState = {\n  milestones: [],\n  milestoneTypes: [],\n  requestStatus: [],\n  forms: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneReducer(state = initialState, action: MilestoneReduxActions): IMilestoneState {\n  switch (action.type) {\n    case MILESTONE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n     case MILESTONE_UDPATE_STATUS:\n      return {\n        ...state,\n        milestones: [...state.milestones.map((milestone) => {\n          if (milestone._id === action.payload.milestone._id) {\n            return {\n              milestone,\n              ...action.payload.milestone\n            };\n          }\n          return milestone;\n        })]\n      };\n    case MILESTONE_LOAD_FORMS:\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case MILESTONE_LOAD_TYPES:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes\n      };\n    case MILESTONE_LOAD_REQUEST_STATUS:\n      return {\n        ...state,\n        requestStatus: action.payload.requestStatus\n      };\n    case MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { IMilestoneTypeState,\n  MilestoneTypeReduxActions,\n  MILESTONE_TYPE_CANCEL_STATUS,\n  MILESTONE_TYPE_CHANGE_ORDER,\n  MILESTONE_TYPE_IS_LOADING,\n  MILESTONE_TYPE_LOAD_STATUS\n} from '../actions/milestoneType.types';\n\nconst initialState: IMilestoneTypeState = {\n  milestoneTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function milestoneTypeReducer(state = initialState, action: MilestoneTypeReduxActions): IMilestoneTypeState {\n  switch (action.type) {\n    case MILESTONE_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case MILESTONE_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case MILESTONE_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case MILESTONE_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IModalState, ModalReduxAction} from '../actions/modal.actions';\n\nconst initialState: IModalState = {\n  title: '',\n  body: null,\n  footer: null\n};\n\nexport function modalReducer(state = initialState, action: ModalReduxAction): IModalState {\n  switch (action.type) {\n    case '/MODAL/LOAD_DATA':\n      setTimeout(() => {\n        ($('#andesModal') as any).modal('show');\n      }, 100);\n      return {\n        ...state,\n        title: action.payload.title,\n        body: action.payload.body,\n        footer: action.payload.footer ? action.payload.footer : null\n      };\n    case '/MODAL/CLEAR':\n      return initialState;\n    default:\n      return state;\n  }\n}\n","import { IOperationTypeState,\n  OperationTypeReduxActions,\n  OPERATION_TYPE_CANCEL_STATUS,\n  OPERATION_TYPE_CHANGE_ORDER,\n  OPERATION_TYPE_IS_LOADING,\n  OPERATION_TYPE_LOAD_STATUS\n} from '../actions/operationType.types';\n\nconst initialState: IOperationTypeState = {\n  operationTypes: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function operationTypeReducer(state = initialState, action: OperationTypeReduxActions): IOperationTypeState {\n  switch (action.type) {\n    case OPERATION_TYPE_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case OPERATION_TYPE_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case OPERATION_TYPE_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case OPERATION_TYPE_LOAD_STATUS:\n      return {\n        ...state,\n        operationTypes: action.payload.operationTypes,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IPaymentMethodState,\n  PAYMENT_METHOD_CANCEL,\n  PAYMENT_METHOD_CHANGE_ORDER,\n  PAYMENT_METHOD_IS_LOADING,\n  PAYMENT_METHOD_LOAD,\n  PaymentMethodReduxActions\n} from '../actions/paymentMethod.types';\n\nconst initialState: IPaymentMethodState = {\n  paymentMethods: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function paymentMethodReducer(state = initialState, action: PaymentMethodReduxActions): IPaymentMethodState {\n  switch (action.type) {\n    case PAYMENT_METHOD_CANCEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case PAYMENT_METHOD_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case PAYMENT_METHOD_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case PAYMENT_METHOD_LOAD:\n      return {\n        ...state,\n        paymentMethods: action.payload.paymentMethods,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IPlanningState, PlanningReduxAction} from \"../actions/planning.action\";\n\nconst initialState: IPlanningState = {\n  plannings: [],\n  loading: true,\n  source: null,\n  pagination: {\n     count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function planningReducer(state = initialState, action: PlanningReduxAction): IPlanningState {\n  switch (action.type) {\n    case '/PLANNING/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/PLANNING/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/PLANNING/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/PLANNING/LOAD_PLANNING':\n      return {\n        ...state,\n        plannings: action.payload.plannings,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IReasonsState,\n  ReasonsReduxActions,\n  REASON_CANCEL_REASON,\n  REASON_CHANGE_ORDER,\n  REASON_IS_LOADING,\n  REASON_LOAD_REASONS\n} from '../actions/reasons.types';\n\nconst initialState: IReasonsState = {\n  reasons: [],\n  reason: {},\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function reasonsReducers(state = initialState, action: ReasonsReduxActions): IReasonsState {\n  switch (action.type) {\n    case REASON_CANCEL_REASON:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REASON_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REASON_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REASON_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {RegionReduxAction, IRegionsState} from '../actions/regions.actions';\n\nconst initialState: IRegionsState = {\n  regions: [],\n  tempRegion: {\n    name: '',\n    code: ''\n  },\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function regionsReducer(state = initialState, action: RegionReduxAction): IRegionsState {\n  switch (action.type) {\n    case '/REGIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/REGIONS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/REGIONS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/REGIONS/CHANGE_TEMP_REGION':\n      return {\n        ...state,\n        tempRegion: action.payload.region\n      };\n    case '/REGIONS/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import { ISalesChannelState,\n  RequestChannelReduxActions,\n  REQUEST_CANCEL_CHANNEL,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CHANNEL\n} from '../actions/requestChannel.types';\n\nconst initialState: ISalesChannelState = {\n  channels: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestChannelReducer(state = initialState, action: RequestChannelReduxActions): ISalesChannelState {\n  switch (action.type) {\n    case REQUEST_CANCEL_CHANNEL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_CHANNEL:\n      return {\n        ...state,\n        channels: action.payload.channels,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {\n  IRequestItemsState,\n  RequestItemsReduxActions,\n  REQUEST_ITEMS_CANCEL_REQUEST,\n  REQUEST_ITEMS_CHANGE_FILTER,\n  REQUEST_ITEMS_CHANGE_ORDER,\n  REQUEST_ITEMS_CREATE_ITEM,\n  REQUEST_ITEMS_DELETE_ITEM,\n  REQUEST_ITEMS_IS_LOADING,\n  REQUEST_ITEMS_LOAD_CARRIERS,\n  REQUEST_ITEMS_LOAD_ITEM_STATUS,\n  REQUEST_ITEMS_LOAD_PROPERTIES,\n  REQUEST_ITEMS_LOAD_REASONS,\n  REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n  REQUEST_ITEMS_LOAD_VENUES,\n  REQUEST_ITEMS_UPDATE_ITEM, REQUEST_ITEMS_LOAD_SETTINGS, REQUEST_ITEMS_LOAD_USERS\n} from '../actions/requestItems.types';\nimport { requestSettings } from '../components/Request/defaults';\nimport * as moment from 'moment';\n\nconst initialState: IRequestItemsState = {\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  venues: [],\n  users: [],\n  properties: [],\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  loading: true,\n  source: null,\n  requestSettings,\n  filters: {\n    request: '',\n    transmittal: '',\n    ticket: '',\n    conectaID: '',\n    entry: '',\n    text: '',\n    sellerText: '',\n    venues: [],\n    users: [],\n    properties: [],\n    status: [],\n    from: moment().subtract(12, 'months').startOf('day'),\n    to: moment().endOf('day')\n  },\n  options: {\n    orderBy: 'meta.request.number',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestItemsReducers(state = initialState, action: RequestItemsReduxActions): IRequestItemsState {\n  switch (action.type) {\n    case REQUEST_ITEMS_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_ITEMS_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_ITEMS_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_ITEMS_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_ITEMS_LOAD_VENUES:\n      return {\n        ...state,\n        venues: action.payload.venues\n      };\n    case REQUEST_ITEMS_LOAD_USERS:\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    case REQUEST_ITEMS_LOAD_PROPERTIES:\n        return {\n          ...state,\n          properties: action.payload.properties\n        };\n    case REQUEST_ITEMS_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_ITEMS_LOAD_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_ITEMS_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_ITEMS_CHANGE_FILTER:\n      return {\n        ...state,\n        filters: {\n          ...state.filters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case REQUEST_ITEMS_LOAD_REQUESTS_ITEMS:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_ITEMS_CREATE_ITEM:\n      return {\n        ...state,\n        requestItems: [action.payload.item, ...state.requestItems]\n      };\n    case REQUEST_ITEMS_UPDATE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.map((item) => {\n          if (item._id === action.payload.item._id) {\n            return {\n              item,\n              ...action.payload.item\n            };\n          }\n          return item;\n        })]\n      };\n    case REQUEST_ITEMS_DELETE_ITEM:\n      return {\n        ...state,\n        requestItems: [...state.requestItems.filter((item) => {\n          return item._id !== action.payload.item._id;\n        })]\n      };\n    default:\n      return state;\n  }\n}\n","import { IRequestStatusState,\n  RequestStatusReduxActions,\n  REQUEST_CANCEL_STATUS,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_STATUS\n} from '../actions/requestStatus.types';\n\nconst initialState: IRequestStatusState = {\n  status: [],\n  loading: true,\n  source: null,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestStatusReducer(state = initialState, action: RequestStatusReduxActions): IRequestStatusState {\n  switch (action.type) {\n    case REQUEST_CANCEL_STATUS:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_STATUS:\n      return {\n        ...state,\n        status: action.payload.status,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import * as moment from 'moment-timezone';\nimport {\n  IRequestsState,\n  REQUEST_CANCEL_REQUEST,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_DELETE_REQUEST_IN_LIST,\n  REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CARRIERS, REQUEST_LOAD_ITEMS,\n  REQUEST_LOAD_REASONS,\n  REQUEST_LOAD_REQUEST,\n  REQUEST_LOAD_REQUEST_ITEM_STATUS,\n  REQUEST_LOAD_REQUESTS,\n  REQUEST_LOAD_SETTINGS,\n  REQUEST_TAB_STATUS,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n  RequestsReduxActions\n} from '../actions/requests.types';\nimport { requestSettings } from '../components/Request/defaults';\n\nconst initialState: IRequestsState = {\n  requests: [],\n  requestItems: [],\n  reasons: [],\n  carriers: [],\n  requestOpen: [],\n  requestItemsById: {},\n  requestItemStatus: [],\n  requestItemStatusMin: 0,\n  requestItemStatusMax: 100,\n  request: {},\n  loading: true,\n  source: null,\n  requestSettings,\n  options:{\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function requestsReducers(state = initialState, action: RequestsReduxActions): IRequestsState {\n  switch (action.type) {\n    case REQUEST_CANCEL_REQUEST:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case REQUEST_IS_LOADING:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case REQUEST_LOAD_REASONS:\n      return {\n        ...state,\n        reasons: action.payload.reasons\n      };\n    case REQUEST_LOAD_CARRIERS:\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case REQUEST_LOAD_SETTINGS:\n      return {\n        ...state,\n        requestSettings: action.payload.requestSettings\n      };\n    case REQUEST_TAB_STATUS:\n      return {\n        ...state,\n        requestOpen: state.requestOpen.includes(action.payload.request)\n          ? [...state.requestOpen.filter(request => request !== action.payload.request)]\n          : [...state.requestOpen, action.payload.request]\n      };\n    case REQUEST_CHANGE_ORDER:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case REQUEST_LOAD_REQUEST_ITEM_STATUS:\n      return {\n        ...state,\n        requestItemStatus: action.payload.requestItemStatus,\n        requestItemStatusMin: action.payload.min,\n        requestItemStatusMax: action.payload.max\n      };\n    case REQUEST_LOAD_REQUESTS:\n      return {\n        ...state,\n        requests: action.payload.requests,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = [...request.items, action.payload.item];\n          }\n          return request;\n        })\n      };\n    case REQUEST_LOAD_ITEMS:\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          [action.payload.request]: action.payload.items\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_LIST:\n      let updateItem: any = {};\n      if(state.requestItemsById.hasOwnProperty(action.payload.request)){\n        updateItem[action.payload.request] = state.requestItemsById[action.payload.request].map((item:any)=>{\n          if(item._id === action.payload.item._id){\n            return action.payload.item\n          }\n          return item;\n        })\n      }\n      return {\n        ...state,\n        requestItemsById: {\n          ...state.requestItemsById,\n          ...updateItem\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].map((request) => {\n          if (request._id === action.payload.idRequest) {\n            request.updatedAt = moment().toDate();\n            request.items = request.items.filter((item) => {\n              return item._id !== action.payload.item._id;\n            });\n          }\n          return request;\n        })\n      };\n    case REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!, action.payload.item]\n        }\n      };\n    case REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request!.items!.map((item) => {\n            if (item._id === action.payload.item._id) {\n              return {\n                item,\n                ...action.payload.item\n              };\n            }\n            return item;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL:\n      return {\n        ...state,\n        request: {\n          ...state.request,\n          items: [...state.request.items!.filter((item) => {\n            return item._id !== action.payload.item._id;\n          })]\n        }\n      };\n    case REQUEST_DELETE_REQUEST_IN_LIST:\n      return {\n        ...state,\n        requests: [...state.requests].filter((request) => {\n          return request._id !== action.payload.id;\n        })\n      };\n    case REQUEST_LOAD_REQUEST:\n      return {\n        ...state,\n        request: action.payload.request\n      };\n    default:\n      return state;\n  }\n}\n","import {IStatsDashboardState, StatsDashboardReducerAction} from '../actions/statsDashboard.actions';\n\nconst initialState : IStatsDashboardState = {\n  loading: true,\n  studios: [],\n  users: [],\n  currentStudio: null,\n  tempStudio: {\n    _id: '',\n    users: [],\n    name: '',\n    type: '',\n    embedURL: '',\n    team: null\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\n\nexport function statsDashboardReducer(state: IStatsDashboardState = initialState, action: StatsDashboardReducerAction) {\n  switch (action.type) {\n    case '/STATS_DASHBOARD/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STATS_DASHBOARD/LOAD_STUDIOS':\n      return {\n        ...state,\n        studios: action.payload.studios\n      };\n    case '/STATS_DASHBOARD/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO':\n      return {\n        ...state,\n        tempStudio: action.payload.tempStudio\n      };\n    case '/STATS_DASHBOARD/DELETE_USER':\n      return state;\n    case '/STATS_DASHBOARD/LOAD_STUDIOS_USERS':\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n\n}\n\n","import {IStockState, StockReducerAction} from \"../actions/stock.actions\";\nimport * as unorm from \"unorm\";\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport * as moment from 'moment-timezone';\nimport { StatusHistory } from \"../../../../../src/app/models/history.types\";\n\nconst initialState: IStockState = {\n  cars: [],\n  carsTable: [],\n  filter: {\n    text: '',\n    property: '',\n    status: [StatusHistory.available, StatusHistory.inTransit],\n    venues: [],\n    colors: [],\n    brands: [],\n    denominations: [],\n    from: moment().subtract(30, 'days').startOf('day'),\n    to: moment().endOf('day')\n  },\n  defaultSorted: [{\n    dataField: 'daysInVenue',\n    order: 'desc'\n  }],\n  dataFilters:{\n    venues:[],\n    colors:[],\n    brands:[],\n    denominations:[],\n    types:[],\n    properties:[],\n  },\n  vinInStock: {},\n  searching: false,\n  message: \"\",\n  loading: true,\n  source: null,\n  rangeOptions: {\n    startDate: moment().subtract(11, 'months').startOf('month').toDate(),\n    endDate: moment().toDate(),\n    maxDate: moment().toDate(),\n    locale: {\n      format: 'DD/MM/YYYY',\n      customRangeLabel: 'Período personalizado',\n      applyLabel: 'Aplicar',\n      cancelLabel: 'Cancelar'\n    },\n    ranges: {\n      // 'Este mes': [moment().startOf('month').startOf('month').toDate(), moment().endOf('month').toDate()],\n      // 'Últimos 3 meses': [moment().startOf('month').subtract(3, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n      // 'Últimos 6 meses': [moment().startOf('month').subtract(6, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n      // 'Último año': [moment().startOf('month').subtract(12, 'months').startOf('month').toDate(), moment().endOf('month').toDate()]\n    },\n    opens: 'left'\n  }\n};\n\nexport interface IFilterStock {\n  text: string;\n  status: string[];\n  property: string;\n  venues: string[];\n  colors: string[];\n  brands: string[];\n  denominations: string[];\n  from: any;\n  to: any;\n}\n\n\nexport function stockReducer(state = initialState, action: StockReducerAction) {\n  switch (action.type) {\n    case '/STOCK/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/STOCK/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n     case '/STOCK/CHANGE_FILTER':\n      return {\n        ...state,\n        ...processCars(state.cars, action.payload.filter),\n        filter: action.payload.filter,\n        searching: isSearching(action.payload.filter)\n      };\n    case '/STOCK/CHANGE_ORDER':\n      return {\n        ...state,\n        defaultSorted: [action.payload.order]\n      }\n    case '/STOCK/LOAD':\n      let rangeOptions: any = state.rangeOptions;\n      let filter: any = state.filter;\n      if (action.payload.inventories.length && !Object.keys(state.rangeOptions.ranges as any).length) {\n        if (action.payload.inventories.length === 2) {\n          rangeOptions['ranges']['Último inventario'] = [moment(action.payload.inventories[0].createdAt).startOf('day'), moment().endOf('day')];\n          rangeOptions['ranges']['Penúltimo inventario'] = [moment(action.payload.inventories[1].createdAt).startOf('day'), moment().endOf('day')];\n          rangeOptions['startDate'] = moment(action.payload.inventories[0].createdAt).startOf('day');\n          rangeOptions['endDate'] = moment().endOf('day');\n          filter['from'] = moment(action.payload.inventories[0].createdAt).startOf('day');\n          filter['to'] = moment().endOf('day');\n        }\n        if (action.payload.inventories.length === 1) {\n          rangeOptions['ranges']['Último inventario'] = [moment(action.payload.inventories[0].createdAt).startOf('day'), moment(action.payload.inventories[0].finalizedAt).endOf('day')];\n          rangeOptions['startDate'] = moment(action.payload.inventories[0].createdAt).startOf('day');\n          rangeOptions['endDate'] = moment().endOf('day');\n          filter['from'] = moment(action.payload.inventories[0].createdAt).startOf('day');\n          filter['to'] = moment().endOf('day');\n        }\n      }\n      return {\n        ...state,\n        cars: action.payload.cars,\n        ...processCars(action.payload.cars, state.filter),\n        dataFilters: processfilters(action.payload.cars),\n        message: action.payload.message,\n        filter,\n        rangeOptions\n      };\n    default:\n      return state;\n  }\n}\n\nfunction isSearching(filter: IFilterStock){\n  const {text, brands, venues, colors, denominations, property, status} = filter;\n  return !!(text.length || brands.length || venues.length || colors.length || denominations.length || property.length || status.length);\n}\n\nfunction processfilters(cars:IInventoryCar[]){\n  const venues: any[] = [],\n    colors: any[] = [],\n    brands: any[] = [],\n    denominations: any[] = [],\n    types: any[] = [],\n    properties: any[] = [];\n  const venuesKeys: string[] = [],\n    colorsKeys: string[] = [],\n    brandsKeys: string[] = [],\n    denominationsKeys: string[] = [],\n    typesKeys: string[] = [],\n    propertiesKeys: string[] = [];\n\n  for (const car of cars) {\n\n    if (!car.car)\n      continue;\n    const {color, property, type, brand, denomination} = car.car;\n    const {from, to } = car as any;\n    let venue = to ? to : from ? from : null;\n    let venueFound = to ? to : from ? from : null;\n    if (brand && brand.length && !brandsKeys.includes(brand)) {\n      brandsKeys.push(brand);\n      brands.push(brand);\n    }\n    if (color && color.length && !colorsKeys.includes(color)) {\n      colorsKeys.push(color);\n      colors.push(color);\n    }\n    if (denomination && denomination.length && !denominationsKeys.includes(denomination)) {\n      denominationsKeys.push(denomination);\n      denominations.push(denomination);\n    }\n    if (type && type.length && !typesKeys.includes(type)) {\n      typesKeys.push(type);\n      types.push(type);\n    }\n    if (property && property.length && !propertiesKeys.includes(property)) {\n      propertiesKeys.push(property);\n      properties.push(property);\n    }\n\n    if (venueFound && !venuesKeys.includes(venueFound._id)) {\n      venuesKeys.push(venueFound._id);\n      venues.push(venueFound);\n    }\n    if (venue && !venuesKeys.includes(venue._id)) {\n      venuesKeys.push(venue._id);\n      venues.push(venue);\n    }\n\n  }\n  return {\n    venues: venues.sort(function(a, b){\n      if(a.name < b.name) { return -1; }\n      if(a.name > b.name) { return 1; }\n      return 0;\n    }),\n    colors: colors.sort(),\n    brands: brands.sort(),\n    denominations: denominations.sort(),\n    types: types.sort(),\n    properties: properties.sort()\n  }\n}\n\nfunction processCars(cars: IInventoryCar[], filter: IFilterStock): { carsTable: any[]; vinInStock: any; } {\n  const data: any[] = [];\n  let vinInStock: any = {};\n  for (const car of cars) {\n\n    if (!car.car)\n      continue;\n\n    let add = true;\n    let venue = (car as any).to ? (car as any).to : (car as any).from;\n\n    if (filter.from) {\n      add = moment(car.createdAt).isSameOrAfter(filter.from);\n    }\n    if (add && filter.to) {\n      add = moment(car.createdAt).isSameOrBefore(filter.to);\n    }\n    if (add && filter && filter.venues && filter.venues.length && venue) {\n      add = (filter.venues as any).includes(venue._id);\n    }\n    if (add && filter && filter.brands && filter.brands.length && car.car.brand) {\n      add = (filter.brands as any).includes(car.car.brand);\n    }\n    if (add && filter && filter.denominations && filter.denominations.length && car.car.denomination) {\n      add = (filter.denominations as any).includes(car.car.denomination);\n    }\n    if (add && filter && filter.colors && filter.colors.length && car.car.color) {\n      add = (filter.colors as any).includes(car.car.color);\n    }\n    if (add && filter && filter.property && filter.property.length) {\n      add = car.car.property === filter.property;\n    }\n    if (add && filter && filter.status && filter.status.length) {\n      add = filter.status.includes(car.status);\n    }\n    if (add && filter && filter.text && filter.text.length) {\n      const result: boolean[] = filter.text.toLowerCase().split(' ').map((text) => (\n        unorm.nfd(`${car.car.vin}${car.car.brand}${car.car.color}${car.car.denomination}${car.car.patent}${car.car.internalNumber}`)\n          .replace(/[\\u0300-\\u036f]/g, '')\n          .toLowerCase()\n          .includes(text.toLowerCase())\n      ));\n      add = result.every((element: boolean) => element);\n    }\n\n    const patent: string = car.car.patent ? car.car.patent : '';\n    if (add) {\n      const {vin} = car.car;\n      if (!vinInStock.hasOwnProperty(vin)) {\n        vinInStock[vin] = {\n        }\n      }\n      const venueFoundID = venue ? venue._id : '-';\n      let daysInVenue = null;\n      let daysPermanence = moment().diff(moment(car.car.createdAt), 'days');\n      let receptionVenue = null;\n\n      if (car.car?.meta?.location?.venue && car.car.meta.location.venue._id === venueFoundID) {\n        receptionVenue = car.car.meta.location.checkedDate;\n        daysInVenue = moment().diff(moment(receptionVenue), 'days');\n      }\n\n      data.push({\n        _id: (car as any)._id,\n        carID: (car as any).car._id,\n        vin: car.car.vin,\n        brand: car.car.brand,\n        denomination: car.car.denomination,\n        internalNumber: car.car.internalNumber,\n        label: car.label,\n        labelName: car.label && car.label.hasOwnProperty('name') ? car.label.name : 'z',\n        labelBy: car.labelBy,\n        color: car.car.color,\n        labelText: car.labelText,\n        meta: car.car.meta,\n        venue: (car as any).to ? (car as any).to.name : (car as any).from ? (car as any).from.name : '-',\n        images: car.images && car.images.length ? car.images : [],\n        comments: car.comments && car.comments.length ? car.comments : [],\n        countComments: car.comments && car.comments.length ? car.comments.length : 0,\n        venueFoundID,\n        venueFound: (car as any).to ? (car as any).to.name : (car as any).from ? (car as any).from.name : '-',\n        receptionVenue,\n        lastUpdate: car.createdAt,\n        daysInVenue,\n        movements: car.car.events.length,\n        daysPermanence,\n        patent,\n        inventoriedBy: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n        status: car.status,\n        option: car.status\n      });\n    }\n  }\n  return {\n    carsTable: data,\n    vinInStock\n  };\n}\n\n","import {\n  CANCEL_REQUEST_TRANSMITTAL,\n  CHANGE_ORDER_TRANSMITTAL,\n  CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_TRANSMITTAL,\n  FILTER_REQUEST_ITEMS_TRANSMITTAL,\n  ITransmittalActionTypes,\n  ITransmittalState,\n  LOAD_CARRIERS_TRANSMITTAL,\n  LOAD_DRIVERS_TRANSMITTAL,\n  LOAD_MILESTONE_TYPES_TRANSMITTAL,\n  LOAD_REQUEST_ITEMS_TRANSMITTAL,\n  LOAD_TRANSMITTAL,\n  LOAD_TRANSMITTAL_RESUME,\n  LOAD_VENUES_TRANSMITTAL,\n  LOADING_REQUEST_ITEMS_TRANSMITTAL,\n  LOADING_TRANSMITTAL,\n  TOOGLE_TAB_TRANSMITTAL,\n  TRANSPORT_MILESTONE_LOAD_STATUS,\n  UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_TRANSMITTAL\n} from '../actions/transmittal.types';\nimport {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\n\nconst initialState: ITransmittalState<ITransmittal> = {\n  loading: true,\n  requestItemsLoading: true,\n  data: [],\n  carriers: [],\n  venues: [],\n  drivers: [],\n  milestoneTypes: [],\n  milestones: [],\n  transmittalOpen: [],\n  source: null,\n  requestItems: [],\n  resume: [],\n  requestItemsfilters: {\n    request: '',\n    entry: '',\n    text: '',\n    venues: [],\n    properties: [],\n    status: [],\n    from: null,\n    to: null\n  },\n  requestItemsPagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  },\n  options: {\n    orderBy: '_id',\n    orderType: 'descending'\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 0\n  }\n};\n\nexport default function transmittalReducer(state= initialState, action: ITransmittalActionTypes): ITransmittalState {\n  switch (action.type) {\n    case LOADING_TRANSMITTAL:\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case LOAD_TRANSMITTAL:\n      return {\n        ...state,\n        data: action.payload.data,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case DELETE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.filter((item: any) => {\n                return item._id !== action.payload.transmittalItem._id;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case DELETE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.filter((transmittal: any) => {\n          return transmittal._id !== action.payload.transmittal._id;\n        })\n      };\n    case UPDATE_TRANSMITTAL_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittal._id) {\n            return {\n              ...transmittal,\n              ...action.payload.transmittal\n            };\n          } else {\n            return transmittal;\n          }\n        })\n      };\n    case CREATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: [...transmittal.items, action.payload.transmittalItem]\n            };\n          }\n          return transmittal;\n        })\n      };\n    case UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL:\n      return  {\n        ...state,\n        data: state.data.map<ITransmittal>((transmittal: any) => {\n          if (transmittal._id === action.payload.transmittalItem?.transmittal) {\n            return {\n              ...transmittal,\n              items: transmittal.items.map((item: any) => {\n                if (item._id === action.payload.transmittalItem._id) {\n                  return {\n                    ...item,\n                    ...action.payload.transmittalItem\n                  };\n                }\n                return item;\n              })\n            };\n          }\n          return transmittal;\n        })\n      };\n    case LOAD_CARRIERS_TRANSMITTAL:\n      return {\n        ...state,\n        carriers: action.payload.carriers,\n      };\n    case LOAD_DRIVERS_TRANSMITTAL:\n      return {\n        ...state,\n        drivers: action.payload.drivers,\n      };\n    case LOAD_MILESTONE_TYPES_TRANSMITTAL:\n      return {\n        ...state,\n        milestoneTypes: action.payload.milestoneTypes,\n      };\n    case LOAD_VENUES_TRANSMITTAL:\n      return {\n        ...state,\n        venues: action.payload.venues,\n      };\n    case TOOGLE_TAB_TRANSMITTAL:\n      return {\n        ...state,\n        transmittalOpen: state.transmittalOpen.includes(action.payload.transmittalId) ?\n          state.transmittalOpen.filter(id => action.payload.status || id !== action.payload.transmittalId) :\n          [...state.transmittalOpen, action.payload.transmittalId]\n      };\n    case CHANGE_ORDER_TRANSMITTAL:\n      return {\n        ...state,\n        options: {\n          orderBy: action.payload.orderBy,\n          orderType: action.payload.orderType\n        }\n      };\n    case CANCEL_REQUEST_TRANSMITTAL:\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case LOADING_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsLoading: action.payload.requestItemsLoading\n      };\n    case FILTER_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItemsfilters: {\n          ...state.requestItemsfilters,\n          [action.payload.key]: action.payload.value\n        }\n      };\n    case LOAD_REQUEST_ITEMS_TRANSMITTAL:\n      return {\n        ...state,\n        requestItems: action.payload.requestItems,\n        requestItemsPagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          page: action.payload.page,\n          count: action.payload.count\n        }\n      };\n    case TRANSPORT_MILESTONE_LOAD_STATUS:\n      return {\n        ...state,\n        milestones: action.payload.milestones\n      };\n    case LOAD_TRANSMITTAL_RESUME:\n      return {\n        ...state,\n        resume: action.payload.resume\n      };\n    default:\n      return state;\n  }\n}\n","import { IUsersState, UserReduxAction } from '../actions/users.actions';\n\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\n\nconst initialState: IUsersState = {\n  users: [],\n  venues: [],\n  companies: [],\n  searchText: '',\n  permissions: [],\n  forms: [],\n  channels: [],\n  loading: true,\n  tempUser: {\n    _id: '',\n    isAdmin: false,\n    isDriver: false,\n    firstName: '',\n    company: null,\n    lastName: '',\n    email: '',\n    settings: {},\n    userPermissions: [],\n    userForms: [],\n    venuesAccess: [],\n    companiesAccess: []\n  },\n  filters: {\n    venues: []\n  },\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function usersReducer(\n  state = initialState,\n  action: UserReduxAction\n): IUsersState {\n  switch (action.type) {\n    case '/USERS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/USERS/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues.sort((a, b) => a.company.name.localeCompare(b.company.name)),\n        companies: action.payload.companies\n      };\n    case '/USERS/FILTER_VENUES':\n      return {\n        ...state,\n        filters: {\n          ...state.filters,\n          venues: action.payload.venues\n        }\n      };\n    case '/USERS/LOAD_PERMISSIONS':\n      return {\n        ...state,\n        permissions: action.payload.permissions\n      };\n    case '/USERS/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/USERS/LOAD_FORMS':\n      return {\n        ...state,\n        forms: action.payload.forms\n      };\n    case '/USERS/LOAD_CHANNELS':\n      return {\n        ...state,\n        channels: action.payload.channels\n      };\n    case '/USERS/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/USERS/CHANGE_TEMP_USER':\n      return {\n        ...state,\n        tempUser: action.payload.user\n      };\n    case '/USERS/CHANGE_USER':\n      return {\n        ...state,\n        users: state.users.map((user) =>\n          user._id === action.payload.user._id ? action.payload.user : user\n        )\n      };\n    case '/USERS/LOAD_USERS':\n      return {\n        ...state,\n        users: action.payload.users,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case '/USERS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/USERS/DELETE_USER':\n      return {\n        ...state,\n        users: state.users.filter(\n          (user: IUser) => user._id !== action.payload.id\n        ),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/USERS/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    default:\n      return state;\n  }\n}\n","import {IVenue} from '../../../../../src/app/interfaces/venue.interface';\nimport {IVenuesState, VenueReduxAction} from '../actions/venues.actions';\n\nconst initialState: IVenuesState = {\n  venues: [],\n  allVenues: [],\n  companies: [],\n  carriers: [],\n  regions: [],\n  searchText: '',\n  loading: true,\n  source: null,\n  users: [],\n  tempVenue: {\n    _id: '',\n    lat: 0,\n    lng: 0,\n    name: '',\n    code: '',\n    abbreviation: '',\n    type: 'receiver',\n    responsible: [],\n    sendToDays: [],\n    sendTo: [],\n    shippingMaxDays: 5,\n    receiveFrom: [],\n    shippingCarriers: [],\n    receptionCarriers: []\n  },\n  filters: {\n    company: ''\n  },\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function venuesReducer(state = initialState, action: VenueReduxAction): IVenuesState {\n  switch (action.type) {\n    case '/VENUES/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/VENUES/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VENUES/CHANGE_PAGE':\n      return {\n        ...state,\n        pagination: {\n          ...state.pagination,\n          page: action.payload.page\n        }\n      };\n    case '/VENUES/CHANGE_SEARCH':\n      return {\n        ...state,\n        searchText: action.payload.searchText\n      };\n    case '/VENUES/LOAD_COMPANIES':\n      return {\n        ...state,\n        companies: action.payload.companies\n      };\n    case '/VENUES/LOAD_ALL_VENUES':\n      return {\n        ...state,\n        allVenues: action.payload.allVenues.sort((a, b) => a.company.name.localeCompare(b.company.name))\n      };\n    case '/VENUES/LOAD_CARRIERS':\n      return {\n        ...state,\n        carriers: action.payload.carriers\n      };\n    case '/VENUES/LOAD_REGIONS':\n      return {\n        ...state,\n        regions: action.payload.regions\n      };\n    case '/VENUES/CHANGE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.map((venue: IVenue) => {\n          if (venue._id === action.payload.venue._id) {\n            venue.name = action.payload.venue.name;\n            venue.code = action.payload.venue.code;\n            venue.abbreviation = action.payload.venue.abbreviation;\n            venue.company = action.payload.venue.company;\n            venue.type = action.payload.venue.type;\n            venue.sendToDays = action.payload.venue.sendToDays;\n            venue.sendTo = action.payload.venue.sendTo;\n            venue.shippingMaxDays = action.payload.venue.shippingMaxDays;\n            venue.receiveFrom = action.payload.venue.receiveFrom;\n          }\n          return venue;\n        })\n      };\n    case '/VENUES/CHANGE_TEMP_VENUE':\n      return {\n        ...state,\n        tempVenue: action.payload.venue\n      };\n    case '/VENUES/DELETE_VENUE':\n      return {\n        ...state,\n        venues: state.venues.filter((venue: IVenue) => venue._id !== action.payload.id),\n        pagination: {\n          ...state.pagination,\n          count: state.pagination.count - 1\n        }\n      };\n    case '/VENUES/CHANGE_FILTER':\n      return {\n        ...state,\n        filters: {\n          [action.payload.filter]: action.payload.value\n        }\n      }\n    case '/VENUES/LOAD_VENUES':\n      return {\n        ...state,\n        venues: action.payload.venues,\n        pagination: {\n          ...state.pagination,\n          pages: action.payload.pages,\n          count: action.payload.count\n        }\n      };\n    case \"/VENUES/LOAD_USERS\":\n      return {\n        ...state,\n        users: action.payload.users\n      };\n    default:\n      return state;\n  }\n}\n","import {IVersionsState, VersionReduxAction} from \"../actions/versions.actions\";\n\nconst initialState: IVersionsState = {\n  versions: [],\n  loading: true,\n  source: null,\n  pagination: {\n    count: 0,\n    page: 1,\n    pages: 1\n  }\n};\n\nexport function versionsReducer(state = initialState, action: VersionReduxAction): IVersionsState {\n  switch (action.type) {\n    case '/VERSIONS/IS_LOADING':\n      return {\n        ...state,\n        loading: action.payload.loading\n      };\n    case '/ALERTS/CANCEL_REQUEST':\n      return {\n        ...state,\n        source: action.payload.source\n      };\n    case '/VERSIONS/CREATE':\n      return {\n        ...state,\n        versions: [action.payload.version, ...state.versions]\n      };\n    case '/VERSIONS/LOAD_DATA':\n      return {\n        ...state,\n        versions: action.payload.versions\n      };\n    default:\n      return state;\n  }\n}\n","import { routerMiddleware } from 'connected-react-router';\nimport * as createRavenMiddleware from 'raven-for-redux';\nimport * as Raven from 'raven-js';\nimport {applyMiddleware, createStore} from 'redux';\nimport createDebounce from 'redux-debounced';\nimport {composeWithDevTools} from 'redux-devtools-extension';\n// import LogerMiddleware from 'redux-logger';\nimport ThunkMiddleware from 'redux-thunk';\nimport {IWindow} from '../interfaces/window';\nimport createRootReducer from '../reducers/index.reducer';\nimport browserHistort from '../utils/history';\n\ndeclare let window: IWindow;\n\nexport const history = browserHistort;\n\nconst configureStore = () => {\n  let enhancers: any;\n  const middlewares: any[] = [routerMiddleware(history)];\n\n  if (process.env.NODE_ENV === 'development') {\n    middlewares.push(ThunkMiddleware);\n    // middlewares.push(LogerMiddleware);\n    middlewares.push(createDebounce());\n    const composeEnhancers = composeWithDevTools({trace: true, traceLimit: 10 });\n    enhancers = composeEnhancers(applyMiddleware(...middlewares));\n  } else {\n    middlewares.push(ThunkMiddleware);\n    middlewares.push(createDebounce());\n    Raven.config('https://0420e8358aae4b1f91e2d0b234eddebd@sentry.osacontrol.com/17').install();\n    const context = {\n        id: window.user._id,\n        name: `${window.user.firstName} ${window.user.lastName}`,\n        email: window.user.email\n    };\n    Raven.setUserContext(context);\n    Raven.setTagsContext({\n        environment: process.env.NODE_ENV\n    });\n    Raven.setExtraContext({\n        app: 'Andes'\n    });\n    middlewares.push(createRavenMiddleware(Raven));\n    enhancers = applyMiddleware(...middlewares);\n  }\n\n  return createStore(createRootReducer(history), enhancers);\n};\n\nexport default configureStore;\n","import Axios, {\n  AxiosError,\n  AxiosInstance,\n  AxiosPromise,\n  AxiosRequestHeaders,\n  CancelTokenSource,\n  CancelTokenStatic\n} from 'axios';\nimport * as Raven from 'raven-js';\nimport * as swal from 'sweetalert';\nimport { IBaseCarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IBaseCompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IBaseRegion } from '../../../../../src/app/interfaces/region.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport * as queryString from 'query-string';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\nimport { IBaseVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport { ITempUser } from '../actions/users.actions';\nimport { IFilterCar } from '../reducers/inventory.reducer';\nimport { ITransmittalItem } from '../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport { ITransmittal } from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport { IOperationType } from '../../../../../src/request/interfaces/operationType.interface';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport { ITempStudio } from '../actions/statsDashboard.actions';\nimport { getUsersParams } from './axios.types';\nimport { IBaseBorder } from '../../../../../src/app/interfaces/border.interface';\n\nexport default class ApiService {\n  private readonly instance: AxiosInstance;\n  private CancelToken: CancelTokenStatic;\n  private source: CancelTokenSource;\n\n  constructor(private headers: AxiosRequestHeaders = {}) {\n    this.instance = Axios.create({\n      headers: this.headers\n    });\n    this.CancelToken = Axios.CancelToken;\n  }\n\n  public errorHandler(err: AxiosError): void {\n    if (err.response) {\n      if ([500].includes(err.response.status)) {\n        Raven.captureException(JSON.stringify(err.response));\n        swal!(\n          'Ups ha ocurrido un error',\n          err.response.data.message\n            ? err.response.data.message\n            : err.response.data.errmsg,\n          'error'\n        );\n      } else {\n        swal!(\n          'Ups ha ocurrido un error',\n          err.response.data.message\n            ? err.response.data.message\n            : err.response.data.errmsg,\n          'error'\n        );\n      }\n    } else if (err.request) {\n      Raven.captureException(JSON.stringify(err.request));\n    } else {\n      Raven.captureException(JSON.stringify(err));\n    }\n  }\n\n  public getProperties(): AxiosPromise {\n    return this.instance.get(`/api/cars/properties/`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public getUsers({\n    page,\n    search,\n    type,\n    venue,\n    minified = false,\n    limit = 20\n  }: getUsersParams): AxiosPromise {\n    const params = queryString.stringify({\n      page,\n      search,\n      type,\n      venue,\n      minified,\n      limit\n    });\n    return this.instance.get(`/api/admin/users?${params}`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public createUser(user: ITempUser): AxiosPromise {\n    delete user._id;\n    return this.instance.post(`/api/admin/users/`, user);\n  }\n\n  public changePasswordUser(user: string, password: string): AxiosPromise {\n    return this.instance.post(`/api/admin/users/change-password/`, {\n      user,\n      password\n    });\n  }\n\n  public changeStatusUser(userId: any, active: boolean): AxiosPromise {\n    return this.instance.patch(`/api/admin/users/change-status/${userId}/`, {\n      active\n    });\n  }\n\n  public updateUser(user: ITempUser): AxiosPromise {\n    return this.instance.patch(`/api/admin/users/${user._id}/`, user);\n  }\n\n  public deleteUser(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/users/${id}/`);\n  }\n\n  public createIntegration(user: any): AxiosPromise {\n    return this.instance.post(`/api/admin/integrations/`, user);\n  }\n\n  public updateIntegration(user: ITempUser): AxiosPromise {\n    return this.instance.patch(`/api/admin/integrations/${user._id}/`, user);\n  }\n\n  public deleteIntegration(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/integrations/${id}/`);\n  }\n\n  public getParticipantsPerDate(onlyControls: Boolean, companies?: string) {\n    return this.instance.get(\n      `/api/participants-per-date${\n        onlyControls ? `?only_controls=1` : `?only_controls=0`\n      }${companies ? `&companies=${companies}` : ''}`\n    );\n  }\n\n  public getParticipant(id: string) {\n    return this.instance.get(`/api/participant/${id}/`);\n  }\n\n  public getCompanies(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/companies?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }`\n    );\n  }\n\n  public createCompany(company: IBaseCompany): AxiosPromise {\n    const formData = new FormData();\n    formData.append('name', company.name);\n    formData.append('businessName', company.businessName);\n    formData.append('rut', company.rut);\n    formData.append('billing', JSON.stringify(company.billing));\n    formData.append('notifications', JSON.stringify(company.notifications));\n    if (company.image) {\n      formData.append('image', company.image);\n    }\n    if (company.marker) {\n      formData.append('marker', company.marker);\n    }\n    this.instance.defaults.headers.common['Content-Type'] =\n      'multipart/form-data';\n    return this.instance.post(`/api/admin/companies/`, formData);\n  }\n\n  public updateCompany(company: IBaseCompany): AxiosPromise {\n    const formData = new FormData();\n    formData.append('name', company.name);\n    formData.append('businessName', company.businessName);\n    formData.append('rut', company.rut);\n    formData.append('billing', JSON.stringify(company.billing));\n    formData.append('notifications', JSON.stringify(company.notifications));\n    if (company.image) {\n      formData.append('image', company.image);\n    }\n    if (company.marker) {\n      formData.append('marker', company.marker);\n    }\n    this.instance.defaults.headers.common['Content-Type'] =\n      'multipart/form-data';\n    return this.instance.patch(\n      `/api/admin/companies/${company._id}/`,\n      formData\n    );\n  }\n\n  public deleteCompany(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/companies/${id}/`);\n  }\n\n  public createVenue(venue: IBaseVenue): AxiosPromise {\n    return this.instance.post(`/api/admin/venues/`, venue);\n  }\n\n  public updateVenue(venue: IBaseVenue): AxiosPromise {\n    return this.instance.patch(`/api/admin/venues/${venue._id}/`, venue);\n  }\n\n  public deleteVenue(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/venues/${id}/`);\n  }\n\n  public getVenues({\n    page,\n    pageSize,\n    noPopulate,\n    company,\n    filted,\n    search\n  }: {\n    page: number;\n    company?: string;\n    pageSize?: number;\n    noPopulate?: boolean;\n    filted?: boolean;\n    search?: string;\n  }): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/venues?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }${company ? `&company=${company}` : ''}${\n        noPopulate ? `&noPopulate=${noPopulate}` : ''\n      }${filted ? `&filted=${filted}` : ''}${search ? `&search=${search}` : ''}`\n    );\n  }\n  public getCompanyVenues(): AxiosPromise {\n    return this.instance.get(`/api/admin/company-venues/`);\n  }\n\n  public createReason(reason: any): AxiosPromise {\n    return this.instance.post(`/api/v1/reasons/`, reason);\n  }\n\n  public updateReason(reason: IReason): AxiosPromise {\n    return this.instance.patch(`/api/v1/reasons/${reason._id}/`, reason);\n  }\n\n  public deleteReason(reason: IReason): AxiosPromise {\n    return this.instance.delete(`/api/v1/reasons/${reason._id}/`);\n  }\n\n  public getReasons({\n    page,\n    pageSize,\n    orderBy,\n    orderType\n  }: {\n    page: number;\n    orderType?: string;\n    orderBy?: string;\n    pageSize?: number;\n  }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/reasons?page=${page}${pageSize ? `&pageSize=${pageSize}` : ''}${\n        orderBy ? `&orderBy=${orderBy}` : ''\n      }${orderType ? `&orderType=${orderType}` : ''}`\n    );\n  }\n\n  public createSalesChannel(salesChannel: any): AxiosPromise {\n    return this.instance.post(`/api/v1/sales-channel/`, salesChannel);\n  }\n\n  public updateSalesChannel(salesChannel: ISalesChannel): AxiosPromise {\n    return this.instance.patch(\n      `/api/v1/sales-channel/${salesChannel._id}/`,\n      salesChannel\n    );\n  }\n\n  public deleteSalesChannel(salesChannel: ISalesChannel): AxiosPromise {\n    return this.instance.delete(`/api/v1/sales-channel/${salesChannel._id}/`);\n  }\n\n  public getSalesChannel({\n    page,\n    pageSize,\n    orderBy,\n    orderType\n  }: {\n    page: number;\n    orderType?: string;\n    orderBy?: string;\n    pageSize?: number;\n  }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/sales-channel?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }${orderBy ? `&orderBy=${orderBy}` : ''}${\n        orderType ? `&orderType=${orderType}` : ''\n      }`\n    );\n  }\n\n  public createPaymentMethod(paymentMethod: any): AxiosPromise {\n    return this.instance.post(`/api/v1/payment-method/`, paymentMethod);\n  }\n\n  public updatePaymentMethod(paymentMethod: IPaymentMethod): AxiosPromise {\n    return this.instance.patch(\n      `/api/v1/payment-method/${paymentMethod._id}/`,\n      paymentMethod\n    );\n  }\n\n  public deletePaymentMethod(paymentMethod: IPaymentMethod): AxiosPromise {\n    return this.instance.delete(`/api/v1/payment-method/${paymentMethod._id}/`);\n  }\n\n  public getPaymentMethods({\n    page,\n    pageSize,\n    orderBy,\n    orderType\n  }: {\n    page: number;\n    orderType?: string;\n    orderBy?: string;\n    pageSize?: number;\n  }): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/payment-method?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }${orderBy ? `&orderBy=${orderBy}` : ''}${\n        orderType ? `&orderType=${orderType}` : ''\n      }`\n    );\n  }\n\n  public createCarrier(carrier: IBaseCarrier): AxiosPromise {\n    return this.instance.post(`/api/admin/carriers/`, carrier);\n  }\n\n  public updateCarrier(carrier: IBaseCarrier): AxiosPromise {\n    return this.instance.patch(`/api/admin/carriers/${carrier._id}/`, carrier);\n  }\n\n  public deleteCarrier(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/carriers/${id}/`);\n  }\n\n  public getCarriers(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/carriers?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }`\n    );\n  }\n\n  public getDrivers(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/v1/users/drivers?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }`\n    );\n  }\n\n  public createRegion(region: IBaseRegion): AxiosPromise {\n    return this.instance.post(`/api/admin/regions/`, region);\n  }\n\n  public updateRegion(region: IBaseRegion): AxiosPromise {\n    return this.instance.patch(`/api/admin/regions/${region._id}/`, region);\n  }\n\n  public deleteRegion(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/regions/${id}/`);\n  }\n\n  public getRegions(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/regions?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }`\n    );\n  }\n\n  public getPermissions(page: number, pageSize?: number): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/permissions?page=${page}${\n        pageSize ? `&pageSize=${pageSize}` : ''\n      }`\n    );\n  }\n\n  public getCars(page: number, search?: string): AxiosPromise {\n    return this.instance.get(\n      `/api/cars?page=${page}${search ? `&search=${search}` : ''}`,\n      {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getRevisions({\n    onlyControls,\n    deliveries,\n    page,\n    search,\n    delivery,\n    from,\n    to,\n    forms\n  }: {\n    onlyControls: boolean;\n    deliveries: boolean;\n    page: number;\n    delivery?: string;\n    search?: string;\n    from?: Date;\n    to?: Date;\n    forms?: String[];\n  }): AxiosPromise {\n    let query = `?page=${page}&only_controls=${\n      onlyControls ? '1' : '0'\n    }&deliveries=${deliveries ? '1' : '0'}`;\n    if (search) query += `&search=${search}`;\n    if (delivery) query += `&delivery=${delivery}`;\n\n    if (from) query += `&from=${from.toISOString()}`;\n\n    if (to) query += `&to=${to.toISOString()}`;\n\n    if (forms) query += `&forms=${forms.join(',')}`;\n\n    return this.instance.get(`/api/revisions${query}`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public getAdminCars(page?: number, search?: string): AxiosPromise {\n    return this.instance.get(\n      `/api/admin/cars?page=${page}${search ? `&search=${search}` : ''}`,\n      {\n        cancelToken: this.source.token\n      }\n    );\n  }\n\n  public getCar(id: string): AxiosPromise {\n    return this.instance.get(`/api/cars/${id}/`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public sendImportCars(data: any): AxiosPromise {\n    return this.instance.post(`/api/admin/import-cars/`, data, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public getInventories(page: number): AxiosPromise {\n    return this.instance.get(`/api/inventory?page=${page}`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public getInventory(id: string): AxiosPromise {\n    return this.instance.get(`/api/inventory/${id}/`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public addComment(id: string, carId: string, comment: string): AxiosPromise {\n    return this.instance.post(`/api/inventory/${id}/comment/`, {\n      _id: carId,\n      comment\n    });\n  }\n\n  // public createInventory({carsByVenue: any, name: string, notification: boolean, file: File, backup: File | null}): AxiosPromise {\n  public createInventory({\n    carsByVenue,\n    name,\n    notification,\n    file,\n    backupFile,\n    manualPhoto,\n    reportPhoto\n  }: {\n    carsByVenue: any;\n    name: string;\n    notification: boolean;\n    file: File | null;\n    backupFile: File | null;\n    manualPhoto: number;\n    reportPhoto: number;\n  }): AxiosPromise {\n    const formData = new FormData();\n    formData.append('carsByVenue', JSON.stringify(carsByVenue));\n    formData.append('name', name);\n    formData.append('notification', notification.toString());\n    formData.append('file', file!);\n    formData.append('manualPhoto', manualPhoto.toString());\n    formData.append('reportPhoto', reportPhoto.toString());\n    if (backupFile) {\n      formData.append('backup', backupFile);\n    }\n    this.instance.defaults.headers.common['Content-Type'] =\n      'multipart/form-data';\n    return this.instance.post(`/api/inventory/`, formData, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public importPlanning(data: any): AxiosPromise {\n    return this.instance.post(`/api/admin/planning/`, data, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public updateMassiveRequest(data: any): AxiosPromise {\n    return this.instance.post(`/api/v1/requests/update-massive/`, data, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public importRequests(data: any): AxiosPromise {\n    return this.instance.post(`/api/v1/requests/import/`, data, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public finishInventory(id: string): AxiosPromise {\n    return this.instance.post(`/api/inventory/${id}/finish/`, {});\n  }\n\n  public deleteInventory(id: string): AxiosPromise {\n    return this.instance.delete(`/api/inventory/${id}/`, {});\n  }\n\n  public getAlerts(): AxiosPromise {\n    return this.instance.get(`/api/admin/alerts/`, {\n      cancelToken: this.source.token\n    });\n  }\n\n  public createAlert(alert: any): AxiosPromise {\n    return this.instance.post(`/api/admin/alerts/`, alert);\n  }\n\n  public deleteAlert(id: string): AxiosPromise {\n    return this.instance.delete(`/api/admin/alerts/${id}/`);\n  }\n  public preMassAllocation(data: any): AxiosPromise {\n    return this.instance.post(`/api/v1/requests/pre-mass-allocation/`, data);\n  }\n\n  public checkItemMassAllocation(data: any): AxiosPromise {\n    return this.instance.post(\n      `/api/v1/requests/check-item-mass-allocation/`,\n      data\n    );\n  }\n\n  public processItemMassAllocation(data: any): 