 './components/Request/RequestCreateIntegration';\nimport ColorListView from './components/Colors/ColorsListView';\nimport {\n  VDistributionDashboardStatsView, VInventoryDashboardStatsView, VPlanificationDashboardStatsView,\n  VUnitControlDashboardStatsView\n} from \"./components/Stats/DashboardStatsView\";\nimport DashboardStatsListView from \"./components/Stats/DashboardStatsListView\";\nimport DashboardView from \"./components/Transmittal/StatsDashboard/DashboardView\";\nimport BordersListView from \"./components/Borders/BordersListView\";\nimport BillingSettingsListView from './components/Billing/BillingSettings/BillingSettingsListView';\nimport BillingCoporateListView from './components/Billing/BillingSettings/BillingCorporateDetailView';\nimport DeliveriesView from './components/Deliveries/DeliveriesView';\nimport * as ReactGA from 'react-ga';\n\n\ndeclare let window: IWindow;\n\nconst store = configureStore();\n\nconst NoMatch = ({ location }: RouteComponentProps<{}>) => (\n  <div>\n    <h3>No match for <code>{location.pathname}</code></h3>\n  </div>\n);\nconst App = () => (\n  <Provider store={store}>\n    <ConnectedRouter history={history}>\n      <Switch>\n        <Route exact path=\"/settings/integrations/\" component={IntegrationListView}/>\n        <Route exact path='/' component={DashboardGeneralView} />\n        <Route exact path='/cars/' component={DashboardVinView} />\n        <Route exact path='/deliveries/' component={DeliveriesView} />\n        <Route exact path='/planning/import/' component={PlanningImportView} />\n        <Route exact path='/planning/studio/' component={VPlanificationDashboardStatsView} />\n        <Route exact path='/planning/' component={PlanningListView} />\n        <Route exact path='/dashboard/damages/' component={DashboardDamagesView} />\n        <Route exact path='/dashboard/timing/' component={DashboardTimingView} />\n        <Route exact path='/dashboard/derco/' component={DashboardDercoView} />\n        <Route exact path='/dashboard/studio/' component={VUnitControlDashboardStatsView}  />\n        <Route exact path='/dashboard/custom-dashboard/' component={CustomDashboardComponent} />\n        <Route exact path='/forms/settings/forms/' component={FormsSettingsListView} />\n        <Route exact path='/stock/' component={StockView} />\n        <Route exact path='/stock/import/' component={StockImportView} />\n        <Route exact path='/cars/:id/' component={DashboardVinDetail} />\n        <Route exact path='/deliveries/cars/:id/' component={DashboardVinDetail} />\n        <Route exact path='/inventory/' component={InventoryListView} />\n        <Route exact path='/inventory/studio/' component={VInventoryDashboardStatsView} />\n        <Route exact path='/inventory/dashboard/' component={InventoryDashboardView} />\n        <Route exact path='/inventory/create/' component={InventoryCreateView} />\n        <Route exact path='/inventory/:id/' component={InventoryDetailView} />\n        <Route exact path='/inventory/:id/:tab/' component={InventoryDetailView} />\n        <Route exact path='/settings/users/' component={UsersListView} />\n        <Route exact path='/settings/cars/' component={CarsListView} />\n        <Route exact path='/settings/cars/import/' component={ImportCarsView} />\n        <Route exact path='/settings/cars/:id/' component={CarDetailView} />\n        <Route exact path='/settings/labels/' component={LabelsListView} />\n        <Route exact path='/settings/venues/' component={VenuesListView} />\n        <Route exact path='/settings/regions/' component={RegionsListView} />\n        <Route exact path='/settings/colors/' component={ColorListView} />\n        <Route exact path='/settings/carriers/' component={CarriersListView} />\n        <Route exact path='/settings/companies/' component={CompaniesListView} />\n        <Route exact path='/settings/alerts/' component={AlertsViews} />\n        <Route exact path='/settings/versions/' component={VersionListView} />\n        <Route exact path='/settings/billing-settings/' component={BillingSettingsListView} />\n        <Route exact path='/settings/billing/corporate/' component={BillingCoporateListView} />\n        <Route exact path='/settings/billing/' component={BillingListView} />\n        <Route exact path='/settings/billing/' component={BillingListView} />\n        <Route exact path='/settings/stats/' component={DashboardStatsListView} />\n        <Route exact path='/settings/border/' component={BordersListView} />\n        <Route exact path='/requests/create/' component={RequestCreateView} />\n        <Route exact path='/transmittals/' component={TransmittalListView} />\n        <Route exact path='/transmittals/create/' component={TransmittalCreateView} />\n        <Route exact path='/transmittals/dashboard/' component={DashboardView} />\n        <Route exact path='/requests/' component={RequestListView} />\n        <Route exact path='/requests/settings/reasons/' component={RequestReasonListView} />\n        <Route exact path='/requests/settings/channels/' component={RequestChannelListView} />\n        <Route exact path='/requests/settings/payment-methods/' component={PaymentMethodListView} />\n        <Route exact path='/requests/settings/status/' component={RequestStatusListView} />\n        <Route exact path='/requests/settings/operations-type/' component={OperationTypeListView} />\n        <Route exact path='/transmittals/settings/milestone/' component={MilestoneListView} />\n        <Route exact path='/transmittals/settings/milestone-type/' component={MilestoneTypeListView} />\n        <Route exact path='/requests/import/' component={RequestImportView} />\n        <Route exact path='/requests/mass-allocation/' component={RequestImportVINSView} />\n        <Route exact path='/requests/update/' component={RequestUpdaterView} />\n        <Route exact path='/requests/studio/' component={VDistributionDashboardStatsView} />\n        <Route exact path='/requests/vehicles/external/create/' component={RequestCreateIntegration} />\n        <Route exact path='/requests/vehicles/create' component={RequestCreateView} />\n        <Route exact path='/requests/vehicles/:id/' component={RequestDetailView} />\n        <Route exact path='/requests/vehicles/' component={RequestVehicleListView} />\n        <Route exact path='/requests/:id/' component={RequestDetailView} />\n        <Route component={NoMatch} />\n      </Switch>\n    </ConnectedRouter>\n  </Provider>\n);\nconst $body = $('body');\n// clear state of the modeal on hidden\n$body.on('hidden.bs.modal', '#andesModal', () => {\n  store.dispatch({\n    type: '/MODAL/CLEAR'\n  });\n});\n\n$(() => {\n  // add ekko-lightbox\n  const script = document.createElement('script');\n  const link = document.createElement('link');\n  link.rel = 'stylesheet';\n  link.href = isIntenertExplorer() ? '/static/js/vendor/lightbox/ekko-lightbox.css' : '/static/js/vendor/lightbox/ekko-lightbox.last.css';\n  const js = document.getElementsByClassName('js')[0];\n  script.src = isIntenertExplorer() ? '/static/js/vendor/lightbox/ekko-lightbox.min.js' : '/static/js/vendor/lightbox/ekko-lightbox.last.min.js';\n  js.appendChild(script);\n  js.appendChild(link);\n\n  moment.locale('es');\n  ReactGA.initialize('UA-101792436-1', {\n    debug: false,\n    titleCase: false,\n    gaOptions: {\n      userId: window.user._id,\n      clientId: window.user.email,\n      name: 'tracker'\n    }\n  });\n  ReactDOM.render(\n    <App />,\n    document.querySelector('#app')\n  );\n  ($('.sidebar-menu') as any).tree();\n  $body.on('click', '.treeview-menu li', () => {\n    $body.removeClass('sidebar-open');\n  });\n  // ekk-lightbox\n  $(document).on('click', '[data-toggle=\"lightbox\"]', function(event) {\n    event.preventDefault();\n    ($(this) as any).ekkoLightbox();\n  });\n  // fix ekk-lightbox\n  $(document).on('hidden.bs.modal', () => {\n    if ($('.modal:visible').length) {\n      $body.addClass('modal-open');\n    }\n  });\n\n  $(document).on('click.bs.dropdown.data-api', '.dropdown.keep-inside-clicks-open', function(event) {\n    event.stopPropagation();\n  });\n  // prevenet show modal addons when is open and user change page\n  window.addEventListener('popstate', function() {\n    $('.modal-backdrop').remove();\n    $body.removeClass('modal-open');\n    // ($('#andesModal') as any).modal('hide');\n  });\n\n\n  ($ as any).AdminLTESidebarTweak = {};\n\n  ($ as any).AdminLTESidebarTweak.options = {\n    EnableRemember: true,\n    NoTransitionAfterReload: true\n    //Removes the transition after page reload.\n  };\n\n  $(function() {\n    'use strict';\n    $body.on('collapsed.pushMenu', function() {\n      if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n        localStorage.setItem('toggleState', 'closed');\n      }\n    });\n\n    $body.on('expanded.pushMenu', function() {\n      if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n        localStorage.setItem('toggleState', 'opened');\n      }\n    });\n    // $('.sidebar-menu a').on('click', function() {\n    //   const toggleState = localStorage.getItem('toggleState');\n    //   console.log(toggleState);\n    //   if(toggleState === 'closed'){\n    //     localStorage.setItem('toggleState', 'closed');\n    //     $body.addClass('sidebar-collapse');\n    //   }\n    // });\n\n    if (($ as any).AdminLTESidebarTweak.options.EnableRemember) {\n      const toggleState = localStorage.getItem('toggleState');\n      if (toggleState === 'closed') {\n        if (($ as any).AdminLTESidebarTweak.options.NoTransitionAfterReload) {\n          $body.addClass('sidebar-collapse hold-transition').delay(100).queue(function() {\n            $(this).removeClass('hold-transition');\n          });\n        } else {\n          $body.addClass('sidebar-collapse');\n        }\n      }\n    }\n  });\n});\n\nif (process.env.NODE_ENV !== 'development') {\n  // disable react debug\n  if (window.hasOwnProperty('__REACT_DEVTOOLS_GLOBAL_HOOK__')) {\n    window.__REACT_DEVTOOLS_GLOBAL_HOOK__._renderers = {};\n  }\n}\n","import {AxiosError, AxiosResponse, CancelTokenSource} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../src/app/interfaces/alert.interface';\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IAlertsState {\n  alerts: Array<IAlert>;\n  users: Array<IUser>;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/ALERTS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/ALERTS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/ALERTS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/ALERTS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IDeleteAlert {\n  type: '/ALERTS/DELETE';\n  payload: {\n    id: string;\n  };\n}\n\nexport function deleteAlert(id: string): IDeleteAlert {\n  return {\n    type: '/ALERTS/DELETE',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteAlertAction(id: string) {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteAlert(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#alert-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(deleteAlert(data.id));\n        }, 500);\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ICreateAlert {\n  type: '/ALERTS/CREATE';\n  payload: {\n    alert: IAlert;\n  };\n}\n\nexport function createAlert(alert: IAlert): ICreateAlert {\n  return {\n    type: '/ALERTS/CREATE',\n    payload: {\n      alert\n    }\n  };\n}\n\nexport function createAlertAction(alert: any) {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.createAlert(alert)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(createAlert(data.alert));\n        dispatch(isLoadingAction(false));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n        dispatch(isLoadingAction(false));\n      });\n  };\n}\n\ninterface ILoadAlerts {\n  type: '/ALERTS/LOAD_DATA';\n  payload: {\n    alerts: IAlert[];\n    users: IUser[];\n  };\n}\n\nexport function loadAlertsAction(alerts: IAlert[], users: IUser[]): ILoadAlerts {\n  return {\n    type: '/ALERTS/LOAD_DATA',\n    payload: {\n      alerts,\n      users\n    }\n  };\n}\n\nexport function getAlertsAction() {\n  return (dispatch: Dispatch<AlertReduxAction>) => {\n    const api: ApiService = new ApiService();\n    // dispatch(isLoadingAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getAlerts()\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadAlertsAction(data.alerts, data.users));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type AlertReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadAlerts |\n  IDeleteAlert |\n  ICreateAlert;\n","import {IInvoice} from '../../../../../src/billing/interfaces/invoice.interface';\nimport {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from \"axios\";\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\n\nexport interface IBillingState {\n  invoices: IInvoice[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/BILLING/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/BILLING/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/BILLING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/BILLING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/BILLING/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/BILLING/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadBilling {\n  type: '/BILLING/LOAD_BILLING';\n  payload: {\n    invoices: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadBillingAction(invoices: any, count: number, pages: number): ILoadBilling {\n  return {\n    type: '/BILLING/LOAD_BILLING',\n    payload: {\n      invoices,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getBillingAction(nextPage: number) {\n  return (dispatch: Dispatch<BillingReduxAction>, getState: () => {labels: IBillingState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getBilling(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadBillingAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function getInvoiceAction(nextPage: number) {\n  return (dispatch: Dispatch<BillingReduxAction>, getState: () => {labels: IBillingState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getBilling(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadBillingAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type BillingReduxAction = IIsLoading\n  | ICancelRequest\n  | ILoadBilling\n  | IChangePage;\n","import ApiService from '../utils/axios';\nimport { ThunkDispatch } from 'redux-thunk';\nimport { autofill, FormAction, submit } from 'redux-form';\nimport {\n  CANCEL_BILLING_SETINGS,\n  IBillingSettingsActionTypes,\n  IBillingSettingsState,\n  LOAD_ALL_COMPANIES_BILLING_SETINGS,\n  LOAD_ALL_MODULES_BILLING_SETINGS,\n  LOAD_BILLING_SETINGS, LOAD_INVOICE,\n  LOADING_BILLING_SETINGS\n} from './billingSettings.types';\nimport Axios, { AxiosError, CancelTokenSource } from 'axios';\nimport { ICompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IModule } from '../../../../../src/billing/interfaces/module.interface';\nimport { ITeamBilling } from '../../../../../src/billing/interfaces/teamBiling.interfaces';\nimport { IInvoiceTeamBilling } from '../../../../../src/billing/interfaces/invoiceTeamBilling.interface';\nimport { Moment } from 'moment';\n\nexport default class BillingSettingsActions {\n\n  readonly form = 'billingSettingsForm';\n  private api: ApiService;\n\n  constructor(\n    private dispatch: ThunkDispatch<{ transmittal: IBillingSettingsState }, {}, IBillingSettingsActionTypes | FormAction>\n  ) {\n    this.api = new ApiService();\n  }\n\n  public loadingAction(loading: boolean): void {\n    this.dispatch({\n      type: LOADING_BILLING_SETINGS,\n      payload: {\n        loading\n      }\n    });\n  }\n\n  public loadInvoiceAction(invoice: IInvoiceTeamBilling, oldest: Moment, last: Moment): void {\n    this.dispatch({\n      type: LOAD_INVOICE,\n      payload: {\n        invoice,\n        oldest,\n        last\n      }\n    });\n  }\n\n  public loadBillingSettingsAction(billingSettings: ITeamBilling): void {\n    this.dispatch({\n      type: LOAD_BILLING_SETINGS,\n      payload: {\n        billingSettings\n      }\n    });\n  }\n\n  public loadAllCompanies(companies: ICompany[]): void {\n    this.dispatch({\n      type: LOAD_ALL_COMPANIES_BILLING_SETINGS,\n      payload: {\n        companies\n      }\n    });\n  }\n\n  public loadAllModules(modules: IModule[]): void {\n    this.dispatch({\n      type: LOAD_ALL_MODULES_BILLING_SETINGS,\n      payload: {\n        modules\n      }\n    });\n  }\n\n  public cancelRequestAction(source: CancelTokenSource): void {\n    this.dispatch({\n      type: CANCEL_BILLING_SETINGS,\n      payload: {\n        source\n      }\n    });\n  }\n\n  public submit(form: string) {\n    this.dispatch(submit(form));\n  }\n\n  public autofill(field: string, value: any) {\n    this.dispatch(\n      autofill(this.form, field, value),\n    );\n  }\n\n  public getInvoice({ period }: { period?: string }): void {\n    this.dispatch((dispatch) => {\n      const actions = new BillingSettingsActions(dispatch);\n      actions.loadingAction(true);\n      Axios\n        .all([\n          this.api.getInvoiceCorporate({ period })\n        ])\n        .then(Axios.spread((\n          invoice) => {\n          const {results, oldestInvoice, lastInvoice} = invoice.data;\n          actions.loadInvoiceAction(results, oldestInvoice, lastInvoice);\n          actions.loadingAction(false);\n        }))\n        .catch((err: AxiosError): void => {\n          actions.loadingAction(true);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public getTeamSettings(): void {\n    this.dispatch((dispatch) => {\n      const actions = new BillingSettingsActions(dispatch);\n      actions.loadingAction(true);\n      Axios\n        .all([\n          this.api.getAllCompanies(),\n          this.api.getAllModules(),\n          this.api.getBillingByCorporate(),\n          // this.api.getDrivers(1, 200),\n          // this.api.getMilestoneTypes({ page: 1, pageSize: 200 })\n        ])\n        .then(Axios.spread((\n          companies,\n          modules,\n          billingSettings) => {\n          actions.loadAllCompanies(companies.data.results);\n          actions.loadAllModules(modules.data.results);\n          actions.loadBillingSettingsAction(billingSettings.data.results);\n          // actions.loadDrivers(drivers.data.results);\n          // actions.loadMilestoneTypes(milestones.data.results);\n          actions.loadingAction(false);\n        }))\n        .catch((err: AxiosError): void => {\n          actions.loadingAction(true);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n}\n","import { CancelTokenSource } from 'axios';\nimport { ITeamBilling } from '../../../../../src/billing/interfaces/teamBiling.interfaces';\nimport { IModule } from '../../../../../src/billing/interfaces/module.interface';\nimport { ICompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IInvoiceTeamBilling } from '../../../../../src/billing/interfaces/invoiceTeamBilling.interface';\nimport { Moment } from 'moment';\n\nexport const LOADING_BILLING_SETINGS = '@billingSettings/IS_LOADING';\nexport const LOAD_BILLING_SETINGS = '@billingSettings/LOAD_BILLING_SETINGS';\nexport const LOAD_INVOICE = '@billingSettings/LOAD_INVOICE';\nexport const LOAD_ALL_COMPANIES_BILLING_SETINGS = '@billingSettings/LOAD_ALL_COMPANIES';\nexport const LOAD_ALL_MODULES_BILLING_SETINGS = '@billingSettings/LOAD_ALL_MODULES';\nexport const CANCEL_BILLING_SETINGS = '@billingSettings/CANCEL_REQUEST';\n\n\ninterface IBillingSettingsLoadingAction {\n  type: typeof LOADING_BILLING_SETINGS;\n  payload: {\n    loading: boolean;\n  };\n}\n\ninterface IBillingSettingsLoadAllCompaniesAction {\n  type: typeof LOAD_ALL_COMPANIES_BILLING_SETINGS;\n  payload: {\n    companies: ICompany[];\n  };\n}\n\ninterface IBillingSettingsLoadAllModulesAction {\n  type: typeof LOAD_ALL_MODULES_BILLING_SETINGS;\n  payload: {\n    modules: IModule[];\n  };\n}\n\ninterface IBillingSettingsCancerlRequestAction {\n  type: typeof CANCEL_BILLING_SETINGS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\ninterface IBillingSettingsLoadAction {\n  type: typeof LOAD_BILLING_SETINGS;\n  payload: {\n    billingSettings: ITeamBilling;\n    // count: number;\n    // pages: number;\n    // page: number;\n  };\n}\n\ninterface IInvoiceLoadAction {\n  type: typeof LOAD_INVOICE;\n  payload: {\n    invoice: IInvoiceTeamBilling;\n    oldest: Moment;\n    last: Moment;\n  };\n}\n\nexport interface IBillingSettingsState {\n  loading: boolean;\n  source: CancelTokenSource | null;\n  billingSettings: ITeamBilling | null;\n  invoice: IInvoiceTeamBilling | null;\n  oldest: Moment | null;\n  last: Moment | null;\n  companies: ICompany[];\n  modules: IModule[];\n}\n\nexport type IBillingSettingsActionTypes =\n  IBillingSettingsLoadingAction |\n  IInvoiceLoadAction |\n  IBillingSettingsLoadAllCompaniesAction |\n  IBillingSettingsLoadAllModulesAction |\n  IBillingSettingsCancerlRequestAction |\n  IBillingSettingsLoadAction;\n\n","import {IBaseBorder, IBorder} from \"../../../../../src/app/interfaces/border.interface\";\nimport {ICompany} from \"../../../../../src/app/interfaces/company.interface\";\nimport {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from \"axios\";\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\nimport {showModal, statusFooterButttonsModal} from \"../utils/common\";\nimport * as swal from 'sweetalert';\nimport {processDeleteVenueAction} from \"./venues.actions\";\n\nexport interface IBorderState {\n  borders: IBorder[];\n  tempBorder: IBaseBorder;\n  companies: ICompany[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  searchText: string;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/BORDERS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  }\n}\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/BORDERS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/BORDERS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/BORDERS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/BORDERS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/BORDERS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeSearchBorder {\n  type: '/BORDERS/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchAction(searchText: string): IChangeSearchBorder {\n  return {\n    type: '/BORDERS/CHANGE_SEARCH',\n    payload: {\n      searchText\n    }\n  };\n}\n\ninterface IChangeTempBorder {\n  type: '/BORDERS/CHANGE_TEMP_BORDER';\n  payload: {\n    border: IBaseBorder;\n  };\n}\n\nexport function changeTempBorderAction(border: IBaseBorder): IChangeTempBorder {\n  return {\n    type: '/BORDERS/CHANGE_TEMP_BORDER',\n    payload: {\n      border\n    }\n  };\n}\n\ninterface ILoadBorders {\n  type: '/BORDERS/LOAD_BORDERS';\n  payload: {\n    borders: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadBorderAction(borders: any, count: number, pages: number): ILoadBorders {\n  return {\n    type: '/BORDERS/LOAD_BORDERS',\n    payload: {\n      borders,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadCompaniesBorder {\n  type: '/BORDERS/LOAD_COMPANIES';\n  payload: {\n    companies: ICompany[];\n  };\n}\n\nexport function loadCompaniesBorderAction(companies: ICompany[]): ILoadCompaniesBorder {\n  return {\n    type: '/BORDERS/LOAD_COMPANIES',\n    payload: {\n      companies\n    }\n  };\n}\n\n\n\nexport function getBorderCompanyAction() {\n  return (dispatch: Dispatch<BorderReduxAction>, getState: () => { border: IBorderState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getCompanies(1, 200)\n      .then((companies: AxiosResponse) => {\n        dispatch(loadCompaniesBorderAction(companies.data.results));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getBorderAction(nextPage: number) {\n  return (dispatch: Dispatch<BorderReduxAction>, getState: () => { border: IBorderState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    const { searchText } = state.border;\n    if (nextPage && nextPage !== state.border.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.border.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getBorders(page, 20, searchText)\n      .then((response: AxiosResponse) => {\n        dispatch(loadBorderAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n  };\n}\n\n\nexport function createBorderAction() {\n  return (dispatch: Dispatch<BorderReduxAction>, getState: () => { border: IBorderState }) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const { tempBorder } = state.border;\n    const api: ApiService = new ApiService();\n    api.createBorder(tempBorder)\n      .then((response: AxiosResponse) => {\n        dispatch(getBorderAction(state.border.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateBorderAction() {\n  return (dispatch: Dispatch<BorderReduxAction>, getState: () => { border: IBorderState }) => {\n    const state = getState();\n    const { tempBorder } = state.border;\n    const $border = $(`#border-${tempBorder._id}`);\n    const api: ApiService = new ApiService();\n    api.updateBorder(tempBorder)\n      .then((response: AxiosResponse) => {\n        dispatch(getBorderAction(state.border.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        $border.addClass('editing-item');\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $border.removeClass('editing-item');\n        }, 1000);\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $border.removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteBorder {\n  type: '/BORDERS/DELETE_BORDER';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteBorderAction(id: string): IDeleteBorder {\n  return {\n    type: '/BORDERS/DELETE_BORDER',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteBorderAction(id: string) {\n  return (dispatch: Dispatch<BorderReduxAction>, getState: () => { border: IBorderState }) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    api.deleteBorder(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#border-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteBorderAction(id));\n          dispatch(isLoadingAction(false));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type BorderReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadBorders |\n  IChangeSearchBorder |\n  IChangeTempBorder |\n  IDeleteBorder |\n  ILoadCompaniesBorder;\n\n","import {\n  AxiosError,\n  AxiosResponse,\n  CancelTokenSource,\n  default as Axios\n} from 'axios';\nimport {\n  Dispatch\n} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IBaseCarrier,\n  ICarrier\n} from '../../../../../src/app/interfaces/carrier.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ICarriersState {\n  carriers: ICarrier[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  tempCarrier: IBaseCarrier;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/CARRIERS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/CARRIERS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/CARRIERS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/CARRIERS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/CARRIERS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/CARRIERS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempCarrier {\n  type: '/CARRIERS/CHANGE_TEMP_CARRIER';\n  payload: {\n    carrier: IBaseCarrier;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempCarrierAction(carrier: IBaseCarrier, delay?: boolean): IChangeTempCarrier {\n  return {\n    type: '/CARRIERS/CHANGE_TEMP_CARRIER',\n    payload: {\n      carrier\n    },\n    meta: {\n      debounce: {\n        time: delay ? 300 : 0\n      }\n    }\n  };\n}\n\ninterface ILoadCarriers {\n  type: '/CARRIERS/LOAD_CARRIERS';\n  payload: {\n    carriers: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarriersAction(carriers: any, count: number, pages: number): ILoadCarriers {\n  return {\n    type: '/CARRIERS/LOAD_CARRIERS',\n    payload: {\n      carriers,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getCarriersAction(nextPage: number) {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => { carriers: ICarriersState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.carriers.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.carriers.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getCarriers(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarriersAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createCarrierAction() {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempCarrier} = state.carriers;\n    const api: ApiService = new ApiService();\n    api.createCarrier(tempCarrier)\n      .then((response: AxiosResponse) => {\n        dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateCarrierAction() {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    const state = getState();\n    const {tempCarrier} = state.carriers;\n    const $carrier = $(`#carrier-${tempCarrier._id}`);\n    const api: ApiService = new ApiService();\n    api.updateCarrier(tempCarrier)\n      .then((response: AxiosResponse) => {\n        $carrier.addClass('editing-item');\n        dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $carrier.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteCarrierAction(id: string) {\n  return (dispatch: Dispatch<CarrierReduxAction>, getState: () => {carriers: ICarriersState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteCarrier(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#carrier-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getCarriersAction(state.carriers.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type CarrierReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangeTempCarrier |\n  ILoadCarriers |\n  IChangePage;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport {ICar} from '../../../../../src/app/interfaces/car.interface';\nimport ApiService from '../utils/axios';\n\nexport interface ICarsState {\n  cars: ICar[];\n  car: ICar | null;\n  carEvents: any;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/CARS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/CARS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/CARS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/CARS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/CARS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/CARS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadCars {\n  type: '/CARS/LOAD_CARS';\n  payload: {\n    cars: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarsAction(cars: any, count: number, pages: number): ILoadCars {\n  return {\n    type: '/CARS/LOAD_CARS',\n    payload: {\n      cars,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadCar {\n  type: '/CARS/LOAD_CAR';\n  payload: {\n    car: ICar;\n  };\n}\n\nexport function loadCarAction(car: ICar): ILoadCar {\n  return {\n    type: '/CARS/LOAD_CAR',\n    payload: {\n      car\n    }\n  };\n}\n\nexport function getCarAction(id: string) {\n  return (dispatch: Dispatch<CarReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getCar(id)\n      .then((response: AxiosResponse) => {\n        document.title = `OSA Andes | Detalle VIN ${response.data.data.vin}`;\n        dispatch(loadCarAction(response.data.data));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function getCarsAction(nextPage: number, search?: string) {\n  return (dispatch: Dispatch<CarReduxAction>, getState: () => {cars: ICarsState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.cars.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.cars.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getAdminCars(page, search)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type CarReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadCars |\n  ILoadCar;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IColor } from '../../../../../src/app/interfaces/color.interface';\nimport ApiService from '../utils/axios';\nimport {\n  COLOR_IS_LOADING,\n  COLOR_CHANGE_ORDER,\n  COLOR_CANCEL,\n  COLOR_LOAD,\n  COLOR_CREATE,\n  COLOR_UDPATE,\n  COLOR_DELETE,\n  ICreateColor,\n  ICancelColor,\n  IIsLoadingColor,\n  ILoadColor,\n  IUpdateColor,\n  IDeleteColor,\n  IChangeOrderColor,\n  IColorState,\n  ColorReduxActions\n} from './color.types';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\nimport * as swal from 'sweetalert';\n\nexport function cancelColorAction(source: CancelTokenSource): ICancelColor {\n  return {\n    type: COLOR_CANCEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingColorAction(loading: boolean): IIsLoadingColor {\n  return {\n    type: COLOR_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadColorAction(colors: IColor[], count: number, pages: number, page: number): ILoadColor {\n  return {\n    type: COLOR_LOAD,\n    payload: {\n      colors,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createColorAction(color: IColor): ICreateColor {\n  return {\n    type: COLOR_CREATE,\n    payload: {\n      color\n    }\n  };\n}\n\nexport function updateColorAction(color: IColor): IUpdateColor {\n  return {\n    type: COLOR_UDPATE,\n    payload: {\n      color\n    }\n  };\n}\n\n\nexport function deleteColorAction(color: IColor): IDeleteColor {\n  return {\n    type: COLOR_DELETE,\n    payload: {\n      color\n    }\n  };\n}\n\nexport function changeOrderColorAction(orderBy: string, orderType: string): IChangeOrderColor {\n  return {\n    type: COLOR_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getColorsThunkAction(colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<ColorReduxActions>, getState: () => { color: IColorState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingColorAction(!hideLoading));\n    const page = nextPage ? nextPage : state.color.pagination.page;\n    dispatch(changeOrderColorAction(orderBy, orderType));\n    dispatch(cancelColorAction(api.getSource()));\n    Axios\n      .all([\n        api.getColors({ page })\n      ])\n      .then(Axios.spread((colors) => {\n        const { data } = colors;\n        dispatch(loadColorAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingColorAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingColorAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    statusFooterButttonsModal(true);\n    api.createColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        dispatch(createColorAction(data.result));\n         swal(response.data.message, {\n          icon: 'success'\n        });\n        statusFooterButttonsModal(false);\n        showModal(false);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    statusFooterButttonsModal(true);\n    api.updateColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        dispatch(updateColorAction(data.result));\n        statusFooterButttonsModal(false);\n        showModal(false);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteColorThunkAction(color: IColor) {\n  return (dispatch: Dispatch<ColorReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteColor(color)\n      .then((response: AxiosResponse) => {\n        const { data } = response;\n        dispatch(deleteColorAction(data.id));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IColor } from '../../../../../src/app/interfaces/color.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\n\nexport const COLOR_CANCEL = '/COLOR/CANCEL';\nexport const COLOR_IS_LOADING = '/COLOR/IS_LOADING';\nexport const COLOR_LOAD = '/COLOR/LOAD';\nexport const COLOR_LOAD_FORMS = '/COLOR/LOAD_FORMS';\nexport const COLOR_LOAD_REQUEST = '/COLOR/LOAD_REQUEST';\nexport const COLOR_CREATE = '/COLOR/CREATE';\nexport const COLOR_UDPATE = '/COLOR/UDPATE';\nexport const COLOR_DELETE = '/COLOR/DELETE';\nexport const COLOR_CHANGE_ORDER = '/COLOR/CHANGE_ORDER';\n\nexport interface IColorState {\n  colors: IColor[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelColor {\n  type: typeof COLOR_CANCEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingColor {\n  type: typeof COLOR_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadFormsColor {\n  type: typeof COLOR_LOAD_FORMS;\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport interface ILoadRequestStatusColor {\n  type: typeof COLOR_LOAD_REQUEST;\n  payload: {\n    requestStatus: IRequestStatus[];\n  };\n}\n\nexport interface ILoadColor {\n  type: typeof COLOR_LOAD;\n  payload: {\n    colors: IColor[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateColor {\n  type: typeof COLOR_CREATE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IUpdateColor {\n  type: typeof COLOR_UDPATE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IDeleteColor {\n  type: typeof COLOR_DELETE;\n  payload: {\n    color: IColor\n  };\n}\n\nexport interface IChangeOrderColor {\n  type: typeof COLOR_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type ColorReduxActions =\n  ICancelColor |\n  IIsLoadingColor |\n  ILoadFormsColor |\n  ILoadRequestStatusColor |\n  ICreateColor |\n  IUpdateColor |\n  IDeleteColor |\n  IChangeOrderColor |\n  ILoadColor;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseCompany} from '../../../../../src/app/interfaces/company.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ICompaniesState {\n  companies: IBaseCompany[];\n  tempCompany: IBaseCompany;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/COMPANIES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/COMPANIES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/COMPANIES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/COMPANIES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/COMPANIES/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/COMPANIES/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempCompany {\n  type: '/COMPANIES/CHANGE_TEMP_COMPANY';\n  payload: {\n    company: IBaseCompany;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempCompanyAction(company: IBaseCompany): IChangeTempCompany {\n  return {\n    type: '/COMPANIES/CHANGE_TEMP_COMPANY',\n    payload: {\n      company\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\ninterface ILoadCompanies {\n  type: '/COMPANIES/LOAD_COMPANIES';\n  payload: {\n    companies: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCompaniesAction(companies: any, count: number, pages: number): ILoadCompanies {\n  return {\n    type: '/COMPANIES/LOAD_COMPANIES',\n    payload: {\n      companies,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getCompaniesAction(nextPage: number) {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.companies.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.companies.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getCompanies(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadCompaniesAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createCompanyAction() {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const state = getState();\n    const {tempCompany} = state.companies;\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    statusFooterButttonsModal(true);\n    api.createCompany(tempCompany)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getCompaniesAction(1) as any);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeCompany {\n  type: '/COMPANIES/CHANGE_COMPANY';\n  payload: {\n    company: IBaseCompany;\n  };\n}\n\nexport function changeCompanyAction(company: IBaseCompany): IChangeCompany {\n  return {\n    type: '/COMPANIES/CHANGE_COMPANY',\n    payload: {\n      company\n    }\n  };\n}\n\nexport function updateCompanyAction() {\n  return (dispatch: Dispatch<CompaniesReduxAction>, getState: () => {companies: ICompaniesState}) => {\n    const state = getState();\n    const {tempCompany} = state.companies;\n    statusFooterButttonsModal(true);\n    const $company = $(`#company-${tempCompany._id}`);\n    const api: ApiService = new ApiService();\n    api.updateCompany(tempCompany)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(changeCompanyAction(response.data.company));\n        $company.addClass('editing-item');\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $company.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $company.removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteCompany {\n  type: '/COMPANIES/DELETE_COMPANY';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteCompanyAction(id: string): IDeleteCompany {\n  return {\n    type: '/COMPANIES/DELETE_COMPANY',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteCompanyAction(id: string) {\n  return (dispatch: Dispatch<CompaniesReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteCompany(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#company-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteCompanyAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type CompaniesReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadCompanies |\n  IChangeTempCompany |\n  IChangeCompany |\n  IDeleteCompany;\n","import { AxiosError, AxiosResponse, CancelTokenSource, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as React from 'react';\nimport { Dispatch } from 'redux';\nimport { ICar } from '../../../../../src/app/interfaces/car.interface';\nimport { IParticipant, IParticipantSection } from '../../../../../src/form/interfaces/participant.interface';\nimport ImageLazyLoad from '../components/Utils/ImageLazyLoad';\nimport ApiService from '../utils/axios';\nimport { loadDataAction } from './modal.actions';\nimport ShowIf from '../components/Utils/ShowIf';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\n\nexport interface IDashboardState {\n  forms: IForm[];\n  searchForms: string[],\n  loading: boolean;\n  source: CancelTokenSource | null;\n  participants: any[];\n  requests: any[];\n  companies: any[];\n  car: ICar | null;\n  carEvents: any;\n  participantsReceivedPerDate: any[];\n  participantsSentPerDate: any[];\n  carsPerDate: any[];\n  planningPerDate: any[];\n  planningProcessPerDate: any[];\n  carsByVenue: any[];\n  searchText: string;\n  searchFrom: Date,\n  searchTo: Date,\n  participantPerRange: any[];\n  loadingParticipant: string | null;\n  totalCars: number;\n  venueStats: any[] | null;\n  revisionStats: any;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ICancelRequest {\n  type: '/DASHBOARD/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/DASHBOARD/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface ILoadRevisions {\n  type: '/DASHBOARD/LOAD_PARTICIPANTS';\n  payload: {\n    participants: IParticipant[];\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadCarsAction(participants: IParticipant[], count: number, pages: number): ILoadRevisions {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANTS',\n    payload: {\n      participants,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadParticipantInCar {\n  type: '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR';\n  payload: {\n    participant: IParticipant;\n  };\n}\n\ninterface ILoadRequestsInCar {\n  type: '/DASHBOARD/LOAD_REQUESTS_IN_CAR';\n  payload: {\n    requests: any;\n  };\n}\n\nexport function loadParticipantInCarAction(participant: IParticipant): ILoadParticipantInCar {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANT_IN_CAR',\n    payload: {\n      participant\n    }\n  };\n}\n\nexport function loadRequestsInCarAction(requests: any): ILoadRequestsInCar {\n  return {\n    type: '/DASHBOARD/LOAD_REQUESTS_IN_CAR',\n    payload: {\n      requests\n    }\n  };\n}\n\ninterface ILoadCar {\n  type: '/DASHBOARD/LOAD_CAR';\n  payload: {\n    car: ICar;\n  };\n}\n\nexport function loadCarAction(car: ICar): ILoadCar {\n  return {\n    type: '/DASHBOARD/LOAD_CAR',\n    payload: {\n      car\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/DASHBOARD/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/DASHBOARD/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeSearchDashboard {\n  type: '/DASHBOARD/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchDashboardAction(searchText: string): IChangeSearchDashboard {\n  return {\n    type: '/DASHBOARD/CHANGE_SEARCH',\n    payload:\n      {\n      searchText\n    }\n  };\n}\n\ninterface IChangeRangeDashboard {\n  type: '/DASHBOARD/CHANGE_RANGE';\n  payload: {\n    from: Date,\n    to: Date,\n  };\n}\n\nexport function changeRangeDashboardAction(from: Date, to: Date): IChangeRangeDashboard {\n  return {\n    type: '/DASHBOARD/CHANGE_RANGE',\n    payload: {\n      from,\n      to\n    }\n  }\n}\n\ninterface IChangeFormsSearchDashboard {\n  type: '/DASHBOARD/CHANGE_FORM_SEARCH';\n  payload: {\n    searchForms: string[];\n  };\n}\n\nexport function changeFormsSearchDashboardAction(searchForms: string[]): IChangeFormsSearchDashboard {\n  return {\n    type: '/DASHBOARD/CHANGE_FORM_SEARCH',\n    payload: {\n      searchForms\n    }\n  };\n}\n\ninterface ILoadingForms {\n  type: '/DASHBOARD/LOAD_FORMS';\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport function loadForms(forms: IForm[]): ILoadingForms {\n  return {\n    type: '/DASHBOARD/LOAD_FORMS',\n    payload: {\n      forms\n    }\n  };\n}\n\nexport function getRevisionsThunkAction(nextPage: number, loading: boolean, search?: string, from?: string, to?: string, onlyControls : boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>, getState: () => {dashboard: IDashboardState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(cancelRequestAction(api.getSource()));\n    if (loading) {\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.dashboard.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    const { searchText, searchFrom, searchTo, searchForms } = state.dashboard;\n    Axios\n      .all([\n        api.getRevisions({ onlyControls, deliveries: false, page, search: searchText, from: searchFrom, to: searchTo, forms: searchForms }),\n        api.getUserForms({ deliveries: false })\n      ])\n      .then(Axios.spread((response, forms) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(loadForms(forms.data.results));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      }))\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          if (loading) {\n            dispatch(isLoadingAction(true));\n          }\n        } else {\n          if (loading) {\n            dispatch(isLoadingAction(false));\n          }\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\n\nexport function getRevisionsAction(nextPage: number, loading: boolean, search?: string, from?: string, to?: string, onlyControls : boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>, getState: () => {dashboard: IDashboardState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(cancelRequestAction(api.getSource()));\n    if (loading) {\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.dashboard.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    const { searchText, searchFrom, searchTo, searchForms } = state.dashboard;\n    api.getRevisions({ onlyControls, deliveries: false, page, search: searchText, from: searchFrom, to: searchTo, forms: searchForms })\n      .then((response: AxiosResponse) => {\n        dispatch(loadCarsAction(response.data.results, response.data.count, response.data.pages));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          if (loading) {\n            dispatch(isLoadingAction(true));\n          }\n        } else {\n          if (loading) {\n            dispatch(isLoadingAction(false));\n          }\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingParticipant {\n  type: '/DASHBOARD/LOADING_PARTICIPANT';\n  payload: {\n    loadingParticipant: string | null;\n  };\n}\n\nexport function loadingParticipantAction(loadingParticipant: string | null): ILoadingParticipant {\n  return {\n    type: '/DASHBOARD/LOADING_PARTICIPANT',\n    payload: {\n      loadingParticipant\n    }\n  };\n}\n\nexport function getParticipant(id: string) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(loadingParticipantAction(id));\n    api.getParticipant(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data.data;\n        dispatch(loadDataAction(\n          data.name,\n          <div id=\"form-detail\">\n            <table style={{width: '100%'}}>\n              <tbody>\n              <tr>\n                <td style={{width: '40%'}}><strong>Supervisor</strong></td>\n                <td>{data.user ? data.user.firstName : ''} {data.user ? data.user.lastName : ''}</td>\n              </tr>\n              <tr>\n                <td style={{width: '40%'}}><strong>Fecha</strong></td>\n                <td>{moment(data.createdAt).format('LLL')}</td>\n              </tr>\n              {/* <tr>\n                <td style={{width: '40%'}}><strong>Calificación</strong></td>\n                <td>{Math.round(data.qualification)}%</td>\n              </tr> */}\n              {\n                data.receptionText && data.receptionText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Recepcionado</strong>\n                    </td>\n                    <td>{data.receptionConfirmation ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.receptionText && data.receptionText.length && data.receptionImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.receptionImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'reception'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              {\n                data.receiveFrom ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Recepcionado desde</strong>\n                    </td>\n                    <td>{data.receiveFrom.name}</td>\n                  </tr> : null\n              }\n              {\n                data.sendTo ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Enviado a</strong>\n                    </td>\n                    <td>{data.sendTo.name}</td>\n                  </tr> : null\n              }\n              {\n                data.carrier && data.carrierBy ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Transportista</strong>\n                    </td>\n                    <td>{data.carrierBy.name}</td>\n                  </tr> : null\n              }\n              {\n                data.shippingText && data.shippingText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Enviado</strong>\n                    </td>\n                    <td>{data.shipping ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.shippingText && data.shippingText.length && data.shippingImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.shippingImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'shipping'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              {\n                data.conciliationText && data.conciliationText.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                      <strong>Conciliado</strong>\n                    </td>\n                    <td>{data.conciliation ? <i className=\"fa fa-check text-success\" /> : <i className=\"fa fa-close text-danger\" />}</td>\n                  </tr> : null\n              }\n              {\n                data.conciliationText && data.conciliationText.length && data.conciliationImages.length ?\n                  <tr>\n                    <td style={{width: '40%'}}>\n                    </td>\n                    <td>{\n                      <div className=\"row special-question images\">\n                        {\n                          data.conciliationImages.map((image: any) => {\n                            return (\n                              <div className=\"col-md-2 col-sm-2 col-xs-2 text-center\" key={image._id}>\n                                <a href={image.file.url} data-toggle=\"lightbox\" data-gallery={'conciliation'}>\n                                  <ImageLazyLoad\n                                    url={image.file.url}\n                                    small={true}\n                                    height={'50px'}\n                                  />\n                                </a>\n                              </div>\n                            );\n                          })\n                        }\n                      </div>\n                    }</td>\n                  </tr> : null\n              }\n              </tbody>\n            </table>\n            {\n              data.sections.map((section: IParticipantSection, index: number) => {\n                return (\n                  <div className=\"section\" key={index}>\n                    <h4>{section.name} <small>{Math.round(section.qualification)}%</small></h4>\n                      {\n                        section.answers.map((answer: any) => {\n                          const selectChoice = answer.scale ? answer.scale.choices.find((choice: any) => choice._id === answer.answer) : undefined;\n                          const kinds: any = answer.damages && answer.damages.hasOwnProperty('kinds') ? answer.damages.kinds.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            return acc;\n                          }, {}) : {};\n                          const parts: any = answer.damages && answer.damages.hasOwnProperty('parts') ? answer.damages.parts.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            return acc;\n                          }, {}) : {};\n                          const positions: any = answer.damages && answer.damages.hasOwnProperty('positions') ? answer.damages.positions.reduce((acc: any, cur: any) => {\n                            acc[cur._id] = cur.name;\n                            const severity: string = answer.damages && answer.requireSeverity && answer.damages.hasOwnProperty('severity') ? answer.damages.severity : \"\"\n                            return acc;\n                          }, {}) : {};\n                          // no show conciliation questions if no require\n                          if (answer.conciliation && !selectChoice) {\n                            return null;\n                          }\n                          const accesorySeletedIds = answer.accesoriesAnswered ? answer.accesoriesAnswered.map((accesory:any) => accesory.item) : [];\n                          const items = answer.accessories ? answer.accessories.items.filter((item:any) => accesorySeletedIds.includes(item._id)) : [];\n                          return (\n                            <div className=\"question\" key={answer._id}>\n                              <p><strong>{answer.order} {answer.question} {!answer.optional ? <span className=\"red text-bold\">*</span> : null }</strong>\n                              {answer.hint && answer.hint !== \"\" ? <small><br/>{answer.hint}</small> : null}</p>\n                              {\n                                answer.scale ?\n                                  <div className=\"flex\" role=\"group\" aria-label=\"...\" key={answer._id}>\n                                    {\n                                      answer.scale.choices.map((choice: any) => {\n                                        const btnDefault = 'btn-default';\n                                        const optionsClass: any = {\n                                          blue: 'btn-primary',\n                                          green: 'btn-success',\n                                          yellow: 'btn-warning',\n                                          red: 'btn-danger'\n                                        };\n                                        const btnClass = optionsClass.hasOwnProperty(choice.backgroundColor) ? optionsClass[choice.backgroundColor] : btnDefault;\n                                        return (\n                                          <button\n                                            key={choice._id}\n                                            type=\"button\"\n                                            className={`btn flex-row-item text-wrap ${choice._id === answer.answer ? btnClass : btnDefault}`}\n                                            style={{margin: '2px'}}\n                                            disabled={true}\n                                          >{choice.choice}</button>\n                                        );\n                                      })\n                                    }\n                                  </div>\n                                  : null\n                              }\n                              {\n                                // TODO: validate by kind question\n                                answer.damagesSelected && answer.damagesSelected.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    {\n                                      answer.damagesSelected.map((ds: any, index: number) => (\n                                        <div className=\"col-md-12 damage\" key={index}>\n                                          <div className=\"damage-detail\">\n                                            <p className=\"damage-description\">\n                                              <strong className=\"title\">{parts.hasOwnProperty(ds.part) ? parts[ds.part] : '-'}</strong><br/>\n                                              <strong>Daño</strong> {kinds.hasOwnProperty(ds.kind) ? kinds[ds.kind] : '-'}{' '}\n                                              <strong>Posición</strong> {positions.hasOwnProperty(ds.position) ? positions[ds.position] : '-'}\n                                              { answer.damages && answer.requireSeverity && ds.hasOwnProperty('severity') ?\n                                                <> <strong>Severidad</strong> {ds.severity} </> : null\n                                              }\n                                            </p>\n                                            <ShowIf\n                                              condition={!!ds.images.length}\n                                              alternative={\n                                                <p style={{ padding: '0 5px' }} className=\"text-muted\">\n                                                  No se reportaron imágenes.\n                                                </p>\n                                              }\n                                            >\n                                              <div className='row images'>\n                                                {\n                                                  ds.images.map((image: any) => {\n                                                    return (\n                                                      <div\n                                                        className='col-md-3 col-sm-4 col-xs-4 text-center'\n                                                        key={image._id}\n                                                        data-toggle='tooltip'\n                                                        data-placement='bottom'\n                                                        title={image.file.name}\n                                                      >\n                                                        <a\n                                                          href={image.file.url}\n                                                          data-toggle='lightbox'\n                                                          className='zoom-in'\n                                                          data-gallery={ds._id}\n                                                          data-title={parts.hasOwnProperty(ds.part) ? parts[ds.part] : '-'}\n                                                        >\n                                                          <ImageLazyLoad\n                                                            url={image.file.url}\n                                                            height={'100px'}\n                                                          />\n                                                        </a>\n                                                        {/*<p*/}\n                                                        {/*  className={'text-ellipsis'}*/}\n                                                        {/*  data-toggle='tooltip'*/}\n                                                        {/*  data-placement='top'*/}\n                                                        {/*  title={image.file.name}*/}\n                                                        {/*>*/}\n                                                        {/*  {image.file.name}*/}\n                                                        {/*</p>*/}\n                                                      </div>\n                                                    );\n                                                  })\n                                                }\n                                              </div>\n                                            </ShowIf>\n                                          </div>\n                                        </div>\n                                      ))\n                                    }\n                                  </div>\n                                  : answer.damages && answer.damages.hasOwnProperty('parts') ? 'No se han seleccionado daños.' : null\n                              }\n                              {\n                                selectChoice && selectChoice.requireAccesories && answer.accessories && answer.accessories.items.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>{answer.accessories.question}</strong></p>\n                                      {\n                                        items.length ? items.map((item:any) => {\n                                          return (\n                                            <p key={item._id}\n                                              // className={answer.accesoriesAnswered.includes(item._id) ? 'text-green' : 'text-red'}\n                                            >\n                                              {\n                                                /*\n                                                answer.accesoriesSelected.includes(item._id) ?\n                                                  <i className=\"fa fa-check\" style={{marginRight: '5px'}}/> :\n                                                  <i className=\"fa fa-times\" style={{marginRight: '5px', width: '14px'}}/>\n                                                 */\n                                              } - {item.item} {item.amount ? `(${answer.accesoriesAnswered.find((accesory:any) => accesory.item === item._id).amount})` : ''}\n                                            </p>\n                                          );\n                                        }) : 'No se seleccionaron items.'\n                                      }\n                                    </div>\n                                  </div>\n                                  : null\n                              }\n                              {\n                                ((selectChoice && selectChoice.requireImage) || answer.kind === 'image') && answer.images && answer.images.length ?\n                                  <div className=\"row images\">\n                                    {\n                                      answer.images.map((image: any) => {\n                                        return (\n                                          <div className=\"col-md-3 col-sm-4 col-xs-4 text-center\" key={image._id}>\n                                            <a\n                                              href={image.file.url}\n                                              className=\"zoom-in\"\n                                              data-toggle=\"lightbox\"\n                                              data-gallery={answer._id}\n                                            >\n                                              <ImageLazyLoad\n                                                url={image.file.url}\n                                                height={'100px'}\n                                              />\n                                            </a>\n                                            <p\n                                              className={'text-ellipsis'}\n                                              data-toggle=\"tooltip\"\n                                              data-placement=\"top\"\n                                              title={image.file.name}\n                                            >\n                                              {image.file.name}\n                                            </p>\n                                          </div>\n                                        );\n                                      })\n                                    }\n                                  </div>\n                                : null\n                              }\n                              {\n                                (answer.kind === 'text' || selectChoice && selectChoice.requireComment) && answer.comment && answer.comment.length ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>Comentario</strong>: <span className=\"text-muted\">{answer.comment}</span></p>\n                                    </div>\n                                  </div>\n                                : null\n                              }\n\n                              {\n                                (answer.kind === 'numeric-scale') && answer.score != -1  ?\n                                  <div className=\"row\" style={{marginTop: '10px'}}>\n                                    <div className=\"col-md-12\">\n                                      <p><strong>Evaluación</strong>: <span className=\"text-muted\">{answer.score} (Del {answer.minValue} al {answer.maxValue})</span></p>\n                                    </div>\n                                  </div>\n                                  : null\n                              }\n                            </div>\n                          );\n                        })\n                      }\n                  </div>\n                );\n              })\n            }\n            <small>Las preguntas marcadas con <span className=\"red text-bold\">*</span> son obligatorias.</small>\n          </div>\n          ) as any);\n        dispatch(loadingParticipantAction(null));\n        ($('[data-toggle=\"tooltip\"]') as any).tooltip();\n      })\n      .catch((err: AxiosError) => {\n        if (Axios.isCancel(err)) {\n          dispatch(loadingParticipantAction(null));\n        } else {\n          dispatch(loadingParticipantAction(null));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadParticipantsPerDate {\n  type: '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE';\n  payload: {\n    companies: any[];\n    participantsReceivedPerDate: any;\n    participantsSentPerDate: any;\n    carsPerDate: any;\n    planningPerDate: any;\n    planningProcessPerDate: any;\n    carsByVenue: any;\n    totalCars: number;\n    participantPerRange: any;\n  };\n}\n\nexport function loadParticipantsPerDateAction(companies: any[], participantsReceivedPerDate: any, participantsSentPerDate:any, carsPerDate: any, planningPerDate: any, planningProcessPerDate:any, totalCars: number, carsByVenue: any, participantPerRange: any): ILoadParticipantsPerDate {\n  return {\n    type: '/DASHBOARD/LOAD_PARTICIPANTS_PER_DATE',\n    payload: {\n      companies,\n      participantsReceivedPerDate,\n      participantsSentPerDate,\n      carsPerDate,\n      planningPerDate,\n      planningProcessPerDate,\n      carsByVenue,\n      totalCars,\n      participantPerRange\n    }\n  };\n}\n\nexport function getParticipantsPerDateAction(companies?:string, onlyControls: boolean = true) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getParticipantsPerDate(onlyControls, companies)\n      .then((response: AxiosResponse) => {\n        dispatch(loadParticipantsPerDateAction(response.data.companies, response.data.participantsReceived, response.data.participantsSent, response.data.cars, response.data.planning, response.data.planningProcess, response.data.totalCars, response.data.carsByVenue, response.data.participantPerRange));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function getCarAction(id: string) {\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getCar(id),\n      api.getRequestsByCar(id)\n    ]).then(Axios.spread((car, requests) => {\n      // dispatch(loadDashboardCleaningAction(dashboard.data));\n      document.title = `OSA Andes | Detalle VIN ${car.data.data.vin}`;\n      dispatch(loadCarAction(car.data.data));\n      dispatch(loadRequestsInCarAction(requests.data));\n      dispatch(isLoadingAction(false));\n      window.scrollTo(0, 0);\n    }))\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingVenuesStats {\n  type: '/DASHBOARD/LOAD_VENUES_STATS';\n  payload: {\n    venuesStats: any[];\n  };\n}\n\nexport function loadVenuesStats(venuesStats: any[]): ILoadingVenuesStats {\n  return {\n    type: '/DASHBOARD/LOAD_VENUES_STATS',\n    payload: {\n      venuesStats\n    }\n  };\n}\n\nexport function getVenuesStats(from: number, to: number){\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getVenuesStats(from, to)\n      .then((response: AxiosResponse) => {\n        dispatch(loadVenuesStats(response.data as any[]));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n        } else {\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadingRevisionsStats {\n  type: '/DASHBOARD/LOAD_REVISION_STATS';\n  payload: {\n    revisionStats: any;\n  };\n}\n\nexport function loadRevisionsStats(revisionStats: any[]): ILoadingRevisionsStats {\n  return {\n    type: '/DASHBOARD/LOAD_REVISION_STATS',\n    payload: {\n      revisionStats\n    }\n  };\n}\n\nexport function getRevisionStats(){\n  return (dispatch: Dispatch<DashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    dispatch(isLoadingAction(true));\n    api.getRevisionsStats()\n      .then((response: AxiosResponse) => {\n        dispatch(loadRevisionsStats(response.data));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(true));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\n\nexport type DashboardReduxAction =\n  IIsLoading |\n  ICancelRequest |\n  ILoadRevisions |\n  IChangeSearchDashboard |\n  IChangeRangeDashboard |\n  ILoadCar |\n  ILoadParticipantsPerDate |\n  ILoadingParticipant |\n  IChangePage |\n  ILoadParticipantInCar |\n  ILoadRequestsInCar |\n  ILoadingVenuesStats |\n  ILoadingRevisionsStats |\n  ILoadingForms |\n  IChangeFormsSearchDashboard;\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\nexport interface IDashboardDamagesState {\n  data: any;\n  venues: any[],\n  loading: boolean;\n}\n\ninterface ILoadDashboardDamages {\n  type: '/DASHBOARD/DAMAGES/LOAD_DATA';\n  payload: {\n    data: any\n  };\n}\n\nexport function loadDashboardDamagesAction(data: any): ILoadDashboardDamages {\n  return {\n    type: '/DASHBOARD/DAMAGES/LOAD_DATA',\n    payload: {\n      data\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/DAMAGES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/DAMAGES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardDamagesPerVenue(update?: boolean) {\n  return (dispatch: Dispatch<DashboardDamagesReduxAction>) => {\n    const api: ApiService = new ApiService();\n    if (update) {\n      dispatch(isLoadingAction(true));\n    }\n    Axios.all([\n      api.getDashboardDamagesPerVenue()\n    ]).then(Axios.spread((dashboard) => {\n      dispatch(isLoadingAction(false));\n      dispatch(loadDashboardDamagesAction(dashboard.data));\n    })).catch((err: AxiosError): void => {\n      dispatch(isLoadingAction(false));\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport type DashboardDamagesReduxAction = ILoadDashboardDamages | IIsLoading;\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\ninterface ICleaningData {\n  loading: boolean,\n  days: [],\n  clean: [],\n  notClean: []\n}\n\nexport interface IDashboardDercoState {\n  cleaning: ICleaningData\n}\n\ninterface ILoadDashboardCleaning {\n  type: '/DASHBOARD/CLEANING/LOAD_DATA_DAILY';\n  payload: {\n    cleaning: ICleaningData,\n  };\n}\n\nexport function loadDashboardCleaningAction(cleaning: ICleaningData): ILoadDashboardCleaning {\n  return {\n    type: '/DASHBOARD/CLEANING/LOAD_DATA_DAILY',\n    payload: {\n      cleaning\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/CLEANING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/CLEANING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardCleaning() {\n  return (dispatch: Dispatch<DashboardDercoReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getDashboardCleaning()\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadDashboardCleaningAction(dashboard.data));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport type DashboardDercoReduxAction = ILoadDashboardCleaning | IIsLoading\n","import {AxiosError, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport ApiService from '../utils/axios';\n\ninterface ITimingData {\n  months: string[];\n  overdue: number[];\n  ontime: number[];\n}\n\nexport interface IDashboardTimingState {\n  data: any;\n  venues: any[];\n  venuesDict: any;\n  loading: boolean;\n  loadingPerVenue: boolean;\n  perVenue: any;\n}\n\ninterface ILoadDashboardTiming {\n  type: '/DASHBOARD/TIMING/LOAD_DATA';\n  payload: {\n    venues: any[],\n    data: any\n  };\n}\n\nexport function loadDashboardTimingAction(venues: any[], data: any): ILoadDashboardTiming {\n  return {\n    type: '/DASHBOARD/TIMING/LOAD_DATA',\n    payload: {\n      venues,\n      data\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/DASHBOARD/TIMING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/DASHBOARD/TIMING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IIsLoadingPerVenue {\n  type: '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingPerVenueAction(loading: boolean): IIsLoadingPerVenue {\n  return {\n    type: '/DASHBOARD/TIMING/IS_LOADING_PER_VENUE',\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function getDashboardTiming(from: string, to: string) {\n  return (dispatch: Dispatch<DashboardTimingReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getDashboardTiming(from, to)\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadDashboardTimingAction(venues.data.results, dashboard.data));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\n\nexport type DashboardTimingReduxAction = ILoadDashboardTiming | IIsLoading | IIsLoadingPerVenue;\n","import ApiService from '../utils/axios';\nimport { Dispatch } from 'redux';\nimport {\n  CANCEL_DELIVERIES,\n  CHANGE_FILTER_DELIVERIES,\n  DeliveriesFilter,\n  IDeliveriesActionTypes,\n  IDeliveriesState,\n  IDeliveryDispatch,\n  LOAD_DELIVERIES,\n  LOAD_FORMS,\n  LOADING_DELIVERIES\n} from './deliveries.types';\nimport { AxiosError, CancelTokenSource, default as Axios } from 'axios';\nimport { IParticipant } from '../../../../../src/form/interfaces/participant.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\n\nexport default class DeliveriesActions {\n\n  private api: ApiService;\n\n  constructor(private dispatch: IDeliveryDispatch) {\n    this.api = new ApiService();\n  }\n\n  public loadingAction(loading: boolean): void {\n    this.dispatch({\n      type: LOADING_DELIVERIES,\n      payload: {\n        loading\n      }\n    });\n  }\n\n  public loadDeliveriesAction(participants: IParticipant[], count: number, page: number, pages: number): void {\n    this.dispatch({\n      type: LOAD_DELIVERIES,\n      payload: {\n        participants,\n        count,\n        page,\n        pages\n      }\n    });\n  }\n\n  public loadFormsAction(forms: IForm[]): void {\n    this.dispatch({\n      type: LOAD_FORMS,\n      payload: {\n        forms\n      }\n    });\n  }\n\n  public updateFiltersAction(filters: Partial<DeliveriesFilter>): void {\n    Object.entries(filters).forEach(([key, value]) => {\n      this.changeFilterAction({ [key]: value });\n    });\n    this.getDeliveriesThunkAction(1, true);\n  }\n\n  public changeFilterAction(filters: Partial<DeliveriesFilter>): void {\n    this.dispatch({\n      type: CHANGE_FILTER_DELIVERIES,\n      payload: filters\n    });\n  }\n\n  public getDeliveriesThunkAction(nextPage: number, loading: boolean): void {\n    this.dispatch((dispatch: Dispatch<IDeliveriesActionTypes>, getState: () => { deliveries: IDeliveriesState }) => {\n      const { deliveries } = getState();\n      const { pagination, filters } = deliveries;\n      const page = nextPage ? nextPage : pagination.page;\n      this.cancelAction(this.api.getSource());\n      Axios\n        .all([\n          this.api.getRevisions({\n            onlyControls:true,\n            deliveries: true,\n            page,\n            forms: filters.forms,\n            from: filters.from,\n            to: filters.to,\n            search: filters.searchText,\n            delivery: filters.searchDelivery,\n          }),\n          this.api.getUserForms({ deliveries: true })\n        ])\n        .then(Axios.spread((deliveries, forms) => {\n          const { results, count, pages } = deliveries.data;\n          this.loadDeliveriesAction(results, count, page, pages);\n          this.loadFormsAction(forms.data.results);\n          this.loadingAction(false);\n        }))\n        .catch((err: AxiosError) => {\n          if (Axios.isCancel(err)) {\n            if (loading) {\n              this.loadingAction(true);\n            }\n          } else {\n            if (loading) {\n              this.loadingAction(false);\n            }\n            this.api.errorHandler(err);\n          }\n        });\n    });\n  }\n\n  private cancelAction(source: CancelTokenSource): void {\n    this.dispatch({\n      type: CANCEL_DELIVERIES,\n      payload: {\n        source\n      }\n    });\n  }\n}\n","import { CancelTokenSource } from 'axios';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IParticipant } from '../../../../../src/form/interfaces/participant.interface';\nimport { ThunkDispatch } from 'redux-thunk';\n\nexport const LOADING_DELIVERIES = '@deliveries/LOADING_DELIVERIES';\nexport const LOAD_DELIVERIES = '@deliveries/LOAD_DELIVERIES';\nexport const LOAD_FORMS = '@deliveries/LOAD_FORMS';\nexport const CHANGE_FILTER_DELIVERIES = '@deliveries/CHANGE_FILTER_DELIVERIES';\nexport const CANCEL_DELIVERIES = '@deliveries/CANCEL_DELIVERIES';\n\ninterface IDeliveriesLoadingAction {\n  type: typeof LOADING_DELIVERIES;\n  payload: {\n    loading: boolean;\n  };\n}\n\ninterface IDeliveriesLoadAction {\n  type: typeof LOAD_DELIVERIES;\n  payload: {\n    participants: IParticipant[];\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IDeliveriesLoadFormsAction {\n  type: typeof LOAD_FORMS;\n  payload: {\n    forms: IForm[];\n  }\n}\n\ninterface IDeliveriesCancelAction {\n  type: typeof CANCEL_DELIVERIES;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport type DeliveriesFilterFields = 'forms' | 'from' | 'to' | 'searchText'| 'searchDelivery';\nexport type DeliveriesFilterValues = any | any[];\nexport type DeliveriesFilter = Record<DeliveriesFilterFields, DeliveriesFilterValues>\n\ninterface IDeliveriesChangeFilterAction {\n  type: typeof CHANGE_FILTER_DELIVERIES;\n  payload: Partial<DeliveriesFilter>;\n}\n\nexport interface IDeliveriesState {\n  forms: IForm[];\n  participants: IParticipant[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  filters: DeliveriesFilter;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport type IDeliveryDispatch = ThunkDispatch<{ deliveries: IDeliveriesState }, {}, IDeliveriesActionTypes>;\n\nexport type IDeliveriesActionTypes =\n  IDeliveriesLoadingAction |\n  IDeliveriesChangeFilterAction |\n  IDeliveriesLoadAction |\n  IDeliveriesLoadFormsAction |\n  IDeliveriesCancelAction;\n\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport ApiService from '../utils/axios';\nimport {\n  FORM_CANCEL_STATUS,\n  FORM_CHANGE_ORDER,\n  FORM_CREATE_STATUS,\n  FORM_DELETE_STATUS,\n  FORM_IS_LOADING, FORM_LOAD_MILESTONE_TYPES,\n  FORM_LOAD_REQUEST_STATUS,\n  FORM_LOAD_STATUS,\n  FORM_UDPATE_STATUS,\n  FormReduxActions,\n  ICancelForm,\n  IChangeOrderForm,\n  ICreateForm,\n  IDeleteForm,\n  IFormsState,\n  IIsLoadingForm,\n  ILoadForm, ILoadMilestoneTypesForm,\n  ILoadRequestStatusForm,\n  IUpdateForm\n} from './form.types';\nimport * as swal from 'sweetalert';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport {IMilestoneType} from \"../../../../../src/distribution/interfaces/milestoneType.interface\";\n\nexport function cancelFormAction(source: CancelTokenSource): ICancelForm {\n  return {\n    type: FORM_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingFormAction(loading: boolean): IIsLoadingForm {\n  return {\n    type: FORM_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadFormAction(forms: IForm[], count: number, pages: number, page: number): ILoadForm {\n  return {\n    type: FORM_LOAD_STATUS,\n    payload: {\n      forms,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createFormItemAction(form: IForm): ICreateForm {\n  return {\n    type: FORM_CREATE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\nexport function updateFormItemAction(form: IForm): IUpdateForm {\n  return {\n    type: FORM_UDPATE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\n\nexport function deleteFormAction(form: IForm): IDeleteForm {\n  return {\n    type: FORM_DELETE_STATUS,\n    payload: {\n      form\n    }\n  };\n}\n\nexport function changeOrderFormAction(orderBy: string, orderType: string): IChangeOrderForm {\n  return {\n    type: FORM_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function loadRequestStatusFormAction(requestStatus: IRequestStatus[]): ILoadRequestStatusForm {\n  return {\n    type: FORM_LOAD_REQUEST_STATUS,\n    payload: {\n      requestStatus\n    }\n  };\n}\n\nexport function loadTypesMilestoneAction(milestoneTypes: IMilestoneType[]): ILoadMilestoneTypesForm {\n  return {\n    type: FORM_LOAD_MILESTONE_TYPES,\n    payload: {\n      milestoneTypes\n    }\n  };\n}\n\n\n\nexport function getFormsThunkAction(nextPage: number, hideLoading?: boolean) {\n  return (dispatch: Dispatch<FormReduxActions>, getState: () => { form: IFormsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingFormAction(!hideLoading));\n    const page = nextPage ? nextPage : state.form.pagination.page;\n    // dispatch(changeOrderFormAction(orderBy, orderType));\n    dispatch(cancelFormAction(api.getSource()));\n    Axios\n      .all([\n        api.getForms(page),\n        api.getRequestItemsStatus({ page:1, pageSize: 200 }),\n        api.getMilestoneTypes({ page: 1, pageSize: 200 }),\n      ])\n      .then(Axios.spread((forms, requestStatus, milestones) => {\n        const { data } = forms;\n        dispatch(loadFormAction(data.results, data.count, data.pages, page));\n        dispatch(loadRequestStatusFormAction(requestStatus.data.results));\n        dispatch(loadTypesMilestoneAction(milestones.data.results));\n        dispatch(isLoadingFormAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingFormAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\nexport function createFormThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateFormThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateFormWithoutThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateForm(form)\n      .then()\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteFormItemThunkAction(form: IForm) {\n  return (dispatch: Dispatch<FormReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteForm(form)\n      .then((response: AxiosResponse) => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport {IMilestoneType} from \"../../../../../src/distribution/interfaces/milestoneType.interface\";\n\nexport const FORM_CANCEL_STATUS = '/FORM/CANCEL_STATUS';\nexport const FORM_IS_LOADING = '/FORM/IS_LOADING';\nexport const FORM_LOAD_STATUS = '/FORM/LOAD_STATUS';\nexport const FORM_LOAD_REQUEST_STATUS = '/FORM/LOAD_REQUEST_STATUS';\nexport const FORM_LOAD_MILESTONE_TYPES = '/FORM/LOAD_MILESTONE_TYPES';\nexport const FORM_CREATE_STATUS = '/FORM/CREATE_STATUS';\nexport const FORM_UDPATE_STATUS = '/FORM/UDPATE_STATUS';\nexport const FORM_DELETE_STATUS = '/FORM/DELETE_STATUS';\nexport const FORM_CHANGE_ORDER = '/FORM/CHANGE_ORDER';\n\nexport interface IFormsState {\n  forms: IForm[];\n  requestStatus: IRequestStatus[];\n  milestoneTypes: IMilestoneType[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelForm {\n  type: typeof FORM_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingForm {\n  type: typeof FORM_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestStatusForm {\n  type: typeof FORM_LOAD_REQUEST_STATUS;\n  payload: {\n    requestStatus: IRequestStatus[];\n  };\n}\n\nexport interface ILoadMilestoneTypesForm {\n  type: typeof FORM_LOAD_MILESTONE_TYPES;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n  };\n}\n\nexport interface ILoadForm {\n  type: typeof FORM_LOAD_STATUS;\n  payload: {\n    forms: IForm[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateForm {\n  type: typeof FORM_CREATE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IUpdateForm {\n  type: typeof FORM_UDPATE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IDeleteForm {\n  type: typeof FORM_DELETE_STATUS;\n  payload: {\n    form: IForm\n  };\n}\n\nexport interface IChangeOrderForm {\n  type: typeof FORM_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type FormReduxActions =\n  ICancelForm |\n  IIsLoadingForm |\n  ILoadRequestStatusForm |\n  ILoadMilestoneTypesForm |\n  ICreateForm |\n  IUpdateForm |\n  IDeleteForm |\n  IChangeOrderForm |\n  ILoadForm;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IInventoryCar} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\nimport {IInventoryComment} from '../../../../../src/inventory/interfaces/inventoryComment.interface';\nimport {IInventoryLabel} from '../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {IFilterCar} from '../reducers/inventory.reducer';\nimport ApiService from '../utils/axios';\n\nexport interface IInventorySummaryResult {\n  pending: number;\n  found: number;\n  leftover: number;\n  reported: number;\n  missing: number;\n}\n\nexport interface IInventorySummary {\n  _id: string;\n  name: string;\n  createdBy?: {\n    lastName: string;\n    firstName: string;\n    fullName: string;\n  };\n  results?: IInventorySummaryResult;\n  status: string;\n  createdAt: Date | null;\n  finalizedAt: Date | null;\n}\n\nexport interface IDetailByVenue {\n  _id: string;\n  name: string;\n  results: {\n    pending: number;\n    found: number;\n    leftover: number;\n    missing: number;\n    reported: number;\n  };\n}\n\nexport interface IDetailByBrand {\n  name: string;\n  results: {\n    pending: number;\n    found: number;\n    missing: number;\n    leftover: number;\n    reported: number;\n  };\n}\n\nexport interface IInventoryState {\n  inventories: any[];\n  inventorySettings: IInventorySetting;\n  loading: boolean;\n  inventoryCar: IInventoryCar | null;\n  source: CancelTokenSource | null;\n  loadingDetail: boolean;\n  fetchingDetail: boolean;\n  summary: IInventorySummary;\n  detail: any | null;\n  detailByVenue: IDetailByVenue[];\n  labels: IInventoryLabel[];\n  detailByBrand: IDetailByBrand[];\n  carsTable: any[];\n  cardTypes: string[];\n  cardProperties: string[];\n  selectedItems: {\n    [key: string]: any\n  };\n  filter: IFilterCar;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IUpdateInventoryCar {\n  type: '/INVENTORIES/UPDATE_INVENTORY_CAR';\n  payload: {\n    inventoryCar: IInventoryCar;\n  };\n}\n\nexport function updateInventoryCarAction(inventoryCar: IInventoryCar): IUpdateInventoryCar {\n  return {\n    type: '/INVENTORIES/UPDATE_INVENTORY_CAR',\n    payload: {\n      inventoryCar\n    }\n  };\n}\n\ninterface IAddComment {\n  type: '/INVENTORIES/ADD_COMMENT';\n  payload: {\n    inventoryComment: IInventoryComment;\n  };\n}\n\nexport function addCommentAction(inventoryComment: IInventoryComment): IAddComment {\n  return {\n    type: '/INVENTORIES/ADD_COMMENT',\n    payload: {\n      inventoryComment\n    }\n  };\n}\n\ninterface ICancelRequest {\n  type: '/INVENTORIES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/INVENTORIES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/INVENTORIES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/INVENTORIES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ILoadInventories {\n  type: '/INVENTORIES/LOAD_DATA';\n  payload: {\n    inventories: any[];\n    inventorySettings: any;\n    count: number;\n    pages: number;\n    page: number\n  };\n}\n\nexport function loadInventoriesAction(inventories: any[], inventorySettings: any, count: number, pages: number, page: number): ILoadInventories {\n  return {\n    type: '/INVENTORIES/LOAD_DATA',\n    payload: {\n      inventories,\n      inventorySettings,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function getInventoriesAction(loading: boolean, nextPage: number,) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (loading) {\n      window.scrollTo(0, 0);\n      dispatch(isLoadingAction(true));\n    }\n    const page = nextPage ? nextPage : state.inventories.pagination.page;\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getInventories(page)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadInventoriesAction(data.inventories, data.inventorySettings, data.count, data.pages, page));\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n      })\n      .catch((err: AxiosError) => {\n        if (loading) {\n          dispatch(isLoadingAction(false));\n        }\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function finishInventoryAction(id: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.finishInventory(id)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(getInventoriesAction(false, state.inventories.pagination.page) as any);\n        swal('Inventarios', data.message, 'success');\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteInventoryAction(id: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteInventory(id)\n      .then((response: AxiosResponse) => {\n        $(`#inventory-${id}`)\n          .addClass('deleted-item');\n        const data = response.data;\n        swal('Inventarios', data.message, 'success');\n        setTimeout(() => {\n          dispatch(getInventoriesAction(false, state.inventories.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ILoadingDetailInventory {\n  type: '/INVENTORIES/LOADING_INVENTORY_DETAIL';\n  payload: {\n    loadingDetail: boolean;\n  };\n}\n\nexport function loadingInventoryDetaillAction(loadingDetail: boolean): ILoadingDetailInventory {\n  return {\n    type: '/INVENTORIES/LOADING_INVENTORY_DETAIL',\n    payload: {\n      loadingDetail\n    }\n  };\n}\n\ninterface IFetchingDetailInventory {\n  type: '/INVENTORIES/FETCHING_INVENTORY_DETAIL';\n  payload: {\n    fetchingDetail: boolean;\n  };\n}\n\nexport function fetchingnventoryDetaillAction(fetchingDetail: boolean): IFetchingDetailInventory {\n  return {\n    type: '/INVENTORIES/FETCHING_INVENTORY_DETAIL',\n    payload: {\n      fetchingDetail\n    }\n  };\n}\n\ninterface IDetailInventorySelected {\n  type: '/INVENTORIES/CHANGE_SELECTED';\n  payload: {\n    item: string;\n  };\n}\n\nexport function inventoryDetailChangeSelected(item: string): IDetailInventorySelected {\n  return {\n    type: '/INVENTORIES/CHANGE_SELECTED',\n    payload: {\n      item\n    }\n  };\n}\n\ninterface IDetailChangeFilter {\n  type: '/INVENTORIES/CHANGE_FILTER';\n  payload: {\n    filter: IFilterCar\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function inventoryDetailChangeFilter(filter: IFilterCar): IDetailChangeFilter {\n  return {\n    type: '/INVENTORIES/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 0\n      }\n    }\n  };\n}\n\nexport function inventoryDetailChangeFilterText(filter: IFilterCar): IDetailChangeFilter {\n  return {\n    type: '/INVENTORIES/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\ninterface ILoadInventory {\n  type: '/INVENTORIES/LOAD_INVENTORY_DATA';\n  payload: {\n    summary: IInventorySummary;\n    inventorySettings: any;\n    detailByVenue: IDetailByVenue[];\n    detailByBrand: IDetailByBrand[];\n    labels: IInventoryLabel[],\n    detail: any;\n    resetFilter: boolean;\n  };\n}\n\nexport function loadInventoryAction(\n  summary: IInventorySummary,\n  inventorySettings: any,\n  detailByVenue: IDetailByVenue[],\n  detailByBrand: IDetailByBrand[],\n  labels: IInventoryLabel[],\n  detail: any,\n  resetFilter: boolean\n): ILoadInventory {\n  return {\n    type: '/INVENTORIES/LOAD_INVENTORY_DATA',\n    payload: {\n      resetFilter: !resetFilter,\n      summary,\n      inventorySettings,\n      detailByVenue,\n      detailByBrand,\n      labels,\n      detail\n    }\n  };\n}\n\nlet preventRepeatGetInventoryDetail: any;\nexport function getInventoryDetailAction(id: string, update: boolean) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => { inventories: IInventoryState }) => {\n    const state = getState();\n    if (state.inventories.fetchingDetail) {\n      clearTimeout(preventRepeatGetInventoryDetail);\n      preventRepeatGetInventoryDetail = setTimeout(() => (dispatch as any)(getInventoryDetailAction(id, update)), 1000);\n    } else {\n      dispatch(fetchingnventoryDetaillAction(true));\n      if (!update) {\n        dispatch(loadingInventoryDetaillAction(true));\n      }\n      const api: ApiService = new ApiService();\n      dispatch(cancelRequestAction(api.getSource()));\n      api.getInventory(id)\n        .then((response: AxiosResponse) => {\n          const {data} = response;\n          dispatch(loadInventoryAction(\n            data.summary,\n            data.inventorySettings,\n            data.detailByVenue,\n            data.detailByBrand,\n            data.labels,\n            data.detail,\n            update\n          ));\n          dispatch(fetchingnventoryDetaillAction(false));\n          dispatch(loadingInventoryDetaillAction(false));\n          if (!update) {\n            $('.count').each(function() {\n              $(this).prop('Counter', 0).animate({\n                Counter: $(this).text()\n              }, {\n                duration: 1500,\n                easing: 'swing',\n                step: function(now) {\n                  $(this).text(Math.ceil(now));\n                }\n              });\n            });\n          }\n        })\n        .catch((err: AxiosError) => {\n          console.log('err', err);\n          if (!Axios.isCancel(err)) {\n            api.errorHandler(err);\n          }\n          dispatch(loadingInventoryDetaillAction(false));\n          dispatch(fetchingnventoryDetaillAction(false));\n        });\n    }\n  };\n}\n\nexport function sendCommentAction(carId: string, comment: string) {\n  return (dispatch: Dispatch<InventoryReduxAction>, getState: () => {inventories: IInventoryState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.addComment(state.inventories.detail._id, carId, comment)\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function actionSetLabel(inventory: string, car: string, carID: string, label: IInventoryLabel) {\n  return (dispatch: Dispatch<InventoryReduxAction>) => {\n    const api: ApiService = new ApiService();\n    if (label.requireCustomText) {\n      (swal as any)('Agregar datos adicionales:', {\n        content: 'input'\n      }).then((custom: string) => {\n        if (custom && custom.trim().length) {\n          api.setLabel(inventory, car, carID, label._id, custom)\n            .then((response: AxiosResponse) => {\n              swal(response.data.message, {\n                icon: 'success'\n              });\n              setTimeout(() => {\n                (swal as any).close();\n              }, 1000);\n            })\n            .catch((err: AxiosError) => {\n              api.errorHandler(err);\n            });\n        } else {\n          swal('Operación cancelada', {\n            icon: 'error'\n          });\n        }\n      });\n    } else {\n      api.setLabel(inventory, car, carID, label._id)\n        .then((response: AxiosResponse) => {\n          swal(response.data.message, {\n            icon: 'success'\n          });\n          setTimeout(() => {\n            (swal as any).close();\n          }, 1500);\n        })\n        .catch((err: AxiosError) => {\n          api.errorHandler(err);\n        });\n    }\n  };\n}\n\nexport type InventoryReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadInventories |\n  ILoadInventory |\n  ILoadingDetailInventory |\n  IUpdateInventoryCar |\n  IAddComment |\n  IDetailChangeFilter |\n  IDetailInventorySelected |\n  IFetchingDetailInventory;\n","import { AxiosError, default as Axios } from 'axios';\nimport {Dispatch} from 'redux';\nimport {IFilterCar} from '../reducers/inventory.reducer';\nimport ApiService from '../utils/axios';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport interface IInventoryDashboardState {\n  venues: any[];\n  monthlyReport: any[];\n  inventorySettings: IInventorySetting;\n  filter: IFilterCar;\n  loading: boolean;\n}\n\ninterface ILoadInventoryDashboard {\n  type: '/INVENTORY_DASHBOARD/LOAD_DATA';\n  payload: {\n    venues: any[];\n    monthlyReport: any[];\n    inventorySettings: any;\n  };\n}\n\nexport function loadInventoriesDashboardAction(venues: any[], monthlyReport: any[], inventorySettings: any): ILoadInventoryDashboard {\n  return {\n    type: '/INVENTORY_DASHBOARD/LOAD_DATA',\n    payload: {\n      venues,\n      monthlyReport,\n      inventorySettings\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/INVENTORY_DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/INVENTORY_DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ILoadInventoryDashboardFiltered {\n  type: '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED';\n  payload: {\n    filter: IFilterCar;\n    monthlyReport: any[];\n    inventorySettings: any;\n  };\n}\n\nexport function loadInventoriesDashboardFilteredAction(filter: IFilterCar, monthlyReport: any[], inventorySettings: any): ILoadInventoryDashboardFiltered {\n  return {\n    type: '/INVENTORY_DASHBOARD/LOAD_DATA_FILTERED',\n    payload: {\n      filter,\n      monthlyReport,\n      inventorySettings\n    }\n  };\n}\n\nexport function getInventoryDashboard() {\n  return (dispatch: Dispatch<InventoryDashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingAction(true));\n    Axios.all([\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getInventoryDashboard()\n    ]).then(Axios.spread((venues, dashboard) => {\n      dispatch(loadInventoriesDashboardAction(venues.data.results, dashboard.data.data, dashboard.data.inventorySettings));\n    })).catch((err: AxiosError): void => {\n      api.errorHandler(err);\n    });\n  };\n}\n\nexport function getInventoryDashboardFiltered(filter: IFilterCar) {\n  return (dispatch: Dispatch<InventoryDashboardReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.getInventoryDashboard(filter)\n      .then((dashboard) => {\n        dispatch(loadInventoriesDashboardFilteredAction(filter, dashboard.data.data, dashboard.data.inventorySettings));\n      }).catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type InventoryDashboardReduxAction = ILoadInventoryDashboard | ILoadInventoryDashboardFiltered | IIsLoading;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IInventoryLabel\n} from '../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {IInventorySetting} from '../../../../../src/app/interfaces/teamSetting.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface ILabelsState {\n  labels: IInventoryLabel[];\n  inventorySettings: IInventorySetting;\n  loading: boolean;\n  tempLabel: IInventoryLabel;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/LABELS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/LABELS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/LABELS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/LABELS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/LABELS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/LABELS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempLabel {\n  type: '/LABELS/CHANGE_TEMP_LABEL';\n  payload: {\n    tempLabel: IInventoryLabel;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempLabelAction(tempLabel: IInventoryLabel, debounce?: number): IChangeTempLabel {\n  return {\n    type: '/LABELS/CHANGE_TEMP_LABEL',\n    payload: {\n      tempLabel\n    },\n    meta: {\n      debounce: {\n        time: debounce ? debounce : 0\n      }\n    }\n  };\n}\n\ninterface ICreateLabel {\n  type: '/LABELS/CREATE_LABEL';\n  payload: {\n    label: IInventoryLabel;\n  };\n}\n\nexport function createLabel(label: IInventoryLabel): ICreateLabel {\n  return {\n    type: '/LABELS/CREATE_LABEL',\n    payload: {\n      label\n    }\n  };\n}\n\nexport function createLabelAction(label: IInventoryLabel) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.createLabel(label)\n      .then((response: AxiosResponse) => {\n        showModal(false);\n        dispatch(createLabel(response.data.label));\n        statusFooterButttonsModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        const $label = $(`#label-${response.data.label._id}`);\n        $label.addClass('editing-item');\n        setTimeout(() => {\n          $label.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface ILoadLabels {\n  type: '/LABELS/LOAD_LABELS';\n  payload: {\n    labels: any;\n    inventorySettings: IInventorySetting;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadLabelsAction(labels: any, inventorySettings: IInventorySetting, count: number, pages: number): ILoadLabels {\n  return {\n    type: '/LABELS/LOAD_LABELS',\n    payload: {\n      labels,\n      inventorySettings,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getLabelsAction(nextPage: number) {\n  return (dispatch: Dispatch<LabelsReduxAction>, getState: () => {labels: ILabelsState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getLabels(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadLabelsAction(response.data.results, response.data.inventorySettings, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface IChangeLabel {\n  type: '/LABELS/CHANGE_LABEL';\n  payload: {\n    label: IInventoryLabel;\n  };\n}\n\nexport function changeLabel(label: IInventoryLabel): IChangeLabel {\n  return {\n    type: '/LABELS/CHANGE_LABEL',\n    payload: {\n      label\n    }\n  };\n}\n\nexport function changeLabelAction(label: IInventoryLabel, message?: boolean) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.updateLabel(label)\n      .then((response: AxiosResponse) => {\n        if (message) {\n          statusFooterButttonsModal(false);\n          showModal(false);\n          const $label = $(`#label-${label._id}`);\n          $label.addClass('editing-item');\n          setTimeout(() => {\n            $label.removeClass('editing-item');\n          }, 1000);\n          swal!(response.data.message, {\n            icon: 'success'\n          });\n        }\n        dispatch(changeLabel(label));\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\ninterface IDeleteLabel {\n  type: '/LABELS/DELETE_LABEL';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteLabelAction(id: string): IDeleteLabel {\n  return {\n    type: '/LABELS/DELETE_LABEL',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteLabelAction(id: string) {\n  return (dispatch: Dispatch<LabelsReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteLabel(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#label-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteLabelAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type LabelsReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadLabels |\n  IChangeTempLabel |\n  IChangeLabel |\n  IDeleteLabel |\n  ICreateLabel;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport ApiService from '../utils/axios';\nimport {\n  MILESTONE_IS_LOADING,\n  MILESTONE_CHANGE_ORDER,\n  MILESTONE_CANCEL_STATUS,\n  MILESTONE_LOAD_STATUS,\n  MILESTONE_CREATE_STATUS,\n  MILESTONE_UDPATE_STATUS,\n  MILESTONE_DELETE_STATUS,\n  ICreateMilestone,\n  ICancelMilestone,\n  IIsLoadingMilestone,\n  ILoadMilestone,\n  IUpdateMilestone,\n  IDeleteMilestone,\n  IChangeOrderMilestone,\n  IMilestoneState,\n  MilestoneReduxActions,\n  MILESTONE_LOAD_FORMS,\n  MILESTONE_LOAD_REQUEST_STATUS,\n  ILoadRequestStatusMilestone,\n  ILoadFormsMilestone, ILoadTypesMilestone, MILESTONE_LOAD_TYPES\n} from './milestone.types';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport function cancelMilestoneAction(source: CancelTokenSource): ICancelMilestone {\n  return {\n    type: MILESTONE_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingMilestoneAction(loading: boolean): IIsLoadingMilestone {\n  return {\n    type: MILESTONE_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadMilestoneAction(milestones: IMilestone[], count: number, pages: number, page: number): ILoadMilestone {\n  return {\n    type: MILESTONE_LOAD_STATUS,\n    payload: {\n      milestones,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function loadFormsMilestoneAction(forms: IForm[]): ILoadFormsMilestone {\n  return {\n    type: MILESTONE_LOAD_FORMS,\n    payload: {\n      forms\n    }\n  };\n}\n\nexport function loadTypesMilestoneAction(milestoneTypes: IMilestoneType[]): ILoadTypesMilestone {\n  return {\n    type: MILESTONE_LOAD_TYPES,\n    payload: {\n      milestoneTypes\n    }\n  };\n}\n\nexport function loadRequestStatusMilestoneAction(requestStatus: IRequestStatus[]): ILoadRequestStatusMilestone {\n  return {\n    type: MILESTONE_LOAD_REQUEST_STATUS,\n    payload: {\n      requestStatus\n    }\n  };\n}\n\n\nexport function createMilestoneAction(milestone: IMilestone): ICreateMilestone {\n  return {\n    type: MILESTONE_CREATE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\nexport function updateMilestoneAction(milestone: IMilestone): IUpdateMilestone {\n  return {\n    type: MILESTONE_UDPATE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\n\nexport function deleteMilestoneAction(milestone: IMilestone): IDeleteMilestone {\n  return {\n    type: MILESTONE_DELETE_STATUS,\n    payload: {\n      milestone\n    }\n  };\n}\n\nexport function changeOrderMilestoneAction(orderBy: string, orderType: string): IChangeOrderMilestone {\n  return {\n    type: MILESTONE_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getMilestonesThunkAction(milestoneType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<MilestoneReduxActions>, getState: () => { milestone: IMilestoneState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingMilestoneAction(!hideLoading));\n    const page = nextPage ? nextPage : state.milestone.pagination.page;\n    dispatch(changeOrderMilestoneAction(orderBy, orderType));\n    dispatch(cancelMilestoneAction(api.getSource()));\n    Axios\n      .all([\n        api.getMilestones({ milestoneType, page, orderBy, orderType }),\n        api.getMilestoneTypes({ page: 1, pageSize: 200 }),\n        api.getForms(1, 200),\n        api.getRequestItemsStatus({ page:1, pageSize: 200 })\n      ])\n      .then(Axios.spread((milestones, types, forms, requestStatus) => {\n        const { data } = milestones;\n        dispatch(loadMilestoneAction(data.results, data.count, data.pages, page));\n        dispatch(loadTypesMilestoneAction(types.data.results));\n        dispatch(loadFormsMilestoneAction(forms.data.results));\n        dispatch(loadRequestStatusMilestoneAction(requestStatus.data.results));\n        dispatch(isLoadingMilestoneAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingMilestoneAction(false));\n        api.errorHandler(err);\n      });\n  };\n\n}\n\n/*export function createMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneAction(idMilestone, data));\n      });\n  };\n}*/\n\nexport function updateMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        dispatch(updateMilestoneAction(response.data.data));\n      });\n  };\n}\n\n/*export function deleteMilestoneThunkAction(milestone: IMilestone) {\n  return (dispatch: Dispatch<MilestoneReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteMilestone(milestone)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateMilestoneAction(idMilestone, data));\n      });\n  };\n}*/\n","import { CancelTokenSource } from 'axios';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\n\nexport const MILESTONE_CANCEL_STATUS = '/MILESTONE/CANCEL_STATUS';\n