umber\n    page: number\n  };\n}\n\nexport interface ICreateOperationType {\n  type: typeof OPERATION_TYPE_CREATE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IUpdateOperationType {\n  type: typeof OPERATION_TYPE_UDPATE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IDeleteOperationType {\n  type: typeof OPERATION_TYPE_DELETE_STATUS;\n  payload: {\n    operationType: IOperationType\n  };\n}\n\nexport interface IChangeOrderOperationType {\n  type: typeof OPERATION_TYPE_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type OperationTypeReduxActions =\n  ICancelOperationType |\n  IIsLoadingOperationType |\n  ICreateOperationType |\n  IUpdateOperationType |\n  IDeleteOperationType |\n  IChangeOrderOperationType |\n  ILoadOperationType;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelPaymentMethod,\n  IChangeOrderPaymentMethod,\n  ICreatePaymentMethod,\n  IDeletePaymentMethod,\n  IIsLoadingPaymentMethod,\n  ILoadPaymentMethod,\n  IPaymentMethodState,\n  IUpdatePaymentMethod,\n  PAYMENT_METHOD_CANCEL,\n  PAYMENT_METHOD_CHANGE_ORDER,\n  PAYMENT_METHOD_CREATE,\n  PAYMENT_METHOD_DELETE,\n  PAYMENT_METHOD_IS_LOADING,\n  PAYMENT_METHOD_LOAD,\n  PAYMENT_METHOD_UDPATE,\n  PaymentMethodReduxActions\n} from './paymentMethod.types';\n\nexport function cancelPaymentMethodAction(source: CancelTokenSource): ICancelPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CANCEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingPaymentMethodAction(loading: boolean): IIsLoadingPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadPaymentMethodAction(paymentMethods: IPaymentMethod[], count: number, pages: number, page: number): ILoadPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_LOAD,\n    payload: {\n      paymentMethods,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createPaymentMethodItemAction(reason: IPaymentMethod): ICreatePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CREATE,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updatePaymentMethodItemAction(reason: IPaymentMethod): IUpdatePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_UDPATE,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deletePaymentMethodAction(reason: IPaymentMethod): IDeletePaymentMethod {\n  return {\n    type: PAYMENT_METHOD_DELETE,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderPaymentMethodAction(orderBy: string, orderType: string): IChangeOrderPaymentMethod {\n  return {\n    type: PAYMENT_METHOD_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getPaymentMethodThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>, getState: () => { paymentMethod: IPaymentMethodState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingPaymentMethodAction(!hideLoading));\n    const page = nextPage ? nextPage : state.paymentMethod.pagination.page;\n    dispatch(changeOrderPaymentMethodAction(orderBy, orderType));\n    dispatch(cancelPaymentMethodAction(api.getSource()));\n    Axios\n      .all([\n        api.getPaymentMethods({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((channels) => {\n        const { data } = channels;\n        dispatch(loadPaymentMethodAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingPaymentMethodAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingPaymentMethodAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createPaymentMethodThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createPaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n\nexport function updatePaymentMethodThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updatePaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n\nexport function deletePaymentMethodItemThunkAction(paymentMethod: IPaymentMethod) {\n  return (dispatch: Dispatch<PaymentMethodReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deletePaymentMethod(paymentMethod)\n      .then((response: AxiosResponse) => {\n        // dispatch(updatePaymentMethodItemAction(idPaymentMethod, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IPaymentMethod } from '../../../../../src/request/interfaces/paymentMethod.interface';\n\nexport const PAYMENT_METHOD_CANCEL = '/PAYMENT_METHOD/CANCEL';\nexport const PAYMENT_METHOD_IS_LOADING = '/PAYMENT_METHOD/IS_LOADING';\nexport const PAYMENT_METHOD_LOAD = '/PAYMENT_METHOD/LOAD';\nexport const PAYMENT_METHOD_CREATE = '/PAYMENT_METHOD/CREATE';\nexport const PAYMENT_METHOD_UDPATE = '/PAYMENT_METHOD/UDPATE';\nexport const PAYMENT_METHOD_DELETE = '/PAYMENT_METHOD/DELETE';\nexport const PAYMENT_METHOD_CHANGE_ORDER = '/PAYMENT_METHOD/CHANGE_ORDER';\n\nexport interface IPaymentMethodState {\n  paymentMethods: IPaymentMethod[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelPaymentMethod {\n  type: typeof PAYMENT_METHOD_CANCEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingPaymentMethod {\n  type: typeof PAYMENT_METHOD_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadPaymentMethod {\n  type: typeof PAYMENT_METHOD_LOAD;\n  payload: {\n    paymentMethods: IPaymentMethod[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreatePaymentMethod {\n  type: typeof PAYMENT_METHOD_CREATE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IUpdatePaymentMethod {\n  type: typeof PAYMENT_METHOD_UDPATE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IDeletePaymentMethod {\n  type: typeof PAYMENT_METHOD_DELETE;\n  payload: {\n    reason: IPaymentMethod\n  };\n}\n\nexport interface IChangeOrderPaymentMethod {\n  type: typeof PAYMENT_METHOD_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type PaymentMethodReduxActions =\n  ICancelPaymentMethod |\n  IIsLoadingPaymentMethod |\n  ICreatePaymentMethod |\n  IUpdatePaymentMethod |\n  IDeletePaymentMethod |\n  IChangeOrderPaymentMethod |\n  ILoadPaymentMethod;\n","import {AxiosError, AxiosResponse, CancelTokenSource, default as Axios} from \"axios\";\nimport {\n  IPlanning\n} from '../../../../../src/planning/interfaces/planning.interface';\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\n\nexport interface IPlanningState {\n  plannings: IPlanning[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/PLANNING/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/PLANNING/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/PLANNING/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/PLANNING/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/PLANNING/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/PLANNING/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface ILoadPlanning {\n  type: '/PLANNING/LOAD_PLANNING';\n  payload: {\n    plannings: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadPlanningAction(plannings: any, count: number, pages: number): ILoadPlanning {\n  return {\n    type: '/PLANNING/LOAD_PLANNING',\n    payload: {\n      plannings,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getPlanningAction(nextPage: number) {\n  return (dispatch: Dispatch<PlanningReduxAction>, getState: () => {labels: IPlanningState}) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if (nextPage && nextPage !== state.labels.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.labels.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getPlanning(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadPlanningAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport type PlanningReduxAction =\n  ILoadPlanning |\n  IChangePage |\n  IIsLoading |\n  ICancelRequest;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelReason,\n  IChangeOrderReason,\n  ICreateReason,\n  IDeleteReason,\n  IIsLoadingReason,\n  ILoadReasons,\n  IReasonsState,\n  IUpdateReason,\n  ReasonsReduxActions, REASON_CANCEL_REASON,\n  REASON_CHANGE_ORDER,\n  REASON_CREATE_REASON,\n  REASON_DELETE_REASON,\n  REASON_IS_LOADING,\n  REASON_LOAD_REASONS,\n  REASON_UDPATE_REASON\n} from './reasons.types';\n\nexport function cancelReasonAction(source: CancelTokenSource): ICancelReason {\n  return {\n    type: REASON_CANCEL_REASON,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingReasonAction(loading: boolean): IIsLoadingReason {\n  return {\n    type: REASON_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsAction(reasons: any[], count: number, pages: number, page: number): ILoadReasons {\n  return {\n    type: REASON_LOAD_REASONS,\n    payload: {\n      reasons,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createReasonItemAction(reason: IReason): ICreateReason {\n  return {\n    type: REASON_CREATE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateReasonItemAction(reason: IReason): IUpdateReason {\n  return {\n    type: REASON_UDPATE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function deleteReasonItemAction(reason: IReason): IDeleteReason {\n  return {\n    type: REASON_DELETE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function deleteReasonAction(reason: IReason): IDeleteReason {\n  return {\n    type: REASON_DELETE_REASON,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderReasonAction(orderBy: string, orderType: string): IChangeOrderReason {\n  return {\n    type: REASON_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getReasonsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<ReasonsReduxActions>, getState: () => { requests: IReasonsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingReasonAction(!hideLoading));\n    const page = nextPage ? nextPage : state.requests.pagination.page;\n    dispatch(changeOrderReasonAction(orderBy, orderType));\n    dispatch(cancelReasonAction(api.getSource()));\n    Axios\n      .all([\n        api.getReasons({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((reasons) => {\n        const { data } = reasons;\n        dispatch(loadReasonsAction(data.results, data.count, data.pages, page));\n        // dispatch(loadCarriersReasonAction(carriers.data.results));\n        dispatch(isLoadingReasonAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingReasonAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n\nexport function updateReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n\nexport function deleteReasonThunkAction(reason: IReason) {\n  return (dispatch: Dispatch<ReasonsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteReason(reason)\n      .then((response: AxiosResponse) => {\n        console.log('response', response);\n        // dispatch(updateReasonItemAction(idReason, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\n\nexport const REASON_CANCEL_REASON = '/REASONS/CANCEL_REASON';\nexport const REASON_IS_LOADING = '/REASONS/IS_LOADING';\nexport const REASON_LOAD_REASONS = '/REASONS/LOAD_REASONS';\nexport const REASON_CREATE_REASON = '/REASONS/CREATE_REASON';\nexport const REASON_UDPATE_REASON = '/REASONS/UDPATE_REASON';\nexport const REASON_DELETE_REASON = '/REASONS/DELETE_REASON';\nexport const REASON_CHANGE_ORDER = '/REASONS/CHANGE_ORDER';\n\nexport interface IReasonsState {\n  reasons: IReason[];\n  reason: Partial<IReason> | IReason;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelReason {\n  type: typeof REASON_CANCEL_REASON;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingReason {\n  type: typeof REASON_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasons {\n  type: typeof REASON_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateReason {\n  type: typeof REASON_CREATE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IUpdateReason {\n  type: typeof REASON_UDPATE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IDeleteReason {\n  type: typeof REASON_DELETE_REASON;\n  payload: {\n    reason: IReason\n  };\n}\n\nexport interface IChangeOrderReason {\n  type: typeof REASON_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type ReasonsReduxActions =\n  ICancelReason |\n  IIsLoadingReason |\n  ICreateReason |\n  IUpdateReason |\n  IDeleteReason |\n  IChangeOrderReason |\n  ILoadReasons;\n","import {\n  AxiosError,\n  AxiosResponse,\n  CancelTokenSource,\n  default as Axios\n} from 'axios';\nimport {\n  Dispatch\n} from 'redux';\nimport * as swal from 'sweetalert';\nimport {\n  IBaseRegion,\n  IRegion\n} from '../../../../../src/app/interfaces/region.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IRegionsState {\n  regions: IRegion[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  tempRegion: IBaseRegion;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/REGIONS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/REGIONS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/REGIONS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/REGIONS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/REGIONS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/REGIONS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeTempRegion {\n  type: '/REGIONS/CHANGE_TEMP_REGION';\n  payload: {\n    region: IBaseRegion;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempRegionAction(region: IBaseRegion, delay?: boolean): IChangeTempRegion {\n  return {\n    type: '/REGIONS/CHANGE_TEMP_REGION',\n    payload: {\n      region\n    },\n    meta: {\n      debounce: {\n        time: delay ? 300 : 0\n      }\n    }\n  };\n}\n\ninterface ILoadRegion {\n  type: '/REGIONS/LOAD_REGIONS';\n  payload: {\n    regions: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadRegionsAction(regions: any, count: number, pages: number): ILoadRegion {\n  return {\n    type: '/REGIONS/LOAD_REGIONS',\n    payload: {\n      regions,\n      count,\n      pages\n    }\n  };\n}\n\nexport function getRegionsAction(nextPage: number) {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => { regions: IRegionsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.regions.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.regions.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    api.getRegions(page)\n      .then((response: AxiosResponse) => {\n        dispatch(loadRegionsAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createRegionAction() {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempRegion} = state.regions;\n    const api: ApiService = new ApiService();\n    api.createRegion(tempRegion)\n      .then((response: AxiosResponse) => {\n        dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateRegionAction() {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    const state = getState();\n    const {tempRegion} = state.regions;\n    const $region = $(`#region-${tempRegion._id}`);\n    const api: ApiService = new ApiService();\n    api.updateRegion(tempRegion)\n      .then((response: AxiosResponse) => {\n        $region.addClass('editing-item');\n        dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $region.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteRegionAction(id: string) {\n  return (dispatch: Dispatch<RegionReduxAction>, getState: () => {regions: IRegionsState}) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api.deleteRegion(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        $(`#region-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getRegionsAction(state.regions.pagination.page) as any);\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type RegionReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangeTempRegion |\n  ILoadRegion |\n  IChangePage;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\nimport ApiService from '../utils/axios';\nimport { ICancelRequestChannel, IIsLoadingRequestChannel, ILoadRequestChannel, ICreateRequestChannel, IUpdateRequestChannel, IDeleteRequestChannel, IChangeOrderRequestChannel, RequestChannelReduxActions, ISalesChannelState } from './requestChannel.types';\nimport { REQUEST_CANCEL_CHANNEL,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CHANNEL,\n  REQUEST_CREATE_CHANNEL,\n  REQUEST_UDPATE_CHANNEL,\n  REQUEST_DELETE_CHANNEL,\n  REQUEST_CHANGE_ORDER\n} from './requestChannel.types';\n\nexport function cancelRequestChannelAction(source: CancelTokenSource): ICancelRequestChannel {\n  return {\n    type: REQUEST_CANCEL_CHANNEL,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestChannelAction(loading: boolean): IIsLoadingRequestChannel {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadRequestChannelAction(channels: ISalesChannel[], count: number, pages: number, page: number): ILoadRequestChannel {\n  return {\n    type: REQUEST_LOAD_CHANNEL,\n    payload: {\n      channels,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createRequestChannelItemAction(reason: ISalesChannel): ICreateRequestChannel {\n  return {\n    type: REQUEST_CREATE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateRequestChannelItemAction(reason: ISalesChannel): IUpdateRequestChannel {\n  return {\n    type: REQUEST_UDPATE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deleteRequestChannelAction(reason: ISalesChannel): IDeleteRequestChannel {\n  return {\n    type: REQUEST_DELETE_CHANNEL,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderRequestChannelAction(orderBy: string, orderType: string): IChangeOrderRequestChannel {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestChannelThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>, getState: () => { requestStatus: ISalesChannelState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestChannelAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requestStatus.pagination.page;\n    dispatch(changeOrderRequestChannelAction(orderBy, orderType));\n    dispatch(cancelRequestChannelAction(api.getSource()));\n    Axios\n      .all([\n        api.getSalesChannel({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((channels) => {\n        const { data } = channels;\n        dispatch(loadRequestChannelAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingRequestChannelAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestChannelAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createRequestChannelThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n\nexport function updateRequestChannelThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n\nexport function deleteRequestChannelItemThunkAction(requestStatus: ISalesChannel) {\n  return (dispatch: Dispatch<RequestChannelReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteSalesChannel(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestChannelItemAction(idRequestChannel, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\n\nexport const REQUEST_CANCEL_CHANNEL = '/REQUEST/CANCEL_CHANNEL';\nexport const REQUEST_IS_LOADING = '/REQUEST/IS_LOADING';\nexport const REQUEST_LOAD_CHANNEL = '/REQUEST/LOAD_CHANNEL';\nexport const REQUEST_CREATE_CHANNEL = '/REQUEST/CREATE_CHANNEL';\nexport const REQUEST_UDPATE_CHANNEL = '/REQUEST/UDPATE_CHANNEL';\nexport const REQUEST_DELETE_CHANNEL = '/REQUEST/DELETE_CHANNEL';\nexport const REQUEST_CHANGE_ORDER = '/REQUEST/CHANGE_ORDER';\n\nexport interface ISalesChannelState {\n  channels: ISalesChannel[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestChannel {\n  type: typeof REQUEST_CANCEL_CHANNEL;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestChannel {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestChannel {\n  type: typeof REQUEST_LOAD_CHANNEL;\n  payload: {\n    channels: ISalesChannel[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestChannel {\n  type: typeof REQUEST_CREATE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IUpdateRequestChannel {\n  type: typeof REQUEST_UDPATE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IDeleteRequestChannel {\n  type: typeof REQUEST_DELETE_CHANNEL;\n  payload: {\n    reason: ISalesChannel\n  };\n}\n\nexport interface IChangeOrderRequestChannel {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestChannelReduxActions =\n  ICancelRequestChannel |\n  IIsLoadingRequestChannel |\n  ICreateRequestChannel |\n  IUpdateRequestChannel |\n  IDeleteRequestChannel |\n  IChangeOrderRequestChannel |\n  ILoadRequestChannel;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport * as Rx from 'rxjs';\nimport { of } from 'rxjs';\nimport { ajax } from 'rxjs/ajax';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelRequestItems,\n  IChangeFilterRequestItems,\n  IChangeOrderRequestItems,\n  ICreateRequestItems,\n  IDeleteRequestItems,\n  IIsLoadingRequestItems,\n  ILoadCarriersRequestItems,\n  ILoadPropertiesRequestItems,\n  ILoadReasonsRequestItems,\n  ILoadRequestItems,\n  ILoadRequestItemStatus,\n  ILoadSettingsRequestItems,\n  ILoadVenuesRequestItems,\n  IRequestItemsFilters,\n  IRequestItemsState,\n  IUpdateRequestItems,\n  REQUEST_ITEMS_CANCEL_REQUEST,\n  REQUEST_ITEMS_CHANGE_FILTER,\n  REQUEST_ITEMS_CHANGE_ORDER,\n  REQUEST_ITEMS_CREATE_ITEM,\n  REQUEST_ITEMS_DELETE_ITEM,\n  REQUEST_ITEMS_IS_LOADING,\n  REQUEST_ITEMS_LOAD_CARRIERS,\n  REQUEST_ITEMS_LOAD_ITEM_STATUS,\n  REQUEST_ITEMS_LOAD_PROPERTIES,\n  REQUEST_ITEMS_LOAD_REASONS,\n  REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n  REQUEST_ITEMS_LOAD_SETTINGS, REQUEST_ITEMS_LOAD_USERS,\n  REQUEST_ITEMS_LOAD_VENUES,\n  REQUEST_ITEMS_UPDATE_ITEM,\n  RequestItemsReduxActions,\n  ILoadUsersRequestItems\n} from './requestItems.types';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { UserTypes } from '../../../../../src/app/models/user.model.types';\n\nexport function cancelRequestItemsAction(source: CancelTokenSource): ICancelRequestItems {\n  return {\n    type: REQUEST_ITEMS_CANCEL_REQUEST,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestItemsAction(loading: boolean): IIsLoadingRequestItems {\n  return {\n    type: REQUEST_ITEMS_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsRequestItemsAction(reasons: IReason[]): ILoadReasonsRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_REASONS,\n    payload: {\n      reasons\n    }\n  };\n}\n\n// export function loadCarriersRequestItemsAction(carriers: ICarrier[]): ILoadCarriersRequestItems {\n//   return {\n//     type: REQUEST_ITEMS_LOAD_CARRIERS,\n//     payload: {\n//       carriers\n//     }\n//   };\n// }\n\nexport function loadUsersRequestItemsAction(users: IUser[]): ILoadUsersRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_USERS,\n    payload: {\n      users\n    }\n  };\n}\n\nexport function loadVenuesRequestItemsAction(venues: IVenue[]): ILoadVenuesRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_VENUES,\n    payload: {\n      venues\n    }\n  };\n}\n\nexport function loadPropertiesRequestItemsAction(properties: ICarrier[]): ILoadPropertiesRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_PROPERTIES,\n    payload: {\n      properties\n    }\n  };\n}\n\nexport function loadRequestItemsStatusRequestAction(requestItemStatus: IRequestItemStatus[], min: number, max: number): ILoadRequestItemStatus {\n  return {\n    type: REQUEST_ITEMS_LOAD_ITEM_STATUS,\n    payload: {\n      requestItemStatus,\n      min,\n      max\n    }\n  };\n}\n\nexport function loadRequestsItemsAction(requestItems: IRequestItem[], count: number, pages: number, page: number): ILoadRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_REQUESTS_ITEMS,\n    payload: {\n      requestItems,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function changeOrderRequestAction(orderBy: string, orderType: string): IChangeOrderRequestItems {\n  return {\n    type: REQUEST_ITEMS_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function changeFilterRequestAction(key: keyof IRequestItemsFilters, value: any | any[]): IChangeFilterRequestItems {\n  return {\n    type: REQUEST_ITEMS_CHANGE_FILTER,\n    payload: {\n      key,\n      value\n    }\n  };\n}\n\nexport function createRequestItemAction(item: IRequestItem): ICreateRequestItems {\n  return {\n    type: REQUEST_ITEMS_CREATE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function updateRequestItemAction(item: IRequestItem): IUpdateRequestItems {\n  return {\n    type: REQUEST_ITEMS_UPDATE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemAction(item: IRequestItem): IDeleteRequestItems {\n  return {\n    type: REQUEST_ITEMS_DELETE_ITEM,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function loadRequestSettingsAction(requestSettings: IRequestSetting): ILoadSettingsRequestItems {\n  return {\n    type: REQUEST_ITEMS_LOAD_SETTINGS,\n    payload: {\n      requestSettings\n    }\n  };\n}\n\nexport function getRequestItemsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>, getState: () => { requestItems: IRequestItemsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    if(!hideLoading){\n      dispatch(isLoadingRequestItemsAction(true));\n    }\n    const page = nextPage ? nextPage : state.requestItems.pagination.page;\n    dispatch(changeOrderRequestAction(orderBy, orderType));\n    dispatch(cancelRequestItemsAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequestItems({ page, orderBy, orderType, pageSize: 25, filters: state.requestItems.filters }),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getVenues({ page: 1, pageSize: 200, noPopulate: true, filted: true }),\n        api.getUsers({ page: 1, search: '', type: UserTypes.common,  minified: true, limit: 200 }),\n        api.getProperties(),\n        api.getTeamSettings()\n      ])\n      .then(Axios.spread((requests, reasons, requestItemStatus/*, carriers*/, venues, users, properties, teamsettings) => {\n        const { data } = requests;\n        dispatch(loadRequestsItemsAction(data.results, data.count, data.pages, page));\n        dispatch(loadReasonsRequestItemsAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadUsersRequestItemsAction(users.data.results));\n        dispatch(loadVenuesRequestItemsAction(venues.data.results));\n        dispatch(loadPropertiesRequestItemsAction(properties.data));\n        dispatch(loadRequestSettingsAction(teamsettings.data.request));\n        dispatch(isLoadingRequestItemsAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestItemsAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nconst $updateRequestItem = new Rx.Subject<any>();\n\n$updateRequestItem.pipe(\n  debounceTime(2000),\n  switchMap((item: any) => {\n    return item ? ajax({\n      url: `/api/v1/requests-item/${item._id}/`,\n      headers: {\n        'Content-Type': 'application/json;charset=UTF-8'\n      },\n      method: 'PATCH',\n      body: item\n    }) : of();\n  })\n).subscribe();\nexport function updateRequestItemsThunkAction({ item, debounce }: { item: IRequestItem, debounce?: boolean}) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>) => {\n    dispatch(updateRequestItemAction(item));\n    if (debounce) {\n      // debounceUpdateRequestItem(item);\n      $updateRequestItem.next(item);\n    } else {\n      const api: ApiService = new ApiService();\n      $updateRequestItem.next(null);\n      api.updateRequestItem(item._id, item)\n        // tslint:disable-next-line: no-empty\n        .then((response: AxiosResponse) => {});\n    }\n  };\n}\n\nexport function deleteRequestItemsThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestItemsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItem(id)\n      // tslint:disable-next-line: no-empty\n      .then((response: AxiosResponse) => {});\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport const REQUEST_ITEMS_CANCEL_REQUEST = '/REQUESTS_ITEMS/CANCEL_REQUEST';\nexport const REQUEST_ITEMS_IS_LOADING = '/REQUESTS_ITEMS/IS_LOADING';\nexport const REQUEST_ITEMS_LOAD_REASONS = '/REQUESTS_ITEMS/LOAD_REASONS';\nexport const REQUEST_ITEMS_LOAD_CARRIERS = '/REQUESTS_ITEMS/LOAD_CARRIERS';\nexport const REQUEST_ITEMS_LOAD_VENUES = '/REQUESTS_ITEMS/LOAD_VENUES';\nexport const REQUEST_ITEMS_LOAD_USERS = '/REQUESTS_ITEMS/LOAD_USERS';\nexport const REQUEST_ITEMS_LOAD_PROPERTIES = '/REQUESTS_ITEMS/LOAD_PROPERTIES';\nexport const REQUEST_ITEMS_LOAD_REQUESTS_ITEMS = '/REQUESTS_ITEMS/LOAD_REQUESTS_ITEMS';\nexport const REQUEST_ITEMS_LOAD_ITEM_STATUS = '/REQUESTS_ITEMS/LOAD_ITEM_STATUS';\nexport const REQUEST_ITEMS_CHANGE_ORDER = '/REQUESTS_ITEMS/CHANGE_ORDER';\nexport const REQUEST_ITEMS_CHANGE_FILTER = '/REQUESTS_ITEMS/CHANGE_FILTER';\nexport const REQUEST_ITEMS_CREATE_ITEM = '/REQUESTS_ITEMS/CREATE_ITEM';\nexport const REQUEST_ITEMS_UPDATE_ITEM = '/REQUESTS_ITEMS/UPDATE_ITEM';\nexport const REQUEST_ITEMS_DELETE_ITEM = '/REQUESTS_ITEMS/DELETE_ITEM';\nexport const REQUEST_ITEMS_LOAD_SETTINGS = '/REQUESTS_ITEMS/LOAD_SETTINGS';\n\nexport interface IRequestItemsFilters {\n  text: string;\n  sellerText: string;\n  ticket: string;\n  conectaID: string;\n  request: string;\n  transmittal: string;\n  entry: string;\n  venues: any[];\n  users: any[];\n  properties: any[];\n  status: any[];\n  from: any;\n  to: any;\n}\n\nexport interface IRequestItemsState {\n  requestItems: IRequestItem[];\n  reasons: IReason[];\n  carriers: ICarrier[];\n  properties: ICarrier[];\n  venues: IVenue[];\n  users: IUser[];\n  requestItemStatus: IRequestItemStatus[];\n  requestSettings: IRequestSetting;\n  requestItemStatusMin: number;\n  requestItemStatusMax: number;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  filters: IRequestItemsFilters;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestItems {\n  type: typeof REQUEST_ITEMS_CANCEL_REQUEST;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestItems {\n  type: typeof REQUEST_ITEMS_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasonsRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n  };\n}\n\nexport interface ILoadCarriersRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_CARRIERS;\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport interface ILoadUsersRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_USERS;\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport interface ILoadVenuesRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_VENUES;\n  payload: {\n    venues: IVenue[];\n  };\n}\n\nexport interface ILoadPropertiesRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_PROPERTIES;\n  payload: {\n    properties: ICarrier[];\n  };\n}\n\nexport interface ILoadRequestItemStatus {\n  type: typeof REQUEST_ITEMS_LOAD_ITEM_STATUS;\n  payload: {\n    requestItemStatus: IRequestItemStatus[];\n    min: number;\n    max: number;\n  };\n}\n\nexport interface ILoadRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_REQUESTS_ITEMS;\n  payload: {\n    requestItems: IRequestItem[];\n    count: number;\n    pages: number;\n    page: number;\n  };\n}\n\nexport interface IChangeOrderRequestItems {\n  type: typeof REQUEST_ITEMS_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport interface IChangeFilterRequestItems {\n  type: typeof REQUEST_ITEMS_CHANGE_FILTER;\n  payload: {\n    key: keyof IRequestItemsFilters;\n    value: any | any[];\n  };\n}\n\nexport interface ICreateRequestItems {\n  type: typeof REQUEST_ITEMS_CREATE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface IUpdateRequestItems {\n  type: typeof REQUEST_ITEMS_UPDATE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface IDeleteRequestItems {\n  type: typeof REQUEST_ITEMS_DELETE_ITEM;\n  payload: {\n    item: IRequestItem;\n  };\n}\n\nexport interface ILoadSettingsRequestItems {\n  type: typeof REQUEST_ITEMS_LOAD_SETTINGS;\n  payload: {\n    requestSettings: IRequestSetting;\n  };\n}\n\nexport type RequestItemsReduxActions =\n  ICancelRequestItems |\n  ILoadReasonsRequestItems |\n  ILoadRequestItemStatus |\n  ILoadRequestItems |\n  ILoadCarriersRequestItems |\n  ILoadUsersRequestItems |\n  ILoadVenuesRequestItems |\n  ILoadPropertiesRequestItems |\n  IChangeOrderRequestItems |\n  IChangeFilterRequestItems |\n  ICreateRequestItems |\n  IUpdateRequestItems |\n  IDeleteRequestItems |\n  ILoadSettingsRequestItems |\n  IIsLoadingRequestItems;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\nimport ApiService from '../utils/axios';\nimport {\n  REQUEST_IS_LOADING,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CANCEL_STATUS,\n  REQUEST_LOAD_STATUS,\n  REQUEST_CREATE_STATUS,\n  REQUEST_UDPATE_STATUS,\n  REQUEST_DELETE_STATUS,\n  ICreateRequestStatus,\n  ICancelRequestStatus,\n  IIsLoadingRequestStatus,\n  ILoadRequestStatus,\n  IUpdateRequestStatus,\n  IDeleteRequestStatus,\n  IChangeOrderRequestStatus,\n  IRequestStatusState,\n  RequestStatusReduxActions\n} from './requestStatus.types';\n\nexport function cancelRequestStatusAction(source: CancelTokenSource): ICancelRequestStatus {\n  return {\n    type: REQUEST_CANCEL_STATUS,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestStatusAction(loading: boolean): IIsLoadingRequestStatus {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadRequestStatusAction(status: IRequestStatus[], count: number, pages: number, page: number): ILoadRequestStatus {\n  return {\n    type: REQUEST_LOAD_STATUS,\n    payload: {\n      status,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\n\nexport function createRequestStatusItemAction(reason: IRequestStatus): ICreateRequestStatus {\n  return {\n    type: REQUEST_CREATE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function updateRequestStatusItemAction(reason: IRequestStatus): IUpdateRequestStatus {\n  return {\n    type: REQUEST_UDPATE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\n\nexport function deleteRequestStatusAction(reason: IRequestStatus): IDeleteRequestStatus {\n  return {\n    type: REQUEST_DELETE_STATUS,\n    payload: {\n      reason\n    }\n  };\n}\n\nexport function changeOrderRequestStatusAction(orderBy: string, orderType: string): IChangeOrderRequestStatus {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestStatusThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>, getState: () => { requestStatus: IRequestStatusState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestStatusAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requestStatus.pagination.page;\n    dispatch(changeOrderRequestStatusAction(orderBy, orderType));\n    dispatch(cancelRequestStatusAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequestItemsStatus({ page, orderBy, orderType })\n      ])\n      .then(Axios.spread((status) => {\n        const { data } = status;\n        dispatch(loadRequestStatusAction(data.results, data.count, data.pages, page));\n        dispatch(isLoadingRequestStatusAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestStatusAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createRequestStatusThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.createRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n\nexport function updateRequestStatusThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n\nexport function deleteRequestStatusItemThunkAction(requestStatus: IRequestStatus) {\n  return (dispatch: Dispatch<RequestStatusReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItemsStatus(requestStatus)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestStatusItemAction(idRequestStatus, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { IRequestStatus } from '../../../../../src/request/interfaces/requestStatus.interface';\n\nexport const REQUEST_CANCEL_STATUS = '/REQUEST/CANCEL_STATUS';\nexport const REQUEST_IS_LOADING = '/REQUEST/IS_LOADING';\nexport const REQUEST_LOAD_STATUS = '/REQUEST/LOAD_STATUS';\nexport const REQUEST_CREATE_STATUS = '/REQUEST/CREATE_STATUS';\nexport const REQUEST_UDPATE_STATUS = '/REQUEST/UDPATE_STATUS';\nexport const REQUEST_DELETE_STATUS = '/REQUEST/DELETE_STATUS';\nexport const REQUEST_CHANGE_ORDER = '/REQUEST/CHANGE_ORDER';\n\nexport interface IRequestStatusState {\n  status: IRequestStatus[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequestStatus {\n  type: typeof REQUEST_CANCEL_STATUS;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequestStatus {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadRequestStatus {\n  type: typeof REQUEST_LOAD_STATUS;\n  payload: {\n    status: IRequestStatus[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestStatus {\n  type: typeof REQUEST_CREATE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IUpdateRequestStatus {\n  type: typeof REQUEST_UDPATE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IDeleteRequestStatus {\n  type: typeof REQUEST_DELETE_STATUS;\n  payload: {\n    reason: IRequestStatus\n  };\n}\n\nexport interface IChangeOrderRequestStatus {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestStatusReduxActions =\n  ICancelRequestStatus |\n  IIsLoadingRequestStatus |\n  ICreateRequestStatus |\n  IUpdateRequestStatus |\n  IDeleteRequestStatus |\n  IChangeOrderRequestStatus |\n  ILoadRequestStatus;\n","import Axios, { AxiosError, AxiosResponse, CancelTokenSource } from 'axios';\nimport { Dispatch } from 'redux';\nimport { debounce } from 'throttle-debounce';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport ApiService from '../utils/axios';\nimport {\n  ICancelRequest,\n  IChangeOrderRequest,\n  ICreateRequestItemInDetail,\n  ICreateRequestItemInList,\n  IDeleteRequestInList,\n  IDeleteRequestItemInDetail,\n  IDeleteRequestItemInList,\n  IIsLoadingRequest,\n  ILoadCarriersRequest,\n  ILoadSettingsRequest,\n  ILoadReasonsRequest,\n  ILoadRequest,\n  ILoadRequestItemStatus,\n  ILoadRequests,\n  IRequestsState,\n  ITabStatusRequest,\n  IUpdateRequestItemInDetail,\n  IUpdateRequestItemInList,\n  RequestsReduxActions,\n  REQUEST_CANCEL_REQUEST,\n  REQUEST_CHANGE_ORDER,\n  REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_DELETE_REQUEST_IN_LIST,\n  REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n  REQUEST_IS_LOADING,\n  REQUEST_LOAD_CARRIERS,\n  REQUEST_LOAD_REASONS,\n  REQUEST_LOAD_REQUEST,\n  REQUEST_LOAD_REQUESTS,\n  REQUEST_LOAD_REQUEST_ITEM_STATUS,\n  REQUEST_TAB_STATUS,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n  REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n  REQUEST_LOAD_SETTINGS, ILoadItemsRequest, REQUEST_LOAD_ITEMS\n} from './requests.types';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\n\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: REQUEST_CANCEL_REQUEST,\n    payload: {\n      source\n    }\n  };\n}\n\nexport function isLoadingRequestAction(loading: boolean): IIsLoadingRequest {\n  return {\n    type: REQUEST_IS_LOADING,\n    payload: {\n      loading\n    }\n  };\n}\n\nexport function loadReasonsRequestAction(reasons: IReason[]): ILoadReasonsRequest {\n  return {\n    type: REQUEST_LOAD_REASONS,\n    payload: {\n      reasons\n    }\n  };\n}\n\nexport function loadCarriersRequestAction(carriers: ICarrier[]): ILoadCarriersRequest {\n  return {\n    type: REQUEST_LOAD_CARRIERS,\n    payload: {\n      carriers\n    }\n  };\n}\n\nexport function loadRequestItemsStatusRequestAction(requestItemStatus: IRequestItemStatus[], min: number, max: number): ILoadRequestItemStatus {\n  return {\n    type: REQUEST_LOAD_REQUEST_ITEM_STATUS,\n    payload: {\n      requestItemStatus,\n      min,\n      max\n    }\n  };\n}\n\nexport function loadRequestItemsSettingsAction(requestSettings: IRequestSetting): ILoadSettingsRequest {\n  return {\n    type: REQUEST_LOAD_SETTINGS,\n    payload: {\n      requestSettings\n    }\n  };\n}\n\nexport function loadRequestsAction(requests: any[], count: number, pages: number, page: number): ILoadRequests {\n  return {\n    type: REQUEST_LOAD_REQUESTS,\n    payload: {\n      requests,\n      count,\n      pages,\n      page\n    }\n  };\n}\n\nexport function loadRequestAction(request: IRequest): ILoadRequest {\n  return {\n    type: REQUEST_LOAD_REQUEST,\n    payload: {\n      request\n    }\n  };\n}\n\nexport function createRequestItemActionInList(idRequest: string, item: IRequestItem): ICreateRequestItemInList {\n  return {\n    type: REQUEST_CREATE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      idRequest,\n      item\n    }\n  };\n}\n\nexport function updateRequestItemActionInList(request: string, item: IRequestItem): IUpdateRequestItemInList {\n  return {\n    type: REQUEST_UDPATE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      request,\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemActionInList(idRequest: string, item: IRequestItem): IDeleteRequestItemInList {\n  return {\n    type: REQUEST_DELETE_REQUEST_ITEM_IN_LIST,\n    payload: {\n      idRequest,\n      item\n    }\n  };\n}\n\nexport function createRequestItemActionInDetail(item: IRequestItem): ICreateRequestItemInDetail {\n  return {\n    type: REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function updateRequestItemActionInDetail(item: IRequestItem): IUpdateRequestItemInDetail {\n  return {\n    type: REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function deleteRequestItemActionInDetail(item: IRequestItem): IDeleteRequestItemInDetail {\n  return {\n    type: REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL,\n    payload: {\n      item\n    }\n  };\n}\n\nexport function changeTabStatusAction(request: string): ITabStatusRequest {\n  return {\n    type: REQUEST_TAB_STATUS,\n    payload: {\n      request\n    }\n  };\n}\n\nexport function loadItemsAction(request: string, items: any): ILoadItemsRequest {\n  return {\n    type: REQUEST_LOAD_ITEMS,\n    payload: {\n      request,\n      items\n    }\n  };\n}\n\nexport function tabStatusAction(request: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>, getState: () => { requests: IRequestsState }) => {\n    const state = getState();\n    const isOpen = state.requests.requestOpen.includes(request);\n    const hasItems = state.requests.requestItemsById.hasOwnProperty(request);\n    dispatch(changeTabStatusAction(request));\n    if (!isOpen && !hasItems) {\n      const api: ApiService = new ApiService();\n      api.getRequest(request)\n        .then((response: AxiosResponse) => {\n          dispatch(loadItemsAction(request, response.data.items));\n        });\n    }\n  };\n}\n\nexport function deleteRequestActionInList(id: string): IDeleteRequestInList {\n  return {\n    type: REQUEST_DELETE_REQUEST_IN_LIST,\n    payload: {\n      id\n    }\n  };\n}\n\nexport function changeOrderRequestAction(orderBy: string, orderType: string): IChangeOrderRequest {\n  return {\n    type: REQUEST_CHANGE_ORDER,\n    payload: {\n      orderBy,\n      orderType\n    }\n  };\n}\n\nexport function getRequestsThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) {\n  return (dispatch: Dispatch<RequestsReduxActions>, getState: () => { requests: IRequestsState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    dispatch(isLoadingRequestAction(hideLoading ? false : true));\n    const page = nextPage ? nextPage : state.requests.pagination.page;\n    dispatch(changeOrderRequestAction(orderBy, orderType));\n    dispatch(cancelRequestAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequests({page, orderBy, orderType}),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getTeamSettings()\n        // api.getCarriers(1, 200)\n      ])\n      .then(Axios.spread((requests, reasons, requestItemStatus, teamsettings /*, carriers*/) => {\n        const {data} = requests;\n        dispatch(loadRequestsAction(data.results, data.count, data.pages, page));\n        dispatch(loadReasonsRequestAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadRequestItemsSettingsAction(teamsettings.data.request));\n        // dispatch(loadCarriersRequestAction(carriers.data.results));\n        dispatch(isLoadingRequestAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getRequestThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    dispatch(isLoadingRequestAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    Axios\n      .all([\n        api.getRequest(id),\n        api.getReasons({ page: 1, pageSize: 200 }),\n        api.getRequestItemsStatus({ page: 1, pageSize: 200 }),\n        api.getTeamSettings()\n        // api.getCarriers(1, 200)\n      ])\n      .then(Axios.spread((request, reasons, requestItemStatus, teamsettings /*, carriers*/) => {\n        const { data } = request;\n        dispatch(loadRequestAction(data));\n        dispatch(loadReasonsRequestAction(reasons.data.results));\n        dispatch(loadRequestItemsStatusRequestAction(requestItemStatus.data.results, requestItemStatus.data.min, requestItemStatus.data.max));\n        dispatch(loadRequestItemsSettingsAction(teamsettings.data.request));\n        // dispatch(loadCarriersRequestAction(carriers.data.results));\n        dispatch(isLoadingRequestAction(false));\n      }))\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingRequestAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateRequestItemInListThunkAction(idRequest: string, item: IRequestItem) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.updateRequestItem(item._id, item)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n\nexport function deleteRequestItemThunkAction(item: IRequestItem) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequestItem(item._id)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n\nconst debounceUpdateRequestItem = debounce(500, (item) => {\n  const api: ApiService = new ApiService();\n  api.updateRequestItem(item._id, item)\n    // tslint:disable-next-line: no-empty\n    .then((response: AxiosResponse) => { });\n});\nexport function updateRequestItemInDetailThunkAction({ item, debounce }: { item: IRequestItem, debounce?: boolean}) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    dispatch(updateRequestItemActionInDetail(item));\n    if (debounce) {\n      debounceUpdateRequestItem(item);\n    } else {\n      const api: ApiService = new ApiService();\n      api.updateRequestItem(item._id, item)\n        // tslint:disable-next-line: no-empty\n        .then((response: AxiosResponse) => { });\n    }\n  };\n}\n\nexport function deleteRequestThunkAction(id: string) {\n  return (dispatch: Dispatch<RequestsReduxActions>) => {\n    const api: ApiService = new ApiService();\n    api.deleteRequest(id)\n      .then((response: AxiosResponse) => {\n        // dispatch(updateRequestItemActionInList(idRequest, data));\n      });\n  };\n}\n","import { CancelTokenSource } from 'axios';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { IRequestSetting } from '../../../../../src/app/interfaces/teamSetting.interface';\n\nexport const REQUEST_CANCEL_REQUEST = '/REQUESTS/CANCEL_REQUEST';\nexport const REQUEST_IS_LOADING = '/REQUESTS/IS_LOADING';\nexport const REQUEST_LOAD_SETTINGS = '/REQUESTS/REQUEST_LOAD_SETTINGS';\nexport const REQUEST_LOAD_REASONS = '/REQUESTS/LOAD_REASONS';\nexport const REQUEST_LOAD_REQUEST_ITEM_STATUS = '/REQUESTS/LOAD_REQUEST_ITEM_STATUS';\nexport const REQUEST_LOAD_CARRIERS = '/REQUESTS/LOAD_CARRIERS';\nexport const REQUEST_LOAD_REQUESTS = '/REQUESTS/LOAD_REQUESTS';\nexport const REQUEST_LOAD_REQUEST = '/REQUESTS/LOAD_REQUEST';\nexport const REQUEST_CREATE_REQUEST_ITEM_IN_LIST = '/REQUESTS/CREATE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_UDPATE_REQUEST_ITEM_IN_LIST = '/REQUESTS/UDPATE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_DELETE_REQUEST_ITEM_IN_LIST = '/REQUESTS/DELETE_REQUEST_ITEM_IN_LIST';\nexport const REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/UDPATE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/DELETE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL = '/REQUESTS/CREATE_REQUEST_ITEM_IN_DETAIL';\nexport const REQUEST_DELETE_REQUEST_IN_LIST = '/REQUESTS/DELETE_REQUEST_IN_LIST';\nexport const REQUEST_TAB_STATUS = '/REQUESTS/TAB_STATUS';\nexport const REQUEST_LOAD_ITEMS = '/REQUESTS/LOAD_ITEMS';\nexport const REQUEST_CHANGE_ORDER = '/REQUESTS/CHANGE_ORDER';\n\nexport interface IRequestsState {\n  requests: IRequest[];\n  requestItems: IRequestItem[];\n  reasons: IReason[];\n  carriers: ICarrier[];\n  requestOpen: string[];\n  requestItemsById: any;\n  requestItemStatus: IRequestItemStatus[];\n  requestItemStatusMin: number;\n  requestItemStatusMax: number;\n  request: Partial<IRequest> | IRequest;\n  loading: boolean;\n  source: CancelTokenSource | null;\n  requestSettings: IRequestSetting;\n  options: {\n    orderBy: string;\n    orderType: string;\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\nexport interface ICancelRequest {\n  type: typeof REQUEST_CANCEL_REQUEST;\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport interface IIsLoadingRequest {\n  type: typeof REQUEST_IS_LOADING;\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport interface ILoadReasonsRequest {\n  type: typeof REQUEST_LOAD_REASONS;\n  payload: {\n    reasons: IReason[];\n  };\n}\n\nexport interface ILoadRequestItemStatus {\n  type: typeof REQUEST_LOAD_REQUEST_ITEM_STATUS;\n  payload: {\n    requestItemStatus: IRequestItemStatus[];\n    min: number;\n    max: number;\n  };\n}\n\nexport interface ILoadSettingsRequest {\n  type: typeof REQUEST_LOAD_SETTINGS;\n  payload: {\n    requestSettings: IRequestSetting;\n  };\n}\n\nexport interface ILoadCarriersRequest {\n  type: typeof REQUEST_LOAD_CARRIERS;\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport interface ILoadRequests {\n  type: typeof REQUEST_LOAD_REQUESTS;\n  payload: {\n    requests: IRequest[];\n    count: number;\n    pages: number\n    page: number\n  };\n}\n\nexport interface ICreateRequestItemInList {\n  type: typeof REQUEST_CREATE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    idRequest: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IUpdateRequestItemInList {\n  type: typeof REQUEST_UDPATE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    request: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestItemInList {\n  type: typeof REQUEST_DELETE_REQUEST_ITEM_IN_LIST;\n  payload: {\n    idRequest: string;\n    item: IRequestItem\n  };\n}\n\nexport interface IUpdateRequestItemInDetail {\n  type: typeof REQUEST_UDPATE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface ICreateRequestItemInDetail {\n  type: typeof REQUEST_CREATE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestItemInDetail {\n  type: typeof REQUEST_DELETE_REQUEST_ITEM_IN_DETAIL;\n  payload: {\n    item: IRequestItem\n  };\n}\n\nexport interface IDeleteRequestInList {\n  type: typeof REQUEST_DELETE_REQUEST_IN_LIST;\n  payload: {\n    id: string;\n  };\n}\n\nexport interface ILoadRequest {\n  type: typeof REQUEST_LOAD_REQUEST;\n  payload: {\n    request: IRequest;\n  };\n}\n\nexport interface ITabStatusRequest {\n  type: typeof REQUEST_TAB_STATUS;\n  payload: {\n    request: string;\n  };\n}\n\nexport interface ILoadItemsRequest {\n  type: typeof REQUEST_LOAD_ITEMS;\n  payload: {\n    request: string;\n    items: any;\n  };\n}\n\nexport interface IChangeOrderRequest {\n  type: typeof REQUEST_CHANGE_ORDER;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\nexport type RequestsReduxActions =\n  ICancelRequest |\n  IIsLoadingRequest |\n  ILoadRequest |\n  ILoadItemsRequest |\n  ICreateRequestItemInList |\n  IUpdateRequestItemInList |\n  IDeleteRequestItemInList |\n  IDeleteRequestInList |\n  ILoadSettingsRequest |\n  ICreateRequestItemInDetail |\n  IUpdateRequestItemInDetail |\n  IDeleteRequestItemInDetail |\n  ILoadRequestItemStatus |\n  IChangeOrderRequest |\n  ILoadReasonsRequest |\n  ILoadCarriersRequest |\n  ITabStatusRequest |\n  ILoadRequests;\n","import { AxiosError, AxiosResponse } from 'axios';\nimport { Dispatch } from 'redux';\nimport ApiService from '../utils/axios';\nimport { StatsDashboardTypes } from '../../../../../src/stats/models/studio.types';\nimport { IStudio } from '../../../../../src/stats/interfaces/studio.interface';\nimport { ITeam } from '../../../../../src/app/interfaces/team.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport * as swal from 'sweetalert';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\n\nexport interface ITempStudio {\n  _id?: string;\n  name: string;\n  embedURL: string;\n  users: IUser[];\n  type: string;\n  team: ITeam | null\n}\n\n\nexport interface IStatsDashboardState {\n  loading: boolean;\n  studios: IStudio[];\n  tempStudio: ITempStudio;\n  currentStudio: IStudio | null;\n  users: IUser[];\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface IChangePage {\n  type: '/STATS_DASHBOARD/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/STATS_DASHBOARD/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/STATS_DASHBOARD/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/STATS_DASHBOARD/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\n\ninterface IChangeTempStudio {\n  type: '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO';\n  payload: {\n    tempStudio: ITempStudio;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempStudioAction(tempStudio: ITempStudio): IChangeTempStudio {\n  return {\n    type: '/STATS_DASHBOARD/CHANGE_TEMP_STUDIO',\n    payload: {\n      tempStudio\n    },\n    meta: {\n      debounce: {\n        time: 100\n      }\n    }\n  };\n}\n\n\ninterface ILoadStudios {\n  type: '/STATS_DASHBOARD/LOAD_STUDIOS';\n  payload: {\n    studios: IStudio[];\n  };\n}\n\n\nexport function loadStudiosAction(studios: IStudio[]): ILoadStudios {\n  return {\n    type: '/STATS_DASHBOARD/LOAD_STUDIOS',\n    payload: {\n      studios\n    }\n  };\n}\n\nexport function getMyStudiosAction(type? : StatsDashboardTypes) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getMyStudiosDashboards(type)\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudiosAction(response.data.studios));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getStudiosAction(type? : StatsDashboardTypes) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getStudiosDashboards(type)\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudiosAction(response.data.studios));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteStudio {\n  type: '/STATS_DASHBOARD/DELETE_USER';\n  payload: {\n    id: string;\n  };\n}\n\nexport function removeStudioAction(id: string): IDeleteStudio {\n  return {\n    type: '/STATS_DASHBOARD/DELETE_USER',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteStudioAction(id: string) {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteStudio(id)\n      .then((response: AxiosResponse): void => {\n        dispatch(removeStudioAction(id));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        // effect when removing user\n        $(`#studio-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(getStudiosAction() as any);\n        }, 1000);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface ILoadStudioUsers {\n  type: '/STATS_DASHBOARD/LOAD_STUDIOS_USERS';\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport function loadStudioUsers(users: IUser[]): ILoadStudioUsers {\n  return {\n    type: '/STATS_DASHBOARD/LOAD_STUDIOS_USERS',\n    payload: {\n      users\n    }\n  };\n}\n\nexport function loadStudioUsersAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api.getStudioUsers()\n      .then((response: AxiosResponse) => {\n        dispatch(loadStudioUsers(response.data.results));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createStudioAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>, getState: () => {statsDashboard: IStatsDashboardState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempStudio} = state.statsDashboard;\n    const api: ApiService = new ApiService();\n    api.createStudio(tempStudio)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getStudiosAction() as any);\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function editStudioAction() {\n  return (dispatch: Dispatch<StatsDashboardReducerAction>, getState: () => {statsDashboard: IStatsDashboardState}) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const {tempStudio} = state.statsDashboard;\n    const api: ApiService = new ApiService();\n    api.updateStudio(tempStudio)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getStudiosAction() as any);\n        $(`#studio-${tempStudio._id}`).addClass('editing-item');\n        swal(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $(`#studio-${tempStudio._id}`).removeClass('editing-item');\n          console.log(\"remove editing-item\");\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        console.log(err)\n        statusFooterButttonsModal(false);\n        $(`#studio-${tempStudio._id}`).removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\n\nexport type StatsDashboardReducerAction =\n  IIsLoading |\n  ILoadStudios |\n  IChangePage |\n  IChangeTempStudio |\n  IDeleteStudio |\n  ILoadStudioUsers;\n\n\n","import {AxiosError, AxiosResponse, CancelTokenSource} from \"axios\";\nimport {IInventoryCar, IInventory} from '../../../../../src/inventory/interfaces/inventory.interface';\nimport {Dispatch} from \"redux\";\nimport ApiService from \"../utils/axios\";\nimport { Options } from \"daterangepicker\";\nimport {IFilterStock} from \"../reducers/stock.reducer\";\n\nexport interface IStockState {\n  cars: any[];\n  carsTable: any[];\n  filter: IFilterStock;\n  dataFilters: {\n    venues: any[];\n    colors: any[];\n    brands: any[];\n    denominations: any[];\n    types: any[];\n    properties: any[];\n  };\n  defaultSorted: any[];\n  vinInStock: any;\n  searching: boolean;\n  message: string;\n  loading: boolean;\n  rangeOptions: Options;\n  source: CancelTokenSource | null;\n}\n\ninterface ICancelRequest {\n  type: '/STOCK/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/STOCK/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/STOCK/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/STOCK/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangeOrder {\n  type: '/STOCK/CHANGE_ORDER';\n  payload: {\n    order: any;\n  }\n}\n\nexport function changeOrder(order: any) {\n  return {\n    type: '/STOCK/CHANGE_ORDER',\n    payload: {\n      order\n    }\n  };\n}\n\ninterface ILoadStock {\n  type: '/STOCK/LOAD';\n  payload: {\n    inventories: IInventory[];\n    cars: IInventoryCar[];\n    message: string;\n  };\n}\n\nexport function loadStockAction(cars: IInventoryCar[], message: string, inventories: IInventory[]): ILoadStock {\n  return {\n    type: '/STOCK/LOAD',\n    payload: {\n      cars,\n      message,\n      inventories\n    }\n  };\n}\n\ninterface IChangeFilter {\n  type: '/STOCK/CHANGE_FILTER';\n  payload: {\n    filter: IFilterStock\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeFilterText(filter: IFilterStock): IChangeFilter {\n  return {\n    type: '/STOCK/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 300\n      }\n    }\n  };\n}\n\nexport function changeFilter(filter: IFilterStock): IChangeFilter {\n  return {\n    type: '/STOCK/CHANGE_FILTER',\n    payload: {\n      filter\n    },\n    meta: {\n      debounce: {\n        time: 0\n      }\n    }\n  };\n}\n\nexport function getStockAction() {\n  return (dispatch: Dispatch<StockReducerAction>) => {\n    // dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getStock()\n      .then((response: AxiosResponse) => {\n        dispatch(loadStockAction(response.data.cars, response.data.message, response.data.inventories));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type StockReducerAction =\n  ICancelRequest |\n  IChangeFilter |\n  IChangeOrder |\n  ILoadStock |\n  IIsLoading;\n","import {ITransmittal} from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport {\n  CANCEL_REQUEST_TRANSMITTAL,\n  CHANGE_ORDER_TRANSMITTAL,\n  CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  DELETE_TRANSMITTAL_TRANSMITTAL,\n  FILTER_REQUEST_ITEMS_TRANSMITTAL,\n  IRequestItemsFilters,\n  ITransmittalActionTypes,\n  ITransmittalState,\n  LOAD_CARRIERS_TRANSMITTAL,\n  LOAD_DRIVERS_TRANSMITTAL, LOAD_MILESTONE_TYPES_TRANSMITTAL,\n  LOAD_REQUEST_ITEMS_TRANSMITTAL,\n  LOAD_TRANSMITTAL,\n  LOAD_VENUES_TRANSMITTAL,\n  LOADING_REQUEST_ITEMS_TRANSMITTAL,\n  LOADING_TRANSMITTAL,\n  TOOGLE_TAB_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n  UPDATE_TRANSMITTAL_TRANSMITTAL,\n  TRANSPORT_MILESTONE_LOAD_STATUS, LOAD_TRANSMITTAL_RESUME,\n} from './transmittal.types';\nimport ApiService from \"../utils/axios\";\nimport Axios, {AxiosError, AxiosResponse, CancelTokenSource} from \"axios\";\nimport {ThunkDispatch} from \"redux-thunk\";\nimport {IVenue} from '../../../../../src/app/interfaces/venue.interface';\nimport {ICarrier} from '../../../../../src/app/interfaces/carrier.interface';\nimport {arrayPush, autofill, FormAction, submit} from \"redux-form\";\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport {IRequestItem} from '../../../../../src/request/interfaces/requestItem.interface';\nimport {ITransmittalItem} from '../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport {IMilestone} from \"../../../../../src/distribution/interfaces/milestone.interface\";\n\nexport default class TransmittalActions {\n  private api: ApiService;\n\n  public formName: string = 'transmittalForm';\n\n  constructor(\n    private dispatch: ThunkDispatch<{ transmittal: ITransmittalState }, {}, ITransmittalActionTypes | FormAction>\n  ) {\n    this.api = new ApiService();\n  }\n\n  public loadingAction(loading: boolean): void {\n    this.dispatch({\n      type: LOADING_TRANSMITTAL,\n      payload: {\n        loading\n      }\n    });\n  }\n\n  public loadAction(data: ITransmittal[], count: number, pages: number, page: number): void {\n    this.dispatch({\n      type: LOAD_TRANSMITTAL,\n      payload: {\n        data,\n        count,\n        pages,\n        page\n      }\n    });\n  }\n\n  public cancelRequestAction(source: CancelTokenSource): void {\n    this.dispatch({\n      type: CANCEL_REQUEST_TRANSMITTAL,\n      payload: {\n        source\n      }\n    });\n  }\n\n  public changeOrderAction(orderBy: string, orderType: string): void {\n    this.dispatch({\n      type: CHANGE_ORDER_TRANSMITTAL,\n      payload: {\n        orderBy,\n        orderType\n      }\n    });\n  }\n\n  public loadCarriers(carriers:  ICarrier[]): void {\n    this.dispatch({\n      type: LOAD_CARRIERS_TRANSMITTAL,\n      payload: {\n        carriers,\n      }\n    });\n  }\n\n  public loadDrivers(drivers: IUser[]): void {\n    this.dispatch({\n      type: LOAD_DRIVERS_TRANSMITTAL,\n      payload: {\n        drivers,\n      }\n    });\n  }\n\n  public loadMilestoneTypes(milestoneTypes: IMilestoneType[]): void {\n    this.dispatch({\n      type: LOAD_MILESTONE_TYPES_TRANSMITTAL,\n      payload: {\n        milestoneTypes,\n      }\n    });\n  }\n\n  public loadVenues(venues:  IVenue[]): void {\n    this.dispatch({\n      type: LOAD_VENUES_TRANSMITTAL,\n      payload: {\n        venues,\n      }\n    });\n  }\n\n  public toogleTab(transmittalId:  string, status?: boolean): void {\n    this.dispatch({\n      type: TOOGLE_TAB_TRANSMITTAL,\n      payload: {\n        transmittalId,\n        status\n      }\n    });\n  }\n\n  public submit(form: string) {\n    this.dispatch(submit(form));\n  }\n\n  public autofill(field: string, value: any) {\n    this.dispatch(\n      autofill(this.formName, field, value),\n    );\n  }\n\n  public pushItem(value: any) {\n    this.dispatch(\n      arrayPush(this.formName, 'items', value)\n    );\n  }\n\n  public updateTransmittalAction(transmittal: Partial<ITransmittal>){\n    this.dispatch({\n      type: UPDATE_TRANSMITTAL_TRANSMITTAL,\n      payload: {\n        transmittal\n      }\n    })\n  }\n\n  public updateTransmittalThunkAction(transmittal: any) {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      this.api.updateTransmittal(transmittal)\n        .then((response: AxiosResponse) => {\n          transmittalActions.updateTransmittalAction(response.data.data);\n        })\n        .catch((err: AxiosError) => {\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public deleteTransmittalAction(transmittal: Partial<ITransmittal>){\n    this.dispatch({\n      type: DELETE_TRANSMITTAL_TRANSMITTAL,\n      payload: {\n        transmittal\n      }\n    })\n  }\n\n  public deleteTransmittalItemAction(transmittalItem: Partial<ITransmittalItem>){\n    this.dispatch({\n      type: DELETE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public createTransmittalItemAction(transmittalItem: Partial<ITransmittal>){\n    this.dispatch({\n      type: CREATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public updateTransmittalItemAction(transmittalItem: Partial<ITransmittal>){\n    this.dispatch({\n      type: UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL,\n      payload: {\n        transmittalItem\n      }\n    })\n  }\n\n  public loadMilestoneAction(milestones: IMilestone[]): void {\n    this.dispatch( {\n      type: TRANSPORT_MILESTONE_LOAD_STATUS,\n      payload: {\n        milestones\n      }\n    });\n  }\n\n  public updateTransmittalItemThunkAction(transmitallItem: any) {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      this.api.updateTransmittalItem(transmitallItem)\n        .then((response: AxiosResponse) => {\n          transmittalActions.updateTransmittalItemAction(response.data.data);\n        })\n        .catch((err: AxiosError) => {\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public getFormBaseData(): void {\n    this.dispatch((dispatch) => {\n      const transmittalActions = new TransmittalActions(dispatch);\n      transmittalActions.loadingAction(true);\n      Axios\n        .all([\n          this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n          this.api.getCarriers(1, 200),\n          this.api.getDrivers(1, 200),\n          this.api.getMilestoneTypes({ page: 1, pageSize: 200 })\n        ])\n        .then(Axios.spread((venues, carriers, drivers,milestones) => {\n          transmittalActions.loadVenues(venues.data.results);\n          transmittalActions.loadCarriers(carriers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadMilestoneTypes(milestones.data.results);\n          transmittalActions.loadingAction(false);\n        }))\n        .catch((err: AxiosError): void => {\n          transmittalActions.loadingAction(false);\n          this.api.errorHandler(err);\n        });\n    })\n  }\n\n  public getTransmittalsThunkAction({\n  nextPage, orderBy, orderType, hideLoading, number, plate, drivers, types, from, to\n}:{\n    nextPage: number,\n    orderBy: string,\n    orderType: string,\n    number?: string,\n    hideLoading?: boolean,\n    plate?: string,\n    drivers?: string[],\n    types?: string[],\n    from: number,\n    to: number\n}): void {\n    this.dispatch((dispatch, getState) => {\n      const state = getState();\n      const transmittalActions = new TransmittalActions(dispatch);\n      const page = nextPage ? nextPage : state.transmittal.pagination.page;\n      transmittalActions.loadingAction(!hideLoading);\n      transmittalActions.changeOrderAction(orderBy, orderType);\n      transmittalActions.cancelRequestAction(this.api.getSource());\n      Axios\n        .all([\n          this.api.getTransmittals({page, orderBy, orderType, number, plate, drivers, types, from, to}),\n          this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n          this.api.getCarriers(1, 200),\n          this.api.getDrivers(1, 200),\n          this.api.getMilestoneTypes({ page: 1, pageSize: 200 }),\n          this.api.getMilestones({ page: 1, pageSize: 200 })\n        ])\n        .then(Axios.spread((transmittals,venues, carriers, drivers, milestoneTypes, milestones) => {\n          const {data} = transmittals;\n          transmittalActions.loadAction(data.results, data.count, data.pages, page);\n          transmittalActions.loadVenues(venues.data.results);\n          transmittalActions.loadCarriers(carriers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadDrivers(drivers.data.results);\n          transmittalActions.loadMilestoneTypes(milestoneTypes.data.results);\n          transmittalActions.loadMilestoneAction(milestones.data.results);\n          transmittalActions.loadingAction(false);\n        }))\n        .catch((err: AxiosError) => {\n          transmittalActions.loadingAction(false);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public loadingRequestItemAction(requestItemsLoading: boolean): void {\n    this.dispatch({\n      type: LOADING_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        requestItemsLoading,\n      }\n    });\n  }\n\n  public filterRequestItemAction(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    this.dispatch({\n      type: FILTER_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        key,\n        value\n      }\n    });\n  }\n\n  public loadRequestItemAction(requestItems: IRequestItem[], count: number, pages: number, page: number): void {\n    this.dispatch({\n      type: LOAD_REQUEST_ITEMS_TRANSMITTAL,\n      payload: {\n        requestItems,\n        count,\n        pages,\n        page\n      }\n    });\n  }\n\n  public getRequestItemThunkAction(nextPage: number, hideLoading?: boolean) {\n    this.dispatch((dispatch, getState) => {\n      const state = getState();\n      const transmittalActions = new TransmittalActions(dispatch);\n      const page = nextPage ? nextPage : state.transmittal.requestItemsPagination.page;\n      transmittalActions.loadingRequestItemAction(!hideLoading);\n      transmittalActions.cancelRequestAction(this.api.getSource());\n      this.api.getRequestItems({\n        page,\n        pageSize: 20,\n        orderBy: \"request.number\",\n        orderType: \"descending\",\n        filters: {\n          ...state.transmittal.requestItemsfilters,\n          transmitttalModule: true\n        },\n      })\n        .then((response: AxiosResponse) => {\n          const {data} = response;\n          transmittalActions.loadRequestItemAction(data.results, data.count, data.pages, page);\n          transmittalActions.loadingRequestItemAction(false);\n        })\n        .catch((err: AxiosError) => {\n          transmittalActions.loadingRequestItemAction(false);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n  public loadTransmittalResumeAction(resume: any[]): void{\n    this.dispatch({\n      type: LOAD_TRANSMITTAL_RESUME,\n      payload: {resume: resume}\n    })\n  }\n\n  public loadTransmittalResume(from: string, to: string): void {\n    this.dispatch((dispatch, getState) => {\n      const state = getState();\n      const transmittalActions = new TransmittalActions(dispatch);\n      transmittalActions.loadingAction(true);\n      this.api.getTransmittalResume(from, to).then((response: AxiosResponse) => {\n        transmittalActions.loadTransmittalResumeAction(response.data.data);\n        transmittalActions.loadingAction(false);\n      })\n        .catch((err: AxiosError) => {\n          transmittalActions.loadTransmittalResumeAction([]);\n          transmittalActions.loadingAction(false);\n          this.api.errorHandler(err);\n        });\n    });\n  }\n\n}\n","import { CancelTokenSource } from 'axios';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { ITransmittalItem } from '../../../../../src/distribution/interfaces/transmittalItem.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { IRequestItem } from '../../../../../src/request/interfaces/requestItem.interface';\nimport { ITransmittal } from '../../../../../src/distribution/interfaces/transmittal.interface';\nimport { IMilestoneType } from '../../../../../src/distribution/interfaces/milestoneType.interface';\nimport { IMilestone } from '../../../../../src/distribution/interfaces/milestone.interface';\n\n\nexport const LOADING_TRANSMITTAL = '@transmittal/IS_LOADING';\nexport const LOAD_TRANSMITTAL = '@transmittal/LOAD';\nexport const LOAD_TRANSMITTAL_RESUME = '@transmittal/LOAD_RESUME';\nexport const LOAD_VENUES_TRANSMITTAL = '@transmittal/LOAD_VENUES';\nexport const LOAD_CARRIERS_TRANSMITTAL = '@transmittal/LOAD_CARRIERS';\nexport const LOAD_DRIVERS_TRANSMITTAL = '@transmittal/LOAD_DRIVERS';\nexport const LOAD_MILESTONE_TYPES_TRANSMITTAL = '@transmittal/LOAD_MILESTONE_TYPES';\nexport const TOOGLE_TAB_TRANSMITTAL = '@transmittal/TOOGLE_TAB';\nexport const CHANGE_ORDER_TRANSMITTAL = '@transmittal/CHANGE_ORDER';\nexport const CANCEL_REQUEST_TRANSMITTAL = '@transmittal/CANCEL_REQUEST';\nexport const CREATE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/CREATE_TRANSMITTAL_ITEM';\nexport const UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/UPDATE_TRANSMITTAL_ITEM';\nexport const DELETE_TRANSMITTAL_ITEM_TRANSMITTAL = '@transmittal/DELETE_TRANSMITTAL_ITEM';\nexport const UPDATE_TRANSMITTAL_TRANSMITTAL = '@transmittal/UPDATE_TRANSMITTAL';\nexport const DELETE_TRANSMITTAL_TRANSMITTAL = '@transmittal/DELETE_TRANSMITTAL';\nexport const TRANSPORT_MILESTONE_LOAD_STATUS = '@transmittal/LOAD_MILESTONES';\n\n\nexport interface IPaginationListView {\n  count: number;\n  page: number;\n  pages: number;\n}\n\nexport interface IOrderListView {\n  orderType: string;\n  orderBy: string;\n}\n\nexport interface IListView<T = any> {\n  loading: boolean;\n  data: T[];\n  source: CancelTokenSource | null;\n  pagination: IPaginationListView;\n  options: IOrderListView;\n}\n\nexport interface IRequestItemsFilters {\n  text: string;\n  request: string;\n  entry: string;\n  venues: any[];\n  properties: any[];\n  status: any[];\n  from: any;\n  to: any;\n}\n\nexport interface ITransmittalState<T = ITransmittal> extends IListView<T> {\n  requestItemsLoading: boolean;\n  venues: IVenue[];\n  carriers: ICarrier[];\n  drivers: IUser[];\n  milestoneTypes: IMilestoneType[];\n  milestones: IMilestone[];\n  requestItems: IRequestItem[];\n  requestItemsfilters: IRequestItemsFilters;\n  requestItemsPagination: IPaginationListView;\n  transmittalOpen: string[];\n  resume: any[];\n}\n\nexport interface ITransmittalChangeOrderAction {\n  type: typeof CHANGE_ORDER_TRANSMITTAL;\n  payload: {\n    orderBy: string;\n    orderType: string;\n  };\n}\n\ninterface ITransmittalLoadingAction {\n  type: typeof LOADING_TRANSMITTAL;\n  payload: {\n    loading: boolean;\n  }\n}\n\ninterface ITransmittalCancerlRequestAction {\n  type: typeof CANCEL_REQUEST_TRANSMITTAL;\n  payload: {\n    source: CancelTokenSource;\n  }\n}\n\ninterface ITransmittalLoadMilestones {\n  type: typeof TRANSPORT_MILESTONE_LOAD_STATUS;\n  payload: {\n    milestones: IMilestone[];\n  }\n}\n\ninterface ITransmittalLoadAction {\n  type: typeof LOAD_TRANSMITTAL;\n  payload: {\n    data: ITransmittal[];\n    count: number;\n    pages: number;\n    page: number;\n  }\n}\n\ninterface ITransmittalLoadVenuesAction {\n  type: typeof LOAD_VENUES_TRANSMITTAL;\n  payload: {\n    venues: IVenue[];\n  }\n}\n\ninterface ITransmittalLoadCarriersAction {\n  type: typeof LOAD_CARRIERS_TRANSMITTAL;\n  payload: {\n    carriers: ICarrier[];\n  }\n}\n\ninterface ITransmittalLoadDriversAction {\n  type: typeof LOAD_DRIVERS_TRANSMITTAL;\n  payload: {\n    drivers: IUser[];\n  }\n}\n\ninterface ITransmittalLoadMilestoneTypesAction {\n  type: typeof LOAD_MILESTONE_TYPES_TRANSMITTAL;\n  payload: {\n    milestoneTypes: IMilestoneType[];\n  }\n}\n\ninterface ITransmittalToogleTabAction {\n  type: typeof TOOGLE_TAB_TRANSMITTAL;\n  payload: {\n    transmittalId: string;\n    status?: boolean;\n  }\n}\n\ninterface ICreateTransmittalItemAction {\n  type: typeof CREATE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItem>;\n  }\n}\n\ninterface IUpdateTransmittalItemAction {\n  type: typeof UPDATE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItem>;\n  }\n}\n\ninterface IDeleteTransmittalAction {\n  type: typeof DELETE_TRANSMITTAL_TRANSMITTAL;\n  payload: {\n    transmittal: Partial<ITransmittal>;\n  }\n}\n\ninterface IDeleteTransmittalItemAction {\n  type: typeof DELETE_TRANSMITTAL_ITEM_TRANSMITTAL;\n  payload: {\n    transmittalItem: Partial<ITransmittalItem>;\n  }\n}\n\ninterface IUpdateTransmittalAction {\n  type: typeof UPDATE_TRANSMITTAL_TRANSMITTAL;\n  payload: {\n    transmittal: Partial<ITransmittal>;\n  }\n}\n\n// SEARCH CARS IN REQUEST\nexport const LOAD_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/LOAD_REQUEST_ITEMS';\nexport const LOADING_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/LOADING_REQUEST_ITEMS';\nexport const FILTER_REQUEST_ITEMS_TRANSMITTAL = '@transmittal/FILTER_REQUEST_ITEMS';\n\nexport interface IChangeFilterRequestItemsTransmittalItemAction  {\n  type: typeof FILTER_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    key: keyof IRequestItemsFilters;\n    value: any | any[];\n  };\n}\n\nexport interface ILoadRequestItemsTransmittalItemAction  {\n  type: typeof LOAD_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    requestItems: IRequestItem[];\n    count: number;\n    pages: number\n    page: number;\n  };\n}\n\nexport interface ILoadingRequestItemsTransmittalItemAction  {\n  type: typeof LOADING_REQUEST_ITEMS_TRANSMITTAL;\n  payload: {\n    requestItemsLoading: boolean;\n  };\n}\n\nexport interface ILoadTransmittalResume {\n  type: typeof LOAD_TRANSMITTAL_RESUME;\n  payload: {\n    resume: any[]\n  }\n}\n\nexport type ITransmittalActionTypes =\n  ITransmittalCancerlRequestAction |\n  ITransmittalLoadVenuesAction |\n  ITransmittalLoadCarriersAction |\n  ITransmittalToogleTabAction |\n  ITransmittalChangeOrderAction |\n  ITransmittalLoadAction |\n  IUpdateTransmittalAction |\n  IDeleteTransmittalItemAction |\n  ICreateTransmittalItemAction |\n  IUpdateTransmittalItemAction |\n  IDeleteTransmittalAction |\n  ITransmittalLoadDriversAction |\n  ITransmittalLoadMilestoneTypesAction |\n  IChangeFilterRequestItemsTransmittalItemAction |\n  ILoadRequestItemsTransmittalItemAction |\n  ILoadingRequestItemsTransmittalItemAction |\n  ITransmittalLoadingAction |\n  ITransmittalLoadMilestones |\n  ILoadTransmittalResume;\n\n","import {\n  AxiosError,\n  AxiosResponse,\n  CancelTokenSource,\n  default as Axios\n} from 'axios';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { ICompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IForm } from '../../../../../src/form/interfaces/form.interface';\nimport { IPermission } from '../../../../../src/billing/interfaces/permission.interface';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\nimport { ISalesChannel } from '../../../../../src/request/interfaces/salesChannel.interface';\nimport { UserTypes } from '../../../../../src/app/models/user.model.types';\n\nexport interface IUsersState {\n  users: IUser[];\n  venues: IVenue[];\n  forms: IForm[];\n  channels: ISalesChannel[];\n  companies: ICompany[];\n  permissions: IPermission[];\n  loading: boolean;\n  tempUser: ITempUser;\n  source: CancelTokenSource | null;\n  searchText: string;\n  filters: {\n    venues: string[];\n  };\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/USERS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/USERS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/USERS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/USERS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/USERS/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/USERS/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IFilterVenues {\n  type: '/USERS/FILTER_VENUES';\n  payload: {\n    venues: string[];\n  };\n}\n\nexport function filterVenuesAction(venues: string[]): IFilterVenues {\n  return {\n    type: '/USERS/FILTER_VENUES',\n    payload: {\n      venues\n    }\n  };\n}\n\nexport function changeStatusUserAction(user: IUser) {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    const state = getState();\n    const api: ApiService = new ApiService();\n    api\n      .changeStatusUser(user._id, !user.active)\n      .then((response: AxiosResponse) => {\n          const $user = $(`#user-${user._id}`);\n          $user.addClass('editing-item');\n          dispatch(getUsersAction(state.users.pagination.page, UserTypes.common) as any)\n          setTimeout(() => {\n            $user.removeClass('editing-item');\n          }, 1000);\n          // swal!(response.data.message, {\n          //   icon: 'success'\n          // });\n\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport interface ITempUser {\n  _id?: string;\n  firstName?: string;\n  password?: string;\n  lastName?: string;\n  email?: string;\n  venue?: string | null;\n  venuesAccess: IVenue[];\n  userForms: IForm[];\n  settings: Dictionary<any>;\n  isAdmin: boolean;\n  isDriver: boolean;\n  preferred?: string | null;\n  userPermissions: IPermission[];\n  company: ICompany | null;\n}\n\ninterface IChangeTempUser {\n  type: '/USERS/CHANGE_TEMP_USER';\n  payload: {\n    user: ITempUser;\n  };\n  meta: {\n    debounce: {\n      time: number;\n    };\n  };\n}\n\nexport function changeTempUserAction(user: ITempUser): IChangeTempUser {\n  return {\n    type: '/USERS/CHANGE_TEMP_USER',\n    payload: {\n      user\n    },\n    meta: {\n      debounce: {\n        time: 100\n      }\n    }\n  };\n}\n\ninterface ILoadUsers {\n  type: '/USERS/LOAD_USERS';\n  payload: {\n    users: any;\n    count: number;\n    pages: number;\n  };\n}\n\nexport function loadUserAction(\n  users: any,\n  count: number,\n  pages: number\n): ILoadUsers {\n  return {\n    type: '/USERS/LOAD_USERS',\n    payload: {\n      users,\n      count,\n      pages\n    }\n  };\n}\n\ninterface IChangeUser {\n  type: '/USERS/CHANGE_USER';\n  payload: {\n    user: IUser;\n  };\n}\n\nexport function changeUserAction(user: IUser): IChangeUser {\n  return {\n    type: '/USERS/CHANGE_USER',\n    payload: {\n      user\n    }\n  };\n}\n\nexport function createUserAction() {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const { tempUser } = state.users;\n    const api: ApiService = new ApiService();\n    api\n      .createUser(tempUser)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getUsersAction(1, UserTypes.common) as any);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateUserAction() {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    // dispatch(isLoadingAction(true));\n    const state = getState();\n    const { tempUser } = state.users;\n    const api: ApiService = new ApiService();\n    api\n      .updateUser(tempUser)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(changeUserAction(response.data.user));\n        $(`#user-${tempUser._id}`).addClass('editing-item');\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $(`#user-${tempUser._id}`).removeClass('editing-item');\n        }, 1000);\n        dispatch(\n          getUsersAction(state.users.pagination.page, UserTypes.common) as any\n        );\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $(`#user-${tempUser._id}`).removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function createIntegrationAction(user: any) {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    api\n      .createIntegration(user)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(getUsersAction(1, UserTypes.integration) as any);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function updateIntegrationAction(user: any) {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    // dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    const state = getState();\n    api\n      .updateIntegration(user)\n      .then((response: AxiosResponse) => {\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(changeUserAction(response.data.user));\n        $(`#user-${user._id}`).addClass('editing-item');\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $(`#user-${user._id}`).removeClass('editing-item');\n        }, 1000);\n        dispatch(\n          getUsersAction(\n            state.users.pagination.page,\n            UserTypes.integration\n          ) as any\n        );\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $(`#user-${user._id}`).removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeSearchUser {\n  type: '/USERS/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchUserAction(searchText: string): IChangeSearchUser {\n  return {\n    type: '/USERS/CHANGE_SEARCH',\n    payload: {\n      searchText\n    }\n  };\n}\n\ninterface ILoadVenuesUser {\n  type: '/USERS/LOAD_VENUES';\n  payload: {\n    venues: IVenue[];\n  };\n}\n\nexport function loadVenuesUserAction(venues: IVenue[]): ILoadVenuesUser {\n  return {\n    type: '/USERS/LOAD_VENUES',\n    payload: {\n      venues\n    }\n  };\n}\n\ninterface ILoadPermissionsUser {\n  type: '/USERS/LOAD_PERMISSIONS';\n  payload: {\n    permissions: IPermission[];\n  };\n}\n\nexport function loadPermissionsUserAction(\n  permissions: IPermission[]\n): ILoadPermissionsUser {\n  return {\n    type: '/USERS/LOAD_PERMISSIONS',\n    payload: {\n      permissions\n    }\n  };\n}\n\ninterface ILoadFormsUser {\n  type: '/USERS/LOAD_FORMS';\n  payload: {\n    forms: IForm[];\n  };\n}\n\nexport function loadFormsUserAction(forms: IForm[]): ILoadFormsUser {\n  return {\n    type: '/USERS/LOAD_FORMS',\n    payload: {\n      forms\n    }\n  };\n}\n\ninterface ILoadCompaniesUser {\n  type: '/USERS/LOAD_COMPANIES';\n  payload: {\n    companies: ICompany[];\n  };\n}\n\nexport function loadCompaniesUserAction(\n  companies: ICompany[]\n): ILoadCompaniesUser {\n  return {\n    type: '/USERS/LOAD_COMPANIES',\n    payload: {\n      companies\n    }\n  };\n}\n\ninterface ILoadChannelsUser {\n  type: '/USERS/LOAD_CHANNELS';\n  payload: {\n    channels: ISalesChannel[];\n  };\n}\n\nexport function loadChannelsUserAction(\n  channels: ISalesChannel[]\n): ILoadChannelsUser {\n  return {\n    type: '/USERS/LOAD_CHANNELS',\n    payload: {\n      channels\n    }\n  };\n}\n\nexport function getUsersAction(\n  nextPage: number,\n  type: UserTypes,\n  search?: string\n) {\n  return (\n    dispatch: Dispatch<UserReduxAction>,\n    getState: () => { users: IUsersState }\n  ) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n\n    if (nextPage && nextPage !== state.users.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    // get venues and permissions\n\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.users.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    Axios.all([\n      api.getUsers({\n        page,\n        type,\n        venue: state.users.filters.venues.length\n          ? state.users.filters.venues[0]\n          : undefined,\n        search: state.users.searchText\n      }),\n      api.getCompanies(1, 200),\n      api.getVenues({ page: 1, pageSize: 200, noPopulate: false }),\n      api.getSalesChannel({ page: 1, pageSize: 200 }),\n      api.getPermissions(1, 200),\n      api.getForms(1, 200)\n    ])\n      .then(\n        Axios.spread(\n          (users, companies, venues, channeles, permissions, forms) => {\n            dispatch(\n              loadUserAction(\n                users.data.results,\n                users.data.count,\n                users.data.pages\n              )\n            );\n            dispatch(loadCompaniesUserAction(companies.data.results));\n            dispatch(loadChannelsUserAction(channeles.data.results));\n            dispatch(loadVenuesUserAction(venues.data.results));\n            dispatch(loadPermissionsUserAction(permissions.data.results));\n            dispatch(loadFormsUserAction(forms.data.results));\n            dispatch(isLoadingAction(false));\n          }\n        )\n      )\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n\n    // .then((response: AxiosResponse): void => {\n    //   dispatch(loadUserAction(response.data.results, response.data.count, response.data.pages));\n    //   dispatch(isLoadingAction(false));\n    // })\n    // .catch((err: AxiosError): void => {\n    //   // if the request is canceled\n    //   if (Axios.isCancel(err)) {\n    //     dispatch(isLoadingAction(true));\n    //   } else {\n    //     dispatch(isLoadingAction(false));\n    //     api.errorHandler(err);\n    //   }\n    // });\n  };\n}\n\ninterface IDeleteUser {\n  type: '/USERS/DELETE_USER';\n  payload: {\n    id: string;\n  };\n}\n\nexport function removeUserAction(id: string): IDeleteUser {\n  return {\n    type: '/USERS/DELETE_USER',\n    payload: {\n      id\n    }\n  };\n}\n\nexport function deleteUserAction(id: string) {\n  return (dispatch: Dispatch<UserReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api\n      .deleteUser(id)\n      .then((response: AxiosResponse): void => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        // effect when removing user\n        $(`#user-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(removeUserAction(id));\n        }, 1000);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function deleteIntegrationAction(id: string) {\n  return (dispatch: Dispatch<UserReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api\n      .deleteIntegration(id)\n      .then((response: AxiosResponse): void => {\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        // effect when removing user\n        $(`#user-${id}`).addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(removeUserAction(id));\n        }, 1000);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type UserReduxAction =\n  | IIsLoading\n  | ILoadUsers\n  | IFilterVenues\n  | IChangePage\n  | IDeleteUser\n  | IChangeSearchUser\n  | ICancelRequest\n  | IChangeTempUser\n  | ILoadChannelsUser\n  | IChangeUser\n  | ILoadVenuesUser\n  | ILoadPermissionsUser\n  | ILoadFormsUser\n  | ILoadCompaniesUser;\n","import { AxiosError, AxiosResponse, CancelTokenSource, default as Axios } from 'axios';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { ICarrier } from '../../../../../src/app/interfaces/carrier.interface';\nimport { ICompany } from '../../../../../src/app/interfaces/company.interface';\nimport { IRegion } from '../../../../../src/app/interfaces/region.interface';\nimport { IBaseVenue, IVenue } from '../../../../../src/app/interfaces/venue.interface';\nimport ApiService from '../utils/axios';\nimport { showModal, statusFooterButttonsModal } from '../utils/common';\nimport { IUser } from '../../../../../src/app/interfaces/user.interface';\nimport { UserTypes } from '../../../../../src/app/models/user.model.types';\nimport { Dictionary } from 'lodash';\n\nexport interface IVenuesState {\n  venues: IVenue[];\n  allVenues: IVenue[];\n  companies: ICompany[];\n  regions: IRegion[];\n  carriers: ICarrier[];\n  users: IUser[];\n  loading: boolean;\n  tempVenue: IBaseVenue;\n  source: CancelTokenSource | null;\n  searchText: string;\n  filters: Dictionary<string>\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/VENUES/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/VENUES/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/VENUES/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\n\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/VENUES/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface IChangePage {\n  type: '/VENUES/CHANGE_PAGE';\n  payload: {\n    page: number;\n  };\n}\n\nexport function changePageAction(page: number): IChangePage {\n  return {\n    type: '/VENUES/CHANGE_PAGE',\n    payload: {\n      page\n    }\n  };\n}\n\ninterface IChangeFilter {\n  type: '/VENUES/CHANGE_FILTER';\n  payload: {\n    filter: string;\n    value: string\n  };\n}\n\nexport function changeFilterAction(filter: string, value: string): IChangeFilter {\n  return {\n    type: '/VENUES/CHANGE_FILTER',\n    payload: {\n      filter,\n      value\n    }\n  };\n}\n\ninterface IChangeSearchVenue {\n  type: '/VENUES/CHANGE_SEARCH';\n  payload: {\n    searchText: string;\n  };\n}\n\nexport function changeSearchAction(searchText: string): IChangeSearchVenue {\n  return {\n    type: '/VENUES/CHANGE_SEARCH',\n    payload: {\n      searchText\n    }\n  };\n}\n\n\ninterface IChangeTempVenue {\n  type: '/VENUES/CHANGE_TEMP_VENUE';\n  payload: {\n    venue: IBaseVenue;\n  };\n  meta: {\n    debounce: {\n      time: number\n    }\n  };\n}\n\nexport function changeTempVenueAction(venue: IBaseVenue, noDelay?: boolean): IChangeTempVenue {\n  return {\n    type: '/VENUES/CHANGE_TEMP_VENUE',\n    payload: {\n      venue\n    },\n    meta: {\n      debounce: {\n        time: noDelay ? 0 : 300\n      }\n    }\n  };\n}\n\ninterface ILoadVenues {\n  type: '/VENUES/LOAD_VENUES';\n  payload: {\n    venues: any;\n    count: number;\n    pages: number\n  };\n}\n\nexport function loadVenuesAction(venues: any, count: number, pages: number): ILoadVenues {\n  return {\n    type: '/VENUES/LOAD_VENUES',\n    payload: {\n      venues,\n      count,\n      pages\n    }\n  };\n}\n\ninterface ILoadCompaniesVenue {\n  type: '/VENUES/LOAD_COMPANIES';\n  payload: {\n    companies: ICompany[];\n  };\n}\n\nexport function loadCompaniesVenueAction(companies: ICompany[]): ILoadCompaniesVenue {\n  return {\n    type: '/VENUES/LOAD_COMPANIES',\n    payload: {\n      companies\n    }\n  };\n}\n\ninterface ILoadAllVenue {\n  type: '/VENUES/LOAD_ALL_VENUES';\n  payload: {\n    allVenues: IVenue[];\n  };\n}\n\nexport function loadAllVenueAction(allVenues: IVenue[]): ILoadAllVenue {\n  return {\n    type: '/VENUES/LOAD_ALL_VENUES',\n    payload: {\n      allVenues\n    }\n  };\n}\n\ninterface ILoadCarriers {\n  type: '/VENUES/LOAD_CARRIERS';\n  payload: {\n    carriers: ICarrier[];\n  };\n}\n\nexport function loadCarriersAction(carriers: ICarrier[]): ILoadCarriers {\n  return {\n    type: '/VENUES/LOAD_CARRIERS',\n    payload: {\n      carriers\n    }\n  };\n}\n\ninterface ILoadRegions {\n  type: '/VENUES/LOAD_REGIONS';\n  payload: {\n    regions: IRegion[];\n  };\n}\n\nexport function loadRegionsAction(regions: IRegion[]): ILoadRegions {\n  return {\n    type: '/VENUES/LOAD_REGIONS',\n    payload: {\n      regions\n    }\n  };\n}\n\nexport function getVenuesAction(nextPage: number) {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    const api: ApiService = new ApiService();\n    const state = getState();\n    const { searchText, filters } = state.venues;\n    if (nextPage && nextPage !== state.venues.pagination.page) {\n      dispatch(isLoadingAction(true));\n    }\n    dispatch(cancelRequestAction(api.getSource()));\n    const page = nextPage ? nextPage : state.venues.pagination.page;\n    if (nextPage) {\n      dispatch(changePageAction(nextPage));\n    }\n    Axios.all([\n      api.getCompanies(1, 200),\n      api.getVenues({ page: 1, pageSize: 200 }),\n      api.getCarriers(1, 200),\n      api.getRegions(1, 200)\n    ])\n      .then(Axios.spread((companies: AxiosResponse, venues: AxiosResponse, carriers: AxiosResponse, regions: AxiosResponse) => {\n        dispatch(loadCompaniesVenueAction(companies.data.results));\n        dispatch(loadAllVenueAction(venues.data.results));\n        dispatch(loadCarriersAction(carriers.data.results));\n        dispatch(loadRegionsAction(regions.data.results));\n      }))\n      .catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n    api.getVenues({ page, search: searchText, company: filters.company })\n      .then((response: AxiosResponse) => {\n        dispatch(loadVenuesAction(response.data.results, response.data.count, response.data.pages));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        // if the request is canceled\n        if (Axios.isCancel(err)) {\n          dispatch(isLoadingAction(true));\n        } else {\n          dispatch(isLoadingAction(false));\n          api.errorHandler(err);\n        }\n      });\n  };\n}\n\nexport function createVenueAction() {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    dispatch(isLoadingAction(true));\n    const state = getState();\n    const { tempVenue } = state.venues;\n    const api: ApiService = new ApiService();\n    api.createVenue(tempVenue)\n      .then((response: AxiosResponse) => {\n        dispatch(getVenuesAction(state.venues.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IChangeVenue {\n  type: '/VENUES/CHANGE_VENUE';\n  payload: {\n    venue: IBaseVenue;\n  };\n}\n\nexport function changeVenueAction(venue: IBaseVenue): IChangeVenue {\n  return {\n    type: '/VENUES/CHANGE_VENUE',\n    payload: {\n      venue\n    }\n  };\n}\n\nexport function updateVenueAction() {\n  return (dispatch: Dispatch<VenueReduxAction>, getState: () => { venues: IVenuesState }) => {\n    const state = getState();\n    const { tempVenue, filters } = state.venues;\n    const $venue = $(`#venue-${tempVenue._id}`);\n    const api: ApiService = new ApiService();\n    api.updateVenue(tempVenue)\n      .then((response: AxiosResponse) => {\n        dispatch(changeVenueAction(response.data.venue));\n        dispatch(getVenuesAction(state.venues.pagination.page) as any);\n        statusFooterButttonsModal(false);\n        showModal(false);\n        $venue.addClass('editing-item');\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        setTimeout(() => {\n          $venue.removeClass('editing-item');\n        }, 1000);\n      })\n      .catch((err: AxiosError) => {\n        statusFooterButttonsModal(false);\n        $venue.removeClass('editing-item');\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\ninterface IDeleteVenue {\n  type: '/VENUES/DELETE_VENUE';\n  payload: {\n    id: string;\n  };\n}\n\nexport function processDeleteVenueAction(id: string): IDeleteVenue {\n  return {\n    type: '/VENUES/DELETE_VENUE',\n    payload: {\n      id\n    }\n  };\n}\n\ninterface ILoadUsers {\n  type: '/VENUES/LOAD_USERS';\n  payload: {\n    users: IUser[];\n  };\n}\n\nexport function loadUsers(users: IUser[]): ILoadUsers {\n  return {\n    type: '/VENUES/LOAD_USERS',\n    payload: {\n      users\n    }\n  };\n}\n\nexport function deleteVenueAction(id: string) {\n  return (dispatch: Dispatch<VenueReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.deleteVenue(id)\n      .then((response: AxiosResponse): void => {\n        // effect when removing user\n        swal!(response.data.message, {\n          icon: 'success'\n        });\n        $(`#venue-${id}`)\n          .addClass('deleted-item');\n        setTimeout(() => {\n          dispatch(processDeleteVenueAction(id));\n        }, 500);\n      })\n      .catch((err: AxiosError): void => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport function getVenueUsersAction(page: number, venue: IVenue) {\n  return (dispatch: Dispatch<VenueReduxAction>) => {\n    const api: ApiService = new ApiService();\n    api.getSource();\n    api.getUsers({\n      page,\n      type: UserTypes.common,\n      search: '',\n      venue: venue._id,\n      minified: true,\n      limit: 100\n    })\n      .then((response: AxiosResponse): void => {\n        dispatch(loadUsers(response.data.results));\n      })\n      .catch((err: any) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type VenueReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  IChangePage |\n  ILoadVenues |\n  IDeleteVenue |\n  IChangeSearchVenue |\n  IChangeTempVenue |\n  IChangeVenue |\n  IChangeFilter |\n  ILoadCompaniesVenue |\n  ILoadAllVenue |\n  ILoadCarriers |\n  ILoadRegions |\n  ILoadUsers;\n","import {AxiosError, AxiosResponse, CancelTokenSource} from 'axios';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../src/app/interfaces/alert.interface';\nimport {IVersion} from '../../../../../src/app/interfaces/version.interface';\nimport {IUser} from '../../../../../src/app/interfaces/user.interface';\nimport ApiService from '../utils/axios';\nimport {showModal, statusFooterButttonsModal} from '../utils/common';\n\nexport interface IVersionsState {\n  versions: IVersion[];\n  loading: boolean;\n  source: CancelTokenSource | null;\n  pagination: {\n    count: number;\n    page: number;\n    pages: number;\n  };\n}\n\ninterface ICancelRequest {\n  type: '/ALERTS/CANCEL_REQUEST';\n  payload: {\n    source: CancelTokenSource;\n  };\n}\n\nexport function cancelRequestAction(source: CancelTokenSource): ICancelRequest {\n  return {\n    type: '/ALERTS/CANCEL_REQUEST',\n    payload: {\n      source\n    }\n  };\n}\n\ninterface IIsLoading {\n  type: '/VERSIONS/IS_LOADING';\n  payload: {\n    loading: boolean;\n  };\n}\nexport function isLoadingAction(loading: boolean): IIsLoading {\n  return {\n    type: '/VERSIONS/IS_LOADING',\n    payload: {\n      loading\n    }\n  };\n}\n\ninterface ICreateVersion {\n  type: '/VERSIONS/CREATE';\n  payload: {\n    version: IVersion;\n  };\n}\n\nexport function createVersion(version: IVersion): ICreateVersion {\n  return {\n    type: '/VERSIONS/CREATE',\n    payload: {\n      version\n    }\n  };\n}\n\nexport function createVersionAction(version: any) {\n  return (dispatch: Dispatch<VersionReduxAction>) => {\n    dispatch(isLoadingAction(true));\n    const api: ApiService = new ApiService();\n    console.log(\"-- version\", version)\n    api.createVersion(version)\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        statusFooterButttonsModal(false);\n        showModal(false);\n        dispatch(createVersion(data.version));\n        dispatch(isLoadingAction(false));\n        swal(response.data.message, {\n          icon: 'success'\n        });\n      })\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n        dispatch(isLoadingAction(false));\n      });\n  };\n}\n\ninterface ILoadVersions {\n  type: '/VERSIONS/LOAD_DATA';\n  payload: {\n    versions: IVersion[]\n  };\n}\n\nexport function loadVersionsAction(versions: IVersion[]): ILoadVersions {\n  return {\n    type: '/VERSIONS/LOAD_DATA',\n    payload: {\n      versions\n    }\n  };\n}\n\nexport function getVersionsAction() {\n  return (dispatch: Dispatch<VersionReduxAction>) => {\n    const api: ApiService = new ApiService();\n    // dispatch(isLoadingAction(true));\n    dispatch(cancelRequestAction(api.getSource()));\n    api.getVersions()\n      .then((response: AxiosResponse) => {\n        const data = response.data;\n        dispatch(loadVersionsAction(data.versions));\n        dispatch(isLoadingAction(false));\n      })\n      .catch((err: AxiosError) => {\n        dispatch(isLoadingAction(false));\n        api.errorHandler(err);\n      });\n  };\n}\n\nexport type VersionReduxAction =\n  ICancelRequest |\n  IIsLoading |\n  ILoadVersions |\n  ICreateVersion;\n","import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {IUser} from '../../../../../../src/app/interfaces/user.interface';\n\ninterface IPropsType {\n  users: IUser[];\n  changeTempAlert: (tempAlert: ITempAlert) => void;\n}\n\ninterface ITempAlert {\n  name: string;\n  gte: number;\n  lte: number;\n  users: string[];\n  type: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempAlert: ITempAlert;\n  currentUser: string;\n}\n\nclass AlertFormView extends React.Component<IPropsType, IStateType> {\n\n  static propTypes = {\n    users: PropTypes.array.isRequired\n  };\n\n  readonly state = {\n    error: null,\n    currentUser: '',\n    tempAlert: {\n      name: '',\n      type: 'lte',\n      gte: 0,\n      lte: 0,\n      users: []\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.onChangeSelectUser = this.onChangeSelectUser.bind(this);\n    this.addUser = this.addUser.bind(this);\n    this.changeQualification = this.changeQualification.bind(this);\n    this.onChangeType = this.onChangeType.bind(this);\n    this.onChangeName = this.onChangeName.bind(this);\n    this.deleteUser = this.deleteUser.bind(this);\n  }\n\n  public componentDidMount() {\n    ($('#user-select') as any).chosen().change((e: React.ChangeEvent<HTMLSelectElement>) => {\n      this.onChangeSelectUser(e);\n      // console.log(e.target.value)\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  componentDidUpdate() {\n    $('#user-select').trigger('chosen:updated');\n    this.props.changeTempAlert(this.state.tempAlert);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { users } = this.props;\n    const { tempAlert } = this.state;\n    const usersToNotify = users.filter((user) => (tempAlert.users as string[]).includes(user._id));\n    return (\n      <div className={'row'}>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Nombre</label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={200}\n              onChange={this.onChangeName}\n            />\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\">\n            <label>Usuarios a notificar</label>\n            <select\n              id=\"user-select\"\n              className=\"chosen-select form-control\"\n              style={{minWidth: '200px'}}\n              onChange={this.onChangeSelectUser}\n              data-placeholder={'Seleccione usuarios'}\n            >\n              <option value=\"\" />\n              {\n                users.filter((user) => !(tempAlert.users as string[]).includes(user._id)).map((user) => {\n                  return (\n                    <option key={user._id} value={user._id}>{user.firstName} {user.lastName} {`<${user.email}>`}</option>\n                  );\n                })\n              }\n            </select>\n            {/*<span className=\"input-group-btn\">*/}\n              {/*<button className=\"btn btn-success\" onClick={this.addUser}>agregar</button>*/}\n            {/*</span>*/}\n          </div>\n        </div>\n        <div className=\"col-md-12\">\n          <table className=\"table table-striped\">\n            <thead>\n              <tr>\n                <th style={{width: '40%'}}>Nombre</th>\n                <th style={{width: '50%'}}>Email</th>\n                <th style={{width: '10%'}}/>\n              </tr>\n            </thead>\n            <tbody>\n            {\n              usersToNotify.length ? usersToNotify.map((user) => {\n                return (\n                  <tr key={user._id}>\n                    <td>{user.firstName} {user.lastName}</td>\n                    <td>{user.email}</td>\n                    <td className=\"text-center text-red pointer\" onClick={() => this.deleteUser(user._id)}><i className=\"fa fa-minus-circle\"/></td>\n                  </tr>\n                );\n                }) :\n              <tr>\n                <td colSpan={3}>Aún no se han seleccionado usuarios.</td>\n              </tr>\n            }\n            </tbody>\n          </table>\n        </div>\n        <div className=\"col-md-12\">\n          <div className=\"form-group\" style={{marginBottom: '0px'}}>\n            <label>Notificar cuando la calificación sea:</label>\n          </div>\n          <div>\n            <label className=\"radio-inline\">\n              <input type=\"radio\" value=\"lte\" checked={this.state.tempAlert.type === 'lte'} onChange={this.onChangeType}/>\n              Menor igual que\n            </label>\n            <label className=\"radio-inline\">\n              <input type=\"radio\" value=\"gte\" checked={this.state.tempAlert.type === 'gte'} onChange={this.onChangeType}/>\n              Mayor igual que\n            </label>\n            <input\n              type=\"text\"\n              className=\"form-control\"\n              maxLength={4}\n              onChange={this.changeQualification}\n              value={this.state.tempAlert.type === 'gte' ? this.state.tempAlert.gte : this.state.tempAlert.lte}\n              style={{marginTop: '10px'}}\n            />\n          </div>\n        </div>\n      </div>\n    );\n  }\n\n  private onChangeName(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        name: e.target.value.trim()\n      }\n    });\n  }\n\n  private changeQualification(e: React.ChangeEvent<HTMLInputElement>) {\n    const pattern = new RegExp(/[^\\d]/g);\n    const value = e.target.value.replace(pattern, '');\n    if (value && value.length) {\n      const numberValue = parseInt(value, 10);\n      this.setState({\n        tempAlert: {\n          ...this.state.tempAlert,\n          [this.state.tempAlert.type]: numberValue > 100 ? 100 : numberValue\n        }\n      });\n    } else {\n      this.setState({\n        tempAlert: {\n          ...this.state.tempAlert,\n          [this.state.tempAlert.type]: ''\n        }\n      });\n    }\n  }\n\n  private onChangeType(e: React.ChangeEvent<HTMLInputElement>) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        type: e.target.value,\n        gte: e.target.value === 'gte' ? this.state.tempAlert.lte : 0,\n        lte: e.target.value === 'gte' ? 0 : this.state.tempAlert.gte\n      }\n    });\n  }\n\n  private onChangeSelectUser(e: React.ChangeEvent<HTMLSelectElement>) {\n    if (e.target.value) {\n      this.setState({\n        currentUser: e.target.value\n      }, () => this.addUser());\n    }\n  }\n\n  private deleteUser(id: string) {\n    this.setState({\n      tempAlert: {\n        ...this.state.tempAlert,\n        users: this.state.tempAlert.users.filter((user) => id !== user)\n      }\n    });\n  }\n\n  private addUser() {\n    if (this.state.currentUser && this.state.currentUser.length) {\n      this.setState({\n        currentUser: '',\n        tempAlert: {\n          ...this.state.tempAlert,\n          users: [this.state.currentUser, ...this.state.tempAlert.users]\n        }\n      });\n    }\n  }\n}\n\nexport default AlertFormView;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IAlert} from '../../../../../../src/app/interfaces/alert.interface';\nimport {AlertReduxAction, createAlertAction, deleteAlertAction, getAlertsAction, IAlertsState} from '../../actions/alerts.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {statusFooterButttonsModal} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport AlertFormView from './AlertFormView';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  alerts: IAlertsState;\n  dispatch: Dispatch<AlertReduxAction>;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  getAlertsAction(): ModalReduxAction;\n\n  deleteAlertAction(id: string): ModalReduxAction;\n  createAlertAction(alert: ITempAlert): ModalReduxAction;\n}\n\ninterface ITempAlert {\n  name: string;\n  gte: number;\n  lte: number;\n  users: string[];\n  type: string;\n}\n\ninterface IStateType {\n  error: Error | null;\n  tempAlert: ITempAlert;\n}\n\nclass AlertViews extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   alerts: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    tempAlert: {\n      name: '',\n      type: 'gte',\n      gte: 0,\n      lte: 0,\n      users: []\n    }\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = ' Listado de alertas';\n    this.changeTempAlert = this.changeTempAlert.bind(this);\n\n    this.addAlert = this.addAlert.bind(this);\n    this.processAddAlert = this.processAddAlert.bind(this);\n\n    this.deleteAlert = this.deleteAlert.bind(this);\n  }\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    this.props.getAlertsAction();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.alerts.source) {\n      this.props.alerts.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {alerts, loading} = this.props.alerts;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Alertas <small>{alerts.length}</small></h3>\n              <div className=\"pull-right box-tools\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addAlert}>Agregar</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nombre</th>\n                    <th className=\"middle text-center\">Menor igual que</th>\n                    <th className=\"middle text-center\">Mayor igual que</th>\n                    <th style={{width: '40%'}} className=\"middle hidden-xs\">Usuarios</th>\n                    {/*<th className=\"width-10\" />*/}\n                    <th className=\"middle width-10\" />\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  alerts.length ?\n                    alerts.map((alert) => {\n                      return (\n                        <tr\n                          key={alert._id}\n                          id={`alert-${alert._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{alert.name}</td>\n                          <td className=\"middle text-center\">{alert.lte !== 0 ? alert.lte : '-'}</td>\n                          <td className=\"middle text-center\">{alert.gte !== 0 ? alert.gte : '-'}</td>\n                          <td className=\"hidden-xs\">\n                            {\n                              alert.users.map((user) => {\n                                return (\n                                  <p key={user._id} style={{margin: 0}}>{`${user.firstName} ${user.lastName} <${user.email}>`}</p>\n                                );\n                              })\n                            }\n                          </td>\n                          {/*<td className=\"text-blue pointer\" onClick={undefined}><i className=\"fa fa-pencil\"/></td>*/}\n                          <td className=\"text-red pointer\" onClick={() => this.deleteAlert(alert)}><i className=\"fa fa-minus-circle\"/></td>\n                        </tr>\n                      );\n                    }) : <tr>\n                      <td colSpan={5}>Aún no se han ingresado alertas</td>\n                    </tr>\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteAlert(alert: IAlert) {\n    // ask if you are sure that you are going to delete the alert?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la alerta ${alert.name}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteAlertAction(alert._id);\n      }\n    });\n  }\n\n  private addAlert() {\n    const {users} = this.props.alerts;\n    this.props.loadDataAction(\n      'Agregar Alerta',\n        <AlertFormView users={users} changeTempAlert={this.changeTempAlert} />\n      ,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-sm btn-primary\" onClick={this.processAddAlert}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private changeTempAlert(tempAlert: ITempAlert) {\n    this.setState({\n      tempAlert\n    });\n  }\n\n  private processAddAlert() {\n    const {tempAlert} = this.state;\n    const value = (tempAlert as any)[tempAlert.type];\n    if (tempAlert.name.trim().length === 0) {\n      swal('Agregar alerta', 'El campo nombre es requerido.', 'error');\n    } else if (tempAlert.users.length === 0) {\n      swal('Agregar alerta', 'Debe seleccionar al menos un usuario para notificar.', 'error');\n    } else if (!value || value === 0) {\n      swal('Agregar alerta', 'El valor para notificar debe ser entre 1 y 100.', 'error');\n    } else {\n      statusFooterButttonsModal(true);\n      this.props.createAlertAction(tempAlert);\n      // console.log('tempAlert', tempAlert);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { alerts: IAlertsState }) => {\n  return {\n    alerts: state.alerts\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getAlertsAction: () => dispatch(getAlertsAction()),\n    deleteAlertAction: (id: string) => dispatch(deleteAlertAction(id)),\n    createAlertAction: (alert: ITempAlert) => dispatch(createAlertAction(alert))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(AlertViews);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport {\n  BillingReduxAction,\n  getBillingAction,\n  IBillingState\n} from '../../actions/billing.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ }> {\n  dispatch: Dispatch<BillingReduxAction>;\n  billing: IBillingState;\n\n  getBillingAction(page: number): BillingReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass BillingListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Billing';\n    this.changePage = this.changePage.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.billing;\n    this.props.getBillingAction(pagination.page);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.billing.pagination !== prevProps.billing.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.billing.source) {\n      this.props.billing.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render() {\n    const {pagination, loading, invoices} = this.props.billing;\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.2\" cAction=\"Detalle\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Billing <small>{pagination.count}</small></h3>\n            </div>\n            <div className={`box-body ${invoices.length ? 'no-padding' : ''}`}>\n              {\n                !loading && !invoices.length?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <p>No se han encontrado resultados.</p>\n                    </div>\n                  </div>\n                  :null\n              }\n              {\n                invoices.length ?\n                  <table className=\"table\">\n                    <thead>\n                      <tr>\n                        <th className=\"middle\">Período</th>\n                        <th className=\"middle\">Empresa</th>\n                        <th className=\"middle hidden-xs\">Inventario</th>\n                        <th className=\"middle hidden-xs\">Entregas</th>\n                        <th className=\"middle hidden-xs\">Checklist</th>\n                        <th className=\"middle hidden-xs\">Solicitudes</th>\n                        <th className=\"middle\">Total</th>\n                        <th style={{width: '80px'}} />\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        invoices.map((invoice)=>(\n                          <tr key={invoice._id}>\n                            <td className=\"middle\">\n                              <strong className='text-info'>\n                                {\n                                  moment(invoice.createdAt).subtract(1, 'month').format('MMMM YYYY').toUpperCase()\n                                }\n                              </strong>\n                            </td>\n                            <td className=\"middle\">\n                              <strong className='text-primary'>{invoice.company.name}</strong> <br />\n                              <span className='text-sm text-muted'>\n                              {invoice.company?.businessName ?? ''} - {invoice.company?.rut ?? ''}\n                            </span>\n                            </td>\n                            <td className=\"middle text-muted hidden-xs\">{invoice.inventoryCars}</td>\n                            <td className=\"middle text-muted hidden-xs\">{invoice.deliveryCars}</td>\n                            <td className=\"middle text-muted hidden-xs\">{invoice.checklistCars}</td>\n                            <td className=\"middle text-muted hidden-xs\">{invoice.requestCars}</td>\n                            <td className=\"middle\">{invoice.totalUF.toFixed(2)} UF</td>\n                            <td className=\"middle\">\n                              <button\n                                className=\"btn btn-sm btn-primary\"\n                                onClick={()=>window.open(`/settings/billing/pdf/${invoice._id}`,'_blank')}\n                              >\n                                <i className=\"fa fa-fw fa-download\" /> Ver detalle\n                              </button>\n                            </td>\n                          </tr>\n                        ))\n                      }\n                    </tbody>\n                  </table>\n                  : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getBillingAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { billing: IBillingState }) => {\n  return {\n    billing: state.billing\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getBillingAction: (page: number) => dispatch(getBillingAction(page))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(BillingListView);\n","import * as React from 'react';\nimport ShowIf from '../Utils/ShowIf';\nimport { Link } from 'react-router-dom';\n\nconst BillingMenu: React.FunctionComponent<{}> = () => {\n  return (\n    <div className='list-group'>\n      {/*<ShowIf condition={window.user.isAdmin}>*/}\n      <Link to='/settings/billing-settings/' className='list-group-item active'>\n        Billing\n      </Link>\n      <Link to='/settings/billing-settings/' className='list-group-item disabled'>\n        Módulos\n      </Link>\n      <Link to='/settings/billing-settings/' className='list-group-item disabled'>\n        Submódulos\n      </Link>\n      <Link to='/settings/billing-settings/' className='list-group-item disabled'>\n        Permisos\n      </Link>\n      {/*</ShowIf>*/}\n    </div>\n  );\n};\n\nexport default BillingMenu;\n","import TrackingBasePage from '../../Utils/TrackingBasePage';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport BillingSettingsActions from '../../../actions/billingSettings.actions';\nimport { IBillingSettingsActionTypes, IBillingSettingsState } from '../../../actions/billingSettings.types';\nimport AppContainer from '../../../container/AppContainer';\nimport * as Raven from 'raven-js';\nimport ModalView from '../../Modal/ModalView';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\nimport * as moment from 'moment-timezone';\nimport ShowIf from '../../Utils/ShowIf';\nimport ApiService from '../../../utils/axios';\nimport BootstrapSelect from '../../Utils/BootstrapSelect';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<IBillingSettingsActionTypes>;\n  billingSettings: IBillingSettingsState;\n  billingSettingsActions: BillingSettingsActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass BillingCoporateListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  private api: ApiService;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Billing Corporativo';\n    this.api = new ApiService();\n    this.selectPeriod = this.selectPeriod.bind(this);\n    this.makeRangeMonths = this.makeRangeMonths.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { billingSettingsActions } = this.props;\n    billingSettingsActions.getInvoice({});\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.billingSettings.source) {\n      this.props.billingSettings.source.cancel('Operation canceled by the user.');\n    }\n    // this.socket.emit('leave', { room: `distribution-list-${window.user.team._id}` });\n    // this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, invoice } = this.props.billingSettings;\n    return (\n      <AppContainer title={''} cMenu='200' cSubMenu='200.4'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-12'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Billing {moment(`${invoice?.period}01`, 'YYYYMMDD').format('MMMM YYYY')}</h3>\n                  <div className='box-tools pull-right'>\n                    <button\n                      className='btn btn-default btn-sm'\n                      onClick={\n                        () => window.open(`/settings/billing/pdf-corporate/${invoice?._id}`, '_blank')\n                      }\n                    >\n                      PDF\n                    </button>\n                    <button\n                      className='btn btn-primary btn-sm'\n                      style={{ marginLeft: '5px' }}\n                      onClick={\n                        () => window.open(`/settings/billing/export/?period=${invoice?.period}`, '_blank')\n                      }\n                    >\n                      Exportar\n                    </button>\n                  </div>\n                </div>\n                <div className={`box-body`}>\n                  <div className='row'>\n                    <div className='col-md-12'>\n                      <div className={'pull-right'} style={{ width: '200px' }}>\n                        <BootstrapSelect\n                          noneSelectedText='Seleccione un periodo'\n                          displayItems={2}\n                          sm={true}\n                          selectedText='periodos seleccionadas.'\n                          selected={invoice?.period ? [invoice.period] : []}\n                          autoClouse={true}\n                          allOption={false}\n                          selectAll={() => ({})}\n                          options={this.makeRangeMonths()}\n                          onClick={this.selectPeriod}\n                        />\n                      </div>\n                    </div>\n                    <div className='col-md-6 text-right'>{}\n                    </div>\n                  </div>\n                  <div className='row'>\n                    <div className='col-md-5' style={{ padding: '15px' }}>\n                      <div style={{ fontSize: '120%' }}>Módulo Control de Stock</div>\n                      <ShowIf condition={!!(invoice && invoice.totalDolar <= invoice.teamBilling.baseCost)}>\n                        <div className='alert alert-danger' style={{ margin: '10px 0' }}>{invoice?.teamBilling.textBaseCost}</div>\n                      </ShowIf>\n                      <ShowIf condition={!!(invoice && invoice.totalDolar > invoice.teamBilling.baseCost)}>\n                        {\n                          invoice?.teamBilling.modules.map((module, index) => {\n                            const section = module.sections.find((section) => invoice.total >= section.start && invoice.total <= section.end);\n                            if (section) {\n                              return (\n                                <div key={index}>\n                                  <div className='alert alert-success'>{section?.text}</div>\n                                </div>\n                              );\n                            }\n                            return null;\n                          })\n                        }\n                      </ShowIf>\n                    </div>\n                    <div className='col-md-5' style={{ padding: '15px' }}>\n                      <div style={{ fontSize: '120%' }}>{new Intl.NumberFormat('de-DE').format(invoice?.total as number)} unidades controladas</div>\n                      <div>\n                        <ShowIf condition={!!(invoice && invoice.totalDolar > invoice.teamBilling.baseCost)}>\n                          {\n                            invoice?.teamBilling.modules.map((module, index) => {\n                              let totalInModule = invoice.total;\n                              return module.sections.sort((a: any, b: any) => {\n                                if (a.start < b.start) {\n                                  return -1;\n                                }\n                                if (a.start > b.start) {\n                                  return 1;\n                                }\n                                return 0;\n                              }).map((section) => {\n                                if (totalInModule > 0) {\n                                  const maxSection = (section.end - section.start) +1;\n                                  const totalInSection = totalInModule >= maxSection ? maxSection : totalInModule;\n                                  totalInModule = totalInModule - totalInSection;\n                                  return (\n                                    <div key={section._id} className={'text-muted'}>\n                                      {new Intl.NumberFormat('de-DE').format(totalInSection)} a {new Intl.NumberFormat('de-DE').format(section.price)} USD\n                                    </div>\n                                  );\n                                }\n                                return null;\n                              });\n                            })\n                          }\n                        </ShowIf>\n                      </div>\n                    </div>\n                    <div className='col-md-2 text-right' style={{ padding: '15px' }}>\n                      <div style={{ fontSize: '120%' }}>{new Intl.NumberFormat('de-DE').format(invoice?.totalDolar as number)} USD</div>\n                    </div>\n                    <div className='col-md-12'>\n                      <table className='table'>\n                        <thead>\n                        <tr>\n                          <th>Empresa</th>\n                          <th></th>\n                          <th></th>\n                        </tr>\n                        </thead>\n                        <tbody>\n                        {\n                          invoice?.companies.map((company, index) => (\n                            <tr key={index}>\n                              <td><strong>{company.company.name}</strong></td>\n                              <td>{new Intl.NumberFormat('de-DE').format(company.histories.length)} unidades únicas</td>\n                              <td></td>\n                            </tr>\n                          ))\n                        }\n                        </tbody>\n                      </table>\n                    </div>\n                  </div>\n                  {/*{JSON.stringify(invoice)}*/}\n                </div>\n                {/*<div className='box-footer text-right'>*/}\n                {/*</div>*/}\n                <ShowIf condition={loading}>\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private makeRangeMonths() {\n    const { oldest, last } = this.props.billingSettings;\n    const months = [];\n    const lastDate = moment(last).clone();\n    while (lastDate?.isSameOrAfter(oldest)) {\n      months.push({\n        value: lastDate.format('YYYYMM'),\n        text: lastDate.format('MMMM YYYY').toUpperCase()\n      });\n      lastDate?.subtract(1, 'month');\n    }\n    return months;\n  }\n\n  private selectPeriod(value: any): void {\n    const { billingSettingsActions } = this.props;\n    billingSettingsActions.getInvoice({ period: value });\n  }\n\n}\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState, router: any }) => {\n  return {\n    billingSettings: state.billingSettings,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const billingSettingsActions = new BillingSettingsActions(dispatch);\n  return {\n    dispatch,\n    billingSettingsActions,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(BillingCoporateListView);\n","import TrackingBasePage from '../../Utils/TrackingBasePage';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport BillingSettingsActions from '../../../actions/billingSettings.actions';\nimport {\n  IBillingSettingsActionTypes,\n  IBillingSettingsState\n} from '../../../actions/billingSettings.types';\nimport AppContainer from '../../../container/AppContainer';\nimport * as Raven from 'raven-js';\nimport BillingSettingsForm from './form/BillingSettingsForm';\nimport ModalView from '../../Modal/ModalView';\nimport { loadDataAction, ModalReduxAction } from '../../../actions/modal.actions';\nimport { IForm } from '../../../../../../../src/form/interfaces/form.interface';\nimport * as swal from 'sweetalert';\nimport ShowIf from '../../Utils/ShowIf';\nimport BillingMenu from '../BillingMenu';\nimport ApiService from '../../../utils/axios';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  router: any;\n  dispatch: Dispatch<IBillingSettingsActionTypes>;\n  billingSettings: IBillingSettingsState;\n  billingSettingsActions: BillingSettingsActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass BillingSettingsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  private api: ApiService;\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Configuración de Billing';\n    this.processUpdateSettings = this.processUpdateSettings.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    const { billingSettingsActions } = this.props;\n    billingSettingsActions.getTeamSettings();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.billingSettings.source) {\n      this.props.billingSettings.source.cancel('Operation canceled by the user.');\n    }\n    // this.socket.emit('leave', { room: `distribution-list-${window.user.team._id}` });\n    // this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { billingSettingsActions } = this.props;\n    const { loading, modules, billingSettings } = this.props.billingSettings;\n    return (\n      <AppContainer title={''} cMenu='200' cSubMenu='200.21'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <BillingMenu />\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Configuración de Billing</h3>\n                </div>\n                <div className={`box-body`}>\n                  <ShowIf condition={!loading}>\n                    <BillingSettingsForm\n                      initialValues={{\n                        name: 'default',\n                        businessName : '',\n                        notifications:[{\n                          name: 'Soporte',\n                          email: 'soporte@osacontrol.com',\n                        }],\n                        ...billingSettings,\n                        modules : modules.map((module) => {\n                          const moduleSetting = billingSettings?.modules.find((m) => {\n                            return m.module === module._id;\n                          });\n                          if(moduleSetting){\n                            return {\n                              ...moduleSetting,\n                              ...module,\n                            }\n                          }\n                          return {\n                            ...module,\n                          }\n                        })\n                      }}\n                      onSubmit={this.processUpdateSettings}\n                    />\n                  </ShowIf>\n                </div>\n                <div className='box-footer text-right'>\n                  <button\n                    className='btn btn-sm btn-primary'\n                    style={{ marginLeft: '5px' }}\n                    onClick={() => billingSettingsActions.submit('billingSettingsForm')}\n                    // disabled={sending}\n                  >\n                    Actualizar\n                    {/*<ShowIf condition={sending} alternative={'Actualizar'}>*/}\n                    {/*  <React.Fragment>*/}\n                    {/*    <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...*/}\n                    {/*  </React.Fragment>*/}\n                    {/*</ShowIf>*/}\n                  </button>\n                </div>\n                <ShowIf condition={loading}>\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private processUpdateSettings(form: any): void {\n    this.api.updateBillingByCorporate({\n      ...form,\n      modules: form.modules.map((module: any) => {\n        return {\n          ...module,\n          module: module._id\n        }\n      })\n    }).then((response: any) => {\n      console.log(response);\n    });\n  }\n\n  private deleteForm(form: IForm): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el formulario: ${form.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        // this.props.deleteFormThunkAction(form);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState, router: any }) => {\n  return {\n    billingSettings: state.billingSettings,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const billingSettingsActions = new BillingSettingsActions(dispatch);\n  return {\n    dispatch,\n    billingSettingsActions,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(BillingSettingsListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { autofill, Field, FieldArray, formValueSelector, getFormValues, InjectedFormProps, reduxForm } from 'redux-form';\n\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { IBillingSettingsState } from '../../../../actions/billingSettings.types';\nimport BillingNotificationRender, { IBillingSettinsNotificationRenderItemProps } from './renders/BillingSettingsNotificationRender';\nimport BillingModuleRender, { IBillingSettinsModuleRenderItemProps } from './renders/BillingSettingsModuleRender';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport BillingSettingsActions from '../../../../actions/billingSettings.actions';\nimport JsonFormatter from 'react-json-formatter';\nimport ShowIf from '../../../Utils/ShowIf';\n\n\ninterface IPropsType extends InjectedFormProps {\n  formValues: any;\n  update: boolean;\n  billingSettings: IBillingSettingsState;\n  billingSettingsActions: BillingSettingsActions;\n}\n\ninterface IStateType {\n  change: boolean;\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed, billingSettings, billingSettingsActions, formValues } = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className='row'>\n          {/*<div className='col-md-12 form-group-no-margin'>\n            <Field\n              name='name'\n              label='Nombre *'\n              placeholder='Nombre'\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>*/}\n          <div className='col-md-12 form-group-no-margin'>\n            <Field\n              name='businessName'\n              label='Razón social *'\n              placeholder='Razón social'\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-12 form-group-no-margin'>\n            <Field\n              name='rut'\n              label='RUT *'\n              placeholder='RUT'\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-12 form-group-no-margin'>\n            <Field\n              name='baseCost'\n              label='Costo Base'\n              type='number'\n              component={InputField}\n            />\n          </div>\n          <div className='col-md-12 form-group-no-margin'>\n            <Field\n              name='textBaseCost'\n              label='Texto Costo Base'\n              type='text'\n              component={InputField}\n            />\n          </div>\n          <div className='col-md-12 form-group-no-margin'>\n            <Field\n            name={`companies`}\n            label='Empresas *'\n            component={BootstrapSelectField}\n            validate={[inputStringRequired]}\n            props={{\n              noneSelectedText: 'Seleccione empresas',\n              selectedText: 'empresas seleccionadas.',\n              autoClouse: false,\n              sm: true,\n              displayItems: 3,\n              allOption: false,\n              search: true,\n              options: billingSettings.companies.map(company => ({\n                value: company._id,\n                text: `${company?.team?.name} - ${company.name}`\n              })),\n              selectAll: (all: boolean) => {\n                /*this.props.dispatch!!(autofill('formForm', `${item}.config.transmittalTypes`, all ? milestoneTypes.map(mT => mT._id) : []))*/\n              },\n              onClick: (value: string) => {\n                let currentValue = formValues?.companies ?? [];\n                if (currentValue?.includes(value)) {\n                  currentValue = currentValue.filter((v: string) => v !== value);\n                } else {\n                  currentValue.push(value);\n                }\n                billingSettingsActions.autofill(`companies`, currentValue);\n                this.setState({ change: true });\n              }\n            }}\n            />\n          </div>\n\n          <FieldArray<IBillingSettinsModuleRenderItemProps>\n            name='modules'\n            component={BillingModuleRender}\n            props={{\n              billingSettings\n            }}\n          />\n\n          <ShowIf condition={false}>\n            <div className='col-md-12'>\n            <JsonFormatter\n              json={JSON.stringify(billingSettings.modules)}\n              jsonStyle={{\n                propertyStyle: { color: 'red' },\n                stringStyle: { color: 'green' },\n                numberStyle: { color: 'darkorange' }\n              }}\n            />\n            </div>\n          </ShowIf>\n\n          <FieldArray<IBillingSettinsNotificationRenderItemProps>\n            name='notifications'\n            component={BillingNotificationRender}\n            props={{\n              billingSettings\n            }}\n          />\n\n          {\n            submitFailed && !valid &&\n            <div className='col-md-12'>\n              <div\n                className='alert alert-danger'\n                style={{marginTop: '10px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst BillingSettingsForm = reduxForm({\n  form: 'billingSettingsForm'\n})(Form);\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState, router: any }) => {\n  return {\n    formValues:  getFormValues('billingSettingsForm')(state),\n    billingSettings: state.billingSettings\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const billingSettingsActions = new BillingSettingsActions(dispatch);\n  return {\n    billingSettingsActions,\n    dispatch\n  };\n};\n\nexport default connect<{ billingSettings: IBillingSettingsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(BillingSettingsForm);\n","import * as React from 'react';\nimport { Field, FieldArray, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { connect } from 'react-redux';\nimport { IBillingSettingsState } from '../../../../../actions/billingSettings.types';\nimport BillingSectionSettingsRender from './BillingSettingsSectionRender';\nimport BootstrapSwitchField from '../../../../Utils/forms/BootsrapSwitchField';\n\nexport interface IBillingSettinsModuleRenderItemProps {\n  billingSettings: IBillingSettingsState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IBillingSettinsModuleRenderItemProps {\n  formValues: any;\n}\n\ninterface IStateType {\n}\n\nclass BillingModuleRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, billingSettings } = this.props;\n    return (\n      <div className='col-md-12'>\n        <h4>Módulos</h4>\n        <table style={{width: \"100%\"}}>\n          <tbody>\n          {\n            fields.map((item, index) => {\n              const value: any = fields.get(index);\n              return (\n                <React.Fragment key={index}>\n                  <tr>\n                    <td style={{ padding: '5px 0' }}>\n                      <Field\n                        name={`${item}.active`}\n                        label={<div>\n                          <strong>{value.name}</strong> <span className={'text-muted'}>({\n                          value.subModules.map((subModule: any) => subModule.name).join(', ')\n                        })</span>\n                        </div>}\n                        type='checkbox'\n                        checked={value?.active}\n                        component={BootstrapSwitchField}\n                        validate={[]}\n                      />\n\n                    </td>\n                  </tr>\n                  <tr>\n                    <td>\n                      <FieldArray<IBillingSettinsModuleRenderItemProps>\n                        name={`${item}.sections`}\n                        component={BillingSectionSettingsRender}\n                        props={{\n                          billingSettings\n                        }}\n                      />\n                    </td>\n                  </tr>\n                </React.Fragment>\n              );\n            })\n          }\n          </tbody>\n        </table>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState }) => {\n  const selector = formValueSelector('formTypeForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    billingSettings: state.billingSettings\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IBillingSettinsModuleRenderItemProps>(mapStateToProps, mapDispatchToProps)(BillingModuleRender);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport InputField from '../../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../../Utils/forms/validations';\nimport { connect } from 'react-redux';\nimport { IBillingSettingsState } from '../../../../../actions/billingSettings.types';\nimport * as uuid from 'uuid';\n\nexport interface IBillingSettinsNotificationRenderItemProps {\n  billingSettings: IBillingSettingsState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IBillingSettinsNotificationRenderItemProps {\n  formValues: any;\n}\n\ninterface IStateType {\n}\n\nclass BillingNotificationRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, billingSettings } = this.props;\n    return (\n      <div className='col-md-12'>\n        <h4>Notificaciones</h4>\n        <table width={'100%'}>\n          <tbody>\n          {\n            fields.map((item, index) => {\n              const value: any = fields.get(index);\n              // console.log(value);\n              return (\n                <tr key={index}>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.name`}\n                      label='Nombre *'\n                      placeholder='Nombre'\n                      type='text'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                    />\n                  </td>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.email`}\n                      label='Email *'\n                      placeholder='Email'\n                      type='text'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                    />\n                  </td>\n                  <td style={{paddingTop: \"10px\", width: \"10px\"}}>\n                    <button className={\"btn btn-sm btn-danger\"} onClick={(e) => {\n                      e.preventDefault();\n                      fields.remove(index);\n                    }}>\n                      <i className='fa fa-minus-circle' />\n                    </button>\n                  </td>\n                </tr>\n              );\n            })\n          }\n          </tbody>\n        </table>\n        <div className='row'>\n          <div className='col-md-12 text-right'>\n            <button\n              className='btn btn-sm btn-success'\n              onClick={(e) => {\n                e.preventDefault();\n                fields.push({\n                  tid: uuid.v4(),\n                  enabled: true\n                });\n              }}\n            >\n              <i className='fa fa-plus' /> Agregar Destinatario\n            </button>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState }) => {\n  const selector = formValueSelector('formTypeForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    billingSettings: state.billingSettings\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IBillingSettinsNotificationRenderItemProps>(mapStateToProps, mapDispatchToProps)(BillingNotificationRender);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport InputField from '../../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../../Utils/forms/validations';\nimport { connect } from 'react-redux';\nimport { IBillingSettingsState } from '../../../../../actions/billingSettings.types';\nimport * as uuid from 'uuid';\n\nexport interface IBillingSettinsSectionRenderItemProps {\n  billingSettings: IBillingSettingsState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IBillingSettinsSectionRenderItemProps {\n  formValues: any;\n}\n\ninterface IStateType {\n}\n\nclass BillingSectionRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, billingSettings } = this.props;\n    return (\n      <React.Fragment>\n        <table className={\"table\"} width={'100%'}>\n          <thead>\n            <tr>\n              <th>Tramo</th>\n              <th>Desde</th>\n              <th>Hasta</th>\n              <th>Precio</th>\n              <th>Texto</th>\n              <th></th>\n            </tr>\n          </thead>\n          <tbody>\n          {\n            fields.map((item, index) => {\n              const value: any = fields.get(index);\n              // console.log(value);\n              return (\n                <tr key={index}>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.name`}\n                      label='Nombre *'\n                      placeholder=''\n                      type='text'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                       props={{\n                         labelOff: true\n                       }}\n                    />\n                  </td>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.start`}\n                      label=''\n                      placeholder=''\n                      type='number'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                      props={{\n                        labelOff: true\n                      }}\n                    />\n                  </td>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.end`}\n                      label=''\n                      placeholder=''\n                      type='number'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                      props={{\n                        labelOff: true\n                      }}\n                    />\n                  </td>\n                   <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.price`}\n                      label=''\n                      placeholder=''\n                      type='number'\n                      component={InputField}\n                      validate={[inputStringRequired]}\n                      props={{\n                        labelOff: true\n                      }}\n                    />\n                  </td>\n                  <td className={'form-group-no-margin'} style={{ padding: '5px' }}>\n                    <Field\n                      name={`${item}.text`}\n                      label=''\n                      placeholder=''\n                      type='text'\n                      component={InputField}\n                      // validate={[inputStringRequired]}\n                       props={{\n                         labelOff: true\n                       }}\n                    />\n                  </td>\n                  <td style={{paddingTop: \"5px\", width: \"10px\"}}>\n                    <button className={\"btn btn-sm btn-danger\"} onClick={(e) => {\n                      e.preventDefault();\n                      fields.remove(index);\n                    }}>\n                      <i className='fa fa-minus-circle' />\n                    </button>\n                  </td>\n                </tr>\n              );\n            })\n          }\n          </tbody>\n        </table>\n        <div className='row'>\n          <div className='col-md-12 text-right'>\n            <button\n              className='btn btn-sm btn-success'\n              onClick={(e) => {\n                e.preventDefault();\n                fields.push({\n                  tid: uuid.v4(),\n                  enabled: true\n                });\n              }}\n            >\n              <i className='fa fa-plus' /> Agregar Tramo\n            </button>\n          </div>\n        </div>\n      </React.Fragment>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { billingSettings: IBillingSettingsState }) => {\n  const selector = formValueSelector('formTypeForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    billingSettings: state.billingSettings\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IBillingSettinsSectionRenderItemProps>(mapStateToProps, mapDispatchToProps)(BillingSectionRender);\n","import {BorderReduxAction, changeTempBorderAction, IBorderState} from \"../../actions/borders.actions\";\nimport {IBaseBorder} from \"../../../../../../src/app/interfaces/border.interface\";\nimport * as React from \"react\";\nimport BootstrapSelect from \"../Utils/BootstrapSelect\";\nimport {connect} from \"react-redux\";\n\ninterface IPropsType {\n  borderState?: IBorderState;\n  changeTempBorderAction?: (border: IBaseBorder) => BorderReduxAction\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass BorderFormView extends React.Component<IPropsType, IStateType>{\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.borderState && this.props.changeTempBorderAction) {\n      const {changeTempBorderAction} = this.props;\n      const {tempBorder, companies} = this.props.borderState;\n\n      return (\n        <React.Fragment>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempBorder.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempBorderAction({\n                          ...tempBorder,\n                          name: e.target.value\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Latitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      step=\"any\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempBorder.lat}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempBorderAction({\n                          ...tempBorder,\n                          lat: parseFloat(e.target.value)\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-6\">\n                  <div className=\"form-group\">\n                    <label>Longitud</label>\n                    <input\n                      type=\"number\"\n                      name=\"lng\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tempBorder.lng}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempBorderAction({\n                          ...tempBorder,\n                          lng: parseFloat(e.target.value)\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"id-company\">Empresa</label>\n                    <BootstrapSelect\n                      noneSelectedText=\"Seleccione\"\n                      search={true}\n                      options={\n                        companies\n                          .map((company) => ({\n                            value: company._id,\n                            text: company.name\n                          }))\n                      }\n                      selected={tempBorder.company ? [tempBorder.company._id] : []}\n                      autoClouse={true}\n                      onClick={(value: string) => changeTempBorderAction({\n                        ...tempBorder,\n                        company: companies.find((company) => (company._id === value))\n                      })}\n                    />\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n}\n\nconst mapStateToProps = (state: { border: IBorderState }) => {\n  return {\n    borderState: state.border\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempBorderAction: (border: IBaseBorder) => dispatch(changeTempBorderAction(border)),\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(BorderFormView);\n","import {\n  BorderReduxAction, changeSearchAction, changeTempBorderAction,\n  createBorderAction, deleteBorderAction,\n  getBorderAction,\n  getBorderCompanyAction,\n  IBorderState, updateBorderAction\n} from \"../../actions/borders.actions\";\nimport {IBaseBorder, IBorder} from \"../../../../../../src/app/interfaces/border.interface\";\nimport {loadDataAction, ModalReduxAction} from \"../../actions/modal.actions\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {RouteComponentProps} from \"react-router\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport Row from \"../Utils/Row\";\nimport {hasPermission} from \"../../utils/common\";\nimport * as React from \"react\";\nimport * as moment from \"moment\";\nimport Paginator from \"../Utils/Paginator\";\nimport ModalView from \"../Modal/ModalView\";\nimport AppContainer from \"../../container/AppContainer\";\nimport * as mapboxgl from \"mapbox-gl\";\nimport {Dispatch} from \"redux\";\nimport TableListView, {Actions} from \"../Utils/TableListView\";\nimport * as swal from \"sweetalert\";;\nimport BorderFormView from \"./BorderFormView\";;\nimport {connect} from \"react-redux\";\n\nenum IPageSelector {\n  list = 'list',\n  map = 'map',\n}\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<BorderReduxAction>;\n  border: IBorderState;\n  changeTempBorder(border: IBaseBorder): BorderReduxAction;\n  getCompaniesAction(): BorderReduxAction;\n  getBordersAction(page: number): BorderReduxAction;\n  createBorderAction(): BorderReduxAction;\n  updateBorderAction(): BorderReduxAction;\n  deleteBorderAction(id?: string): BorderReduxAction;\n  changeSearchAction(searchText: string): BorderReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\n\ninterface IStateType {\n  error: Error | null;\n  tab: IPageSelector;\n}\n\ndeclare let window: IWindow;\n\nclass BordersListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string = \"Administrador de pórticos\";\n  private map: any;\n  timer: any;\n\n  state: IStateType = {\n    error: null,\n    tab: IPageSelector.list\n  }\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.changeTab = this.changeTab.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.changeBorder = this.changeBorder.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.createBorder = this.createBorder.bind(this);\n    this.deleteBorder = this.deleteBorder.bind(this);\n    this.processChangeBorder = this.processChangeBorder.bind(this);\n    this.processCreateBorder = this.processCreateBorder.bind(this);\n    this.onChangeTab = this.onChangeTab.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.border;\n    this.props.getCompaniesAction();\n    this.props.getBordersAction(pagination.page);\n  }\n\n  private debounce(fn: Function, delay = 300): void {\n    return (() => {\n      clearTimeout(this.timer)\n      this.timer = setTimeout(() => fn(), delay)\n    })()\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.props.changeSearchAction(value);\n    this.debounce(() => {\n      this.props.getBordersAction(1);\n    }, 300)\n  }\n\n  private createBorder() {\n    this.props.changeTempBorder({\n      _id: '',\n      name: '',\n      lng: 0,\n      lat: 0,\n      company: null\n    });\n    this.props.loadDataAction(\n      'Agregar Pórtico',\n      <BorderFormView />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={this.processCreateBorder}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateBorder() {\n    const {tempBorder} = this.props.border;\n    if (!tempBorder.name || !tempBorder.name.trim()) {\n      swal!('Agregar pórtico', 'El nombres es requerido', 'error');\n    } else if (!tempBorder.company || !tempBorder.company._id) {\n      swal!('Agregar pórtico', 'La empresa es requerida', 'error');\n    } else {\n      this.props.createBorderAction();\n    }\n  }\n\n  private changeBorder(border: IBaseBorder) {\n    this.props.changeTempBorder(border);\n    this.props.loadDataAction(\n      'Editar Pórtico',\n      <BorderFormView />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={this.processChangeBorder}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processChangeBorder() {\n    const {tempBorder} = this.props.border;\n    if (!tempBorder.name || !tempBorder.name.trim()) {\n      swal!('Agregar pórtico', 'El nombres es requerido', 'error');\n    } else if (!tempBorder.company || !tempBorder.company._id) {\n      swal!('Agregar pórtico', 'La empresa es requerida', 'error');\n    } else {\n      this.props.updateBorderAction();\n    }\n  }\n\n  private deleteBorder(border: IBaseBorder) {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el pórtico ${border.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteBorderAction(border._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getBordersAction(page);\n  }\n\n\n\n  public componentDidMount() {\n    super.componentDidMount();\n    // mapboxgl.accessToken = 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw';\n    this.map = new mapboxgl.Map({\n      accessToken: 'pk.eyJ1IjoicmliYXJyYWNsIiwiYSI6ImNqems3dW85bTAwZmUzbnF0a2xubnl5ejUifQ.tfPmGSbHYdh2nMA6Fmxcxw',\n      container: 'map',\n      style: 'mapbox://styles/mapbox/streets-v11',\n      center: [-70.593536, -33.509243],\n      zoom: 10,\n      trackResize: true\n    });\n    this.map.addControl(new mapboxgl.NavigationControl(), 'bottom-right');\n\n    $('a[href=\\'#tab_2\\']').on('shown.bs.tab', () => {\n      this.onChangeTab();\n    });\n  }\n\n  private changeTab(name: IPageSelector): void {\n    this.setState({\n      tab: name\n    }, this.onChangeTab);\n  }\n\n  private onChangeTab() {\n    let borders = this.props.border?.borders;\n    if (!borders)\n      return\n\n    const geojson = {\n      type: 'FeatureCollection',\n      features: borders\n        .filter((border) => (border.lng && border.lat))\n        .map((border: any) => {\n          return {\n            type: 'Feature',\n            geometry: {\n              type: 'Point',\n              coordinates: [border.lng, border.lat]\n            },\n            properties: {\n              title: 'Pórticos',\n              name: border.name?.toUpperCase(),\n              border,\n              logo: border.company.marker?.url?.length\n                ? `url(\"${border.company.marker.url}\")`\n                : 'url(\"/static/images/files/pin_osa.svg\")'\n            }\n          };\n        })\n    };\n\n    const $map = this.map;\n    // $('#map').css('width', $('#tab_2').width() as any);\n    const bounds = new mapboxgl.LngLatBounds();\n    geojson.features.forEach((marker) => {\n\n      // create a HTML element for each feature\n      const el: HTMLDivElement = document.createElement('div');\n      // here set class use in the marker\n      // el.className = 'marker';\n      el.style.backgroundImage = marker.properties.logo;\n      el.style.backgroundSize = 'cover';\n      el.style.width = '50px';\n      el.style.height = '50px';\n      el.style.borderRadius = '50p%';\n      el.style.cursor = 'pointer';\n\n      // make a marker for each feature and add to the map\n      if (Math.abs(marker.geometry.coordinates[0]) > 0.1) {\n        new mapboxgl.Marker(el)\n          .setLngLat((marker.geometry.coordinates as [number, number]))\n          .setPopup(new mapboxgl.Popup({ offset: 25 })\n            .setHTML(`\n            <strong>${marker.properties.name}</strong>\n<!--            <strong >Editar</strong>-->\n          `))\n          .addTo($map);\n\n        bounds.extend((marker.geometry.coordinates as [number, number]));\n      }\n    });\n    $map.resize();\n    $map.fitBounds(bounds, {padding: 100});\n  }\n\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const {tab} = this.state;\n    const {pagination, searchText, loading, borders} = this.props.border;\n\n    let actions: Actions[] = [];\n    if (hasPermission(window.user, 'changeBorder'))\n      actions.push(Actions.edit)\n    if (hasPermission(window.user, 'deleteBorder'))\n      actions.push(Actions.delete)\n\n    return (\n      <AppContainer title='' cMenu='10' cSubMenu='10.11' cAction='Listado'>\n        <section className='content'>\n          <Row>\n            <div className='col-md-12 col-lg-12'>\n              <div className='box box-solid'>\n                <ul className='nav nav-pills nav-justified no-padding'>\n                  <li className={tab === IPageSelector.list ? 'no-margin active' : 'no-margin'}>\n                    <a\n                      href='javascript:void(0);'\n                      className={tab === IPageSelector.list ? 'background-transition' : ''}\n                      style={{borderTop: '0', marginBottom: '0'}}\n                      onClick={() => this.changeTab(IPageSelector.list)}\n                    >Pórticos</a>\n                  </li>\n                  <li className={tab === IPageSelector.map ? 'no-margin active' : 'no-margin'}>\n                    <a\n                      className={tab === IPageSelector.map ? 'background-transition' : ''}\n                      href='javascript:void(0);'\n                      style={{borderTop: '0', marginBottom: '0'}}\n                      onClick={() => this.changeTab(IPageSelector.map)}\n                    >Mapa</a>\n                  </li>\n                </ul>\n              </div>\n            </div>\n          </Row>\n\n          <div className={`box ${tab === IPageSelector.list ? '' : 'hidden'}`}>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Pórticos <small>{pagination.count}</small></h3>\n              <div className='box-tools pull-right'>\n                {\n                  hasPermission(window.user, 'addBorder') ?\n                    <button className='btn btn-sm btn-success' onClick={this.createBorder}><i\n                      className='fa fa-plus'/> Crear Pórtico</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className='box-body no-padding'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <div className='input-group input-group-sm'\n                       style={{padding: '10px'}}\n                  >\n                    <input\n                      type='text'\n                      value={searchText}\n                      className='form-control pull-right'\n                      onChange={this.onChangeSearch}\n                      placeholder='Buscar'/>\n                    <div className='input-group-btn'>\n                      <button className='btn btn-default'><i className='fa fa-search'/></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n\n              <TableListView headers={[\n                {name: 'Nombre', accessor: (data: IBorder) => data.name},\n                {name: 'Ubicación', accessor: (data: IBorder) => `lat:${data.lat}\\nlng:${data.lng}`},\n                {name: 'Modificado', accessor: (data: IBorder) => moment(data.updatedAt).format('LLL')},\n              ]} actions={actions} data={borders} name={'border'} editElement={this.changeBorder} deleteElement={this.deleteBorder} />\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer text-right'>\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple'/>\n              </div>\n            }\n          </div>\n\n          <div className={`box ${tab === IPageSelector.map ? '' : 'hidden'}`}>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Pasos de Frontera <small>{pagination.count}</small></h3>\n            </div>\n            <div className='box-body no-padding'>\n              <div\n                id='map'\n                style={{\n                  position: 'relative',\n                  width: '100%',\n                  height: '70vh'\n                }}\n              />\n            </div>\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { border: IBorderState }) => {\n  return {\n    border: state.border\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    changeTempBorder: (border: IBaseBorder) => dispatch(changeTempBorderAction(border)),\n    getCompaniesAction: () => dispatch(getBorderCompanyAction()),\n    getBordersAction: (page: number) => dispatch(getBorderAction(page)),\n    createBorderAction: () => dispatch(createBorderAction()),\n    updateBorderAction: () => dispatch(updateBorderAction()),\n    deleteBorderAction: (id: string) => dispatch(deleteBorderAction(id)),\n    changeSearchAction: (searchText: string) => dispatch(changeSearchAction(searchText)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ border: IBorderState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(BordersListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {\n  IBaseCarrier\n} from '../../../../../../src/app/interfaces/carrier.interface';\nimport {\n  CarrierReduxAction,\n  changeTempCarrierAction,\n  ICarriersState\n} from '../../actions/carriers.actions';\n\ninterface IPropsType {\n  carriers?: ICarriersState;\n  update?: boolean;\n  changeTempCarrierAction?: (carrier: IBaseCarrier, delay?: boolean) => CarrierReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarriersFormView extends React.Component<IPropsType, IStateType> {\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.carriers && this.props.changeTempCarrierAction) {\n      const {tempCarrier} = this.props.carriers;\n      const {changeTempCarrierAction} = this.props;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"fistName\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempCarrier ? tempCarrier.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => changeTempCarrierAction({\n                    ...tempCarrier,\n                    name: e.target.value\n                  })\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    }\n    return null;\n  }\n}\n\nconst mapStateToProps = (state: { carriers: ICarriersState }) => {\n  return {\n    carriers: state.carriers\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempCarrierAction: (carrier: IBaseCarrier, delay?: boolean) => dispatch(changeTempCarrierAction(carrier, delay))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarriersFormView);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { IBaseCarrier, ICarrier } from '../../../../../../src/app/interfaces/carrier.interface';\nimport {\n  CarrierReduxAction,\n  changeTempCarrierAction,\n  createCarrierAction,\n  deleteCarrierAction,\n  getCarriersAction,\n  ICarriersState,\n  updateCarrierAction\n} from '../../actions/carriers.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport CarriersFormView from './CarriersFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport CopyText from '../Utils/CopyText';\n\ninterface IPropsType extends RouteComponentProps<{ carrier: string }> {\n  dispatch: Dispatch<CarrierReduxAction>;\n  carriers: ICarriersState;\n\n  createCarrierAction(): CarrierReduxAction;\n\n  updateCarrierAction(): CarrierReduxAction;\n\n  deleteCarrierAction(id: string): CarrierReduxAction;\n\n  changeTempCarrierAction(carrier: IBaseCarrier, delay?: boolean): CarrierReduxAction;\n\n  getCarriersAction(page: number): CarrierReduxAction;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass CarriersListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de transportistas';\n    this.createCarrier = this.createCarrier.bind(this);\n    this.processCreateCarrier = this.processCreateCarrier.bind(this);\n    this.updateCarrier = this.updateCarrier.bind(this);\n    this.processUpdateCarrier = this.processUpdateCarrier.bind(this);\n    this.deleteCarrier = this.deleteCarrier.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.carriers;\n    this.props.getCarriersAction(pagination.page);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.carriers.source) {\n      this.props.carriers.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, carriers, pagination } = this.props.carriers;\n    return (\n      <AppContainer title='' cMenu='10' cSubMenu='10.6' cAction='Listado'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'><h3 className='box-title'>Transportistas <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addCarrier') ?\n                  <div className='box-tools pull-right'>\n                    <button className='btn btn-sm btn-success' onClick={this.createCarrier}><i className='fa fa-plus' /> Crear transportista</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className='box-body no-padding'>\n              <table className='table table-andes table-striped'>\n                <thead>\n                <tr>\n                  <th style={{ width: '80%' }} className='middle'>Nombre</th>\n                  <th style={{ width: '18%' }} className='middle hidden-xs'>Modificado</th>\n                  {\n                    hasPermission(window.user, 'changeCarrier') ?\n                      <th style={{ width: '1%' }} className='width-10' /> : null\n                  }\n                  {\n                    hasPermission(window.user, 'deleteCarrier') ?\n                      <th style={{ width: '1%' }} className='width-10' /> : null\n                  }\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  carriers.map((carrier: ICarrier) => {\n                    return (\n                      <tr\n                        key={carrier._id}\n                        id={`carrier-${carrier._id}`}\n                        className={'background-transition'}\n                      >\n                        <td className='middle'>\n                          <CopyText value={`${carrier.name?.toUpperCase()}`}>\n                            <strong className='text-primary'>\n                              {carrier.name?.toUpperCase()}\n                            </strong>\n                          </CopyText>\n                        </td>\n                        <td className='middle hidden-xs text-sm text-muted'>{moment(carrier.updatedAt).format('LLL')}</td>\n                        {\n                          hasPermission(window.user, 'changeCarrier') ?\n                            <td\n                              className='middle text-blue pointer'\n                              onClick={() => this.updateCarrier(carrier)}\n                            >\n                              <i className='fa fa-pencil' />\n                            </td> : null\n                        }\n                        {\n                          hasPermission(window.user, 'deleteCarrier') ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteCarrier(carrier)}\n                            ><i className='fa fa-minus-circle' /></td> : null\n                        }\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer text-right'>\n                <Paginator changePage={this.props.getCarriersAction} page={pagination.page} pages={pagination.pages} />\n              </div>\n            }\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createCarrier(): void {\n    this.props.changeTempCarrierAction({\n      _id: '',\n      name: ''\n    });\n    this.props.loadDataAction(\n      'Agregar Transportista',\n      <CarriersFormView />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={this.processCreateCarrier}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateCarrier(): void {\n    const { tempCarrier } = this.props.carriers;\n    if (!tempCarrier.name || !tempCarrier.name.trim()) {\n      swal('Agregar Transportista', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createCarrierAction();\n    }\n  }\n\n  private updateCarrier(carrier: ICarrier): void {\n    const { _id, name } = carrier;\n    this.props.changeTempCarrierAction({ _id, name });\n    this.props.loadDataAction(\n      'Editar Transportista',\n      <CarriersFormView update={true} />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={this.processUpdateCarrier}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateCarrier(): void {\n    const { tempCarrier } = this.props.carriers;\n    if (!tempCarrier.name || !tempCarrier.name.trim()) {\n      swal('Editar Transportista', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateCarrierAction();\n    }\n  }\n\n  private deleteCarrier(carrier: ICarrier): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar al transportista ${carrier.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteCarrierAction(carrier._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { carriers: ICarriersState }) => {\n  return {\n    carriers: state.carriers\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarriersAction: (page: number) => dispatch(getCarriersAction(page)),\n    createCarrierAction: () => dispatch(createCarrierAction()),\n    updateCarrierAction: () => dispatch(updateCarrierAction()),\n    deleteCarrierAction: (id: string) => dispatch(deleteCarrierAction(id)),\n    changeTempCarrierAction: (carrier: IBaseCarrier, delay?: boolean) => dispatch(changeTempCarrierAction(carrier, delay)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ carriers: ICarriersState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(CarriersListView);\n","// import * as PropTypes from 'prop-types';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport { ErrorInfo } from 'react';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { IParticipant } from '../../../../../../src/form/interfaces/participant.interface';\nimport { CarReduxAction, getCarAction, ICarsState } from '../../actions/cars.actions';\nimport { getParticipant, IDashboardState, loadParticipantInCarAction } from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport Row from '../Utils/Row';\nimport TimeLineForm from './TimeLineForm';\nimport TimeLineInventory from './TimeLineInventory';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport CopyText from '../Utils/CopyText';\nimport { parseReplicableURL } from '../../utils/common';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n  dashboard: IDashboardState;\n\n  getCarAction(id: string): void;\n\n  getParticipant(id: string): void;\n\n  loadParticipantInCarAction(participant: IParticipant): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  state = {\n    error: null,\n    highlight: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle VIN';\n  }\n\n  componentWillMount() {\n    const { id } = this.props.match.params;\n    this.props.getCarAction(id);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.cars.source) {\n      this.props.cars.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, car, carEvents } = this.props.cars;\n    const { loadingParticipant } = this.props.dashboard;\n    const { getParticipant } = this.props;\n    return (\n      <AppContainer title={`Detalle VIN ${car ? car.vin : null}`} cMenu='1' cSubMenu='1.0' cAction='Detalle'>\n        <section className='content'>\n          <Row>\n            <div className='col-md-3 col-lg-3'>\n              <div className='box box-primary'>\n                <div className='box-body box-profile'>\n                  {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'100px'} maxHeight={'100px'} maxWidth={'100px'} small={true}/>*/}\n                  {/*<img*/}\n                  {/*className=\"profile-user-img img-responsive img-circle\"*/}\n                  {/*src=\"https://cdn.forbes.com.mx/2018/03/Auto-Carretera-1280x720.jpg\"*/}\n                  {/*alt=\"User profile picture\"*/}\n                  {/*style={{*/}\n                  {/*fontFamily: 'object-fit:cover',*/}\n                  {/*objectFit: 'cover',*/}\n                  {/*width: '100px',*/}\n                  {/*height: '100px'*/}\n                  {/*}}*/}\n                  {/*/>*/}\n                  <h3 className='profile-username text-center text-black'>{car && car.brand ? car.brand : '-'}</h3>\n                  <p className='text-muted text-center text-black'>{car && car.denomination ? car.denomination : '-'}</p>\n                  <ul className='list-group list-group-unbordered no-margin text-muted'>\n                    <li className='list-group-item'>\n                      <strong>VIN</strong>\n                      <span className='pull-right text-primary'>\n                        <CopyText value={car?.vin ?? ''}>\n                          <strong>{\n                            car && car.vin ? car.vin : '-'\n                          }</strong>\n                        </CopyText>\n                      </span>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Color</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.color ? car.color : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Material</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.material ? car.material : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Patente</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.patent ? car.patent : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Nº Interno</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.internalNumber ? car.internalNumber : '-'\n                        }\n                      </strong>\n                    </li>\n\n                    {/*<li className='list-group-item'>*/}\n                    {/*  <strong>Revisiones</strong>*/}\n                    {/*  <span className='pull-right'>*/}\n                    {/*    {*/}\n                    {/*      car && car.participants ? car.participants.length : 0*/}\n                    {/*    }*/}\n                    {/*  </span>*/}\n                    {/*</li>*/}\n                    {/*<li className='list-group-item'>*/}\n                    {/*  <strong>Inventarios</strong>*/}\n                    {/*  <span className='pull-right'>*/}\n                    {/*    {*/}\n                    {/*      car && car.inventories ? car.inventories.length : 0*/}\n                    {/*    }*/}\n                    {/*  </span>*/}\n                    {/*</li>*/}\n                  </ul>\n                  <button\n                    className='btn btn-primary btn-block'\n                    onClick={() => {\n                      this.props.history.replace(parseReplicableURL(`/cars/${car?._id}`));\n                    }}\n                  >\n                    <strong>Controles</strong>\n                  </button>\n                </div>\n              </div>\n            </div>\n            <div className='col-md-9 col-lg-9'>\n              {\n                loading ?\n                  <div className='box'>\n                    <div className='box-body text-center'>\n                      <p>&nbsp;</p>\n                    </div>\n                    <div className='overlay'>\n                      <i className='fa fa-spinner fa-spin text-purple' />\n                    </div>\n                  </div> :\n                  <div className='nav-tabs-custom'>\n                    <ul className='nav nav-tabs'>\n                      <li className='active'><a href='#timeline' data-toggle='tab' aria-expanded='true'>Timeline</a></li>\n                    </ul>\n                    <div className='tab-content' style={{\n                      backgroundColor: '#f9f9f9'\n                      // maxHeight: '80vh',\n                      // overflowX: 'auto'\n                    }}>\n                      <div className='tab-pane active' id='timeline'>\n                        <ul className='timeline'>\n                          {\n                            Object.keys(carEvents).map((event) => {\n                              const events = carEvents[event];\n                              return <React.Fragment key={event}>\n                                <li className='time-label'>\n                                  <span className='bg-blue'>\n                                      {moment(event).format('MMMM YYYY')}\n                                  </span>\n                                </li>\n                                {\n                                  events.map((data: any) => {\n                                    return (\n                                      data.typeEvent === 'created' ?\n                                        <li style={{ marginRight: '0' }} key={data._id}>\n                                          <i className={`fa fa-cloud-upload bg-green`} />\n                                          <div className='timeline-item'>\n                                            <span className='time' style={{\n                                              color: '#888',\n                                              fontSize: '13px'\n                                            }}>\n                                              <div\n                                                className='text-muted text-sm' data-toggle='tooltip'\n                                                data-placement='top'\n                                                title={moment(data.createdAt).format('LLL')}\n                                              >\n                                <i className='fa fa-fw fa-clock-o' /> {moment(data.createdAt).fromNow()}\n                              </div>\n                                            </span>\n                                            <h3 className='timeline-header'><a href='javascript:void(0)'>VEHÍCULO IMPORTADO</a></h3>\n                                            <div className='timeline-body'>\n                                              El vehículo fue importado al sistema\n                                              el {data.createdAt.format('LLLL')}.\n                                            </div>\n                                          </div>\n                                        </li>\n                                        : data.typeEvent === 'revision' ?\n                                          <TimeLineForm form={data} getParticipant={getParticipant} loadingParticipant={loadingParticipant}\n                                                        key={data._id} />\n                                          : <TimeLineInventory inventory={data} key={data._id} />\n                                    );\n                                  })\n                                }\n                              </React.Fragment>;\n                            })\n                          }\n                          <li>\n                            <i className='fa fa-clock-o bg-gray' />\n                          </li>\n                        </ul>\n                      </div>\n                    </div>\n                  </div>\n              }\n            </div>\n          </Row>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState, dashboard: IDashboardState }) => {\n  return {\n    cars: state.cars,\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarAction: (id: string) => dispatch(getCarAction(id)),\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadParticipantInCarAction: (participant: IParticipant) => dispatch(loadParticipantInCarAction(participant))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarDetailView);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport { ErrorInfo } from 'react';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { debounce } from 'throttle-debounce';\nimport { ICar } from '../../../../../../src/app/interfaces/car.interface';\nimport { CarReduxAction, getCarsAction, ICarsState } from '../../actions/cars.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../utils/common';\nimport CopyText from '../Utils/CopyText';\nimport ShowIf from '../Utils/ShowIf';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<CarReduxAction>;\n  cars: ICarsState;\n\n  getCarsAction(page: number, search?: string): CarReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  searchText: string;\n}\n\nclass CarListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly state = {\n    error: null,\n    searchText: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de autos';\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount() {\n    const { pagination } = this.props.cars;\n    this.props.getCarsAction(pagination.page);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.cars.pagination !== prevProps.cars.pagination) {\n      window.scrollTo(0, 0);\n    }\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.cars.source) {\n      this.props.cars.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, cars, pagination } = this.props.cars;\n    const { searchText } = this.state;\n    return (\n      <AppContainer title='' cMenu='1' cSubMenu='1.0' cAction='Listado'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>\n                Unidades <small>{pagination.count}</small>\n              </h3>\n              <div className='box-tools'>\n                {\n                  hasPermission(window.user, 'addCar') ?\n                    <button\n                      className='btn btn-sm btn-primary hidden-xs'\n                      onClick={() => this.props.history.push(`/settings/cars/import/`)}\n                    ><i className='fa fa-fw fa-cloud-upload' /> Importar</button> : null\n                }\n              </div>\n            </div>\n            <div className='box-body no-padding'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type='text'\n                      className='form-control pull-right'\n                      onChange={this.onChangeSearch}\n                      placeholder='Buscar' />\n                    <div className='input-group-btn'>\n                      <button className='btn btn-default'><i className='fa fa-search' /></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <table className='table table-andes table-striped'>\n                <thead>\n                <tr>\n                  {/*<th className='middle  hidden-xs' style={{ width: '180px' }}>VIN</th>*/}\n                  <th className='middle'>Descripción</th>\n                  <ShowIf\n                    condition={\n                      ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id)\n                    }\n                  >\n                    <th className='middle hidden-xs' style={{ width: '100px' }}>Material</th>\n                  </ShowIf>\n                  <ShowIf\n                    condition={\n                      !['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id)\n                    }\n                  >\n                    <th className='middle hidden-xs' style={{ width: '100px' }}>Partida</th>\n                  </ShowIf>\n                  <th className='middle hidden-xs' style={{ width: '15%' }}></th>\n                  <th style={{ width: '1%' }} />\n                </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && cars.length === 0 && searchText ? <tr>\n                    <td colSpan={5}>No se han encontrado resultados.</td>\n                  </tr> : null\n                }\n                {\n                  cars.map((car: ICar) => {\n                    return (\n                      <tr key={car._id} id={`car-${car._id}`}>\n                        <td\n                          className='middle text-muted'\n                        >\n                          <CopyText value={car?.vin}>\n                            <strong\n                              className='text-primary pointer text-underline'\n                              onClick={() => this.props.history.push(parseReplicableURL(`/settings/cars/${car?._id}`))}\n                            >\n                              {car?.vin}\n                            </strong>\n                          </CopyText>\n                          <div className={'text-sm'}>\n                            <strong className={'text-muted'}>\n                              {car?.brand}\n                            </strong><br />\n                            {car?.denomination}<br />\n                            {car.color}\n                          </div>\n                          <ShowIf condition={!!car?.patent?.length}>\n                            <br />\n                            <i\n                              className='fa fa-fw fa-id-card-o' /> {car?.patent && car?.patent.length ? car?.patent : '-'}\n                          </ShowIf>\n                        </td>\n                        <ShowIf\n                            condition={\n                              ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id)\n                            }\n                          >\n                            <td\n                              className='middle text-muted  hidden-xs'\n                            >\n                              {car.material?.length ? car.material : '-'}\n                            </td>\n                          </ShowIf>\n                        <ShowIf\n                          condition={\n                            !['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id)\n                          }\n                        >\n                          <td\n                            className='middle text-muted hidden-xs'\n                          >\n                            {car.entry}\n                          </td>\n                        </ShowIf>\n                        <td className='middle hidden-xs text-ellipsis text-muted hidden-xs'>\n                          <div\n                            className='text-muted text-sm' data-toggle='tooltip'\n                            data-placement='top'\n                            title={moment(car.createdAt).format('LLL')}\n                          >\n                            <i className='fa fa-fw fa-clock-o' /> {moment(car.createdAt).fromNow()}\n                          </div>\n                        </td>\n                        <td className='text-primary middle-center'>\n                          <button\n                            className='btn btn-sm btn-primary'\n                            onClick={() => this.props.history.push(`/settings/cars/${car._id}`)}\n                          ><i className='fa fa-bars' />\n                          </button>\n                        </td>\n                      </tr>\n                    );\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6'>\n                    {\n                      searchText && searchText.length ? <p><strong>Filtrado por:</strong> {searchText}</p> : null\n                    }\n                  </div>\n                  <div className='col-md-6 text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    this.setState({\n      searchText: value\n    });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { searchText } = this.state;\n    if (searchText && searchText.length) {\n      this.props.getCarsAction(1, searchText);\n    } else {\n      this.props.getCarsAction(1);\n    }\n  }\n\n  private changePage(page: number): void {\n    const { searchText } = this.state;\n    this.props.getCarsAction(page, searchText);\n  }\n}\n\nconst mapStateToProps = (state: { cars: ICarsState }) => {\n  return {\n    cars: state.cars\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarsAction: (page: number, search?: string) => dispatch(getCarsAction(page, search))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CarListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport * as moment from 'moment-timezone';\n\nimport Row from '../Utils/Row';\n\ninterface IPropsType {\n  form: any;\n  loadingParticipant: string | null;\n\n  getParticipant(id: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass TimeLineForm extends React.Component<IPropsType, IStateType> {\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.getColorByDamage = this.getColorByDamage.bind(this);\n    this.getIconDamage = this.getIconDamage.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const { form, loadingParticipant } = this.props;\n    return (\n\n      <li style={{ marginRight: '0' }}>\n        <i className={`fa ${form.imported ? 'fa-cloud-upload' : this.getIconDamage(form.hasDamages)} ${form.imported ? 'bg-orange' : this.getColorByDamage(form.hasDamages)}`} />\n        <div className='timeline-item'>\n          <span className='time text-sm' style={{\n            color: '#888'\n          }}>\n            <div\n              className='text-muted text-sm' data-toggle='tooltip'\n              data-placement='top'\n              title={moment(form.createdAt).format('LLL')}\n            >\n              <i className='fa fa-fw fa-clock-o' /> {moment(form.createdAt).fromNow()}\n            </div>\n          </span>\n\n          <h3 className='timeline-header'><a href='javascript:void(0)'>{form.name}</a></h3>\n\n          <div className='timeline-body'>\n            {form.kind === 'final' ?\n              <React.Fragment>\n                El vehículo fue entregado en <span className='text-blue'>{form.venue.name}</span>\n              </React.Fragment> : null\n            }\n            {\n              form.kind != 'final' && form.form.reception ?\n                <React.Fragment>\n                  El vehículo fue recepcionado\n                  {\n                    form.venue ?\n                      <React.Fragment> en <span className='text-blue'>{form.venue.name}</span></React.Fragment>\n                      : ''\n                  }\n                  {\n                    form.receiveFrom ?\n                      <React.Fragment> desde <span className='text-blue'>{form.receiveFrom.name}</span></React.Fragment>\n                      : ''\n                  }.\n                  {/* Con una calificación de <strong>{form.qualification.toFixed(0)}%</strong>. */}\n                </React.Fragment> : null\n            }\n            {\n              form.kind != 'final' && form.form.shipping ?\n                <React.Fragment>\n                  El vehículo fue Despachado desde <span className='text-blue'>{form.venue.name}</span>\n                  {\n                    form.sendTo ?\n                      <React.Fragment> hacia <span className='text-blue'>{form.sendTo.name}</span></React.Fragment>\n                      : ''\n                  }.\n                  {/* Con una calificación de <strong>{form.qualification.toFixed(0)}%</strong>. */}\n                </React.Fragment>\n                : ''\n            }\n            {form.imported ? <small className='text-muted'><br />* Cargado de forma masiva.</small> : ''}\n          </div>\n          <div className='timeline-footer'>\n            <Row>\n              <div\n                className='col col-md-5 col-sm-5 col-xs-5'\n                style={{\n                  height: '60px',\n                  padding: '15px 5px 15px 15px'\n                }}>\n                <button\n                  className='btn btn-primary btn-flat btn-sm'\n                  disabled={loadingParticipant && loadingParticipant === form._id ? true : false}\n                  onClick={() => this.props.getParticipant(form._id)}\n                >\n                  {\n                    loadingParticipant && loadingParticipant === form._id\n                      ?\n                      <><i className='fa fa-spin fa-spinner' /> Cargando...</>\n                      :\n                      <><i className='fa fa-fw fa-bar-chart' /> Detalle</>\n                  }\n                </button>\n              </div>\n              <div\n                className='col col-md-7 col-sm-7 col-xs-7 text-right text-muted text-sm'\n                style={{\n                  height: '60px',\n                  padding: '22px 15px 15px 5px'\n                }}>\n                <div>\n                  {\n                    form.user ?\n                      <React.Fragment>\n                        <i className='fa fa-user-o' /> {form.user.firstName} {form.user.lastName}\n                      </React.Fragment> : null\n                  }\n                </div>\n              </div>\n            </Row>\n          </div>\n        </div>\n      </li>\n    );\n  }\n\n\n  private getColorByDamage(hasDamages: boolean): string {\n    if (hasDamages) {\n      return 'bg-red';\n    } else {\n      return 'bg-green';\n    }\n  }\n\n  private getIconDamage(hasDamages: boolean): string {\n    if (hasDamages) {\n      return 'fa-warning';\n    } else {\n      return 'fa-check-square-o';\n    }\n  }\n\n  private getColor(form: any): string {\n    const { qualification } = form;\n    if (qualification <= 25) {\n      return 'bg-red';\n    } else if (qualification <= 50) {\n      return 'bg-orange';\n    } else if (qualification <= 75) {\n      return 'bg-yellow';\n    } else {\n      return 'bg-green';\n    }\n  }\n}\n\nexport default TimeLineForm;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport Row from '../Utils/Row';\nimport * as moment from 'moment-timezone';\n\ninterface IPropsType {\n  inventory: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass TimeLineInventory extends React.Component<IPropsType, IStateType> {\n\n  private iconStatus: any = {\n    pending: 'fa-clock-o',\n    found: 'fa-check',\n    leftover: 'fa-arrow-up',\n    missing: 'fa-arrow-down',\n    reported: 'fa-exclamation'\n  };\n\n  private classStatus: any = {\n    pending: 'bg-aqua',\n    found: 'bg-green',\n    missing: 'bg-red',\n    leftover: 'bg-yellow',\n    reported: 'bg-gray'\n  };\n\n  private classLabelStatus: any = {\n    pending: 'label-info',\n    found: 'label-success',\n    missing: 'label-danger',\n    leftover: 'label-warning',\n    reported: 'label-default'\n  };\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  render(): React.ReactElement<IPropsType> {\n    const { inventory } = this.props;\n    return (\n      <li style={{ marginRight: '0' }}>\n        <i className={`fa ${this.iconStatus[inventory.status]} ${this.classStatus[inventory.status]}`} />\n        <div className='timeline-item'>\n          <span className='time text-sm' style={{\n            color: '#888',\n            fontSize: '13px'\n          }}>\n            <div\n              className='text-muted text-sm' data-toggle='tooltip'\n              data-placement='top'\n              title={moment(inventory.createdAt).format('LLL')}\n            >\n                                <i className='fa fa-fw fa-clock-o' /> {moment(inventory.createdAt).fromNow()}\n                              </div>\n          </span>\n\n          <h3 className='timeline-header'><a href={`/inventory/${inventory.inventory._id}`} target='_blank'>{inventory.inventory.name}</a></h3>\n\n          <div className='timeline-body'>\n            {\n              ['found'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue encontrado en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment>\n                : null\n            }\n            {\n              ['pending'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo no fue encontrado en <span className='text-blue'>{inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['reported'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue reportado en <span className='text-blue'>{inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['missing'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue marcado como faltante en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n            {\n              ['leftover'].includes(inventory.status) ?\n                <React.Fragment>\n                  El vehículo fue marcado como sobrante en <span\n                  className='text-blue'>{inventory.venueFound ? inventory.venueFound.name : inventory.venue.name}</span>.\n                </React.Fragment> : null\n            }\n          </div>\n          <div className='timeline-footer'>\n            <Row>\n              <div\n                className='col col-md-5 col-sm-5 col-xs-5'\n                style={{\n                  height: '60px',\n                  padding: '15px 5px 15px 15px'\n                }}>\n                {this.status(inventory.status)}{' '}\n                {this.label(inventory.label, inventory.labelText)}\n              </div>\n              <div\n                className='col col-md-7 col-sm-7 col-xs-7 text-right text-muted text-sm'\n                style={{\n                  color: '#888',\n                  padding: '15px 15px 15px 5px'\n                }}>\n                {\n                  ['leftover', 'missing'].includes(inventory.status) && inventory.labelBy ?\n                    <React.Fragment>\n                      <i className='fa fa-user-o' /> {inventory.labelBy.firstName} {inventory.labelBy.lastName}\n                    </React.Fragment>\n                    : inventory.inventoriedBy ?\n                      <React.Fragment>\n                        <i className='fa fa-user-o' /> {inventory.inventoriedBy.firstName} {inventory.inventoriedBy.lastName}\n                      </React.Fragment> : null\n                }\n              </div>\n            </Row>\n          </div>\n        </div>\n      </li>\n    );\n  }\n\n  private label(label: any, labelText: string) {\n    if (label) {\n      const { sendTo } = label;\n      return (\n        <span\n          className={\n            `label ${this.classLabelStatus.hasOwnProperty(sendTo) ? this.classLabelStatus[sendTo] : ''}`\n          }\n          style={{\n            padding: '5px 10px'\n          }}\n        >\n          <i className={`fa fa-fw ${this.iconStatus[sendTo]}`} />\n          {label.name} {label.requireCustomText ? <span\n          data-toggle='tooltip'\n          data-placement='top'\n          title={labelText}>Ver más</span> : ''}\n        </span>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private status(status: string) {\n    return (\n      <span\n        className={`label ${this.classLabelStatus.hasOwnProperty(status) ? this.classLabelStatus[status] : ''}`}\n        style={{\n          padding: '5px 10px'\n        }}\n      >\n          {this.statusText.hasOwnProperty(status) ? this.statusText[status] : status}\n          </span>\n    );\n  }\n}\n\nexport default TimeLineInventory;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ColorForm = reduxForm({\n  form: 'colorForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ColorForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport { IColor } from '../../../../../../src/app/interfaces/color.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { ColorReduxActions, IColorState } from '../../actions/color.types';\nimport { createColorThunkAction, deleteColorThunkAction, getColorsThunkAction, updateColorThunkAction } from '../../actions/color.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport Paginator from '../Utils/Paginator';\nimport ColorForm from './ColorsFormView';\nimport ModalView from '../Modal/ModalView';\nimport * as moment from 'moment';\nimport * as swal from 'sweetalert';\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<ColorReduxActions | FormAction>;\n  colors: IColorState;\n\n  getColorThunkAction(colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): ColorReduxActions;\n\n  createColorThunkAction(color: IColor): ColorReduxActions;\n  updateColorThunkAction(color: IColor): ColorReduxActions;\n  deleteColorThunkAction(color: IColor): ColorReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass ColorListView extends TrackingBasePage<IPropsType, IStateType> {\n  private socket: Socket;\n\n  public title: string;\n  readonly state = {\n    error: null,\n    colorType: '',\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Colores';\n    this.changePage = this.changePage.bind(this);\n    this.createColor = this.createColor.bind(this);\n    this.processCreateColor = this.processCreateColor.bind(this);\n    this.updateColor = this.updateColor.bind(this);\n    this.processUpdateColor = this.processUpdateColor.bind(this);\n    this.deleteColor = this.deleteColor.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.colors;\n    const { orderBy, orderType } = this.props.colors.options;\n    const { colorType } = this.state;\n    this.props.getColorThunkAction(colorType, pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `color-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.colors;\n        const { orderBy, orderType } = this.props.colors.options;\n        const { colorType } = this.state;\n        this.props.getColorThunkAction(colorType, pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.colors.pagination !== prevProps.colors.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.colors.source) {\n      this.props.colors.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, colors, pagination } = this.props.colors;\n    // const isDevelopment = process.env.NODE_ENV === 'development';\n    const isDevelopment = false;\n    const canCreate = hasPermission(window.user, 'addColor') || isDevelopment;\n    const canUpdate = hasPermission(window.user, 'changeColor') || isDevelopment;\n    const canDelete = hasPermission(window.user, 'deleteColor') || isDevelopment;\n    return (\n      <AppContainer title='' cMenu='10' cSubMenu='10.10' cAction='Colors'>\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Colores <small>{pagination.count}</small></h3>\n              {\n                canCreate ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createColor}><i className=\"fa fa-plus\" /> Crear color</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '82%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '18%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      canUpdate ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      canDelete ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                {\n                  !loading && !colors.length ?\n                    <tr>\n                      <td\n                        colSpan={2 + (canUpdate ? 1 : 0) + (canDelete ? 1 : 0)}\n                      >\n                        No se han creado colores\n                      </td>\n                    </tr>\n                    : null\n                }\n                {\n                  colors.map((color)=>{\n                    return (\n                      <tr\n                          key={color._id}\n                          id={`color-${color._id}`}\n                          className={'background-transition'}\n                        >\n                        <td className=\"middle\">{color.name}</td>\n                        <td className='middle hidden-xs text-sm text-muted'>{moment(color.updatedAt).format('LLL')}</td>\n                        {\n                          canUpdate ?\n                            <td\n                              className='middle text-blue pointer'\n                              onClick={() => this.updateColor(color)}\n                            >\n                              <i className='fa fa-pencil' />\n                            </td> : null\n                        }\n                        {\n                          canDelete ?\n                            <td\n                              className={'middle text-red pointer'}\n                              onClick={() => this.deleteColor(color)}\n                            ><i className='fa fa-minus-circle' /></td> : null\n                        }\n                      </tr>\n                    )\n                  })\n                }\n                </tbody>\n              </table>\n            </div>\n             {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createColor(): void {\n    this.props.loadDataAction(\n      'Agregar Color',\n      <ColorForm\n        onSubmit={this.processCreateColor}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button\n          type='button' className='btn btn-sm btn-primary'\n          onClick={() => this.props.dispatch(submit('colorForm'))}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateColor(color: any){\n    this.props.createColorThunkAction(color);\n  }\n\n  private updateColor(color: any): void {\n    this.props.loadDataAction(\n      'Editar Color',\n      <ColorForm\n        initialValues={color}\n        onSubmit={this.processUpdateColor}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button\n          type='button' className='btn btn-sm btn-primary'\n          onClick={() => this.props.dispatch(submit('colorForm'))}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateColor(color: any): void {\n    this.props.updateColorThunkAction(color);\n  }\n\n  private deleteColor(color: any): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el color ${color.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteColorThunkAction(color);\n      }\n    });\n    // this.props.updateColorThunkAction(color);\n  }\n\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.colors.options;\n    const { colorType } = this.state;\n    this.props.getColorThunkAction(colorType, page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { colors: IColorState }) => {\n  return {\n    colors: state.colors\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getColorThunkAction: (colorType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getColorsThunkAction(colorType, nextPage, orderBy, orderType, hideLoading)),\n    createColorThunkAction: (color: IColor) => dispatch(createColorThunkAction(color)),\n    updateColorThunkAction: (color: IColor) => dispatch(updateColorThunkAction(color)),\n    deleteColorThunkAction: (color: IColor) => dispatch(deleteColorThunkAction(color)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ colors: IColorState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(ColorListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {IBaseCompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {\n  changeTempCompanyAction,\n  CompaniesReduxAction,\n  ICompaniesState\n} from '../../actions/companies.actions';\nimport ImageLazyLoad from '../Utils/ImageLazyLoad';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport * as uuid from 'uuid';\n\ninterface IPropsType {\n  companies?: ICompaniesState;\n  changeTempCompanyAction?: (company: IBaseCompany) => CompaniesReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  tmpReceiver: any;\n}\n\nclass CompaniesFormView extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    tmpReceiver:{\n      name: '',\n      email: ''\n    }\n  };\n  readonly inputImage: React.RefObject<HTMLInputElement>;\n  readonly inputMarker: React.RefObject<HTMLInputElement>;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.handleAddReceiver = this.handleAddReceiver.bind(this);\n    this.handleRemoveReceiver = this.handleRemoveReceiver.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.inputImage = React.createRef();\n    this.inputMarker = React.createRef();\n  }\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.companies && this.props.changeTempCompanyAction) {\n      const {tempCompany} = this.props.companies;\n      const {changeTempCompanyAction} = this.props;\n      const {tmpReceiver} = this.state;\n      return (\n        <React.Fragment>\n          <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n            <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n            <li><a data-toggle=\"tab\" href=\"#billing\">Billing</a></li>\n            <li><a data-toggle=\"tab\" href=\"#customizations\">Personalizaciones</a></li>\n          </ul>\n          <div className=\"tab-content\">\n            <div id=\"general\" className=\"tab-pane fade in active\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.name : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          name: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Razón social</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.businessName : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          businessName: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>RUT</label>\n                    <input\n                      type=\"text\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.rut : ''}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          rut: e.target.value.trim()\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group-switch\">\n                    <BootstrapSwitch\n                      checked={tempCompany.billing.active}\n                      color=\"blue\"\n                      onChange={() => {\n                        changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            active: !tempCompany.billing.active\n                          }\n                        });\n                      }}/>\n                    <label className=\"switch-label\">Activar billing</label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div id=\"billing\" className=\"tab-pane fade\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Precio Inventario</label>\n                    <input\n                      type=\"number\"\n                      name=\"inventoryPrice\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.inventoryPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            inventoryPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Precio Entregas</label>\n                    <input\n                      type=\"number\"\n                      name=\"requestDeliveryPrice\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.deliveryPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            deliveryPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Precio Checklist</label>\n                    <input\n                      type=\"number\"\n                      name=\"checklistPrice\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.checklistPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            checklistPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Precio Solicitudes</label>\n                    <input\n                      type=\"number\"\n                      name=\"fistName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      defaultValue={tempCompany ? tempCompany.billing.requestPrice : '0.0'}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => changeTempCompanyAction({\n                          ...tempCompany,\n                          billing: {\n                            ...tempCompany.billing,\n                            requestPrice: parseFloat(e.target.value.trim())\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12\">\n                  <strong style={{color: '#2372bb'}}>Notificaciones</strong>\n                  <table className=\"table table-striped\">\n                    <thead>\n                    <tr>\n                      <th>Nombre</th>\n                      <th>Email</th>\n                      <th/>\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      !tempCompany.notifications.length ?\n                        <tr>\n                          <td colSpan={3} className={'text-center'}>\n                            <strong>No se han agregado destinatarios</strong>\n                          </td>\n                        </tr> :\n                        null\n                    }\n                    {\n                      tempCompany.notifications.map((notification) => (\n                        <tr key={notification._id ? notification._id : notification.tempID}>\n                          <td width={'45%'}>{notification.name}</td>\n                          <td width={'45%'}>{notification.email}</td>\n                          <td\n                            className={'text-center'}\n                          >\n                            <i\n                              className=\"fa fa-minus-circle text-red\"\n                              onClick={() => this.handleRemoveReceiver(notification._id || notification.tempID)}\n                            />\n                          </td>\n                        </tr>\n                      ))\n                    }\n                    </tbody>\n                  </table>\n                  {/*<div className=\"alert alert-info alert-dismissible\">*/}\n                  {/*  <p>Estos son los destinatarios que recibiran un correo mensual con el informe de billing.</p>*/}\n                  {/*</div>*/}\n                </div>\n                <div className=\"col-md-5\">\n                  <div className=\"form-group\">\n                    <label>Nombre</label>\n                    <input\n                      type=\"text\"\n                      name=\"receiverName\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tmpReceiver.name}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => this.setState({\n                          tmpReceiver: {\n                            ...this.state.tmpReceiver,\n                            name: e.target.value\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-7\">\n                  <div className=\"form-group\">\n                    <label>Email</label>\n                    <input\n                      type=\"text\"\n                      name=\"receiverEmail\"\n                      className=\"form-control\"\n                      maxLength={50}\n                      value={tmpReceiver.email}\n                      onChange={\n                        (e: React.ChangeEvent<HTMLInputElement>) => this.setState({\n                          tmpReceiver: {\n                            ...this.state.tmpReceiver,\n                            email: e.target.value.trim()\n                          }\n                        })\n                      }\n                    />\n                  </div>\n                </div>\n                <div className=\"col-md-12 text-right\">\n                  <button\n                    className=\"btn btn-sm btn-success\"\n                    onClick={this.handleAddReceiver}\n                  >\n                    Agregar Destinatario\n                  </button>\n                </div>\n              </div>\n            </div>\n            <div id=\"customizations\" className=\"tab-pane fade\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div className=\"form-group\">\n                    <label>Imagen</label>\n                    {\n                      tempCompany.imageURI ?\n                        <div\n                          className=\"change-image-wrapper text-center\"\n                          style={{display: 'table', width: '100%', color: '#2776b8'}}\n                          onClick={() => this.clickUploadFile('inputImage')}\n                        >\n                          <ImageLazyLoad\n                            url={tempCompany.imageURI}\n                            height={'200px'}\n                            style={{\n                              maxWidth: '100%',\n                              maxHeight: '200px'\n                            }}\n                          />\n                          <div className=\"text-layer pointer\">\n                            <p className=\"text\">\n                              <i className=\"fa fa-2x fa-cloud-upload\"/> <br/>Haz click aquí para cambiar la imágen.\n                            </p>\n                          </div>\n                        </div> :\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={() => this.clickUploadFile('inputImage')}\n                          onDrop={(e) => this.handleDrop(e, 'image')}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando la imágen aquí, o haz click para seleccionar la imágen a cargar.\n                        </div>\n                    }\n                    <input\n                      type=\"file\"\n                      accept=\"image/*\"\n                      ref={this.inputImage}\n                      style={{display: 'none'}}\n                      onChange={(e) => this.handleChangeInputFile(e, 'image')}\n                    />\n                  </div>\n                  <div className=\"form-group\">\n                    <label>Marcador de Mapa</label>\n                    {\n                      tempCompany.markerURI ?\n                        <div\n                          className=\"change-image-wrapper text-center\"\n                          style={{display: 'table', width: '100%', color: '#2776b8'}}\n                          onClick={() => this.clickUploadFile('inputMarker')}\n                        >\n                          <ImageLazyLoad\n                            url={tempCompany.markerURI}\n                            height={'100px'}\n                            style={{\n                              maxWidth: '100px'\n                            }}\n                          />\n                          <div className=\"text-layer pointer\">\n                            <p className=\"text\">\n                              <i className=\"fa fa-2x fa-cloud-upload\"/> <br/>Haz click aquí para cambiar la imágen.\n                            </p>\n                          </div>\n                        </div> :\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={() => this.clickUploadFile('inputMarker')}\n                          onDrop={(e) => this.handleDrop(e, 'marker')}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '24px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px',\n                            height: '100px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando la imágen aquí, o haz click para seleccionar la imágen a cargar.\n                        </div>\n                    }\n                    <input\n                      type=\"file\"\n                      accept=\"image/*\"\n                      ref={this.inputMarker}\n                      style={{display: 'none'}}\n                      onChange={(e) => this.handleChangeInputFile(e, 'marker')}\n                    />\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n        </React.Fragment>\n      );\n    }\n    return null;\n  }\n\n  private handleAddReceiver(){\n    const {tmpReceiver} = this.state;\n    this.props.changeTempCompanyAction!({\n      ...this.props.companies!.tempCompany,\n      notifications: [...this.props.companies!.tempCompany.notifications!, {\n        ...tmpReceiver,\n        tempID: uuid.v1()\n      }]\n    });\n    this.setState({\n      tmpReceiver: {\n        name: '',\n        email: ''\n      }\n    });\n  }\n\n  private handleRemoveReceiver(id: any) {\n    this.props.changeTempCompanyAction!({\n      ...this.props.companies!.tempCompany,\n      notifications: this.props.companies!.tempCompany.notifications!.filter((notification) => {\n        return notification._id !== id && notification.tempID !== id;\n      })\n    });\n  }\n\n  private clickUploadFile(input: 'inputImage' | 'inputMarker') {\n    if (this[input].current) {\n      this[input].current!.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>, input: 'marker' | 'image'): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processFile(file, input);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processFile(file, input);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>, input: 'marker' | 'image' ) {\n    const {files} = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      this.processFile(file, input);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private processFile(file: File, input: 'marker' | 'image'): void {\n    if (file && this.props.companies && this.props.changeTempCompanyAction) {\n      const {tempCompany} = this.props.companies;\n      const {changeTempCompanyAction} = this.props;\n      const reader: FileReader = new FileReader();\n      reader.onload = (e: ProgressEvent) => {\n        if (e.target) {\n          changeTempCompanyAction({\n            ...tempCompany,\n            [`${input}URI`]: (e.target as any).result,\n            [input]: file\n          });\n        }\n      };\n      reader.readAsDataURL(file);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { companies: ICompaniesState }) => {\n  return {\n    companies: state.companies\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempCompanyAction: (company: IBaseCompany) => dispatch(changeTempCompanyAction(company))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(CompaniesFormView);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseCompany, ICompany} from '../../../../../../src/app/interfaces/company.interface';\nimport {\n  changeTempCompanyAction,\n  CompaniesReduxAction,\n  createCompanyAction, deleteCompanyAction,\n  getCompaniesAction,\n  ICompaniesState,\n  updateCompanyAction\n} from '../../actions/companies.actions';\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport CompaniesFormView from './CompaniesFormView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ company: string }> {\n  dispatch: Dispatch<CompaniesReduxAction>;\n  companies: ICompaniesState;\n\n  getCompaniesAction(page: number): CompaniesReduxAction;\n  createCompanyAction(): CompaniesReduxAction;\n  updateCompanyAction(): CompaniesReduxAction;\n  deleteCompanyAction(id?: string): CompaniesReduxAction;\n  changeTempCompanyAction(company: IBaseCompany): CompaniesReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass CompaniesListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de empresas';\n    this.addCompany = this.addCompany.bind(this);\n    this.processAddCompany = this.processAddCompany.bind(this);\n    this.udpateCompany = this.udpateCompany.bind(this);\n    this.processUpdateCompany = this.processUpdateCompany.bind(this);\n    this.deleteCompany = this.deleteCompany.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.companies;\n    this.props.getCompaniesAction(pagination.page);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.companies.source) {\n      this.props.companies.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, companies, pagination} = this.props.companies;\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.0\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Empresas <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addCompany') ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.addCompany}><i className=\"fa fa-plus\" /> Crear empresa</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    {/*<th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>*/}\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10 hidden-xs\">Inventario</th> : null\n                    }\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10 hidden-xs\">Entregas</th> : null\n                    }\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10 hidden-xs\">Checklist</th> : null\n                    }\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10 hidden-xs\">Solicitudes</th> : null\n                    }\n                    {\n                      window.user.isAdmin ?\n                        <th style={{width: '1%'}} className=\"width-10\">Billing</th> : null\n                    }\n                    {\n                      hasPermission(window.user, 'changeCompany') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      hasPermission(window.user, 'deleteCompany') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    companies.map((company: ICompany) => {\n                      return (\n                        <tr\n                          key={company._id}\n                          id={`company-${company._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">\n                            <strong className='text-primary'>{company.name}</strong> <br/>\n                            <span className=\"text-sm text-muted\">\n                              {company?.businessName ?? ''} - {company?.rut ?? ''}\n                            </span>\n                          </td>\n                          {/*<td className=\"middle hidden-xs\">{moment(company.updatedAt).format('LLL')}</td>*/}\n                          {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center hidden-xs\">\n                                {\n                                  company.billing.inventoryPrice ? `${company.billing.inventoryPrice?.toFixed(4)}UF` : '-'\n                                }\n                              </td> : null\n                          }\n                           {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center hidden-xs\">\n                                {\n                                  company.billing.deliveryPrice ? `${company.billing.deliveryPrice?.toFixed(4)}UF` : '-'\n                                }\n                              </td> : null\n                          }\n                          {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center hidden-xs\">\n                                {\n                                  company.billing.checklistPrice ? `${company.billing.checklistPrice?.toFixed(4)}UF` : '-'\n                                }\n                              </td> : null\n                          }\n                          {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center hidden-xs\">\n                                {\n                                  company.billing.requestPrice ? `${company.billing.requestPrice?.toFixed(4)}UF` : '-'\n                                }\n                              </td> : null\n                          }\n\n                          {\n                            window.user.isAdmin ?\n                              <td className=\"middle text-center\">\n                                <i\n                                  className={\n                                    company.billing.active ?\n                                      'fa fa-check-circle text-green':\n                                      'fa fa-times-circle text-red'\n                                  }\n                                />\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'changeCompany') ?\n                              <td\n                                className=\"middle text-blue pointer\"\n                                onClick={() => this.udpateCompany(company)}>\n                                <i className=\"fa fa-pencil\"/>\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteCompany') ?\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteCompany(company)}\n                              ><i className=\"fa fa-minus-circle\"/></td> : null\n                          }\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.props.getCompaniesAction} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addCompany(): void {\n    this.props.changeTempCompanyAction({\n      _id: '',\n      name: '',\n      businessName: '',\n      rut: '',\n      image: null,\n      marker: null,\n      markerURI: '/static/images/files/pin_osa.svg',\n      billing: {\n        active: false,\n        checklistPrice: 0.0,\n        inventoryPrice: 0.0,\n        requestPrice: 0.0,\n        deliveryPrice: 0.0\n      },\n      notifications: []\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Empresa',\n        <CompaniesFormView />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processAddCompany}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processAddCompany(): void {\n    const {tempCompany} = this.props.companies;\n    if (!tempCompany.name || !tempCompany.name.trim()) {\n      swal('Agregar empresa', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createCompanyAction();\n    }\n  }\n\n  private udpateCompany(company: ICompany): void {\n    const {_id, name, businessName, rut, billing, marker, image, notifications} = company;\n    this.props.changeTempCompanyAction({\n      _id,\n      name,\n      businessName,\n      rut,\n      image: null,\n      marker: null,\n      imageURI: image && image.hasOwnProperty('url') ? decodeURI(image.url) : null,\n      markerURI: marker && marker.hasOwnProperty('url') ? decodeURI(marker.url) : '/static/images/files/pin_osa.svg',\n      billing,\n      notifications\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Editar Empresa',\n        <CompaniesFormView />,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateCompany}>Editar</button>\n        </React.Fragment>\n      );\n    }, 400);\n  }\n\n  private processUpdateCompany(): void {\n    const {name} = this.props.companies.tempCompany;\n    if (!name || !name.trim()) {\n      swal('Editar Empresa', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateCompanyAction();\n    }\n  }\n\n  private deleteCompany(company: ICompany): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la empresa ${company.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteCompanyAction(company._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { companies: ICompaniesState }) => {\n  return {\n    companies: state.companies\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getCompaniesAction: (page: number) => dispatch(getCompaniesAction(page)),\n    createCompanyAction: () => dispatch(createCompanyAction()),\n    updateCompanyAction: () => dispatch(updateCompanyAction()),\n    deleteCompanyAction: (id: string) => dispatch(deleteCompanyAction(id)),\n    changeTempCompanyAction: (company: IBaseCompany) => dispatch(changeTempCompanyAction(company)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{companies: ICompaniesState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(CompaniesListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport {CompaniesReduxAction, ICompaniesState} from \"../../actions/companies.actions\";\nimport {connect} from \"react-redux\";\nimport {IWindow} from \"../../interfaces/window\";\n\ndeclare let window: IWindow;\n\nexport interface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<CompaniesReduxAction>;\n  dashboard: ICompaniesState;\n}\n\ninterface IStateType {\n  error: Error | null;\n  showDrilldown: boolean,\n  selectedDate: string | null,\n  from: Date,\n  to: Date,\n}\n\nexport class DashboardTimingView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n  public cMenu  : string = \"1\";\n  public cSubMenu  : string = \"1.7\";\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reporte personalizado';\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public getDashboardURL() : string{\n    return window.user.company.iFrameURL;\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    return (\n      <AppContainer title=\"\" cMenu={this.cMenu} cSubMenu={this.cSubMenu}>\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h1 className=\"box-title\">Dashboard de análisis de datos</h1>\n                </div>\n                <div className=\"box-body\">\n                  <iframe src={this.getDashboardURL()} style={{width: \"100%\", minWidth: \"1000px\" ,minHeight: \"500px\", height: \"100vh\"}} allowFullScreen={true}  frameBorder={0} security={\"\"}/>\n                </div>\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { dashboardTiming: ICompaniesState }) => {\n  return {\n    dashboard: state.dashboardTiming\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardTimingView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as moment from 'moment';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { DashboardReduxAction } from '../../actions/dashboard.actions';\nimport { getDashboardDamagesPerVenue, IDashboardDamagesState } from '../../actions/dashboardDamages.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport { IWindow } from '../../interfaces/window';\nimport * as swal from 'sweetalert';\nimport { default as Axios } from 'axios';\nimport ApiService from '../../utils/axios';\nimport { hasPermission } from '../../utils/common';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardDamagesState;\n\n  getDashboardDamagesPerVenue(update?: boolean): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  detail: boolean;\n  detailName: string;\n  exporting: boolean\n}\n\nclass DashboardDamagesView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly state: IStateType = {\n    error: null,\n    detail: false,\n    detailName: '',\n    exporting: false,\n  };\n  protected damagesPerVenueChart: echarts.ECharts;\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de daños';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.showdetail = this.showdetail.bind(this);\n    this.back = this.back.bind(this);\n    this.updateDamagesPerVenueChart = this.updateDamagesPerVenueChart.bind(this);\n    this.exportDamages = this.exportDamages.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getDashboardDamagesPerVenue(true);\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `dashboard-vin-view-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        this.props.getDashboardDamagesPerVenue();\n      }\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $damagesPerVenue = document.getElementById('damages-per-venue') as HTMLDivElement;\n    this.damagesPerVenueChart = echarts.init($damagesPerVenue);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    this.updateDamagesPerVenueChart();\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    this.socket.disconnect();\n  }\n\n  public exportDamages() {\n    this.setState({\n      exporting: true\n    });\n    this.trackClick(\"Exportar\");\n    const api: ApiService = new ApiService();\n    const instance = api.getInstance();\n    instance.defaults.responseType = 'blob';\n    instance\n      .get(`/api/damages/export/`)\n      .then((response) => {\n        const blob = new Blob([response.data], {\n          type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n        });\n        const fileName = `${moment().format('YYYYMMDD')}-danos.xlsx`;\n        // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n        //   // IE workaround for \"HTML7007: One or more blob URLs were\n        //   // revoked by closing the blob for which they were created.\n        //   // These URLs will no longer resolve as the data backing\n        //   // the URL has been freed.\"\n        //   window.navigator.msSaveBlob(blob, fileName);\n        // } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          this.setState({\n            exporting: false\n          });\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n        // }\n      })\n      .catch((err) => {\n        this.setState({\n          exporting: false\n        });\n        if (!Axios.isCancel(err)) {\n          swal('Exportar daños', 'Ha ocurrido un error al general el excel.', 'error');\n        }\n      });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading} = this.props.dashboard;\n    const {detail, detailName, exporting} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.4\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Dashboard de daños</h3>\n                  {\n                    false && hasPermission(window.user, 'exportDamages') ?\n                    <div className='box-tools pull-right'>\n                      <button\n                        className='btn btn-sm btn-primary hidden-xs hidden-sm'\n                        onClick={this.exportDamages}\n                        disabled={exporting}\n                      >\n                        {\n                          exporting ?\n                            <React.Fragment>\n                              <i className='fa fa-fw fa-spinner fa-spin'></i> Exportando reporte\n                            </React.Fragment>\n                            :\n                            <React.Fragment>\n                              <i className='fa fa-fw fa-download'></i> Exportar reporte\n                            </React.Fragment>\n                        }\n                      </button>\n                    </div>\n                    :\n                    null\n                  }\n                </div>\n                <div className=\"box-body\">\n                  {\n                    detail ?\n                      <div className=\"text-center\">\n                        <h4 className=\"text-muted\" style={{margin: '0 5px'}}>Detalle del {detailName}</h4>\n                        <p className=\"text-muted\">Para volver al detalle por día haz <a\n                          href=\"javascript:void(0)\"\n                          onClick={this.back}\n                        >click aquí</a></p>\n                      </div> :\n                      <div className=\"text-center\">\n                        <h4 className=\"text-muted\" style={{margin: '0 5px'}}>Detalle de daños por día</h4>\n                        <p className=\"text-muted\">Haz click sobre una barra para ver el detalle por sucursales</p>\n                      </div>\n                  }\n                  <div id=\"damages-per-venue\" style={{height: '70vh', maxWidth: '100%'}}/>\n\n                </div>\n                {\n                  loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private updateDamagesPerVenueChart() {\n    const {loading} = this.props.dashboard;\n    if (!loading) {\n      const {data} = this.props.dashboard;\n      const {detail, detailName} = this.state;\n      let damages = [],\n          undamages = [];\n      let category = Object.keys(data).reverse();\n      if (detail) {\n        let detailData = [];\n        for(const key in data[detailName]){\n          if ( data[detailName].hasOwnProperty(key) && !['damaged', 'undamaged'].includes(key)) {\n            const venue = data[detailName][key];\n            detailData.push(venue)\n          }\n        }\n        detailData = detailData.sort((a, b) => (a.name > b.name) ? 1 : ((b.name > a.name) ? -1 : 0));\n        const detailCategories = [];\n        for (const venue of detailData) {\n            detailCategories.push(venue.name);\n            damages.push(venue.damaged);\n            undamages.push(venue.undamaged);\n        }\n        category = detailCategories;\n      } else {\n        for (const key in data) {\n          if (data.hasOwnProperty(key)) {\n            const day = data[key];\n            damages.push(day.damaged);\n            undamages.push(day.undamaged);\n          }\n        }\n        damages = damages.reverse()\n        undamages = undamages.reverse()\n      }\n\n      const option: echarts.EChartOption = {\n        color: ['#00aa51', '#f1392c'],\n        tooltip: {\n          trigger: 'axis',\n          axisPointer: {\n            type: 'shadow'\n          }\n        },\n        legend: {\n          data: ['Sin daños', 'Con daños'],\n          // x: 'center',\n          bottom: 50,\n        },\n        xAxis: {\n          type: 'category',\n          axisTick: {show: false},\n          data: category,\n          axisLine: {\n            lineStyle: {\n              color: 'rgba(0, 0, 0, 0.5)'\n            }\n          },\n          splitLine: {\n            show: false,\n            lineStyle: {\n              type: 'dashed',\n              color: 'rgba(150, 150, 150, 0.5)'\n            }\n          },\n          axisLabel: {\n            rotate: 60,\n            fontSize: 10,\n            formatter: function (value: string) {\n              let text = '';\n              const array = value.split(\" \");\n              for (let i = 0; i < array.length; i++) {\n                text += `${array[i]}`;\n                if (i > 0 && i % 2 !== 0) {\n                  text += ' \\n';\n                } else {\n                  text += ' ';\n                }\n              }\n              return text;\n            }\n          }\n        },\n        grid: {\n          top: 10,\n          bottom: 100,\n          // left\n          left: 5,\n          // right\n          right: 10,\n          containLabel: true\n        },\n        yAxis: [\n          {\n            minInterval: 1,\n            type: 'value',\n            axisLine: {\n              lineStyle: {\n                color: 'rgba(0, 0, 0, 0.5)'\n              }\n            },\n            splitLine: {\n              show: true,\n              lineStyle: {\n                type: 'dashed',\n                color: 'rgba(150, 150, 150, 0.5)'\n              }\n            }\n          }\n        ],\n        series: [\n          {\n            name: 'Sin daños',\n            type: 'bar',\n            barGap: \"0.1\",\n            barMaxWidth: 50,\n            data: undamages\n          },\n          {\n            name: 'Con daños',\n            type: 'bar',\n            barGap: \"0.1\",\n            barMaxWidth: 50,\n            data: damages\n          }\n        ],\n        dataZoom: [{\n          show: true,\n          realtime: true,\n          start: 0,\n          end: 100\n        }]\n      };\n      this.damagesPerVenueChart.setOption(option);\n      this.damagesPerVenueChart.off('click');\n      this.damagesPerVenueChart.on('click', (params: any) => {\n        this.showdetail(params.name);\n      });\n    }\n  }\n\n  private back(){\n    this.setState({detail: false, detailName: ''})\n  }\n\n  private showdetail(name: string){\n    const {detail} =this.state;\n    const {data} = this.props.dashboard;\n    if(!detail && data.hasOwnProperty(name)){\n      const day = data[name];\n      if(day.damaged || day.undamaged){\n        this.setState({\n          detailName: name,\n          detail: true\n        })\n      }\n    }\n  }\n\n  private resizeCharts() {\n    if (this.damagesPerVenueChart) {\n      this.damagesPerVenueChart.resize();\n      setTimeout(() => {\n        this.damagesPerVenueChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardDamages: IDashboardDamagesState }) => {\n  return {\n    dashboard: state.dashboardDamages\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardDamagesPerVenue: (update?: boolean) => dispatch(getDashboardDamagesPerVenue(update))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardDamagesView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {DashboardReduxAction} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport {getDashboardCleaning, IDashboardDercoState} from \"../../actions/dashboardDerco.actions\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardDercoState;\n\n  getDashboardCleaning(): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass DashboardDercoView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  cleaningPerDayChart: echarts.ECharts;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de daños';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateCleaningPerDayChart = this.updateCleaningPerDayChart.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getDashboardCleaning();\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $cleaningPerDayChart = document.getElementById('cleaning-per-day') as HTMLDivElement;\n    this.cleaningPerDayChart = echarts.init($cleaningPerDayChart);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n\n    const { cleaning } = this.props.dashboard;\n    if (!cleaning.loading) {\n      this.updateCleaningPerDayChart();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { cleaning } = this.props.dashboard;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.4\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\"># Unidades con daños por sucursal</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"cleaning-per-day\" style={{height: '50vh', maxWidth: '100%'}} />\n                </div>\n                {\n                  cleaning.loading &&\n                  <div className=\"overlay\">\n                    <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private updateCleaningPerDayChart() {\n\n    const { cleaning } = this.props.dashboard;\n\n    const option: any = {\n      color: ['#00aa51', '#f1392c'],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['Sin daños', 'Con daños'],\n        x: 'center',\n        bottom: 50\n      },\n      xAxis: {\n        data: cleaning.days,\n        axisLabel: {\n          rotate: 60\n        }\n\n      },\n      yAxis: {\n        // type: 'category',\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        x: 20,\n        // right\n        x2: 10,\n        containLabel: true\n      },\n      series: [\n        {\n          name: 'Limpios',\n          type: 'bar',\n          data: cleaning.clean,\n          stack: '1'\n        },\n        {\n          name: 'Con daños',\n          type: 'bar',\n          data: cleaning.notClean,\n          stack: '1'\n        }\n      ]\n    };\n    this.cleaningPerDayChart.setOption(option);\n\n  }\n\n  private resizeCharts() {\n    if (this.cleaningPerDayChart) {\n      this.cleaningPerDayChart.resize();\n      setTimeout(() => {\n        this.cleaningPerDayChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardDerco: IDashboardDercoState }) => {\n  return {\n    dashboard: state.dashboardDerco\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardCleaning: () => dispatch(getDashboardCleaning())\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardDercoView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {DashboardReduxAction, getParticipantsPerDateAction, IDashboardState} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { hasPermission } from '../../utils/common';\nimport { IWindow } from '../../interfaces/window';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n\n  getParticipantsPerDateAction(companies?:string): void;\n}\n\ninterface IStateType {\n  selectedCompanies: any[];\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass DashboardGeneralView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   dashboard: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired,\n  //   getParticipantsPerDateAction: PropTypes.func.isRequired\n  // };\n  readonly state = {\n    error: null,\n    selectedCompanies: ['']\n  };\n\n  participantsPerDayChart: echarts.ECharts;\n  participantsRangeChart: echarts.ECharts;\n  carsByVenueChart: echarts.ECharts;\n\n  // chartsColors: string[] = ['#3085c1', '#5c4b55', '#55b188', '#4d5c99', '#c53e5a', '#f8d991'];\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportes generales';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateParticipantsChart = this.updateParticipantsChart.bind(this);\n    this.updateCarsChart = this.updateCarsChart.bind(this);\n    this.updateChartParticipantRange = this.updateChartParticipantRange.bind(this);\n    this.filterCompanies = this.filterCompanies.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    this.props.getParticipantsPerDateAction();\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $participantPerDate = document.getElementById('participant-per-date') as HTMLDivElement;\n    const $participantRange = document.getElementById('participant-range') as HTMLDivElement;\n    const $carsByVenue = document.getElementById('cars-by-venue') as HTMLDivElement;\n    this.participantsPerDayChart = echarts.init($participantPerDate);\n    this.carsByVenueChart = echarts.init($carsByVenue);\n    this.participantsRangeChart = echarts.init($participantRange);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const {loading} = this.props.dashboard;\n    if (!loading) {\n      this.updateParticipantsChart();\n      // this.updateCarsChart();\n      this.updateChartParticipantRange();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loading, participantsReceivedPerDate, participantsSentPerDate, carsPerDate, totalCars, companies\n    } = this.props.dashboard;\n    const {selectedCompanies} = this.state;\n\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.1\">\n        <section className=\"content\">\n          <Row>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-aqua\"><i className=\"fa fa-clipboard\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Revisiones Hoy</span>\n                  <span className=\"info-box-number\">\n                    {(participantsReceivedPerDate.length ? participantsReceivedPerDate[participantsReceivedPerDate.length - 1 ].total : 0) +participantsSentPerDate.length ? participantsSentPerDate[participantsSentPerDate.length - 1 ].total : 0 }\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-yellow\"><i className=\"fa fa-check-square\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Cargados Hoy</span>\n                  <span className=\"info-box-number\">{carsPerDate.length ? carsPerDate[carsPerDate.length - 1 ].total : 0}</span>\n                </div>\n              </div>\n            </div>\n            <div className=\"col-md-3 col-sm-6 col-xs-12\">\n              <div className=\"info-box\">\n                <span className=\"info-box-icon bg-green\"><i className=\"fa fa-car\"/></span>\n                <div className=\"info-box-content\">\n                  <span className=\"info-box-text\">Total Cargas</span>\n                  <span className=\"info-box-number\">{new Intl.NumberFormat('es-CL').format(totalCars)}</span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row>\n            <div className=\"col-md-12\">\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Revisiones y cargas realizadas por día</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div className=\"row\">\n                    <div className=\"col-md-8\" />\n                    <div className=\"col-md-4\">\n                      <BootstrapSelect\n                        noneSelectedText=\"Todas las empresas\"\n                        displayItems={2}\n                        selectedText=\"empresas seleccionadas.\"\n                        selected={selectedCompanies}\n                        autoClouse={true}\n                        allOption={false}\n                        selectAll={() => ({})}\n                        options={[{value: '', text: 'Todas las empresas'},\n                          ...companies.map((company: any) => ({\n                          value: company._id,\n                          text: company.name\n                        }))]}\n                        onClick={this.filterCompanies}\n                      />\n                    </div>\n                    <div className=\"col-md-12\">\n                      <div id=\"participant-per-date\" style={{height: '450px', maxWidth: '100%'}}/>\n                    </div>\n                  </div>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n            <div className=\"col-md-12\" style={{display: 'none'}}>\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Histograma cumplimiento de revisiones</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"participant-range\" style={{height: '400px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n            <div className=\"col-md-8\" style={{display: 'none'}}>\n              <div className=\"box\">\n                <div className=\"box-header with-border\"><h3 className=\"box-title\">Vehiculos por sucursal</h3>\n                  <div className=\"box-tools pull-right\">\n                  </div>\n                </div>\n                <div className=\"box-body\">\n                  <div id=\"cars-by-venue\" style={{height: '500px', maxWidth: '100%'}}/>\n                </div>\n                {\n                  loading &&\n                    <div className=\"overlay\">\n                      <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                    </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterCompanies(value: any) {\n    this.props.getParticipantsPerDateAction(value);\n    this.setState({\n      selectedCompanies: [value]\n    });\n  }\n\n  private updateParticipantsChart() {\n    const {\n      participantsReceivedPerDate,participantsSentPerDate, carsPerDate,\n      planningPerDate, planningProcessPerDate\n    } = this.props.dashboard;\n    const categories: any[] = [];\n    const totalsReceived: any[] = [];\n    const totalsSent: any[] = [];\n    const totalsCars: any[] = [];\n    const totalsPlanning: any[] = [];\n    const totalsplanningProcess: any[] = [];\n\n    if (participantsReceivedPerDate.length) {\n      participantsReceivedPerDate.forEach((day) => {\n        categories.push(day._id);\n        totalsReceived.push(day.total);\n      });\n    }\n    if (participantsSentPerDate.length) {\n      participantsSentPerDate.forEach((day) => {\n        totalsSent.push(day.total);\n      });\n    }\n    if (carsPerDate.length) {\n      carsPerDate.forEach((day) => {\n        totalsCars.push(day.total);\n      });\n    }\n    if (planningPerDate.length) {\n      planningPerDate.forEach((day) => {\n        totalsPlanning.push(day.total);\n      });\n    }\n    if (planningProcessPerDate.length) {\n      planningProcessPerDate.forEach((day) => {\n        totalsplanningProcess.push(day.total);\n      });\n    }\n    const dataLabels = ['Recepciones', 'Envíos'];\n    const series = [{\n      data: totalsReceived,\n      name: 'Recepciones',\n      type: 'line',\n      color: '#337AB7',\n      smooth: true\n    }, {\n      data: totalsSent,\n      name: 'Envíos',\n      type: 'line',\n      color: '#2DB06B',\n      smooth: true\n    }, {\n      data: totalsCars,\n      name: 'Cargados',\n      type: 'line',\n        color: '#678099',\n        smooth: true\n      }];\n\n    if (hasPermission(window.user, 'viewPlanning')) {\n      dataLabels.push('Planificados', 'Linea de control');\n      series.push({\n        data: totalsPlanning,\n        name: 'Planificados',\n        type: 'line',\n        color: '#00b5fd',\n        smooth: true\n      });\n      series.push({\n        data: totalsplanningProcess,\n        name: 'Linea de control',\n        type: 'line',\n        color: '#a1214c',\n        smooth: true\n      });\n    }\n    dataLabels.push('Cargados');\n    // const option: echarts.EChartOption = {\n    const option: any = {\n      // title: {\n      //   text: 'Revisiones y cargas realizadas por día',\n      //   x: 'center',\n      //   textStyle: {\n      //     align: 'center'\n      //   }\n      // },\n      tooltip: {\n        trigger: 'axis'\n      },\n      legend: {\n        x: 'center',\n        bottom: 60,\n        // y: 'bottom',\n        data: dataLabels\n      },\n      xAxis: {\n        type: 'category',\n        boundaryGap: false,\n        data: categories,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: false,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 60\n          // fontSize: 10\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 80,\n        // left\n        x: 20,\n        // right\n        x2: 20,\n        containLabel: true\n        // borderColor: '#FF0000'\n      },\n      dataZoom: {\n        show: true,\n        realtime: true,\n        start: 0,\n        end: 100\n      },\n      series\n    };\n    this.participantsPerDayChart.setOption(option);\n  }\n\n  private updateChartParticipantRange() {\n    const {participantPerRange} = this.props.dashboard;\n    const legends: any[] = [];\n    const proyectionInterval = 5;\n    const totals: any[] = [];\n    for (let i = 0; i < 100; i += proyectionInterval) {\n      const max = i + proyectionInterval;\n      const key = `${i}-${max}`;\n      legends.push(key);\n      const value = participantPerRange.find((range) => (range._id === key));\n      if (value) {\n        totals.push(value.count);\n      } else {\n        totals.push(0);\n      }\n      // proyection.push({$cond: [{$and: [{$gte: ['$qualification', i]}, {$lte: ['$qualification', max]}]}, `${i}-${max}`, '']});\n    }\n    // const option: echarts.EChartOption | any = {\n    const option: any = {\n      tooltip: {\n        trigger: 'axis'\n      },\n      xAxis: {\n        type: 'category',\n        // boundaryGap: false,\n        data: legends,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: false,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      legend: {\n        x: 'center',\n        y: 'bottom',\n        data: ['Revisiones']\n      },\n      grid: {\n        top: 30,\n        // left\n        x: 20,\n        // right\n        x2: 20,\n        containLabel: true\n        // borderColor: '#FF0000'\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      series: [{\n        data: totals,\n        type: 'line',\n        name: 'Revisiones',\n        color: '#e54e76',\n        areaStyle: {},\n        smooth: true\n      }]\n    };\n    this.participantsRangeChart.setOption(option);\n  }\n\n  private updateCarsChart() {\n    const {carsByVenue} = this.props.dashboard;\n    const legends = [];\n    const series = [];\n    for (const car in carsByVenue) {\n      const currentCar = carsByVenue[car];\n      if (car !== 'inTransit') {\n        legends.push(car);\n        series.push({\n          name: car,\n          value: currentCar.cars.length\n          // itemStyle: {\n          //   col  or: this.chartsColors[0]\n          // }\n        });\n      } else {\n        legends.push('En tránsito');\n        series.push({\n          name: 'En tránsito',\n          value: currentCar.cars.length\n          // itemStyle: {\n          //   color: this.chartsColors[0]\n          // }\n        });\n      }\n    }\n    const option: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'item',\n        formatter: '{a} <br/>{b} : {c} ({d}%)'\n      },\n      legend: {\n        // x: 'center',\n        // type: 'scroll',\n        // orient: 'vertical',\n        // right: 10,\n        // top: 20,\n        // bottom: 20,\n        data: legends,\n        bottom: 40,\n        selected: {\n          ['En tránsito']: Object.keys(carsByVenue).length === 1\n        }\n      },\n      series: [\n        {\n          name: 'Sucursales',\n          type: 'pie',\n          radius: '70%',\n          center: ['50%', '43%'],\n          // label: {\n          //   normal: {\n          //     position: 'inner'\n          //   }\n          // },\n          data: series,\n          itemStyle: {\n            emphasis: {\n              shadowBlur: 10,\n              shadowOffsetX: 0,\n              shadowColor: 'rgba(0, 0, 0, 0.5)'\n            }\n          }\n        }\n      ]\n    };\n    this.carsByVenueChart.setOption(option);\n\n  }\n\n  private resizeCharts() {\n    if (this.participantsPerDayChart) {\n      this.participantsPerDayChart.resize();\n      setTimeout(() => {\n        this.participantsPerDayChart.resize();\n      }, 400);\n    }\n    if (this.carsByVenueChart) {\n      this.carsByVenueChart.resize();\n      setTimeout(() => {\n        this.carsByVenueChart.resize();\n      }, 400);\n    }\n    if (this.participantsRangeChart) {\n      this.participantsRangeChart.resize();\n      setTimeout(() => {\n        this.participantsRangeChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getParticipantsPerDateAction: (companies?:string) => dispatch(getParticipantsPerDateAction(companies))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardGeneralView);\n","// import * as PropTypes from 'prop-types';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport * as moment from 'moment';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { DashboardReduxAction } from '../../actions/dashboard.actions';\nimport { getDashboardTiming, IDashboardTimingState } from '../../actions/dashboardTiming.actions';\nimport AppContainer from '../../container/AppContainer';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport DateRangeInput from '../Utils/DateRangeInput';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardTimingState;\n\n  getDashboardTiming(from: string, to: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  showDrilldown: boolean,\n  selectedDate: string | null,\n  from: Date,\n  to: Date,\n}\n\nclass DashboardTimingView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n  timingPerMonthChart: echarts.ECharts;\n  timingPerVenueChart: echarts.ECharts;\n\n  state = {\n    showDrilldown: false,\n    error: null,\n    selectedDate: null,\n    from: moment().subtract(2, 'months').startOf('month').toDate(),\n    to: moment().endOf('month').toDate()\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Reportería de tiempos de traslado';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.updateTimingPerMonthChart = this.updateTimingPerMonthChart.bind(this);\n    this.showVenueChart = this.showVenueChart.bind(this);\n    this.showDateChart = this.showDateChart.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // get data\n    let from = moment().subtract(2, 'months').startOf('month');\n    let to = moment().endOf('month');\n    this.props.getDashboardTiming(from.format('YYYY-MM-DD'), to.format('YYYY-MM-DD'));\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n  }\n\n  getDateRangeOptions(): daterangepicker.Options {\n    return {\n      maxDate: moment().toDate(),\n      locale: {\n        format: 'MM/YYYY',\n        customRangeLabel: 'Período personalizado',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      ranges: {\n        'Este mes': [moment().startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Últimos 3 meses': [moment().subtract(2, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Últimos 6 meses': [moment().subtract(5, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Último año': [moment().subtract(11, 'months').startOf('month').toDate(), moment().endOf('month').toDate()]\n      }\n    };\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $timingPerMonth = document.getElementById('damages-per-month') as HTMLDivElement;\n    this.timingPerMonthChart = echarts.init($timingPerMonth);\n    this.timingPerMonthChart.on('click', this.showVenueChart);\n  }\n\n  onDateRangeChange(from: Date, to: Date) {\n    this.props.getDashboardTiming(moment(from).format('YYYY-MM-DD'), moment(to).format('YYYY-MM-DD'));\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const { loading, loadingPerVenue, perVenue } = this.props.dashboard;\n    const { showDrilldown } = this.state;\n    if (!loading) {\n      showDrilldown ? this.updateTimingPerVenueChart() :\n        this.updateTimingPerMonthChart();\n    }\n  }\n\n  public componentWillUnmount() {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading } = this.props.dashboard;\n    const { selectedDate, from, to } = this.state;\n    let selectedMonth = selectedDate ?\n      this.capitalizeFirstLetter(moment(selectedDate, 'MM-YYYY').format('MMMM YYYY')) : '';\n\n    return (\n      <AppContainer title='' cMenu='1' cSubMenu='1.5'>\n        <section className='content'>\n          <Row>\n            <div className='col-md-12'>\n              <div className='box'>\n                <div className='box-header with-border'><h3\n                  className='box-title'>{selectedDate ? `Traslados nacionales: ${selectedMonth}` : 'Traslados nacionales por mes'}</h3>\n                  <div className='box-tools pull-right'>\n                  </div>\n                </div>\n\n                <div className='row' style={{ display: selectedDate ? 'none' : 'inherit' }}>\n                  <div className='col-md-offset-8 col-md-4'>\n                    <DateRangeInput\n                      options={this.getDateRangeOptions()}\n                      onChange={this.onDateRangeChange}\n                      startDate={from}\n                      endDate={to}\n                    />\n                  </div>\n                </div>\n                <div className='box-body'>\n                  <p\n                    className='text-muted text-center'\n                    style={{ padding: '10px 0 0 0', margin: '0' }}\n                  >{selectedDate ? '' : 'Haz click en el gráfico para ver detalles de no cumplimiento'}.</p>\n                  <div id='damages-per-month' style={{ minHeight: '350px', maxWidth: '100%' }} />\n                </div>\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private capitalizeFirstLetter(str: string) {\n    return str.charAt(0).toUpperCase() + str.slice(1);\n  }\n\n  private updateTimingPerMonthChart() {\n    const { data } = this.props.dashboard;\n    let months: string[] = [];\n    let overdue: any[] = [];\n    let ontime: any[] = [];\n    const createDataElement = (n: number) => n > 0 ? {\n      value: n,\n      label: n > 0 ? { show: true, position: 'insideRight' } : { show: false }\n    } : null;\n\n    Object.keys(data).map(k => {\n      months.push(this.capitalizeFirstLetter(moment(k, 'MM-YYYY').format('MMMM YYYY')));\n      ontime.push(data[k].filter((d: { atTime: boolean; }) => d.atTime).length);\n      overdue.push(data[k].filter((d: { atTime: boolean; }) => !d.atTime).length);\n    });\n\n    ontime = ontime.map(createDataElement);\n    overdue = overdue.map(createDataElement);\n\n    const option: echarts.EChartOption = {\n      color: ['#f1392c', '#00aa51'],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['No cumple', 'Cumple'],\n        // x: 'center',\n        bottom: 5\n      },\n      xAxis: {\n        type: 'value',\n        position: 'top'\n      },\n      yAxis: {\n        type: 'category',\n        data: months\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        left: 10,\n        right: 10,\n        containLabel: true,\n        height: 290\n      },\n      series: [\n        {\n          name: 'No cumple',\n          type: 'bar',\n          stack: '1',\n          data: overdue,\n          barMinHeight: 15\n        },\n        {\n          name: 'Cumple',\n          type: 'bar',\n          stack: '1',\n          data: ontime,\n          barMinHeight: 15\n        }\n      ],\n      toolbox: []\n    };\n\n    this.timingPerMonthChart.setOption(option, true);\n  }\n\n  private updateTimingPerVenueChart() {\n    const { selectedDate } = this.state;\n    const { data } = this.props.dashboard;\n    let values = data[selectedDate!];\n    let routes: any = {};\n    let names: string[] = [];\n\n    const createDataElement = (n: number) => n > 0 ? {\n      value: n,\n      label: n > 0 ? { show: true, position: 'insideRight' } : { show: false }\n    } : null;\n\n    values.map((d: any) => {\n      let routeName = d.from + ' - ' + d.to;\n      if (routes[routeName] === undefined) {\n        routes[routeName] = { overdue: 0, ontime: 0, limitTime: d.daysLimit };\n        names.push(routeName);\n      }\n      d.atTime ? routes[routeName].ontime++ : routes[routeName].overdue++;\n    });\n\n    names.sort();\n    let ontime: any[] = [];\n    let overdue: any[] = [];\n\n    names.map((n: string) => {\n      let data = routes[n];\n      ontime.push({ ...createDataElement(data.ontime as number), limitTime: data.limitTime });\n      overdue.push({ ...createDataElement(data.overdue as number), limitTime: data.limitTime });\n    });\n\n    const option: echarts.EChartOption = {\n      color: ['#f1392c', '#00aa51'],\n      tooltip: {\n        trigger: 'axis',\n        formatter: function(params: any) {\n          let timeLimit = 0;\n          let output = '<b>' + params[0].name + '</b><br/>';\n\n          params.map((p: any) => {\n            output += p.marker + p.seriesName + ': ' + (p.value ? p.value : '-') + '<br/>'; // : every 2nth\n            if (timeLimit === 0)\n              timeLimit = p.data.limitTime;\n          });\n\n          output += `Tiempo límite de entrega: ${timeLimit} días`;\n          return output;\n        },\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        data: ['No cumple', 'Cumple'],\n        // x: 'center',\n        bottom: 5\n      },\n      xAxis: {\n        type: 'value',\n        position: 'top'\n      },\n      yAxis: {\n        type: 'category',\n        data: names\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        left: 10,\n        right: 10,\n        containLabel: true,\n        height: 290\n      },\n      series: [\n        {\n          name: 'No cumple',\n          type: 'bar',\n          stack: '1',\n          data: overdue,\n          barMinHeight: 15,\n          barMinWidth: 25\n        },\n        {\n          name: 'Cumple',\n          type: 'bar',\n          stack: '1',\n          data: ontime,\n          barMinHeight: 15,\n          barMinWidth: 25\n        }\n      ],\n      toolbox: {\n        left: 20,\n        top: 0,\n        feature: {\n          myBackBtn: {\n            show: true,\n            icon: 'path://M16.6666667 9.16666667 6.525 9.16666667 11.1833333 4.50833333 10 3.33333333 3.33333333 10 10 16.6666667 11.175 15.4916667 6.525 10.8333333 16.6666667 10.8333333z',\n            title: ' ',\n            onclick: this.showDateChart\n          }\n        },\n        iconStyle: {\n          color: 'rgba(0, 0, 0, 0.8)',\n          fontWeight: 'bolder',\n          borderColor: 'rgba(0, 0, 0, 0)',\n          shadowColor: 'rgba(0, 0, 0, 0)',\n          emphasis: {\n            color: '#a94442',\n            borderColor: 'rgba(0, 0, 0, 0)',\n            shadowColor: 'rgba(0, 0, 0, 0)'\n          }\n        }\n      }\n    };\n\n    this.timingPerMonthChart.setOption(option, true);\n\n  }\n\n  private showVenueChart(param: any) {\n    const { data } = this.props.dashboard;\n    const month = moment(param.name.toLowerCase(), 'MMMM YYYY').format('MM-YYYY');\n    this.setState({\n      showDrilldown: true,\n      selectedDate: month\n    }, () => {\n      setTimeout(() => {\n        this.timingPerMonthChart.off('click');\n      }, 200);\n    });\n  }\n\n  private showDateChart() {\n    this.setState({\n      showDrilldown: false,\n      selectedDate: null\n    }, () => {\n      setTimeout(() => {\n        this.timingPerMonthChart.on('click', this.showVenueChart);\n      }, 500);\n      const $timingPerMonth = document.getElementById('damages-per-month') as HTMLDivElement;\n      this.timingPerMonthChart = echarts.init($timingPerMonth);\n    });\n  }\n\n  private resizeCharts() {\n    if (this.timingPerMonthChart) {\n      this.timingPerMonthChart.resize();\n      setTimeout(() => {\n        this.timingPerMonthChart.resize();\n      }, 400);\n    }\n\n    if (this.timingPerVenueChart) {\n      this.timingPerVenueChart.resize();\n      setTimeout(() => {\n        this.timingPerVenueChart.resize();\n      }, 400);\n    }\n  }\n}\n\nconst mapStateToProps = (state: { dashboardTiming: IDashboardTimingState }) => {\n  return {\n    dashboard: state.dashboardTiming\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getDashboardTiming: (from: string, to: string) => dispatch(getDashboardTiming(from, to))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardTimingView);\n","// import * as PropTypes from 'prop-types';\nimport * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport { ErrorInfo } from 'react';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\nimport { IParticipant } from '../../../../../../src/form/interfaces/participant.interface';\nimport {\n  DashboardReduxAction,\n  getCarAction,\n  getParticipant,\n  IDashboardState,\n  loadParticipantInCarAction\n} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport { hasPermission, parseReplicableURL } from '../../utils/common';\nimport CopyText from '../Utils/CopyText';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n\n  getCarAction(id: string): void;\n\n  getParticipant(id: string): void;\n\n  loadParticipantInCarAction(participant: IParticipant): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  highlight: string[];\n  carLoading: string;\n}\n\nclass DashboardVinDetail extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  // static propTypes = {\n  //   dashboard: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired,\n  //   getCarAction: PropTypes.func.isRequired,\n  //   getParticipant: PropTypes.func.isRequired\n  // };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle VIN';\n    this.openBlank = this.openBlank.bind(this);\n  }\n\n  readonly state = {\n    error: null,\n    highlight: [],\n    carLoading: ''\n  };\n  protected printIframe: any;\n\n  private socket: Socket;\n\n  componentWillMount() {\n    // set the title of the page\n    const { id } = this.props.match.params;\n    this.props.getCarAction(id);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `dashboard-vin-detail-${window.user.team._id}-${id}` });\n    });\n    this.socket.on('ADD_PARTICIPANT', (data: any): void => {\n      this.setState({\n        highlight: [data._id, ...this.state.highlight]\n      });\n      this.props.loadParticipantInCarAction(data);\n    });\n\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public printPdf(url: string, carLoading: string) {\n    this.setState({ carLoading });\n    let iframe: any = this.printIframe;\n    const timezone = moment.tz.guess();\n    if (!this.printIframe) {\n      iframe = this.printIframe = document.createElement('iframe');\n      document.body.appendChild(iframe);\n      iframe.style.display = 'none';\n      iframe.onload = () => {\n        setTimeout(() => {\n          iframe.focus();\n          iframe.contentWindow.print();\n          this.setState({ carLoading: '' });\n          // document.body.removeChild(iframe)\n        }, 1);\n      };\n    }\n    iframe.src = `${url}?timezone=${timezone}`;\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { car, loadingParticipant, requests } = this.props.dashboard;\n    const { highlight, carLoading } = this.state;\n    const { getParticipant } = this.props;\n    const deliveriesView = this.props.location.pathname.includes('deliveries/cars');\n    return (\n      <AppContainer title={`Detalle ${car ? car.vin : null}`} cMenu='1' cSubMenu={deliveriesView ? '1.8' : '1.2'} cAction={`Detalle`}>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3 col-lg-3'>\n              <div className='box box-primary'>\n                <div className='box-body box-profile'>\n                  {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'100px'} maxHeight={'100px'} maxWidth={'100px'} small={true}/>*/}\n                  {/*<img*/}\n                  {/*className=\"profile-user-img img-responsive img-circle\"*/}\n                  {/*src=\"https://cdn.forbes.com.mx/2018/03/Auto-Carretera-1280x720.jpg\"*/}\n                  {/*alt=\"User profile picture\"*/}\n                  {/*style={{*/}\n                  {/*fontFamily: 'object-fit:cover',*/}\n                  {/*objectFit: 'cover',*/}\n                  {/*width: '100px',*/}\n                  {/*height: '100px'*/}\n                  {/*}}*/}\n                  {/*/>*/}\n                  <h3 className='profile-username text-center text-black'>{car && car.brand ? car.brand : '-'}</h3>\n                  <p className='text-muted text-center text-black'>{car && car.denomination ? car.denomination : '-'}</p>\n                  <ul className='list-group list-group-unbordered no-margin text-muted'>\n                    <li className='list-group-item'>\n                      <strong>VIN</strong>\n                      <span className='pull-right text-primary'>\n                        <CopyText value={car?.vin ?? ''}>\n                          <strong>{\n                            car && car.vin ? car.vin : '-'\n                          }</strong>\n                        </CopyText>\n                      </span>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Color</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.color ? car.color : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Material</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.material ? car.material : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Patente</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.patent ? car.patent : '-'\n                        }\n                      </strong>\n                    </li>\n                    <li className='list-group-item'>\n                      <strong>Nº Interno</strong>\n                      <strong className='pull-right'>\n                        {\n                          car && car.internalNumber ? car.internalNumber : '-'\n                        }\n                      </strong>\n                    </li>\n\n                    {/*<li className='list-group-item'>*/}\n                    {/*  <strong>Revisiones</strong>*/}\n                    {/*  <span className='pull-right'>*/}\n                    {/*    {*/}\n                    {/*      car && car.participants ? car.participants.length : 0*/}\n                    {/*    }*/}\n                    {/*  </span>*/}\n                    {/*</li>*/}\n                    {/*<li className='list-group-item'>*/}\n                    {/*  <strong>Inventarios</strong>*/}\n                    {/*  <span className='pull-right'>*/}\n                    {/*    {*/}\n                    {/*      car && car.inventories ? car.inventories.length : 0*/}\n                    {/*    }*/}\n                    {/*  </span>*/}\n                    {/*</li>*/}\n                  </ul>\n                  <ShowIf condition={hasPermission(window.user, 'viewCar')}>\n                    <button\n                      className='btn btn-primary btn-block'\n                      onClick={() => {\n                        this.props.history.replace(parseReplicableURL(`/settings/cars/${car?._id}`));\n                      }}\n                    >\n                      <strong>Detalle</strong>\n                    </button>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <div className='col-md-9 col-lg-9'>\n              <div className='nav-tabs-custom'>\n                <ul className='nav nav-tabs'>\n                  <li className='active'><a href='#checklist' data-toggle='tab' aria-expanded='false'>Controles\n                    ({car?.participants?.length ?? '0'})</a>\n                  </li>\n                  {/*<li className=''><a href='#distribution' data-toggle='tab' aria-expanded='true'>Distribución ({requests?.length ?? '0'})</a></li>*/}\n                  {/*<li className=\"dropdown\">\n                        <a className=\"dropdown-toggle\" data-toggle=\"dropdown\" href=\"#\">\n                          Dropdown <span className=\"caret\"></span>\n                        </a>\n                        <ul className=\"dropdown-menu\">\n                          <li role=\"presentation\"><a role=\"menuitem\" tabIndex={-1} href=\"#\">Action</a></li>\n                          <li role=\"presentation\"><a role=\"menuitem\" tabIndex={-1} href=\"#\">Another action</a></li>\n                          <li role=\"presentation\"><a role=\"menuitem\" tabIndex={-1} href=\"#\">Something else here</a></li>\n                          <li role=\"presentation\" className=\"divider\"></li>\n                          <li role=\"presentation\"><a role=\"menuitem\" tabIndex={-1} href=\"#\">Separated link</a></li>\n                        </ul>\n                      </li>\n                      <li className=\"pull-right\"><a href=\"#\" className=\"text-muted\"><i className=\"fa fa-gear\"></i></a></li>*/}\n                </ul>\n                <div className='tab-content no-padding'>\n                  {/*style={{maxHeight: '80vh', overflowX: 'scroll'}}*/}\n                  <div className='tab-pane active' id='checklist'>\n                    <table className='table table-striped no-margin'>\n                      <thead>\n                      <tr>\n                        <th className='middle' style={{ width: '40%' }}>Control</th>\n                        {/*<th className=\"middle hidden-xs\">Supervisor</th>*/}\n                        <th className='middle hidden-xs' style={{ width: '40%' }}>Realizado por</th>\n                        <th className='middle hidden-xs' style={{ width: '20%' }}></th>\n                        <th className='middle-center hidden-xs' style={{ width: '3%' }}></th>\n                        <th style={{ width: '1%' }} />\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        car?.participants?.map((participant) => (\n                          <tr key={participant._id}\n                              className={highlight.length && highlight.includes(participant._id as never) ? 'highlight-info' : ''}>\n                            <td className='middle text-sm' style={{\n                              paddingTop: '10px',\n                              paddingBottom: '10px'\n                            }}>\n                              <div className='visible-xs visible-sm'>\n                                <strong className='text-muted'>\n                                  #{participant.number}\n                                </strong><br />\n                                <strong className='text-primary'>{participant.name}</strong>\n                              </div>\n                              <div className='hidden-xs hidden-sm '>\n                                <strong className='text-primary'>{participant.name}</strong><br />\n                                <strong className='text-muted'>\n                                  #{participant.number}\n                                </strong>\n                              </div>\n                              <div className='text-muted text-sm'>\n                                <div className='visible-xs visible-sm'>\n                                  <strong>\n                                    <i className='fa fa-fw fa-user-o' /> {participant.user?.firstName ?? ''} {participant.user?.lastName ?? ''}\n                                  </strong>\n                                    <div><i className='fa fa-fw fa-flag-o' /> {participant.venue ? participant.venue.name : '-'} <ShowIf\n                                  condition={participant.hasDamages}\n                                >\n                                  <React.Fragment>\n                                    {' '}<i\n                                    className='fa fa-fw fa-warning text-red'\n                                    data-toggle='tooltip'\n                                    data-placement='top'\n                                    title='Daños encontrados en esta revisión.'\n                                  />\n                                  </React.Fragment>\n                                </ShowIf></div>\n                                  <div>{participant.company?.name}</div>\n                                  <div>\n                                    <i\n                                      className='fa fa-clock-o fa-fw' /> {moment(participant.createdAt).fromNow()} ({moment(participant.createdAt).format('LLL')})\n                                  </div>\n                                </div>\n                              </div>\n                            </td>\n                            {/*<td className=\"middle hidden-xs\">{participant.user ? participant.user.firstName : ''} {participant.user ? participant.user.lastName : ''}</td>*/}\n                            <td className='middle hidden-xs text-sm text-muted text-ellipsis' style={{\n                              paddingTop: '10px',\n                              paddingBottom: '10px'\n                            }}>\n                              <strong className='text-muted'>\n                                <i\n                                  className='fa fa-fw fa-user-o' /> {participant.user ? participant.user.firstName : ''} {participant.user ? participant.user.lastName : ''}\n                              </strong>\n                              <div><i className='fa fa-fw fa-flag-o' /> {participant.venue ? participant.venue.name : '-'} <ShowIf\n                              condition={participant.hasDamages}\n                            >\n                              <React.Fragment>\n                                {' '}<i\n                                className='fa fa-fw fa-warning text-red'\n                                data-toggle='tooltip'\n                                data-placement='top'\n                                title='Daños encontrados en esta revisión.'\n                              />\n                              </React.Fragment>\n                            </ShowIf></div>\n                              {participant.company?.name}\n                            </td>\n                            <td className='middle-center hidden-xs text-muted text-sm text-ellipsis'>\n                              <div\n                                className='text-muted text-sm' data-toggle='tooltip'\n                                data-placement='top'\n                                title={moment(participant.createdAt).format('LLL')}\n                              >\n                                <i className='fa fa-fw fa-clock-o' /> {moment(participant.createdAt).fromNow()}\n                              </div>\n                            </td>\n                            <td className='middle-center hidden-xs text-muted text-sm'>\n                              <ShowIf\n                                condition={!!(participant.hasOwnProperty('qualification') && participant.qualification)}\n                                alternative={''}\n                              >\n                                {`${Math.round(participant.qualification)}%`}\n                              </ShowIf>\n                            </td>\n                            <td className='text-primary middle-center text-ellipsis'>\n                              <div\n                                className='hidden-xs hidden-sm'\n                              >\n                                <div className='btn-group' style={{ width: '70px' }}>\n                                  <button\n                                    className='btn btn-sm btn-default'\n                                    disabled={carLoading === participant._id}\n                                    onClick={() => this.printPdf(`/report/forms/pdf/${participant._id}.pdf`, participant._id)}\n                                  ><i className={carLoading === participant._id ? 'fa fa-spinner fa-spin' : 'fa fa-print'} /></button>\n                                  <button\n                                    className='btn btn-sm btn-primary'\n                                    disabled={!!(loadingParticipant && loadingParticipant === participant._id)}\n                                    onClick={loadingParticipant ? undefined : () => getParticipant(participant._id)}\n                                  >\n                                    <ShowIf\n                                      condition={!!(loadingParticipant && loadingParticipant === participant._id)}\n                                      alternative={<i className='fa fa-bar-chart' />}\n                                    >\n                                      <i className='fa fa-spin fa-spinner' />\n                                    </ShowIf>\n                                  </button>\n                                </div>\n                              </div>\n                              <div\n                                className='visible-xs visible-sm'\n                              >\n                                <button\n                                  className='btn btn-sm btn-primary'\n                                  disabled={!!(loadingParticipant && loadingParticipant === participant._id)}\n                                  onClick={loadingParticipant ? undefined : () => getParticipant(participant._id)}\n                                >\n                                  <ShowIf\n                                    condition={!!(loadingParticipant && loadingParticipant === participant._id)}\n                                    alternative={<i className='fa fa-bar-chart' />}\n                                  >\n                                    <i className='fa fa-spin fa-spinner' />\n                                  </ShowIf>\n                                </button>\n                              </div>\n                            </td>\n                          </tr>\n                        ))\n                      }\n                      </tbody>\n                    </table>\n                  </div>\n                  <div className='tab-pane' id='distribution' style={{ maxHeight: '80vh', overflowX: 'scroll' }}>\n                    <table className='table table-striped'>\n                      <thead>\n                      <tr>\n                        <th className='middle'>Nº</th>\n                        <th className='middle'>Estado</th>\n                        <th className='middle'>Solicitante</th>\n                        <th className='middle'>Vendedor</th>\n                        <th className='middle'>Cliente</th>\n                        <th className='middle'>RUT Cliente</th>\n                        <th className='middle'>Correo</th>\n                        <th className='middle-center'>Ticket</th>\n                        <th className='middle'>Nº Ticket</th>\n                        <th className='middle'>Sucursal</th>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        requests.map((request) => {\n                          return (\n                            <tr key={request._id}>\n                              <td>\n                                <a\n                                  href={parseReplicableURL(`/requests/vehicles/${request.request._id}/`)}\n                                  target='_blank'\n                                  style={{\n                                    textDecoration: 'underline'\n                                  }}\n                                >#{request.request.number} <i className='fa fa-fw fa-share-alt-square' /></a>\n                              </td>\n                              <td>{request.status?.name}</td>\n                              <td>{request.request.createdBy ? `${request.request.createdBy.firstName} ${request.request.createdBy.lastName}` : ''}</td>\n                              <td>{request.request.sellerText}</td>\n                              <td>{request.request?.customerInformation?.name}</td>\n                              <td>{request.request?.customerInformation?.rut}</td>\n                              <td>{request.request?.customerInformation?.email}</td>\n                              <td className='middle-center'>\n                                {\n                                  request.request?.advancePaymentInformation?.files?.length ?\n                                    <i\n                                      className='fa fa-check-circle text-green pointer'\n                                      onClick={() => this.openBlank(request.request.advancePaymentInformation.files[0].file.url)}\n                                    /> : ''\n                                }\n                              </td>\n                              <td className='middle'>{request.request?.advancePaymentInformation?.number}</td>\n                              <td>{request.destination?.name}</td>\n                            </tr>\n                          );\n                        })\n                      }\n                      </tbody>\n                    </table>\n                  </div>\n                </div>\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private openBlank(url: string) {\n    window.open(url, '_blank');\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getCarAction: (id: string) => dispatch(getCarAction(id)),\n    getParticipant: (id: string) => dispatch(getParticipant(id)),\n    loadParticipantInCarAction: (participant: IParticipant) => dispatch(loadParticipantInCarAction(participant))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardVinDetail);\n","import * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { debounce } from 'throttle-debounce';\nimport * as swal from 'sweetalert';\nimport { IParticipant } from '../../../../../../src/form/interfaces/participant.interface';\nimport {\n  changeFormsSearchDashboardAction,\n  changeRangeDashboardAction,\n  changeSearchDashboardAction,\n  DashboardReduxAction,\n  getRevisionsAction,\n  getRevisionsThunkAction,\n  IDashboardState\n} from '../../actions/dashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport DateRangeInput from '../Utils/DateRangeInput';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport ShowIf from '../Utils/ShowIf';\nimport CopyText from '../Utils/CopyText';\nimport { parseReplicableURL } from '../../utils/common';\nimport * as daterangepicker from 'daterangepicker';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<DashboardReduxAction>;\n  dashboard: IDashboardState;\n\n  getRevisionsThunkAction(page: number, loading: boolean, search?: string): void;\n\n  getRevisionsAction(page: number, loading: boolean, search?: string): void;\n\n  changeSearchFormsDashboardAction(forms: string[]): DashboardReduxAction;\n\n  changeSearchDashboardAction(searchText: string): DashboardReduxAction;\n\n  changeRangeDashboardAction(from: Date, to: Date): DashboardReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  highlight: string[];\n  searchText: string;\n  selectedForms: string[];\n  carLoading: string;\n  from: Date;\n  to: Date;\n  downloading: boolean;\n}\n\nclass DashboardVinView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n\n  readonly state: IStateType = {\n    error: null,\n    highlight: [],\n    searchText: '',\n    carLoading: '',\n    selectedForms: [],\n    from: moment().subtract(3, 'months').startOf('month').toDate(),\n    to: moment().toDate(),\n    downloading: false\n  };\n  protected printIframe: any;\n\n  protected isMount: boolean = false;\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Revisiones';\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.printPdf = this.printPdf.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n    this.downloadReport = this.downloadReport.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.filterForms = this.filterForms.bind(this);\n    this.filterAllForms = this.filterAllForms.bind(this);\n  }\n\n  public printPdf(url: string, carLoading: string) {\n    this.setState({ carLoading });\n    let iframe: any = this.printIframe;\n    const timezone = moment.tz.guess();\n    if (!this.printIframe) {\n      iframe = this.printIframe = document.createElement('iframe');\n      window.document.body.appendChild(iframe);\n      iframe.style.display = 'none';\n      iframe.onload = () => {\n        setTimeout(() => {\n          iframe.focus();\n          iframe.contentWindow.print();\n          this.setState({ carLoading: '' });\n          // document.body.removeChild(iframe)\n        }, 1);\n      };\n    }\n    iframe.src = `${url}?timezone=${timezone}`;\n  }\n\n  public componentWillMount(): void {\n    // set the title of the page\n    const { page } = this.props.dashboard.pagination;\n    this.props.getRevisionsThunkAction(page, true);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `dashboard-vin-view-${window.user.team._id}` });\n    });\n\n    this.socket.on('REFRESH', (data: any): void => {\n      const { page } = this.props.dashboard.pagination;\n      const { forms } = this.props.dashboard;\n      if (data.update && window.user.venuesAccess.includes(data.venueId) && forms.map((form: IForm) => form._id).includes(data.formId)) {\n        this.props.getRevisionsAction(page, false);\n        ($ as any).toast({\n          heading: data.notification.title,\n          text: data.notification.text,\n          position: 'top-right',\n          loaderBg: '#e2e2e2',\n          icon: 'success',\n          hideAfter: 5000,\n          stack: 6\n        } as any);\n        if (!this.state.highlight.includes(data.car)) {\n          this.setState({\n            highlight: [data.car, ...this.state.highlight]\n          });\n        } else {\n          this.setState({\n            highlight: this.state.highlight.filter((e) => e !== data.car)\n          }, () => {\n            this.setState({\n              highlight: [data.car, ...this.state.highlight]\n            });\n          });\n        }\n        setTimeout(() => {\n          if (this.isMount) {\n            this.setState({\n              highlight: this.state.highlight.filter((e) => e !== data.car)\n            });\n          }\n        }, 3000);\n      }\n    });\n    this.isMount = true;\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount() {\n    this.isMount = false;\n    // cancel request if component is inmounted\n    if (this.props.dashboard.source) {\n      this.props.dashboard.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public downloadReport() {\n    const { from, to, selectedForms, searchText } = this.state;\n    const monthsDiff = moment(to).diff(moment(from), 'months');\n    this.trackClick('Descargar reporte', {\n      from,\n      to\n    });\n    if (monthsDiff > 3) {\n      swal!('Revisiones', 'Selecciona un rango menor que 3 meses para descargar la información', 'error');\n    } else {\n      let query = `?deliveries=0&from=${moment(from).unix()}&to=${moment(to).unix()}`;\n\n      if (searchText)\n        query += `&search=${searchText}`;\n\n      if (selectedForms)\n        query += `&forms=${selectedForms.join(',')}`;\n\n      window.open(`/api/participant/export/${query}`, '_blank');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, participants, pagination, searchText, forms } = this.props.dashboard;\n    const { highlight, carLoading, downloading, from, to, selectedForms } = this.state;\n    return (\n      <AppContainer title='Revisiones' cMenu='1' cSubMenu='1.2'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Controles <small>{pagination.count}</small>\n              </h3>\n              <div className='box-tools pull-right'>\n                <button\n                  className='btn btn-sm btn-primary hidden-xs hidden-sm hidden-sm'\n                  onClick={this.downloadReport}\n                  disabled={downloading}\n                >\n                  <i className='fa fa-fw fa-download' /> Exportar\n                </button>\n              </div>\n            </div>\n            <div className={`box-body no-padding`}>\n              <div className='row no-margin'>\n                <div className='col-md-6 no-padding'>\n                  <div style={{ padding: '10px' }}>\n                    <BootstrapSelect\n                      noneSelectedText='Todos los controles'\n                      displayItems={4}\n                      sm={true}\n                      autoClouse={true}\n                      selectedText='formularios seleccionadas.'\n                      selected={selectedForms}\n                      allOption={true}\n                      selectAll={this.filterAllForms}\n                      separator=' - '\n                      options={forms.map((form: IForm) => ({\n                        value: form._id,\n                        text: form.name\n                      }))}\n                      onClick={this.filterForms}\n                      notHideOnClickOutside={false}\n                    />\n                  </div>\n                </div>\n                <div className='col-md-6 no-padding'>\n                  <div style={{ padding: '10px' }}>\n                    <DateRangeInput\n                      options={this.getDateRangeOptions()}\n                      onChange={this.onDateRangeChange}\n                      startDate={from}\n                      endDate={to}\n                    />\n                  </div>\n                </div>\n                <div className='col-md-12 no-padding'>\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type='text'\n                      className='form-control pull-right'\n                      onChange={this.onChangeSearch}\n                      value={searchText}\n                      placeholder='Buscar VIN, marca, supervisor o sucursal' />\n                    <div className='input-group-btn'>\n                      <button className='btn btn-default'><i className='fa fa-search' /></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              {\n                participants.length ?\n                  <div className='table-responsive' style={{ border: 0 }}>\n                    <table className='table table-andes table-striped table-hover'>\n                      <thead>\n                      <tr>\n                        <th style={{ width: '18%' }} className='middle'>Detalle</th>\n                        {/*<th style={{width: '18%'}} className=\"middle hidden-xs hidden-sm\">Unidad</th>*/}\n                        {/*<th style={{width: '13%'}} className=\"middle hidden-xs hidden-sm\">Supervisor</th>*/}\n                        <th style={{ width: '15%' }} className='middle hidden-xs hidden-sm'>Control</th>\n                        <th style={{ width: '20%' }} className='middle hidden-xs hidden-sm'>Realizado por</th>\n                        <th style={{ width: '10%' }} className='middle hidden-xs hidden-sm'></th>\n                        <th style={{ width: '1%' }} className='middle-center hidden-xs hidden-sm'></th>\n                        {/*<th style={{width: '15%'}} className=\"hidden-xs hidden-sm\">Fecha</th>*/}\n                        <th style={{ width: '1%' }} />\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        participants.map((participant: IParticipant) => {\n                          return (\n                            <tr\n                              key={participant._id} id={`car-${participant._id}`}\n                              className={highlight.length && highlight.includes(participant._id as never) ? 'highlight-info' : ''}\n                            >\n                              <td\n                                className='middle'\n                                style={{\n                                  paddingTop: '10px',\n                                  paddingBottom: '10px'\n                                }}\n                              >\n                                <div\n                                  className='visible-xs visible-sm'\n                                >\n                                  <strong className='text-primary'>\n                                    {participant.car?.vin}\n                                  </strong> <strong className='text-muted'>#{participant.number}</strong><br />\n                                  <strong className={'text-muted'}>{participant.name}</strong>\n                                </div>\n                                <div\n                                  className='hidden-xs hidden-sm'\n                                >\n                                  <CopyText value={participant.car?.vin}>\n                                    <strong\n                                      className='text-primary pointer text-underline'\n                                      onClick={() => this.props.history.push(parseReplicableURL(`/cars/${participant.car?._id}`))}\n                                    >\n                                      {participant.car?.vin}\n                                    </strong>\n                                  </CopyText> <strong className='text-sm text-muted'>\n                                  #{participant.number}\n                                </strong>\n                                </div>\n                                <span className='visible-xs visible-sm'>\n                                  <strong\n                                    className={'text-muted'}>{participant.car?.brand}</strong><br /> {participant.car?.denomination}<br />{participant.car?.color}<br />\n                                </span>\n                                <span className='text-muted text-sm hidden-xs hidden-sm'>\n                                  <strong>{participant.car?.brand}</strong><br />{participant.car?.denomination}<br /> {participant.car?.color}\n                                  <ShowIf condition={!!participant.car?.patent?.length}>\n                                    <div>\n                                      <i\n                                        className='fa fa-fw fa-id-card-o' /> {participant.car?.patent && participant.car?.patent.length ? participant.car?.patent : '-'}\n                                    </div>\n                                  </ShowIf>\n                                </span>\n                                <div className='visible-xs visible-sm text-muted text-sm'>\n                                  <span><i\n                                    className='fa fa-fw fa-user-o' /> {`${participant.user ? `${participant.user.firstName} ${participant.user.lastName}` : ''}`}</span><br />\n                                  <span><i className='fa fa-fw fa-flag-o' /> {`${participant.venue ? `${participant.venue.name}` : '-'}`} <ShowIf\n                                    condition={participant.hasDamages}\n                                  >\n                                    <React.Fragment>\n                                      {' '}<i\n                                      className='fa fa-warning text-red'\n                                      data-toggle='tooltip'\n                                      data-placement='top'\n                                      title='Daños encontrados en esta revisión.'\n                                    />\n                                    </React.Fragment>\n                                  </ShowIf></span><br />\n                                  <div>\n                                    <i\n                                      className='fa fa-clock-o fa-fw' /> {moment(participant.createdAt).fromNow()} ({moment(participant.createdAt).format('LLL')})\n                                  </div>\n                                  <ShowIf condition={!!participant.car?.patent?.length}>\n                                    <span>\n                                      <i\n                                        className='fa fa-fw fa-id-card-o' /> {participant.car?.patent && participant.car?.patent.length ? participant.car?.patent : '-'}\n                                    </span>\n                                  </ShowIf>\n                                </div>\n                              </td>\n                              <td className='middle hidden-xs hidden-sm'>\n                                <strong className='text-muted text-sm'>{participant.name}</strong>\n                              </td>\n                              <td className='middle hidden-xs hidden-sm  text-ellipsis' style={{\n                                paddingTop: '15px',\n                                paddingBottom: '15px'\n                              }}>\n                                <div className='text-muted'>\n                                  <strong><i\n                                    className='fa fa-fw fa-user-o' /> {`${participant.user ? `${participant.user.firstName} ${participant.user.lastName}` : ''}`}\n                                  </strong><br />\n                                </div>\n                                <div className='text-muted text-sm'><i\n                                  className='fa fa-fw fa-flag-o' /> {`${participant.venue ? `${participant.venue.name}` : '-'}`} <ShowIf\n                                  condition={participant.hasDamages}\n                                >\n                                  <React.Fragment>\n                                    {' '}<i\n                                    className='fa fa-warning text-red'\n                                    data-toggle='tooltip'\n                                    data-placement='top'\n                                    title='Daños encontrados en esta revisión.'\n                                  />\n                                  </React.Fragment>\n                                </ShowIf>\n                                </div>\n                                <div className='text-muted text-sm'>\n                                  {`${participant.company ? `${participant.company.name}` : '-'}`}\n                                </div>\n                              </td>\n                              <td className='middle-center hidden-xs hidden-sm'>\n                                <div\n                                  className='text-muted text-sm' data-toggle='tooltip'\n                                  data-placement='top'\n                                  title={moment(participant.createdAt).format('LLL')}\n                                >\n                                  <i className='fa fa-fw fa-clock-o' /> {moment(participant.createdAt).fromNow()}\n                                </div>\n                              </td>\n                              <td className='middle-center hidden-xs hidden-sm text-muted text-sm'>\n                                {\n                                  `${participant.hasOwnProperty('qualification') ?\n                                    participant.qualification ? `${Math.round(participant.qualification)}%` : !participant.hasDamages ? '' : '' : ''}`\n                                }\n                              </td>\n                              <td className='text-primary middle-center text-ellipsis'>\n                                <div\n                                  className='hidden-xs hidden-sm'\n                                >\n                                  <div className='btn-group' style={{ width: '70px' }}>\n                                    <button\n                                      className='btn btn-sm btn-default hidden-xs hidden-sm'\n                                      disabled={carLoading === participant._id}\n                                      onClick={() => this.printPdf(`/report/forms/pdf/${participant._id}.pdf`, participant._id)}\n                                    ><i className={carLoading === participant._id ? 'fa fa-spinner fa-spin' : 'fa fa-print'} /></button>\n                                    <button\n                                      className='btn btn-sm btn-primary'\n                                      onClick={() => this.props.history.push(`/cars/${participant.car?._id}`)}\n                                    ><i className='fa fa-bars' /></button>\n                                  </div>\n                                </div>\n                                <div\n                                  className='visible-xs visible-sm'\n                                >\n                                  <button\n                                    className='btn btn-sm btn-primary'\n                                    onClick={() => this.props.history.push(`/cars/${participant.car?._id}`)}\n                                  ><i className='fa fa-bars' /></button>\n                                </div>\n                              </td>\n                            </tr>\n                          );\n                        })\n                      }\n                      </tbody>\n                    </table>\n                  </div>\n                  : !loading ? <p style={{ padding: '10px' }}><strong>No se han encontrado revisiones.</strong></p> : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                    <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              !participants.length && loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private filterForms(value: any) {\n    let { selectedForms } = this.state;\n    let sForms = selectedForms;\n\n    sForms = sForms.includes(value)\n      ? sForms.filter((form) => form !== value)\n      : [value, ...selectedForms];\n\n    this.setState({\n      selectedForms: sForms\n    }, () => {\n      this.props.changeSearchFormsDashboardAction(this.state.selectedForms);\n      this.props.getRevisionsAction(1, false);\n    });\n  }\n\n  private filterAllForms(value: boolean) {\n    let { forms } = this.props.dashboard;\n    let sForms = value ? forms.map((f: IForm) => f._id) : [];\n\n\n    this.setState({\n      selectedForms: sForms\n    }, () => {\n      this.props.changeSearchFormsDashboardAction(this.state.selectedForms);\n      this.props.getRevisionsAction(1, false);\n    });\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value;\n    this.setState({\n      searchText: value\n    });\n    this.props.changeSearchDashboardAction(value);\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { searchText } = this.state;\n    if (searchText && searchText.length) {\n      this.props.getRevisionsAction(1, false, searchText);\n    } else {\n      this.props.getRevisionsAction(1, false);\n    }\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getRevisionsAction(page, false);\n    window.scrollTo(0, 0);\n  }\n\n  private getDateRangeOptions(): daterangepicker.Options {\n    return {\n      // startDate: moment().subtract(11, 'months').startOf('month').toDate(),\n      // endDate: moment().toDate(),\n      maxDate: moment().toDate(),\n      locale: {\n        format: 'DD/MM/YYYY',\n        customRangeLabel: 'Período personalizado',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      ranges: {\n        'Este mes': [moment().startOf('month').startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Últimos 3 meses': [moment().startOf('month').subtract(3, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Últimos 6 meses': [moment().startOf('month').subtract(6, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n        'Último año': [moment().startOf('month').subtract(12, 'months').startOf('month').toDate(), moment().endOf('month').toDate()]\n      },\n      opens: 'left'\n    };\n  }\n\n  private onDateRangeChange(from: Date, to: Date) {\n    this.setState({\n      from,\n      to\n    });\n    this.props.changeRangeDashboardAction(\n      moment(from).toDate(), moment(to).toDate()\n    );\n    this.debounceOnChangeSearch();\n  }\n}\n\nconst mapStateToProps = (state: { dashboard: IDashboardState }) => {\n  return {\n    dashboard: state.dashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRevisionsThunkAction: (page: number, loading: boolean, search?: string) => dispatch(getRevisionsThunkAction(page, loading, search, undefined, undefined, undefined)),\n    changeSearchFormsDashboardAction: (forms: string[]) => dispatch(changeFormsSearchDashboardAction(forms)),\n    changeSearchDashboardAction: (searchText: string) => dispatch(changeSearchDashboardAction(searchText)),\n    changeRangeDashboardAction: (from: Date, to: Date) => dispatch(changeRangeDashboardAction(from, to)),\n    getRevisionsAction: (page: number, loading: boolean, search?: string) => dispatch(getRevisionsAction(page, loading, search))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DashboardVinView);\n","import * as React from 'react';\nimport CopyText from '../Utils/CopyText';\nimport { parseReplicableURL } from '../../utils/common';\nimport ShowIf from '../Utils/ShowIf';\nimport * as moment from 'moment-timezone';\nimport { IParticipant } from '../../../../../../src/form/interfaces/participant.interface';\nimport * as H from 'history';\n\ninterface IPropsType<S = H.LocationState> {\n  participants: any[];\n  highlight: string[];\n  carLoading: string;\n  history: H.History<S>;\n\n  printPdf(url: string, carLoading: string): void;\n}\n\nconst DeliveriesCarDetail: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  const { participants, highlight, history, carLoading, printPdf } = props;\n  return (\n    <div className='table-responsive' style={{ border: 0 }}>\n      <table className='table table-andes table-hover table-striped'>\n        <thead>\n        <tr>\n          <th style={{ width: '18%' }} className='middle'>Detalle</th>\n          <th style={{ width: '15%' }} className='middle hidden-xs hidden-sm'>Control</th>\n          <th style={{ width: '20%' }} className='middle hidden-xs hidden-sm'>Realizado por</th>\n          <th style={{ width: '20%' }} className='middle hidden-xs hidden-sm'>Cliente</th>\n          <th style={{ width: '10%' }} className='middle hidden-xs hidden-sm'></th>\n          <th style={{ width: '1%' }} className='middle-center hidden-xs hidden-sm'></th>\n          <th style={{ width: '1%' }} />\n        </tr>\n        </thead>\n        <tbody>\n        {\n          participants.map((participant: IParticipant) => {\n            return (\n              <tr\n                key={participant._id} id={`car-${participant._id}`}\n                className={highlight.length && highlight.includes(participant._id as never) ? 'highlight-info' : ''}\n              >\n                <td\n                  className='middle'\n                  style={{\n                    paddingTop: '10px',\n                    paddingBottom: '10px'\n                  }}\n                >\n                  <div\n                    className='visible-xs visible-sm'\n                  >\n                    <strong className='text-primary'>\n                      {participant.car?.vin}\n                    </strong> <strong className='text-muted'>#{participant.number}</strong><br />\n                    <strong className={'text-muted'}>{participant.name}</strong>\n                  </div>\n                  <div\n                    className='hidden-xs hidden-sm'\n                  >\n                    <CopyText value={participant.car?.vin}>\n                      <strong\n                        className='text-primary pointer text-underline'\n                        onClick={() => history.push(parseReplicableURL(`/cars/${participant.car?._id}`))}\n                      >\n                        {participant.car?.vin}\n                      </strong>\n                    </CopyText> <strong className='text-sm text-muted'>\n                    #{participant.number}\n                  </strong>\n                  </div>\n                  <span className='visible-xs visible-sm'>\n                                  <strong\n                                    className={'text-muted'}>{participant.car?.brand}</strong><br /> {participant.car?.denomination}<br />{participant.car?.color}<br />\n                                </span>\n                  <span className='text-muted text-sm hidden-xs hidden-sm'>\n                                  <strong>{participant.car?.brand}</strong><br />{participant.car?.denomination}<br /> {participant.car?.color}\n                    <ShowIf condition={!!participant.car?.patent?.length}>\n                        <div>\n                          <i\n                            className='fa fa-fw fa-id-card-o' /> {participant.car?.patent && participant.car?.patent.length ? participant.car?.patent : '-'}\n                        </div>\n                      </ShowIf>\n                    </span>\n                  <div className='visible-xs visible-sm text-muted text-sm'>\n                                  <span><i\n                                    className='fa fa-fw fa-user-o' /> {`${participant.user ? `${participant.user.firstName} ${participant.user.lastName}` : ''}`}</span><br />\n                    <span><i className='fa fa-fw fa-flag-o' /> {`${participant.venue ? `${participant.venue.name}` : '-'}`} <ShowIf\n                      condition={participant.hasDamages}\n                    >\n                      <React.Fragment>\n                        {' '}<i\n                        className='fa fa-warning text-red'\n                        data-toggle='tooltip'\n                        data-placement='top'\n                        title='Daños encontrados en esta revisión.'\n                      />\n                      </React.Fragment>\n                    </ShowIf></span><br />\n                    <div>\n                      <i\n                        className='fa fa-clock-o fa-fw' /> {moment(participant.createdAt).fromNow()} ({moment(participant.createdAt).format('LLL')})\n                    </div>\n                    <ShowIf condition={!!participant.car?.patent?.length}>\n                      <span>\n                        <i\n                          className='fa fa-fw fa-id-card-o' /> {participant.car?.patent && participant.car?.patent.length ? participant.car?.patent : '-'}\n                      </span>\n                    </ShowIf>\n                  </div>\n                </td>\n                <td className='middle hidden-xs hidden-sm'>\n                  <strong className='text-muted text-sm'>{participant.name}</strong>\n                </td>\n                <td className='middle hidden-xs hidden-sm text-ellipsis' style={{\n                  paddingTop: '15px',\n                  paddingBottom: '15px'\n                }}>\n                  <div className='text-muted'>\n                    <strong><i\n                      className='fa fa-fw fa-user-o' /> {`${participant.user ? `${participant.user.firstName?.toLocaleUpperCase()} ${participant.user.lastName?.toLocaleUpperCase()}` : ''}`}\n                    </strong><br />\n                  </div>\n                  <div className='text-muted text-sm'><i\n                    className='fa fa-fw fa-flag-o' /> {`${participant.venue ? `${participant.venue.name}` : '-'}`} <ShowIf\n                    condition={participant.hasDamages}\n                  >\n                    <React.Fragment>\n                      {' '}<i\n                      className='fa fa-warning text-red'\n                      data-toggle='tooltip'\n                      data-placement='top'\n                      title='Daños encontrados en esta revisión.'\n                    />\n                    </React.Fragment>\n                  </ShowIf>\n                  </div>\n                  <div className='text-muted text-sm'>\n                    {`${participant.company ? `${participant.company.name}` : '-'}`}\n                  </div>\n                </td>\n                <td className='middle hidden-xs hidden-sm text-ellipsis' style={{\n                  paddingTop: '15px',\n                  paddingBottom: '15px'\n                }}>\n                  <div className='text-primary'>\n                    <strong><i\n                      className='fa fa-fw fa-user-o text-muted' /> {`${participant?.deliveryInfo?.name?.toLocaleUpperCase() ? `${participant?.deliveryInfo?.name?.toLocaleUpperCase()}` : ''}`}\n                    </strong><br />\n                  </div>\n                  <ShowIf condition={!!participant?.deliveryInfo?.rut}>\n                    <div className='text-muted text-sm'>\n                      {participant?.deliveryInfo?.rut}\n                    </div>\n                  </ShowIf>\n                  <ShowIf condition={!!participant?.deliveryInfo?.email}>\n                    <div className='text-muted text-sm'>\n                      <i className='fa fa-fw fa-envelope-o' /> {participant?.deliveryInfo?.email}\n                    </div>\n                  </ShowIf>\n                  <ShowIf condition={!!participant?.deliveryInfo?.order}>\n                    <div className='text-muted text-sm'>\n                      <i className='fa fa-fw fa-bookmark-o' /> {participant?.deliveryInfo?.order}\n                    </div>\n                  </ShowIf>\n                  <div style={{ display: 'flex', alignItems: 'stretch'}}>\n                    {/*<div className='col-md-6'>*/}\n                      {\n                        participant?.deliveryInfo?.signature?.map((image: any, index: number) => (\n                          <div key={image._id} className={'images-25'} style={{ display: index === 0 ? '' : 'none', paddingRight: '10px' }}>\n                            <a href={decodeURI(image.file.url)}\n                               data-toggle='lightbox'\n                               data-gallery={`images-${participant._id}`}\n                               data-title={`Firma cliente ${participant?.deliveryInfo?.name}`}\n                               data-footer={`Entrega ${participant.number}`}\n                            >\n                              <button\n                                className='btn btn-xs btn-default'\n                                data-toggle='tooltip'\n                                data-placement='top'\n                                title='Ver firma.'\n                              >\n                                <i className='fa fa-fw fa-pencil-square-o' />\n                              </button>\n                              {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'10px'} maxHeight={'35px'} maxWidth={'35px'} small={true}/>*/}\n                            </a>\n                          </div>\n                        ))\n                      }\n                    {/*</div>*/}\n                    {/*<div className='col-md-6'>*/}\n                      {\n                        participant?.deliveryInfo?.identifyCard?.map((image: any, index: number) => (\n                          <div key={image._id} className={'images-25'} style={{ display: index === 0 ? '' : 'none', paddingRight: '10px' }}>\n                            <a href={decodeURI(image.file.url)}\n                               data-toggle='lightbox'\n                               data-gallery={`images-${participant._id}`}\n                               data-title={`Identificación cliente ${participant?.deliveryInfo?.name}`}\n                               data-footer={`Entrega ${participant.number}`}\n                            >\n                              <button\n                                className='btn btn-xs btn-default'\n                                data-toggle='tooltip'\n                                data-placement='top'\n                                title='Ver identificación.'\n                              >\n                                <i className='fa fa-fw fa-address-card-o' />\n                              </button>\n                              {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'10px'} maxHeight={'35px'} maxWidth={'35px'} small={true}/>*/}\n                            </a>\n                          </div>\n                        ))\n                      }\n                    {/*</div>*/}\n                    {\n                        participant?.deliveryInfo?.plateEvidence?.map((image: any, index: number) => (\n                                <div key={image._id} className={'images-25'} style={{ display: index === 0 ? '' : 'none' }}>\n                                  <a href={decodeURI(image.file.url)}\n                                    data-toggle='lightbox'\n                                    data-gallery={`images-${participant._id}`}\n                                    data-title={`Evidencia patente ${participant?.deliveryInfo?.name}`}\n                                    data-footer={`Entrega ${participant.number}`}\n                                    >\n                                    <button\n                                      className='btn btn-xs btn-default'\n                                      data-toggle='tooltip'\n                                      data-placement='top'\n                                      title='Ver Automovil y patente.'\n                                      >\n                                      <i className='fa fa-fw fa-car' />\n                                    </button>\n                                    {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'10px'} maxHeight={'35px'} maxWidth={'35px'} small={true}/>*/}\n                                  </a>\n                                </div>\n                                ))\n                      }\n                  </div>\n                </td>\n                <td className='middle-center hidden-xs hidden-sm'>\n                  <div\n                    className='text-muted text-sm' data-toggle='tooltip'\n                    data-placement='top'\n                    title={moment(participant.createdAt).format('LLL')}\n                  >\n                    <i className='fa fa-fw fa-clock-o' /> {moment(participant.createdAt).fromNow()}\n                  </div>\n                </td>\n                <td className='middle-center hidden-xs hidden-sm text-muted text-sm'>\n                  {\n                    `${participant.hasOwnProperty('qualification') ?\n                      participant.qualification ? `${Math.round(participant.qualification)}%` : !participant.hasDamages ? '' : '' : ''}`\n                  }\n                </td>\n                <td className='text-primary middle-center text-ellipsis'>\n                  <div\n                    className='hidden-xs hidden-sm'\n                  >\n                    <div className='btn-group' style={{ width: '70px' }}>\n                      <button\n                        className='btn btn-sm btn-default hidden-xs hidden-sm'\n                        disabled={carLoading === participant._id}\n                        onClick={() => printPdf(`/report/forms/pdf/${participant._id}.pdf`, participant._id)}\n                      ><i className={carLoading === participant._id ? 'fa fa-spinner fa-spin' : 'fa fa-print'} /></button>\n                      <button\n                        className='btn btn-sm btn-primary'\n                        onClick={() => history.push(`/deliveries/cars/${participant.car?._id}`)}\n                      ><i className='fa fa-bars' /></button>\n                    </div>\n                  </div>\n                  <div\n                    className='visible-xs visible-sm'\n                  >\n                    <button\n                      className='btn btn-sm btn-primary'\n                      onClick={() => history.push(`/deliveries/cars/${participant.car?._id}`)}\n                    ><i className='fa fa-bars' /></button>\n                  </div>\n                </td>\n              </tr>\n            );\n          })\n        }\n        </tbody>\n      </table>\n    </div>\n  );\n};\n\nexport default DeliveriesCarDetail;\n","import { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport AppContainer from '../../container/AppContainer';\nimport * as Raven from 'raven-js';\nimport { IDeliveriesActionTypes, IDeliveriesState, IDeliveryDispatch } from '../../actions/deliveries.types';\nimport DeliveriesActions from '../../actions/deliveries.actions';\nimport ShowIf from '../Utils/ShowIf';\nimport Paginator from '../Utils/Paginator';\nimport * as moment from 'moment-timezone';\nimport * as swal from 'sweetalert';\nimport DeliveriesCarDetail from './DeliveriesCarDetail';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport DateRangeInput from '../Utils/DateRangeInput';\nimport * as daterangepicker from 'daterangepicker';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { io } from 'socket.io-client';\nimport { IWindow } from '../../interfaces/window';\nimport { debounce } from 'throttle-debounce';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<IDeliveriesActionTypes>;\n  deliveries: IDeliveriesState;\n  deliveriesActions: DeliveriesActions;\n}\n\ninterface IStateType {\n  error: Error | null;\n  highlight: string[];\n  carLoading: string;\n}\n\nclass DeliveriesView extends TrackingBasePage<IPropsType, IStateType> {\n\n  public title: string;\n\n  protected isMount: boolean = false;\n  protected printIframe: any;\n\n  private socket: Socket;\n\n  readonly state: IStateType = {\n    error: null,\n    highlight: [],\n    carLoading: ''\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Entregas';\n    this.filterForms = this.filterForms.bind(this);\n    this.filterAllForms = this.filterAllForms.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.getDateRangeOptions = this.getDateRangeOptions.bind(this);\n    this.downloadReport = this.downloadReport.bind(this);\n    this.printPdf = this.printPdf.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.onChangeSearch = this.onChangeSearch.bind(this);\n    this.debounceOnChangeSearch = debounce(300, this.debounceOnChangeSearch);\n    this.onChangeSearchDelivery = this.onChangeSearchDelivery.bind(this);\n    this.debounceOnChangeSearchDelivery = debounce(300, this.debounceOnChangeSearchDelivery);\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { page } = this.props.deliveries.pagination;\n    const { deliveriesActions } = this.props;\n    deliveriesActions.getDeliveriesThunkAction(page, true);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `deliveries-view-${window.user.team._id}` });\n    });\n\n    this.socket.on('REFRESH', (data: any): void => {\n      const { page } = this.props.deliveries.pagination;\n      const { forms } = this.props.deliveries;\n      if (data.update && window.user.venuesAccess.includes(data.venueId) && forms.map((form: IForm) => form._id).includes(data.formId)) {\n        deliveriesActions.getDeliveriesThunkAction(page, false);\n        ($ as any).toast({\n          heading: data.notification.title,\n          text: data.notification.text,\n          position: 'top-right',\n          loaderBg: '#e2e2e2',\n          icon: 'success',\n          hideAfter: 5000,\n          stack: 6\n        } as any);\n        if (!this.state.highlight.includes(data.car)) {\n          this.setState({\n            highlight: [data.car, ...this.state.highlight]\n          });\n        } else {\n          this.setState({\n            highlight: this.state.highlight.filter((e) => e !== data.car)\n          }, () => {\n            this.setState({\n              highlight: [data.car, ...this.state.highlight]\n            });\n          });\n        }\n        setTimeout(() => {\n          if (this.isMount) {\n            this.setState({\n              highlight: this.state.highlight.filter((e) => e !== data.car)\n            });\n          }\n        }, 3000);\n      }\n    });\n\n    this.isMount = true;\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    this.isMount = false;\n    if (this.props.deliveries.source) {\n      this.props.deliveries.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { participants, forms, pagination, loading, filters } = this.props.deliveries;\n    const { highlight, carLoading } = this.state;\n    return (\n      <AppContainer title={this.title} cMenu='1' cSubMenu='1.8'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Controles <small>{pagination.count}</small>\n              </h3>\n              <div className='box-tools pull-right'>\n                <button\n                  className='btn btn-sm btn-primary hidden-xs hidden-sm hidden-sm'\n                  onClick={this.downloadReport}\n                >\n                  <i className='fa fa-fw fa-download' /> Exportar\n                </button>\n              </div>\n            </div>\n            <div className={`box-body no-padding`}>\n              <div className='row no-margin'>\n                <div className='col-md-6 no-padding'>\n                  <div style={{ padding: '10px' }}>\n                    <BootstrapSelect\n                      noneSelectedText='Todos los controles'\n                      displayItems={4}\n                      sm={true}\n                      autoClouse={true}\n                      selectedText='formularios seleccionadas.'\n                      selected={filters.forms}\n                      allOption={true}\n                      selectAll={this.filterAllForms}\n                      separator=' - '\n                      options={forms.map((form: IForm) => ({\n                        value: form._id,\n                        text: form.name\n                      }))}\n                      onClick={this.filterForms}\n                      notHideOnClickOutside={false}\n                    />\n                  </div>\n                </div>\n                <div className='col-md-6 no-padding'>\n                  <div style={{ padding: '10px' }}>\n                    <DateRangeInput\n                      options={this.getDateRangeOptions()}\n                      onChange={this.onDateRangeChange}\n                      startDate={filters.from}\n                      endDate={filters.to}\n                    />\n                  </div>\n                </div>\n              </div>\n              <div className='row no-margin'>\n                <div className='col-md-6 no-padding'>\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type='text'\n                      className='form-control pull-right'\n                      onChange={this.onChangeSearch}\n                      value={filters.searchText}\n                      placeholder='Buscar por VIN, marca, vendedor o sucursal' />\n                    <div className='input-group-btn'>\n                      <button className='btn btn-default'><i className='fa fa-search' /></button>\n                    </div>\n                  </div>\n                </div>\n                <div className='col-md-6 no-padding'>\n                  <div\n                    className='input-group input-group-sm'\n                    style={{ padding: '10px' }}\n                  >\n                    <input\n                      type='text'\n                      className='form-control pull-right'\n                      onChange={this.onChangeSearchDelivery}\n                      value={filters.searchDelivery}\n                      placeholder='Buscar por nombre, rut, email u orden del cliente. ' />\n                    <div className='input-group-btn'>\n                      <button className='btn btn-default'><i className='fa fa-search' /></button>\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <ShowIf\n                condition={participants.length > 0}\n                alternative={\n                  <ShowIf condition={!loading}>\n                    <p style={{ padding: '10px' }}>\n                      <strong>No se han encontrado entregas.</strong>\n                    </p>\n                  </ShowIf>\n                }\n              >\n                <DeliveriesCarDetail\n                  participants={participants}\n                  highlight={highlight}\n                  carLoading={carLoading}\n                  history={this.props.history}\n                  printPdf={this.printPdf}\n                />\n              </ShowIf>\n            </div>\n            <ShowIf condition={pagination.pages > 1}>\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                    <span className='react-bootstrap-table-pagination-total text-ellipsis'>\n                      &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                      </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator\n                        changePage={this.changePage}\n                        page={pagination.page}\n                        pages={pagination.pages}\n                      />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </ShowIf>\n            <ShowIf condition={loading && !participants.length}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onChangeSearch(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const { value } = e.target;\n    const { deliveriesActions } = this.props;\n    deliveriesActions.changeFilterAction({ searchText: value });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearch(): void {\n    const { deliveriesActions } = this.props;\n    deliveriesActions.getDeliveriesThunkAction(1, false);\n  }\n\n  private onChangeSearchDelivery(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const { value } = e.target;\n    const { deliveriesActions } = this.props;\n    deliveriesActions.changeFilterAction({ searchDelivery: value });\n    this.debounceOnChangeSearch();\n  }\n\n  private debounceOnChangeSearchDelivery(): void {\n    const { deliveriesActions } = this.props;\n    deliveriesActions.getDeliveriesThunkAction(1, false);\n  }\n\n  private filterForms(value: any) {\n    const { deliveriesActions } = this.props;\n    const { filters } = this.props.deliveries;\n    let sForms = [...filters.forms];\n\n    sForms = sForms.includes(value)\n      ? sForms.filter((form: string) => form !== value)\n      : [value, ...filters.forms];\n\n    deliveriesActions.updateFiltersAction({ forms: sForms });\n  }\n\n  private filterAllForms(): void {\n    const { deliveriesActions } = this.props;\n    const { forms } = this.props.deliveries;\n    deliveriesActions.updateFiltersAction({\n      forms: forms.map((form: IForm) => form._id)\n    });\n  }\n\n  private onDateRangeChange(from: Date, to: Date): void {\n    const { deliveriesActions } = this.props;\n    deliveriesActions.updateFiltersAction({ from, to });\n  }\n\n  public printPdf(url: string, carLoading: string): void {\n    this.setState({ carLoading });\n    let iframe: any = this.printIframe;\n    const timezone = moment.tz.guess();\n    if (!this.printIframe) {\n      iframe = this.printIframe = document.createElement('iframe');\n      window.document.body.appendChild(iframe);\n      iframe.style.display = 'none';\n      iframe.onload = () => {\n        setTimeout(() => {\n          iframe.focus();\n          iframe.contentWindow.print();\n          this.setState({ carLoading: '' });\n          // document.body.removeChild(iframe)\n        }, 1);\n      };\n    }\n    iframe.src = `${url}?timezone=${timezone}`;\n  }\n\n  private downloadReport(): void {\n    const { from, to, forms, searchText } = this.props.deliveries.filters;\n    const monthsDiff = moment(to).diff(moment(from), 'months');\n    this.trackClick('Descargar acta de entregas', {\n      from,\n      to\n    });\n    if (monthsDiff > 3) {\n      swal!('Revisiones', 'Selecciona un rango que 3 meses para descargar la información', 'error');\n    } else {\n      let query = `?deliveries=1&from=${moment(from).unix()}&to=${moment(to).unix()}`;\n      if (searchText.trim().length) {\n        query += `&search=${searchText}`;\n      }\n      if (forms) {\n        query += `&forms=${forms.join(',')}`;\n      }\n      window.open(`/api/participant/export/${query}`, '_blank');\n    }\n  }\n\n  private changePage(page: number): void {\n    const { deliveriesActions } = this.props;\n    deliveriesActions.getDeliveriesThunkAction(page, false);\n    window.scrollTo(0, 0);\n  }\n\n  private getDateRangeOptions(): daterangepicker.Options {\n    return {\n      // startDate: moment().subtract(11, 'months').startOf('month').toDate(),\n      // endDate: moment().toDate(),\n      maxDate: moment().toDate(),\n      locale: {\n        format: 'DD/MM/YYYY',\n        customRangeLabel: 'Período personalizado',\n        applyLabel: 'Aplicar',\n        cancelLabel: 'Cancelar'\n      },\n      ranges: {\n        'Este mes': [moment().startOf('month').startOf('month'), moment().endOf('month')],\n        'Últimos 3 meses': [moment().startOf('month').subtract(3, 'months').startOf('month'), moment().endOf('month')],\n        'Últimos 6 meses': [moment().startOf('month').subtract(6, 'months').startOf('month'), moment().endOf('month')],\n        'Último año': [moment().startOf('month').subtract(12, 'months').startOf('month'), moment().endOf('month')]\n      },\n      opens: 'left'\n    };\n  }\n}\n\nconst mapStateToProps = (state: { deliveries: IDeliveriesState }) => {\n  return {\n    deliveries: state.deliveries\n  };\n};\n\nconst mapDispatchToProps = (dispatch: IDeliveryDispatch) => {\n  const deliveriesActions = new DeliveriesActions(dispatch);\n  return {\n    dispatch,\n    deliveriesActions\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(DeliveriesView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, FieldArray, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IFormsState } from '../../actions/form.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\nimport FormTriggerRenderItem, { IFormTriggerRenderItemItemProps } from './renders/FormTriggerRender';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n  forms: IFormsState;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed, forms} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-12'>\n            <FieldArray<IFormTriggerRenderItemItemProps>\n              name='triggers'\n              component={FormTriggerRenderItem}\n              props={{\n                forms\n              }}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst FormForm = reduxForm({\n  form: 'formForm'\n})(Form);\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ forms: IFormsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(FormForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { FormReduxActions, IFormsState } from '../../actions/form.types';\nimport {\n  createFormThunkAction,\n  deleteFormItemThunkAction,\n  getFormsThunkAction,\n  updateFormThunkAction,\n  updateFormWithoutThunkAction\n} from '../../actions/form.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport FormSettingsForm from './FormForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\n\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<FormReduxActions | FormAction>;\n  forms: IFormsState;\n\n  getFormThunkAction(nextPage: number, hideLoading?: boolean): FormReduxActions;\n\n  createFormThunkAction(form: IForm): FormReduxActions;\n\n  updateFormThunkAction(form: IForm): FormReduxActions;\n\n  updateFormWithoutThunkAction(form: IForm): FormReduxActions;\n\n  deleteFormThunkAction(form: IForm): FormReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass FormListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Formularios';\n    this.changePage = this.changePage.bind(this);\n    this.createForm = this.createForm.bind(this);\n    this.processCreateForm = this.processCreateForm.bind(this);\n    this.updateForm = this.updateForm.bind(this);\n    this.processUpdateForm = this.processUpdateForm.bind(this);\n    this.deleteForm = this.deleteForm.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.forms;\n    // const { orderBy, orderType } = this.props.form.options;\n    this.props.getFormThunkAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `forms-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.forms;\n        // const { orderBy, orderType } = this.props.form.options;\n        this.props.getFormThunkAction(pagination.page, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.forms.pagination !== prevProps.forms.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.forms.source) {\n      this.props.forms.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, forms, pagination } = this.props.forms;\n    const canEdit = true;\n    const canDelete = true;\n    return (\n      <AppContainer title='' cMenu='1' cSubMenu='1.10' cAction='Formularios'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/requests/settings/forms/' className='list-group-item active'>\n                    Formularios\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Formularios <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                    <ShowIf condition={(process.env.NODE_ENV === 'development')}>\n                      <button\n                        className='btn btn-sm btn-success'\n                        onClick={this.createForm}\n                      >\n                        <i className='fa fa-plus' /> Agregar\n                      </button>\n                    </ShowIf>\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <table className='table table-andes table-striped'>\n                    <thead>\n                    <tr>\n                      <th style={{ width: '70%' }} className='middle'>Nombre</th>\n                      <th style={{ width: '16%' }} className='middle-center'>Activo</th>\n                      <th style={{ width: '15%' }} className='middle-center'>Triggers</th>\n                      <ShowIf condition={canEdit}>\n                        <th style={{ width: '1%' }} className='width-10' />\n                      </ShowIf>\n                      <ShowIf condition={canDelete}>\n                        <th style={{ width: '1%' }} className='width-10' />\n                      </ShowIf>\n                    </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      forms.map((item) => {\n                        return (\n                          <tr key={item._id}>\n                            <td\n                              className={`middle ${!item.active ? 'line-through text-muted' : 'text-primary'}`}\n                            >\n                              <strong>\n                                {item.name}\n                              </strong>\n                            </td>\n                            <td className='middle-center' style={{ paddingTop: '15px' }}>\n                              <BootstrapSwitch\n                                checked={item.active}\n                                onChange={() => {\n                                  this.props.updateFormWithoutThunkAction({\n                                    ...item,\n                                    active: !item.active\n                                  });\n                                }}\n                              />\n                            </td>\n                            <td className='middle-center text-muted'>\n                              {item.triggers?.length ?? 0}\n                            </td>\n                            <ShowIf condition={canEdit}>\n                              <td\n                                className='middle text-blue pointer'\n                                onClick={() => this.updateForm(item)}\n                              >\n                                <i className='fa fa-gears' />\n                              </td>\n                            </ShowIf>\n                            <ShowIf condition={canDelete}>\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteForm(item)}\n                              >\n                                <i className='fa fa-minus-circle' />\n                              </td>\n                            </ShowIf>\n                          </tr>\n                        );\n                      })\n                    }\n                    </tbody>\n                  </table>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createForm(): void {\n    this.props.loadDataAction(\n      'Agregar formulario',\n      <FormSettingsForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateForm}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('formForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateForm(form: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createFormThunkAction(form);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private updateForm(form: any): void {\n    this.props.loadDataAction(\n      'Editar formulario',\n      <FormSettingsForm\n        initialValues={{ update: false, ...form }}\n        onSubmit={this.processUpdateForm}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('formForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateForm(form: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateFormThunkAction(form);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  private deleteForm(form: IForm): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el formulario: ${form.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteFormThunkAction(form);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    // const { orderBy, orderType } = this.props.form.options;\n    this.props.getFormThunkAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getFormThunkAction: (nextPage: number, hideLoading?: boolean) => dispatch(getFormsThunkAction(nextPage, hideLoading)),\n    createFormThunkAction: (form: IForm) => dispatch(createFormThunkAction(form)),\n    updateFormThunkAction: (form: IForm) => dispatch(updateFormThunkAction(form)),\n    updateFormWithoutThunkAction: (form: IForm) => dispatch(updateFormWithoutThunkAction(form)),\n    deleteFormThunkAction: (form: IForm) => dispatch(deleteFormItemThunkAction(form)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ forms: IFormsState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(FormListView);\n","import * as React from 'react';\nimport { Field, formValueSelector, WrappedFieldArrayProps } from 'redux-form';\nimport { connect } from 'react-redux';\nimport { IFormsState } from '../../../actions/form.types';\nimport InputField from '../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../Utils/forms/validations';\nimport CheckBoxField from '../../Utils/forms/CheckBoxField';\nimport SelectField from '../../Utils/forms/SelectField';\nimport { KindTrigger } from '../../../../../../../src/form/models/trigger.types';\nimport FormFileTriggerRender from './TriggersTypes/FormFileTriggerRender';\nimport FormEmailTriggerRender from './TriggersTypes/FormEmaiTriggerRender';\nimport FormRequestTriggerRender from './TriggersTypes/FormRequestTriggerRender';\nimport ShowIf from '../../Utils/ShowIf';\nimport FormIntegrationTriggerRender from './TriggersTypes/FormIntegrationTriggerRender';\nimport * as uuid from 'uuid';\nimport FormTransmittalTriggerRender from './TriggersTypes/FormTransmittalTriggerRender';\n\n\nexport interface IFormTriggerRenderItemItemProps {\n  forms: IFormsState;\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IFormTriggerRenderItemItemProps {\n  formValues: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  openTabs: string[];\n}\n\nclass FormTriggerRender extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    openTabs: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, meta: { error, submitFailed }, forms } = this.props;\n    const { openTabs } = this.state;\n    return (\n      <React.Fragment>\n        <h4>Triggers</h4>\n        <ShowIf condition={!fields?.length}>\n          <div className='row'>\n            <div className='col-md-12'>\n              <p\n                className='text-center text-muted'\n                style={{ padding: '20px 0' }}\n              >\n                No hay triggers para agregar uno <a href='javascript:void(0)'\n                                                    onClick={() => fields.push({\n                                                      tid: uuid.v4(),\n                                                      enabled: true,\n                                                      config: { method: 'post' }\n                                                    })}>haz click aquí.</a>\n              </p>\n            </div>\n          </div>\n        </ShowIf>\n        {\n          fields.map((item, index) => {\n            const value: any = fields.get(index);\n            const openTab = openTabs.includes(value._id ?? value.tid);\n            return (\n              <div className='row' key={index} style={{ paddingTop: '10px' }}>\n                <div className='col-md-4' style={{ backgroundColor: '#fff' }}>\n                  <Field\n                    name={`${item}.name`}\n                    label='Nombre *'\n                    placeholder='Nombre'\n                    type='text'\n                    component={InputField}\n                    validate={[inputStringRequired]}\n                  />\n                </div>\n                <div className='col-md-4' style={{ backgroundColor: '#fff' }}>\n                  <Field\n                    name={`${item}.kind`}\n                    label='Tipo *'\n                    component={SelectField}\n                    validate={[inputStringRequired]}\n                  >\n                    <option value={''} disabled={true}>Seleccione</option>\n                    <option key={KindTrigger.file} value={KindTrigger.file}>Archivo</option>\n                    <option key={KindTrigger.email} value={KindTrigger.email}>Correo</option>\n                    <option key={KindTrigger.request} value={KindTrigger.request}>Estado solicitudes</option>\n                    <option key={KindTrigger.integration} value={KindTrigger.integration}>Integraciones</option>\n                    <option key={KindTrigger.transmittal} value={KindTrigger.transmittal}>Cierre OT</option>\n                  </Field>\n                </div>\n                <div className='col-md-2' style={{ backgroundColor: '#fff', paddingBottom: '13px' }}>\n                  <Field\n                    name={`${item}.enabled`}\n                    label='Activo'\n                    placeholder='Activo'\n                    type='checkbox'\n                    component={CheckBoxField}\n                    props={{\n                      style: {\n                        marginBottom: 0,\n                        marginTop: '30px'\n                      }\n                    }}\n                    validate={[]}\n                  />\n                </div>\n                <div\n                  className={`col-md-2 pointer text-right`}\n                  style={{ paddingTop: '30px', paddingBottom: '10px', backgroundColor: '#fff' }}\n                >\n                  <ul className='list-inline'>\n                    <li onClick={() => fields.remove(index)} style={{ padding: '0 10px' }}>\n                      <i className='fa fa-minus-circle text-red' />\n                    </li>\n                    <li onClick={() => this.toogleTab(value._id ?? value.tid)} style={{ padding: '0 10px' }}>\n                      {\n                        openTab ? <i className='fa fa-chevron-up' /> : <i className='fa fa-chevron-down' />\n                      }\n                    </li>\n                  </ul>\n                </div>\n                <ShowIf condition={openTab}>\n                  <div\n                    className='col-md-12'\n                    style={{ backgroundColor: '#f4f4f4', paddingTop: '10px', paddingBottom: '10px' }}\n                  >\n                    <ShowIf condition={KindTrigger.file === value.kind}>\n                      <FormFileTriggerRender item={item} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.email === value.kind}>\n                      <FormEmailTriggerRender item={item} value={value} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.request === value.kind}>\n                      <FormRequestTriggerRender item={item} forms={forms} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.integration === value.kind}>\n                      <FormIntegrationTriggerRender item={item} />\n                    </ShowIf>\n                    <ShowIf condition={KindTrigger.transmittal === value.kind}>\n                      <FormTransmittalTriggerRender item={item} forms={forms} />\n                    </ShowIf>\n                    <ShowIf condition={!value.kind}>\n                      <span className={'text-muted'}>Seleccione un tipo</span>\n                    </ShowIf>\n                  </div>\n                </ShowIf>\n              </div>\n            );\n          })\n        }\n        <div className='row' style={{ padding: '15px 0' }}>\n          <div className='col-md-12 text-right'>\n            <button\n              className='btn btn-sm btn-success'\n              onClick={() => fields.push({\n                  tid: uuid.v4(),\n                  enabled: true,\n                  config: { method: 'post' }\n                }\n              )}\n            >\n              <i className='fa fa-plus' /> Agregar trigger\n            </button>\n          </div>\n        </div>\n        {submitFailed && error && <span>{error}</span>}\n      </React.Fragment>\n    );\n  }\n\n  private toogleTab(id: string) {\n    const { openTabs } = this.state;\n    if (openTabs.includes(id)) {\n      this.setState({\n        openTabs: [...openTabs.filter(tab => tab !== id)]\n      });\n    } else {\n      this.setState({\n        openTabs: [...openTabs, id]\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  const selector = formValueSelector('formTypeForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IFormTriggerRenderItemItemProps>(mapStateToProps, mapDispatchToProps)(FormTriggerRender);\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport CheckBoxField from \"../../../Utils/forms/CheckBoxField\";\n\ninterface IPropsType {\n  item: string;\n  value: any;\n}\n\ninterface IStateType {\n}\n\nclass FormEmailTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item, value } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.subject`}\n            label='Asunto del correo'\n            placeholder='ACTA DE ENTREGA '\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.template`}\n            label='Template del correo'\n            placeholder='vouchers/client-sell.pug'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.responsible`}\n            label='Enviar a responsables de sucursales'\n            type='checkbox'\n            component={CheckBoxField}\n            validate={[]}\n          />\n        </div>\n        { !value.config.responsible ?\n          <>\n          <div className='col-md-10'>\n            <Field\n              name={`${item}.config.fullname`}\n              label='ID pregunta con nombre / campo del usuario que responde / nombre fijo'\n              placeholder=''\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-10'>\n            <Field\n              name={`${item}.config.email`}\n              label='ID pregunta con email / campo del usuario que responde / email fijo'\n              placeholder='example@email.com'\n              type='text'\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n        </> : null }\n      </div>\n    );\n  }\n}\n\nexport default FormEmailTriggerRender;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\n\ninterface IPropsType {\n  item: string;\n}\n\ninterface IStateType {\n}\n\nclass FormFileTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.filename`}\n            label='Nombre del archivo'\n            placeholder='voucher.pdf'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.template`}\n            label='Template del archivo'\n            placeholder='vouchers/client-sell.pug'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.signature`}\n            label='ID Signature question (Si desea utilizarla en el template)'\n            placeholder='618ad37fdf7f091efa6c6633'\n            type='text'\n            component={InputField}\n            validate={[]}\n          />\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default FormFileTriggerRender;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport TextAreaField from '../../../Utils/forms/TextAreaField';\nimport SelectField from '../../../Utils/forms/SelectField';\n\ninterface IPropsType {\n  item: string;\n}\n\ninterface IStateType {\n}\n\nclass FormIntegrationTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.url`}\n            label='URL'\n            placeholder='https://api.osacontrol.com'\n            type='text'\n            component={InputField}\n            validate={[inputStringRequired]}\n          />\n        </div>\n        <div className='col-md-10'>\n           <Field\n            name={`${item}.config.method`}\n            label='Tipo *'\n            component={SelectField}\n            validate={[inputStringRequired]}\n          >\n            <option value={''} disabled={true}>Seleccione</option>\n            <option value={'post'}>post</option>\n          </Field>\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.header`}\n            label='Header'\n            placeholder='Authorization: API-KEY 71fMfsbE6PRamEZrK5iw6TiD1iN416yM'\n            type='text'\n            component={InputField}\n            validate={[]}\n          />\n        </div>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.body`}\n            label='Payload'\n            placeholder='{\"action\": \"hook\"}'\n            component={TextAreaField}\n            type='text'\n            rows={4}\n            props={{\n              resize: 'none'\n            }}\n          />\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default FormIntegrationTriggerRender;\n","import * as React from 'react';\nimport { Field } from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport SelectField from '../../../Utils/forms/SelectField';\nimport { IFormsState } from '../../../../actions/form.types';\nimport { connect } from 'react-redux';\nimport { IFormTriggerRenderItemItemProps } from '../FormTriggerRender';\n\ninterface IPropsType {\n  item: string;\n  forms: IFormsState;\n}\n\ninterface IStateType {\n}\n\nclass FormRequestTriggerRender extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const { item, forms: {requestStatus} } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.requestItemStatus`}\n            label='Tipo *'\n            component={SelectField}\n            validate={[inputStringRequired]}\n          >\n            <option value={''} disabled={true}>Seleccione</option>\n            {\n              requestStatus.map((status) => (\n                <option key={status._id} value={status._id}>{status.name}</option>\n              ))\n            }\n          </Field>\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { forms: IFormsState }) => {\n  return {\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IFormTriggerRenderItemItemProps>(mapStateToProps, mapDispatchToProps)(FormRequestTriggerRender);\n","import * as React from 'react';\nimport {autofill, Field, getFormValues, InjectedFormProps, WrappedFieldArrayProps} from 'redux-form';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport { IFormsState } from '../../../../actions/form.types';\nimport { connect } from 'react-redux';\nimport { IFormTriggerRenderItemItemProps } from '../FormTriggerRender';\nimport BootstrapSelectField from \"../../../Utils/forms/BootstrapSelectField\";\nimport {Dispatch} from \"redux\";\nimport {get} from \"lodash\";\n\ninterface IPropsType {\n\n  dispatch: Dispatch<any>;\n  item: string;\n  forms: IFormsState;\n}\n\n\ninterface IPropsFullType {\n  formValues?: any;\n  dispatch?: Dispatch<any>;\n  item: string;\n  forms: IFormsState;\n}\n\n\ninterface IStateType {\n}\n\nclass FormTransmittalTriggerRender extends React.Component<IPropsFullType, IStateType> {\n  public render(): React.ReactElement<IPropsFullType> {\n    const { item, forms: {milestoneTypes} } = this.props;\n    return (\n      <div className={`row`}>\n        <div className='col-md-10'>\n          <Field\n            name={`${item}.config.transmittalTypes`}\n            label='Tipo de Hito en el/los cual(es) intenta cerrar la OT *'\n            component={BootstrapSelectField}\n            validate={[inputStringRequired]}\n            props={{\n              noneSelectedText: 'Selecciona un tipo',\n              selectedText: 'tipo seleccionad0.',\n              autoClouse: false,\n              sm: true,\n              allOption: true,\n              search: true,\n              options: [\n                ...milestoneTypes.map((milestoneType) => ({\n                  value: milestoneType._id,\n                  text: milestoneType.name\n                }))\n              ],\n              selectAll: (all: boolean) => {\n                this.props.dispatch!!(autofill('formForm', `${item}.config.transmittalTypes`, all ? milestoneTypes.map(mT => mT._id) : []))\n              },\n              onClick: (value: string) => {\n                let currentValue = get(this.props.formValues!!, `${item}.config.transmittalTypes`) ?? [];\n                if (currentValue.includes(value))\n                  currentValue = currentValue.filter((v: string) => v !== value)\n                else\n                  currentValue.push(value)\n                this.props.dispatch!!(autofill('formForm', `${item}.config.transmittalTypes`, currentValue))\n              }\n            }}\n          />\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: any) => {\n  return {\n    formValues: getFormValues('formForm')(state),\n    forms: state.forms\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IFormTriggerRenderItemItemProps>(mapStateToProps, mapDispatchToProps)(FormTransmittalTriggerRender);\n","import Axios, {AxiosError} from 'axios';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo, RefObject} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport * as uuid from 'uuid';\nimport * as XLSX from 'xlsx';\nimport {IUsersState, UserReduxAction} from '../../actions/users.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\nenum carStatus {\n  Error,\n  Pending,\n  Finish\n}\n\ninterface IImportCar {\n  id?: string;\n  NInterno: string;\n  vin: string;\n  marca: string;\n  denominacion: string;\n  patente: string;\n  color: string;\n  destino: string;\n  status: number;\n}\n\ninterface ICarObject {\n  [key: string]: IImportCar;\n}\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<UserReduxAction>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loadFile: boolean;\n  cars: IImportCar[];\n  carsObj: ICarObject;\n  canDrop: boolean;\n}\n\nclass ImportCarsView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  // static propTypes = {\n  //   users: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  state = {\n    error: null,\n    loadFile: false,\n    cars: [],\n    canDrop: false,\n    carsObj: {}\n  };\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  // private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar autos';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.startLoad = this.startLoad.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.inputFile = React.createRef();\n  }\n\n componentDidMount() {\n   super.componentDidMount();\n }\n\n  public componentWillUnmount() {\n    // this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {cars, loadFile} = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"1\" cSubMenu=\"1.0\"  cAction=\"Importar\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar autos</h3>\n              <div className=\"pull-right box-tools\">\n                <button\n                  className=\"btn btn-sm btn-primary\"\n                  onClick={this.downloadTemplate}\n                  style={{marginRight: '5px'}}>\n                  <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                </button>\n                {\n                  cars.length >= 1 ? <button\n                    className=\"btn btn-sm btn-default\"\n                    onClick={this.clickUploadFile}>\n                    <i className=\"fa fa-fw fa-cloud-upload\"/> {cars.length >= 1 ? 'Cargar otro excel' : 'Subir excel'}\n                  </button> : null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <input\n                    type=\"file\"\n                    ref={this.inputFile}\n                    style={{display: 'none'}}\n                    onChange={this.handleChangeInputFile}\n                    accept=\".xlsx, .xls\"\n                  />\n                </div>\n              </div>\n              {\n                cars.length ?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      {\n                        loadFile ? <div>\n                          Cargando...\n                        </div> :\n                          <div className=\"pull-right\">\n                            <button className=\"btn btn-sm btn-flat btn-success\" onClick={this.startLoad}>\n                              <i className=\"fa fa-fw fa-play\" /> Iniciar carga\n                            </button>\n                          </div>\n                      }\n                      <table className=\"table\">\n                        <thead>\n                        <tr>\n                          <th>Nº Interno</th>\n                          <th>VIN</th>\n                          <th>Patente</th>\n                          <th>Marca</th>\n                          <th>Denominación</th>\n                          <th>Color</th>\n                          <th>Destino</th>\n                        </tr>\n                        </thead>\n                        <tbody>\n                        {\n                          cars.map((car: IImportCar) => {\n                            let classTR = '';\n                            if (car.status === carStatus.Finish) {\n                              classTR = 'success';\n                            } else if (car.status === carStatus.Error) {\n                              classTR = 'danger';\n                            }\n                            return (\n                              <tr key={car.id} className={classTR}>\n                                <td>{car.NInterno}</td>\n                                <td>{car.vin}</td>\n                                <td>{car.patente}</td>\n                                <td>{car.marca}</td>\n                                <td>{car.denominacion}</td>\n                                <td>{car.color}</td>\n                                <td>{car.destino}</td>\n                              </tr>\n                            );\n                          })\n                        }\n                        </tbody>\n                      </table>\n                    </div>\n                  </div> : <div\n                  className=\"upload-file text-center pointer\"\n                  onClick={this.clickUploadFile}\n                  onDrop={this.handleDrop}\n                  onDragOver={this.dragOverHandler}\n                  onDragEnd={this.dragEndHandler}\n                  onDragLeave={this.dragLeaveHandler}\n                  style={{\n                    backgroundColor: '#EEEEEE',\n                    border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                    padding: '100px 20px',\n                    color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                    borderRadius: '5px',\n                    marginBottom: '10px'\n                  }}>\n                  <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                  Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                </div>\n              }\n            </div>\n            {\n              loadFile &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private startLoad() {\n    const {cars} = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a cargar ${cars.length} autos, recuerda que puedes revisar que los datos estén correctos en la pre visualización del Excel.`,\n      icon: 'warning',\n      buttons: true,\n      dangerMode: true\n    } as any)\n      .then((willDelete) => {\n        if (willDelete) {\n          const api: ApiService = new ApiService();\n          this.setState({\n            loadFile: true\n          });\n          api\n            .getSource();\n\n          let slicedCars = []\n          const chunkSize = 1000;\n          for (let i = 0; i < cars.length; i += chunkSize){\n            slicedCars.push(\n              cars.slice(i, i + chunkSize)\n            );\n          }\n\n          Axios.all(slicedCars.map(sCars =>  api\n            .sendImportCars({cars: sCars})))\n            .then(() => {\n              swal('Importador de autos', 'La carga a finalizado exitosamente.', 'success');\n              this.setState({\n                loadFile: false,\n                cars: this.state.cars.map((car: IImportCar) => {\n                  car.status = carStatus.Finish;\n                  return car;\n                })\n              });\n            })\n            .catch((err: AxiosError) => {\n              api.errorHandler(err);\n            });\n        }\n      });\n\n  }\n\n  private clickUploadFile() {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private downloadTemplate() {\n    /* headers worksheet */\n    const data = [{\n     NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: ''\n      // motor: '',\n      // destino: ''\n    }];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_import_cars_v1.1.xlsx');\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>) {\n    const {files} = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      this.processSettings(file);\n    }\n  }\n\n  private processSettings(file: File): void {\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const cars: IImportCar[] = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n          if (cars.length >= 1) {\n            this.setState({\n              cars: cars.map((car) => {\n                car.id = uuid.v1();\n                car.status = carStatus.Pending;\n                return car;\n              })\n            });\n          } else {\n            swal('Importador de autos', 'Este excel no cumple con los requisitos mínimos o no tiene autos.', 'error');\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(ImportCarsView);\n","import * as React from \"react\";\nimport {Field, InjectedFormProps, reduxForm} from 'redux-form'\nimport {RouteComponentProps} from \"react-router\";\nimport {IUsersState, UserReduxAction} from \"../../actions/users.actions\";\nimport {connect} from \"react-redux\";\nimport InputField from \"../Utils/forms/InputField\";\nimport {Dispatch} from \"redux\";\nimport {inputStringRequired} from \"../../utils/formValidations\";\nimport BootstrapSelectField from \"../Utils/forms/BootstrapSelectField\";\n\ninterface IPropsType extends InjectedFormProps, RouteComponentProps<{}> {\n  dispatch: Dispatch<UserReduxAction>;\n  users: IUsersState;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public render(): React.ReactElement<IPropsType> {\n    const {companies} = this.props.users;\n    return (\n      <React.Fragment>\n        <ul className=\"nav nav-tabs\" style={{marginBottom: '15px'}}>\n          <li className=\"active\"><a data-toggle=\"tab\" href=\"#general\">General</a></li>\n          {/*{*/}\n          {/*  window.user.isAdmin ?*/}\n          {/*    <li><a data-toggle=\"tab\" href=\"#permissions\">Permisos</a></li>*/}\n          {/*    : null*/}\n          {/*}*/}\n          {/*<li><a data-toggle=\"tab\" href=\"#access\">Accesos</a></li>*/}\n        </ul>\n        <div className=\"tab-content\">\n          <div id=\"general\" className=\"tab-pane fade in active\">\n            <div className=\"row\">\n              <div className=\"col-md-12\">\n                <Field\n                  name={`firstName`}\n                  label=\"Nombre\"\n                  type=\"text\"\n                  validate={[inputStringRequired]}\n                  component={InputField}\n                />\n              </div>\n              <div className=\"col-md-12\">\n                <Field\n                  name={`company`}\n                  label=\"Empresa\"\n                  props={{\n                    noneSelectedText: 'Seleccione...',\n                    displayItems: 2,\n                    selectedText: 'empresas seleccionadas.',\n                    autoClouse: true,\n                    sm: true,\n                    allOption: false,\n                    search: true,\n                    options: [\n                      ...companies.map((company) => ({\n                        value: company._id,\n                        text: company.name\n                      }))\n                    ],\n                    onClick: (value: string) => {\n                      this.props.autofill('company', value);\n                    }\n                  }}\n                  component={BootstrapSelectField}\n                  validate={[inputStringRequired]}\n                 />\n              </div>\n            </div>\n          </div>\n          {/*<div id=\"permissions\" className=\"tab-pane fade in\">*/}\n          {/*  <div className=\"row\">*/}\n          {/*    <div className=\"col-md-12\">*/}\n          {/*    </div>*/}\n          {/*  </div>*/}\n          {/*</div>*/}\n        </div>\n      </React.Fragment>\n    )\n  }\n}\n\nconst IntegrationFormView = reduxForm({\n  form: \"integrationForm\",\n})(Form);\n\n// const selector = formValueSelector(\"sitiesForm\");\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  // const venue = selector(state, 'venue');\n  return {\n    users: state.users\n  };\n};\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n  };\n};\n\nexport default connect<{}, {}, any | IPropsType>(mapStateToProps, mapDispatchToProps)(IntegrationFormView);\n","import * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { IWindow } from '../../interfaces/window';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport {\n  createIntegrationAction,\n  deleteIntegrationAction,\n  getUsersAction,\n  IUsersState,\n  updateIntegrationAction,\n  UserReduxAction\n} from '../../actions/users.actions';\nimport { connect } from 'react-redux';\nimport * as Raven from 'raven-js';\nimport AppContainer from '../../container/AppContainer';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IUser } from '../../../../../../src/app/interfaces/user.interface';\nimport IntegrationFormView from './IntegrationFormView';\nimport { submit } from 'redux-form';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport * as swal from 'sweetalert';\nimport CopyText from '../Utils/CopyText';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { io } from 'socket.io-client';\nimport { UserTypes } from '../../../../../../src/app/models/user.model.types';\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  dispatch: Dispatch<UserReduxAction>;\n  users: IUsersState;\n\n  submitForm(form: string): UserReduxAction;\n  createIntegrationAction(user: any): UserReduxAction;\n  deleteIntegrationAction(id: string): UserReduxAction;\n  updateIntegrationAction(user: any): UserReduxAction;\n  getUsersAction(nextPage: number, type: UserTypes, search?: string): UserReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\ninterface IStateType {\n  error: Error | null;\n}\ndeclare let window: IWindow;\n\nclass IntegrationListView extends React.Component<IPropsType, IStateType> {\n  readonly state = {\n    error: null\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.showToken = this.showToken.bind(this);\n    this.createIntegration = this.createIntegration.bind(this);\n    this.updateIntegration = this.updateIntegration.bind(this);\n    this.deleteIntegration = this.deleteIntegration.bind(this);\n    this.changePage = this.changePage.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.users;\n    // set the title of the page\n    document.title = 'OSA Andes | Listado de integraciones';\n    this.props.getUsersAction(1, UserTypes.integration);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: (window.user as any).token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `integration-list-${window.user.team}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.users;\n        this.props.getUsersAction(pagination.page, UserTypes.integration);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {users, loading, pagination} = this.props.users;\n    return (\n      <AppContainer title=\"\" cMenu=\"200\" cSubMenu=\"200.1\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Integraciones <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button\n                  className=\"btn btn-sm btn-success\"\n                  onClick={this.createIntegration}\n                >\n                  Agregar\n                </button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\" style={{width: '25%'}}>Nombre</th>\n                    <th className=\"middle\" style={{width: '25%'}}>Empresa</th>\n                    <th className=\"middle\" style={{width: '40%'}}>Token</th>\n                    <th className=\"middle-center\" style={{width: '7%'}}>Estado</th>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    !loading && users.length === 0 && users ? <tr>\n                      <td colSpan={6}>No se han encontrado resultados.</td>\n                    </tr> : null\n                  }\n                  {\n                    users.map((user: IUser) => {\n                      return (\n                        <tr\n                          key={user._id}\n                          id={`user-${user._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{user.firstName}</td>\n                          <td className=\"middle\">{user.company?.name}</td>\n                          <td className=\"middle\">••••••••••••••••••••• <button\n                            onClick={()=> this.showToken(user)}\n                            className={\"btn btn-xs btn-default\"}\n                          >\n                            <i className=\"fa fa fa-eye\" /></button>\n                          </td>\n                          <td className=\"middle-center\">\n                            <i className=\"fa fa-check-circle text-green\" />\n                          </td>\n                          <td\n                            className=\"middle-center pointer\"\n                            onClick={()=> this.updateIntegration(user)}\n                          >\n                            <i className=\"fa fa-pencil text-blue\"/>\n                          </td>\n                          <td\n                            className=\"middle-center pointer\"\n                            onClick={() => this.deleteIntegration(user)}\n                          >\n                            <i className=\"fa fa-minus-circle text-red\"/>\n                          </td>\n                        </tr>\n                      )\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className=\"box-footer text-right\">\n                <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages}/>\n              </div>\n            }\n            {\n              loading &&\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\"/>\n              </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    )\n  }\n\n  private showToken(user: IUser): void {\n    this.props.loadDataAction(\n      `Token de ${user.firstName} `,\n      <div className=\"row\">\n        <div className=\"col-md-12\">\n          <p\n            style={{\n              wordBreak: \"break-all\"\n            }}\n          ><CopyText value={user.token}><strong>Token:</strong> {user.token}</CopyText></p>\n        </div>\n      </div>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cerrar</button>\n      </React.Fragment>\n    );\n  }\n\n  private createIntegration(): void {\n    this.props.loadDataAction(\n      'Agregar Integración',\n      <IntegrationFormView onSubmit={this.props.createIntegrationAction}/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-primary\"\n          onClick={() => this.props.submitForm(\"integrationForm\")}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private updateIntegration(user: IUser): void {\n    this.props.loadDataAction(\n      `Editando ${user.firstName} `,\n      <IntegrationFormView\n        onSubmit={this.props.updateIntegrationAction}\n        initialValues={{\n          _id: user._id,\n          firstName: user.firstName,\n          company: user.company?._id\n        }}\n      />,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button\n          type=\"button\"\n          className=\"btn btn-sm btn-primary\"\n          onClick={() => this.props.submitForm(\"integrationForm\")}\n        >\n          Grabar\n        </button>\n      </React.Fragment>\n    );\n  }\n\n  private deleteIntegration(user: IUser) {\n    // ask if you are sure that you are going to delete the integration?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la integración ${user.firstName || ''}`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteIntegrationAction(user._id);\n      }\n    });\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getUsersAction(page, UserTypes.integration);\n  }\n}\n\nconst mapStateToProps = (state: { users: IUsersState }) => {\n  return {\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    submitForm: (form: string) => dispatch(submit(form)),\n    createIntegrationAction: (user: any) => dispatch(createIntegrationAction(user)),\n    deleteIntegrationAction: (id: string) => dispatch(deleteIntegrationAction(id)),\n    updateIntegrationAction: (user: IUser) => dispatch(updateIntegrationAction(user)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    getUsersAction: (nextPage: number, type: UserTypes, search?: string) => dispatch(getUsersAction(nextPage, type, search)),\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(IntegrationListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\n\ninterface IPropsType {\n  car: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass CarDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { car } = this.props;\n    return (\n      <tr>\n        <td>\n          {\n            car.hasWarnings && car.warning.vin ?\n              <i\n                className='fa fa-warning pointer'\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle='tooltip'\n                data-placement='top'\n                title='El vin debe tener al menos 17 dígitos.'\n              /> : null} {car.vin}\n        </td>\n        <td>\n          {\n            car.hasWarnings && car.warning.patent ?\n              <i\n                className='fa fa-warning pointer'\n                style={{\n                  color: '#f2aa2e'\n                }}\n                data-toggle='tooltip'\n                data-placement='top'\n                title='La patente debe tener al menos 6 dígitos.'\n              /> : null} {car.patent}\n        </td>\n        <td>{car.brand}</td>\n        <td>{car.denomination}</td>\n        <td>{car.type}</td>\n      </tr>\n    );\n  }\n}\n\nexport default CarDetail;\n","import * as moment from 'moment';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { IInventoryComment } from '../../../../../../src/inventory/interfaces/inventoryComment.interface';\nimport { addCommentAction, IInventoryState, sendCommentAction } from '../../actions/inventory.actions';\nimport { IWindow } from '../../interfaces/window';\nimport Row from '../Utils/Row';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\n\ninterface IPropsType {\n  inventories: IInventoryState;\n  socket: Socket;\n\n  addCommentAction(inventoryComment: IInventoryComment): void;\n\n  sendCommentAction(carId: string, comment: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  comment: string;\n  resetRender: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass InventoryCarComments extends React.Component<IPropsType, IStateType> {\n\n  state = {\n    error: null,\n    comment: '',\n    resetRender: true\n  };\n\n  interval: any;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.handlerComment = this.handlerComment.bind(this);\n    this.sendComment = this.sendComment.bind(this);\n    this.keyPressComment = this.keyPressComment.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { inventoryCar } = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n      this.props.socket.on('connect', () => {\n        this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n      });\n      this.props.socket.on('NEW_COMMENT', (data: any): void => {\n        this.props.addCommentAction(data);\n        const $comments = document.getElementById('comments');\n        if ($comments) {\n          $comments.scrollTop = $comments.scrollHeight;\n        }\n      });\n    }\n  }\n\n  public componentDidMount(): void {\n    setTimeout(() => {\n      const $comments = document.getElementById('comments');\n      if ($comments) {\n        $comments.scrollTop = $comments.scrollHeight;\n      }\n    }, 300);\n    this.interval = setInterval(() => {\n      this.setState({\n        resetRender: !this.state.resetRender\n      });\n    }, 2000);\n  }\n\n  public componentWillUnmount(): void {\n    clearInterval(this.interval);\n    this.props.socket.off('NEW_COMMENT');\n    const { inventoryCar } = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('leave', { room: `inventory-comment-${id}` });\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { inventoryCar } = this.props.inventories;\n    return (\n      <Row>\n        <div className={'col-md-12'}>\n          <strong>Detalle del vehiculo</strong>\n        </div>\n        <div className={'col-md-3'}>\n          <strong>VIN</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).vin ? (inventoryCar as any).vin : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Marca</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).brand ? (inventoryCar as any).brand : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Denominación</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).denomination ? (inventoryCar as any).denomination : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Reportado en</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).venueFound ? (inventoryCar as any).venueFound : '-'}\n        </div>\n        <div className={'col-md-3'}>\n          <strong>Reportado por</strong>\n        </div>\n        <div className={'col-md-9'}>\n          {(inventoryCar as any).inventoriedBy ? (inventoryCar as any).inventoriedBy : '-'}\n        </div>\n        <div className={'col-md-12'}>\n          &nbsp;\n        </div>\n        <div className={'col-md-12'}>\n          <div className='direct-chat-info' style={{ border: '1px solid #efefef' }}>\n            <div className='direct-chat-messages' id={'comments'} style={{ height: '30vh' }}>\n              {\n                inventoryCar ? inventoryCar.comments.map((comment) => {\n                  return (\n                    <div\n                      className={`direct-chat-msg ${comment.user && comment.user._id === window.user._id ? 'right' : ''}`}\n                      key={comment._id}\n                    >\n                      <div className='direct-chat-info clearfix'>\n                        <span\n                          className='direct-chat-name pull-left'\n                        >\n                          {comment.user ? `${comment.user.firstName} ${comment.user.lastName}` : '-'}\n                        </span>\n                        <span className='direct-chat-timestamp pull-right'>{moment(comment.createdAt).fromNow()}</span>\n                      </div>\n                      <img className='direct-chat-img' src='/static/images/icon_circular.png' alt='message user image' />\n                      <div className='direct-chat-text'>\n                        {\n                          comment.comment.split('\\n').map((item, key) => {\n                            return (\n                              <span key={key}>{item}<br /></span>\n                            );\n                          })}\n                      </div>\n                    </div>\n                  );\n                }) : null\n              }\n            </div>\n          </div>\n          <div className='form-group'>\n            <label htmlFor='comment'>Comentario:</label>\n            <textarea\n              className='form-control'\n              rows={4}\n              id='comment'\n              onChange={this.handlerComment}\n              onKeyPress={this.keyPressComment}\n              value={this.state.comment}\n            />\n          </div>\n          <div className='form-group text-right'>\n            <button type='button' className='btn btn-sm btn-primary' onClick={this.sendComment}>Comentar</button>\n          </div>\n        </div>\n      </Row>\n    );\n  }\n\n  private handlerComment(e: React.ChangeEvent<HTMLTextAreaElement>): void {\n    this.setState({\n      comment: e.target.value\n    });\n  }\n\n  private keyPressComment(e: React.KeyboardEvent<HTMLTextAreaElement>): void {\n    if (e.key === 'Enter' && !e.shiftKey) {\n      this.sendComment();\n      setTimeout(() => {\n        this.setState({\n          comment: ''\n        });\n      }, 100);\n    }\n  }\n\n  private sendComment() {\n    const { inventoryCar } = this.props.inventories;\n    if (inventoryCar && this.state.comment.trim().length) {\n      this.props.sendCommentAction((inventoryCar as any)._id, this.state.comment);\n      this.setState({\n        comment: ''\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    addCommentAction: (inventoryComment: IInventoryComment) => dispatch(addCommentAction(inventoryComment)),\n    sendCommentAction: (carId: string, comment: string) => dispatch(sendCommentAction(carId, comment))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryCarComments);\n","import { AxiosError, AxiosResponse } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { AlertReduxAction, IAlertsState } from '../../actions/alerts.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport { getExtension, getIconFromExtension } from '../../utils/common';\nimport Checkbox from '../Utils/CheckBox';\nimport VenueDetail from './VenueDetail';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  alerts: IAlertsState;\n  dispatch: Dispatch<AlertReduxAction>;\n\n  loadDataAction(\n    title: string,\n    body: JSX.Element,\n    footer: JSX.Element\n  ): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  notification: boolean;\n  loadingSettings: boolean;\n  carsByVenue: any;\n  venues: any[];\n  loading: boolean;\n  name: string;\n  sending: boolean;\n  file: File | null;\n  backupFile: File | null;\n  backupUri: string;\n  manualPhoto: number;\n  reportPhoto: number;\n}\n\nclass InventoryCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly inputBackup: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    loadingSettings: false,\n    carsByVenue: [],\n    venues: [],\n    loading: true,\n    notification: true,\n    name: `Inventario del ${moment().format('DD-MM-YYYY')}`,\n    sending: false,\n    file: null,\n    backupFile: null,\n    backupUri: '',\n    manualPhoto: 1,\n    reportPhoto: 1\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Creando Inventario';\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.clickUploadBackup = this.clickUploadBackup.bind(this);\n    this.getVenues = this.getVenues.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.deleteVenue = this.deleteVenue.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.handleChangeInputBackup = this.handleChangeInputBackup.bind(this);\n    this.handleChangeManualPhoto = this.handleChangeManualPhoto.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.clearBackup = this.clearBackup.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.handleChangeName = this.handleChangeName.bind(this);\n    this.handleChangeNotification = this.handleChangeNotification.bind(this);\n    this.inputFile = React.createRef();\n    this.inputBackup = React.createRef();\n  }\n\n  public componentWillMount(): void {\n    this.getVenues();\n  }\n\n  public componentWillUnmount() {\n    // cancel request if component is inmounted\n    // if (this.props.alerts.source) {\n    //   this.props.alerts.source.cancel('Operation canceled by the user.');\n    // }\n  }\n\n  public componentDidUpdate(\n    prevProps: Readonly<IPropsType>,\n    prevState: Readonly<IStateType>,\n    snapshot?: any\n  ): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $reportPhoto: any = $('#report-photo');\n    $reportPhoto\n      .TouchSpin({\n        initval: 1,\n        min: 0,\n        max: 3\n      })\n      .on('change', () => {\n        this.setState({\n          reportPhoto: parseInt($reportPhoto.val(), 10)\n        });\n      });\n    const $manualPhoto: any = $('#manual-photo');\n    $manualPhoto\n      .TouchSpin({\n        initval: 1,\n        min: 0,\n        max: 3\n      })\n      .on('change', () => {\n        this.setState({\n          manualPhoto: parseInt($manualPhoto.val(), 10)\n        });\n      });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings,\n      carsByVenue,\n      name,\n      sending,\n      notification,\n      backupFile,\n      backupUri,\n      loading\n    } = this.state;\n    let carsInSettings = 0;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.1\" cAction=\"Creación\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Creando Inventario</h3>\n            </div>\n            <div className=\"box-body margin\">\n              <div className=\"row\">\n                <div className=\"col col-md-6\">\n                  <div className=\"form-group\">\n                    <label htmlFor=\"name\">Nombre</label>\n                    <input\n                      type=\"text\"\n                      className=\"form-control\"\n                      id=\"name\"\n                      value={name}\n                      onChange={this.handleChangeName}\n                    />\n                  </div>\n                </div>\n              </div>\n              {carsByVenue.length ? (\n                <div className=\"row\">\n                  <div className=\"col-md-12\">\n                    <div className=\"form-group\">\n                      <label>Configuración cargada</label>\n                      <div\n                        className=\"box-group\"\n                        id=\"accordion\"\n                        style={{ margin: '2px 0 10px 0' }}>\n                        {carsByVenue.map((venue: any, index) => {\n                          carsInSettings += venue.cars.length;\n                          return (\n                            <VenueDetail\n                              index={index}\n                              venue={venue}\n                              key={venue.name}\n                              deleteVenue={this.deleteVenue}\n                            />\n                          );\n                        })}\n                      </div>\n                    </div>\n                  </div>\n                  <div className=\"col-md-6\">\n                    <p>\n                      <strong>Total de sucursales:</strong> {carsByVenue.length}\n                    </p>\n                    <p>\n                      <strong>Total de unidades:</strong> {carsInSettings}\n                    </p>\n                  </div>\n                  <div className=\"col-md-6 text-right\">\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                    <button\n                      className=\"btn btn-sm btn-default\"\n                      onClick={this.clickUploadFile}\n                      style={{ marginLeft: '5px' }}>\n                      <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                    </button>\n                  </div>\n                  <div className=\"col-md-12\">\n                    <div className=\"form-group\" style={{ marginBottom: '0px' }}>\n                      <label>Archivo de respaldo</label>\n                    </div>\n                    <div className=\"preview-files\">\n                      {backupFile && backupUri ? (\n                        <div className=\"file\">\n                          <i\n                            className=\"fa fa-minus-circle text-red pointer\"\n                            onClick={this.clearBackup}\n                          />\n                          <a\n                            href={backupUri}\n                            className=\"zoom-in\"\n                            data-toggle=\"lightbox\"\n                            data-title={`Vista previa de la imagen`}\n                            data-footer={(backupFile as unknown as File).name}>\n                            <img\n                              src={backupUri}\n                              data-toggle=\"tooltip\"\n                              data-placement=\"bottom\"\n                              title={(backupFile as unknown as File).name}\n                            />\n                          </a>\n                        </div>\n                      ) : backupFile ? (\n                        <div className=\"file\">\n                          <i\n                            className=\"fa fa-minus-circle text-red pointer\"\n                            onClick={this.clearBackup}\n                          />\n                          <div\n                            className={`icon type-${getIconFromExtension(\n                              getExtension((backupFile as unknown as File).name)\n                            )}`}\n                          />\n                          <div\n                            className=\"name-file\"\n                            data-toggle=\"tooltip\"\n                            data-placement=\"bottom\"\n                            title={(backupFile as unknown as File).name}>\n                            {(backupFile as unknown as File).name}\n                          </div>\n                        </div>\n                      ) : (\n                        <div\n                          className=\"add-file\"\n                          onClick={this.clickUploadBackup}>\n                          <i className=\"fa fa-plus\" />\n                          AGREGAR ARCHIVO\n                        </div>\n                      )}\n                    </div>\n                    <input\n                      type=\"file\"\n                      onChange={this.handleChangeInputBackup}\n                      style={{ display: 'None' }}\n                      ref={this.inputBackup}\n                    />\n                  </div>\n                </div>\n              ) : (\n                <div className=\"row\">\n                  <div className=\"col col-md-12\">\n                    <div className=\"form-group\">\n                      <label>Importar configuración</label>\n                      <div\n                        className=\"upload-file text-center pointer\"\n                        onClick={this.clickUploadFile}\n                        onDrop={this.handleDrop}\n                        onDragOver={this.dragOverHandler}\n                        onDragEnd={this.dragEndHandler}\n                        onDragLeave={this.dragLeaveHandler}\n                        style={{\n                          backgroundColor: '#EEEEEE',\n                          border: this.state.canDrop\n                            ? '1px solid #979797'\n                            : '1px dashed #979797',\n                          padding: '40px 20px',\n                          color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                          borderRadius: '5px'\n                        }}>\n                        <i className=\"fa fa-2x fa-cloud-upload\" />\n                        <br />\n                        Prueba soltando el excel aquí, o haz click para\n                        seleccionar el excel a cargar.\n                      </div>\n                    </div>\n                  </div>\n                  <div className=\"col-md-12 text-right\">\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                  </div>\n                </div>\n              )}\n\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{ display: 'None' }}\n                ref={this.inputFile}\n                accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n              <div className=\"row\">\n                <div className=\"col-md-12\">\n                  <div\n                    className=\"form-group\"\n                    style={{ marginBottom: '0px', marginTop: '10px' }}>\n                    <label>Configuraciones</label>\n                  </div>\n                </div>\n                <div className=\"col-md-12 no-padding\">\n                  <div className=\"col-sm-12 col-md-8 col-lg-6\">\n                    <div className=\"form-horizontal\">\n                      <div\n                        className=\"form-group\"\n                        style={{ marginRight: '0', marginLeft: '0' }}>\n                        <div className=\"col-sm-6 col-md-8 col-lg-8 no-padding\">\n                          <span\n                            className=\"control-label\"\n                            style={{\n                              paddingLeft: '0',\n                              textAlign: 'left',\n                              fontWeight: 600\n                            }}>\n                            Nº imágenes al inventariar\n                          </span>\n                          <br />\n                          <span className={'text-sm text-muted'}>\n                            Cantidad de fotografías solicitadas al ingresar\n                            unidad digitando el VIN.\n                          </span>\n                        </div>\n                        <input\n                          id=\"manual-photo\"\n                          type=\"text\"\n                          className=\"col-sm-6 col-md-4 col-lg-4 form-control\"\n                        />\n                      </div>\n                    </div>\n                    {/*<div className=\"checkbox\">*/}\n                    {/*  <label style={{paddingLeft: '0'}} onClick={this.handleChangeManualPhoto}>*/}\n                    {/*    <Checkbox*/}\n                    {/*      active={manualPhoto === 1}*/}\n                    {/*      action={this.handleChangeManualPhoto}*/}\n                    {/*      classes=\"icheck-in-checkbox\"*/}\n                    {/*      style={{marginTop: '-4px', marginRight: '5px'}}*/}\n                    {/*    />*/}\n                    {/*    Solicitar foto en modo manual*/}\n                    {/*  </label>*/}\n                    {/*</div>*/}\n                  </div>\n                </div>\n                <div className=\"col-sm-12 col-md-8 col-lg-6\">\n                  <div className=\"form-horizontal\">\n                    <div\n                      className=\"form-group\"\n                      style={{ marginRight: '0', marginLeft: '0' }}>\n                      <div className=\"col-sm-6 col-md-8 col-lg-8 no-padding\">\n                        <span\n                          className=\"control-label\"\n                          style={{\n                            paddingLeft: '0',\n                            textAlign: 'left',\n                            fontWeight: 600\n                          }}>\n                          Nº imágenes al reportar\n                        </span>\n                        <br />\n                        <span className={'text-sm text-muted'}>\n                          Cantidad de fotografías solicitadas al reportar una\n                          unidad.\n                        </span>\n                      </div>\n                      <input\n                        id=\"report-photo\"\n                        type=\"text\"\n                        className=\"col-sm-6 col-md-4 col-lg-4 form-control\"\n                      />\n                    </div>\n                  </div>\n                  {/*<input*/}\n                  {/*  type=\"text\"*/}\n                  {/*  id=\"report-photo\"*/}\n                  {/*  className=\"input-sm form-control\"*/}\n                  {/*  style={{*/}\n                  {/*    width: '35px'*/}\n                  {/*  }}*/}\n                  {/*/>*/}\n                  {/*<span>Cantidad de imágenes al reportar</span>*/}\n                </div>\n                <div className=\"col-md-8 col-sm-12\">\n                  <div className=\"checkbox\">\n                    <label\n                      style={{ paddingLeft: '0', fontWeight: 600 }}\n                      onClick={this.handleChangeNotification}>\n                      <Checkbox\n                        active={notification}\n                        action={this.handleChangeNotification}\n                        classes=\"icheck-in-checkbox\"\n                        style={{ marginTop: '-4px', marginRight: '5px' }}\n                      />\n                      Enviar notificaciones push\n                    </label>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div className=\"box-footer text-right\">\n              <button\n                className=\"btn btn-sm btn-default\"\n                onClick={() => this.props.history.push('/inventory/')}>\n                Cancelar\n              </button>\n              <button\n                className=\"btn btn-sm btn-primary\"\n                style={{ marginLeft: '5px' }}\n                onClick={this.sendCreate}\n                disabled={sending}>\n                {sending || loading ? (\n                  <React.Fragment>\n                    <i className=\"fa fa-fw fa-spin fa-spinner\" /> Creando...\n                  </React.Fragment>\n                ) : (\n                  'Crear'\n                )}\n              </button>\n            </div>\n            {sending || loading || loadingSettings ? (\n              <div className=\"overlay\">\n                <i className=\"fa fa-spinner fa-spin text-purple\" />\n              </div>\n            ) : null}\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private deleteVenue(venueName: string): void {\n    const { carsByVenue } = this.state;\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la sucursal \"${venueName}\"`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.setState({\n          carsByVenue: carsByVenue.filter(\n            (venue: any) => venue.name !== venueName\n          )\n        });\n      }\n    });\n  }\n\n  private handleChangeNotification() {\n    this.setState({\n      notification: !this.state.notification\n    });\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private clickUploadBackup(): void {\n    if (this.inputBackup.current) {\n      this.inputBackup.current.click();\n    }\n  }\n\n  private handleChangeManualPhoto(): void {\n    const { manualPhoto } = this.state;\n    this.setState({\n      manualPhoto: manualPhoto === 1 ? 0 : 1\n    });\n  }\n\n  private handleChangeName(e: React.ChangeEvent<HTMLInputElement>): void {\n    const { value } = e.target;\n    this.setState({\n      name: value\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* headers worksheet */\n    const data = [\n      {\n        sucursal: '',\n        NInterno: '',\n        vin: '',\n        marca: '',\n        patente: '',\n        denominacion: '',\n        color: '',\n        propiedad: '',\n        tipo: ''\n      }\n    ];\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_inventory_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    const { venues } = this.state;\n    this.setState({\n      loadingSettings: true\n    });\n    if (\n      [\n        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n      ].includes(file.type)\n    ) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        if (e.target) {\n          let data = e.target.result;\n          if (!rABS) {\n            data = new Uint8Array(data);\n          }\n          const workbook: XLSX.WorkBook = XLSX.read(data, {\n            type: rABS ? 'binary' : 'array'\n          });\n          const excelData = workbook.Sheets.hasOwnProperty('Autos')\n            ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos)\n            : [];\n          const carsByVenue: any = {};\n          if (excelData.length >= 1) {\n            excelData.forEach((item: any) => {\n              if (\n                item.hasOwnProperty('vin') &&\n                item.vin &&\n                item.hasOwnProperty('sucursal') &&\n                item.sucursal\n              ) {\n                const vinWarning = item.vin.length < 17;\n                const patentWarning = item.patente && item.patente.length < 6;\n                const car = {\n                  vin: item.vin.trim(),\n                  internalNumber: item.NInterno ? item.NInterno.trim() : '',\n                  color: item.color ? item.color.trim() : '',\n                  denomination: item.denominacion\n                    ? item.denominacion.trim()\n                    : '',\n                  brand: item.marca ? item.marca.trim() : '',\n                  patent: item.patente ? item.patente.trim() : '',\n                  property: item.propiedad\n                    ? item.propiedad.trim().toUpperCase()\n                    : '',\n                  type: item.tipo ? item.tipo.trim() : '',\n                  hasWarnings: vinWarning || patentWarning,\n                  warning: {\n                    vin: vinWarning,\n                    patent: patentWarning\n                  }\n                };\n                if (!carsByVenue.hasOwnProperty(item.sucursal)) {\n                  // venues.push(item.sucursal);\n                  carsByVenue[item.sucursal] = {\n                    cars: []\n                  };\n                }\n                carsByVenue[item.sucursal].cars.push(car);\n                // cars.push(car);\n              } else {\n                /* tslint:disable:no-console */\n                // swal!('Error en archivo de configuracion', `Revise la linea ${item.__rowNum__}`, 'error');\n                console.log('Error en linea:');\n                console.log(item.__rowNum__);\n                return;\n              }\n            });\n            const carsByVenueArray: any[] = [];\n            const venuesNotFound: string[] = [];\n            for (const cv in carsByVenue) {\n              if (carsByVenue.hasOwnProperty(cv)) {\n                const existVenue = venues.some((venue: any) => {\n                  return (\n                    venue.name.trim().toLowerCase() === cv.trim().toLowerCase()\n                  );\n                });\n                if (!existVenue && !venuesNotFound.includes(cv.toLocaleUpperCase())) {\n                  venuesNotFound.push(cv.toLocaleUpperCase());\n                }\n                carsByVenueArray.push({\n                  name: cv.trim(),\n                  warningNoExist: !existVenue,\n                  cars: carsByVenue[cv].cars.sort((x: any, y: any) => {\n                    return x.hasWarnings === y.hasWarnings\n                      ? 0\n                      : x.hasWarnings\n                      ? -1\n                      : 1;\n                  })\n                });\n              }\n            }\n            if (venuesNotFound.length > 0) {\n              swal!('Sucursales no configuradas', `No se encontraron las siguientes sucursales:\\n\\n - ${venuesNotFound.join(\"\\n- \")}\\n\\n Estas sucursales no existen o no tienes acceso a ellas.\\n\\nVuelve a subir el archivo con las sucursales correctas, o solicita la configuración de una nueva sucursal o acceso a una existente escribiéndonos a  soporte@osacontrol.com`, 'error');\n              this.setState({\n                loadingSettings: false\n              });\n            } else {\n              this.setState({\n                file,\n                carsByVenue: carsByVenueArray,\n                loadingSettings: false\n              });\n            }\n          } else {\n            swal!(\n              'Importador de configuración',\n              `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n              'error'\n            );\n            this.setState({\n              loadingSettings: false\n            });\n          }\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    } else {\n      swal!(\n        'Importador de configuración',\n        'Este archivo no cumple con los requisitos mínimos o no tiene autos.',\n        'error'\n      );\n      this.setState({\n        loadingSettings: false\n      });\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const { files } = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private validateSize(size: number): boolean {\n    const maxSize = Math.pow(1024, 2) * 10; // 10MB\n    return size <= maxSize;\n  }\n\n  private clearBackup(): void {\n    this.setState({\n      backupFile: null,\n      backupUri: ''\n    });\n  }\n\n  private handleChangeInputBackup(\n    e: React.ChangeEvent<HTMLInputElement>\n  ): void {\n    const { files } = e.target;\n    if (files && files.length) {\n      const file = files[0];\n      if (!this.validateSize(file.size)) {\n        swal!(\n          'Envió inventario',\n          'El archivo supera los 10Mb permitidos.',\n          'error'\n        );\n      } else {\n        if (new RegExp('\\\\bimage\\\\b').test(file.type)) {\n          const reader = new FileReader();\n          reader.onload = (e) => {\n            if (e.target) {\n              this.setState({\n                backupFile: file,\n                backupUri: (e.target as any).result\n              });\n            }\n          };\n          reader.readAsDataURL(file);\n        } else {\n          this.setState({\n            backupFile: file,\n            backupUri: ''\n          });\n        }\n      }\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private getVenues() {\n    this.setState({ loading: true });\n    const api: ApiService = new ApiService();\n    api\n      .getVenues({ page: 1, pageSize: 200, noPopulate: true, filted: true })\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          venues: response.data.results,\n          loading: false\n        });\n      })\n      .catch((err: AxiosError): void => {\n        api.errorHandler(err);\n      });\n  }\n\n  private sendCreate(): void {\n    const {\n      carsByVenue,\n      name,\n      notification,\n      file,\n      backupFile,\n      manualPhoto,\n      reportPhoto\n    } = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    if (!name.trim().length) {\n      swal!(\n        'Envió inventario',\n        'El nombre del inventario es obligatorio.',\n        'error'\n      );\n      this.setState({\n        sending: false\n      });\n    } else if (!carsByVenue.length) {\n      swal!(\n        'Envió inventario',\n        'No se ha importado la configuración o no contiene sucursales.',\n        'error'\n      );\n      this.setState({\n        sending: false\n      });\n    } else if (file) {\n      const api = new ApiService({\n        'Content-Type': 'multipart/form-data'\n      });\n      api.getSource();\n      api\n        .createInventory({\n          carsByVenue,\n          name,\n          notification,\n          file,\n          backupFile,\n          manualPhoto,\n          reportPhoto\n        })\n        .then((response: any) => {\n          const { message } = response.data;\n          swal!('Envió inventario', message, 'success');\n          setTimeout(() => {\n            this.setState({\n              sending: false\n            });\n            swal.close();\n            history.push('/inventory/');\n          }, 2000);\n        })\n        .catch((e) => {\n          console.log('e', e);\n          swal!(\n            'Envió inventario',\n            'Se produjo un error al crear el inventario.',\n            'error'\n          );\n          this.setState({\n            sending: false\n          });\n        });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { alerts: IAlertsState }) => {\n  return {\n    alerts: state.alerts\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) =>\n      dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(\n  mapStateToProps,\n  mapDispatchToProps\n)(InventoryCreateView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport {\n  getInventoryDashboard,\n  getInventoryDashboardFiltered,\n  IInventoryDashboardState,\n  InventoryDashboardReduxAction\n} from '../../actions/inventoryDashboard.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { IFilterCar } from '../../reducers/inventory.reducer';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Row from '../Utils/Row';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  inventoryDashboard: IInventoryDashboardState;\n  dispatch: Dispatch<InventoryDashboardReduxAction>;\n\n  getInventoryDashboard(filter: IFilterCar): void;\n\n  getInventoryDashboardFiltered(filter: IFilterCar): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass InventoryDashboardView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  monthlyReport: echarts.ECharts;\n\n  state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Dashboard de inventarios';\n    this.resizeCharts = this.resizeCharts.bind(this);\n\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n  }\n\n  public componentWillMount(): void {\n\n    window.scrollTo(0, 0);\n\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n\n    // get data\n    const { filter } = this.props.inventoryDashboard;\n    this.props.getInventoryDashboard(filter);\n\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $monthlyReport = document.getElementById('inventory-monthly-report') as HTMLDivElement;\n    this.monthlyReport = echarts.init($monthlyReport);\n\n  }\n\n  public componentDidUpdate(prevProps: IPropsType, prevState: IStateType): void {\n    const { loading } = this.props.inventoryDashboard;\n    if (!loading) {\n      this.updateDashboardChart();\n    }\n  }\n\n  public componentWillUnmount(): void {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { filter, loading, venues } = this.props.inventoryDashboard;\n    return (\n      <AppContainer title='' cMenu='2' cSubMenu='2.3'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Dashboard de inventarios</h3>\n            </div>\n            <div className='box-body no-padding'>\n              <Row>\n                <div className='col-md-offset-8 col-md-4' style={{ padding: '20px 40px' }}>\n                  <BootstrapSelect\n                    sm={true}\n                    noneSelectedText='Todas'\n                    displayItems={2}\n                    selectedText='sucursales seleccionadas.'\n                    selected={filter.venues}\n                    allOption={true}\n                    selectAll={this.filterAllVenues}\n                    options={venues.map((venue: any) => ({\n                      value: venue._id,\n                      text: venue.name\n                    }))}\n                    onClick={this.filterVenues}\n                  />\n                </div>\n                <div className='col-md-12' style={{padding: '0 0 15px 0'}}>\n                   <div id='inventory-monthly-report' style={{ height: '65vh', maxWidth: '100%' }} />\n                </div>\n              </Row>\n            </div>\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private resizeCharts(): void {\n    if (this.monthlyReport) {\n      this.monthlyReport.resize();\n      setTimeout(() => {\n        this.monthlyReport.resize();\n      }, 400);\n    }\n  }\n\n  private filterVenues(value: any) {\n\n    const { filter } = this.props.inventoryDashboard;\n\n    const venues = filter.venues.includes(value) ? filter.venues.filter((venue) => venue !== value) : [value, ...filter.venues];\n    this.props.getInventoryDashboardFiltered({\n      ...filter,\n      venues\n    });\n  }\n\n  private filterAllVenues(value: boolean) {\n    const { filter, venues } = this.props.inventoryDashboard;\n    this.props.getInventoryDashboardFiltered({\n      ...filter,\n      venues: value ? venues.map((v) => v._id) : []\n    });\n  }\n\n  private updateDashboardChart() {\n    const { monthlyReport, inventorySettings } = this.props.inventoryDashboard;\n\n    const labelOption = {\n      normal: {\n        show: true,\n        position: 'inside',\n        align: 'center',\n        verticalAlign: 'middle',\n        rotate: 90,\n        formatter: '{c}',\n        fontSize: 12,\n        rich: {\n          name: {\n            textBorderColor: '#fff'\n          }\n        }\n      }\n    };\n\n    const xSerie = Object.keys(monthlyReport);\n    const found = Object.values(monthlyReport).map((v) => v.found);\n    const pending = Object.values(monthlyReport).map((v) => v.pending);\n    const leftover = Object.values(monthlyReport).map((v) => v.leftover);\n    const missing = Object.values(monthlyReport).map((v) => v.missing);\n    const reported = Object.values(monthlyReport).map((v) => v.reported);\n\n    const option: any = {\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'cross',\n          label: {\n            backgroundColor: '#6a7985'\n          }\n        }\n      },\n      legend: {\n        // x: 'center',\n        // bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      calculable: true,\n      xAxis: [\n        {\n          type: 'category',\n          boundaryGap: false,\n          data: xSerie\n        }\n      ],\n       yAxis: {\n        // minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        left: '3%',\n        right: '4%',\n        bottom: 80,\n        containLabel: true\n      },\n      dataZoom: {\n        show: true,\n        realtime: true,\n        start: 50,\n        end: 100\n      },\n      series: [\n        {\n          name: inventorySettings.found,\n          type: 'line',\n          stack: 'Total',\n          // barMaxWidth: 100,\n          // label: labelOption,\n          areaStyle: {},\n          // label: {\n          //   show: true,\n          //   position: 'bottom',\n          //   color: '#444'\n          // },\n          emphasis: {\n            focus: 'series'\n          },\n          data: found\n        },\n        {\n          name: inventorySettings.leftover,\n          type: 'line',\n          stack: 'Total',\n          // barMaxWidth: 100,\n          // label: labelOption,\n          areaStyle: {},\n          emphasis: {\n            focus: 'series'\n          },\n\n          data: leftover\n        },\n        {\n          name: inventorySettings.missing,\n          type: 'line',\n          stack: 'Total',\n          // barMaxWidth: 100,\n          // label: labelOption,\n          areaStyle: {},\n          emphasis: {\n            focus: 'series'\n          },\n\n          data: missing\n        },\n        {\n          name: inventorySettings.pending,\n          type: 'line',\n          stack: 'Total',\n          // barMaxWidth: 100,\n          // label: labelOption,\n          areaStyle: {},\n          emphasis: {\n            focus: 'series'\n          },\n\n          data: pending\n        },\n        {\n          name: inventorySettings.reported,\n          type: 'line',\n          stack: 'Total',\n          // barMaxWidth: 100,\n          // label: labelOption,\n          areaStyle: {},\n          emphasis: {\n            focus: 'series'\n          },\n\n          data: reported\n        }\n      ]\n    };\n\n    this.monthlyReport.setOption(option);\n\n  }\n}\n\nconst mapStateToProps = (state: { inventoryDashboard: IInventoryDashboardState }) => {\n  return {\n    inventoryDashboard: state.inventoryDashboard\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getInventoryDashboard: () => dispatch(getInventoryDashboard()),\n    getInventoryDashboardFiltered: (filter: IFilterCar) => dispatch(getInventoryDashboardFiltered(filter))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDashboardView);\n","///<reference path=\"../../../src/types/react-bootstrap-table-next.d.ts\"/>\n///<reference path=\"../../../src/types/react-bootstrap-table2-filter.d.ts\"/>\n///<reference path=\"../../../src/types/react-bootstrap-table2-paginator.d.ts\"/>\nimport { CancelTokenSource, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport BootstrapTable from 'react-bootstrap-table-next';\nimport filterFactory from 'react-bootstrap-table2-filter';\nimport paginationFactory from 'react-bootstrap-table2-paginator';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { RouterState } from 'react-router-redux';\nimport { Dispatch } from 'redux';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { IInventoryCar } from '../../../../../../src/inventory/interfaces/inventory.interface';\nimport { IInventoryLabel } from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport { IInventorySetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport {\n  actionSetLabel,\n  addCommentAction,\n  getInventoryDetailAction,\n  IDetailByBrand,\n  IDetailByVenue,\n  IInventoryState,\n  IInventorySummaryResult,\n  inventoryDetailChangeFilter,\n  inventoryDetailChangeFilterText,\n  inventoryDetailChangeSelected,\n  InventoryReduxAction,\n  sendCommentAction,\n  updateInventoryCarAction\n} from '../../actions/inventory.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { IFilterCar } from '../../reducers/inventory.reducer';\nimport ApiService from '../../utils/axios';\nimport { goToSection, hasPermission, isDercoDercocenter, maxText } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport Checkbox from '../Utils/CheckBox';\nimport CopyText from '../Utils/CopyText';\nimport ImageLazyLoad from '../Utils/ImageLazyLoad';\nimport Row from '../Utils/Row';\nimport InventoryCarComments from './InventoryCarComments';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport InventoryFileManager from './InventoryFileManager';\nimport ShowIf from '../Utils/ShowIf';\n\ndeclare let window: IWindow;\n\nexport type CarStatusType = Extract<keyof IInventorySetting, string>;\n\ninterface IPropsType extends RouteComponentProps<{ id: string, tab?: string }> {\n  inventories: IInventoryState;\n  router: RouterState;\n  dispatch: Dispatch<InventoryReduxAction>;\n\n  inventoryDetailChangeSelected(item: string): InventoryReduxAction;\n\n  updateInventoryCarAction(inventoryCar: IInventoryCar): InventoryReduxAction;\n\n  inventoryDetailChangeFilter(filter: IFilterCar): InventoryReduxAction;\n\n  inventoryDetailChangeFilterText(filter: IFilterCar): InventoryReduxAction;\n\n  getInventoryDetailAction(id: string, update: boolean): InventoryReduxAction;\n\n  loadDataAction(title: string, body: JSX.Element, footer?: JSX.Element): ModalReduxAction;\n\n  actionSetLabel(inventory: string, car: string, carID: string, label: IInventoryLabel): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  setCharts: boolean;\n  tab: string;\n  source: CancelTokenSource | null;\n  downloadImages: {\n    downloading: boolean;\n    progress: number;\n    sizeFile: number;\n    loaded: number;\n  };\n}\n\nclass InventoryDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    downloadImages: {\n      downloading: false,\n      progress: 0,\n      sizeFile: 0,\n      loaded: 0\n    },\n    setCharts: false,\n    tab: 'summary',\n    source: null\n  };\n\n  private venuesDetailChart: echarts.ECharts;\n  private brandDetailChart: echarts.ECharts;\n\n  private labelOption: any = {\n    normal: {\n      show: true,\n      position: 'inside',\n      align: 'center',\n      verticalAlign: 'middle',\n      rotate: 90,\n      formatter: '{c}',\n      fontSize: 12,\n      rich: {\n        name: {\n          textBorderColor: '#fff'\n        }\n      }\n    }\n  };\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  private iconStatus: any = {\n    pending: 'fa-clock-o',\n    found: 'fa-check',\n    leftover: 'fa-arrow-up',\n    missing: 'fa-arrow-down',\n    reported: 'fa-exclamation',\n    deleted: 'fa-close'\n  };\n\n  private paginationOption: any = {\n    // paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '10', value: 10\n    }, {\n      text: '50', value: 50\n    }, {\n      text: '200', value: 200\n    }],\n    onPageChange: () => {\n      setTimeout(() => {\n        $('[data-toggle=\"tooltip\"]').tooltip();\n      }, 200);\n    }\n  };\n\n  private defaultSorted = [{\n    dataField: 'status',\n    order: 'asc'\n  }];\n\n  private readonly columns: any[] = [];\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle Inventario';\n    this.resizeCharts = this.resizeCharts.bind(this);\n    this.xlsExport = this.xlsExport.bind(this);\n    this.carComments = this.carComments.bind(this);\n    this.selectedFormatter = this.selectedFormatter.bind(this);\n    this.filterVenues = this.filterVenues.bind(this);\n    this.filterAllVenues = this.filterAllVenues.bind(this);\n    this.filterStatus = this.filterStatus.bind(this);\n    this.filterType = this.filterType.bind(this);\n    this.filterProperty = this.filterProperty.bind(this);\n    this.selectedHeaderFormatter = this.selectedHeaderFormatter.bind(this);\n    this.statusFormatter = this.statusFormatter.bind(this);\n    this.brandFormatter = this.brandFormatter.bind(this);\n    this.commentFormatter = this.commentFormatter.bind(this);\n    this.labelFormatter = this.labelFormatter.bind(this);\n    this.optionsFormatter = this.optionsFormatter.bind(this);\n    this.calculateDetails = this.calculateDetails.bind(this);\n    this.imagesFormatter = this.imagesFormatter.bind(this);\n    this.filesFormatter = this.filesFormatter.bind(this);\n    this.openFileManager = this.openFileManager.bind(this);\n    this.handleChangeSearchText = this.handleChangeSearchText.bind(this);\n    this.clearFilter = this.clearFilter.bind(this);\n    this.sendToDetailFilteredByState = this.sendToDetailFilteredByState.bind(this);\n    this.sendToDetailFilteredByVenue = this.sendToDetailFilteredByVenue.bind(this);\n    this.downloadImages = this.downloadImages.bind(this);\n    this.changeTab = this.changeTab.bind(this);\n    const { tab } = this.props.match.params;\n    if (tab && tab === 'detail') {\n      this.state.tab = 'detail';\n    }\n    this.columns = [{\n      dataField: 'selected',\n      text: '',\n      // headerFormatter: this.selectedHeaderFormatter,\n      formatter: this.selectedFormatter,\n      sort: true,\n      headerClasses: 'pointer middle-center hidden-xs hidden-sm',\n      classes: 'middle-center hidden-xs hidden-sm',\n      headerStyle: {\n        maxWidth: '60px',\n        minWidth: '60px',\n        width: '60px'\n      },\n      style: {\n        maxWidth: '60px',\n        minWidth: '60px',\n        width: '60px'\n      }\n    }, {\n      dataField: 'brand',\n      text: 'Vehículo',\n      formatter: this.brandFormatter,\n      filterValue: (cell: any, row: any) => `${cell}${row.denomination}${row.vin}${row.patent}`,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      sort: true,\n      headerStyle: {\n        maxWidth: '250px',\n        minWidth: '250px',\n        width: '250px'\n      },\n      style: {\n        maxWidth: '250px',\n        minWidth: '250px',\n        width: '250px'\n      }\n    }, {\n      dataField: 'venue',\n      text: 'Sucursal',\n      classes: 'middle hidden-xs hidden-sm text-muted',\n      headerClasses: 'middle hidden-xs hidden-sm pointer',\n      style: {\n        width: '18%'\n      },\n      sort: true\n    }, {\n      dataField: 'venueFound',\n      text: 'Encontrado en',\n      classes: 'middle hidden-xs hidden-sm text-muted',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md pointer',\n      style: {\n        width: '18%'\n      },\n      sort: true\n    }, /* {\n      dataField: 'countComments',\n      text: 'Comentarios',\n      classes: 'middle hidden-xs text-ellipsis',\n      formatter: this.commentFormatter,\n      headerClasses: 'middle hidden-xs',\n      style: {\n        width: '15%'\n      },\n      headerStyle: {\n        verticalAlign: 'top'\n      }\n    } */ {\n      dataField: 'labelName',\n      text: 'Etiqueta',\n      sort: true,\n      classes: 'middle hidden-xs',\n      filterValue: (cell: any) => `${cell ? cell.name : ''}`,\n      formatter: this.labelFormatter,\n      headerClasses: 'middle hidden-xs',\n      style: {\n        width: '18%',\n        maxWidth: '18%'\n      },\n      headerStyle: {\n        verticalAlign: 'top'\n      }\n    }, {\n      dataField: 'images',\n      text: 'Imágenes',\n      classes: 'middle hidden-xs hidden-sm hidden-md',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md',\n      formatter: this.imagesFormatter,\n      headerStyle: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      },\n      style: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      }\n    }, {\n      dataField: 'files',\n      text: 'Archivos',\n      classes: 'middle hidden-xs hidden-sm hidden-md',\n      headerClasses: 'middle hidden-xs hidden-sm hidden-md',\n      formatter: this.filesFormatter,\n      headerStyle: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      },\n      style: {\n        maxWidth: '80px',\n        minWidth: '80px',\n        width: '80px'\n      }\n    }, {\n      dataField: 'status',\n      text: 'Estado',\n      sort: true,\n      formatter: this.statusFormatter,\n      // formatter: (cell: string) => (this.statusText[cell]),\n      headerClasses: 'middle pointer',\n      headerStyle: {\n        maxWidth: '100px',\n        minWidth: '100px',\n        width: '100px'\n      },\n      style: {\n        maxWidth: '100px',\n        minWidth: '100px',\n        width: '100px'\n      },\n      classes: 'middle-center'\n      // classes: (cell: any) => {\n      //   return `middle-center ${this.classStatus.hasOwnProperty(cell) ? this.classStatus[cell] : ''}`;\n      // }\n    }, {\n      dataField: 'option',\n      text: '',\n      formatter: this.optionsFormatter,\n      headerClasses: 'middle hidden-xs hidden-sm',\n      classes: () => {\n        return `middle-center hidden-xs hidden-sm`;\n      },\n      headerStyle: {\n        maxWidth: '150px',\n        minWidth: '150px',\n        width: '150px'\n      },\n      style: {\n        maxWidth: '150px',\n        minWidth: '150px',\n        width: '150px'\n      }\n    }];\n  }\n\n  public componentWillMount(): void {\n    // get data\n    const { id } = this.props.match.params;\n    this.props.getInventoryDetailAction(id, false);\n    // add listeners\n    window.addEventListener('resize', this.resizeCharts, false);\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `inventory-detail-${id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && (window.user.venuesAccess as string[]).includes(data.venue)) {\n        this.props.getInventoryDetailAction(id, true);\n        if (data.title) {\n          const status: any = {\n            found: 'success',\n            leftover: 'warning',\n            reported: 'grey'\n          };\n          (($ as any).toast as any)({\n            heading: data.title,\n            text: data.text,\n            position: 'top-right',\n            loaderBg: '#e2e2e2',\n            icon: status[data.status],\n            hideAfter: 5000,\n            stack: 6\n          });\n        }\n      }\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // remove listeners\n    window.removeEventListener('resize', this.resizeCharts, false);\n    // cancel request if component is inmounted\n    if (this.props.inventories.source) {\n      this.props.inventories.source.cancel('Operation canceled by the user.');\n    }\n    if (this.state.source) {\n      (this.state.source as any).cancel('Operation canceled by the user.');\n    }\n    const { id } = this.props.match.params;\n    this.socket.emit('leave', { room: `inventory-detail-${id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $venuesDetail = document.getElementById('chart-venues-detail') as HTMLDivElement;\n    const $brandDetail = document.getElementById('chart-brand-detail') as HTMLDivElement;\n    this.venuesDetailChart = echarts.init($venuesDetail);\n    this.brandDetailChart = echarts.init($brandDetail);\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    const { loadingDetail, detailByVenue, detailByBrand } = this.props.inventories;\n    // style react boostrap table\n    $('.react-bootstrap-table-pagination').css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div').removeClass('col-xs-6').addClass('col-xs-12').css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div:last-child').removeClass('text-right').addClass('text-right');\n    $('#pageDropDown').removeClass('btn-sm').addClass('btn-sm');\n    $('.bs-searchbox input').removeClass('input-sm').addClass('input-sm');\n    $('.pagination').removeClass('pagination-sm').addClass('pagination-sm').css({ margin: 0 });\n    const { setCharts } = this.state;\n    if (!loadingDetail && !setCharts) {\n      this.updateVenueChart(detailByVenue, false);\n      this.updateBrandChart(detailByBrand, false);\n      this.setState({\n        setCharts: true\n      });\n    } else {\n      this.updateVenueChart(detailByVenue, true);\n      this.updateBrandChart(detailByBrand, true);\n    }\n    $('[data-toggle=\"tooltip\"]').tooltip();\n    if (\n      !this.props.router.location || !prevProps.router.location ||\n      this.props.router.location.key !== prevProps.router.location.key\n    ) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public imagesFormatter(cell: string, row: any) {\n    if (row.images && row.images.length) {\n      return (\n        <div className='row'>{\n          row.images.map((image: any, index: number) => (\n            <div key={image._id} className={'col-md-12 images-25 text-center'} style={{ display: index === 0 ? '' : 'none' }}>\n              <a href={decodeURI(image.file.url)}\n                 data-toggle='lightbox'\n                 data-gallery={row._id}\n                 data-title={`${row.vin} / ${row.brand} ${row.denomination} `}\n                 data-footer={`${row.venueFound ? `En ${row.venueFound}` : `En ${row.venue}`} ${row.inventoriedBy ? ` por ${row.inventoriedBy}.` : ''}`}\n              >\n                <button className='btn btn-xs btn-default'>\n                  <i className='fa fa-fw fa-image' /> {row.images.length}\n                </button>\n                {/*<ImageLazyLoad url={decodeURI(image.file.url)} height={'10px'} maxHeight={'35px'} maxWidth={'35px'} small={true}/>*/}\n              </a>\n            </div>\n          ))\n        }</div>\n      );\n    }\n    return null;\n  }\n\n  private openFileManager(car: any): void {\n    const { inventories } = this.props;\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Archivos de ${car.vin}`,\n        <InventoryFileManager\n          inventories={inventories}\n          inventoryCardId={car._id}\n          socket={this.socket}\n        />\n      );\n    }, 200);\n  }\n\n  public filesFormatter(cell: string, row: any) {\n    return (\n      <div className='row'>\n        <div className={'col-md-12 images-25 text-center'}>\n          <button className='btn btn-xs btn-default' onClick={() => this.openFileManager(row)}>\n            <i className='fa fa-fw fa-cloud-upload' /> {row.files?.length}\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  public brandFormatter(cell: any, row: any) {\n    return (\n      <React.Fragment>\n        {\n          row.venue && row.venueFound && row.venueFound !== '-' && row.venue !== row.venueFound ?\n            <React.Fragment>\n              <i\n                data-toggle='tooltip'\n                data-placement='top'\n                title='Este vehículo no fue encontrado en la sucursal esperada.'\n                className='fa fa-warning text-yellow pointer'\n              /> {` `}\n            </React.Fragment>\n            : null\n        }\n        <React.Fragment>\n          <ShowIf\n            condition={row.vin?.length}\n            alternative={row?.vin}\n          >\n            <ShowIf\n              condition={hasPermission(window.user, 'viewCar')}\n              alternative={\n                <CopyText value={row.vin}>\n                  <strong className='text-primary'>{row.vin}</strong>\n                </CopyText>\n              }\n            >\n              <CopyText value={row?.vin}>\n                <strong\n                  className={'text-underline text-primary pointer'}\n                  onClick={() => {\n                    this.props.history.push(`/settings/cars/${row.carID}/`);\n                  }}\n                >\n                  {row?.vin}\n                </strong>\n              </CopyText>\n            </ShowIf>\n          </ShowIf>\n          &nbsp;\n          {\n            row.patent && row.patent.length\n              ? <CopyText value={row.patent} className={'text-muted'}><strong>{row.patent}</strong></CopyText>\n              : null\n          }\n        </React.Fragment>\n        <br />\n        <span className='text-muted'><strong>{cell}</strong> {row.denomination}</span>\n        {\n          row.color ?\n            <React.Fragment><br />\n              <span className='text-muted text-sm'>{row.color}</span>\n            </React.Fragment> : null\n        }\n        {\n          row.internalNumber ? <React.Fragment><br /><span className='text-muted text-sm'>{row.internalNumber}</span></React.Fragment> : null\n        }\n        <div className='visible-xs'>\n          {this.labelFormatter(cell, row)}\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  public selectedFormatter(cell: any, row: any) {\n    return (\n      <Checkbox\n        active={cell}\n        action={() => this.props.inventoryDetailChangeSelected(row._id)}\n        classes='icheck-in-checkbox'\n        style={{ margin: '5px', marginTop: '5px' }}\n      />\n    );\n  }\n\n  public statusFormatter(cell: CarStatusType) {\n    const { inventorySettings } = this.props.inventories;\n    const className = `${cell}Class` as CarStatusType;\n    return (\n      <span\n        className={`label label-${inventorySettings.hasOwnProperty(className) ? inventorySettings[className] : ''}`}\n        style={{\n          padding: '5px 10px'\n        }}\n      >\n        {inventorySettings.hasOwnProperty(cell) ? inventorySettings[cell] : cell}\n        </span>\n    );\n  }\n\n  public optionsFormatter(cell: any, row: any) {\n    const { labels } = this.props.inventories;\n    const { id } = this.props.match.params;\n    const newLabels = [...labels];\n    if (hasPermission(window.user, 'deleteReported')) {\n      newLabels.push({\n        _id: 'deleted',\n        name: 'Eliminar vehículo',\n        description: '',\n        sendTo: 'deleted',\n        requireCustomText: false,\n        isExhibition: false,\n        affected: ['reported'],\n        color: '',\n        active: true\n      });\n    }\n    const options = newLabels.filter((label) => {\n      return label.affected.includes(row.status);\n    });\n    if (options.length) {\n      return (\n        <div className='btn-group btn-group-sm' style={{\n          marginLeft: '5px'\n        }}>\n          <button type='button' className='btn btn-default'>\n            <i className='fa fa-fw fa-cogs' /> Etiqueta\n          </button>\n          <button type='button' className='btn btn-default dropdown-toggle' data-toggle='dropdown'>\n            <span className='caret' />\n            <span className='sr-only'>Toggle Dropdown</span>\n          </button>\n          <ul className='dropdown-menu dropdown-menu-right dropdown-menu-scrollable' role='menu'>\n            {\n              options.map((option) => {\n                return (\n                  <li key={option._id} onClick={() => {\n                    this.props.actionSetLabel(id, row._id, row.carID, option);\n                  }}>\n                    <a href='javascript:void(0)'>\n                      <i className={`fa ${this.iconStatus[option.sendTo]}`} />{option.name}\n                    </a>\n                  </li>\n                );\n              })\n            }\n          </ul>\n        </div>\n      );\n    }\n    return null;\n  }\n\n  public commentFormatter(cell: any, row: any) {\n    if (row.comments && row.comments.length) {\n      return (\n        <React.Fragment>\n          {maxText(row.comments[row.comments.length - 1].comment, 20)}<br />\n          <button className={'btn btn-default btn-xs'} onClick={() => this.carComments(row)}>\n            {row.comments.length} <i className={'fa fa-comments'} />\n          </button>\n        </React.Fragment>\n      );\n    } else {\n      return (\n        <button className={'btn btn-default btn-xs'} onClick={() => this.carComments(row)}>\n          Agregar <i className={'fa fa-comments'} />\n        </button>\n      );\n    }\n  }\n\n  public labelFormatter(cell: any, row: any) {\n    if (row.label) {\n      const sendTo = row.label.sendTo;\n      const { inventorySettings } = this.props.inventories;\n      const className = `${sendTo}Class` as CarStatusType;\n      return (\n        <React.Fragment>\n          <span\n            className={\n              `label label-${inventorySettings.hasOwnProperty(className) ? inventorySettings[className] : ''}`\n            }\n          >\n            <i className={`fa fa-fw ${this.iconStatus[sendTo]}`} />\n            {row.label.name}\n          </span>\n          {/*<span*/}\n          {/*   data-toggle=\"tooltip\"*/}\n          {/*   data-placement=\"top\"*/}\n          {/*   title={row.labelText}*/}\n          {/* >*/}\n          {/*   Ver más*/}\n          {/* </span>*/}\n          {\n            row.label.requireCustomText ?\n              <React.Fragment>\n                <p\n                  style={{\n                    paddingTop: '5px',\n                    marginBottom: 0\n                  }}\n                  className={'text-sm'}\n                >\n                  <strong>Datos adicionales:</strong>\n                </p>\n                <p\n                  className={'text-sm text-muted'}\n                >\n                  {row.labelText}\n                </p>\n              </React.Fragment> :\n              ''\n          }\n        </React.Fragment>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingDetail,\n      summary,\n      detail,\n      carsTable,\n      filter,\n      selectedItems,\n      cardTypes,\n      cardProperties,\n      inventorySettings\n    } = this.props.inventories;\n    const { tab, source } = this.state;\n    const selected = Object.keys(selectedItems);\n    const {\n      percentagePending,\n      percentageFound,\n      percentageLeftover,\n      percentageReported,\n      percentageMissing\n    } = this.calculateDetails(summary.results);\n\n    const showDownloadFile = isDercoDercocenter(this.props.inventories.detail) || moment().subtract(1, 'months').isSameOrBefore(summary.createdAt);\n\n    return (\n      <AppContainer title={summary.name} cMenu='2' cSubMenu='2.1' cAction={tab === 'summary' ? 'Consolidado' : 'Detalle'}>\n        <section className='content'>\n          <Row>\n            <div className='col-md-12 col-lg-12'>\n              <div className='box box-solid'>\n                <ul className='nav nav-pills nav-justified'>\n                  <li className={tab === 'summary' ? 'no-margin active' : 'no-margin'}>\n                    <a\n                      href='javascript:void(0);'\n                      className={tab === 'summary' ? 'background-transition' : ''}\n                      style={{ borderTop: '0', marginBottom: '0' }}\n                      onClick={() => this.changeTab('summary')}\n                    >Consolidado</a>\n                  </li>\n                  <li className={tab === 'detail' ? 'no-margin active' : 'no-margin'}>\n                    <a\n                      className={tab === 'detail' ? 'background-transition' : ''}\n                      href='javascript:void(0);'\n                      style={{ borderTop: '0', marginBottom: '0' }}\n                      onClick={() => this.changeTab('detail')}\n                    >Detalle</a>\n                  </li>\n                </ul>\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'summary' ? 'block' : 'none' }}>\n            <div className='col-md-12 col-lg-12'>\n              <div className='box box-default'>\n                <div className='box-header with-border'>\n                  <Row className='vertical-line-mobile'>\n                    <div className='col-md-4 col-lg-3'>\n                      <i className='fa fa-fw fa-user text-primary' />\n                      <strong>\n                        {\n                          !loadingDetail && summary && summary.createdBy ?\n                            summary.createdBy.fullName\n                            : '-'\n                        }\n                      </strong>\n\n                    </div>\n                    <div className='col-md-4 col-lg-3'>\n                      <i className='fa fa-fw fa-clock-o text-green' />\n                      <strong>{!loadingDetail && summary && summary.createdAt ? moment(summary.createdAt).format('LLL') : '-'}</strong>\n                    </div>\n                    <div className='col-md-4 col-lg-3'>\n                      <i className='fa fa-fw fa-clock-o text-red' />\n                      <strong>{!loadingDetail && summary && summary.finalizedAt ? moment(summary.finalizedAt).format('LLL') : '-'}</strong>\n                    </div>\n                    <div className='col-md-12 col-lg-3 text-right'>\n                      {!loadingDetail ? this.labelStatus(detail.status) : null}\n                    </div>\n                  </Row>\n                </div>\n                {\n                  loadingDetail &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'summary' ? 'block' : 'none' }}>\n            <div className='col-md-4 col-lg-4 pointer' onClick={() => this.sendToDetailFilteredByState('found')}>\n              <div className={`info-box bg-${inventorySettings.foundClass}`}>\n                <span className='info-box-icon'><i className='fa fa-check' /></span>\n                <div className='info-box-content'>\n                  <span className='info-box-text'>{inventorySettings.found}</span>\n                  <span className='info-box-number count'>\n                    {!loadingDetail && summary.results ? summary.results.found : <i className='fa fa-spinner fa-spin' />}\n                  </span>\n                  <div className='progress'>\n                    <div className='progress-bar' style={{\n                      width: `${!loadingDetail ? percentageFound : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className='progress-description'>\n                    {!loadingDetail ? `${percentageFound.toFixed(1)}% ${inventorySettings.found.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className='col-md-4 col-lg-4 pointer' onClick={() => this.sendToDetailFilteredByState('leftover')}>\n              <div className={`info-box bg-${inventorySettings.leftoverClass}`}>\n                <span className='info-box-icon'><i className='fa fa-arrow-up' /></span>\n                <div className='info-box-content'>\n                  <span className='info-box-text'>{inventorySettings.leftover}</span>\n                  <span className='info-box-number count'>\n                    {!loadingDetail && summary.results ? summary.results.leftover : <i className='fa fa-spinner fa-spin' />}\n                  </span>\n                  <div className='progress'>\n                    <div className='progress-bar' style={{\n                      width: `${!loadingDetail ? percentageLeftover : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className='progress-description'>\n                    {!loadingDetail ? `${percentageLeftover.toFixed(1)}% ${inventorySettings.leftover.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className='col-md-4 col-lg-4 pointer' onClick={() => this.sendToDetailFilteredByState('missing')}>\n              <div className={`info-box bg-${inventorySettings.missingClass}`}>\n                <span className='info-box-icon'>\n                  <i className='fa fa-arrow-down' />\n                </span>\n                <div className='info-box-content'>\n                  <span className='info-box-text'>{inventorySettings.missing}</span>\n                  <span className='info-box-number count'>\n                    {!loadingDetail && summary.results ? summary.results.missing : <i className='fa fa-spinner fa-spin' />}\n                  </span>\n                  <div className='progress'>\n                    <div className='progress-bar' style={{\n                      width: `${!loadingDetail ? percentageMissing : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className='progress-description'>\n                    {!loadingDetail ? `${percentageMissing.toFixed(1)}% ${inventorySettings.missing.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'summary' ? 'block' : 'none' }}>\n            <div className='col-md-12 col-lg-12'>\n              <div className='box box-primary'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Detalle de inventario por sucursal</h3>\n                  {\n                    showDownloadFile ?\n                      <div className='box-tools pull-right'>\n                        <button\n                          className='btn btn-sm btn-primary hidden-xs hidden-sm'\n                          onClick={() => this.xlsExport(['pending', 'found', 'leftover', 'missing', 'reported'])}\n                        >\n                          <i className='fa fa-fw fa-download' /> Exportar Excel\n                        </button>\n                      </div> : null\n                  }\n                </div>\n                <div className='box-body'>\n                  <div id='chart-venues-detail' style={{ height: '550px', maxWidth: '100%' }} />\n                </div>\n                {\n                  loadingDetail &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'summary' ? 'block' : 'none' }}>\n            <div className='col-md-12'>\n              <div className='box box-success'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Detalle de inventario por Marca</h3>\n                  {/*<div className=\"box-tools pull-right\">*/}\n                  {/*</div>*/}\n                </div>\n                <div className='box-body'>\n                  <div id='chart-brand-detail' style={{ height: '550px', maxWidth: '100%' }} />\n                </div>\n                {\n                  loadingDetail &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'detail' ? 'block' : 'none' }}>\n            <div className='col-md-6 col-lg-6 pointer' onClick={() => this.sendToDetailFilteredByState('pending')}>\n              <div className={`info-box bg-${inventorySettings.pendingClass}`}>\n                <span className='info-box-icon'><i className='fa fa-clock-o' /></span>\n                <div className='info-box-content'>\n                  <span className='info-box-text'>{inventorySettings.pending}</span>\n                  <span className='info-box-number count'>\n                    {!loadingDetail && summary.results ? summary.results.pending : <i className='fa fa-spinner fa-spin' />}\n                  </span>\n                  <div className='progress'>\n                    <div className='progress-bar' style={{\n                      width: `${!loadingDetail ? percentagePending : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className='progress-description'>\n                    {!loadingDetail ? `${percentagePending.toFixed(1)}% ${inventorySettings.pending.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n            <div className='col-md-6 col-lg-6 pointer' onClick={() => this.sendToDetailFilteredByState('reported')}>\n              <div className={`info-box bg-${inventorySettings.reportedClass}`}>\n                <span className='info-box-icon'><i className='fa fa-exclamation' /></span>\n                <div className='info-box-content'>\n                  <span className='info-box-text'>{inventorySettings.reported}</span>\n                  <span className='info-box-number count'>\n                    {!loadingDetail && summary.results ? summary.results.reported : <i className='fa fa-spinner fa-spin' />}\n                  </span>\n                  <div className='progress'>\n                    <div className='progress-bar' style={{\n                      width: `${!loadingDetail ? percentageReported : 0}%`,\n                      transition: loadingDetail ? 'none' : 'width .6s ease'\n                    }} />\n                  </div>\n                  <span className='progress-description'>\n                    {!loadingDetail ? `${percentageReported.toFixed(1)}% ${inventorySettings.reported.toLowerCase()}.` : null}\n                  </span>\n                </div>\n              </div>\n            </div>\n          </Row>\n          <Row style={{ display: tab === 'detail' ? 'block' : 'none' }}>\n            <div className='col-md-12'>\n              <div className='box box-info'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>\n                    Detalle de inventario {selected.length ? <small\n                      className='hidden-sm hidden-xs text-primary'>{selected.length} {selected.length > 1 ? 'seleccionados' : 'seleccionado'}.</small> :\n                    <small>{carsTable.length}</small>}\n                  </h3>\n                  <div className='box-tools pull-right'>\n                    {\n                      showDownloadFile ?\n                        <button\n                          className='btn btn-sm btn-primary hidden-xs hidden-sm'\n                          onClick={() => this.xlsExport(['pending', 'found', 'leftover', 'missing', 'reported'])}\n                        >\n                          <i className='fa fa-fw fa-download' /> Exportar Excel\n                        </button>\n                        : null\n                    }\n                    <div className='btn-group btn-group-sm hidden-xs hidden-sm' style={{ marginLeft: '5px' }}>\n                      <button type='button' className='btn btn-success'><i className='fa fa-fw fa-cogs' /> Acciones</button>\n                      <button type='button' className='btn btn-success dropdown-toggle' data-toggle='dropdown'>\n                        <span className='caret' />\n                        <span className='sr-only'>Toggle Dropdown</span>\n                      </button>\n                      <ul className='dropdown-menu' role='menu'>\n                        <li onClick={() => this.downloadImages({ all: true })}>\n                          <a href='javascript:void(0)'><i className='fa fa-fw fa-download' /> Descargar todas las imágenes</a>\n                        </li>\n                        <li onClick={() => this.downloadImages({})}>\n                          <a href='javascript:void(0)'><i className='fa fa-fw fa-download' /> Descargar imágenes seleccionadas</a>\n                        </li>\n                      </ul>\n                    </div>\n                  </div>\n                </div>\n                <div className='box-body no-padding' id='table-detail-inventory' style={{\n                  display: loadingDetail ? 'none' : ''\n                }}>\n                  <Row style={{ margin: '5px 0' }}>\n                    <div className='col-md-12'>\n                      <div className='form-group'>\n                        <label htmlFor='cars' className='control-label'>Unidades</label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          id='cars'\n                          placeholder='Busca por VIN, patente, marca o modelo.'\n                          onChange={this.handleChangeSearchText}\n                        />\n                      </div>\n                    </div>\n                    <div className='col-md-3'>\n                      <div className='form-group'>\n                        <label htmlFor='venues' className='control-label'>Sucursales</label>\n                        <BootstrapSelect\n                          noneSelectedText='Todas'\n                          displayItems={2}\n                          sm={true}\n                          selectedText='sucursales seleccionadas.'\n                          selected={filter.venues}\n                          allOption={true}\n                          selectAll={this.filterAllVenues}\n                          options={detail.venues.map((venue: any) => ({\n                            value: venue._id,\n                            text: venue.name\n                          }))}\n                          onClick={this.filterVenues}\n                        />\n                      </div>\n                    </div>\n                    <div className='col-md-3'>\n                      <div className='form-group'>\n                        <label htmlFor='states' className='control-label'>Estados</label>\n                        <BootstrapSelect\n                          noneSelectedText='Todos'\n                          displayItems={4}\n                          sm={true}\n                          selectedText='estados seleccionados.'\n                          separator=' - '\n                          options={Object\n                            .keys(this.statusText)\n                            .map((status: CarStatusType) => ({\n                              value: status,\n                              text: inventorySettings[status],\n                              className: `label label-${inventorySettings[`${status}Class` as CarStatusType]}`\n                            }))}\n                          selected={filter.states}\n                          onClick={this.filterStatus}\n                        />\n                      </div>\n                    </div>\n                    {\n                      cardTypes.length ?\n                        <div className='col-md-3'>\n                          <div className='form-group'>\n                            <label htmlFor='states' className='control-label'>Tipo</label>\n                            <BootstrapSelect\n                              noneSelectedText='Todos'\n                              displayItems={4}\n                              sm={true}\n                              selectedText='estados seleccionados.'\n                              separator=' - '\n                              options={cardTypes\n                                .map((name) => ({\n                                  value: name,\n                                  text: name\n                                }))}\n                              selected={[filter.type]}\n                              autoClouse={true}\n                              onClick={this.filterType}\n                            />\n                          </div>\n                        </div>\n                        : null\n                    }\n                    {\n                      cardProperties.length ?\n                        <div className='col-md-3'>\n                          <div className='form-group'>\n                            <label htmlFor='states' className='control-label'>Propiedad</label>\n                            <BootstrapSelect\n                              noneSelectedText='Todos'\n                              displayItems={4}\n                              sm={true}\n                              selectedText='estados seleccionados.'\n                              separator=' - '\n                              options={cardProperties\n                                .map((name) => ({\n                                  value: name,\n                                  text: name\n                                }))}\n                              selected={[filter.property]}\n                              autoClouse={true}\n                              onClick={this.filterProperty}\n                            />\n                          </div>\n                        </div>\n                        : null\n                    }\n                  </Row>\n                  <Row style={{ margin: '5px 0' }}>\n                    <div className='col-md-3 col-md-push-9 text-right' style={{ marginBottom: '10px' }}>\n                      <button\n                        className='btn btn-default btn-sm'\n                        onClick={this.clearFilter}\n                        style={{ paddingLeft: '5px' }}\n                        disabled={\n                          !(filter.states.length || filter.text.length || filter.venues.length || filter.type.length || filter.property.length)}\n                      >\n                        <i className='fa fa-fw fa-eraser' /> Limpiar\n                      </button>\n                    </div>\n                  </Row>\n                  {\n                    this.state.downloadImages.downloading ?\n                      <Row>\n                        <div className='col-md-12' style={{ padding: '24px 25vh' }}>\n                          <div className='progress progress-xs progress-striped active'>\n                            <div\n                              className='progress-bar progress-bar-success'\n                              style={{ width: `${this.state.downloadImages.progress}%` }} />\n                          </div>\n                          {\n                            this.state.downloadImages.downloading && this.state.downloadImages.sizeFile === 0 ?\n                              <div className='text-center'>\n                                Estamos preparando las imágenes.\n                                <button\n                                  className='btn btn-sm btn-danger'\n                                  style={{ marginLeft: '10px' }}\n                                  onClick={() => (source as any).cancel('Operation canceled by the user.')}\n                                >\n                                  Cancelar\n                                </button>\n                              </div>\n                              : <div className='text-center'>\n                                Descargando imágenes {this.state.downloadImages.progress}%\n                                <button\n                                  className='btn btn-sm btn-danger'\n                                  style={{ marginLeft: '10px' }}\n                                  onClick={() => (source as any).cancel('Operation canceled by the user.')}\n                                >\n                                  Cancelar\n                                </button>\n                              </div>\n                          }\n                        </div>\n                      </Row> : null\n                  }\n                  <Row>\n                    <div className='col-md-12'>\n                      {\n                        !loadingDetail && carsTable.length ?\n                          <BootstrapTable\n                            keyField='_id'\n                            data={carsTable}\n                            columns={this.columns}\n                            filter={filterFactory()}\n                            pagination={paginationFactory(this.paginationOption)}\n                            defaultSorted={this.defaultSorted}\n                          /> : !loadingDetail ? <p className='text-center text-muted'>\n                            <ImageLazyLoad\n                              url='/images/not_found.png'\n                              height={'200px'}\n                              style={{\n                                opacity: 0.5,\n                                maxHeight: '200px',\n                                marginBottom: '10px'\n                              }}\n                              replaceLoading={<i\n                                className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                                style={{ padding: '30px' }}\n                              />}\n                            /><br />\n                            <strong>No hay información para mostrar</strong>\n                          </p> : null\n                      }\n                    </div>\n                  </Row>\n                </div>\n                {\n                  carsTable.length === 0 && loadingDetail &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </Row>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private downloadImages({ all }: { all?: boolean }) {\n    const { id } = this.props.match.params;\n    const { selectedItems, summary, carsTable } = this.props.inventories;\n    let ids: string[];\n    if (all) {\n      ids = carsTable\n        .filter((car) => car.images.length)\n        .map((car) => car._id);\n    } else {\n      ids = Object.keys(selectedItems);\n    }\n\n    const countImages: number = carsTable\n      .filter((car) => ids.includes(car._id))\n      .reduce((a: any, b: any) => {\n        return a + b.images.length;\n      }, 0);\n\n    if (countImages > 0) {\n      this.setState({\n        downloadImages: {\n          downloading: true,\n          progress: 0,\n          sizeFile: 0,\n          loaded: 0\n        }\n      });\n      const api: ApiService = new ApiService();\n      const instance = api.getInstance();\n      instance.defaults.responseType = 'blob';\n      instance.defaults.timeout = 7200000;\n      const source = api.getSource();\n      this.setState({\n        source\n      });\n      instance\n        .post(\n          `/api/inventory/${id}/download-images/`, {\n            cars: ids\n          }, {\n            cancelToken: source.token,\n            onDownloadProgress: (progressEvent) => {\n              const sizeFile = parseInt(progressEvent.target.getResponseHeader('size'), 10);\n              const { loaded } = progressEvent;\n              if (sizeFile) {\n                const progress = Math.round((progressEvent.loaded * 100) / sizeFile);\n                this.setState({\n                  downloadImages: {\n                    downloading: true,\n                    progress,\n                    sizeFile,\n                    loaded\n                  }\n                });\n              }\n            }\n          }\n        )\n        .then((response) => {\n          const blob = new Blob([response.data], {\n            type: 'application/zip'\n          });\n          const fileName = `${summary.name}.zip`;\n          // if (typeof window.navigator.msSaveBlob !== 'undefined') {\n          //   // IE workaround for \"HTML7007: One or more blob URLs were\n          //   // revoked by closing the blob for which they were created.\n          //   // These URLs will no longer resolve as the data backing\n          //   // the URL has been freed.\"\n          //   window.navigator.msSaveBlob(blob, fileName);\n          // } else {\n          const blobURL = URL.createObjectURL(blob);\n          const tempLink = document.createElement('a');\n          tempLink.style.display = 'none';\n          tempLink.href = blobURL;\n          tempLink.setAttribute('download', fileName);\n          // Safari thinks _blank anchor are pop ups. We only want to set _blank\n          // target if the browser does not support the HTML5 download attribute.\n          // This allows you to download files in desktop safari if pop up blocking\n          // is enabled.\n          if (typeof tempLink.download === 'undefined') {\n            tempLink.setAttribute('target', '_blank');\n          }\n          document.body.appendChild(tempLink);\n          tempLink.click();\n          document.body.removeChild(tempLink);\n          URL.revokeObjectURL(blobURL);\n          // }\n          this.setState({\n            downloadImages: {\n              ...this.state.downloadImages,\n              downloading: false,\n              progress: 100,\n              sizeFile: 0,\n              loaded: 0\n            }\n          });\n        })\n        .catch((err) => {\n          if (!Axios.isCancel(err)) {\n            Raven.captureException(JSON.stringify({\n              error: JSON.stringify(err),\n              ...this.state.downloadImages\n            }));\n            swal!('Descargar imágenes', 'ha ocurrido un error descargando las imágenes.', 'error');\n          }\n          this.setState({\n            downloadImages: {\n              downloading: false,\n              progress: 0,\n              sizeFile: 0,\n              loaded: 0\n            }\n          });\n        });\n    } else {\n      if (all) {\n        swal!('Descargar imágenes', 'No hay imágenes para dercargar.', 'error');\n      } else {\n        swal!('Descargar imágenes', 'No has seleccionado unidades que contengan imágenes.', 'error');\n      }\n    }\n  }\n\n  private filterVenues(value: any) {\n    const { filter } = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      venues: filter.venues.includes(value)\n        ? filter.venues.filter((venue) => venue !== value)\n        : [value, ...filter.venues]\n    });\n  }\n\n  private filterAllVenues(value: boolean) {\n    const { filter, detail } = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      venues: value ? detail.venues.map((venue: any) => venue._id) : []\n    });\n  }\n\n  private filterStatus(value: any) {\n    const { filter } = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      states: filter.states.includes(value)\n        ? filter.states.filter((state) => state !== value)\n        : [value, ...filter.states]\n    });\n  }\n\n  private filterType(value: string) {\n    const { filter } = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      type: filter.type !== value ? value : ''\n    });\n  }\n\n  private filterProperty(value: string) {\n    const { filter } = this.props.inventories;\n    this.props.inventoryDetailChangeFilter({\n      ...filter,\n      property: filter.property !== value ? value : ''\n    });\n  }\n\n  private sendToDetailFilteredByState(state: string) {\n    this.props.inventoryDetailChangeFilter({\n      text: '',\n      type: '',\n      property: '',\n      venues: [],\n      states: [state]\n    });\n    $('#cars').val('');\n    this.changeTab('detail');\n    setTimeout(() => {\n      goToSection('#table-detail-inventory');\n    }, 100);\n  }\n\n  private sendToDetailFilteredByVenue(venue: string) {\n    this.props.inventoryDetailChangeFilter({\n      text: '',\n      type: '',\n      property: '',\n      venues: [venue],\n      states: []\n    });\n    $('#cars').val('');\n    this.changeTab('detail');\n    setTimeout(() => {\n      goToSection('#table-detail-inventory');\n    }, 100);\n  }\n\n  private clearFilter(): void {\n    this.props.inventoryDetailChangeFilter({\n      venues: [],\n      states: [],\n      property: '',\n      type: '',\n      text: ''\n    });\n    $('#cars').val('');\n  }\n\n  private handleChangeSearchText(e: React.ChangeEvent<HTMLInputElement>): void {\n    e.preventDefault();\n    const value = e.target.value.trim();\n    const { filter } = this.props.inventories;\n    this.props.inventoryDetailChangeFilterText({\n      ...filter,\n      text: value ? e.target.value : ''\n    });\n  }\n\n  private changeTab(name: string): void {\n    const { id } = this.props.match.params;\n    if (name === 'detail') {\n      this.props.history.replace(`/inventory/${id}/detail/`);\n    } else {\n      this.props.history.replace(`/inventory/${id}/`);\n    }\n    this.setState({\n      tab: name\n    }, () => {\n      this.resizeCharts();\n    });\n  }\n\n  private selectedHeaderFormatter(): React.ReactElement<IPropsType> | null {\n    return (\n      <React.Fragment>\n        <Checkbox\n          active={false}\n          action={undefined}\n          classes='icheck-in-checkbox'\n          style={{ margin: '5px', marginTop: '5px' }}\n        />\n        <i className='fa fa-order' />\n      </React.Fragment>\n    );\n  }\n\n  private calculateDetails(results: IInventorySummaryResult | undefined) {\n    const { loadingDetail } = this.props.inventories;\n    if (!loadingDetail) {\n      const totalCars = results ? results.missing + results.found + results.pending + results.leftover + results.reported : 0;\n      return {\n        totalCars,\n        percentagePending: results && results.pending ? (100 / totalCars) * results.pending : 0,\n        percentageFound: results && results.found ? (100 / totalCars) * results.found : 0,\n        percentageLeftover: results && results.leftover ? (100 / totalCars) * results.leftover : 0,\n        percentageMissing: results && results.missing ? (100 / totalCars) * results.missing : 0,\n        percentageReported: results && results.reported ? (100 / totalCars) * results.reported : 0\n      };\n    }\n    return {\n      totalCars: 0,\n      percentagePending: 0,\n      percentageFound: 0,\n      percentageLeftover: 0,\n      percentageMissing: 0,\n      percentageReported: 0\n    };\n  }\n\n  private carComments(inventoryCar: IInventoryCar): void {\n    const { inventories } = this.props;\n    this.props.updateInventoryCarAction(inventoryCar);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        `Comentarios`,\n        <InventoryCarComments\n          inventories={inventories}\n          socket={this.socket}\n          addCommentAction={addCommentAction}\n          sendCommentAction={sendCommentAction}\n        />\n      );\n    }, 200);\n  }\n\n  private xlsExport(status: string[]) {\n    this.trackClick('Exportar');\n    const { detail } = this.props.inventories;\n    const data: any = [];\n    const { inventorySettings } = this.props.inventories;\n    // Order data\n    if (detail && detail.cars && detail.cars.length) {\n      for (const car of detail.cars) {\n        if (status.includes(car.status) && car.car?.vin) {\n          data.push({\n            VIN: car.car.vin,\n            Patente: car.car.patent && car.car.patent.length ? car.car.patent : '-',\n            ['Nº interno']: car.car.internalNumber && car.car.internalNumber.length ? car.car.internalNumber : '-',\n            Marca: car.car.brand && car.car.brand.length ? car.car.brand : '-',\n            ['Denominación']: car.car.denomination && car.car.denomination.length ? car.car.denomination : '-',\n            Color: car.car.color && car.car.color.length ? car.car.color : '-',\n            Sucursal: car.venue && car.venue.hasOwnProperty('name') ? car.venue.name : '-',\n            Tipo: car.car.type && car.car.type ? car.car.type : '-',\n            Propiedad: car.car.property && car.car.property ? car.car.property : '-',\n            ['Sucursal encontrado']: car.venueFound && car.venueFound.hasOwnProperty('name') ? car.venueFound.name : '-',\n            ['Encontrado por']: car.inventoriedBy ? `${car.inventoriedBy.firstName} ${car.inventoriedBy.lastName}` : '-',\n            ['Comentario']: car.comments && car.comments.length ? `${car.comments[car.comments.length - 1].comment}` : '-',\n            ['Etiqueta']: car.label ? car.label.name : '-',\n            ['Comentario etiqueta']: car.label && car.label.requireCustomText && car.labelText ? car.labelText : '-',\n            ['Imágenes']: car.images.length ? car.images.length : '-',\n            // ['Imágenes']: car.images.length ? car.images.map((image: any) => `${image.file.url}`).join('\\n') : '-',\n            Status: inventorySettings.hasOwnProperty(car.status) ? inventorySettings[car.status as CarStatusType] : '-'\n          });\n        }\n      }\n    }\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet(data);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Detalle');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, `Detalle ${detail.name}.xlsx`);\n  }\n\n  private updateVenueChart(detailByVenue: IDetailByVenue[], update?: boolean) {\n    const { loadingDetail, detail, inventorySettings } = this.props.inventories;\n    const venuesNames: string[] = [];\n    const venuesFound: any[] = [];\n    const venuesPending: any[] = [];\n    const venuesLeftover: any[] = [];\n    const venuesReported: any[] = [];\n    const venuesMissing: any[] = [];\n    // detailByVenue.sort((a, b) => {\n    //   return a.name.localeCompare(b.name);\n    // });\n    if (detail.status === 'inProcess') {\n      detailByVenue.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n    } else {\n      detailByVenue.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n      detailByVenue.sort((a: any, b: any) => {\n        const suma = a.results.leftover + a.results.missing + a.results.reported;\n        const sumb = b.results.leftover + b.results.missing + b.results.reported;\n        return sumb - suma;\n      });\n    }\n\n    for (const venue of detailByVenue) {\n      venuesNames.push(venue.name);\n      venuesFound.push(venue.results && venue.results.found > 0 ? venue.results.found : null);\n      venuesPending.push(venue.results && venue.results.pending > 0 ? venue.results.pending : null);\n      venuesLeftover.push(venue.results && venue.results.leftover > 0 ? venue.results.leftover : null);\n      venuesReported.push(venue.results && venue.results.reported > 0 ? venue.results.reported : null);\n      venuesMissing.push(venue.results && venue.results.missing > 0 ? venue.results.missing : null);\n    }\n    const optionVenues: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        },\n        formatter: (params: any) => {\n          const colorSpan = (color: any) => `<span style='display:inline-block;margin-right:5px;border-radius:10px;width:10px;height:10px;background-color:${color};'></span>`;\n          let rez = `<span> ${params[0].axisValue}</span>`;\n          // console.log(params); //quite useful for debug\n          let total = 0;\n          params.forEach((item: any) => {\n            // console.log(item); //quite useful for debug\n            const value = item.data ? item.data : 0;\n            const xx = `<br />${item.marker} ${item.seriesName}: ${value}`;\n            total += value;\n            rez = rez + xx;\n          });\n          rez += `<br />${colorSpan('#ffffff')} <strong>Total: ${total}</strong>`;\n          return rez;\n        }\n      },\n      legend: {\n        // x: 'center',\n        bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      xAxis: {\n        type: 'category',\n        data: venuesNames,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 60,\n          fontSize: 10,\n          formatter: (value: string) => {\n            let text = '';\n            const array = value.split(' ');\n            for (let i = 0; i < array.length; i++) {\n              text += `${array[i]}`;\n              if (i > 0 && i % 2 !== 0) {\n                text += ' \\n';\n              } else {\n                text += ' ';\n              }\n            }\n            return text;\n          }\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            type: 'dashed',\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        left: 5,\n        // right\n        right: 10,\n        containLabel: true\n      },\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      series: [{\n        data: venuesFound,\n        name: inventorySettings.found,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesLeftover,\n        name: inventorySettings.leftover,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesMissing,\n        name: inventorySettings.missing,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesPending,\n        name: inventorySettings.pending,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        // barMinHeight: 20,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }, {\n        data: venuesReported,\n        name: inventorySettings.reported,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        label: {\n          normal: {\n            ...this.labelOption.normal\n          }\n        },\n        barGap: '0'\n      }]\n    };\n    if (!update) {\n      optionVenues.legend = {\n        ...optionVenues.legend,\n        selected: {\n          Reportados: false\n        }\n      };\n      if (detail.status === 'finalized') {\n        (optionVenues.legend as any).selected = {\n          ...(optionVenues.legend as any).selected,\n          Pendientes: false\n        };\n      }\n      optionVenues.dataZoom = [\n        {\n          show: venuesNames.length > 12,\n          realtime: true,\n          start: 0,\n          end: venuesNames.length > 12 ? 80 : 100\n        }\n      ];\n    }\n    if (!loadingDetail) {\n      this.venuesDetailChart.setOption(optionVenues);\n      (this.venuesDetailChart as any).off();\n      this.venuesDetailChart.on('click', (params: any) => {\n        const venue = detailByVenue[params.dataIndex];\n        this.sendToDetailFilteredByVenue(venue._id);\n      });\n    }\n  }\n\n  private updateBrandChart(detailByBrand: IDetailByBrand[], update?: boolean) {\n    const { loadingDetail, detail, inventorySettings } = this.props.inventories;\n    const brandNames: string[] = [];\n    const brandFound: any[] = [];\n    const brandPending: any[] = [];\n    const brandLeftover: any[] = [];\n    const brandReported: any[] = [];\n    const brandMissing: any[] = [];\n    // detailByBrand.sort((a, b) => {\n    //   return a.name.localeCompare(b.name);\n    // });\n    if (detail.status === 'inProcess') {\n      detailByBrand.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n    } else {\n      detailByBrand.sort((a: any, b: any) => {\n        return b.results.pending - a.results.pending;\n      });\n      detailByBrand.sort((a: any, b: any) => {\n        const suma = a.results.leftover + a.results.missing + a.results.reported;\n        const sumb = b.results.leftover + b.results.missing + b.results.reported;\n        return sumb - suma;\n      });\n    }\n\n    for (const brand of detailByBrand) {\n      brandNames.push(brand.name);\n      brandFound.push(brand.results && brand.results.found > 0 ? brand.results.found : null);\n      brandPending.push(brand.results && brand.results.pending > 0 ? brand.results.pending : null);\n      brandLeftover.push(brand.results && brand.results.leftover > 0 ? brand.results.leftover : null);\n      brandReported.push(brand.results && brand.results.reported > 0 ? brand.results.reported : null);\n      brandMissing.push(brand.results && brand.results.missing > 0 ? brand.results.missing : null);\n    }\n    const optionBrands: echarts.EChartOption = {\n      tooltip: {\n        trigger: 'axis',\n        axisPointer: {\n          type: 'shadow'\n        }\n      },\n      legend: {\n        // x: 'center',\n        bottom: 50,\n        data: [inventorySettings.found, inventorySettings.leftover, inventorySettings.missing, inventorySettings.pending, inventorySettings.reported]\n      },\n      xAxis: {\n        type: 'category',\n        data: brandNames,\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        axisLabel: {\n          rotate: 90\n        }\n      },\n      yAxis: {\n        minInterval: 1,\n        type: 'value',\n        axisLine: {\n          lineStyle: {\n            color: 'rgba(0, 0, 0, 0.5)'\n          }\n        },\n        splitLine: {\n          show: true,\n          lineStyle: {\n            color: 'rgba(150, 150, 150, 0.5)'\n          }\n        }\n      },\n      grid: {\n        top: 30,\n        bottom: 100,\n        // left\n        left: 5,\n        // right\n        right: 10,\n        containLabel: true\n      },\n      color: [inventorySettings.foundColor, inventorySettings.leftoverColor, inventorySettings.missingColor, inventorySettings.pendingColor, inventorySettings.reportedColor],\n      series: [{\n        data: brandFound,\n        name: inventorySettings.found,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandLeftover,\n        name: inventorySettings.leftover,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandMissing,\n        name: inventorySettings.missing,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandPending,\n        name: inventorySettings.pending,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }, {\n        data: brandReported,\n        name: inventorySettings.reported,\n        type: 'bar',\n        stack: 'cars',\n        barMaxWidth: 100,\n        barGap: '0'\n      }]\n    };\n    if (!update) {\n      optionBrands.legend = {\n        ...optionBrands.legend,\n        selected: {\n          Reportados: false\n        }\n      };\n      if (detail.status === 'finalized') {\n        (optionBrands.legend as any).selected = {\n          ...(optionBrands.legend as any).selected,\n          Pendientes: false\n        };\n      }\n      optionBrands.dataZoom = [\n        {\n          show: brandNames.length > 12,\n          realtime: true,\n          start: 0,\n          end: brandNames.length > 12 ? 80 : 100\n        }\n      ];\n    }\n    if (!loadingDetail) {\n      this.brandDetailChart.setOption(optionBrands);\n    }\n  }\n\n  private resizeCharts(): void {\n    if (this.venuesDetailChart) {\n      this.venuesDetailChart.resize();\n      setTimeout(() => {\n        this.venuesDetailChart.resize();\n      }, 400);\n    }\n    if (this.brandDetailChart) {\n      this.brandDetailChart.resize();\n      setTimeout(() => {\n        this.brandDetailChart.resize();\n      }, 400);\n    }\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return (\n      <span className='react-bootstrap-table-pagination-total text-ellipsis' style={{ fontSize: '75%' }}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private labelStatus(option: string): React.ReactElement<IPropsType> | null {\n    if (option === 'finalized') {\n      return <span className='label label-success' style={{\n        padding: '5px 10px', fontSize: '11px'\n      }}><i className='fa fa-fw fa-check' /> Finalizado</span>;\n    } else if (option === 'inProcess') {\n      return <span className='label label-primary' style={{\n        padding: '5px 10px', fontSize: '11px'\n      }}><i className='fa fa-fw fa-spin fa-spinner' /> En progreso</span>;\n    } else {\n      return null;\n    }\n  }\n\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState, router: RouterState }) => {\n  return {\n    inventories: state.inventories,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer)),\n    updateInventoryCarAction: (inventoryCar: IInventoryCar) => dispatch(updateInventoryCarAction(inventoryCar)),\n    inventoryDetailChangeSelected: (item: string) => dispatch(inventoryDetailChangeSelected(item)),\n    getInventoryDetailAction: (id: string, update: boolean) => dispatch(getInventoryDetailAction(id, update)),\n    inventoryDetailChangeFilter: (filter: IFilterCar) => dispatch(inventoryDetailChangeFilter(filter)),\n    inventoryDetailChangeFilterText: (filter: IFilterCar) => dispatch(inventoryDetailChangeFilterText(filter)),\n    actionSetLabel: (inventory: string, car: string, carID: string, label: IInventoryLabel) => dispatch(actionSetLabel(inventory, car, carID, label))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryDetailView);\n","import * as React from 'react';\nimport { connect } from 'react-redux';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport { IWindow } from '../../interfaces/window';\nimport Row from '../Utils/Row';\nimport ShowIf from '../Utils/ShowIf';\nimport MultiUploadFiles, { imageStatus } from '../Utils/MultiUploadFiles';\nimport ApiService from '../../utils/axios';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType {\n  inventoryCardId: string;\n  inventories: IInventoryState;\n  socket: Socket;\n}\n\ninterface IStateType {\n  error: Error | null;\n  loading: boolean;\n  files: any[];\n}\n\ndeclare let window: IWindow;\n\nclass InventoryFileManager extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    loading: true,\n    files: []\n  };\n\n  readonly api: ApiService;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.api = new ApiService();\n    this.deleteFile = this.deleteFile.bind(this);\n  }\n\n  public componentWillMount(): void {\n    // if (inventoryCar) {\n    //   const id = (inventoryCar as any)._id;\n    //   this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n    //   this.props.socket.on('connect', () => {\n    //     this.props.socket.emit('join', { room: `inventory-comment-${id}` });\n    //   });\n    //   this.props.socket.on('NEW_COMMENT', (data: any): void => {\n    //   });\n    // }\n  }\n\n  public componentDidMount(): void {\n    const { inventoryCardId } = this.props;\n    this.api.getInventoryCarFiles(inventoryCardId)\n      .then((response) => {\n        const { files } = response.data;\n        this.setState({\n          loading: false,\n          files: files.map((file: any) => {\n            return {\n              ...file.file,\n              _id: file._id,\n              url: decodeURIComponent(file.file.url),\n              isImage: this.isImage(file.file.type),\n              status: imageStatus.complete\n            };\n          })\n        });\n      });\n  }\n\n  private deleteFile(id: string) {\n    this.api.deleteInventoryCarFile(id);\n  }\n\n  private isImage(type: string): boolean {\n    const accepted = ['image/jpg', 'image/jpeg', 'image/png'];\n    return accepted.includes(type);\n  }\n\n  public componentWillUnmount(): void {\n    const { inventoryCar } = this.props.inventories;\n    if (inventoryCar) {\n      const id = (inventoryCar as any)._id;\n      this.props.socket.emit('leave', { room: `inventory-comment-${id}` });\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { inventories, inventoryCardId } = this.props;\n    const { loading, files } = this.state;\n    return (\n      <>\n        <Row>\n          <div className={'col-md-12'}>\n            <MultiUploadFiles\n              url={`/api/v1/inventory/${inventories.detail._id}/upload-file/`}\n              listMode={true}\n              deleteCalback={this.deleteFile}\n              body={{\n                inventoryCardId\n              }}\n              onChange={(files) => {\n                this.setState({ files });\n              }}\n              files={files}\n            />\n          </div>\n          <ShowIf condition={loading}>\n            <div className={'col-md-12 text-center'}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </div>\n          </ShowIf>\n        </Row>\n      </>\n    );\n  }\n\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryFileManager);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport {\n  deleteInventoryAction,\n  finishInventoryAction,\n  getInventoriesAction,\n  IInventoryState,\n  InventoryReduxAction\n} from '../../actions/inventory.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission } from '../../utils/common';\nimport Row from '../Utils/Row';\nimport Paginator from '../Utils/Paginator';\nimport { Link } from 'react-router-dom';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  inventories: IInventoryState;\n  dispatch: Dispatch<InventoryReduxAction>;\n\n  getInventoriesAction(loading: boolean, page: number): void;\n\n  finishInventoryAction(id: string): void;\n\n  deleteInventoryAction(id: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass InventoryListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  // static propTypes = {\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  readonly state = {\n    error: null\n  };\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Inventarios';\n    this.create = this.create.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.labelStatus = this.labelStatus.bind(this);\n    this.finishInventoryAction = this.finishInventoryAction.bind(this);\n    this.deleteInventoryAction = this.deleteInventoryAction.bind(this);\n    this.goToDetail = this.goToDetail.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { page } = this.props.inventories.pagination;\n    // set the title of the page\n    window.scrollTo(0, 0);\n\n    // get data\n    this.props.getInventoriesAction(true, page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `inventory-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.inventories;\n        this.props.getInventoriesAction(false, pagination.page);\n      }\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.inventories.source) {\n      this.props.inventories.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `inventory-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { inventories, inventorySettings, loading, pagination } = this.props.inventories;\n    return (\n      <AppContainer title='' cMenu='2' cSubMenu='2.1'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Gestión de inventarios <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                {\n                  hasPermission(window.user, 'createInventory') ?\n                    <button className='btn btn-sm btn-success' onClick={this.create}><i className='fa fa-plus' /> Crear inventario</button>\n                    : null\n                }\n              </div>\n            </div>\n            <div className='box-body'>\n              <Row>\n                <div className='col-md-12'>\n                  {\n                    !inventories.length && !loading ? 'Aún no se han creado inventarios.' : null\n                  }\n                  {\n                    inventories.map((inventory: any) => {\n                      return (\n                        <div className='inventory' key={inventory._id} id={`inventory-${inventory._id}`}>\n                          <Row>\n                            <div className='col-md-8 col-xs-8'>\n                              <h4 className='text-primary pointer' onClick={() => this.goToDetail(inventory._id)}>{inventory.name}</h4>\n                            </div>\n                            <div className='col-md-4 col-xs-4 text-right'>\n                              {this.labelStatus(inventory.status)}\n                            </div>\n                          </Row>\n                          <Row>\n                            <div className='col-lg-3 col-md-4 col-xs-12'>\n                              <div className='text-detail-user'>\n                                <div className={\"detail-info  text-muted\"}>\n                                  <i className='fa fa-fw fa-clock-o text-success' />Creado el {moment(inventory.createdAt).format('LLL')}<br />\n                                  {\n                                    inventory.createdBy ?\n                                      <React.Fragment><i className='fa fa-fw fa-user' />Por {inventory.createdBy.fullName}<br /></React.Fragment>\n                                      : null\n                                  }\n                                  {\n                                    inventory.finalizedAt ?\n                                      <React.Fragment>\n                                        <i className='fa fa-fw fa-clock-o text-danger' />Finalizado\n                                        el {moment(inventory.finalizedAt).format('LLL')}<br />\n                                        {\n                                          inventory.finalizedBy ? <React.Fragment><i className='fa fa-fw fa-user' />Por {inventory.finalizedBy.fullName}\n                                          </React.Fragment> : null\n                                        }\n                                      </React.Fragment>\n                                      : null\n                                  }\n                                </div>\n                              </div>\n                            </div>\n                            <div className='col-lg-7 col-md-8'>\n                              <div className='row right-border'>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.foundClass}`}>\n                                  <strong style={{ fontSize: '80%' }}>{inventorySettings.found}</strong>\n                                  <h2 style={{ marginTop: '10px' }}>{inventory.results.found}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.leftoverClass}`}>\n                                  <strong style={{ fontSize: '80%' }}>{inventorySettings.leftover}</strong>\n                                  <h2 style={{ marginTop: '10px' }}>{inventory.results.leftover}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.missingClass}`}>\n                                  <strong style={{ fontSize: '80%' }}>{inventorySettings.missing}</strong>\n                                  <h2 style={{ marginTop: '10px' }}>{inventory.results.missing}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 col-xs-3 text-center text-${inventorySettings.pendingClass} no-right-border-mobile`}>\n                                  <strong style={{ fontSize: '80%' }}>{inventorySettings.pending}</strong>\n                                  <h2 style={{ marginTop: '10px' }}>{inventory.results.pending}</h2>\n                                </div>\n                                <div className={`col-md-5th-1 text-center text-${inventorySettings.reportedClass} hidden-xs hidden-sm`}>\n                                  <strong style={{ fontSize: '80%' }}>{inventorySettings.reported}</strong>\n                                  <h2 style={{ marginTop: '10px' }}>{inventory.results.reported}</h2>\n                                </div>\n                              </div>\n                            </div>\n                            <div className='col-lg-2 col-md-12 text-right'>\n                              <div className='btn-group btn-group-sm'>\n                                {\n                                  inventory.status === 'inProcess' ?\n                                    <button type='button' className='btn btn-default' onClick={() => this.goToDetail(inventory._id)}>\n                                      <i className='fa fa-fw fa-area-chart' /> Ver Progreso\n                                    </button>\n                                    :\n                                    <button type='button' className='btn btn-default' onClick={() => this.goToDetail(inventory._id)}>\n                                      <i className='fa fa-fw fa-area-chart' /> Ver Reporte\n                                    </button>\n                                }\n                                <button type='button' className='btn btn-default dropdown-toggle' data-toggle='dropdown'>\n                                  <span className='caret' />\n                                  <span className='sr-only'>Toggle Dropdown</span>\n                                </button>\n                                <ul className='dropdown-menu pull-right' role='menu'>\n                                  <li>\n                                    <Link to={`/inventory/${inventory._id}/detail/`}>\n                                      {/* <a href=\"javascript:void(0);\" onClick={() => this.goToDetail(inventory._id, true)}> */}\n                                      <i className='fa fa-fw fa-table' />Ver Detalle\n                                      {/* </a> */}\n                                    </Link>\n                                  </li>\n                                  {\n                                    hasPermission(window.user, 'viewFilesInventory') && inventory.file && inventory.file.hasOwnProperty('url') ?\n                                      <li>\n                                        <a href={decodeURI(inventory.file.url)} download={inventory.file.name}>\n                                          <i className='fa fa-fw fa-download' />Descargar archivo cargado\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                  {\n                                    hasPermission(window.user, 'viewFilesInventory') && inventory.backup && inventory.backup.hasOwnProperty('url') ?\n                                      <li>\n                                        <a href={decodeURI(inventory.backup.url)} target='_blank' download={inventory.backup.name}>\n                                          <i className='fa fa-fw fa-download' />Descargar archivo de respaldo\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                  {\n                                    inventory.status === 'inProcess' && hasPermission(window.user, 'finishInventory') ?\n                                      <li>\n                                        <a href='javascript:void(0);' onClick={() => this.finishInventoryAction(inventory)}>\n                                          <i className='fa fa-fw fa-stop' />Finalizar\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                  {\n                                    inventory.status === 'inProcess' && hasPermission(window.user, 'deleteInventory') ?\n                                      <li>\n                                        <a href='javascript:void(0);' onClick={() => this.deleteInventoryAction(inventory)}>\n                                          <i className='fa fa-fw fa-close' />Eliminar\n                                        </a>\n                                      </li>\n                                      : null\n                                  }\n                                </ul>\n                              </div>\n                            </div>\n                          </Row>\n                        </div>\n                      );\n                    })\n                  }\n                </div>\n              </Row>\n            </div>\n            {\n              pagination.pages > 1 &&\n              <div className='box-footer'>\n                <div className='row'>\n                  <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                      <span className='react-bootstrap-table-pagination-total text-muted text-ellipsis'>\n                        &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 10 + 1} al {(pagination.page) * 10} de {pagination.count} registros.\n                            </span>\n                  </div>\n                  <div className='col-md-6'>\n                    <div className='text-right' style={{ marginRight: '15px' }}>\n                      <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                    </div>\n                  </div>\n                </div>\n              </div>\n            }\n            {\n              loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changePage(page: number): void {\n    this.props.getInventoriesAction(true, page);\n  }\n\n  private goToDetail(id: string, detail?: boolean): void {\n    const { history } = this.props;\n    history.push(`/inventory/${id}/${detail ? 'detail/' : ''}`);\n  }\n\n  private finishInventoryAction(inventory: any): void {\n    const { finishInventoryAction } = this.props;\n    // ask if you are sure that you are going to finish the inventory?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a finalizar \"${inventory.name}\".`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        finishInventoryAction(inventory._id);\n      }\n    });\n  }\n\n  private deleteInventoryAction(inventory: any): void {\n    const { deleteInventoryAction } = this.props;\n    // ask if you are sure that you are going to delete the inventory?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar \"${inventory.name}\".`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        deleteInventoryAction(inventory._id);\n      }\n    });\n  }\n\n  private labelStatus(option: string): React.ReactElement<IPropsType> {\n    if (option === 'finalized') {\n      return <span className='label label-success'><i className='fa fa-fw fa-check' /> Finalizado</span>;\n    } else if (option === 'inProcess') {\n      return <span className='label label-primary'><i className='fa fa-fw fa-spin fa-spinner' /> En progreso</span>;\n    } else {\n      return <span className='label label-warning'><i className='fa fa-fw fa-spin fa-spinner' /> Creando inventario...</span>;\n    }\n  }\n\n  private create(): void {\n    this.props.history.push('/inventory/create/');\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getInventoriesAction: (loading: boolean, page: number) => dispatch(getInventoriesAction(loading, page)),\n    finishInventoryAction: (id: string) => dispatch(finishInventoryAction(id)),\n    deleteInventoryAction: (id: string) => dispatch(deleteInventoryAction(id))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(InventoryListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport slugify from 'slugify';\nimport CarDetail from './CarDetail';\n\ninterface IPropsType {\n  venue: any;\n  index: number;\n\n  deleteVenue(venueName: string): void;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass VenueDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { venue, index } = this.props;\n    const warnings = venue.cars.filter((car: any) => car.hasWarnings).length;\n    return (\n      <div className='panel box box-default' style={{ borderTopWidth: '2px' }}>\n        <div className='box-header with-border' style={{ padding: '6px' }}>\n          <h4 className='box-title' style={{\n            fontSize: '15px',\n            display: 'block'\n          }}>\n            <a data-toggle='collapse'\n               data-parent='#accordion'\n               href={`#${slugify(venue.name.toLowerCase(), { remove: /[*+~.()'\"!:@]/g })}`}\n               aria-expanded='false'\n               className='collapsed'>\n              {index + 1} {venue.name} ({venue.cars.length} Unidades)\n            </a>\n            <i className='fa fa-minus-circle text-red pull-right pointer' onClick={() => this.props.deleteVenue(venue.name)} />\n            {\n              venue.warningNoExist ?\n                <span className='text-muted pull-right' style={{ marginLeft: '5px' }}>\n                  <i className='fa fa-warning' style={{ color: '#f2aa2e' }} /> Esta sucursal se creará.\n                </span> : null\n            }\n            {\n              warnings ?\n                <span className='text-muted pull-right' style={{ marginLeft: '5px' }}>\n                  <i className='fa fa-warning' style={{ color: '#f2aa2e' }} /> {warnings} posibles problemas.\n                </span> : null\n            }\n          </h4>\n        </div>\n        <div id={`${slugify(venue.name.toLowerCase(), { remove: /[*+~.()'\"!:@]/g })}`} className='panel-collapse collapse' aria-expanded='false'>\n          <div className='box-body no-padding'>\n            <table className='table table-striped'>\n              <thead>\n              <tr>\n                <th style={{ width: '15%' }}>VIN</th>\n                <th style={{ width: '10%' }}>PATENTE</th>\n                <th style={{ width: '15%' }}>MARCA</th>\n                <th>DENOMINACION</th>\n                <th style={{ width: '15%' }}>TIPO</th>\n              </tr>\n              </thead>\n              <tbody>\n              {\n                venue.cars.map((car: any, index: any) => {\n                  return (\n                    <CarDetail car={car} key={index} />\n                  );\n                })\n              }\n              </tbody>\n            </table>\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nexport default VenueDetail;\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {IInventoryLabel} from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {changeTempLabelAction, ILabelsState, LabelsReduxAction} from '../../actions/labels.actions';\nimport {updateTooltip} from '../../utils/common';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport {CarStatusType} from \"../Inventory/InventoryDetailView\";\n\ninterface IPropsType {\n  labels?: ILabelsState;\n  update?: boolean;\n  changeTempLabelAction: (label: IInventoryLabel, debounce?: number) => LabelsReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass LabelFormView extends React.Component<IPropsType, IStateType> {\n\n  private statusText: any = {\n    pending: 'Pendiente',\n    found: 'Encontrado',\n    leftover: 'Sobrante',\n    missing: 'Faltante',\n    reported: 'Reportado'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.filterAffected = this.filterAffected.bind(this);\n    this.filterSendTo = this.filterSendTo.bind(this);\n    this.getOptions = this.getOptions.bind(this);\n  }\n\n  public componentDidMount(): void {\n    updateTooltip();\n  }\n\n  public componentDidUpdate(): void {\n    updateTooltip();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n\n\n  render(): React.ReactElement<IPropsType> | null {\n    const {changeTempLabelAction} = this.props;\n    if (this.props.labels) {\n      const {tempLabel} = this.props.labels;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"name\"\n                className=\"form-control\"\n                maxLength={50}\n                defaultValue={tempLabel ? tempLabel.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => changeTempLabelAction({\n                    ...tempLabel,\n                    name: e.target.value.trim()\n                  }, 300)\n                }\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label htmlFor=\"states\" className=\"control-label\">Agregar opción en</label>\n              <BootstrapSelect\n                noneSelectedText=\"Seleccione\"\n                displayItems={5}\n                selectedText=\"estados seleccionados.\"\n                separator=\" - \"\n                options={this.getOptions()}\n                selected={tempLabel.affected}\n                onClick={this.filterAffected}\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label htmlFor=\"states\" className=\"control-label\">Enviar a</label>\n              <BootstrapSelect\n                noneSelectedText=\"Seleccione a donde\"\n                displayItems={5}\n                autoClouse={true}\n                selectedText=\"estados seleccionados.\"\n                separator=\" - \"\n                options={this.getOptions()}\n                selected={tempLabel.sendTo ? [tempLabel.sendTo] : []}\n                onClick={this.filterSendTo}\n              />\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group-switch\">\n              <BootstrapSwitch\n                checked={tempLabel.isExhibition}\n                color=\"blue\"\n                onChange={() => {\n                  this.props.changeTempLabelAction({\n                    ...tempLabel,\n                    isExhibition: !tempLabel.isExhibition\n                  });\n                }}/>\n              <label className=\"switch-label\">Unidad de la marca</label>\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group-switch\">\n              <BootstrapSwitch\n                checked={tempLabel.requireCustomText}\n                color=\"blue\"\n                onChange={() => {\n                  this.props.changeTempLabelAction({\n                    ...tempLabel,\n                    requireCustomText: !tempLabel.requireCustomText\n                  });\n                }}/>\n              <label className=\"switch-label\">Requerir datos adicionales</label>\n            </div>\n          </div>\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Descripción</label>\n              <textarea\n                name=\"description\"\n                className=\"form-control\"\n                defaultValue={tempLabel ? tempLabel.description : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLTextAreaElement>) => changeTempLabelAction({\n                    ...tempLabel,\n                    description: e.target.value.trim()\n                  }, 300)\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    } else {\n      return null;\n    }\n  }\n\n  private getOptions() {\n    const {inventorySettings} = this.props.labels!;\n    return Object\n      .keys(this.statusText)\n      .map((status: CarStatusType) => ({\n        value: status,\n        text: inventorySettings[status],\n        className: `label label-${inventorySettings[`${status}Class` as CarStatusType]}`\n      }));\n  }\n\n  private filterAffected(value: any): void  {\n    if (this.props.labels && this.props.changeTempLabelAction) {\n      const {tempLabel} = this.props.labels;\n      this.props.changeTempLabelAction({\n        ...tempLabel,\n        affected: tempLabel.affected.includes(value)\n          ? tempLabel.affected.filter((state) => state !== value)\n          : [value, ...tempLabel.affected]\n      });\n    }\n  }\n\n  private filterSendTo(value: any): void  {\n    if (this.props.labels && this.props.changeTempLabelAction) {\n      const {tempLabel} = this.props.labels;\n      this.props.changeTempLabelAction({\n        ...tempLabel,\n        sendTo: value\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { labels: ILabelsState }) => {\n  return {\n    labels: state.labels\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempLabelAction: (label: IInventoryLabel, debounce?: number) => dispatch(changeTempLabelAction(label, debounce))\n  };\n};\n\nexport default connect<{labels: ILabelsState}, {dispatch: LabelsReduxAction}, IPropsType>(mapStateToProps, mapDispatchToProps)(LabelFormView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport { IInventoryLabel } from '../../../../../../src/inventory/interfaces/inventoryLabel.interface';\nimport {\n  changeLabelAction,\n  changeTempLabelAction,\n  createLabelAction,\n  deleteLabelAction,\n  getLabelsAction,\n  ILabelsState,\n  LabelsReduxAction\n} from '../../actions/labels.actions';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport BootstrapSwitch from '../Utils/BootstrapSwitch';\nimport Paginator from '../Utils/Paginator';\nimport LabelFormView from './LabelFormView';\nimport { CarStatusType } from '../Inventory/InventoryDetailView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<LabelsReduxAction>;\n  labels: ILabelsState;\n\n  changeTempLabelAction(tempLabel: IInventoryLabel): LabelsReduxAction;\n  getLabelsAction(page: number): LabelsReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n  createLabelAction(label: IInventoryLabel): LabelsReduxAction;\n  changeLabelAction(label: IInventoryLabel, message?: boolean): LabelsReduxAction;\n  deleteLabelAction(id: string): LabelsReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass LabelsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de etiquetas';\n    this.addLabel = this.addLabel.bind(this);\n    this.processAddLabel = this.processAddLabel.bind(this);\n    this.editLabel = this.editLabel.bind(this);\n    this.processEditLabel = this.processEditLabel.bind(this);\n    this.deleteLabel = this.deleteLabel.bind(this);\n    this.changePage = this.changePage.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.labels;\n    this.props.getLabelsAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `label-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update && data.updatedBy !== window.user._id) {\n        const {pagination} = this.props.labels;\n        this.props.getLabelsAction(pagination.page);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.labels.pagination !== prevProps.labels.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.labels.source) {\n      this.props.labels.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, labels, pagination, inventorySettings} = this.props.labels;\n    return (\n      <AppContainer title=\"\" cMenu=\"2\" cSubMenu=\"2.2\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Etiquetas <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.addLabel}>Agregar</button>\n              </div>\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table  table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th className=\"middle\">Nombre</th>\n                    <th className=\"middle\" style={{width: '100px'}}>Agregar opción en</th>\n                    <th className=\"middle\" style={{width: '80px'}}>Envia a</th>\n                    <th className=\"middle-center\" style={{width: '80px'}}>Activo</th>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                    <th style={{width: '1%'}} className=\"width-10\"/>\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    labels.map((label) => {\n                      return (\n                        <tr\n                          key={label._id} id={`label-${label._id}`}\n                          className={`background-transition ${!label.active ? 'text-muted' : ''}`}\n                        >\n                          <td className=\"middle text-ellipsis\">\n                            <strong className='text-primary'>{label.name}</strong>\n                            <p\n                              className={\"text-muted text-sm\"}\n                              style={{marginBottom: \"0\"}}\n                            >{label.description}</p>\n                          </td>\n                          <td className=\"middle\" style={{lineHeight: 1.6}}>\n                            {\n                              label.affected.map((aff, key)=>(\n                                <React.Fragment key={key}>\n                                  <label\n                                    className={`label label-${inventorySettings[`${aff}Class` as CarStatusType]}`}\n                                  >\n                                    {inventorySettings[aff as CarStatusType]}\n                                  </label><br />\n                                  </React.Fragment>\n                              ))\n                            }\n                          </td>\n                          <td className=\"middle\">\n                            <label className={`label label-${inventorySettings[`${label.sendTo}Class` as CarStatusType]}`}>\n                              {inventorySettings[label.sendTo as CarStatusType]}\n                            </label>\n                          </td>\n                          <td className=\"middle-center\" style={{paddingTop: '15px'}}>\n                            <BootstrapSwitch\n                              checked={label.active}\n                              onChange={() => {\n                                this.props.changeLabelAction({\n                                  ...label,\n                                  active: !label.active\n                                });\n                              }}\n                            />\n                          </td>\n                          <td\n                            onClick={() => this.editLabel(label)}\n                            className=\"middle text-blue pointer\"\n                          >\n                            <i className=\"fa fa-pencil\"/>\n                          </td>\n                          <td\n                            onClick={() => this.deleteLabel(label)}\n                            className={'middle text-red pointer'}\n                          >\n                            <i className=\"fa fa-minus-circle\"/>\n                          </td>\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addLabel(): void {\n    this.props.changeTempLabelAction({\n      _id: '',\n      name: '',\n      description: '',\n      color: '',\n      affected: [],\n      sendTo: '',\n      requireCustomText: false,\n      isExhibition: false,\n      active: true\n    });\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Agregar Etiqueta',\n        <LabelFormView changeTempLabelAction={changeTempLabelAction}/>,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processAddLabel}>Grabar</button>\n        </React.Fragment>\n      );\n    }, 200);\n  }\n\n  private processAddLabel(): void {\n    const { tempLabel} = this.props.labels;\n    if (this.validateLabel(tempLabel, 'Agregar Etiqueta')) {\n      statusFooterButttonsModal(true);\n      this.props.createLabelAction(tempLabel);\n    }\n  }\n\n  private editLabel(tempLabel: IInventoryLabel): void {\n    this.props.changeTempLabelAction(tempLabel);\n    setTimeout(() => {\n      this.props.loadDataAction(\n        'Editar Etiqueta',\n        <LabelFormView changeTempLabelAction={changeTempLabelAction}/>,\n        <React.Fragment>\n          <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n          <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processEditLabel}>Editar</button>\n        </React.Fragment>\n      );\n    }, 200);\n\n  }\n\n  private processEditLabel(): void {\n    const { tempLabel} = this.props.labels;\n    if (this.validateLabel(tempLabel, 'Editar Etiqueta')) {\n      statusFooterButttonsModal(true);\n      this.props.changeLabelAction(tempLabel, true);\n    }\n  }\n\n  private deleteLabel(label: IInventoryLabel): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la etiqueta \"${label.name}\". Los inventarios marcados con esta etiqueta serán afectados y no se mostrara. `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.props.deleteLabelAction(label._id);\n      }\n    });\n  }\n\n  private validateLabel(label: IInventoryLabel, action: string): boolean {\n    if (!label.name || !label.name.trim().length) {\n      swal!(action, 'El nombres es requerido', 'error');\n      return false;\n    } else if (!label.affected || !label.affected.length) {\n      swal!(action, '\"Agregar opción en\" debe tener al menos 1 seleccionado.', 'error');\n      return false;\n    } else if (!label.sendTo || !label.sendTo.trim().length) {\n      swal!(action, 'Debe seleccionar donde se enviara', 'error');\n      return false;\n    }\n    return true;\n  }\n\n  private changePage(page: number): void {\n    // change the page\n    this.props.getLabelsAction(page);\n  }\n}\n\nconst mapStateToProps = (state: { labels: ILabelsState }) => {\n  return {\n    labels: state.labels\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempLabelAction: (tempLabel: IInventoryLabel) => dispatch(changeTempLabelAction(tempLabel)),\n    createLabelAction: (label: IInventoryLabel) => dispatch(createLabelAction(label)),\n    changeLabelAction: (label: IInventoryLabel, message?: boolean) => dispatch(changeLabelAction(label, message)),\n    deleteLabelAction: (id: string) => dispatch(deleteLabelAction(id)),\n    getLabelsAction: (page: number) => dispatch(getLabelsAction(page)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{labels: ILabelsState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(LabelsListView);\n","// import * as PropTypes from 'prop-types';\nimport * as React from 'react';\nimport {connect} from 'react-redux';\nimport {Dispatch} from 'redux';\nimport {IModalState, ModalReduxAction} from '../../actions/modal.actions';\nimport {IUsersState} from '../../actions/users.actions';\n\ninterface IPropsType {\n  dispatch?: Dispatch<ModalReduxAction>;\n  modal?: IModalState;\n  modalLarge?: boolean;\n  noPadding?: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  show: boolean;\n}\n\nclass ModalView extends React.Component<IPropsType, IStateType> {\n\n  // static propTypes = {\n  //   modal: PropTypes.object.isRequired,\n  //   dispatch: PropTypes.func.isRequired\n  // };\n\n  render() {\n    const {modal, modalLarge, noPadding} = this.props;\n    return (\n      <div className=\"modal fade\" role=\"dialog\" id=\"andesModal\" tabIndex={-1}>\n        <div className={`modal-dialog ${modalLarge ? 'modal-lg' : ''}`} role=\"document\">\n          <div className=\"modal-content\">\n            <div className=\"modal-header\">\n              <button type=\"button\" className=\"close\" data-dismiss=\"modal\" aria-label=\"Close\"><span aria-hidden=\"true\">&times;</span></button>\n              <h4 className=\"modal-title\">{modal ? modal.title : ''}</h4>\n            </div>\n            <div className={`modal-body ${noPadding?'no-padding':''}`}>\n              {modal ? modal.body : ''}\n            </div>\n            {\n              modal && modal.footer ?\n              <div className=\"modal-footer\">\n                {modal && modal.footer ? modal.footer : <button type=\"button\" className=\"btn btn-default\" data-dismiss=\"modal\">Cerrar</button>}\n              </div> : null\n            }\n          </div>\n        </div>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { modal: IModalState, users: IUsersState }) => {\n  return {\n    modal: state.modal,\n    users: state.users\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(ModalView);\n","import * as React from 'react';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport {connect} from 'react-redux';\nimport AppContainer from '../../container/AppContainer';\nimport ModalView from '../Modal/ModalView';\nimport {IPlanningState, PlanningReduxAction} from '../../actions/planning.action';\nimport {IWindow} from '../../interfaces/window';\nimport {ErrorInfo, RefObject} from 'react';\nimport * as Raven from 'raven-js';\nimport * as XLSX from 'xlsx';\nimport * as moment from 'moment';\nimport * as swal from 'sweetalert';\nimport slugify from 'slugify';\nimport ApiService from '../../utils/axios';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<PlanningReduxAction>;\n  planning: IPlanningState;\n}\n\ninterface IStateType {\n  error: Error | null;\n  carsByDate: any[];\n  canDrop: boolean;\n  sending: boolean;\n  loadingSettings: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass PlanningImportView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    sending: false,\n    carsByDate: [],\n    loadingSettings: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importar planicacion';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n  }\n\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.planning.source) {\n      this.props.planning.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, carsByDate, sending\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"4\" cSubMenu=\"4.2\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Importar planificación</h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  !carsByDate.length?\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}\n                      style={{marginRight: '5px'}}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                    :null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                carsByDate.length?\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        <label>Días que serán importardos</label>\n                        {\n                          carsByDate.map((carByDate: any) => (\n                            <div className=\"panel box box-default\" style={{borderTopWidth: '2px', marginBottom: '5px'}} key={carByDate.key}>\n                              <div className=\"box-header with-border\" style={{padding: '6px'}}>\n                                <h4 className=\"box-title\" style={{\n                                  fontSize: '15px',\n                                  display: 'block'\n                                }}>\n                                  <a data-toggle=\"collapse\"\n                                   data-parent=\"#accordion\"\n                                   href={`#${slugify(carByDate.key, {remove: /[*+~.()'\"!:@]/g})}`}\n                                   aria-expanded=\"false\"\n                                   className=\"collapsed\">\n                                  {`${moment(carByDate.key, 'YYYYMMDD').format('dddd, DD MMMM YYYY')} (${carByDate.cars.length} unidades)`}\n                                  </a>\n                                </h4>\n                              </div>\n                              <div id={`${slugify(carByDate.key, {remove: /[*+~.()'\"!:@]/g})}`} className=\"panel-collapse collapse\"\n                                   aria-expanded=\"false\">\n                                <div className=\"box-body no-padding\">\n                                  <table className=\"table table-striped\">\n                                    <thead>\n                                    <tr>\n                                      <th style={{width: '10%'}}>Nº Interno</th>\n                                      <th style={{width: '15%'}}>VIN</th>\n                                      <th style={{width: '5%'}}>PATENTE</th>\n                                      <th style={{width: '10%'}}>MARCA</th>\n                                      <th style={{width: '30%'}}>DENOMINACIÓN</th>\n                                      <th style={{width: '30%'}}>COLOR</th>\n                                    </tr>\n                                    </thead>\n                                    <tbody>\n                                    {\n                                      carByDate.cars.map((car: any) => (\n                                        <tr key={car.vin}>\n                                          <td>{car.NInterno}</td>\n                                          <td>{car.vin}</td>\n                                          <td>{car.patente}</td>\n                                          <td>{car.marca}</td>\n                                          <td>{car.denominacion}</td>\n                                          <td>{car.color}</td>\n                                        </tr>\n                                      ))\n                                    }\n                                    </tbody>\n                                  </table>\n                                </div>\n                              </div>\n                            </div>\n                          ))\n                        }\n                      </div>\n                    </div>\n                    <div className=\"col col-md-6\">\n                      <strong>Total de unidades:</strong> {carsByDate.reduce((total, x: any) => (total + x.cars.length), 0)}\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <button className=\"btn btn-sm btn-primary\" onClick={this.downloadTemplate}>\n                        <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                      </button>\n                      <button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile} style={{marginLeft: '5px'}}>\n                        <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                      </button>\n                    </div>\n                  </div>\n                  :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile} accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <div className=\"box-footer text-right\">\n              <button\n                className=\"btn btn-sm btn-default\"\n                onClick={() => this.props.history.push('/planning/')}\n              >\n                Cancelar\n              </button>\n              {carsByDate.length ? <button className=\"btn btn-sm btn-primary\" style={{marginLeft: '5px'}} onClick={this.sendCreate} disabled={sending}>\n                {\n                  sending ?\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-spin fa-spinner\"/> Importando...\n                    </React.Fragment>\n                    : 'Importar'\n                }\n              </button> : null}\n            </div>\n            {\n              loadingSettings || sending &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      NInterno: '',\n      vin: '',\n      marca: '',\n      patente: '',\n      denominacion: '',\n      color: '',\n      propiedad: '',\n      tipo: '',\n      fecha: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Autos');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_planning_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = workbook.Sheets.hasOwnProperty('Autos') ? XLSX.utils.sheet_to_json(workbook.Sheets.Autos) : [];\n        const carsByDate: any = {};\n        if (excelData.length >= 1) {\n          excelData.forEach((item: any, index: number) => {\n            const date = moment(workbook.Sheets.Autos[`I${index + 2}`].v);\n            if(date.isValid()){\n              const key: string = date.format('YYYYMMDD');\n              if (!carsByDate.hasOwnProperty(key)) {\n                carsByDate[key] = {\n                  key,\n                  cars: []\n                };\n              }\n              carsByDate[key].cars.push({\n                NInterno: item.NInterno,\n                vin: item.vin,\n                marca: item.marca,\n                patente: item.patente,\n                denominacion: item.denominacion,\n                color: item.color,\n                propiedad: item.propiedad,\n                tipo: item.tipo,\n                date\n              });\n            }\n          });\n          this.setState({\n            loadingSettings: false,\n            carsByDate: Object.keys(carsByDate)\n              .map((key) => ({key, ...carsByDate[key]}))\n              .sort((a, b) => {\n                if (a.key < b.key) return 1;\n                if (a.key > b.key) return -1;\n                return 0;\n              })\n              .reverse()\n          });\n        } else {\n          swal(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n            'error'\n          );\n          this.setState({\n            loadingSettings: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(): void {\n    const {carsByDate} = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .importPlanning({\n        carsByDate\n      })\n      .then((response: any) => {\n        const {message} = response.data;\n        setTimeout(() => {\n          swal('Envió planificación', message, 'success');\n        }, 200);\n        history.push('/planning/');\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((e) => {\n        console.log('e', e);\n        swal('Envió planificación', 'Se produjo un error al importar la planificación.', 'error');\n        this.setState({\n          sending: false\n        });\n      });\n\n  }\n\n}\n\nconst mapStateToProps = (state: { planning: IPlanningState }) => {\n  return {\n    planning: state.planning\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ planning: IPlanningState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanningImportView);\n","import * as React from \"react\";\nimport {RouteComponentProps} from \"react-router\";\nimport {Dispatch} from \"redux\";\nimport {connect} from \"react-redux\";\nimport AppContainer from \"../../container/AppContainer\";\nimport ModalView from \"../Modal/ModalView\";\nimport {getPlanningAction, IPlanningState, PlanningReduxAction} from \"../../actions/planning.action\";\nimport {IWindow} from \"../../interfaces/window\";\nimport {ErrorInfo} from \"react\";\nimport * as Raven from \"raven-js\";\nimport * as moment from \"moment\";\nimport Paginator from \"../Utils/Paginator\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\nimport { io } from \"socket.io-client\";\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<PlanningReduxAction>;\n  planning: IPlanningState;\n\n  getPlanningAction(page: number): PlanningReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass PlanningListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de planificación';\n    this.changePage = this.changePage.bind(this);\n    this.import = this.import.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.planning;\n    // set the title of the page\n    this.props.getPlanningAction(pagination.page);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {token: (window.user as any).token}\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', {room: `planning-list-${window.user.team._id}`});\n    });\n    this.socket.on('REFRESH', (): void => {\n        this.props.getPlanningAction(pagination.page);\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if(this.props.planning.pagination !== prevProps.planning.pagination){\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.planning.source) {\n      this.props.planning.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, plannings, pagination} = this.props.planning;\n    return (\n      <AppContainer title=\"\" cMenu=\"4\" cSubMenu=\"4.1\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Planificación <small>{pagination.count}</small></h3>\n              <div className=\"box-tools pull-right\">\n                <button className=\"btn btn-sm btn-success\" onClick={this.import}>Importar</button>\n              </div>\n            </div>\n            <div className=\"box-body\">\n              {\n                !loading && !plannings.length?\n                  <div className=\"row\">\n                    <div className=\"col-md-12\">\n                      <p>No se han encontrado resultados.</p>\n                    </div>\n                  </div>\n                  :null\n              }\n              {\n                plannings.length ?\n                  <table className=\"table\">\n                    <thead>\n                      <tr>\n                        <th>VIN</th>\n                        <th>Marca</th>\n                        <th>Denominación</th>\n                        <th>Color</th>\n                        <th>Fecha</th>\n                      </tr>\n                    </thead>\n                    <tbody>\n                      {\n                        plannings.map((item)=>(\n                          <tr key={item.car.vin}>\n                            <td>{item.car.vin}</td>\n                            <td>{item.car.brand}</td>\n                            <td>{item.car.denomination}</td>\n                            <td>{item.car.color}</td>\n                            <td>{moment(item.date).format(\"DD-MM-YYYY\")}</td>\n                          </tr>\n                        ))\n                      }\n                    </tbody>\n                  </table>\n                  : null\n              }\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n  private changePage(page: number): void {\n    // change the page\n    this.props.getPlanningAction(page);\n  }\n\n  private import(): void {\n    this.props.history.push('/planning/import/');\n  }\n}\n\nconst mapStateToProps = (state: { planning: IPlanningState }) => {\n  return {\n    planning: state.planning\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getPlanningAction: (page: number) => dispatch(getPlanningAction(page)),\n  };\n};\n\nexport default connect<{planning: IPlanningState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(PlanningListView);\n","import * as React from 'react';\nimport {connect} from 'react-redux';\nimport {\n  IBaseRegion\n} from '../../../../../../src/app/interfaces/region.interface';\nimport {\n  RegionReduxAction,\n  changeTempRegionAction,\n  IRegionsState\n} from '../../actions/regions.actions';\n\n\ninterface IPropsType {\n  regions?: IRegionsState;\n  update?: boolean;\n  changeTempRegionAction?: (carrier: IBaseRegion, delay?: boolean) => RegionReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass RegionsFormView extends React.Component<IPropsType, IStateType> {\n\n  render(): React.ReactElement<IPropsType> | null {\n    if (this.props.regions && this.props.changeTempRegionAction) {\n      const {tempRegion} = this.props.regions;\n      return (\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <div className=\"form-group\">\n              <label>Nombre</label>\n              <input\n                type=\"text\"\n                name=\"name\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempRegion ? tempRegion.name : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => this.props.changeTempRegionAction!({\n                    ...tempRegion,\n                    name: e.target.value.trim()\n                  })\n                }\n              />\n            </div>\n            <div className=\"form-group\">\n              <label>Código</label>\n              <input\n                type=\"text\"\n                name=\"code\"\n                className=\"form-control\"\n                maxLength={50}\n                value={tempRegion ? tempRegion.code : ''}\n                onChange={\n                  (e: React.ChangeEvent<HTMLInputElement>) => this.props.changeTempRegionAction!({\n                    ...tempRegion,\n                    code: e.target.value.trim()\n                  })\n                }\n              />\n            </div>\n          </div>\n        </div>\n      );\n    }\n    return null;\n  }\n}\n\nconst mapStateToProps = (state: { regions: IRegionsState }) => {\n  return {\n    regions: state.regions\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    changeTempRegionAction: (carrier: IBaseRegion, delay?: boolean) => dispatch(changeTempRegionAction(carrier, delay))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RegionsFormView);\n","import * as moment from 'moment';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport {ErrorInfo} from 'react';\nimport {connect} from 'react-redux';\nimport {RouteComponentProps} from 'react-router';\nimport {Dispatch} from 'redux';\nimport * as swal from 'sweetalert';\nimport {IBaseRegion, IRegion} from '../../../../../../src/app/interfaces/region.interface';\n\nimport {loadDataAction, ModalReduxAction} from '../../actions/modal.actions';\nimport AppContainer from '../../container/AppContainer';\nimport {IWindow} from '../../interfaces/window';\nimport {hasPermission} from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport RegionsFormView from './RegionsFormView';\nimport {\n  changeTempRegionAction,\n  createRegionAction,\n  deleteRegionAction,\n  getRegionsAction,\n  IRegionsState,\n  RegionReduxAction,\n  updateRegionAction\n} from \"../../actions/regions.actions\";\nimport TrackingBasePage from \"../Utils/TrackingBasePage\";\n\ninterface IPropsType extends RouteComponentProps<{ region: string }> {\n  dispatch: Dispatch<RegionReduxAction>;\n  regions: IRegionsState;\n\n  createRegionAction(): RegionReduxAction;\n  updateRegionAction(): RegionReduxAction;\n\n  deleteRegionAction(id: string): RegionReduxAction;\n  changeTempRegionAction(region: IBaseRegion, delay?: boolean): RegionReduxAction;\n  getRegionsAction(page: number): RegionReduxAction;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\ndeclare let window: IWindow;\n\nclass RegionsListView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado de regiones';\n    this.createRegion = this.createRegion.bind(this);\n    this.processCreateRegion = this.processCreateRegion.bind(this);\n    this.updateRegion = this.updateRegion.bind(this);\n    this.processUpdateRegion = this.processUpdateRegion.bind(this);\n    this.deleteRegion = this.deleteRegion.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const {pagination} = this.props.regions;\n    this.props.getRegionsAction(pagination.page);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.regions.source) {\n      this.props.regions.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {loading, regions, pagination} = this.props.regions;\n    return (\n      <AppContainer title=\"\" cMenu=\"10\" cSubMenu=\"10.9\" cAction=\"Listado\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\"><h3 className=\"box-title\">Regiones <small>{pagination.count}</small></h3>\n              {\n                hasPermission(window.user, 'addRegion') ?\n                  <div className=\"box-tools pull-right\">\n                    <button className=\"btn btn-sm btn-success\" onClick={this.createRegion}>Agregar</button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className=\"box-body no-padding\">\n              <table className=\"table table-andes table-striped\">\n                <thead>\n                  <tr>\n                    <th style={{width: '60%'}} className=\"middle\">Nombre</th>\n                    <th style={{width: '20%'}} className=\"middle hidden-xs\">Modificado</th>\n                    {\n                      hasPermission(window.user, 'changeRegion') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                    {\n                      hasPermission(window.user, 'deleteRegion') ?\n                        <th style={{width: '1%'}} className=\"width-10\"/> : null\n                    }\n                  </tr>\n                </thead>\n                <tbody>\n                  {\n                    !loading && !regions.length?\n                      <tr>\n                        <td\n                          colSpan={2 + (hasPermission(window.user, 'deleteRegion') ? 1 : 0) +( hasPermission(window.user, 'deleteRegion') ? 1 : 0)}\n                        >\n                          No se han creado regiones\n                        </td>\n                      </tr>\n                    :null\n                  }\n                  {\n                    regions.map((region: IRegion) => {\n                      return (\n                        <tr\n                          key={region._id}\n                          id={`region-${region._id}`}\n                          className={'background-transition'}\n                        >\n                          <td className=\"middle\">{region.name}</td>\n                          <td className=\"middle hidden-xs\">{moment(region.updatedAt).format('LLL')}</td>\n                          {\n                            hasPermission(window.user, 'changeRegion') ?\n                              <td\n                                className=\"middle text-blue pointer\"\n                                onClick={() => this.updateRegion(region)}\n                              >\n                                <i className=\"fa fa-pencil\"/>\n                              </td> : null\n                          }\n                          {\n                            hasPermission(window.user, 'deleteRegion') ?\n                              <td\n                                className={'middle text-red pointer'}\n                                onClick={() => this.deleteRegion(region)}\n                              ><i className=\"fa fa-minus-circle\"/></td> : null\n                          }\n                        </tr>\n                      );\n                    })\n                  }\n                </tbody>\n              </table>\n            </div>\n            {\n              pagination.pages > 1 &&\n                <div className=\"box-footer text-right\">\n                  <Paginator changePage={this.props.getRegionsAction} page={pagination.page} pages={pagination.pages} />\n                </div>\n            }\n            {\n              loading &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private createRegion(): void {\n    this.props.changeTempRegionAction({\n      _id: '',\n      name: '',\n      code: ''\n    });\n    this.props.loadDataAction(\n      'Agregar Region',\n      <RegionsFormView/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processCreateRegion}>Grabar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processCreateRegion(): void {\n    const {tempRegion} = this.props.regions;\n    if (!tempRegion.name || !tempRegion.name.trim()) {\n      swal('Agregar Region', 'El nombres es requerido', 'error');\n    } else {\n      this.props.createRegionAction();\n    }\n  }\n\n  private updateRegion(region: IRegion): void {\n    const {_id, name, code} = region;\n    this.props.changeTempRegionAction({_id, name, code});\n    this.props.loadDataAction(\n      'Editar Region',\n      <RegionsFormView update={true}/>,\n      <React.Fragment>\n        <button type=\"button\" className=\"btn btn-sm btn-default\" data-dismiss=\"modal\">Cancelar</button>\n        <button type=\"button\" className=\"btn btn-sm btn-primary\" onClick={this.processUpdateRegion}>Editar</button>\n      </React.Fragment>\n    );\n  }\n\n  private processUpdateRegion(): void {\n    const {tempRegion} = this.props.regions;\n    if (!tempRegion.name || !tempRegion.name.trim()) {\n      swal('Editar Region', 'El nombres es requerido', 'error');\n    } else {\n      this.props.updateRegionAction();\n    }\n  }\n\n  private deleteRegion(region: IRegion): void {\n     // ask if you are sure that you are going to delete the region?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar la región ${region.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRegionAction(region._id);\n      }\n    });\n  }\n}\n\nconst mapStateToProps = (state: { regions: IRegionsState }) => {\n  return {\n    regions: state.regions\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any ) => {\n  return {\n    dispatch,\n    getRegionsAction: (page: number) => dispatch(getRegionsAction(page)),\n    createRegionAction: () => dispatch(createRegionAction()),\n    updateRegionAction: () => dispatch(updateRegionAction()),\n    deleteRegionAction: (id: string) => dispatch(deleteRegionAction(id)),\n    changeTempRegionAction: (region: IBaseRegion, delay?: boolean) => dispatch(changeTempRegionAction(region, delay)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{regions: IRegionsState}, {dispatch: any}, IPropsType>(mapStateToProps, mapDispatchToProps)(RegionsListView);\n","import * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport ApiService from '../../utils/axios';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport RequestForm from './RequestForms/RequestForm';\nimport { AxiosError } from 'axios';\nimport * as swal from 'sweetalert';\nimport { getFormValues } from 'redux-form';\nimport { IWindow } from '../../interfaces/window';\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{}> {\n  router: any;\n}\n\ninterface IStateType {\n  error: Error | null;\n  created: boolean;\n}\n\nclass RequestCreateIntegration extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    created: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear solicitud';\n    this.handleSubmit = this.handleSubmit.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    $('body')\n      .removeClass('skin-purple')\n      .css({ 'background-color':'#ecf0f5' });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    let { location: { query } } = this.props.router;\n    query = Object.fromEntries(\n      Object.entries<string>(query).map(([key, value]) =>\n        // Modify key here\n        [`${key}`, decodeURIComponent(value)]\n      )\n    );\n    const {created} = this.state;\n    return (\n      <RequestForm\n        onSubmit={this.handleSubmit}\n        query={query}\n        created={created}\n        initialValues={{\n          conectaID: query['6154722a94bba10012230aae'] || query['conectaID'],\n          // sellerText: query.sellerText,\n          sellerText: `${window.user.firstName} ${window.user.lastName}`,\n          // channel:\n          venue: window.user.venue._id,\n          customerInformation: {\n            rut: query.hasOwnProperty('5bf2de35caf8ef7096105c22') ? query['5bf2de35caf8ef7096105c22'] : '',\n            name: query.hasOwnProperty('5bf2de35caf8ef7096105c21') ? query['5bf2de35caf8ef7096105c21'] : '',\n            email: query.hasOwnProperty('60b9232164adc90013a79b45') ? query['60b9232164adc90013a79b45'] : ''\n          },\n          advancePaymentInformation: {\n            method: '',\n            number: '',\n            files: []\n          },\n          cars: []\n        }}\n      />\n    );\n  }\n\n  private handleSubmit(values: any) {\n    this.api\n      .createRequest({\n        cars: values.cars,\n        channel: values.channel,\n        operationType: values.operationType,\n        venue: values.venue,\n        sellerText: values.sellerText,\n        advancePaymentInformation: values.advancePaymentInformation,\n        customerInformation: values.customerInformation,\n        deliveryVenue: values.deliveryVenue,\n        deliveryAddress: values.deliveryAddress,\n        deliveryDate: values.deliveryDate,\n        conectaID: values.conectaID,\n      })\n      .then((response) => {\n        const { data } = response.data;\n        this.setState({\n          created: true\n        });\n        swal!('Orden creada!', `La orden ha sido creada satisfactoriamente con el Nº${data.number}!`, 'success', {\n          button: false,\n          closeOnClickOutside: false,\n          closeOnEsc: false\n        });\n        window.scrollTo(0, 0);\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState, router: any }) => {\n  return {\n    inventories: state.inventories,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestCreateIntegration);\n","import { AxiosError, AxiosResponse, default as Axios } from 'axios';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport * as uuid from 'uuid';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IInventoryState } from '../../actions/inventory.actions';\nimport AppContainer from '../../container/AppContainer';\nimport ApiService from '../../utils/axios';\nimport AutoCompleteInput from '../Utils/AutoCompleteInput';\nimport BootstrapSelect from '../Utils/BootstrapSelect';\nimport MultiUploadFiles, { imageStatus } from '../Utils/MultiUploadFiles';\nimport ShowIf from '../Utils/ShowIf';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { IRequestSetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport { IOperationType } from '../../../../../../src/request/interfaces/operationType.interface';\nimport { parseReplicableURL } from '../../utils/common';\nimport { requestSettings } from './defaults';\n\n\ninterface IPropsType extends RouteComponentProps<{}> {\n}\n\ninterface INewCar {\n  brand: string;\n  brands: any[];\n  denomination: string;\n  denominations: any[];\n  material: string;\n  materials: any[];\n  color: string;\n  amount: number;\n  observation: string;\n  priority: boolean;\n  files: any[];\n  answers: any[];\n  equipment: boolean;\n  washed: boolean;\n  reason: string;\n}\n\ninterface IStateType {\n  newCar: INewCar;\n  cars: any[];\n  sellerText: string;\n  venue: string;\n  venues: any[];\n  reasons: IReason[];\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n  channel: string;\n  operationType: string;\n  fleet: boolean;\n  loading: boolean;\n  error: Error | null;\n}\n\nconst initialNewCar = {\n  brand: '',\n  brands: [],\n  denomination: '',\n  denominations: [],\n  material: '',\n  materials: [],\n  files: [],\n  answers: [],\n  color: '',\n  amount: 1,\n  observation: '',\n  reason: '',\n  priority: false,\n  equipment: false,\n  washed: false\n};\n\nclass RequestCreateView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    newCar: initialNewCar,\n    cars: [],\n    venue: '',\n    sellerText: '',\n    venues: [],\n    reasons: [],\n    channels: [],\n    requestSettings,\n    operationTypes: [],\n    operationType: '',\n    loading: false,\n    fleet: false,\n    channel: '',\n    error: null,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Crear solicitud';\n    this.cancel = this.cancel.bind(this);\n    this.addCar = this.addCar.bind(this);\n    this.deleteCar = this.deleteCar.bind(this);\n    this.searchReason = this.searchReason.bind(this);\n    this.createRequest = this.createRequest.bind(this);\n    this.loadBaseData = this.loadBaseData.bind(this);\n    this.changeNewCar = this.changeNewCar.bind(this);\n    this.changeVenue = this.changeVenue.bind(this);\n    this.changeNumberNewCar = this.changeNumberNewCar.bind(this);\n    this.changeBooleanNewCar = this.changeBooleanNewCar.bind(this);\n    this.changeFleet = this.changeFleet.bind(this);\n    this.search = debounce(500, this.search.bind(this));\n    this.api = new ApiService();\n  }\n\n  public componentWillMount(): void {\n    window.scrollTo(0, 0);\n    this.loadBaseData();\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    const $amount: any = $('#amount');\n    $amount.TouchSpin({\n      initval: 1,\n      min: 1,\n      max: 50\n    }).on('change', () => {\n      this.changeNumberNewCar('amount', parseInt($amount.val(), 10));\n    });\n    $('.bootstrap-touchspin')\n      .addClass('input-group-sm');\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { newCar, cars, requestSettings, loading, venues, reasons, channel, channels, operationTypes, operationType } = this.state;\n    const vehiclesView = this.props.location.pathname === '/requests/vehicles/create/';\n    const filesCompleted = newCar.files.filter((file: any) => file.status === imageStatus.complete);\n    const isUploadingFiles = newCar.files.length > 0 && filesCompleted.length < newCar.files.length;\n    const reasonSelected: IReason | undefined = (reasons as IReason[]).find((reason: IReason) => reason._id === newCar.reason);\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu={vehiclesView ? '3.2' : '3.1'} cAction='Crear solicitud'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Crear solicitud</h3>\n            </div>\n            <div className='box-body create-request'>\n              <div className='row'>\n                <div className='col-md-6 col-lg-6'>\n                  <h3>Agregar Unidades</h3>\n                  <div className='form-horizontal'>\n                    <div className='form-group'>\n                      <label htmlFor='marca' className='col-sm-3 control-label label-left'>Marca *</label>\n                      <div className='col-sm-9'>\n                        <AutoCompleteInput\n                          value={newCar.brand}\n                          inputClass={'input-sm'}\n                          items={newCar.brands}\n                          renderItem={(item, index) => (\n                            <div key={index} className='item'>\n                              {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                              <strong>{item.brand}</strong>\n                            </div>\n                          )}\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('brand', value);\n                            this.search(value, 'brands');\n                          }}\n                          onSelect={(item) => {\n                            this.setState({\n                              newCar: {\n                                ...this.state.newCar,\n                                brand: item.brand,\n                                brands: [],\n                                denomination: item.denomination,\n                                denominations: [],\n                                material: '',\n                                materials: []\n                              }\n                            });\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label htmlFor='modelo' className='col-sm-3 control-label label-left'>Modelo {\n                        requestSettings.materialRequired ? '*' : ''\n                      }</label>\n                      <div className='col-sm-9'>\n                        <AutoCompleteInput\n                          value={newCar.denomination}\n                          inputClass={'input-sm'}\n                          items={newCar.denominations}\n                          renderItem={(item, index) => (\n                            <div key={index} className='item'>\n                              {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                              <strong>{item.brand}</strong>\n                            </div>\n                          )}\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('denomination', value);\n                            this.search(value, 'denominations');\n                          }}\n                          onSelect={(item) => {\n                            this.setState({\n                              newCar: {\n                                ...this.state.newCar,\n                                brand: item.brand,\n                                brands: [],\n                                denomination: item.denomination,\n                                denominations: [],\n                                material: '',\n                                materials: []\n                              }\n                            });\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <ShowIf condition={requestSettings.material}>\n                      <div className='form-group'>\n                        <label htmlFor='material' className='col-sm-3 control-label label-left'>Material {\n                          requestSettings.materialRequired ? '*' : ''\n                        }</label>\n                        <div className='col-sm-9'>\n                          <AutoCompleteInput\n                            value={newCar.material}\n                            inputClass={'input-sm'}\n                            items={newCar.materials}\n                            renderItem={(item, index) => (\n                              <div key={index} className='item'>\n                                {item.material ? `${item.material} - ` : ''} {item.denomination} <br />\n                                <strong>{item.brand}</strong>\n                              </div>\n\n                            )}\n                            onChange={(e) => {\n                              const { value } = e.target;\n                              this.changeNewCar('material', value);\n                              this.search(value, 'materials');\n                            }}\n                            onSelect={(item) => {\n                              this.setState({\n                                newCar: {\n                                  ...this.state.newCar,\n                                  brand: item.brand,\n                                  brands: [],\n                                  denomination: item.denomination,\n                                  denominations: [],\n                                  material: '',\n                                  materials: []\n                                }\n                              });\n                            }}\n                          />\n                        </div>\n                      </div>\n                    </ShowIf>\n                    <div className='form-group'>\n                      <label htmlFor='color' className='col-sm-3 control-label label-left'>Color {\n                        requestSettings.colorRequired ? '*' : ''\n                      }</label>\n                      <div className='col-sm-9'>\n                        <input\n                          type='text'\n                          className='input-sm form-control'\n                          value={newCar.color}\n                          onChange={(e) => {\n                            this.changeNewCar('color', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Motivo *</label>\n                      <div className='col-sm-9'>\n                        <BootstrapSelect\n                          noneSelectedText='Seleccione'\n                          displayItems={1}\n                          sm={true}\n                          search={true}\n                          autoClouse={true}\n                          selectedText='motivos seleccionados.'\n                          selected={newCar.reason.length ? [newCar.reason] : []}\n                          allOption={false}\n                          options={reasons.map((reason: any) => ({\n                            value: reason._id,\n                            text: reason.name\n                          }))}\n                          onClick={(value: string) => {\n                            this.changeNewCar('reason', value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                    <ShowIf condition={!!(reasonSelected && reasonSelected.questions.length)}>\n                      {\n                        reasonSelected?.questions.map((question: any) => {\n                          const currentAnswer: any = newCar.answers.find((answer: any) => (answer.questionId === question._id));\n                          return (\n                            <div className='form-group' key={(question)._id}>\n                              <label\n                                htmlFor='color'\n                                className='col-sm-3 control-label label-left'\n                              >\n                                {question.name} {question.required ? '*' : ''}\n                              </label>\n                              <div className='col-sm-9'>\n                                {\n                                  question._id === '5bf2de35caf8ef7096105c23' ?\n                                    <select\n                                      className='form-control select-sm font-12'\n                                      value={currentAnswer ? currentAnswer.answer : ''}\n                                      onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                        this.changeNewCar('answers', (() => {\n                                          if (e.target.value) {\n                                            if (currentAnswer) {\n                                              return [...newCar.answers].map((answer: any) => {\n                                                if (question._id === answer.questionId) {\n                                                  answer.answer = e.target.value;\n                                                }\n                                                return answer;\n                                              });\n                                            }\n                                            return [...newCar.answers, {\n                                              questionId: question._id,\n                                              question: question.name,\n                                              answer: e.target.value\n                                            }];\n                                          }\n                                          return [...newCar.answers].filter((answer: any) => (question._id !== answer.questionId));\n                                        })());\n                                      }}\n                                    >\n                                      <option value=\"\" disabled={true}>Seleccione</option>\n                                      <option value=\"VPP+CREDITO\">VPP+CREDITO</option>\n                                      <option value=\"VPP\">VPP</option>\n                                      <option value=\"CREDITO\">CREDITO</option>\n                                      <option value=\"CONTADO\">CONTADO</option>\n                                      <option value=\"LEASING\">LEASING</option>\n                                    </select> :\n                                    <input\n                                      type='text'\n                                      className='input-sm form-control'\n                                      value={currentAnswer ? currentAnswer.answer : ''}\n                                      onChange={(e) => {\n                                        this.changeNewCar('answers', (() => {\n                                          if (e.target.value) {\n                                            if (currentAnswer) {\n                                              return [...newCar.answers].map((answer: any) => {\n                                                if (question._id === answer.questionId) {\n                                                  answer.answer = e.target.value;\n                                                }\n                                                return answer;\n                                              });\n                                            }\n                                            return [...newCar.answers, {\n                                              questionId: question._id,\n                                              question: question.name,\n                                              answer: e.target.value\n                                            }];\n                                          }\n                                          return [...newCar.answers].filter((answer: any) => (question._id !== answer.questionId));\n                                        })());\n                                      }}\n                                    />\n                                }\n                              </div>\n                            </div>\n                          );\n                        })\n                      }\n                    </ShowIf>\n                    <ShowIf condition={!!(reasonSelected && reasonSelected.file.active)}>\n                      <div className='form-group'>\n                        <label className='col-sm-3 control-label label-left'>Archivos *</label>\n                        <div className='col-sm-9'>\n                          <MultiUploadFiles\n                            url={'/api/v1/requests/upload-file/'}\n                            onChange={(files) => {\n                              this.changeNewCar('files', files);\n                            }}\n                            files={newCar.files}\n                          />\n                          <ShowIf condition={isUploadingFiles}>\n                            <p>\n                              Se están cargando sus archivos, llevamos {filesCompleted.length} de {newCar.files.length} <i\n                              className='fa fa-spinner fa-spin' />.\n                            </p>\n                          </ShowIf>\n                        </div>\n                      </div>\n                    </ShowIf>\n                    {\n                      /* <div className=\"form-group\">\n                        <label className=\"col-sm-3 control-label label-left\">Pre-entrega</label>\n                        <div className=\"col-sm-9\">\n                          <div className=\"checkbox\">\n                            <label>\n                              <input\n                                type=\"checkbox\"\n                                checked={newCar.washed}\n                                onChange={() => {\n                                  this.changeBooleanNewCar('washed', !newCar.washed);\n                                }}\n                              /> <i className=\"material-icons\">local_car_wash</i> Lavado\n                            </label>\n                          </div>\n                          <div className=\"checkbox\">\n                            <label>\n                              <input\n                                type=\"checkbox\"\n                                checked={newCar.equipment}\n                                onChange={() => {\n                                  this.changeBooleanNewCar('equipment', !newCar.equipment);\n                                }}\n                              /> <i className=\"material-icons\">build</i> Pre-entrega mecánica\n                            </label>\n                          </div>\n                        </div>\n                      </div> */\n                    }\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Cantidad</label>\n                      <div className='col-sm-4'>\n                        <input id='amount' type='text' className='form-control' />\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Prioridad</label>\n                      <div className='col-sm-6'>\n                        {\n                          newCar.priority ?\n                            <i\n                              className='fa fa-2x fa-star text-yellow pointer'\n                              style={{ marginTop: '5px', fontSize: '1.7em' }}\n                              onClick={() => this.changeBooleanNewCar('priority', false)}\n                            />\n                            :\n                            <i\n                              className='fa fa-2x fa-star-o text-yellow pointer'\n                              style={{ marginTop: '5px', fontSize: '1.7em' }}\n                              onClick={() => this.changeBooleanNewCar('priority', true)}\n                            />\n                        }\n                      </div>\n                    </div>\n                    <div className='form-group'>\n                      <label className='col-sm-3 control-label label-left'>Observación despacho</label>\n                      <div className='col-sm-9'>\n                        <textarea\n                          className='form-control input-sm'\n                          onChange={(e) => {\n                            const { value } = e.target;\n                            this.changeNewCar('observation', value);\n                          }}\n                          value={newCar.observation}\n                          style={{ resize: 'none' }}\n                          rows={4}\n                        />\n                      </div>\n                    </div>\n                    <div className='text-right'>\n                      <button\n                        className='btn btn-sm btn-primary'\n                        onClick={this.addCar}\n                        disabled={\n                          !(reasonSelected && reasonSelected.questions.length === newCar.answers.length) ||\n                          !newCar.brand.length ||\n                          (requestSettings.denomination && requestSettings.denominationRequired && !newCar.denomination.length) ||\n                          (requestSettings.material && requestSettings.materialRequired && !newCar.material.length) ||\n                          (requestSettings.color && requestSettings.colorRequired && !newCar.color.length) ||\n                          !newCar.reason ||\n                          isUploadingFiles\n                        }\n                      >\n                        Agregar\n                      </button>\n                    </div>\n                  </div>\n                </div>\n                <div className='col-md-6 col-lg-6' style={{ paddingLeft: '10px' }}>\n                  <div className='add-cars'>\n                    <div className='arrow'>\n                      <i className='fa fa-3x fa-caret-right' />\n                    </div>\n                    <div className='detail'>\n                      <h3>Solicitud</h3>\n                      <div className='form-horizontal'>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Destino</label>\n                          <div className='col-sm-9'>\n                            <BootstrapSelect\n                              noneSelectedText='Seleccione'\n                              displayItems={1}\n                              sm={true}\n                              search={true}\n                              autoClouse={true}\n                              selectedText='sucursales seleccionadas.'\n                              selected={this.state.venue.length ? [this.state.venue] : []}\n                              allOption={false}\n                              options={venues.map((venue: any) => ({\n                                value: venue._id,\n                                text: venue.name\n                              }))}\n                              onClick={(value: string) => {\n                                this.changeVenue(value);\n                              }}\n                            />\n                          </div>\n                        </div>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Vendedor</label>\n                          <div className='col-sm-9'>\n                            <input type='text' className='form-control input-sm' onChange={(e) => {\n                              this.setState({\n                                sellerText: e.target.value\n                              });\n                            }} />\n                          </div>\n                        </div>\n                        <div className='form-group'>\n                          <label className='col-sm-3 control-label label-left'>Canal *</label>\n                          <div className='col-sm-9'>\n                            <BootstrapSelect\n                              noneSelectedText='Seleccione'\n                              displayItems={1}\n                              sm={true}\n                              search={true}\n                              autoClouse={true}\n                              selected={channel.length ? [channel] : []}\n                              allOption={false}\n                              options={channels.map((channel: any) => ({\n                                value: channel._id,\n                                text: channel.name\n                              }))}\n                              onClick={(value: string) => {\n                                this.setState({\n                                  channel: value\n                                });\n                              }}\n                            />\n                          </div>\n                        </div>\n                        <ShowIf condition={!!operationTypes.length}>\n                          <div className='form-group'>\n                            <label className='col-sm-3 control-label label-left'>Tipo operación</label>\n                            <div className='col-sm-9'>\n                              <BootstrapSelect\n                                noneSelectedText='Seleccione'\n                                displayItems={1}\n                                sm={true}\n                                search={true}\n                                autoClouse={true}\n                                selected={operationType.length ? [operationType] : []}\n                                allOption={false}\n                                options={operationTypes.map((operationType: any) => ({\n                                  value: operationType._id,\n                                  text: operationType.name\n                                }))}\n                                onClick={(value: string) => {\n                                  this.setState({\n                                    operationType: value\n                                  });\n                                }}\n                              />\n                            </div>\n                          </div>\n                        </ShowIf>\n                      </div>\n                      {/* <div className=\"form-group-switch\">\n                        <label className=\"switch-label switch-label-left\">Estás solicitando flota</label>\n                        <BootstrapSwitch\n                          checked={fleet}\n                          color=\"blue\"\n                          onChange={this.changeFleet}\n                        />\n                      </div> */}\n                      <div className='create-detail'>\n                        <table className='table'>\n                          <tbody>\n                          {\n                            cars.map((car: any) => (\n                              <tr key={car.tid}>\n                                <td className='middle'>{`${car.denomination} ${car.material} ${car.brand}`}</td>\n                                <td className='middle'>{car.color}</td>\n                                <td className='middle'>{this.searchReason(car.reason)}</td>\n                                <td className='middle'>\n                                  <i className={`material-icons ${!car.washed ? 'text-gray' : ''}`}>local_car_wash</i>\n                                </td>\n                                <td className='middle'>\n                                  <i className={`material-icons ${!car.equipment ? 'text-gray' : ''}`}>build</i>\n                                </td>\n                                <td className='middle'>\n                                  {car.files.length ? <i className={`fa fa-paperclip`} /> : null}\n                                </td>\n                                <td className='middle text-muted' style={{ width: '140px' }}>\n                                  {\n                                    car.observation && car.observation.length ?\n                                      car.observation\n                                      : 'Sin observaciones'\n                                  }\n                                </td>\n                                <td\n                                  className='middle'\n                                  onClick={() => this.deleteCar(car)}\n                                >\n                                  <i className='fa fa-trash text-red pointer' />\n                                </td>\n                              </tr>\n                            ))\n                          }\n                          </tbody>\n                        </table>\n                      </div>\n                      <div className='text-right text-muted' style={{ padding: '2px' }}>\n                        {cars.length} unidades\n                      </div>\n                    </div>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div className='box-footer text-right'>\n              <button className='btn btn-sm btn-default' onClick={this.cancel}>Cancelar</button>\n              <button\n                className='btn btn-sm btn-primary'\n                style={{ marginLeft: '5px' }}\n                onClick={this.createRequest}\n              >\n                Crear\n              </button>\n            </div>\n            {\n              loading ?\n                <div className='overlay'>\n                  <i className='fa fa-spinner fa-spin text-purple' />\n                </div> : null\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private addCar(): void {\n    const { newCar, reasons } = this.state;\n    const reasonSelected: IReason | undefined = (reasons as IReason[]).find((reason: IReason) => reason._id === newCar.reason);\n    if (reasonSelected?.file.required && !newCar.files.length) {\n      swal!('Solicitud', `Se requiere que subas un archivo para este vehículo.`, 'error');\n    } else {\n      const $amount: any = $('#amount');\n      const cars = Array(newCar.amount).fill({\n        brand: newCar.brand,\n        denomination: newCar.denomination,\n        files: newCar.files,\n        answers: newCar.answers,\n        material: newCar.material,\n        color: newCar.color,\n        observation: newCar.observation,\n        priority: newCar.priority,\n        equipment: newCar.equipment,\n        reason: newCar.reason,\n        washed: newCar.washed\n      });\n      this.setState({\n        cars: [...this.state.cars, ...cars.map((car) => {\n          const tid = uuid.v4();\n          return {\n            ...car,\n            tid\n          };\n        })],\n        newCar: initialNewCar\n      }, () => {\n        $amount.val(1);\n      });\n    }\n  }\n\n  private searchReason(id: string) {\n    const { reasons } = this.state;\n    const reason: any = reasons.find((r: any) => r._id === id);\n    if (reason) {\n      return reason.name;\n    }\n    return '';\n  }\n\n  private deleteCar(dcar: any): void {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar ${dcar.denomination} ${dcar.material} ${dcar.brand} (${dcar.color})`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete: any) => {\n      if (willDelete) {\n        this.setState({\n          cars: this.state.cars.filter((car: any) => car.tid !== dcar.tid)\n        });\n      }\n    });\n  }\n\n  private changeNewCar(field: keyof INewCar, value: any) {\n    const extra: any = {};\n    if (field === 'reason') {\n      extra.answers = [];\n    }\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        ...extra,\n        [field]: value\n      }\n    });\n  }\n\n  private changeNumberNewCar(field: 'amount', value: number) {\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        [field]: value\n      }\n    });\n  }\n\n  private changeBooleanNewCar(field: 'priority' | 'equipment' | 'washed', value: boolean) {\n    this.setState({\n      newCar: {\n        ...this.state.newCar,\n        [field]: value\n      }\n    });\n  }\n\n  private changeVenue(venue: string) {\n    this.setState({\n      venue\n    });\n  }\n\n  private changeFleet() {\n    const { fleet } = this.state;\n    this.setState({\n      fleet: !fleet\n    });\n  }\n\n  private loadBaseData() {\n    this.setState({ loading: true });\n    Axios\n      .all([\n        this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true, filted: true }),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings(),\n        this.api.getOperationTypes({ page: 1, pageSize: 200 })\n      ])\n      .then(Axios.spread((venues, reasons, channels, teamSettings, operationTypes) => {\n        this.setState({\n          venues: venues.data.results,\n          reasons: reasons.data.results,\n          channels: channels.data.results,\n          requestSettings: teamSettings.data.request,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n      }))\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private search(text: string, base: 'denominations' | 'brands' | 'materials'): void {\n    this.api\n      .searchCar(text)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          newCar: {\n            ...this.state.newCar,\n            [base]: response.data.cars\n          }\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private createRequest() {\n    const vehiclesView = this.props.location.pathname === parseReplicableURL('/requests/vehicles/create/');\n    const { cars, channel, venue, sellerText, operationType } = this.state;\n    if (!cars.length) {\n      swal!('Solicitud', 'No se han agregado unidades para crear la solicitud.', 'error');\n    } else if (!venue.length) {\n      swal!('Solicitud', 'No se ha seleccionado destino para crear la solicitud.', 'error');\n    } else if (!channel.length) {\n      swal!('Solicitud', 'No se ha seleccionado canal para crear la solicitud.', 'error');\n    } else {\n      this.api\n        .createRequest({\n          cars,\n          channel,\n          operationType,\n          venue,\n          sellerText\n        })\n        .then(() => {\n          swal!('Solicitud', 'Se ha creado satisfactoriamente.', 'success').then(() => {\n            this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n          });\n        })\n        .catch((err: AxiosError): void => {\n          this.api.errorHandler(err);\n        });\n    }\n  }\n\n  private cancel(): void {\n    const vehiclesView = this.props.location.pathname === '/requests/vehicles/create/';\n    this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n  }\n}\n\nconst mapStateToProps = (state: { inventories: IInventoryState }) => {\n  return {\n    inventories: state.inventories\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestCreateView);\n","import { AxiosError, AxiosResponse } from 'axios';\nimport * as moment from 'moment-timezone';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  createRequestItemActionInDetail,\n  deleteRequestItemActionInDetail,\n  deleteRequestThunkAction,\n  getRequestThunkAction,\n  updateRequestItemActionInDetail\n} from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { disabledTView, goToSection, hasPermission, parseReplicableURL } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport RequestItem from './RequestItem';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport ShowIf from '../../Utils/ShowIf';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  router: any;\n  requests: IRequestsState;\n  getRequestAction: (id: string) => void;\n  createRequestItemActionInDetail: (item: IRequestItem) => void;\n  updateRequestItemActionInDetail: (item: IRequestItem) => void;\n  deleteRequestItemActionInDetail: (item: IRequestItem) => void;\n  deleteRequestThunkAction: (id: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n  car: Partial<ICar & { reason: string }>;\n}\n\ndeclare let window: IWindow;\n\nclass RequestDetailView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly api: ApiService;\n  readonly state = {\n    error: null,\n    recommends: [],\n    car: {\n      brand: '',\n      denomination: '',\n      material: '',\n      color: '',\n      reason: ''\n    }\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Detalle Solicitud';\n    this.search = debounce(500, this.search.bind(this));\n    this.api = new ApiService();\n    this.deleteRequest = this.deleteRequest.bind(this);\n    this.createItem = this.createItem.bind(this);\n  }\n\n  componentDidMount() {\n    super.componentDidMount();\n    // const { location: { query: item } } = this.props.router;\n    // if(item.length > 0) {\n    //   goToSection(`#request-item-${item}`);\n    // }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { request, loading, reasons, requestSettings } = this.props.requests;\n    const { recommends, car } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest') || window.user.isAdmin;\n    const vehiclesView = this.props.location.pathname.includes('requests/vehicles');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu={vehiclesView ? '3.2' : '3.1'} cAction={'Detalle solicitud'}>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Detalle solicitud #{request?.number}</h3>\n              {\n                hasPermission(window.user, 'deleteRequest') ?\n                  <div className='pull-right box-tools'>\n                    <button\n                      className='btn btn-sm btn-danger'\n                      onClick={this.deleteRequest}\n                    >\n                      <i className='fa fa-fw fa-trash' /> Eliminar solicitud\n                    </button>\n                  </div>\n                  : null\n              }\n            </div>\n            <div className='box-body request-detail no-padding table-responsive'>\n              {\n                Object.keys(request).length ?\n                  <React.Fragment>\n                    <div className={'bg-blue'} style={{ padding: '5px', minWidth: '900px' }}>\n                      <table className='table table-xs bg-blue' style={{ minWidth: '900px' }}>\n                        <tbody>\n                        <tr>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Vendedor</span><br />\n                            <strong><i className='fa fa-fw fa-user-o' /> {request.createdBy?.firstName} {request.createdBy?.lastName}</strong>\n                          </td>\n                          {/*<td style={{ borderTop: '0' }}>*/}\n                          {/*  <span style={{ paddingLeft: '17px' }}> Vendedor</span><br />*/}\n                          {/*  <strong><i className='fa fa-fw fa-handshake' /> {request.sellerText?.length ? request.sellerText : '-'}</strong>*/}\n                          {/*</td>*/}\n                          <td style={{ borderTop: '0' }}>\n                            Canal<br />\n                            <strong>{request.channel?.name}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            ID Cotización<br />\n                            <strong>{request.conectaID}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Destino</span><br />\n                            <strong><i className='fa fa-fw fa-building-o' /> {request.destination?.name}</strong>\n                          </td>\n                          <td style={{ width: '30%', borderTop: '0' }}>\n                            Dirección<br />\n                            <strong>{request?.deliveryAddress}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Creada</span><br />\n                            <strong><i className='fa fa-fw fa-calendar-o' /> {moment(request.createdAt).format('DD-MM-YYYY')}</strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}> Entrega esperada</span><br />\n                            <strong><i\n                              className='fa fa-fw fa-calendar-check-o' /> {request.deliveryDate ? moment(request.deliveryDate).format('DD-MM-YYYY') : '-'}\n                            </strong>\n                          </td>\n                        </tr>\n                        </tbody>\n                      </table>\n                    </div>\n                    <div style={{ padding: '5px', backgroundColor: '#f9f9f9', minWidth: '900px' }}>\n                      <table className='table table-xs text-black' style={{ minWidth: '900px', backgroundColor: '#f9f9f9' }}>\n                        <tbody>\n                        <tr>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Cliente</span><br />\n                            <strong><i className='fa fa-fw fa-address-book-o' /> {request.customerInformation?.name} </strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            Rut Cliente<br />\n                            <strong>{request.customerInformation?.rut} </strong>\n                          </td>\n                          <td style={{ borderTop: '0' }}>\n                            <span style={{ paddingLeft: '17px' }}>Correo Cliente</span><br />\n                            <strong><i className='fa fa-fw fa-envelope-o' /> {\n                              request.customerInformation?.email ?\n                                <a href={`mailto:${request.customerInformation.email}`}>{request.customerInformation.email}</a> : '-'\n                            } </strong>\n                          </td>\n                          <td style={{ width: '40%', borderTop: '0' }} />\n                        </tr>\n                        </tbody>\n                      </table>\n                    </div>\n                    <table className='table table-xs table-striped table-hover' style={{ minWidth: '900px' }}>\n                      <thead>\n                      <tr>\n                        {/*<ShowIf condition={requestSettings.priority}>*/}\n                          <th className='middle' style={{ width: '28px' }} />\n                        {/*</ShowIf>*/}\n                        {/*<th className='middle-center' style={{ width: '25px' }}>#</th>*/}\n                        {/*<th className='middle' style={{ width: '10px' }}>Propiedad</th>*/}\n                        <th className='middle' style={{ width: '80px' }}>Solicitud</th>\n                        <th className='middle' style={{ width: '200px' }}>VIN</th>\n                        <ShowIf\n                          condition={\n                            !['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                            requestSettings.entry\n                          }\n                        >\n                          <th className='middle' style={{ width: '60px' }}>Partida</th>\n                        </ShowIf>\n                        <ShowIf\n                          condition={\n                            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                            requestSettings.material\n                          }\n                        >\n                          <th className='middle' style={{ width: '100px' }}>Material</th>\n                        </ShowIf>\n\n                        <ShowIf condition={requestSettings.brand}>\n                          <th className='middle' style={{ width: '100px' }}>Marca</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.denomination}>\n                          <th className='middle' style={{ maxWidth: '300px' }}>Modelo</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.color}>\n                          <th className='middle'  style={{ maxWidth: '300px' }}>Color</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.ticket}>\n                          <th\n                            className='middle-center pointer'\n                            style={{ minWidth: '40px', maxWidth: '40px' }}\n                          >\n                            Ticket\n                          </th>\n                        </ShowIf>\n                        <ShowIf\n                          condition={\n                            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                            requestSettings.internalNumber\n                          }\n                        >\n                          <th className='middle' style={{ width: '80px' }}>CDO</th>\n                        </ShowIf>\n                        <ShowIf condition={false && requestSettings.reason}>\n                          <th className='middle' style={{ minWidth: '100px' }}>Motivo</th>\n                        </ShowIf>\n                        <th className='middle-center' style={{ width: '40px' }}></th>\n                        <th className='middle' style={{ width: '20px' }}></th>\n                        {\n                          hasPermission(window.user, 'deleteRequest') ?\n                            <th className='middle' style={{ width: '30px' }} />\n                            : null\n                        }\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        request!.items!.map((item, index) => (\n                          <RequestItem\n                            history={this.props.history}\n                            key={item._id}\n                            index={index}\n                            request={request}\n                            item={item}\n                          />\n                        ))\n                      }\n                      </tbody>\n                    </table>\n                    {\n                      canChangeRequest && disabledTView ?\n                        <div className='row' style={{ minWidth: '900px' }}>\n                          <div className='col-md-10 col-md-offset-2' style={{ paddingRight: '5px' }}>\n                            <div className='container-table-add-car' style={{ padding: '5px', marginTop: '20px', marginBottom: '20px' }}>\n                              <table className='table table-xs'>\n                                <thead>\n                                <tr>\n                                  <ShowIf condition={requestSettings.brand}>\n                                    <th>Marca</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.denomination}>\n                                    <th>Modelo</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.material}>\n                                    <th>Material</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.color}>\n                                    <th>Color</th>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.reason}>\n                                    <th style={{ width: '100px' }}>Motivo</th>\n                                  </ShowIf>\n                                  <th style={{ width: '100px' }} />\n                                </tr>\n                                </thead>\n                                <tbody>\n                                <tr>\n                                  <ShowIf condition={requestSettings.brand}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.brand}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.brand}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.denomination}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.denomination}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.denomination}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              denomination: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.material}>\n                                    <td>\n                                      <AutoCompleteInput\n                                        value={car.material}\n                                        inputClass={'input-sm'}\n                                        items={recommends}\n                                        renderItem={(car, index) => (\n                                          <div key={index} className='item'>\n                                            {car.denomination} <br />\n                                            <strong>{car.brand}</strong>\n                                          </div>\n                                        )}\n                                        onChange={(e) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              material: value\n                                            }\n                                          });\n                                          this.search(value);\n                                        }}\n                                        onSelect={(car: any) => {\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              brand: car.brand,\n                                              denomination: car.denomination,\n                                              material: car.material ?? ''\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.color}>\n                                    <td>\n                                      <input\n                                        type='text'\n                                        className='form-control input-sm'\n                                        value={this.state.car.color}\n                                        onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              color: value\n                                            }\n                                          });\n                                        }}\n                                      />\n                                    </td>\n                                  </ShowIf>\n                                  <ShowIf condition={requestSettings.reason}>\n                                    <td>\n                                      <select\n                                        className='form-control select-sm font-12' value={this.state.car.reason}\n                                        onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                          const { value } = e.target;\n                                          this.setState({\n                                            car: {\n                                              ...this.state.car,\n                                              reason: value\n                                            }\n                                          });\n                                        }}\n                                      >\n                                        <option value='' disabled={true}>-</option>\n                                        {\n                                          reasons.map((reason) => (\n                                            <option key={reason._id} value={reason._id}>{reason.name}</option>\n                                          ))\n                                        }\n                                      </select>\n                                    </td>\n                                  </ShowIf>\n                                  <td className='text-right'>\n                                    <button\n                                      className='btn btn-sm btn-block btn-success'\n                                      onClick={this.createItem}\n                                      disabled={!this.state.car.brand || !this.state.car.color || !this.state.car.denomination || !this.state.car.reason}\n                                    >\n                                      <i className='fa fa-fw fa-plus' />Agregar vehículo\n                                    </button>\n                                  </td>\n                                </tr>\n                                </tbody>\n                              </table>\n                            </div>\n                          </div>\n                        </div>\n                        : null\n                    }\n                  </React.Fragment>\n                  : null\n              }\n            </div>\n            <div className='box-footer text-right'>\n              <button className='btn btn-sm btn-default' onClick={() => {\n                this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n              }}>Cancelar\n              </button>\n            </div>\n            {\n              !Object.keys(request).length && loading &&\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            }\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  public componentWillMount(): void {\n    const { id } = this.props.match.params;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestAction(id);\n\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-detail-${window.user.team._id}` });\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        this.props.updateRequestItemActionInDetail(data.item);\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-aqua-active');\n        }\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-red-active');\n        }\n        setTimeout(() => {\n          this.props.deleteRequestItemActionInDetail(data.item);\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST', (data: any): void => {\n      if (data.idRequest === id) {\n        const vehiclesView = this.props.location.pathname.includes('requests/vehicles');\n        this.props.history.push(parseReplicableURL(vehiclesView ? '/requests/vehicles/' : '/requests/'));\n      }\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      if (data.idRequest === id) {\n        this.props.createRequestItemActionInDetail(data.item);\n        const $item = $(`#request-item-${data.item._id}`);\n        if ($item) {\n          $item.addClass('bg-green-active');\n        }\n        setTimeout(() => {\n          $item.removeClass('bg-green-active');\n        }, 300);\n      }\n    });\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requests.source) {\n      this.props.requests.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  private search(text: string): void {\n    this.api\n      .searchCar(text)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          recommends: response.data.cars\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private createItem() {\n    const { id } = this.props.match.params;\n    const { car } = this.state;\n    this.api\n      .createRequestItem(id, car)\n      .then((response: AxiosResponse): void => {\n        this.setState({\n          car: {\n            brand: '',\n            denomination: '',\n            material: '',\n            color: '',\n            reason: ''\n          }\n        });\n      })\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n\n  private deleteRequest() {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar esta solicitud.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        const { id } = this.props.match.params;\n        this.props.deleteRequestThunkAction(id);\n      }\n    });\n  }\n\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState, router: any  }) => {\n  return {\n    requests: state.requests,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    createRequestItemActionInDetail: (item: IRequestItem) => dispatch(createRequestItemActionInDetail(item)),\n    updateRequestItemActionInDetail: (item: IRequestItem) => dispatch(updateRequestItemActionInDetail(item)),\n    deleteRequestItemActionInDetail: (item: IRequestItem) => dispatch(deleteRequestItemActionInDetail(item)),\n    deleteRequestThunkAction: (id: string) => dispatch(deleteRequestThunkAction(id)),\n    getRequestAction: (id: string) => dispatch(getRequestThunkAction(id))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestDetailView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport * as swal from 'sweetalert';\nimport { debounce } from 'throttle-debounce';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequest } from '../../../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { deleteRequestItemThunkAction, deleteRequestThunkAction, updateRequestItemInDetailThunkAction } from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { goToSection, hasPermission } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport AutoCompleteVinInput from '../../Utils/AutoCompleteVinInput';\nimport ShowIf from '../../Utils/ShowIf';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport { Subject } from 'rxjs/internal/Subject';\nimport RequestStatusDislay from '../StatusComponents/RequestStatusDislay';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  router: any;\n  requests: IRequestsState;\n  request: IRequest;\n  item: IRequestItem;\n  index: any;\n  updateRequestItemInDetailThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => void;\n  deleteRequestItemThunkAction: (item: IRequestItem) => void;\n  deleteRequestThunkAction: (idRequest: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n  VINRecommends: any[];\n}\n\ndeclare let window: IWindow;\n\nclass RequestItem extends React.Component<IPropsType, IStateType> {\n  readonly api: ApiService;\n  readonly $subjectRecommends = new Subject<any>();\n  readonly $subjectVINRecommends = new Subject<any>();\n\n  readonly state = {\n    error: null,\n    recommends: [],\n    VINRecommends: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.search = debounce(500, this.search.bind(this));\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.api = new ApiService();\n    this.$subjectRecommends.pipe(\n      debounceTime(300),\n      switchMap((text: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-car/?search=${text}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        recommends: response.response.cars\n      });\n    });\n    this.$subjectVINRecommends.pipe(\n      debounceTime(300),\n      switchMap((vin: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-vin/?vin=${vin}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        VINRecommends: response.response.data\n      });\n    });\n  }\n\n  componentDidMount() {\n    const { location: { query } } = this.props.router;\n    if (query?.item?.length > 0) {\n      const key = `request-item-${query.item}`;\n      const element = document.getElementById(key);\n      if(element){\n        element.style.backgroundColor = '#efefef';\n        // element?.classList.add('bg-gray-light');\n        element?.classList.add('text-black');\n        goToSection(`#${key}`);\n      } else {\n        console.log(`No se encontro el elemento ${key}`)\n      }\n    }\n    // console.log(query);\n    // `request-item-${item}`\n    // window.scrollTo(0, 0);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item, index, request } = this.props;\n    const { requestItemStatus, reasons, requestSettings } = this.props.requests;\n    const { recommends } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest') || window.user.isAdmin;\n    return (\n      <tr id={`request-item-${item._id}`} className={'background-transition'}>\n        {/*<ShowIf condition={requestSettings.priority}>*/}\n          <td\n            className={`middle-center ${canChangeRequest ? 'pointer' : ''}`}\n            onClick={canChangeRequest ? () => {\n              this.props.updateRequestItemInDetailThunkAction({\n                item: {\n                  ...item,\n                  priority: !item.priority\n                },\n                debounce: false\n              });\n            } : undefined}\n          >\n            {item.priority ? <i className='fa fa-star text-yellow' /> : <i className='fa fa-star text-gray' />}\n          </td>\n        {/*</ShowIf>*/}\n        {/*<td className=\"middle-center\"><strong>{item.order}</strong></td>*/}\n        <td className=\"middle\" style={{width: '120px'}}>\n          <RequestStatusDislay requestItem={item} showNumber={true} />\n         </td>\n        {\n          canChangeRequest ?\n           <td\n              className='middle'\n              style={{ paddingRight: !item.car.vin?.length ? '29px' : undefined }}>\n             <div className='flex'>\n              <AutoCompleteVinInput\n                  history={this.props.history}\n                  defaultValue={item.car.vin}\n                  item={item}\n                  inputClass={'input-sm'}\n                  renderItem={(car, index) => (\n                    <div key={index} className='item'>\n                      {car.vin ? `${car.vin} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                />\n               </div>\n            </td> :\n            <td className=\"middle\">{item.car.vin}</td>\n        }\n         <ShowIf condition={\n           !['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n           requestSettings.entry}\n         >\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input\n                  type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car?.entry}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          entry: value\n                        }\n                      },\n                      debounce: true\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle-center\">{item.car?.entry}</td>\n          }\n        </ShowIf>\n        <ShowIf\n          condition={\n            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n            requestSettings.material\n          }\n        >\n          {\n            // canChangeRequest && !requestSettings.materialReadOnly ?\n            canChangeRequest  ?\n              <td className='middle'>\n                <AutoCompleteInput\n                  value={item.car.material}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className='item'>\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          material: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className='middle'><strong>{item.car.material}</strong></td>\n          }\n        </ShowIf>\n        {/*<td className=\"middle\">{item.car.property ? item.car.property : '-'}</td>*/}\n        <ShowIf condition={requestSettings.brand}>\n          {\n            // canChangeRequest && !requestSettings.brandReadOnly ?\n            canChangeRequest?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.brand}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className=\"middle\"><strong>{item.car.brand}</strong></td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.denomination}>\n          {\n            // canChangeRequest && !requestSettings.denominationReadOnly ?\n            canChangeRequest ?\n              <td className=\"middle\">\n                <AutoCompleteInput\n                  value={item.car.denomination}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className=\"item\">\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          denomination: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> : <td className=\"middle text-muted\"><strong>{item.car.denomination}</strong></td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.color}>\n          {\n            // canChangeRequest && !requestSettings.colorReadOnly ?\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.color}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          color: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className='middle text-muted'>\n                <ShowIf condition={!!item.car?.color}>\n                  <strong className='text-primary'>{item.car?.color}</strong><br />\n                </ShowIf>\n                {item.car?.firstColorOption}\n                {item.car?.secondColorOption?.length ? `, ${item.car?.secondColorOption}` : ''}{item.car?.thirdColorOption?.length ? `, ${item.car?.thirdColorOption}` : ''}\n\n              </td>\n          }\n        </ShowIf>\n        <ShowIf condition={canChangeRequest && false} alternative={\n          null // <td className=\"middle\">{item.status?.name}</td>\n        }>\n            <td className=\"middle\" style={{width: '120px'}}>\n              <select className=\"form-control select-sm font-12\" value={item.status?._id ?? ''}\n                onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                  this.props.updateRequestItemInDetailThunkAction({\n                    item: {\n                      ...item,\n                      status: {\n                        ...item.status,\n                        _id: e.target.value\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              >\n                <option value=\"\" disabled={true}>-</option>\n                {\n                  requestItemStatus.map((req) => (\n                    <option key={req._id} value={req._id}>{req.name}</option>\n                  ))\n                }\n\n              </select>\n            </td>\n        </ShowIf>\n        <ShowIf condition={requestSettings.ticket}>\n          <td className='middle-center'>\n             <div\n              data-toggle='tooltip'\n              data-placement='top'\n              className={`${item.request?.advancePaymentInformation?.files?.length ? 'pointer' : ''}`}\n              title={item.request?.advancePaymentInformation?.number ?? '-'}\n              onClick={\n               request.advancePaymentInformation?.files?.length\n                 ? () => this.openBlank(request.advancePaymentInformation.files[0].file.url)\n                 : undefined\n             }\n            >\n              {\n                //request.advancePaymentInformation.files[0].file.url\n                item.request?.advancePaymentInformation?.files?.length ?\n                  <i\n                    className='fa fa-check-circle text-green'\n                  /> : ''\n              }\n            </div>\n          </td>\n        </ShowIf>\n        <ShowIf\n          condition={\n            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n            requestSettings.internalNumber\n          }\n        >\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <input type=\"text\"\n                  className=\"form-control input-sm\"\n                  defaultValue={item.car.internalNumber}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          internalNumber: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td> :\n              <td className=\"middle\">{item.car.internalNumber}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={false && requestSettings.reason}>\n          {\n            canChangeRequest ?\n              <td className=\"middle\">\n                <select\n                  className=\"form-control select-sm font-12\" value={item.reason?._id ?? ''}\n                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                    this.props.updateRequestItemInDetailThunkAction({\n                      item: {\n                        ...item,\n                        reason: {\n                          ...item.reason,\n                          _id: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                >\n                  <option value=\"\" disabled={true}>-</option>\n                  {\n                    reasons.map((reason) => (\n                      <option key={reason._id} value={reason._id}>{reason.name}</option>\n                    ))\n                  }\n                </select>\n              </td> :\n              <td className=\"middle\">{item.reason?.name}</td>\n          }\n        </ShowIf>\n        <td\n          className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n          onClick={() => this.downloadFiles(item)}\n        >\n          {\n            item.files && item.files.length ?\n              <span\n                data-toggle={'tooltip'}\n                data-placement={'top'}\n                title={`${item.files.length} archivos adjuntos.`}\n              >\n                <i className=\"fa fa-paperclip\" /> ({item.files.length})\n              </span> : null\n          }\n        </td>\n        <td className=\"middle-center\">\n          {\n            item.observation && item.observation.length ?\n              <i\n                className=\"fa fa-comment\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title={item.observation}\n              /> : null\n          }\n        </td>\n        <ShowIf condition={hasPermission(window.user, 'deleteRequest')}>\n          <td className=\"middle-center text-red pointer\" onClick={() => this.deleteRequestItem(item)}>\n            <i className=\"fa fa-minus-circle\" />\n          </td>\n        </ShowIf>\n      </tr>\n    );\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    if (item.files && item.files.length) {\n      this.openBlank(`/requests-item/${item._id}/download-files/`);\n    }\n  }\n\n  private openBlank(url: string) {\n    window.open(decodeURI(url), '_blank');\n  }\n\n  private search(text: string): void {\n    this.$subjectRecommends.next(text)\n  }\n\n  private searchVin(vin: string): void {\n    this.$subjectVINRecommends.next(vin)\n  }\n\n  private deleteRequestItem(item: IRequestItem) {\n    const {request} = this.props;\n    if (request.items.length > 1) {\n      swal({\n        title: '¿Estás seguro?',\n        text: `Vas a eliminar este vehículo ${item.car.brand} ${item.car.denomination} ${item.car.material}.`,\n        icon: 'warning',\n        dangerMode: true,\n        buttons: {\n          cancel: 'Cancelar' as any,\n          confirm: {\n            text: 'Sí'\n          }\n        }\n      }).then((willDelete) => {\n        if (willDelete) {\n          this.props.deleteRequestItemThunkAction(item);\n        }\n      });\n    } else {\n      swal({\n        title: '¿Estás seguro?',\n        text: `Si eliminas este último vehículo, vas a eliminar esta solicitud.`,\n        icon: 'warning',\n        dangerMode: true,\n        buttons: {\n          cancel: 'Cancelar' as any,\n          confirm: {\n            text: 'Sí'\n          }\n        }\n      }).then((willDelete) => {\n        if (willDelete) {\n          this.props.deleteRequestThunkAction(request._id);\n        }\n      });\n    }\n  }\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState, router: any }) => {\n  return {\n    requests: state.requests,\n    router: state.router\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemInDetailThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => dispatch(updateRequestItemInDetailThunkAction({ item, debounce })),\n    deleteRequestItemThunkAction: (item: IRequestItem) => dispatch(deleteRequestItemThunkAction(item)),\n    deleteRequestThunkAction: (idRequest: string) => dispatch(deleteRequestThunkAction(idRequest))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestItem);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { arrayPush, Field, FieldArray, FormErrors, getFormSyncErrors, getFormValues, InjectedFormProps, reduxForm, submit } from 'redux-form';\nimport { AxiosError, default as Axios } from 'axios';\nimport * as moment from 'moment';\nimport { IReason } from '../../../../../../../src/request/interfaces/reason.interface';\nimport { IColor } from '../../../../../../../src/app/interfaces/color.interface';\nimport { ISalesChannel } from '../../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IPaymentMethod } from '../../../../../../../src/request/interfaces/paymentMethod.interface';\nimport { IOperationType } from '../../../../../../../src/request/interfaces/operationType.interface';\nimport ApiService from '../../../utils/axios';\nimport BootstrapSelectField from '../../Utils/forms/BootstrapSelectField';\nimport { inputStringRequired } from '../../Utils/forms/validations';\nimport InputField from '../../Utils/forms/InputField';\nimport { IRenderItemProps } from '../../Request/RequestForms/renders/RequestCarRender';\nimport RequestCarRender from './renders/RequestCarRender';\nimport * as uuid from 'uuid';\nimport DateRangePickerField from '../../Utils/forms/DateRangePickerField';\nimport { DecoratedFormProps } from 'redux-form/lib/reduxForm';\nimport InputHiddenField from '../../Utils/forms/InputHiddenField';\nimport ShowIf from '../../Utils/ShowIf';\nimport { IRequestSetting } from '../../../../../../../src/app/interfaces/teamSetting.interface';\nimport * as  swal from 'sweetalert';\nimport MultiUploadFiles, { imageStatus } from '../../Utils/MultiUploadFiles';\nimport { requestSettings } from '../defaults';\n\ninterface IPropsType extends InjectedFormProps {\n  formValues: any;\n  syncErrors: any;\n  dispatch: any;\n  created: boolean;\n  query: Dictionary<string>;\n}\n\ninterface IStateType {\n  filesCache: Dictionary<any>;\n  error: Error | null;\n  venues: any[];\n  reasons: IReason[];\n  colors: IColor[];\n  channels: ISalesChannel[];\n  paymentMethods: IPaymentMethod[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n  loading: boolean;\n  exist: boolean;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n\n  readonly api: ApiService;\n  readonly state: IStateType = {\n    filesCache: {},\n    error: null,\n    venues: [],\n    reasons: [],\n    colors: [],\n    channels: [],\n    paymentMethods: [],\n    operationTypes: [],\n    requestSettings,\n    loading: false,\n    exist: false,\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.loadBaseData = this.loadBaseData.bind(this);\n    this.addCarToForm = this.addCarToForm.bind(this);\n    this.updateFileCache = this.updateFileCache.bind(this);\n    this.api = new ApiService();\n  }\n\n  private updateFileCache(filesCache: Dictionary<any>){\n    this.setState({filesCache})\n  }\n\n  public componentWillMount(): void {\n    window.scrollTo(0, 0);\n    this.loadBaseData();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid, submitFailed, query, syncErrors, formValues, created, submitting } = this.props;\n    const { venues, channels, reasons, colors, loading, exist, filesCache, paymentMethods, requestSettings } = this.state;\n    const uploadingFiles = !!Object.values(filesCache).filter((files: any) => {\n      return !!files.filter((file: any) => file.status !== imageStatus.complete).length;\n    }).length;\n    return (\n      <React.Fragment>\n        <div className='container-fluid' style={{ position: 'relative', minHeight: '100vh', padding: '0 0 150px 0' }}>\n          <form onSubmit={handleSubmit}>\n            <div className='row' style={{ padding: '0 20px' }}>\n              <div className='col-md-12'>\n                <div className='row'>\n                  <div className='col-md-12'>\n                    <h3>Crear solicitud</h3>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Información de venta</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-sm' style={{ width: '100%' }}>\n                              <tbody>\n                              <tr>\n                                <td className={'middle'} style={{ width: '30%' }}>\n                                  <Field\n                                    name='sellerText'\n                                    label='Vendedor *'\n                                    type='text'\n                                    props={{\n                                      readOnly: true\n                                    }}\n                                    component={InputField}\n                                    validate={[inputStringRequired]}\n                                  />\n                                </td>\n                                <td className={'middle'} style={{ width: '25%', maxWidth: '25%' }}>\n                                  <Field\n                                    name='venue'\n                                    label='Sucursal *'\n                                    // labelOff={true}\n                                    component={BootstrapSelectField}\n                                    validate={[inputStringRequired]}\n                                    props={{\n                                      disabled: true,\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...venues.map((venue) => ({\n                                          value: venue._id,\n                                          text: venue.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if(formValues.venue === value){\n                                          this.props.autofill('venue', \"\");\n                                        } else{\n                                          this.props.autofill('venue', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '25%', maxWidth: '25%' }}>\n                                  <Field\n                                    name='channel'\n                                    label='Canal'\n                                    component={BootstrapSelectField}\n                                    validate={[inputStringRequired]}\n                                    props={{\n                                      disabled: true,\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'canales seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...channels.map((channel) => ({\n                                          value: channel._id,\n                                          text: channel.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if (formValues.channel === value) {\n                                          this.props.autofill('channel', '');\n                                        } else {\n                                          this.props.autofill('channel', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '20%' }}>\n                                  <Field\n                                    name='conectaID'\n                                    // labelOff={true}\n                                    label='ID Cotización Conecta *'\n                                    type='text'\n                                    props={{\n                                      readOnly: true\n                                    }}\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                                </td>\n                              </tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Información del cliente</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <table className='table-xs' style={{ width: '100%' }}>\n                          <tbody>\n                          <tr>\n                            <td className={'middle'} style={{ width: '200px' }}>\n                              <Field\n                                name='customerInformation.rut'\n                                label='RUT *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('5bf2de35caf8ef7096105c22')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                            <td className={'middle'}>\n                              <Field\n                                name='customerInformation.name'\n                                label='Nombre Completo *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('5bf2de35caf8ef7096105c21')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                            <td className={'middle'} style={{ width: '30%' }}>\n                              <Field\n                                name='customerInformation.email'\n                                label='Correo Electrónico *'\n                                type='text'\n                                props={{\n                                  readOnly: query.hasOwnProperty('60b9232164adc90013a79b45')\n                                }}\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                          </tr>\n                          </tbody>\n                        </table>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Datos de la reserva</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-xs' style={{ width: '100%' }}>\n                          <tbody>\n                          <tr>\n                            <td className={'middle form-group-no-margin'} style={{ width: '35%' }}>\n                              <Field\n                                name='advancePaymentInformation.method'\n                                label='Método de Pago *'\n                                component={BootstrapSelectField}\n                                validate={[inputStringRequired]}\n                                props={{\n                                  noneSelectedText: 'Seleccione...',\n                                  displayItems: 2,\n                                  selectedText: 'sucursal seleccionadas.',\n                                  autoClouse: true,\n                                  sm: true,\n                                  allOption: false,\n                                  search: true,\n                                  options: [\n                                    ...paymentMethods.map((paymentMethod) => ({\n                                      value: paymentMethod._id,\n                                      text: paymentMethod.name\n                                    }))\n                                  ],\n                                  onClick: (value: string) => {\n                                    if (formValues.advancePaymentInformation.method === value) {\n                                      this.props.autofill('advancePaymentInformation.method', '');\n                                    } else {\n                                      this.props.autofill('advancePaymentInformation.method', value);\n                                    }\n                                  }\n                                }}\n                              >\n                              </Field>\n                            </td>\n                            <td className={'middle form-group-no-margin'} style={{ width: '35%' }}>\n                              <Field\n                                name='advancePaymentInformation.number'\n                                label='Nº de Ticket de Anticipo u Orden de Compra *'\n                                type='text'\n                                component={InputField}\n                                validate={[inputStringRequired]}\n                              />\n                            </td>\n                          </tr>\n                          <tr>\n                            <td className={'middle form-group-no-margin'}>\n                              <div\n                                className={`form-group ${submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'has-error' : ''}`}>\n                                <label className='control-label text-ellipsis'>Subir Ticket de Anticipo u Orden de Compra *</label>\n                                <Field\n                                  name={`advancePaymentInformation.files`}\n                                  type='hidden'\n                                  labelOff={true}\n                                  component={InputHiddenField}\n                                  validate={[inputStringRequired]}\n                                />\n                                <MultiUploadFiles\n                                  url={'/api/v1/requests/upload-file/'}\n                                  className={submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'multi-upload-errors' : ''}\n                                  onChange={(files) => {\n                                    const lastFile = files.length ? [files[files.length - 1]] : [];\n                                    this.updateFileCache({\n                                      ...filesCache,\n                                      ['payment']: lastFile\n                                    });\n                                    this.props.autofill('advancePaymentInformation.files', lastFile);\n                                  }}\n                                  files={filesCache.hasOwnProperty('payment') ? filesCache['payment'] : []}\n                                />\n                                <ShowIf condition={submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length}>\n                                  <span className='help-block text-red'>Este campo es requerido</span>\n                                </ShowIf>\n                              </div>\n                            </td>\n                            <td className={'middle form-group-no-margin'}>\n                              <div\n                                className={`form-group ${submitFailed && !valid && !formValues?.advancePaymentInformation?.files?.length ? 'has-error' : ''}`}>\n                                <label className='control-label text-ellipsis'>Subir Carta de Reserva *</label>\n                                <Field\n                                  name={`advancePaymentInformation.letters`}\n                                  type='hidden'\n                                  labelOff={true}\n                                  component={InputHiddenField}\n                                  validate={[inputStringRequired]}\n                                />\n                                <MultiUploadFiles\n                                  url={'/api/v1/requests/upload-file/'}\n                                  className={submitFailed && !valid && !formValues?.advancePaymentInformation?.letters?.length ? 'multi-upload-errors' : ''}\n                                  onChange={(files) => {\n                                    const lastFile = files.length ? [files[files.length - 1]] : [];\n                                    this.updateFileCache({\n                                      ...filesCache,\n                                      ['letter']: lastFile\n                                    });\n                                    this.props.autofill('advancePaymentInformation.letters', lastFile);\n                                  }}\n                                  files={filesCache.hasOwnProperty('letter') ? filesCache['letter'] : []}\n                                />\n                                <ShowIf condition={submitFailed && !valid && !formValues?.advancePaymentInformation?.letters?.length}>\n                                  <span className='help-block text-red'>Este campo es requerido</span>\n                                </ShowIf>\n                              </div>\n                            </td>\n                          </tr>\n                          </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className='box-title'>Datos de entrega</h3>\n                      </div>\n                      <div className='box-body create-request' style={{ paddingBottom: '0' }}>\n                        <div className='row'>\n                          <div className='col-md-12'>\n                            <table className='table-xs' style={{ width: '100%' }}>\n                              <tbody>\n                              <tr>\n                                <td className={'middle'} style={{ width: '25%' }}>\n                                  <Field\n                                    name='deliveryVenue'\n                                    label='Sucursal'\n                                    // labelOff={true}\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'transportistas seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...venues.map((venue) => ({\n                                          value: venue._id,\n                                          text: venue.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if(formValues.deliveryVenue === value){\n                                          this.props.autofill('deliveryVenue', null);\n                                        } else{\n                                          this.props.autofill('deliveryVenue', value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                </td>\n                                <td className={'middle'} style={{ width: '50%' }}>\n                                  <Field\n                                    name='deliveryAddress'\n                                    // labelOff={true}\n                                    label='Dirección'\n                                    type='text'\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                                </td>\n                                <td className={'middle'} style={{ width: '25%' }}>\n                                  <Field\n                                    name='deliveryDate'\n                                    // labelOff={true}\n                                    label='Fecha'\n                                    type='text'\n                                    component={DateRangePickerField}\n                                    props={{\n                                      className: 'input-sm',\n                                      format: 'DD-MM-YYYY',\n                                      startDate: moment().add(1, 'days').startOf('day'),\n                                      onChange: (e: any) => {\n                                        this.props.autofill('deliveryDate', e?.toDate() ?? '');\n                                      }\n                                    }}\n                                  />\n                                </td>\n                              </tr>\n                              </tbody>\n                            </table>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <div className='col-md-12'>\n                    <div className='box'>\n                      <div className='box-header with-border'>\n                        <h3 className={submitFailed && !valid && !formValues.cars.length ? 'text-red box-title' : 'box-title'}>Unidades</h3>\n                      </div>\n                      <div className='box-body create-request no-padding'>\n                        <div className='row'>\n                          <FieldArray<IRenderItemProps>\n                            name='cars'\n                            component={RequestCarRender}\n                            props={{\n                              reasons,\n                              colors,\n                              requestSettings,\n                              updateFileCache: this.updateFileCache,\n                              filesCache,\n                              loading,\n                              syncErrors,\n                              submitFailed,\n                              formValues,\n                              valid,\n                              query,\n                              autofill: this.props.autofill\n                            }}\n                          />\n                          <div className='col-md-12 text-right' style={{ padding: ' 30px' }}>\n                            <button\n                              className='btn btn-success btn-sm'\n                              type='button'\n                              onClick={this.addCarToForm}\n                            >\n                              <i className='fa fa-plus' /> Agregar vehículo\n                            </button>\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  {/*{\n                    submitFailed && !valid &&\n                    <div className='col-md-12'>\n                      <div\n                        className='alert alert-danger m-t-20'\n                      >\n                        Todos los campos con * son obligatorios\n                      </div>\n                    </div>\n                  }*/}\n                  <div className='col-md-12 text-right'>\n                    <ShowIf condition={uploadingFiles}>\n                      <p className={\"text-muted text-left\"}>Espere a que se terminen de subir las imágenes para crear la solicitud.</p>\n                    </ShowIf>\n                    <button\n                      type={'button'}\n                      disabled={submitting || uploadingFiles}\n                      onClick={submitting || !valid || uploadingFiles ? () => this.props.dispatch(submit('requestForm')) : () => {\n                        swal({\n                          title: '¿Estás seguro?',\n                          text: `Vas a crear esta solicitud.`,\n                          icon: 'warning',\n                          dangerMode: true,\n                          buttons: {\n                            cancel: 'Cancelar' as any,\n                            confirm: {\n                              text: 'Sí'\n                            }\n                          }\n                        }).then((willCReate: any) => {\n                          if (willCReate) {\n                            this.props.dispatch(submit('requestForm'));\n                          }\n                        });\n                      }}\n                      className='btn btn-primary btn-sm'\n                    >\n                      {submitting && <i className='fa fa-fw fa-spinner fa-spin' />} Crear solicitud\n                    </button>\n                  </div>\n                  <Field\n                    name={`cars_error`}\n                    type='hidden'\n                    labelOff={true}\n                    component={InputHiddenField}\n                  />\n                </div>\n              </div>\n            </div>\n          </form>\n          <div className='text-muted text-center' style={{ position: 'absolute', bottom: '0', height: '30px', width: '100%' }}>\n            Copyright (c) {moment().format('YYYY')} <a href='http://www.osacontrol.com' target='_blank'>OSA SPA</a>. All rights reserved.\n          </div>\n        </div>\n        <ShowIf condition={loading}>\n          {/*<ShowIf condition={true}>*/}\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n            <p><i className='fa fa-3x fa-circle-o-notch text-primary fa-spin' /></p>\n            {/*<p style={{ padding: '20px', fontSize: '1.7rem'}}><strong>Cargando datos</strong></p>*/}\n          </div>\n        </ShowIf>\n        <ShowIf condition={created}>\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n          </div>\n        </ShowIf>\n        <ShowIf condition={exist}>\n          <div style={{\n            position: 'absolute',\n            top: '0',\n            height: '100%',\n            width: '100vw',\n            backgroundColor: 'rgba(246,246,246,0.4)',\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'center',\n            paddingTop: '400px'\n            // justifyContent: 'center'\n          }}>\n          </div>\n        </ShowIf>\n      </React.Fragment>\n    );\n  }\n\n  private addCarToForm() {\n    const { query } = this.props;\n    const { material } = query;\n    const { reasons } = this.state;\n    let data: any = {\n      key: uuid.v4(),\n      reason: '5fe0930aa9683b0f8a6e0e42',\n      brand: query.brand,\n      denomination: query.denomination,\n      material: material.substr(material.length > 6 ? material.length - 6 : 0),\n      answersbkp: [],\n      answers: [],\n      files: []\n    };\n    const salfaReason = reasons\n      .find((reason) => reason._id === '5fe0930aa9683b0f8a6e0e42');\n    if (salfaReason) {\n      salfaReason.questions\n        .forEach((question) => {\n          data.answersbkp.push(query[question._id]);\n          if (query[question._id]) {\n            data.answers.push({\n              questionId: question._id,\n              question: question.name,\n              answer: query[question._id]\n            });\n          }\n        });\n    }\n    this.props.dispatch(arrayPush('requestForm', 'cars', data));\n  }\n\n  private loadBaseData() {\n    const {  query } = this.props;\n    const conectaID = query['6154722a94bba10012230aae'] || query['conectaID'];\n    this.setState({ loading: true });\n    Axios\n      .all([\n        this.api.getCompanyVenues(),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getColors({ page: 1, pageSize: 200 }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings(),\n        this.api.getOperationTypes({ page: 1, pageSize: 200 }),\n        this.api.getPaymentMethods({ page: 1, pageSize: 200 }),\n        this.api.validateContectaID(conectaID)\n      ])\n      .then(Axios.spread((venues, reasons, colors, channels, teamSettings, operationTypes, paymentMethods, validateContecta) => {\n        if(validateContecta.data?.error){\n          this.setState({ exist: true });\n          swal!('Solicitud ya creada para esta cotización', `ID de cotización conecta ${conectaID} ya se encuentra asociado en la solicitud ${validateContecta.data.number}.`, 'warning', {\n            button: false,\n            closeOnClickOutside: false,\n            closeOnEsc: false\n          });\n        }\n        this.props.autofill('channel', teamSettings.data?.user?.defaultChannel);\n        this.setState({\n          venues: venues.data.results,\n          colors: colors.data.results,\n          reasons: reasons.data.results.map((reason: any) => {\n            // disable questions and extra files\n            reason.questions = [];\n            reason.file = {\n              '_id': '62521d050cf69800277f2686',\n              'active': false,\n              'required': false\n            };\n            return reason;\n          }),\n          channels: channels.data.results,\n          paymentMethods: paymentMethods.data.results,\n          requestSettings: teamSettings.data.request,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n        this.addCarToForm();\n      }))\n      .catch((err: AxiosError): void => {\n        this.api.errorHandler(err);\n      });\n  }\n}\n\nconst validate = (values: any, props: DecoratedFormProps<FormData, any, string>): FormErrors<FormData, string> => {\n  const errors: any = {};\n  if (values.deliveryAddress?.length && !values.deliveryVenue?.length) {\n    errors.deliveryVenue = 'Este campo es requerido';\n  }\n  if (!values.cars?.length) {\n    errors.cars_error = 'Este campo es requerido';\n  }\n  return errors;\n};\n\nconst RequestForm = reduxForm<any, any, any>({\n  form: 'requestForm',\n  validate\n})(Form);\n\nconst mapStateToProps = (state: any) => {\n  return {\n    formValues: getFormValues('requestForm')(state),\n    syncErrors: getFormSyncErrors('requestForm')(state),\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, { dispatch: any }, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestForm);\n","import * as React from 'react';\nimport { Field, getFormMeta, getFormSyncErrors, WrappedFieldArrayProps } from 'redux-form';\nimport { connect } from 'react-redux';\nimport InputField from '../../../Utils/forms/InputField';\nimport { inputStringRequired } from '../../../Utils/forms/validations';\nimport ShowIf from '../../../Utils/ShowIf';\nimport MultiUploadFiles, { imageStatus } from '../../../Utils/MultiUploadFiles';\nimport { IReason } from '../../../../../../../../src/request/interfaces/reason.interface';\nimport BootstrapSelectField from '../../../Utils/forms/BootstrapSelectField';\nimport InputHiddenField from '../../../Utils/forms/InputHiddenField';\n\n\nexport interface IRenderItemProps {\n}\n\ninterface IPropsType extends WrappedFieldArrayProps<{}>, IRenderItemProps {\n  reasons: any[],\n  colors: any[];\n  syncErrors: any;\n  formValues: any;\n  updateFileCache: any;\n  filesCache: Dictionary<any>\n  query: any;\n  requestSettings: any;\n  submitFailed: any;\n  valid: any;\n  loading: boolean;\n  autofill(field: string, value: any): void;\n}\n\n\ninterface IStateType {\n  error: Error | null;\n  openTabs: string[];\n  reasonSelectedState: Dictionary<string>;\n}\n\nclass RequestCarRender extends React.Component<IPropsType, IStateType> {\n\n  readonly state: IStateType = {\n    error: null,\n    openTabs: [],\n    reasonSelectedState: {}\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.toogleTab = this.toogleTab.bind(this);\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const { fields, submitFailed, valid, reasons, colors, syncErrors, query, formValues, loading, filesCache, requestSettings } = this.props;\n    const { openTabs, reasonSelectedState } = this.state;\n    return (\n      <React.Fragment>\n        {\n          fields.length === 0 ?\n            <ShowIf condition={!loading}>\n              <div className='col-md-12'>\n                <p\n                  className={submitFailed && !valid && !formValues.cars.length ? 'text-red text-center' : ' text-muted text-center'}\n                  style={{ padding: '60px 0px  30px 0px', margin: '0' }}\n                >\n                  {submitFailed && !valid && !formValues.cars.length ? 'Debes agregar al menos un unidad.' : 'No se han agregado unidades aún.'}\n                </p>\n              </div>\n            </ShowIf> :\n            <div className='col-md-12'>\n              {\n                fields.map((item, index) => {\n                  const value: any = fields.get(index) as any;\n                  const openTab = openTabs.includes(value.key);\n                  const reasonSelected: IReason | undefined = reasons.find((reason: IReason) => reason._id === reasonSelectedState[index] || reason._id === value.reason);\n                  let uploadingFiles = 0;\n                  let archivos = 0;\n                  if (filesCache.hasOwnProperty(index)) {\n                    uploadingFiles = filesCache[index].filter((file: any) => file.status !== imageStatus.complete).length;\n                    archivos = filesCache[index].length;\n                  }\n                  let hasErrors = 0;\n                  let hasFileErrors = 0;\n                  if (syncErrors?.cars?.length > index) {\n                    hasErrors = syncErrors?.cars[index]?.answersbkp?.filter((msg: any) => msg).length ?? 0;\n                  }\n                  if (reasonSelected && reasonSelected.file.active && archivos === 0) {\n                    hasErrors++;\n                    hasFileErrors++;\n                  }\n                  return (\n                    <div key={value.key}>\n                      <table className='table-sm' style={{ width: '100%', backgroundColor: '#f6f6f6', borderTop: '1px solid #e5e3e3' }}>\n                        <tbody>\n                        <tr>\n                          <td className={`middle-center`}>\n                            #<strong>{this.padNumber(index + 1)}</strong>\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.brand`}\n                              label='Marca *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.denomination`}\n                              label='Modelo *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`}>\n                            <Field\n                              name={`${item}.material`}\n                              label='Material *'\n                              type='text'\n                              props={{\n                                readOnly: true\n                              }}\n                              component={InputField}\n                              validate={[inputStringRequired]}\n                            />\n                          </td>\n                          <td className={`middle form-group-no-margin`} style={{width: '120px'}}>\n                            {\n                              colors.length ?\n                                <Field\n                                  name={`${item}.color`}\n                                  label='Color *'\n                                  component={BootstrapSelectField}\n                                  validate={[inputStringRequired]}\n                                  props={{\n                                    noneSelectedText: 'Seleccione...',\n                                    displayItems: 2,\n                                    selectedText: 'sucursal seleccionadas.',\n                                    autoClouse: true,\n                                    sm: true,\n                                    allOption: false,\n                                    search: true,\n                                    options: [\n                                      ...colors.map((color) => ({\n                                        value: color.name,\n                                        text: color.name\n                                      }))\n                                    ],\n                                    onClick: (value: string) => {\n                                      this.props.autofill(`${item}.color`, value);\n                                    }\n                                  }}\n                                >\n                                </Field>\n                                :\n                                <Field\n                                  name={`${item}.color`}\n                                  label='Color *'\n                                  type='text'\n                                  component={InputField}\n                                  validate={[inputStringRequired]}\n                                />\n                            }\n                          </td>\n                          <ShowIf condition={requestSettings.secondColorOption}>\n                            <td className={`middle form-group-no-margin`} style={{width: '120px'}}>\n                              {\n                                colors.length ?\n                                  <Field\n                                    name={`${item}.secondColorOption`}\n                                    label='Color 2 (Opcional)'\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...colors.map((color) => ({\n                                          value: color.name,\n                                          text: color.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if (formValues.cars[index]?.secondColorOption === value) {\n                                          this.props.autofill(`${item}.secondColorOption`, \"\");\n                                        } else {\n                                          this.props.autofill(`${item}.secondColorOption`, value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                  :\n                                  <Field\n                                    name={`${item}.secondColorOption`}\n                                    label='Color 2 (Opcional)'\n                                    type='text'\n                                    component={InputField}\n                                    // validate={[inputStringRequired]}\n                                  />\n                              }\n                            </td>\n                          </ShowIf>\n                          <ShowIf condition={requestSettings.thirdColorOption}>\n                            <td className={`middle form-group-no-margin`} style={{width: '120px'}}>\n                              {\n                                colors.length ?\n                                  <Field\n                                    name={`${item}.thirdColorOption`}\n                                    label='Color 3 (Opcional)'\n                                    component={BootstrapSelectField}\n                                    // validate={[inputStringRequired]}\n                                    props={{\n                                      noneSelectedText: 'Seleccione...',\n                                      displayItems: 2,\n                                      selectedText: 'sucursal seleccionadas.',\n                                      autoClouse: true,\n                                      sm: true,\n                                      allOption: false,\n                                      search: true,\n                                      options: [\n                                        ...colors.map((color) => ({\n                                          value: color.name,\n                                          text: color.name\n                                        }))\n                                      ],\n                                      onClick: (value: string) => {\n                                        if (formValues.cars[index]?.thirdColorOption === value) {\n                                          this.props.autofill(`${item}.thirdColorOption`, \"\");\n                                        } else {\n                                          this.props.autofill(`${item}.thirdColorOption`, value);\n                                        }\n                                      }\n                                    }}\n                                  >\n                                  </Field>\n                                  :\n                                  <Field\n                  