\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  {/* pasar a fecha*/}\n                  <Field\n                    name={`${item}.businessYear`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  {/* pasar a fecha*/}\n                  <Field\n                    name={`${item}.manufacturingYear`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.price`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.insurancePrice`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.weight`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.gas`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.ap`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.countryOrigin`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.observation`}\n                    type='text'\n                    component={InputField}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n                <td className='form-group-no-margin'>\n                  <Field\n                    name={`${item}.shippingDate`}\n                    type='text'\n                    component={DateRangePicker}\n                    props={{\n                      labelOff: true\n                    }}\n                  />\n                </td>\n              </tr>\n            );\n          })\n        }\n      </>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { transmittal: ITransmittalState }) => {\n  const selector = formValueSelector('requestImportForm');\n  return {\n    formValues: selector(state, 'all.origin', 'all.destination'),\n    transmittal: state.transmittal\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  const transmittalActions = new TransmittalActions(dispatch);\n  return {\n    dispatch,\n    transmittalActions\n  };\n};\n\n\nexport default connect<{}, {}, IRequestImportRenderItemProps>(mapStateToProps, mapDispatchToProps)(RequestImportRenderRequestItem);\n","import Axios, { AxiosError, AxiosResponse } from 'axios';\nimport * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport BootstrapTable from 'react-bootstrap-table-next';\nimport filterFactory from 'react-bootstrap-table2-filter';\nimport paginationFactory from 'react-bootstrap-table2-paginator';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { ICar } from '../../../../../../src/app/interfaces/car.interface';\nimport { IRequestSetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport { IRequestItemsState } from '../../actions/requestItems.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport ShowIf from '../Utils/ShowIf';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { requestSettings } from './defaults';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<any>;\n}\n\nenum itemStatus {\n  PENDING = 'PENDING',\n  IN_PROCESS = 'IN_PROCESS',\n  READY = 'READY',\n  ERROR = 'ERROR',\n  UPDATED = 'UPDATED'\n}\n\ninterface IExcelData {\n  code: string | null;\n  vin: string | null;\n  material: string | null;\n  count: number;\n}\n\ninterface IIntegrationData {\n  brand: string;\n  color: string;\n  denomination: string;\n  material: string;\n  vin: string;\n}\n\ninterface IAndesData {\n  _id: string;\n  code: string;\n  car: Partial<ICar>;\n}\n\ninterface preMassAllocationResponse {\n  results: IAndesData[];\n}\n\ninterface IRequestItemStore {\n  _id: string;\n  processStatus: itemStatus;\n  andesData: IAndesData;\n  excelData: IExcelData;\n  integrationData?: IIntegrationData;\n  errors: string[];\n  checked: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n  canDrop: boolean;\n  loading: boolean;\n  sending: boolean;\n  requestItems: IRequestItemStore[];\n  requestSettings: IRequestSetting;\n  countItemsByStatus: any;\n}\n\ndeclare let window: IWindow;\n\nclass RequestImportVINSView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly apiService: ApiService;\n\n  private paginationOption: any = {\n    paginationSize: 4,\n    showTotal: true,\n    paginationTotalRenderer: this.customTotal,\n    sizePerPageList: [{\n      text: '20', value: 20\n    }, {\n      text: '50', value: 50\n    }, {\n      text: '100', value: 100\n    }, {\n      text: '200', value: 200\n    }]\n    // onPageChange: () => {\n    //   window.scrollTo(0, 0);\n    //   setTimeout(() => {\n    //     $('[data-toggle=\"tooltip\"]').tooltip();\n    //   }, 200);\n    // }\n  };\n\n  readonly defaultSorted = [{\n    dataField: 'errors.length',\n    order: 'desc'\n  }];\n\n  readonly columns: any[] = [];\n\n  readonly state: IStateType = {\n    error: null,\n    canDrop: false,\n    loading: true,\n    sending: false,\n    requestItems: [],\n    countItemsByStatus: {\n      [itemStatus.PENDING]: 0,\n      [itemStatus.IN_PROCESS]: 0,\n      [itemStatus.READY]: 0,\n      [itemStatus.ERROR]: 0\n    },\n    requestSettings\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importador de solicitudes';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.customTotal = this.customTotal.bind(this);\n    this.checkItems = this.checkItems.bind(this);\n    this.itemsByStatus = this.itemsByStatus.bind(this);\n    this.updateItemStatusByID = this.updateItemStatusByID.bind(this);\n    this.statusFormatter = this.statusFormatter.bind(this);\n    this.vinFormatter = this.vinFormatter.bind(this);\n    this.codeFormatter = this.codeFormatter.bind(this);\n    this.requestedVehicle = this.requestedVehicle.bind(this);\n    this.assignVehicle = this.assignVehicle.bind(this);\n    this.processItems = this.processItems.bind(this);\n    this.answerProcessitems = this.answerProcessitems.bind(this);\n    this.apiService = new ApiService();\n    this.columns = [{\n      dataField: 'processStatus',\n      text: '',\n      formatter: this.statusFormatter,\n      classes: 'middle-center',\n      headerClasses: 'middle-center pointer',\n      style: {\n        width: '40px'\n      }\n    }, {\n      dataField: 'andesData.code',\n      text: 'CODIGO',\n      classes: 'middle-center',\n      formatter: this.codeFormatter,\n      headerClasses: 'middle-center pointer',\n      style: {\n        width: '90px',\n        miWidth: '90px'\n      },\n      sort: true\n    }, {\n      dataField: 'excelData.vin',\n      text: 'VIN',\n      classes: 'middle',\n      formatter: this.vinFormatter,\n      headerClasses: 'middle pointer',\n      style: {\n        width: '18%',\n        miWidth: '18%'\n      },\n      sort: true\n    }, {\n      dataField: 'andesData.car.brand',\n      text: 'Solicitud',\n      classes: 'middle',\n      formatter: this.requestedVehicle,\n      headerClasses: 'middle pointer',\n      style: {\n        width: '27%',\n        miWidth: '27%'\n      }\n      // sort: true\n    }, {\n      dataField: 'car.denomination',\n      text: 'Asignación',\n      classes: 'middle',\n      formatter: this.assignVehicle,\n      headerClasses: 'middle pointer',\n      style: {\n        width: '27%',\n        miWidth: '27%'\n      }\n      // sort: true\n    }, {\n      dataField: 'errors.length',\n      text: 'Problemas',\n      formatter: this.errorsFormatter,\n      classes: 'middle',\n      headerClasses: 'middle pointer',\n      // style: {\n      //   width: '100px',\n      //   miWidth: '100px'\n      // },\n      sort: true\n    }];\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n    const api: ApiService = new ApiService();\n    Axios\n      .all([\n        this.apiService.getTeamSettings()\n      ])\n      .then(Axios.spread((\n        teamSettings\n      ) => {\n        this.setState({\n          requestSettings: teamSettings.data.request,\n          loading: false\n        });\n      }))\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any) {\n    $('.react-bootstrap-table-pagination')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div')\n      .removeClass('col-xs-6')\n      .addClass('col-xs-12')\n      .css({ padding: '3px 15px' });\n    $('.react-bootstrap-table-pagination div:last-child')\n      .removeClass('text-right')\n      .addClass('text-right');\n    $('#pageDropDown')\n      .removeClass('btn-sm')\n      .addClass('btn-sm');\n    $('.bs-searchbox input')\n      .removeClass('input-sm')\n      .addClass('input-sm');\n    $('.pagination')\n      .removeClass('pagination-sm')\n      .addClass('pagination-sm')\n      .css({ margin: 0 });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loading, sending, requestItems\n    } = this.state;\n    const pendings = this.itemsByStatus(itemStatus.PENDING);\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.2' cAction='Asignación masiva de unidades'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Asignación masiva de unidades</h3>\n              <div className='pull-right box-tools'>\n                <ShowIf condition={!requestItems.length}>\n                  <button\n                    className='btn btn-sm btn-primary'\n                    onClick={this.downloadTemplate}\n                    style={{ marginRight: '5px' }}>\n                    <i className='fa fa-fw fa-download' /> Descargar Formato\n                  </button>\n                </ShowIf>\n                <ShowIf condition={!!requestItems.length}>\n                  <div className='btn-group btn-group-sm'>\n                    <button\n                      className='btn btn-sm btn-success'\n                      disabled={!!pendings.length || sending}\n                      onClick={!!pendings.length || sending ? undefined : this.answerProcessitems}\n                    >\n                      <ShowIf condition={sending} alternative={<>\n                        {pendings.length || sending?<i className='fa fa-fw fa-spinner fa-spin ' />:<i className='fa fa-fw fa-check-circle-o' />} Confirmar asignación\n                      </>\n                      }>\n                        <>\n                          <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...\n                        </>\n                      </ShowIf>\n                    </button>\n                    <div className='btn-group btn-group-sm'>\n                      <button type='button' className='btn btn-default dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>\n                        <span className='caret'></span>\n                      </button>\n                      <ul className='dropdown-menu' style={{ paddingRight: '10px' }}>\n                        <li>\n                          <a href='#' onClick={this.downloadTemplate} className='text-muted'>\n                            <i className='fa fa-fw fa-download' /> Descargar Formato v1.0\n                          </a>\n                        </li>\n                        <li>\n                          <a href='#' onClick={this.clickUploadFile} className='text-muted'>\n                            <i className='fa fa-fw fa-upload' /> Cambiar archivo de importación\n                          </a>\n                        </li>\n                        <li>\n                          <a href='#' onClick={() => this.props.history.push('/requests/vehicles/')} className='text-muted'>\n                            <i className='fa fa-fw fa-stop-circle-o' /> Cancelar\n                          </a>\n                        </li>\n                      </ul>\n                    </div>\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n            <div className={`box-body ${requestItems.length ? 'no-padding' : 'margin'}`}>\n              {/*<ul>*/}\n              {/*  <li>Pendiente: {countItemsByStatus[itemStatus.PENDING]}</li>*/}\n              {/*  <li>En proceso: {countItemsByStatus[itemStatus.IN_PROCESS]}</li>*/}\n              {/*  <li>Listos: {countItemsByStatus[itemStatus.READY]}</li>*/}\n              {/*  <li>Error: {countItemsByStatus[itemStatus.ERROR]}</li>*/}\n              {/*</ul>*/}\n              {\n                requestItems.length ?\n                  <>\n                    <div className='mass-allocate-requests'>\n                      <BootstrapTable\n                        keyField='_id'\n                        data={requestItems}\n                        columns={this.columns}\n                        filter={filterFactory()}\n                        pagination={paginationFactory(this.paginationOption)}\n                        defaultSorted={this.defaultSorted}\n                      />\n                    </div>\n                  </>\n                  :\n                  <div className='row'>\n                    <div className='col col-md-12'>\n                      <div className='form-group'>\n                        <div\n                          className='upload-file text-center pointer'\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className='fa fa-2x fa-cloud-upload' /><br />\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type='file'\n                onChange={this.handleChangeInputFile}\n                style={{ display: 'None' }}\n                ref={this.inputFile}\n                accept='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel'\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <div className='btn-group btn-group-sm'>\n                <button\n                  className='btn btn-sm btn-default'\n                  onClick={() => this.props.history.push('/requests/vehicles/')}\n                >\n                  Cancelar\n                </button>\n                <ShowIf condition={!!requestItems.length}>\n                  <div className='btn-group btn-group-sm'>\n                    <button type='button' className='btn btn-default dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>\n                      <span className='caret'></span>\n                    </button>\n                    <ul className='dropdown-menu  dropdown-menu-right' style={{ paddingRight: '10px' }}>\n                      <li>\n                        <a\n                          href='#'\n                          // disabled={!!pendings.length || sending}\n                          onClick={!!pendings.length || sending ? undefined : this.answerProcessitems}\n                          className='text-muted'\n                        >\n                          <ShowIf condition={sending} alternative={<>\n                            {pendings.length || sending ? <i className='fa fa-fw fa-spinner fa-spin ' /> :\n                              <i className='fa fa-fw fa-check-circle-o' />} Confirmar asignación</>}\n                          >\n                            <>\n                              <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...\n                            </>\n                          </ShowIf>\n                        </a>\n                        {/*<button\n                        className='btn btn-sm btn-success'\n                        disabled={!!pendings.length || sending}\n                        onClick={!!pendings.length || sending ? undefined : this.answerProcessitems}\n                      >\n                        <ShowIf condition={sending} alternative={<>\n                          {pendings.length || sending ? <i className='fa fa-fw fa-spinner fa-spin ' /> :\n                            <i className='fa fa-fw fa-check-circle-o' />} Confirmar asignación</>}\n                        >\n                          <>\n                            <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...\n                          </>\n                        </ShowIf>\n                      </button>*/}\n                      </li>\n                    </ul>\n                  </div>\n                </ShowIf>\n              </div>\n            </div>\n            <ShowIf condition={loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const { files } = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      ['CODIGO']: '',\n      ['VIN/ID']: '',\n      ['MATERIAL']: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Solicitudes');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_mass_allocation_request.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loading: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData: any [] = 'Solicitudes' in workbook.Sheets\n          ? XLSX.utils.sheet_to_json(workbook.Sheets.Solicitudes)\n          : [];\n        if (excelData.length >= 1) {\n          const items: any[] = [];\n          const excelDataItemByCode: Dictionary<IExcelData> = {};\n          for (const item of excelData) {\n            const code = item.hasOwnProperty('CODIGO') ? item['CODIGO'].trim().toUpperCase() : null;\n            const vin = item.hasOwnProperty('VIN/ID') ? item['VIN/ID'].trim().toUpperCase() : null;\n            const material = item.hasOwnProperty('MATERIAL') ? item['MATERIAL'].trim().toUpperCase() : null;\n            if (code?.length) {\n              excelDataItemByCode[code] = {\n                code,\n                vin,\n                material,\n                count: excelDataItemByCode[code]?.count ? excelDataItemByCode[code].count + 1 : 1\n              };\n              items.push({\n                code,\n                material,\n                vin\n              });\n            }\n          }\n          this.apiService\n            .preMassAllocation({ items })\n            .then((response: AxiosResponse<preMassAllocationResponse>) => {\n              const { results } = response.data;\n              if (!results.length) {\n                this.setState({\n                  loading: false\n                });\n                swal!(\n                  'Asignador masivo de unidades',\n                  `No se han encontrado unidades.`,\n                  'error'\n                );\n              } else {\n                const requestItems: IRequestItemStore[] = results.map((item) => {\n                  return {\n                    _id: item._id,\n                    processStatus: itemStatus.PENDING,\n                    andesData: item,\n                    excelData: {\n                      vin: excelDataItemByCode[item.code].vin,\n                      material: excelDataItemByCode[item.code].material,\n                      code: excelDataItemByCode[item.code].code,\n                      count: 0\n                    },\n                    errors: [],\n                    checked: false\n                  };\n                });\n                this.setState({\n                  requestItems,\n                  countItemsByStatus: {\n                    [itemStatus.PENDING]: results.length,\n                    [itemStatus.IN_PROCESS]: 0,\n                    [itemStatus.READY]: 0,\n                    [itemStatus.ERROR]: 0\n                  },\n                  loading: false\n                }, () => {\n                  this.checkItems();\n                });\n              }\n            });\n        } else {\n          this.setState({\n            loading: false\n          });\n          swal!(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene unidades.`,\n            'error'\n          );\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private checkItems() {\n    const pendings = this.itemsByStatus(itemStatus.PENDING);\n    if (pendings.length) {\n      let item = pendings[0];\n      item = this.updateItemStatusByID(item, itemStatus.IN_PROCESS);\n      this.apiService\n        .checkItemMassAllocation(item)\n        .then((response: AxiosResponse) => {\n          const { data: integrationData, errors } = response.data;\n          this.updateItemStatusByID({\n              ...item,\n              integrationData: integrationData?.length ? integrationData[0] : integrationData,\n              errors\n            },\n            response.data.errors.length ? itemStatus.ERROR : itemStatus.READY,\n            this.checkItems\n          );\n        })\n        .catch((error) => {\n          if (error.status === 400) {\n            swal!('Asignador masivo de unidades', error.data.message, 'error');\n          } else {\n            this.apiService.errorHandler(error);\n          }\n        });\n    }\n  }\n\n  private customTotal(from: any, to: any, size: any) {\n    return (\n      <span className='react-bootstrap-table-pagination-total text-ellipsis' style={{ fontSize: '14px' }}>\n        &nbsp;&nbsp;Mostrando registros del {from} al {to} de {size} registros.\n      </span>\n    );\n  }\n\n  private answerProcessitems() {\n    const hasErrors = this.itemsByStatus(itemStatus.ERROR);\n    if (hasErrors.length) {\n      swal({\n        title: '¿Estás seguro que deseas continuar?',\n        text: `Hay ${hasErrors.length} unidades con errores, solo se procesarán los que no tienen ningún problema. `,\n        icon: 'warning',\n        dangerMode: true,\n        buttons: {\n          cancel: 'Cancelar' as any,\n          confirm: {\n            text: 'Sí'\n          }\n        }\n      }).then((accept) => {\n        if (accept) {\n          this.processItems();\n        }\n      });\n    } else {\n      this.processItems();\n    }\n  }\n\n  private processItems() {\n    const toProcess = this.itemsByStatus(itemStatus.READY);\n    if (toProcess.length) {\n      let item = toProcess[0];\n      this.setState({\n        sending: true\n      });\n      // item = this.updateItemStatusByID(item, itemStatus.IN_PROCESS);\n      this.apiService\n        .processItemMassAllocation({ item })\n        // .then((response: AxiosResponse) => {\n        .then(() => {\n          this.updateItemStatusByID({\n              ...item\n            },\n            itemStatus.UPDATED,\n            this.processItems\n          );\n          if (toProcess.length === 1) {\n            swal({\n              title: 'Asignador masivo de unidades',\n              text: 'Se completo satisfactoriamente el proceso de asignación, ¿Deseas cargar otro archivo?',\n              icon: 'success',\n              // dangerMode: true,\n              buttons: {\n                cancel: 'Volver a solicitudes' as any,\n                confirm: {\n                  text: 'Sí'\n                }\n              }\n            }).then((accept) => {\n              if (accept) {\n                this.setState({\n                  requestItems: []\n                });\n              } else {\n                const { history } = this.props;\n                history.push('/requests/vehicles/');\n              }\n            });\n          }\n        })\n        .catch((error) => {\n          if (error.status === 400) {\n            swal!('Asignador masivo de unidades', error.data.message, 'error');\n          } else {\n            this.apiService.errorHandler(error);\n          }\n          this.setState({\n            sending: false\n          });\n        });\n    } else {\n      this.setState({\n        sending: false\n      });\n    }\n  }\n\n  private updateItemStatusByID(item: IRequestItemStore, processStatus: itemStatus, callback?: () => void): any {\n    const { requestItems, countItemsByStatus } = this.state;\n    this.setState({\n      countItemsByStatus: {\n        ...countItemsByStatus,\n        [processStatus]: countItemsByStatus[processStatus] + 1,\n        [item.processStatus]: countItemsByStatus[item.processStatus] - 1\n      },\n      requestItems: requestItems.map((requestItem) => {\n        if (requestItem._id === item._id) {\n          return {\n            ...item,\n            processStatus\n          };\n        }\n        return requestItem;\n      })\n    }, callback);\n    return { ...item, processStatus };\n  }\n\n  private itemsByStatus(processStatus: itemStatus) {\n    const { requestItems } = this.state;\n    return requestItems\n      .filter((item) => item.processStatus === processStatus);\n  }\n\n  private errorsFormatter(_: string, row: any) {\n    if ([itemStatus.UPDATED].includes(row.processStatus)) {\n      return <div className={'text-green'} style={{ fontSize: '12px' }}>\n        Asignación procesada.\n      </div>;\n    }\n    return row.errors.length > 0\n      ?\n      <div> {\n        row.errors.map((error: any, index: any) => (\n          <div key={index} className={'text-red'} style={{ fontSize: '12px' }}>\n            {error.message}\n          </div>\n        ))\n      }</div>\n      : <div className={'text-green'} style={{ fontSize: '12px' }}>\n        {\n          [itemStatus.READY].includes(row.processStatus) ? <>{'Sin errores.'}</> : ''\n        }</div>;\n  }\n\n  private statusFormatter(_: string, row: any) {\n    if ([itemStatus.READY, itemStatus.ERROR].includes(row.processStatus)) {\n      return row.errors.length > 0\n        ? <i className={'fa fa-circle text-red'} />\n        : <i className={'fa fa-circle text-green'} />;\n    }\n    if ([itemStatus.UPDATED].includes(row.processStatus)) {\n      return <i className={'fa fa-check-circle text-green'} />;\n    }\n    return '';\n  }\n\n  private requestedVehicle(_: string, row: IRequestItemStore) {\n    return (\n      <div className='text-muted text-sm'>\n        <div><strong>VIN </strong>\n           <strong className={'text-primary'}>{row.andesData.car.vin?.length?row.andesData.car.vin: '-'}</strong>\n        </div>\n        <div><strong>MATERIAL </strong>\n          <ShowIf\n            condition={!!row.excelData?.material?.length}\n            alternative={<strong className={'text-primary'}>{row.andesData.car.material}</strong>}\n          >\n            {row.andesData.car.material} <i className={'fa fa-fw fa-angle-double-right'} /> <strong\n            className={'text-primary'}>{row.excelData?.material}</strong>\n          </ShowIf>\n        </div>\n        <div><strong>MARCA </strong>{row.andesData.car.brand}</div>\n        <div><strong>MODELO </strong>{row.andesData.car.denomination}</div>\n        <div><strong>COLOR </strong>\n          <ShowIf condition={!!row.andesData.car.color?.length}>\n            <strong\n              className={'text-primary'}\n            >\n              {row.andesData.car.color}\n            </strong>\n          </ShowIf> <ShowIf\n            condition={\n              !!(row.andesData.car.firstColorOption?.length ||\n              row.andesData.car.secondColorOption?.length ||\n              row.andesData.car.thirdColorOption?.length)\n            }\n          >(\n            {row.andesData.car.firstColorOption ?? ''}\n            {\n              row.andesData.car.firstColorOption && row.andesData.car.secondColorOption\n                ?`, ${row.andesData.car.secondColorOption}`\n                : row.andesData.car.secondColorOption ?? ''\n            }\n            {\n              (row.andesData.car.firstColorOption || row.andesData.car.secondColorOption) && row.andesData.car.thirdColorOption\n                ?`, ${row.andesData.car.thirdColorOption}`\n                : row.andesData.car.thirdColorOption ?? ''\n            }\n            )\n          </ShowIf>\n        </div>\n      </div>\n    );\n  }\n\n  private assignVehicle(_: string, row: IRequestItemStore) {\n    return (\n      <div className='text-muted text-sm'>\n        <div><strong>VIN </strong>\n          <strong className={`text-primary`} style={{ textDecoration: !row.excelData.vin?.length ? 'line-through' : '' }}>\n            {\n              row.integrationData?.vin?.length\n                ? row.integrationData?.vin\n                : row.andesData.car.vin?.length\n                  ? row.andesData.car.vin\n                  : '-'\n            }\n          </strong>\n        </div>\n        <div>\n          <strong>MATERIAL </strong>\n          <strong className={'text-primary'}>{row.integrationData?.material ?? row.andesData.car.material}</strong>\n        </div>\n        <div><strong>MARCA </strong>\n          <span className={'text-primary'}>\n            {row.integrationData?.brand  ?? row.andesData.car.brand}\n          </span>\n        </div>\n        <div><strong>MODELO </strong>\n          <span className={'text-primary'}>\n            {row.integrationData?.denomination ?? row.andesData.car.denomination}\n          </span>\n        </div>\n        <div><strong>COLOR </strong>\n          <strong\n            className={'text-primary'}\n          >\n            {row.integrationData?.color ?? row.andesData.car.color}\n          </strong>\n        </div>\n      </div>\n    );\n  }\n\n  private codeFormatter(_: string, row: IRequestItemStore) {\n    return (\n      <div className={`${row.errors.length ? 'text-red' : 'text-muted'}`}>\n        <strong>\n          {row.excelData.code}\n        </strong>\n      </div>\n    );\n  }\n\n  private vinFormatter(_: string, row: IRequestItemStore) {\n    // console.log(row);\n    if (row.errors.length) {\n      return (\n        <div>\n          <span className={'text-red'}>{row.excelData.vin?.length ? row.excelData.vin : '-'}</span>\n          <div className='text-sm text-muted'><i className='fa fa-fw fa-info-circle' /> No se realizará ningun cambio</div>\n        </div>\n      );\n    }\n    if (row.andesData.car?.vin) {\n      if (!row.excelData.vin?.length) {\n        return (\n          <div>\n            <span className={'text-red'} style={{ textDecoration: 'line-through' }}>{row.andesData.car.vin}</span>\n            <ShowIf condition={!row.errors.length}>\n              <div className='text-sm text-muted'><i className='fa fa-fw fa-info-circle' /> Elimina VIN de la unidad</div>\n            </ShowIf>\n          </div>\n        );\n      }\n      return (\n        <div>\n          {row.excelData.vin}\n          <ShowIf condition={!row.errors.length}>\n            <div className='text-sm text-muted'><i\n              className='fa fa-fw fa-info-circle' /> {row.excelData.vin === row.andesData.car.vin ? 'No se detectaron cambios' : 'Cambia VIN de la unidad'}\n            </div>\n          </ShowIf>\n        </div>\n      );\n    }\n    if (!row.excelData.vin?.length) {\n      return (\n        <div>\n          <span className={'text-muted'}>{row.excelData.vin?.length ? row.excelData.vin : '-'}&nbsp;</span>\n          <div className='text-sm text-muted'><i className='fa fa-fw fa-info-circle' /> No se ingreso VIN</div>\n        </div>\n      );\n    }\n    return (\n      <div className={!row.errors.length ? 'text-green' : 'text-red'}>\n        {row.excelData.vin}\n        <ShowIf condition={!row.errors.length}>\n          <div className='text-sm text-muted'><i className='fa fa-fw fa-info-circle' /> Asigna VIN de la unidad</div>\n        </ShowIf>\n      </div>\n    );\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestImportVINSView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport * as moment from 'moment-timezone';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { IRequestItemsState } from '../../actions/requestItems.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport Axios, { AxiosError } from 'axios';\nimport { IRequestSetting } from '../../../../../../src/app/interfaces/teamSetting.interface';\nimport { ISalesChannel } from '../../../../../../src/request/interfaces/salesChannel.interface';\nimport { IOperationType } from '../../../../../../src/request/interfaces/operationType.interface';\nimport { IReason } from '../../../../../../src/request/interfaces/reason.interface';\nimport { IVenue } from '../../../../../../src/app/interfaces/venue.interface';\nimport RequestImportForm from './RequestImportForm/RequestImportForm';\nimport { submit } from 'redux-form';\nimport { requestSettings } from './defaults';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<any>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  requests: any[];\n  canDrop: boolean;\n  loading: boolean;\n  sending: boolean;\n  venues: IVenue[];\n  reasons: IReason[];\n  channels: ISalesChannel[];\n  operationTypes: IOperationType[];\n  requestSettings: IRequestSetting;\n}\n\ndeclare let window: IWindow;\n\nclass RequestImportView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n  readonly inputFile: RefObject<HTMLInputElement>;\n  readonly api: ApiService;\n\n  readonly state: IStateType = {\n    error: null,\n    canDrop: false,\n    loading: true,\n    sending: false,\n    requests: [],\n    venues: [],\n    reasons: [],\n    channels: [],\n    operationTypes: [],\n    requestSettings\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Importador de solicitudes';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.parseRequestItem = this.parseRequestItem.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n    this.checkSameVenue = this.checkSameVenue.bind(this);\n    this.api = new ApiService();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n    const api: ApiService = new ApiService();\n    Axios\n      .all([\n        this.api.getOperationTypes({ page: 1, pageSize: 200 }),\n        this.api.getVenues({ page: 1, pageSize: 200, noPopulate: true }),\n        this.api.getSalesChannel({ page: 1, pageSize: 200 }),\n        this.api.getReasons({ page: 1, pageSize: 200 }),\n        this.api.getTeamSettings()\n      ])\n      .then(Axios.spread((\n        operationTypes,\n        venues,\n        channels,\n        reasons,\n        teamSettings\n      ) => {\n        this.setState({\n          requestSettings: teamSettings.data.request,\n          venues: venues.data.results,\n          reasons: reasons.data.results,\n          channels: channels.data.results,\n          operationTypes: operationTypes.data.results,\n          loading: false\n        });\n      }))\n      .catch((err: AxiosError) => {\n        api.errorHandler(err);\n      });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loading, requests, sending, channels, operationTypes, reasons, venues\n    } = this.state;\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.2' cAction='Importar solicitudes por lote'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Importar solicitudes por lote</h3>\n              <div className='pull-right box-tools'>\n                <ShowIf condition={!requests.length}>\n                  <button\n                    className='btn btn-sm btn-primary'\n                    onClick={this.downloadTemplate}\n                    style={{ marginRight: '5px' }}>\n                    <i className='fa fa-fw fa-download' /> Descargar Formato\n                  </button>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='box-body margin'>\n              {\n                requests.length ?\n                  <>\n                    <RequestImportForm\n                      channels={channels}\n                      operationTypes={operationTypes}\n                      reasons={reasons}\n                      venues={venues}\n                      onSubmit={this.sendCreate}\n                      initialValues={{\n                        requests: requests\n                      }}\n                    />\n                    <div className='row'>\n                      <div className='col col-md-6'>\n                        {/*  <strong>Total de :</strong> {requests.length}*/}\n                      </div>\n                      <div className='col-md-6 text-right'>\n                        <button className='btn btn-sm btn-primary' onClick={this.downloadTemplate}>\n                          <i className='fa fa-fw fa-download' /> Descargar Formato\n                        </button>\n                        <button className='btn btn-sm btn-default' onClick={this.clickUploadFile} style={{ marginLeft: '5px' }}>\n                          <i className='fa fa-fw fa-cogs' /> Cambiar configuración\n                        </button>\n                      </div>\n                    </div>\n                  </>\n                  :\n                  <div className='row'>\n                    <div className='col col-md-12'>\n                      <div className='form-group'>\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className='upload-file text-center pointer'\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className='fa fa-2x fa-cloud-upload' /><br />\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type='file'\n                onChange={this.handleChangeInputFile}\n                style={{ display: 'None' }}\n                ref={this.inputFile}\n                accept='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel'\n              />\n            </div>\n            <div className='box-footer text-right'>\n              <button\n                className='btn btn-sm btn-default'\n                onClick={() => this.props.history.push('/requests/vehicles/')}\n              >\n                Cancelar\n              </button>\n              <ShowIf condition={!!requests.length}>\n                <button\n                  className='btn btn-sm btn-primary'\n                  style={{ marginLeft: '5px' }}\n                  onClick={() => this.props.dispatch(submit('requestImportForm'))}\n                  disabled={sending}\n                >\n                  <ShowIf condition={sending} alternative={'Actualizar'}>\n                    <React.Fragment>\n                      <i className='fa fa-fw fa-spin fa-spinner' /> Actualizando...\n                    </React.Fragment>\n                  </ShowIf>\n                </button>\n              </ShowIf>\n            </div>\n            <ShowIf condition={loading || sending}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const { files } = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      ['Numero solicitud']: '',\n      ['Partida']: '',\n      ['Tipo operacion']: '',\n      ['Canal']: '',\n      ['Motivo']: '',\n      ['Vendedor']: '',\n      ['Cliente']: '',\n      ['Origen']: '',\n      ['Destino']: '',\n      ['Factura']: '',\n      ['BL']: '',\n      ['Chasis']: '',\n      ['Motor']: '',\n      ['Marca']: '',\n      ['Modelo']: '',\n      ['Color']: '',\n      ['Tipo']: '',\n      ['Cilindrada']: '',\n      ['Traccion']: '',\n      ['Ano Comercial']: '',\n      ['Ano Fabricacion']: '',\n      ['Monto']: '',\n      ['Seguro']: '',\n      ['Peso']: '',\n      ['Gas']: '',\n      ['AP']: '',\n      ['Pais Origen']: '',\n      ['Observacion']: '',\n      ['Fecha de embarque']: '',\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Propiedades');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_request_settings.xlsx');\n  }\n\n  private parseRequestItem(requestItem: any) {\n    const { venues, reasons } = this.state;\n    return {\n      ['reason']: reasons.find((reason) => {\n        return reason.name?.trim().toLowerCase() === requestItem['Motivo']?.trim().toLowerCase();\n      })?._id,\n      ['vin']: requestItem['Chasis'],\n      ['engineNumber']: requestItem['Motor'],\n      ['brand']: requestItem['Marca'],\n      ['denomination']: requestItem['Modelo'],\n      ['color']: requestItem['Color'],\n      ['type']: requestItem['Tipo'],\n      ['client']: requestItem['Cliente'],\n      ['entry']: requestItem['Partida'],\n      ['invoice']: requestItem['Factura'],\n      ['origin']: venues.find((venue) => {\n        return this.checkSameVenue(venue, requestItem['Origen']);\n        // return venue.name?.trim().toLowerCase() === requestItem['Origen']?.trim().toLowerCase();\n      })?._id,\n      ['destination']: venues.find((venue) => {\n        return this.checkSameVenue(venue, requestItem['Destino']);\n        // return venue.name?.trim().toLowerCase() === requestItem['Destino']?.trim().toLowerCase();\n      })?._id,\n      ['bl']: requestItem['BL'],\n      ['engineSize']: requestItem['Cilindrada'],\n      ['driveType']: requestItem['Traccion'],\n      ['businessYear']: requestItem['Ano Comercial'],\n      ['manufacturingYear']: requestItem['Ano Fabricacion'],\n      ['price']: requestItem['Monto'],\n      ['insurancePrice']: requestItem['Seguro'],\n      ['weight']: requestItem['Peso'],\n      ['gas']: requestItem['Gas'],\n      ['ap']: requestItem['AP'],\n      ['countryOrigin']: requestItem['Pais Origen'],\n      ['observation']: requestItem['Observacion'],\n      ['shippingDate'] : requestItem['Fecha de embarque'] ?\n        moment(requestItem['Fecha de embarque']).format() : ''\n    };\n  }\n\n  private checkSameVenue(venueA: any, venueB: any){\n    const sameName = venueA.name?.trim().toLowerCase() === venueB?.trim().toLowerCase();\n    const foundCode = venueB?.length && (venueA.code?.trim().toLowerCase() === venueB?.trim().toLowerCase());\n    return sameName || foundCode\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loading: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        const { channels, operationTypes } = this.state;\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = 'Propiedades' in workbook.Sheets\n          ? XLSX.utils.sheet_to_json(workbook.Sheets.Propiedades)\n          : [];\n        if (excelData.length >= 1) {\n          const requestByNumber = excelData.reduce<any>((acc: any, cur: any) => {\n            const key = cur['Numero solicitud'];\n            if (!acc.hasOwnProperty(key)) {\n              acc[key] = {\n                ['number']: key,\n                ['sellerText']: cur['Vendedor'],\n                ['channel']: channels.find((channel) => {\n                  return channel.name?.trim().toLowerCase() === cur['Canal']?.trim().toLowerCase();\n                })?._id,\n                ['operationType']: operationTypes.find((operationType) => {\n                  return operationType.name?.trim().toLowerCase() === cur['Tipo operacion']?.trim().toLowerCase();\n                })?._id,\n                cars: [this.parseRequestItem(cur)]\n              };\n            } else {\n              acc[key] = {\n                ...acc[key],\n                cars: [...acc[key].cars, this.parseRequestItem(cur)]\n              };\n            }\n            return acc;\n          }, {});\n\n          this.setState({\n            loading: false,\n            requests: Object.values(requestByNumber)\n              .sort((a: any, b: any) => {\n                return a['number'].localeCompare(b['number'], 'en', { numeric: true });\n              })\n          }, () => {\n            console.log('this.state.requests', this.state.requests);\n          });\n        } else {\n          swal!(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene unidades.`,\n            'error'\n          );\n          this.setState({\n            loading: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(data: any): void {\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .importRequests(data)\n      .then((response: any) => {\n        const { message } = response.data;\n        console.log('message', message);\n        history.push('/requests/vehicles/');\n        setTimeout(() => {\n          swal!('Importador de solicitudes', message, 'success');\n        }, 200);\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((error) => {\n        if (error.status === 400) {\n          swal!('Importador de solicitudes', error.data.message, 'error');\n        } else {\n          api.errorHandler(error);\n        }\n        this.setState({\n          sending: false\n        });\n      });\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestImportView);\n","import * as moment from 'moment-timezone';\nimport * as React from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { ICarrier } from '../../../../../../../src/app/interfaces/carrier.interface';\nimport { IReason } from '../../../../../../../src/request/interfaces/reason.interface';\nimport { IRequest } from '../../../../../../../src/request/interfaces/request.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { IRequestItemStatus } from '../../../../../../../src/request/interfaces/requestItemStatus.interface';\nimport { tabStatusAction, updateRequestItemInListThunkAction } from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ShowIf from '../../Utils/ShowIf';\nimport CopyText from '../../Utils/CopyText';\nimport RequestStatusDislay from '../StatusComponents/RequestStatusDislay';\n\ndeclare let window: IWindow;\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requests: IRequestsState;\n  key: any;\n  request: IRequest;\n  reasons: IReason[];\n  carriers: ICarrier[];\n  requestItemStatus: IRequestItemStatus[];\n  updateRequestItemInListReduxAction: (idRequest: string, item: IRequestItem) => void;\n  tabStatusAction: (request: string) => void;\n}\n\ninterface IStateType {\n  open: boolean;\n  error: Error | null;\n}\n\nexport const getColorForPercentage = (value: number): string => {\n  if (value < 11) {\n    return '#00c0ef';\n  } else if (value < 80) {\n    return '#f39c12';\n  } else if (value < 100) {\n    return '#337ab7';\n  } else {\n    return '#00a65a';\n  }\n};\n\nclass RequestListDetail extends React.Component<IPropsType, IStateType> {\n\n  readonly state = {\n    error: null,\n    open: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.goToDetail = this.goToDetail.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { requests, request, reasons, requestItemStatus } = this.props;\n    const { requestSettings } = requests;\n    const open = this.props.requests.requestOpen.includes(request._id);\n    const canChangeRequest = hasPermission(window.user, 'changeRequest');\n    return (\n      <React.Fragment>\n        <div id={`request-${request._id}`} className='row request bg-request-title background-transition'>\n          <div\n            className='col-sm-1 col-xs-1 col-md-1 col-lg-1 pointer center'\n            onClick={() => this.goToDetail(request._id)}\n          >\n            {/* <i className=\"fa fa-circle status-circle-red\" /> */}\n            <strong className='text-underline'>\n              #{request.number}\n            </strong>&nbsp;\n          </div>\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n            <strong className='text-info'>{request.channel ? request.channel.name : ''}</strong>\n            {/* {\n              request.fleet ?\n                <i className=\"fa fa-check-circle-o text-green\" />\n                : null\n            } */}\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>{request.createdBy?.firstName.length ? `${request.createdBy?.firstName} ${request.createdBy?.lastName}`: '-'}</div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'><strong className='text-primary'>{request.destination.name}</strong></div>\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1 text-muted'>\n            {\n              request.items.length\n            }\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2 text-muted'>\n            {moment(request.createdAt).format('DD-MM-YY')}\n          </div>\n          <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2 text-muted'>\n            {moment(request.updatedAt).format('DD-MM-YY')}\n          </div>\n          {/* <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1 center\"> */}\n          {/* 10 */}\n          {/* </div> */}\n          <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1 chevron pointer' onClick={() => this.props.tabStatusAction(request._id)}>\n            {\n              open ? (<i className='fa fa-chevron-up' />) : (<i className='fa fa-chevron-down' />)\n            }\n          </div>\n        </div>\n        <div className='table-request' style={{ display: open ? 'block' : 'none' }}>\n          <ShowIf condition={!this.props.requests.requestItemsById.hasOwnProperty(request._id)}>\n            <div className='text-center' style={{\n              padding: '10px',\n              borderBottom: '1px solid #e1e1e1',\n              borderLeft: '1px solid #e1e1e1',\n              borderRight: '1px solid #e1e1e1'\n            }}>\n              <i className='fa fa-spinner fa-spin text-purple' />\n            </div>\n          </ShowIf>\n          <ShowIf condition={this.props.requests.requestItemsById.hasOwnProperty(request._id)}>\n            <table className='table table-xd table-striped table-hover'>\n              <thead>\n              <tr style={{ backgroundColor: '#f9f9f9' }}>\n                <th className='middle' style={{ width: '28px' }} />\n                <th className='middle' style={{ width: '100px' }}>Solicitud</th>\n                <th className='middle' style={{ width: '160px' }}>VIN</th>\n                <ShowIf condition={requestSettings.entry}>\n                  <th>Partida</th>\n                </ShowIf>\n                <ShowIf\n                  condition={\n                    ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                    requestSettings.material\n                  }\n                >\n                  <th\n                    className='middler pointer'\n                    style={{ width: '70px' }}\n                  >\n                    Material\n                  </th>\n                </ShowIf>\n                <th className='middle' style={{ width: '180px' }}>Descripción</th>\n                <th className='middle' style={{ width: '120px' }}>Color</th>\n                <ShowIf condition={requestSettings.ticket}>\n                  <th className='middle-center pointer' style={{ width: '60px' }}>\n                    Ticket\n                  </th>\n                  <th className='middle-center pointer' style={{ width: '60px' }}>\n                    Carta\n                  </th>\n                </ShowIf>\n                {/*<th className='middle' style={{ width: '110px' }}>Estado</th>*/}\n                <th>OT</th>\n                <th>F. emisión</th>\n                <th>F. carga</th>\n                <th>F. arribo</th>\n                <th className='middle-center' style={{ width: '20px' }}></th>\n                <th className='middle' />\n                {/* <th className=\"middle-center\">Equip. / Carroc. / Preentrega</th> */}\n                <ShowIf condition={requestSettings.reason && false}>\n                  <th className='middle' style={{ width: '150px' }}>Motivo</th>\n                </ShowIf>\n                {/* <th className=\"middle\" >Transporte</th>\n                <th  className=\"middle\" style={{ width: '70px' }}>Fecha carga</th>\n                <th className=\"middle\"  style={{ width: '70px' }}>Fecha llegada</th> */}\n                <th />\n              </tr>\n              </thead>\n              <tbody>\n              {\n                (this.props.requests.requestItemsById[request._id] || []).map((item: any) => (\n                  <tr key={item._id} id={`request-item-${item._id}`} className={'background-transition'}>\n                    <td className='middle-center'>\n                      {item.priority ?\n                        <i className='fa fa-star text-yellow' />\n                        : null}\n                    </td>\n                    <td className='middle'>\n                      <RequestStatusDislay requestItem={item} showNumber={true} />\n                    </td>\n                    <td className={`middle`}>\n                      <ShowIf condition={item.car.vin?.length}>\n                        <CopyText value={item.car.vin}>\n                          <strong\n                            className={'text-underline text-primary pointer'}\n                            onClick={() => {\n                              this.props.history.push(parseReplicableURL(`/settings/cars/${item.car._id}/`));\n                            }}\n                          >\n                            {item.car.vin}\n                          </strong>\n                        </CopyText>\n                      </ShowIf>\n                    </td>\n                    <ShowIf condition={requestSettings.entry}>\n                      <td className='middle'>\n                        {\n                          item.car.entry && item.car.entry.length ? item.car.entry : null\n                        }\n                      </td>\n                    </ShowIf>\n                    <ShowIf\n                      condition={\n                        ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                        requestSettings.material\n                      }\n                    >\n                      <td className='middle text-muted'>\n                        {\n                          item.car.material?.length ? item.car.material : null\n                        }\n                      </td>\n                    </ShowIf>\n                    <td className='middle text-muted'>\n                      <strong>{item.car.brand}</strong><br />{`${item.car.denomination}`}\n                    </td>\n                    <td className='middle text-muted'>\n                      <ShowIf condition={!!item.car?.color}>\n                        <strong className='text-primary'>{item.car?.color}</strong><br />\n                      </ShowIf>\n                      {item.car?.firstColorOption}\n                      {item.car?.secondColorOption?.length ? `, ${item.car?.secondColorOption}` : ''}{item.car?.thirdColorOption?.length ? `, ${item.car?.thirdColorOption}` : ''}\n                    </td>\n                    <ShowIf condition={requestSettings.ticket}>\n                      <td className='middle-center'>\n                        <div\n                          data-toggle='tooltip'\n                          data-placement='top'\n                          className={`${request?.advancePaymentInformation?.files?.length ? 'pointer' : ''}`}\n                          title={request?.advancePaymentInformation?.number ?? '-'}\n                          onClick={() => this.openBlank(request.advancePaymentInformation.files[0].file.url)}\n                        >\n                          {\n                            //request.advancePaymentInformation.files[0].file.url\n                            request?.advancePaymentInformation?.files?.length ?\n                              <i\n                                className='fa fa-check-circle text-green'\n                              /> : ''\n                          }\n                        </div>\n                      </td>\n                    </ShowIf>\n                    <ShowIf condition={requestSettings.ticket}>\n                      <td className='middle-center'>\n                        <div\n                          data-toggle='tooltip'\n                          data-placement='top'\n                          className={`${request?.advancePaymentInformation?.letters?.length ? 'pointer' : ''}`}\n                          title={request?.advancePaymentInformation?.letters[0]?.file?.name ?? '-'}\n                          onClick={() => this.openBlank(request.advancePaymentInformation.letters[0].file.url)}\n\n                        >\n                          {\n                            //request.advancePaymentInformation.files[0].file.url\n                            request?.advancePaymentInformation?.letters?.length ?\n                              <i\n                                className='fa fa-check-circle text-green'\n                              /> : ''\n                          }\n                        </div>\n                      </td>\n                    </ShowIf>\n                    {\n                      canChangeRequest && false ?\n                        <td className='middle'>\n                          <select className='form-control select-sm font-12' value={item.status?._id ?? ''}\n                                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                    this.props.updateRequestItemInListReduxAction!(request._id, {\n                                      ...item,\n                                      status: e.target.value\n                                    });\n                                  }}\n                          >\n                            <option value='' disabled={true}>-</option>\n                            {\n                              requestItemStatus.map((req) => (\n                                <option key={req._id} value={req._id}>{req.name}</option>\n                              ))\n                            }\n\n                          </select>\n                        </td> : null\n                      // <td className='middle'>{item.status?.name}</td>\n                    }\n                    <td\n                      className={`middle ${item.transmittal?.number ? 'pointer' : ''}`}\n                      onClick={item.transmittal?.number ? () => this.openOT(\n                        item.transmittal.number.toString(),\n                        item?.transmittal?._id,\n                        item?.transmittalItem?._id\n                      ) : undefined}\n                    >\n                      <strong className={'text-underline'}>\n                        {item?.transmittal?.number ? `#${item?.transmittal?.number}` : ''}\n                      </strong>\n                    </td>\n                    <td\n                      className='middle text-muted'>{item.transmittalItem?.loadingDate ? moment(item.transmittalItem.loadingDate).format('DD-MM-YY') : ''}</td>\n                    <td\n                      className='middle text-muted'>{item?.transmittalItem?.revisions?.length ? moment(item.transmittalItem.revisions[item.transmittalItem.revisions.length - 1].createdAt).format('DD-MM-YY') : ''}</td>\n                    <td\n                      className='middle text-muted'>{item?.transmittal?.revision ? moment(item.transmittal.revision.createdAt).format('DD-MM-YY') : ''}</td>\n                    {/*<td>{item.transmittalItem?.arrivalDate ? moment(item.transmittalItem.arrivalDate).format('DD-MM-YYYY') : '-'}</td>*/}\n                    <td\n                      className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n                      onClick={item.files?.length ? () => this.downloadFiles(item) : undefined}\n                    >\n                      {\n                        item.files?.length ?\n                          <i\n                            className='fa fa-paperclip'\n                            data-toggle='tooltip'\n                            data-placement='top'\n                            title={`${item.files.length} archivos adjuntos.`}\n                          /> : null\n                      }\n                    </td>\n                    <td className='middle-center'>\n                      {\n                        item.observation && item.observation.length ?\n                          <i\n                            className='fa fa-comment'\n                            data-toggle='tooltip'\n                            data-placement='top'\n                            title={item.observation}\n                          /> : null\n                      }\n                    </td>\n                    {/* <td className=\"middle\">\n                      <div className=\"flex-wrap\">\n                        <div\n                          className={`flex-wrap-item-center ${item.equipment ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Accesorización\"\n                        >\n                          <i className=\"material-icons\">library_add</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.body ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Carrocero\"\n                        >\n                          <i className=\"material-icons\">rv_hookup</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.washed ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Pre-Lavado\"\n                        >\n                          <i className=\"material-icons\">local_car_wash</i>\n                        </div>\n                        <div\n                          className={`flex-wrap-item-center ${item.review ? '' : 'text-gray'}`}\n                          data-toggle=\"tooltip\"\n                          data-placement=\"top\"\n                          title=\"Inspección Pre-entrega\"\n                        >\n                          <i className=\"material-icons\">build</i>\n                        </div>\n                      </div>\n                    </td> */}\n                    <ShowIf condition={requestSettings.reason && false}>\n                      {\n                        canChangeRequest ?\n                          <td className='middle'>\n                            <select\n                              className='form-control select-sm font-12' value={item.reason?._id ?? ''}\n                              onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                this.props.updateRequestItemInListReduxAction!(request._id, {\n                                  ...item,\n                                  reason: e.target.value\n                                });\n                              }}\n                            >\n                              <option value='' disabled={true}>-</option>\n                              {\n                                reasons.map((reason) => (\n                                  <option key={reason._id} value={reason._id}>{reason.name}</option>\n                                ))\n                              }\n                            </select>\n                          </td> :\n                          <td className='middle'>{item.reason?.name}</td>\n                      }\n                    </ShowIf>\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <select className=\"form-control select-sm font-12\" value={item.carrier?._id ?? ''}\n                            onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                carrier: !e.target.value.length ? null : e.target.value\n                              });\n                            }}\n                          >\n                            <option value=\"\">-</option>\n                            {\n                              carriers.map((carrier) => (\n                                <option key={carrier._id} value={carrier._id}>{carrier.name}</option>\n                              ))\n                            }\n                          </select>\n                        </td> :\n                        <td className=\"middle\">{item.carrier?.name}</td>\n                        */\n                    }\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <DateRangePicker\n                            className={'input-sm'}\n                            value={item.uploadDate}\n                            onChange={(e) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                uploadDate: e\n                              });\n                            }}\n                          />\n                        </td> :\n                        <td className=\"middle\">{item.uploadDate ? moment(item.uploadDate).format('DD-MM-YY') : '-'}</td>\n                        */\n                    }\n                    { /*\n                      canChangeRequest ?\n                        <td className=\"middle\">\n                          <DateRangePicker\n                            className={'input-sm'}\n                            value={item.estimatedArrival}\n                            onChange={(e) => {\n                              this.props.updateRequestItemInListReduxAction!(request._id, {\n                                ...item,\n                                estimatedArrival: e\n                              });\n                            }}\n                          />\n                        </td> :\n                        <td className=\"middle\">{item.estimatedArrival ? moment(item.estimatedArrival).format('DD-MM-YY') : '-'}</td>\n                        */\n                    }\n                    <td></td>\n                  </tr>\n                ))\n              }\n              </tbody>\n            </table>\n          </ShowIf>\n        </div>\n      </React.Fragment>\n    );\n  }\n\n  private openOT(number: string, transmittal: string, item: string) {\n    this.props.history.push(parseReplicableURL(`/transmittals?number=${number}&transmittal=${transmittal}&item=${item}`,\n      ['number', 'transmittal', 'item']));\n    // window.open(parseReplicableURL(`/transmittals/?number=${number}`), '_blank');\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    window.open(`/requests-item/${item._id}/download-files/`, '_blank');\n  }\n\n  private openBlank(url: string) {\n    window.open(decodeURI(url), '_blank');\n  }\n\n  private goToDetail(id: string): void {\n    this.props.history.push(parseReplicableURL(`/requests/${id}/`));\n  }\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemInListReduxAction: (idRequest: string, item: IRequestItem) => dispatch(updateRequestItemInListThunkAction(idRequest, item)),\n    tabStatusAction: (request: string) => dispatch(tabStatusAction(request))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestListDetail);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { Dispatch, ErrorInfo, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  createRequestItemActionInList,\n  deleteRequestActionInList,\n  deleteRequestItemActionInList,\n  getRequestsThunkAction,\n  updateRequestItemActionInList\n} from '../../../actions/requests.actions';\nimport { IRequestsState } from '../../../actions/requests.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport RequestListDetail from './RequestDetail';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requests: IRequestsState;\n  dispatch: Dispatch<IRequestsState>;\n  updateRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n  getRequestsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => void;\n  deleteRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n  deleteRequestActionInList: (id: string) => void;\n  createRequestItemActionInList: (idRequest: string, item: IRequestItem) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  private socket: Socket;\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Solicitudes';\n    this.create = this.create.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.changePage = this.changePage.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.requests.options;\n    const { page } = this.props.requests.pagination;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestsThunkAction(page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-list-${window.user.team._id}` });\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      this.props.updateRequestItemActionInList(data.idRequest, data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 300);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        this.props.deleteRequestItemActionInList(data.idRequest, data.item);\n      }, 300);\n    });\n\n    this.socket.on('DELETE_REQUEST', (data: any): void => {\n      const $item = $(`#request-${data.idRequest}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        this.props.deleteRequestActionInList(data.idRequest);\n      }, 300);\n    });\n\n    this.socket.on('CREATE_REQUEST', (): void => {\n      const { page } = this.props.requests.pagination;\n      const { orderBy, orderType } = this.props.requests.options;\n      this.props.getRequestsThunkAction(page, orderBy, orderType, true);\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      this.props.createRequestItemActionInList(data.idRequest, data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 300);\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requests.source) {\n      this.props.requests.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `request-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, requests, reasons, requestItemStatus, carriers\n    } = this.props.requests;\n    const { orderBy, orderType } = this.props.requests.options;\n    const { exporing } = this.state;\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.1'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Solicitudes <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                {/*<div className='btn-group btn-group-sm'>*/}\n                <ShowIf condition={hasPermission(window.user, 'createRequest')}>\n                  <button\n                    className='btn btn-sm btn-success'\n                    onClick={this.create}\n                    style={{ marginRight: '5px' }}\n                  >\n                    <i className='fa fa-fw fa-plus' /> Crear solicitud\n                  </button>\n                </ShowIf>\n                <ShowIf condition={requests.length > 0}>\n                  <button\n                    className='btn btn-sm btn-primary hidden-xs'\n                    onClick={this.exportExcel}\n                    disabled={exporing}\n                  >\n                    {\n                      exporing ? <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment>\n                        : <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                    }\n                  </button>\n                </ShowIf>\n                {/*</div>*/}\n              </div>\n            </div>\n            <div className='box-body table-responsive request-list no-padding'>\n              <ShowIf condition={requests.length > 0}>\n                <div className='row request bg-primary'>\n                  <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1 center pointer head-sorted' onClick={() => this.changeOrder('_id')}>\n                    <strong>SOL Nº</strong> <i\n                    className={`fa ${orderBy === '_id' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Canal</strong>\n                  </div>\n                  <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>\n                    <strong>Solicitante</strong>\n                  </div>\n                  <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2'>\n                    <strong>Destino</strong>\n                  </div>\n                  <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1'>\n                    <strong>Unidades</strong>\n                  </div>\n                  <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2  pointer head-sorted' onClick={() => this.changeOrder('createdAt')}>\n                    <strong>Creación</strong> <i\n                    className={`fa ${orderBy === 'createdAt' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  <div className='col-sm-2 col-xs-2 col-md-2 col-lg-2  pointer head-sorted' onClick={() => this.changeOrder('updatedAt')}>\n                    <strong>Actualización</strong> <i\n                    className={`fa ${orderBy === 'updatedAt' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                  </div>\n                  {/* <div className=\"col-sm-1 col-xs-1 col-md-1 col-lg-1 center\"> */}\n                  {/* <strong><i className=\"fa fa-comment\" /></strong> */}\n                  {/* </div> */}\n                  <div className='col-sm-1 col-xs-1 col-md-1 col-lg-1' />\n                </div>\n                {\n                  requests.map((request: any) => (\n                    <RequestListDetail\n                      request={request}\n                      requestItemStatus={requestItemStatus}\n                      reasons={reasons}\n                      carriers={carriers}\n                      key={request._id}\n                      {...this.props}\n                    />\n                  ))\n                }\n              </ShowIf>\n              <ShowIf condition={!loading && requests.length === 0}>\n                <div className='row'>\n                  <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                    <ImageLazyLoad\n                      url='/images/not_found.png'\n                      height={'200px'}\n                      style={{\n                        opacity: 0.5,\n                        maxHeight: '200px',\n                        marginBottom: '10px'\n                      }}\n                      replaceLoading={<i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />}\n                    /><br />\n                    <strong>No hay información para mostrar</strong>\n                  </div>\n                </div>\n              </ShowIf>\n            </div>\n            <div className='box-footer'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <ShowIf condition={pagination.pages > 1}>\n                    <div className='row'>\n                      <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                          <span className='react-bootstrap-table-pagination-total text-muted text-ellipsis'>\n                            &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 20 + 1} al {(pagination.page) * 20} de {pagination.count} registros.\n                          </span>\n                      </div>\n                      <div className='col-md-6'>\n                        <div className='text-right' style={{ marginRight: '15px' }}>\n                          <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                        </div>\n                      </div>\n                    </div>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <ShowIf condition={loading && requests.length === 0}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private changeOrder(key: string) {\n    const { page } = this.props.requests.pagination;\n    const { orderBy, orderType } = this.props.requests.options;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.getRequestsThunkAction(page, newOrderBy, newOrderType);\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/requests/create/'));\n  }\n\n  private changePage(page: number): void {\n    const { orderBy, orderType } = this.props.requests.options;\n    this.props.getRequestsThunkAction(page, orderBy, orderType);\n  }\n\n  public exportExcel() {\n    this.trackClick('Exportar');\n    window.open(`/requests/export/`, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/requests/export/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-solicitudes.xlsx`;\n    //     if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //       // IE workaround for \"HTML7007: One or more blob URLs were\n    //       // revoked by closing the blob for which they were created.\n    //       // These URLs will no longer resolve as the data backing\n    //       // the URL has been freed.\"\n    //       window.navigator.msSaveBlob(blob, fileName);\n    //     } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n\n}\n\nconst mapStateToProps = (state: { requests: IRequestsState }) => {\n  return {\n    requests: state.requests\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestsThunkAction(page, orderBy, orderType, hideLoading)),\n    createRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(createRequestItemActionInList(idRequest, item)),\n    updateRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(updateRequestItemActionInList(idRequest, item)),\n    deleteRequestItemActionInList: (idRequest: string, item: IRequestItem) => dispatch(deleteRequestItemActionInList(idRequest, item)),\n    deleteRequestActionInList: (id: string) => dispatch(deleteRequestActionInList(id))\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo, RefObject } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Dispatch } from 'redux';\nimport * as swal from 'sweetalert';\nimport * as XLSX from 'xlsx';\nimport { IRequestItemsState, RequestItemsReduxActions } from '../../actions/requestItems.types';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport ApiService from '../../utils/axios';\nimport ModalView from '../Modal/ModalView';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport { parseReplicableURL } from '../../utils/common';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<RequestItemsReduxActions>;\n}\n\ninterface IStateType {\n  error: Error | null;\n  properties: any[];\n  canDrop: boolean;\n  sending: boolean;\n  loadingSettings: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestUpdaterView extends TrackingBasePage<IPropsType, IStateType> {\n  title : string;\n\n  readonly inputFile: RefObject<HTMLInputElement>;\n\n  readonly state = {\n    error: null,\n    canDrop: false,\n    sending: false,\n    properties: [],\n    loadingSettings: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Actualización masiva';\n    this.inputFile = React.createRef();\n    this.clickUploadFile = this.clickUploadFile.bind(this);\n    this.handleDrop = this.handleDrop.bind(this);\n    this.dragOverHandler = this.dragOverHandler.bind(this);\n    this.dragEndHandler = this.dragEndHandler.bind(this);\n    this.dragLeaveHandler = this.dragLeaveHandler.bind(this);\n    this.handleChangeInputFile = this.handleChangeInputFile.bind(this);\n    this.downloadTemplate = this.downloadTemplate.bind(this);\n    this.processSettings = this.processSettings.bind(this);\n    this.sendCreate = this.sendCreate.bind(this);\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({error});\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidMount(): void {\n    super.componentDidMount();\n    window.scrollTo(0, 0);\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      loadingSettings, properties, sending\n    } = this.state;\n    return (\n      <AppContainer title=\"\" cMenu=\"3\" cSubMenu=\"3.2\" cAction=\"Actualización masiva\">\n        <section className=\"content\">\n          <div className=\"box\">\n            <div className=\"box-header with-border\">\n              <h3 className=\"box-title\">Actualización masiva</h3>\n              <div className=\"pull-right box-tools\">\n                {\n                  !properties.length?\n                    <button\n                      className=\"btn btn-sm btn-primary\"\n                      onClick={this.downloadTemplate}\n                      style={{marginRight: '5px'}}>\n                      <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                    </button>\n                    :null\n                }\n              </div>\n            </div>\n            <div className=\"box-body margin\">\n              {\n                properties.length?\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <table className=\"table table-striped\">\n                        <thead>\n                          <tr>\n                            <th>Propiedad</th>\n                            <th>Marca</th>\n                          </tr>\n                        </thead>\n                        <tbody>\n                          {\n                            properties.map((property: any) => {\n                              return (\n                                <tr key={property.key}>\n                                  <td>{property.key}</td>\n                                  <td>\n                                    {\n                                      property.brands.map((brand: string) => (\n                                        <React.Fragment key={brand}>- {brand}<br /></React.Fragment>)\n                                      )\n                                    }\n                                  </td>\n                                </tr>\n                              );\n                            })\n                          }\n                        </tbody>\n                      </table>\n                    </div>\n                    <div className=\"col col-md-6\">\n                      {/* <strong>Total de :</strong> {properties.reduce((total, x: any) => (total + x.cars.length), 0)} */}\n                    </div>\n                    <div className=\"col-md-6 text-right\">\n                      <button className=\"btn btn-sm btn-primary\" onClick={this.downloadTemplate}>\n                        <i className=\"fa fa-fw fa-download\" /> Descargar Formato\n                      </button>\n                      <button className=\"btn btn-sm btn-default\" onClick={this.clickUploadFile} style={{marginLeft: '5px'}}>\n                        <i className=\"fa fa-fw fa-cogs\" /> Cambiar configuración\n                      </button>\n                    </div>\n                  </div>\n                  :\n                  <div className=\"row\">\n                    <div className=\"col col-md-12\">\n                      <div className=\"form-group\">\n                        {/*<label>Días que serán importardos</label>*/}\n                        <div\n                          className=\"upload-file text-center pointer\"\n                          onClick={this.clickUploadFile}\n                          onDrop={this.handleDrop}\n                          onDragOver={this.dragOverHandler}\n                          onDragEnd={this.dragEndHandler}\n                          onDragLeave={this.dragLeaveHandler}\n                          style={{\n                            backgroundColor: '#EEEEEE',\n                            border: this.state.canDrop ? '1px solid #979797' : '1px dashed #979797',\n                            padding: '100px 20px',\n                            color: this.state.canDrop ? '#aebccb' : '#6e7a89',\n                            borderRadius: '5px',\n                            marginBottom: '10px'\n                          }}>\n                          <i className=\"fa fa-2x fa-cloud-upload\"/><br/>\n                          Prueba soltando el excel aquí, o haz click para seleccionar el excel a cargar.\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n              }\n              <input\n                type=\"file\"\n                onChange={this.handleChangeInputFile}\n                style={{display: 'None'}}\n                ref={this.inputFile} accept=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel\"\n              />\n            </div>\n            <div className=\"box-footer text-right\">\n              <button\n                className=\"btn btn-sm btn-default\"\n                onClick={() => this.props.history.push(parseReplicableURL('/requests/vehicles/'))}\n              >\n                Cancelar\n              </button>\n              {properties.length ? <button className=\"btn btn-sm btn-primary\" style={{marginLeft: '5px'}} onClick={this.sendCreate} disabled={sending}>\n                {\n                  sending ?\n                    <React.Fragment>\n                      <i className=\"fa fa-fw fa-spin fa-spinner\"/> Actualizando...\n                    </React.Fragment>\n                    : 'Actualizar'\n                }\n              </button> : null}\n            </div>\n            {\n              loadingSettings || sending &&\n                <div className=\"overlay\">\n                  <i className=\"fa fa-spinner fa-spin text-purple\"/>\n                </div>\n            }\n          </div>\n          <ModalView/>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private clickUploadFile(): void {\n    if (this.inputFile.current) {\n      this.inputFile.current.click();\n    }\n  }\n\n  private handleDrop(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      if (dt.items.length) {\n        const file: File | null = dt.items[0].getAsFile();\n        if (file) {\n          this.processSettings(file);\n        }\n      }\n    } else {\n      if (dt.files.length) {\n        const file = dt.files[0];\n        this.processSettings(file);\n      }\n    }\n  }\n\n  private handleChangeInputFile(e: React.ChangeEvent<HTMLInputElement>): void {\n    const {files} = e.target;\n    if (files && files.length) {\n      this.processSettings(files[0]);\n    }\n  }\n\n  private dragOverHandler(e: React.DragEvent<HTMLDivElement>): void {\n    e.preventDefault();\n    this.setState({\n      canDrop: true\n    });\n  }\n\n  private dragEndHandler(e: React.DragEvent<HTMLDivElement>): void {\n    const dt = e.dataTransfer;\n    if (dt.items) {\n      // Use DataTransferItemList interface to remove the drag data\n      for (let i = 0; i < dt.items.length; i++) {\n        dt.items.remove(i);\n      }\n    } else {\n      // Use DataTransfer interface to remove the drag data\n      e.dataTransfer.clearData();\n    }\n  }\n\n  private dragLeaveHandler(): void {\n    this.setState({\n      canDrop: false\n    });\n  }\n\n  private downloadTemplate(): void {\n    /* make the worksheet */\n    const ws = XLSX.utils.json_to_sheet([{\n      propiedad: '',\n      marca: ''\n    }]);\n    /* add to workbook */\n    const wb = XLSX.utils.book_new();\n    XLSX.utils.book_append_sheet(wb, ws, 'Propiedades');\n    /* generate an XLSX file */\n    XLSX.writeFile(wb, 'template_request_settings.xlsx');\n  }\n\n  private processSettings(file: File): void {\n    this.setState({\n      loadingSettings: true\n    });\n    if (['application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'].includes(file.type)) {\n      const reader = new FileReader();\n      const rABS = !!reader.readAsBinaryString;\n      reader.onload = (e: any) => {\n        let data = e.target.result;\n        if (!rABS) {\n          data = new Uint8Array(data);\n        }\n        const workbook: XLSX.WorkBook = XLSX.read(data, {\n          type: rABS ? 'binary' : 'array',\n          cellDates: true\n        });\n        const excelData = workbook.Sheets.hasOwnProperty('Propiedades') ? XLSX.utils.sheet_to_json(workbook.Sheets.Propiedades) : [];\n        const brandByProperty: any = {};\n        if (excelData.length >= 1) {\n          excelData.forEach((item: any, index: number) => {\n            const key =  item.propiedad;\n            if (!brandByProperty.hasOwnProperty(key)) {\n              brandByProperty[key] = {\n                brands: []\n              };\n            }\n            brandByProperty[key].brands.push(item.marca);\n          });\n          this.setState({\n            loadingSettings: false,\n            properties: Object.keys(brandByProperty)\n              .map((key) => ({key, ...brandByProperty[key]}))\n              .sort((a, b) => {\n                if (a.key < b.key) return 1;\n                if (a.key > b.key) return -1;\n                return 0;\n              })\n              .reverse()\n          });\n        } else {\n          swal(\n            'Importador de configuración',\n            `\"${file.name}\" no cumple con los requisitos mínimos o no tiene autos.`,\n            'error'\n          );\n          this.setState({\n            loadingSettings: false\n          });\n        }\n      };\n      if (rABS) {\n        reader.readAsBinaryString(file);\n      } else {\n        reader.readAsArrayBuffer(file);\n      }\n      if (this.inputFile.current) {\n        this.inputFile.current.value = '';\n      }\n    }\n  }\n\n  private sendCreate(): void {\n    const { properties } = this.state;\n    const { history } = this.props;\n    this.setState({\n      sending: true\n    });\n    const api = new ApiService();\n    api.getSource();\n    api\n      .updateMassiveRequest({\n        properties\n      })\n      .then((response: any) => {\n        const { message } = response.data;\n        history.push(parseReplicableURL('/requests/vehicles/'));\n        setTimeout(() => {\n          swal('Actualización masiva', message, 'success');\n        }, 200);\n        this.setState({\n          sending: false\n        });\n      })\n      .catch((e) => {\n        swal('Actualización masiva', 'Se produjo un error al actualizar.', 'error');\n        this.setState({\n          sending: false\n        });\n      });\n  }\n\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestUpdaterView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router-dom';\nimport { ICar } from '../../../../../../../src/app/interfaces/car.interface';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport { updateRequestItemsThunkAction } from '../../../actions/requestItems.actions';\nimport { IRequestItemsState } from '../../../actions/requestItems.types';\nimport { IWindow } from '../../../interfaces/window';\nimport ApiService from '../../../utils/axios';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport AutoCompleteInput from '../../Utils/AutoCompleteInput';\nimport ShowIf from '../../Utils/ShowIf';\nimport { debounceTime, switchMap } from 'rxjs/operators';\nimport { ajax } from 'rxjs/ajax';\nimport AutoCompleteVinInput from '../../Utils/AutoCompleteVinInput';\nimport { Subject } from 'rxjs/internal/Subject';\nimport CopyText from '../../Utils/CopyText';\nimport JsonFormatter from 'react-json-formatter';\nimport RequestStatusDislay from '../StatusComponents/RequestStatusDislay';\nimport TransmittalStatusDislay from '../StatusComponents/TransmittalStatusDislay';\n\ninterface IPropsType extends RouteComponentProps<{ id: string }> {\n  requestItems: IRequestItemsState;\n  item: IRequestItem;\n  updateRequestItemsThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => void;\n  deleteRequestItemsThunkAction: (id: string) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  recommends: ICar[];\n}\n\ndeclare let window: IWindow;\n\nclass RequestVehicleItem extends React.Component<IPropsType, IStateType> {\n  readonly api: ApiService;\n  readonly $subjectRecommends = new Subject<any>();\n\n  readonly state = {\n    error: null,\n    recommends: []\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.goToDetail = this.goToDetail.bind(this);\n    this.openOT = this.openOT.bind(this);\n    this.downloadFiles = this.downloadFiles.bind(this);\n    this.api = new ApiService();\n    this.$subjectRecommends.pipe(\n      debounceTime(300),\n      switchMap((text: string) => {\n        return ajax({\n          url: `/api/v1/requests/search-car/?search=${text}`,\n          headers: {\n            'Content-Type': 'application/json;charset=UTF-8'\n          },\n          method: 'GET'\n        });\n      })\n    ).subscribe((response) => {\n      this.setState({\n        recommends: response.response.cars\n      });\n    });\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { item } = this.props;\n    const { requestItemStatus, reasons, requestSettings } = this.props.requestItems;\n    const { recommends } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest') && window.user.isAdmin;\n\n    return (\n      <tr id={`request-item-${item._id}`} className={'background-transition'}>\n        {/*<ShowIf condition={requestSettings.priority}>*/}\n        <td\n          className={`middle-center ${canChangeRequest ? 'pointer' : ''}`}\n          onClick={canChangeRequest ? () => {\n            this.props.updateRequestItemsThunkAction({\n              item: {\n                ...item,\n                priority: !item.priority\n              },\n              debounce: false\n            });\n          } : undefined}\n        >\n          {item.priority ? <i className='fa fa-star text-yellow' /> : <i className='fa fa-star text-gray' />}\n        </td>\n        <td\n          className='middle pointer'\n          onClick={() => this.goToDetail(item._id, item.request._id)}\n          style={{}}\n        >\n          <RequestStatusDislay requestItem={item} showNumber={true} />\n        </td>\n        <td\n          className='middle pointer'\n          onClick={() => this.goToDetail(item._id, item.request._id)}\n          style={{ fontSize: '80%' }}\n        >\n          <div>\n            <strong className='text-primary text-underline'>\n              {item.destination?.name?.toUpperCase() ?? '-'}\n            </strong>\n          </div>\n          <div className={'text-info'}>\n            <strong>\n              {item.destination?.company?.name?.toUpperCase() ?? '-'}\n            </strong>\n          </div>\n        </td>\n        <ShowIf condition={hasPermission(window.user, 'viewTransmittal')}>\n          <td\n            className={`middle ${item.transmittal?.number ? 'pointer' : ''}`}\n            onClick={item.transmittal?.number\n              ? () => this.openOT(item.transmittal?.number.toString(), item.transmittal?._id, item?.transmittalItem?._id)\n              : undefined\n            }\n          >\n            <TransmittalStatusDislay transmittal={item.transmittal} showNumber={true} />\n          </td>\n        </ShowIf>\n        <ShowIf condition={hasPermission(window.user, 'viewTransmittal')}>\n          <td\n            className={`middle text-sm ${!!item.transmittalItem?.origin?.name?.length || !!item.transmittalItem?.destination?.name?.length ? 'pointer' : ''}`}\n            style={{ padding: '20px 5px' }}\n            onClick={!!item.transmittalItem?.origin?.name?.length || !!item.transmittalItem?.destination?.name?.length\n              ? () => this.openOT(item.transmittal.number.toString(), item.transmittal._id, item?.transmittalItem._id)\n              : undefined\n            }\n          >\n            <ShowIf\n              condition={\n                !!item.transmittalItem?.origin?.name?.length ||\n                !!item.transmittalItem?.destination?.name?.length\n              }\n            >\n              <ShowIf\n                condition={\n                  item?.transmittal?.transporter?.driver?._id?.length\n                }\n              >\n                <div className={'text-primary'}>\n                  <strong>{\n                    item?.transmittal?.transporter?.driver?.firstName?.toUpperCase()} {item?.transmittal?.transporter?.driver?.lastName?.toUpperCase()\n                  }</strong>\n                </div>\n\n              </ShowIf>\n              <ShowIf\n                condition={\n                  item?.transmittal?.transporter?.carrier?._id?.length\n                }\n              >\n                <div className={'text-info'}>\n                  <strong>\n                    <ShowIf condition={!!item?.transmittal?.transporter?.patent?.length}>\n                      PLACA: {item?.transmittal?.transporter?.patent?.toUpperCase()} -\n                    </ShowIf> {item?.transmittal?.transporter?.carrier?.name?.toUpperCase()}\n                  </strong>\n                </div>\n\n              </ShowIf>\n\n              <div className={'text-info'}>\n                <strong>\n                  {\n                    item.transmittalItem?.origin?.name?.length\n                      ? item.transmittalItem?.origin?.name?.toUpperCase()\n                      : '-'\n                  }\n                  <i className='fa fa-fw fa-flag-o text-black' />\n                </strong>\n                {/*<br />{item.transmittalItem.origin?.company?.name}*/}\n              </div>\n              <div className={'text-primary  text-underline'}>\n                <strong>\n                  {\n                    item.transmittalItem?.destination?.name?.length\n                      ? item.transmittalItem?.destination?.name?.toUpperCase()\n                      : '-'\n                  }\n                  <i className='fa fa-fw fa-flag-checkered text-black' />\n                </strong>\n                {/*<br />{item.transmittalItem.destination?.company?.name}*/}\n              </div>\n              <ShowIf condition={false}>\n                <JsonFormatter\n                  json={JSON.stringify({\n                    // transmittal: Object.keys(item?.transmittal ?? {}),\n                    transporter: Object.keys(item?.transmittal?.transporter ?? {}),\n                    driver: item?.transmittal?.transporter?.driver ?? {},\n                    carrier: item?.transmittal?.transporter?.carrier ?? {}\n                    // transmittalItem: Object.keys(item?.transmittalItem ?? {})\n                  })}\n                  jsonStyle={{\n                    propertyStyle: { color: 'red' },\n                    stringStyle: { color: 'green' },\n                    numberStyle: { color: 'darkorange' }\n                  }}\n                />\n              </ShowIf>\n            </ShowIf>\n          </td>\n        </ShowIf>\n        <ShowIf condition={false}>\n          <td className='middle' style={{ fontSize: '80%' }}>{item.origin?.name ?? '-'}</td>\n        </ShowIf>\n        {/*<td className=\"middle\">{item.car.property ? item.car.property : '-'}</td>*/}\n        {\n          // canChangeRequest && !requestSettings.brandReadOnly ?\n          !canChangeRequest ? <td className='middle'>\n              <strong className={'text-primary'}>\n                {item.car?.brand}\n              </strong><br />\n              {item.car?.denomination}<br />\n              <ShowIf condition={!!item.car?.vin?.length && !!item.car?.color?.length}>\n                <strong>{item.car?.color?.toUpperCase()}</strong><br />\n              </ShowIf>\n              <ShowIf condition={!item.car?.vin?.length && !!item.car?.firstColorOption.length}>\n                {item.car?.firstColorOption}\n                {item.car?.secondColorOption?.length ? `, ${item.car?.secondColorOption?.toUpperCase()}` : ''}{item.car?.thirdColorOption?.length ? `, ${item.car?.thirdColorOption?.toUpperCase()}` : ''}\n              </ShowIf>\n            </td> :null\n        }\n        <ShowIf condition={requestSettings.entry && false}>\n          <td className='middle-center'><strong>{item.car?.bl}</strong></td>\n        </ShowIf>\n        <ShowIf condition={requestSettings.entry}>\n          {\n            canChangeRequest ?\n              <td className='middle'>\n                <input\n                  type='text'\n                  className='form-control input-sm'\n                  defaultValue={item.car?.entry}\n                  onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          entry: e.target.value\n                        }\n                      },\n                      debounce: true\n                    });\n                  }}\n                />\n              </td>\n              : <td className='middle-center'><strong>{item.car?.entry}</strong></td>\n          }\n        </ShowIf>\n        <ShowIf\n          condition={\n            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n            requestSettings.material\n          }\n        >\n          {\n            canChangeRequest && !requestSettings.materialReadOnly ?\n              <td className='middle'>\n                <AutoCompleteInput\n                  value={item.car?.material}\n                  inputClass={'input-sm'}\n                  items={recommends}\n                  renderItem={(car, index) => (\n                    <div key={index} className='item'>\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  )}\n                  onChange={(e) => {\n                    const { value } = e.target;\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          material: value\n                        }\n                      },\n                      debounce: true\n                    });\n                    this.search(value);\n                  }}\n                  onSelect={(car: any) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        car: {\n                          ...item.car,\n                          brand: car.brand,\n                          denomination: car.denomination,\n                          material: car.material ?? ''\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                />\n              </td>\n              : <td className='middle-center'><strong>{item.car?.material}</strong></td>\n          }\n        </ShowIf>\n        <ShowIf\n          condition={hasPermission(window.user, 'changeRequest') || window.user.isAdmin}\n          alternative={\n            <td\n              className='middle'\n              style={{ padding: '20px 10px 20px 5px' }}\n            >\n              <ShowIf\n                condition={hasPermission(window.user, 'viewCar') && item.car?.vin?.length > 0}\n                alternative={item.car?.vin}\n              >\n                <CopyText value={item.car?.vin}>\n                  <strong\n                    className={'text-underline text-primary pointer'}\n                    onClick={() => {\n                      this.props.history.push(`/settings/cars/${item.car._id}/`);\n                    }}\n                  >\n                    {item.car?.vin}\n                  </strong>\n                </CopyText>\n              </ShowIf>\n            </td>\n          }\n        >\n          <td\n            className='middle'\n            style={{ padding: '20px 10px 20px 5px' }}\n          >\n            <div className='flex'>\n              <AutoCompleteVinInput\n                history={this.props.history}\n                defaultValue={item.car?.vin}\n                item={item}\n                inputClass={'input-sm'}\n                renderItem={(car, index) => (\n                  <div key={index} className='item'>\n                    {car.vin ? `${car.vin} - ` : ''} {car.denomination} <br />\n                    <strong>{car.brand}</strong>\n                  </div>\n                )}\n              />\n            </div>\n          </td>\n        </ShowIf>\n        <ShowIf condition={canChangeRequest}>\n          <td className='middle'>\n              <AutoCompleteInput\n                value={item.car?.brand}\n                inputClass={'input-sm'}\n                items={recommends}\n                renderItem={(car, index) => {\n                  return (\n                    <div key={index} className='item'>\n                      {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                      <strong>{car.brand}</strong>\n                    </div>\n                  );\n                }}\n                onChange={(e) => {\n                  const { value } = e.target;\n                  this.props.updateRequestItemsThunkAction({\n                    item: {\n                      ...item,\n                      car: {\n                        ...item.car,\n                        brand: value\n                      }\n                    },\n                    debounce: true\n                  });\n                  this.search(value);\n                }}\n                onSelect={(car: any) => {\n                  this.props.updateRequestItemsThunkAction({\n                    item: {\n                      ...item,\n                      car: {\n                        ...item.car,\n                        brand: car.brand,\n                        denomination: car.denomination,\n                        material: car.material ?? ''\n                      }\n                    },\n                    debounce: false\n                  });\n                }}\n              />\n            </td>\n        </ShowIf>\n        {/*<ShowIf condition={canChangeRequest && !requestSettings.denominationReadOnly}>*/}\n        <ShowIf condition={canChangeRequest}>\n          <td className='middle'>\n            <AutoCompleteInput\n              value={item.car?.denomination}\n              inputClass={'input-sm'}\n              items={recommends}\n              renderItem={(car, index) => (\n                <div key={index} className='item'>\n                  {car.material ? `${car.material} - ` : ''} {car.denomination} <br />\n                  <strong>{car.brand}</strong>\n                </div>\n              )}\n              onChange={(e) => {\n                const { value } = e.target;\n                this.props.updateRequestItemsThunkAction({\n                  item: {\n                    ...item,\n                    car: {\n                      ...item.car,\n                      denomination: value\n                    }\n                  },\n                  debounce: true\n                });\n                this.search(value);\n              }}\n              onSelect={(car: any) => {\n                this.props.updateRequestItemsThunkAction({\n                  item: {\n                    ...item,\n                    car: {\n                      ...item.car,\n                      brand: car.brand,\n                      denomination: car.denomination,\n                      material: car.material ?? ''\n                    }\n                  },\n                  debounce: false\n                });\n              }}\n            />\n          </td>\n        </ShowIf>\n        <ShowIf condition={requestSettings.color && false}>\n          {\n            canChangeRequest && !requestSettings.colorReadOnly\n              ?\n              <td className='middle'>\n                <input type='text'\n                       className='form-control input-sm'\n                       defaultValue={item.car?.color}\n                       onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                         this.props.updateRequestItemsThunkAction({\n                           item: {\n                             ...item,\n                             car: {\n                               ...item.car,\n                               color: e.target.value\n                             }\n                           },\n                           debounce: false\n                         });\n                       }}\n                />\n              </td>\n              : <td className={`middle ${!!item.car?.color?.length ? '' : ' text-muted'}`}>\n                <ShowIf condition={!!item.car?.color?.length}>\n                  <strong>{item.car?.color}</strong><br />\n                </ShowIf>\n                <ShowIf condition={!item.car?.color}>\n                  {item.car?.firstColorOption}\n                </ShowIf>\n                {item.car?.secondColorOption?.length ? `, ${item.car?.secondColorOption}` : ''}{item.car?.thirdColorOption?.length ? `, ${item.car?.thirdColorOption}` : ''}\n              </td>\n          }\n        </ShowIf>\n        <ShowIf condition={canChangeRequest && false}>\n          {\n            canChangeRequest ?\n              <td className='middle'>\n                <select\n                  className='form-control select-sm font-12'\n                  value={item.status?._id ?? ''}\n                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        status: {\n                          ...item.status,\n                          _id: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                >\n                  <option value='' disabled={true}>-</option>\n                  {\n                    requestItemStatus.map((req) => (\n                      <option key={req._id} value={req._id}>{req.name}</option>\n                    ))\n                  }\n                </select>\n              </td>\n              : <td className='middle text-muted'>{item.status?.name}</td>\n          }\n        </ShowIf>\n        <ShowIf\n          condition={\n            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n            requestSettings.internalNumber\n          }\n        >\n          {\n            canChangeRequest ?\n              <td className='middle'>\n                <input type='text'\n                       className='form-control input-sm'\n                       defaultValue={item.car?.internalNumber}\n                       onChange={(e: React.ChangeEvent<HTMLInputElement>) => {\n                         this.props.updateRequestItemsThunkAction({\n                           item: {\n                             ...item,\n                             car: {\n                               ...item.car,\n                               internalNumber: e.target.value\n                             }\n                           },\n                           debounce: false\n                         });\n                       }}\n                />\n              </td>\n              : <td className='middle'>{item.car?.internalNumber}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.reason && false}>\n          {\n            canChangeRequest ?\n              <td className='middle'>\n                <select\n                  className='form-control select-sm font-12'\n                  value={item.reason?._id ?? ''}\n                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                    this.props.updateRequestItemsThunkAction({\n                      item: {\n                        ...item,\n                        reason: {\n                          ...item.reason,\n                          _id: e.target.value\n                        }\n                      },\n                      debounce: false\n                    });\n                  }}\n                >\n                  <option value='' disabled={true}>-</option>\n                  {\n                    reasons.map((reason) => (\n                      <option key={reason._id} value={reason._id}>{reason.name}</option>\n                    ))\n                  }\n                </select>\n              </td>\n              : <td className='middle'>{item.reason?.name}</td>\n          }\n        </ShowIf>\n        <ShowIf condition={requestSettings.ticket}>\n          <td\n            className='middle-center'\n          >\n            <div\n              data-toggle='tooltip'\n              data-placement='top'\n              className={`${item.request?.advancePaymentInformation?.files?.length ? 'pointer' : ''}`}\n              title={item.request?.advancePaymentInformation?.number ?? '-'}\n              onClick={() => this.openBlank(item.request.advancePaymentInformation.files[0].file.url)}\n            >\n              {\n                //request.advancePaymentInformation.files[0].file.url\n                item.request?.advancePaymentInformation?.files?.length ?\n                  <i\n                    className='fa fa-check-circle text-green'\n                  /> : ''\n              }\n            </div>\n          </td>\n        </ShowIf>\n        {/*<td\n          className={`middle-center ${item.files && item.files.length ? 'pointer' : ''}`}\n          style={{ fontSize: '80%' }}\n          onClick={item.files?.length ? () => this.downloadFiles(item) : undefined}\n        >\n          {\n            item.files?.length ?\n              <span\n                data-toggle={'tooltip'}\n                data-placement={'top'}\n                title={`${item.files.length} archivos adjuntos.`}\n              >\n                <i className=\"fa fa-paperclip\" /> ({item.files.length})\n              </span> : null\n          }\n        </td>\n        <td className=\"middle-center text-gray\">\n          {\n            item.observation && item.observation.length ?\n              <i\n                className=\"fa fa-comment\"\n                data-toggle=\"tooltip\"\n                data-placement=\"top\"\n                title={item.observation}\n              /> : null\n          }\n        </td>*/}\n      </tr>\n    );\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount() {\n    this.$subjectRecommends.unsubscribe();\n  }\n\n  private openOT(number: string, transmittal: string, item: string) {\n    this.props.history.push(parseReplicableURL(`/transmittals?number=${number}&transmittal=${transmittal}&item=${item}`,\n      ['number', 'transmittal', 'item']));\n    // window.open(parseReplicableURL(`/transmittals/?number=${number}`), '_blank');\n  }\n\n  private goToDetail(item: string, request: string): void {\n    this.props.history.push(parseReplicableURL(`/requests/vehicles/${request}?item=${item}`, ['item']));\n  }\n\n  private downloadFiles(item: IRequestItem) {\n    window.open(`/requests-item/${item._id}/download-files/`, '_blank');\n  }\n\n  private search(text: string): void {\n    this.$subjectRecommends.next(text);\n  }\n\n  /*private deleteRequestItem(item: IRequestItem) {\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar este vehículo ${item.car.brand} ${item.car.denomination} ${item.car.material}.`,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteRequestItemsThunkAction(item._id);\n      }\n    });\n  }*/\n\n  private openBlank(url: string) {\n    window.open(decodeURI(url), '_blank');\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    updateRequestItemsThunkAction: ({ item, debounce }: { item: IRequestItem, debounce?: boolean }) => dispatch(updateRequestItemsThunkAction({\n      item,\n      debounce\n    }))\n    // deleteRequestItemsThunkAction: (id: string) => dispatch(deleteRequestItemsThunkAction(id))\n    // deleteRequestThunkAction: (idRequest: string) => dispatch(deleteRequestThunkAction(idRequest))\n  };\n};\n\nexport default connect<{}, {}, IPropsType | any>(mapStateToProps, mapDispatchToProps)(RequestVehicleItem);\n","import * as React from 'react';\nimport { Dispatch, Fragment } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { debounce } from 'throttle-debounce';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport {\n  changeFilterRequestAction,\n  createRequestItemAction,\n  // deleteRequestItemAction,\n  getRequestItemsThunkAction,\n  updateRequestItemAction\n} from '../../../actions/requestItems.actions';\nimport { IRequestItemsFilters, IRequestItemsState, RequestItemsReduxActions } from '../../../actions/requestItems.types';\nimport AppContainer from '../../../container/AppContainer';\nimport { IWindow } from '../../../interfaces/window';\nimport { hasPermission, parseReplicableURL } from '../../../utils/common';\nimport BootstrapSelect from '../../Utils/BootstrapSelect';\nimport DateRangePicker from '../../Utils/DateRangePicker';\nimport ImageLazyLoad from '../../Utils/ImageLazyLoad';\nimport Paginator from '../../Utils/Paginator';\nimport ShowIf from '../../Utils/ShowIf';\nimport TrackingBasePage from '../../Utils/TrackingBasePage';\nimport RequestVehicleItem from './RequestVehicleItem';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\nimport DateRangeInput from '../../Utils/DateRangeInput';\nimport * as moment from 'moment-timezone';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  requestItems: IRequestItemsState;\n  dispatch: Dispatch<RequestItemsReduxActions>;\n  updateRequestItemAction: (item: IRequestItem) => void;\n  getRequestItemsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => void;\n  deleteRequestItemAction: (item: IRequestItem) => void;\n  createRequestItemAction: (item: IRequestItem) => void;\n  changeFilterRequestAction: (key: keyof IRequestItemsFilters, value: any | any[]) => void;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass RequestVehicleListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  readonly rangeOptions: daterangepicker.Options = {\n    // startDate: moment().subtract(11, 'months').startOf('month').toDate(),\n    // endDate: moment().toDate(),\n    maxDate: moment().toDate(),\n    locale: {\n      format: 'DD/MM/YYYY',\n      customRangeLabel: 'Período personalizado',\n      applyLabel: 'Aplicar',\n      cancelLabel: 'Cancelar'\n    },\n    ranges: {\n      'Este mes': [moment().startOf('month').startOf('month').toDate(), moment().endOf('month').toDate()],\n      'Últimos 3 meses': [moment().startOf('month').subtract(3, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n      'Últimos 6 meses': [moment().startOf('month').subtract(6, 'months').startOf('month').toDate(), moment().endOf('month').toDate()],\n      'Último año': [moment().startOf('month').subtract(12, 'months').startOf('month').toDate(), moment().endOf('month').toDate()]\n    },\n    opens: 'left'\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Solicitudes';\n    this.changePage = this.changePage.bind(this);\n    this.changeOrder = this.changeOrder.bind(this);\n    this.onDateRangeChange = this.onDateRangeChange.bind(this);\n    this.changeFilterDebounced = debounce(200, this.changeFilterDebounced.bind(this));\n    this.changeFilter = this.changeFilter.bind(this);\n    this.exportExcel = this.exportExcel.bind(this);\n    this.create = this.create.bind(this);\n    this.update = this.update.bind(this);\n    this.import = this.import.bind(this);\n    this.asignar = this.asignar.bind(this);\n  }\n\n\n  public render(): React.ReactElement<IPropsType> {\n    const {\n      pagination, loading, requestItems, requestItemStatus, venues, filters, properties, requestSettings, users\n    } = this.props.requestItems;\n    const { orderBy, orderType } = this.props.requestItems.options;\n    const { exporing } = this.state;\n    const canChangeRequest = hasPermission(window.user, 'changeRequest') && window.user.isAdmin;\n    return (\n      <AppContainer title={\n        <div\n          style={{ width: '180px' }}\n        >\n          <DateRangeInput\n            options={this.rangeOptions}\n            onChange={this.onDateRangeChange}\n            startDate={filters.from}\n            endDate={filters.to}\n          />\n\n        </div>\n      } cMenu='3' cSubMenu='3.2'>\n        <section className='content'>\n          <div className='box'>\n            <div className='box-header with-border'>\n              <h3 className='box-title'>Unidades <small>{pagination.count}</small></h3>\n              <div className='pull-right box-tools'>\n                <ShowIf\n                  condition={\n                    !['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                    hasPermission(window.user, 'createRequest')}\n                >\n                  <button\n                    onClick={this.create}\n                    className='btn btn-sm btn-success hidden-xs'\n                    style={{marginRight: '5px'}}\n                  >\n                    <i className='fa fa-fw fa-plus' /> Crear solicitud\n                  </button>\n                </ShowIf>\n                <div className='btn-group btn-group-sm'>\n                  <ShowIf condition={requestItems.length > 0}>\n                    <button\n                      className='btn btn-primary'\n                      onClick={this.exportExcel}\n                      disabled={exporing}\n                    >\n                      {\n                        exporing ?\n                          <Fragment><i className='fa fa-spin fa-spinner' /> Exportando</Fragment> :\n                          <Fragment><i className='fa fa-fw fa-download' /> Exportar</Fragment>\n                      }\n                    </button>\n                  </ShowIf>\n                  <ShowIf condition={\n                    requestItems.length > 0 && (\n                      hasPermission(window.user, 'updateMassiveRequest') ||\n                      hasPermission(window.user, 'massAllocation') ||\n                      hasPermission(window.user, 'importRequest')\n                    )\n                  }>\n                    <div className='btn-group btn-group-sm'>\n                      <button type='button' className='btn btn-default dropdown-toggle' data-toggle='dropdown' aria-expanded='true'>\n                        <span className='caret'></span>\n                      </button>\n                      <ul className='dropdown-menu' style={{ paddingRight: '10px' }}>\n                        <ShowIf condition={hasPermission(window.user, 'createRequest')}>\n                          <li className='visible-xs'>\n                            <a href='#' onClick={this.create} className='text-muted'>\n                              <i className='fa fa-fw fa-plus' /> Crear nueva solicitud\n                            </a>\n                          </li>\n                        </ShowIf>\n                        <ShowIf condition={hasPermission(window.user, 'massAllocation')}>\n                          <li>\n                            <a href='#' onClick={this.asignar} className='text-muted'>\n                              <i className='fa fa-fw fa-upload' /> Asignación masiva de unidades\n                            </a>\n                          </li>\n                        </ShowIf>\n                        <ShowIf condition={hasPermission(window.user, 'importRequest')}>\n                          <li>\n                            <a href='#' onClick={this.import} className='text-muted'>\n                              <i className='fa fa-fw fa-upload' /> Importar solicitudes por lote\n                            </a>\n                          </li>\n                        </ShowIf>\n                        {/*<ShowIf condition={hasPermission(window.user, 'updateMassiveRequest')}>*/}\n                        {/*  <li>*/}\n                        {/*    <a href='#' onClick={this.update}>*/}\n                        {/*      <i className='fa fa-fw fa-plus' /> Actualizador*/}\n                        {/*    </a>*/}\n                        {/*  </li>*/}\n                        {/*</ShowIf>*/}\n                      </ul>\n                    </div>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <div className='box-body no-padding'>\n              <div style={{ padding: '10px' }}>\n                <div className='row' style={{ margin: 0 }}>\n                  <div className='col-md-3' style={{ padding: '0 5px' }}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Vehículo\n                      </label>\n                      <input\n                        type='text'\n                        className='form-control input-sm'\n                        placeholder='Busca por VIN, marca, modelo o material.'\n                        defaultValue={filters.text}\n                        onChange={(e) => {\n                          this.changeFilterDebounced('text', e.target.value);\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <ShowIf condition={requestSettings.conectaID}>\n                    <div className='col-md-3' style={{ padding: '0 5px' }}>\n                      <div className='form-group'>\n                        <label className='control-label'>\n                          Conecta ID\n                        </label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          placeholder='Nº de ticket: 14795'\n                          defaultValue={filters.conectaID}\n                          onChange={(e) => {\n                            this.changeFilterDebounced('conectaID', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <ShowIf condition={requestSettings.entry}>\n                    <div className='col-md-3' style={{ padding: '0 5px' }}>\n                      <div className='form-group'>\n                        <label className='control-label'>\n                          Partida\n                        </label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          placeholder='Nº de partida: S14795'\n                          defaultValue={filters.entry}\n                          onChange={(e) => {\n                            this.changeFilterDebounced('entry', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <div className='col-md-3' style={{ padding: '0 5px' }}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Nº Solicitudes\n                      </label>\n                      <input\n                        type='text'\n                        className='form-control input-sm'\n                        placeholder='Nº de solicitudes ejemplo: 2, 8, 10'\n                        defaultValue={filters.request}\n                        onChange={(e) => {\n                          this.changeFilterDebounced('request', e.target.value);\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <ShowIf condition={hasPermission(window.user, 'viewTransmittal')}>\n                    <div className='col-md-3' style={{ padding: '0 5px' }}>\n                      <div className='form-group'>\n                        <label className='control-label'>\n                          Nº Transporte\n                        </label>\n                        <input\n                          type='text'\n                          className='form-control input-sm'\n                          placeholder='Nº de ordenes de transporte ejemplo: 2, 8, 10'\n                          defaultValue={filters.transmittal}\n                          onChange={(e) => {\n                            this.changeFilterDebounced('transmittal', e.target.value);\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <div className='col-md-3' style={{ padding: '0 5px' }}>\n                    <div className='form-group'>\n                      <label htmlFor='venues' className='control-label'>Sucursales</label>\n                      <BootstrapSelect\n                        noneSelectedText='Todas'\n                        search={true}\n                        displayItems={2}\n                        selectedText='sucursales seleccionadas.'\n                        selected={filters.venues}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('venues', venues.map((venue) => venue._id));\n                            } else {\n                              this.changeFilter('venues', []);\n                            }\n                          }\n                        }\n                        options={venues.map((venue) => ({\n                          value: venue._id,\n                          text: venue.name\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.venues.includes(selected)) {\n                            this.changeFilter('venues', [...filters.venues.filter((venue) => venue !== selected)]);\n                          } else {\n                            this.changeFilter('venues', [...filters.venues, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <div className='col-md-3' style={{ padding: '0 5px' }}>\n                    <div className='form-group'>\n                      <label htmlFor='venues' className='control-label'>Estados</label>\n                      <BootstrapSelect\n                        noneSelectedText='Todos'\n                        displayItems={2}\n                        selectedText='estados seleccionados.'\n                        selected={filters.status}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('status', requestItemStatus.map((status) => status._id));\n                            } else {\n                              this.changeFilter('status', []);\n                            }\n                          }\n                        }\n                        options={requestItemStatus.map((status) => ({\n                          value: status._id,\n                          text: status.name\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.status.includes(selected)) {\n                            this.changeFilter('status', [...filters.status.filter((status) => status !== selected)]);\n                          } else {\n                            this.changeFilter('status', [...filters.status, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                  <ShowIf condition={['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id)}>\n                    <div className='col-md-3' style={{ padding: '0 5px' }}>\n                      <div className='form-group'>\n                        <label htmlFor='venues' className='control-label'>Propiedad</label>\n                        <BootstrapSelect\n                          noneSelectedText='Todas'\n                          search={true}\n                          displayItems={2}\n                          selectedText='propiedades seleccionadas.'\n                          selected={filters.properties}\n                          sm={true}\n                          allOption={true}\n                          selectAll={\n                            (all: boolean) => {\n                              if (all) {\n                                this.changeFilter('properties', properties.map((property) => property._id));\n                              } else {\n                                this.changeFilter('properties', []);\n                              }\n                            }\n                          }\n                          options={properties.map((property) => ({\n                            value: property._id,\n                            text: property.name\n                          }))}\n                          onClick={(selected: any) => {\n                            if (filters.properties.includes(selected)) {\n                              this.changeFilter('properties', [...filters.properties.filter((property) => property !== selected)]);\n                            } else {\n                              this.changeFilter('properties', [...filters.properties, selected]);\n                            }\n                          }}\n                        />\n                      </div>\n                    </div>\n                  </ShowIf>\n                  <div className='col-md-3' style={{ padding: '0 5px' }}>\n                    <div className='form-group'>\n                      <label className='control-label'>\n                        Solicitante\n                      </label>\n                      <BootstrapSelect\n                        noneSelectedText='Todas'\n                        search={true}\n                        displayItems={2}\n                        selectedText='sucursales seleccionadas.'\n                        selected={filters.users}\n                        sm={true}\n                        allOption={true}\n                        selectAll={\n                          (all: boolean) => {\n                            if (all) {\n                              this.changeFilter('users', users.map((user) => user._id));\n                            } else {\n                              this.changeFilter('users', []);\n                            }\n                          }\n                        }\n                        options={users.map((user) => ({\n                          value: user._id,\n                          text: `${user.firstName} ${user.lastName}`\n                        }))}\n                        onClick={(selected: any) => {\n                          if (filters.users.includes(selected)) {\n                            this.changeFilter('users', [...filters.users.filter((venue) => venue !== selected)]);\n                          } else {\n                            this.changeFilter('users', [...filters.users, selected]);\n                          }\n                        }}\n                      />\n                    </div>\n                  </div>\n                </div>\n              </div>\n              <ShowIf condition={!loading && requestItems.length > 0}>\n                <div className='table-responsive'>\n                  <table className='table table-striped table-xs table-hover' style={{ minWidth: '1000px' }}>\n                    <thead>\n                      <tr className='bg-primary' style={{ height: '45px' }}>\n                        {/*<ShowIf condition={requestSettings.priority}>*/}\n                          <th className='middle' style={{ width: '45px' }} />\n                        {/*</ShowIf>*/}\n\n                        <ShowIf condition={false}>\n                          <th\n                            className='middle pointer'\n                            style={{ width: '80px' }}\n                            onClick={() => this.changeOrder('meta.origin.name')}\n                          >\n                            Creada\n                            <span style={{ float: 'right' }}><i\n                              className={`fa fa-fw ${orderBy === 'meta.origin.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                          </th>\n                        </ShowIf>\n                        <th\n                          className='middle pointer'\n                          style={{ width: '120px' }}\n                          onClick={() => this.changeOrder('meta.request.number')}\n                        >\n                          Solicitud\n                          <span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'meta.request.number' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                        </th>\n                        <th\n                          className='middle pointer'\n                          style={{ width: '140px' }}\n                          onClick={() => this.changeOrder('meta.destination.name')}\n                        >\n                          Destino\n                          <span style={{ float: 'right' }}>\n                            <i\n                              className={`fa fa-fw ${orderBy === 'meta.destination.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`}\n                            />\n                          </span>\n                        </th>\n                        <ShowIf condition={hasPermission(window.user, 'viewTransmittal')}>\n                          <th\n                            className='middle pointer'\n                            style={{ width: '120px' }}\n                            onClick={() => this.changeOrder('meta.transmittal.number')}\n                          >\n                            Transporte\n                            <span style={{ float: 'right' }}><i className={`fa fa-fw ${orderBy === 'meta.transmittal.number' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf condition={hasPermission(window.user, 'viewTransmittal')}>\n                          <th\n                            className='middle'\n                            style={{ width: '250px', maxWidth: '260px' }}\n                            // onClick={() => this.changeOrder('meta.destination.name')}\n                          >\n                            Ruta\n                            {/*<span style={{ float: 'right' }}>\n                              <i\n                                className={`fa fa-fw ${orderBy === 'meta.destination.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`}\n                              />\n                            </span>*/}\n                          </th>\n                        </ShowIf>\n\n                        {/*<ShowIf condition={canChangeRequest && requestSettings.denominationReadOnly}>*/}\n                        <ShowIf condition={!canChangeRequest}>\n                          <th\n                            className='middle pointer'\n                            style={{ minWidth: '200px' }}\n                            onClick={() => this.changeOrder('meta.car.brand')}\n                          >\n                            Detalle de la unidad\n                            <span style={{ float: 'right' }}>\n                              <i className={`fa fa-fw ${orderBy === 'meta.car.brand' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                            </span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf\n                          condition={\n                            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                            requestSettings.material\n                          }\n                        >\n                          <th\n                            className='middle-center pointer'\n                            style={{ width: '100px' }}\n                            onClick={() => this.changeOrder('meta.car.material')}\n                          >\n                            Material\n                            <span style={{ float: 'right' }}><i\n                              className={`fa fa-fw ${orderBy === 'meta.car.material' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.entry && false}>\n                          <th className='middle-center' style={{ width: '60px' }}>\n                            BL\n                          </th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.entry}>\n                          <th className='middle-center' style={{ width: '60px' }}>\n                            Partida\n                          </th>\n                        </ShowIf>\n                        <th\n                          className='middle pointer'\n                          style={{ minWidth: '210px', width: '210px' }}\n                          onClick={() => this.changeOrder('meta.car.vin')}\n                        >\n                          VIN\n                          <span style={{ float: 'right' }}>\n                              <i className={`fa fa-fw ${orderBy === 'meta.car.vin' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                            </span>\n                        </th>\n                        {/*<ShowIf condition={canChangeRequest && !requestSettings.denominationReadOnly}>*/}\n                        <ShowIf condition={canChangeRequest}>\n                          <th\n                            className='middle pointer'\n                            style={{ width: '120px' }}\n                            onClick={() => this.changeOrder('meta.car.brand')}\n                          >\n                            Marca\n                            <span style={{ float: 'right' }}>\n                              <i className={`fa fa-fw ${orderBy === 'meta.car.brand' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                            </span>\n                          </th>\n                          <th\n                            className='middle pointer'\n                            style={{ minWidth: '120px' }}\n                            onClick={() => this.changeOrder('meta.car.denomination')}\n                          >\n                            Modelo\n                            <span style={{ float: 'right' }}>\n                              <i className={`fa fa-fw ${orderBy === 'meta.car.denomination' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                            </span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.color && false}>\n                          <th\n                            className='middle pointer'\n                            style={{ minWidth: '120px' }}\n                            onClick={() => this.changeOrder('meta.car.color')}\n                          >\n                            Color\n                            <span style={{ float: 'right' }}><i\n                              className={`fa fa-fw ${orderBy === 'meta.car.color' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} /></span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf\n                          condition={\n                            ['5bf2de35caf8ef7096105cdd'].includes(window.user.team._id) &&\n                            requestSettings.internalNumber\n                          }\n                        >\n                          <th className='middle' style={{ width: '60px' }}>CDO</th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.reason && false}>\n                          <th\n                            className='middle pointer'\n                            style={{ minWidth: '100px' }}\n                            onClick={() => this.changeOrder('reason.name')}\n                          >\n                            Motivo\n                            <span\n                              style={{ float: 'right' }}\n                            >\n                              <i\n                                className={`fa fa-fw ${orderBy === 'reason.name' ? `${orderType === 'descending' ? 'fa-sort-down' : 'fa-sort-up'}` : 'fa-sort'}`} />\n                            </span>\n                          </th>\n                        </ShowIf>\n                        <ShowIf condition={requestSettings.ticket}>\n                          <th\n                            className='middle-center'\n                            style={{ minWidth: '40px', maxWidth: '40px' }}\n                          >\n                            Ticket\n                          </th>\n                        </ShowIf>\n                        {/*<th className='middle-center' style={{ width: '20px' }}></th>*/}\n                        {/*<th className='middle-center' style={{ width: '20px' }}></th>*/}\n                      </tr>\n                    </thead>\n                    <tbody>\n                    {\n                      requestItems.map((item) => (\n                        <RequestVehicleItem\n                          key={item._id}\n                          item={item}\n                          {...this.props}\n                        />\n                      ))\n                    }\n                    </tbody>\n                  </table>\n                </div>\n              </ShowIf>\n              <ShowIf condition={!loading && requestItems.length === 0}>\n                <div className='row'>\n                  <div className='col-md-12 text-center' style={{ paddingTop: '10px', paddingBottom: '10px' }}>\n                    <ImageLazyLoad\n                      url='/images/not_found.png'\n                      height={'200px'}\n                      style={{\n                        opacity: 0.5,\n                        maxHeight: '200px',\n                        marginBottom: '10px'\n                      }}\n                      replaceLoading={<i\n                        className={'fa fa-2x fa-circle-o-notch text-primary fa-spin'}\n                        style={{ padding: '30px' }}\n                      />}\n                    /><br />\n                    <strong>No hay información para mostrar</strong>\n                  </div>\n                </div>\n              </ShowIf>\n            </div>\n            <div className='box-footer'>\n              <div className='row'>\n                <div className='col-md-12'>\n                  <ShowIf condition={pagination.pages > 1}>\n                    <div className='row'>\n                      <div className='col-md-6' style={{ padding: '20px 15px' }}>\n                        <span className='react-bootstrap-table-pagination-total text-muted text-ellipsis'>\n                          &nbsp;&nbsp;Mostrando registros del {(pagination.page - 1) * 25 + 1} al {(pagination.page) * 25} de {pagination.count} registros.\n                        </span>\n                      </div>\n                      <div className='col-md-6'>\n                        <div className='text-right' style={{ marginRight: '15px' }}>\n                          <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                        </div>\n                      </div>\n                    </div>\n                  </ShowIf>\n                </div>\n              </div>\n            </div>\n            <ShowIf condition={loading}>\n              <div className='overlay'>\n                <i className='fa fa-spinner fa-spin text-purple' />\n              </div>\n            </ShowIf>\n          </div>\n        </section>\n      </AppContainer>\n    );\n  }\n\n  private onDateRangeChange(from: Date, to: Date) {\n    const { orderBy, orderType } = this.props.requestItems.options;\n    this.props.changeFilterRequestAction('from', from);\n    this.props.changeFilterRequestAction('to', to);\n    this.props.getRequestItemsThunkAction(1, orderBy, orderType, true);\n  }\n\n  public componentDidMount() {\n    super.componentDidMount();\n  }\n\n  public componentWillMount(): void {\n    const { orderBy, orderType } = this.props.requestItems.options;\n    const { page } = this.props.requestItems.pagination;\n    window.scrollTo(0, 0);\n\n    this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: {\n        token: window.user.token\n      }\n    });\n\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `request-list-${window.user.team._id}` });\n    });\n\n    this.socket.on('UPDATE_REQUEST_ITEM', (data: any): void => {\n      this.props.updateRequestItemAction(data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-aqua-active');\n        setTimeout(() => {\n          $item.removeClass('bg-aqua-active');\n        }, 400);\n      }\n    });\n\n    this.socket.on('DELETE_REQUEST_ITEM', (data: any): void => {\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-red-active');\n      }\n      setTimeout(() => {\n        const { orderBy, orderType } = this.props.requestItems.options;\n        const { page } = this.props.requestItems.pagination;\n        this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n        // this.props.deleteRequestItemAction(data.item);\n      }, 400);\n    });\n\n    // this.socket.on('DELETE_REQUEST', (data: any): void => {\n    // const $item = $(`#request-${data.idRequest}`);\n    // if ($item) {\n    //   $item.addClass('bg-red-active');\n    // }\n    // setTimeout(() => {\n    //   this.props.deleteRequestActionInList(data.idRequest);\n    // }, 300);\n    // });\n\n    this.socket.on('CREATE_REQUEST', (data: any): void => {\n      const { page } = this.props.requestItems.pagination;\n      const { orderBy, orderType } = this.props.requestItems.options;\n      if (page === 1) {\n        for (const item of data.request.items) {\n          if (window.user.venuesAccess.includes(item.destination._id)) {\n            this.props.createRequestItemAction(item);\n            const $item = $(`#request-item-${item._id}`);\n            if ($item) {\n              $item.addClass('bg-green-active');\n            }\n            setTimeout(() => {\n              $item.removeClass('bg-green-active');\n            }, 400);\n          }\n        }\n        this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n      } else {\n        this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n      }\n    });\n\n    this.socket.on('CREATE_REQUEST_ITEM', (data: any): void => {\n      this.props.createRequestItemAction(data.item);\n      const $item = $(`#request-item-${data.item._id}`);\n      if ($item) {\n        $item.addClass('bg-green-active');\n      }\n      setTimeout(() => {\n        $item.removeClass('bg-green-active');\n      }, 400);\n    });\n  }\n\n  public componentDidUpdate(prevProps: IPropsType): void {\n    $('[data-toggle=\"tooltip\"]').tooltip();\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.requestItems.source) {\n      this.props.requestItems.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.emit('leave', { room: `request-list-${window.user.team._id}` });\n    this.socket.disconnect();\n  }\n\n  private create(): void {\n    this.props.history.push(parseReplicableURL('/requests/vehicles/create/'));\n  }\n\n  private update() {\n    this.props.history.push(parseReplicableURL('/requests/update/'));\n  }\n\n  private import() {\n    this.props.history.push(parseReplicableURL('/requests/import/'));\n  }\n\n  private asignar() {\n    this.props.history.push(parseReplicableURL('/requests/mass-allocation/'));\n  }\n\n  private changeFilterDebounced(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    this.changeFilter(key, value);\n  }\n\n  private changeFilter(key: keyof IRequestItemsFilters, value: any | any[]): void {\n    const { orderBy, orderType } = this.props.requestItems.options;\n    this.props.changeFilterRequestAction(key, value);\n    this.props.getRequestItemsThunkAction(1, orderBy, orderType, true);\n  }\n\n  private changeOrder(key: string) {\n    const { page } = this.props.requestItems.pagination;\n    const { orderBy, orderType } = this.props.requestItems.options;\n    let newOrderType = orderType;\n    let newOrderBy = orderBy;\n    if (key === orderBy) {\n      newOrderType = orderType === 'descending' ? 'ascending' : 'descending';\n    } else {\n      newOrderBy = key;\n    }\n    this.props.getRequestItemsThunkAction(page, newOrderBy, newOrderType, true);\n  }\n\n  private changePage(page: number): void {\n    window.scrollTo(0, 0);\n    const { orderBy, orderType } = this.props.requestItems.options;\n    this.props.getRequestItemsThunkAction(page, orderBy, orderType, true);\n  }\n\n  public exportExcel(): void {\n    this.trackClick('Exportar');\n    window.open(`/requests/export/`, '_blank');\n    // this.setState({\n    //   exporing: true\n    // });\n    // const api: ApiService = new ApiService();\n    // const instance = api.getInstance();\n    // instance.defaults.responseType = 'blob';\n    // instance\n    //   .get(`/requests/export/`)\n    //   .then((response) => {\n    //     const blob = new Blob([response.data], {\n    //       type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'\n    //     });\n    //     const fileName = `${moment().format('YYYYMMDD')}-solicitudes.xlsx`;\n    //     if (typeof window.navigator.msSaveBlob !== 'undefined') {\n    //       // IE workaround for \"HTML7007: One or more blob URLs were\n    //       // revoked by closing the blob for which they were created.\n    //       // These URLs will no longer resolve as the data backing\n    //       // the URL has been freed.\"\n    //       window.navigator.msSaveBlob(blob, fileName);\n    //     } else {\n    //       const blobURL = URL.createObjectURL(blob);\n    //       const tempLink = document.createElement('a');\n    //       tempLink.style.display = 'none';\n    //       tempLink.href = blobURL;\n    //       tempLink.setAttribute('download', fileName);\n    //       // Safari thinks _blank anchor are pop ups. We only want to set _blank\n    //       // target if the browser does not support the HTML5 download attribute.\n    //       // This allows you to download files in desktop safari if pop up blocking\n    //       // is enabled.\n    //       if (typeof tempLink.download === 'undefined') {\n    //         tempLink.setAttribute('target', '_blank');\n    //       }\n    //       this.setState({\n    //         exporing: false\n    //       });\n    //       document.body.appendChild(tempLink);\n    //       tempLink.click();\n    //       document.body.removeChild(tempLink);\n    //       URL.revokeObjectURL(blobURL);\n    //     }\n    //   })\n    //   .catch((err) => {\n    //     this.setState({\n    //       exporing: false\n    //     });\n    //     if (!Axios.isCancel(err)) {\n    //       swal('Exportar usuarios', 'Ha ocurrido un error al general el excel.', 'error');\n    //     }\n    //   });\n  }\n}\n\nconst mapStateToProps = (state: { requestItems: IRequestItemsState }) => {\n  return {\n    requestItems: state.requestItems\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getRequestItemsThunkAction: (page: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getRequestItemsThunkAction(page, orderBy, orderType, hideLoading)),\n    createRequestItemAction: (item: IRequestItem) => dispatch(createRequestItemAction(item)),\n    updateRequestItemAction: (item: IRequestItem) => dispatch(updateRequestItemAction(item)),\n    // deleteRequestItemAction: (item: IRequestItem) => dispatch(deleteRequestItemAction(item)),\n    changeFilterRequestAction: (key: keyof IRequestItemsFilters, value: any | any[]) => dispatch(changeFilterRequestAction(key, value))\n  };\n};\n\n\nexport default connect<{}, {}, IPropsType>(mapStateToProps, mapDispatchToProps)(RequestVehicleListView);\n","import * as React from 'react';\nimport { IRequestItem } from '../../../../../../../src/request/interfaces/requestItem.interface';\nimport ShowIf from '../../Utils/ShowIf';\nimport { getColorForPercentage } from '../RequestList/RequestDetail';\n\ninterface IPropsType {\n  requestItem: IRequestItem;\n  showNumber: boolean;\n}\n\nconst RequestStatusDislay: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  const { requestItem: item, showNumber } = props;\n  if(!item?.code){\n    return null;\n  }\n  return (\n    <div>\n      <ShowIf condition={showNumber && !!item.code?.length} alternative={'-'}>\n        <div>\n          <strong className='text-underline'>\n            #{item.code}\n          </strong>\n        </div>\n      </ShowIf>\n      <div\n        className={`progress progress-xs progress-striped ${item.status?.weigth > 10 && item.status?.weigth < 100\n          ? 'active'\n          : ''}`\n        }\n        style={{ margin: '3px 0' }}\n      >\n        <div\n          className='progress-bar progress-bar-danger'\n          style={{\n            width: `${(item.status?.weigth ?? 0)}%`,\n            backgroundColor: getColorForPercentage(item.status?.weigth ?? 0)\n          }}\n        />\n      </div>\n      <div>\n        {\n          item.status?.name.length\n            ? item.status?.name\n            : ' Desconocido'\n        }\n      </div>\n    </div>\n  );\n};\n\nexport default RequestStatusDislay;\n","import * as React from 'react';\nimport ShowIf from '../../Utils/ShowIf';\nimport { ChoicesStatusTransmittal } from '../../../../../../../src/distribution/models/transmitall.types';\nimport { ITransmittal } from '../../../../../../../src/distribution/interfaces/transmittal.interface';\n\ninterface IPropsType {\n  transmittal: ITransmittal;\n  showNumber: boolean;\n}\n\nconst transmittalWidth: any = {\n  [ChoicesStatusTransmittal.pending]: 10,\n  [ChoicesStatusTransmittal.inTransit]: 75,\n  [ChoicesStatusTransmittal.completed]: 100,\n  [ChoicesStatusTransmittal.damaged]: 0\n};\nconst transmittalColor: any = {\n  [ChoicesStatusTransmittal.pending]: '#00c0ef',\n  [ChoicesStatusTransmittal.inTransit]: '#337ab7',\n  [ChoicesStatusTransmittal.completed]: '#00a65a',\n  [ChoicesStatusTransmittal.damaged]: '#dd4b39'\n};\nconst transmittalTexto: any = {\n  [ChoicesStatusTransmittal.pending]: 'Pendiente',\n  // [ChoicesStatusTransmittal.inTransit]: <span>En transito <i className={'fa fa-fw text-primary fa-circle-o-notch fa-spin'} style={{fontSize: '10px'}}/></span>,\n  [ChoicesStatusTransmittal.inTransit]: <span>En transito</span>,\n  [ChoicesStatusTransmittal.completed]: <span>Completado</span>,\n  // [ChoicesStatusTransmittal.completed]: <span>Completado <i className={'fa fa-fw text-success fa-check-circle-o'} style={{fontSize: '10px'}}/></span>,\n  [ChoicesStatusTransmittal.damaged]: 'Completado'\n};\n\nconst TransmittalStatusDislay: React.FunctionComponent<IPropsType> = (props: IPropsType) => {\n  const { transmittal, showNumber } = props;\n  return (\n    <>\n      <ShowIf condition={!!transmittal?.number} alternative={''}>\n        <ShowIf condition={showNumber}>\n          <div>\n            <strong className='text-underline'>\n              #{transmittal?.number}\n            </strong>\n          </div>\n        </ShowIf>\n        <ShowIf\n          condition={\n            !!transmittal?.type?._id?.length\n          }\n        >\n          <strong className={'text-info'}> {transmittal?.type?.name?.toUpperCase()}</strong>\n        </ShowIf>\n        <div\n          className={`progress progress-xs progress-striped ${ChoicesStatusTransmittal.inTransit === transmittal?.status ? 'active' : ''}`}\n          style={{ margin: '3px 0' }}>\n          <div\n            className='progress-bar progress-bar-danger'\n            style={{\n              width: `${transmittalWidth[transmittal?.status]}%`,\n              backgroundColor: `${transmittalColor[transmittal?.status]}`\n            }}\n          />\n        </div>\n        <div>\n          {\n            transmittalTexto[transmittal?.status]\n              ?\n              transmittalTexto[transmittal?.status]\n              :\n              'Desconocido'\n          }\n        </div>\n      </ShowIf>\n    </>\n  );\n};\n\nexport default TransmittalStatusDislay;\n","export const requestSettings = {\n  brand: false,\n  brandReadOnly: false,\n  color: false,\n  colorReadOnly: false,\n  colorRequired: false,\n  denomination: false,\n  denominationReadOnly: false,\n  denominationRequired: false,\n  internalNumber: false,\n  internalNumberRequired: false,\n  internalNumberText: 'Número interno',\n  material: false,\n  materialRequired: false,\n  materialReadOnly: false,\n  reason: false,\n  entry: false,\n  sellerText: false,\n  ticket: false,\n  priority: false,\n  conectaID: false,\n  secondColorOption: false,\n  thirdColorOption: false,\n\n};\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\nimport { ISalesChannelState } from '../../actions/requestChannel.types';\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-12\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          {\n            submitFailed && !valid &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst ChannelForm = reduxForm({\n  form: 'channelForm'\n})(Form);\n\nconst mapStateToProps = (state: { requestChannel: ISalesChannelState }) => {\n  return {\n    requestChannel: state.requestChannel\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ requestChannel: ISalesChannelState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(ChannelForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction } from 'redux-form';\nimport { IMilestone } from '../../../../../../src/distribution/interfaces/milestone.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IMilestoneState, MilestoneReduxActions } from '../../actions/milestone.types';\nimport { getMilestonesThunkAction, updateMilestoneThunkAction } from '../../actions/milestone.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport ShowIf from '../Utils/ShowIf';\nimport { IForm } from '../../../../../../src/form/interfaces/form.interface';\nimport { IRequestItemStatus } from '../../../../../../src/request/interfaces/requestItemStatus.interface';\nimport Checkbox from '../Utils/CheckBox';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<MilestoneReduxActions | FormAction>;\n  milestone: IMilestoneState;\n\n  getMilestoneThunkAction(milestoneType: string, nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): MilestoneReduxActions;\n  // createMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  updateMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  // deleteMilestoneThunkAction(milestone: IMilestone): MilestoneReduxActions;\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n  milestoneType: string;\n}\n\ndeclare let window: IWindow;\n\nclass MilestoneListView extends TrackingBasePage<IPropsType, IStateType> {\n  public title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    milestoneType: '',\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Hitos';\n    this.changePage = this.changePage.bind(this);\n    /*this.createMilestone = this.createMilestone.bind(this);\n    this.processCreateMilestone = this.processCreateMilestone.bind(this);*/\n    /*this.updateMilestone = this.updateMilestone.bind(this);*/\n    this.processUpdateMilestone = this.processUpdateMilestone.bind(this);\n    // this.deleteMilestone = this.deleteMilestone.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.milestone;\n    const { orderBy, orderType } = this.props.milestone.options;\n    const { milestoneType } = this.state;\n    this.props.getMilestoneThunkAction(milestoneType, pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `operation-type-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.milestone;\n        const { orderBy, orderType } = this.props.milestone.options;\n        const { milestoneType } = this.state;\n        this.props.getMilestoneThunkAction(milestoneType, pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.milestone.pagination !== prevProps.milestone.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.milestone.source) {\n      this.props.milestone.source.cancel('Operation canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, milestones, pagination, forms, requestStatus, milestoneTypes } = this.props.milestone;\n    const { milestoneType } = this.state;\n    // const canEdit = hasPermission(window.user, 'adminRequest');\n    // const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.3' cAction='Hitos'>\n        <section className='content'>\n          <div className='row'>\n            <div className='col-md-3'>\n              <div className='list-group'>\n                <Link to='/requests/settings/reasons/' className='list-group-item'>\n                  Motivos\n                </Link>\n                <Link to='/requests/settings/channels/' className='list-group-item'>\n                  Canales\n                </Link>\n                <Link to='/requests/settings/status/' className='list-group-item'>\n                  Estados\n                </Link>\n                <Link to='/requests/settings/operations-type/' className='list-group-item'>\n                  Tipos de operación\n                </Link>\n                <Link to=\"/requests/settings/payment-methods/\" className=\"list-group-item\">\n                  Métodos de pago\n                </Link>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone-type/' className='list-group-item'>\n                    Tipos de hitos\n                  </Link>\n                </ShowIf>\n                <ShowIf condition={window.user.isAdmin}>\n                  <Link to='/transmittals/settings/milestone/' className='list-group-item active'>\n                    Hitos\n                  </Link>\n                </ShowIf>\n              </div>\n            </div>\n            <div className='col-md-9'>\n              <div className='box'>\n                <div className='box-header with-border'>\n                  <h3 className='box-title'>Hitos <small>{pagination.count}</small></h3>\n                  <div className='box-tools pull-right'>\n                   {/* {\n                      hasPermission(window.user, 'addVenue') ?\n                        <button className='btn btn-sm btn-success'\n                                onClick={this.createMilestone}\n                        ><i className='fa fa-plus' /> Agregar</button>\n                        : null\n                    }*/}\n                  </div>\n                </div>\n                <div className='box-body table-responsive no-padding'>\n                  <div className='row' style={{padding: '10px'}}>\n                    {/*<div className='col-md-offset-8 col-md-4'>*/}\n                    <div className='col-md-5'>\n                      <div className={`form-group`} style={{margin: '0'}}>\n                        <label className='control-label'>Seleccione hito a configurar</label>\n                        <div className=\"input-group\">\n                        <select\n                          className='form-control select-sm font-12'\n                          onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                            this.setState({\n                              milestoneType: e.target.value\n                            }, () => {\n                              const { orderBy, orderType } = this.props.milestone.options;\n                              const { milestoneType } = this.state;\n                              this.props.getMilestoneThunkAction(milestoneType, 1, orderBy, orderType);\n                            });\n                          }}\n                        >\n                          <option key={''} value={''}>Seleccione</option>\n                          {\n                            milestoneTypes.map((milestoneType) => (\n                              <option key={milestoneType._id} value={milestoneType._id}>{milestoneType.name}</option>\n                            ))\n                          }\n                        </select>\n                          <div className='input-group-addon input-group-primary pointer'>\n                            <i className='fa fa-cogs' />\n                          </div>\n                        </div>\n                      </div>\n                    </div>\n                  </div>\n                  <ShowIf condition={!loading && !!milestoneType?.length}>\n                    <table className='table table-andes table-striped'>\n                      <thead>\n                      <tr>\n                        <th className='middle' style={{ width: '20px' }}>Orden</th>\n                        <th className='middle'>Paso</th>\n                        <th className='middle'>Tipo</th>\n                        <th className='middle'>Formulario</th>\n                        <th className='middle'>Estado solicitudes</th>\n                        <th className='middle'>F. Arribo</th>\n                      </tr>\n                      </thead>\n                      <tbody>\n                      {\n                        milestones.map((item) => {\n                          return (\n                            <tr key={item._id}>\n                              <td className='middle-center text-muted'>{item.order}</td>\n                              <td className='middle'><strong className='text-primary'>{item.name}</strong></td>\n                              <td className='middle'>\n                                <select\n                                  className='form-control select-sm font-12' value={item.kind}\n                                  onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                    this.props.updateMilestoneThunkAction({\n                                      ...item,\n                                      kind: e.target.value\n                                    });\n                                  }}\n                                >\n                                  <option key={'form'} value={'form'}>Formulario</option>\n                                  <option key={'file'} value={'file'}>Archivo</option>\n                                </select>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <select\n                                    className='form-control select-sm font-12' value={item.form?._id ?? ''}\n                                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        form: e.target.value as unknown as IForm\n                                      });\n                                    }}\n                                  >\n                                    <option value='' disabled={true}>Seleccione</option>\n                                    {\n                                      forms.map((form) => (\n                                        <option key={form._id} value={form._id}>{`${form.name}`}</option>\n                                      ))\n                                    }\n                                  </select>\n                                </ShowIf>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <select\n                                    className='form-control select-sm font-12' value={item.requestItemStatus?._id ?? ''}\n                                    onChange={(e: React.ChangeEvent<HTMLSelectElement>) => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        requestItemStatus: e.target.value as unknown as IRequestItemStatus\n                                      });\n                                    }}\n                                  >\n                                    <option value={''}>Seleccione</option>\n                                    {\n                                      requestStatus.map((status) => (\n                                        <option key={status._id} value={status._id}>{`${status.name}`}</option>\n                                      ))\n                                    }\n                                  </select>\n                                </ShowIf>\n                              </td>\n                              <td className='middle'>\n                                <ShowIf condition={item.kind === 'form'}>\n                                  <Checkbox\n                                    active={item.updateItems?.arrivalDate}\n                                    action={() => {\n                                      this.props.updateMilestoneThunkAction({\n                                        ...item,\n                                        updateItems: {\n                                          arrivalDate: !item.updateItems.arrivalDate\n                                        }\n                                      });\n                                    }}\n                                    classes='icheck-in-checkbox'\n                                    style={{ marginTop: '-4px', marginRight: '5px' }}\n                                  />\n                                </ShowIf>\n                              </td>\n                            </tr>\n                          );\n                        })\n                      }\n                      </tbody>\n                    </table>\n                  </ShowIf>\n                </div>\n                {\n                  pagination.pages > 1 &&\n                  <div className='box-footer text-right'>\n                    <Paginator changePage={this.changePage} page={pagination.page} pages={pagination.pages} />\n                  </div>\n                }\n                {\n                  loading &&\n                  <div className='overlay'>\n                    <i className='fa fa-spinner fa-spin text-purple' />\n                  </div>\n                }\n              </div>\n            </div>\n          </div>\n          <ModalView />\n        </section>\n      </AppContainer>\n    );\n  }\n\n  /*private createMilestone(): void {\n    this.props.loadDataAction(\n      'Agregar tipo de operación',\n      <MilestoneForm\n        initialValues={{ update: false }}\n        onSubmit={this.processCreateMilestone}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneForm'))}>Grabar</button>\n      </React.Fragment>\n    );\n  }*/\n\n  /*private processCreateMilestone(milestone: any): void {\n    statusFooterButttonsModal(true);\n    this.props.createMilestoneThunkAction(milestone);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }*/\n\n  /*private updateMilestone(milestone: any): void {\n    this.props.loadDataAction(\n      'Editar hito',\n      <MilestoneForm\n        initialValues={{ update: false, ...milestone }}\n        onSubmit={this.processUpdateMilestone}\n      />,\n      <React.Fragment>\n        <button type='button' className='btn btn-sm btn-default' data-dismiss='modal'>Cancelar</button>\n        <button type='button' className='btn btn-sm btn-primary' onClick={() => this.props.dispatch(submit('milestoneForm'))}>Editar</button>\n      </React.Fragment>\n    );\n  }*/\n\n  private processUpdateMilestone(milestone: any): void {\n    statusFooterButttonsModal(true);\n    this.props.updateMilestoneThunkAction(milestone);\n    statusFooterButttonsModal(false);\n    showModal(false);\n  }\n\n  /*private deleteMilestone(milestone: IMilestone): void {\n    // ask if you are sure that you are going to delete the user?\n    swal({\n      title: '¿Estás seguro?',\n      text: `Vas a eliminar el tipo de operación ${milestone.name} `,\n      icon: 'warning',\n      dangerMode: true,\n      buttons: {\n        cancel: 'Cancelar' as any,\n        confirm: {\n          text: 'Sí'\n        }\n      }\n    }).then((willDelete) => {\n      if (willDelete) {\n        this.props.deleteMilestoneThunkAction(milestone);\n      }\n    });\n  }*/\n\n  private changePage(page: number): void {\n    // change the page\n    const { orderBy, orderType } = this.props.milestone.options;\n    const {milestoneType} = this.state;\n    this.props.getMilestoneThunkAction(milestoneType, page, orderBy, orderType);\n  }\n}\n\nconst mapStateToProps = (state: { milestone: IMilestoneState }) => {\n  return {\n    milestone: state.milestone\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch,\n    getMilestoneThunkAction: (milestoneType: string,nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean) => dispatch(getMilestonesThunkAction(milestoneType, nextPage, orderBy, orderType, hideLoading)),\n    // createMilestoneThunkAction: (milestone: IMilestone) => dispatch(createMilestoneThunkAction(milestone)),\n    updateMilestoneThunkAction: (milestone: IMilestone) => dispatch(updateMilestoneThunkAction(milestone)),\n    // deleteMilestoneThunkAction: (milestone: IMilestone) => dispatch(deleteMilestoneItemThunkAction(milestone)),\n    loadDataAction: (title: string, body: JSX.Element, footer: JSX.Element) => dispatch(loadDataAction(title, body, footer))\n  };\n};\n\nexport default connect<{ milestone: IMilestoneState }, { dispatch: any }, IPropsType>(mapStateToProps, mapDispatchToProps)(MilestoneListView);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { Field, InjectedFormProps, reduxForm } from 'redux-form';\nimport { IReasonsState } from '../../actions/reasons.types';\nimport InputField from '../Utils/forms/InputField';\nimport { inputStringRequired } from '../Utils/forms/validations';\nimport CheckBoxField from \"../Utils/forms/CheckBoxField\";\nimport Checkbox from \"../Utils/CheckBox\";\n\ninterface IPropsType extends InjectedFormProps {\n  update: boolean;\n}\n\ninterface IStateType {\n  error: Error | null;\n}\n\nclass Form extends React.Component<IPropsType, IStateType> {\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n  public render(): React.ReactElement<IPropsType> {\n    const { handleSubmit, valid , submitFailed} = this.props;\n    return (\n      <form onSubmit={handleSubmit}>\n        <div className=\"row\">\n          <div className=\"col-md-10\">\n            <Field\n              name=\"name\"\n              label=\"Nombre *\"\n              placeholder=\"Nombre\"\n              type=\"text\"\n              component={InputField}\n              validate={[inputStringRequired]}\n            />\n          </div>\n          <div className='col-md-12' style={{ backgroundColor: '#fff', paddingBottom: '13px' }}>\n            <Field\n              name='needMarkBorder'\n              label='Necesita marcar pasó por pórtico?'\n              placeholder='Activo'\n              type='checkbox'\n              component={CheckBoxField}\n              props={{\n                style: {\n                  marginBottom: 0,\n                }\n              }}\n              validate={[]}\n            />\n          </div>\n          {\n            submitFailed && valid === false &&\n            <div className=\"col-md-12\">\n              <div\n                className=\"alert alert-danger\"\n                style={{marginTop: '20px'}}\n              >\n                Todos los campos con * son obligatorios\n              </div>\n            </div>\n          }\n        </div>\n      </form>\n    );\n  }\n}\n\nconst MilestoneTypeForm = reduxForm({\n  form: 'milestoneTypeForm'\n})(Form);\n\nconst mapStateToProps = (state: { reasons: IReasonsState }) => {\n  return {\n    reasons: state.reasons\n  };\n};\n\nconst mapDispatchToProps = (dispatch: any) => {\n  return {\n    dispatch\n  };\n};\n\nexport default connect<{ reasons: IReasonsState }, { dispatch: any }, IPropsType | {}>(mapStateToProps, mapDispatchToProps)(MilestoneTypeForm);\n","import * as Raven from 'raven-js';\nimport * as React from 'react';\nimport { ErrorInfo } from 'react';\nimport { connect } from 'react-redux';\nimport { RouteComponentProps } from 'react-router';\nimport { Link } from 'react-router-dom';\nimport { Dispatch } from 'redux';\nimport { FormAction, submit } from 'redux-form';\nimport * as swal from 'sweetalert';\nimport { IMilestoneType } from '../../../../../../src/distribution/interfaces/milestoneType.interface';\nimport { loadDataAction, ModalReduxAction } from '../../actions/modal.actions';\nimport { IMilestoneTypeState, MilestoneTypeReduxActions } from '../../actions/milestoneType.types';\nimport {\n  createMilestoneTypeThunkAction,\n  deleteMilestoneTypeItemThunkAction,\n  getMilestoneTypesThunkAction,\n  updateMilestoneTypeThunkAction\n} from '../../actions/milestoneType.actions';\nimport AppContainer from '../../container/AppContainer';\nimport { IWindow } from '../../interfaces/window';\nimport { hasPermission, showModal, statusFooterButttonsModal } from '../../utils/common';\nimport ModalView from '../Modal/ModalView';\nimport Paginator from '../Utils/Paginator';\nimport TrackingBasePage from '../Utils/TrackingBasePage';\nimport MilestoneTypeForm from './MilestoneTypeForm';\nimport ShowIf from '../Utils/ShowIf';\nimport { io } from 'socket.io-client';\nimport { Socket } from 'socket.io-client/build/esm/socket';\n\ninterface IPropsType extends RouteComponentProps<{ ticket: string }> {\n  dispatch: Dispatch<MilestoneTypeReduxActions | FormAction>;\n  milestoneType: IMilestoneTypeState;\n\n  getMilestoneTypeThunkAction(nextPage: number, orderBy: string, orderType: string, hideLoading?: boolean): MilestoneTypeReduxActions;\n\n  createMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  updateMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  deleteMilestoneTypeThunkAction(milestoneType: IMilestoneType): MilestoneTypeReduxActions;\n\n  loadDataAction(title: string, body: JSX.Element, footer: JSX.Element): ModalReduxAction;\n}\n\ninterface IStateType {\n  error: Error | null;\n  exporing: boolean;\n}\n\ndeclare let window: IWindow;\n\nclass MilestoneTypeListView extends TrackingBasePage<IPropsType, IStateType> {\n  title: string;\n\n  private socket: Socket;\n  readonly state = {\n    error: null,\n    exporing: false\n  };\n\n  constructor(props: IPropsType) {\n    super(props);\n    this.title = 'Listado Tipo de Hitos';\n    this.changePage = this.changePage.bind(this);\n    this.createMilestoneType = this.createMilestoneType.bind(this);\n    this.processCreateMilestoneType = this.processCreateMilestoneType.bind(this);\n    this.updateReaon = this.updateReaon.bind(this);\n    this.processUpdateMilestoneType = this.processUpdateMilestoneType.bind(this);\n    this.deleteMilestoneType = this.deleteMilestoneType.bind(this);\n  }\n\n  public componentWillMount(): void {\n    const { pagination } = this.props.milestoneType;\n    const { orderBy, orderType } = this.props.milestoneType.options;\n    this.props.getMilestoneTypeThunkAction(pagination.page, orderBy, orderType);\n\n    // socket\n    this.socket = io(`${location.protocol}//${location.host}`, {\n      secure: location.protocol === 'https:',\n      transports: ['websocket'],\n      reconnection: true,\n      query: { token: (window.user as any).token }\n    });\n    this.socket.on('connect', () => {\n      this.socket.emit('join', { room: `milestone-type-list-${window.user.team._id}` });\n    });\n    this.socket.on('REFRESH', (data: any): void => {\n      if (data.update) {\n        const { pagination } = this.props.milestoneType;\n        const { orderBy, orderType } = this.props.milestoneType.options;\n        this.props.getMilestoneTypeThunkAction(pagination.page, orderBy, orderType, true);\n      }\n    });\n  }\n\n  public componentDidUpdate(prevProps: Readonly<IPropsType>, prevState: Readonly<IStateType>, snapshot?: any): void {\n    if (this.props.milestoneType.pagination !== prevProps.milestoneType.pagination) {\n      window.scrollTo(0, 0);\n    }\n  }\n\n  public componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    this.setState({ error });\n    Raven.captureException(error, {\n      extra: errorInfo\n    });\n  }\n\n  public componentWillUnmount(): void {\n    // cancel request if component is inmounted\n    if (this.props.milestoneType.source) {\n      this.props.milestoneType.source.cancel('Milestone canceled by the user.');\n    }\n    this.socket.disconnect();\n  }\n\n  public render(): React.ReactElement<IPropsType> {\n    const { loading, milestoneTypes, pagination } = this.props.milestoneType;\n    const canEdit = hasPermission(window.user, 'adminRequest');\n    const canDelete = hasPermission(window.user, 'adminRequest');\n    return (\n      <AppContainer title='' cMenu='3' cSubMenu='3.3' cAction='Tipos de Hitos'>\n   